// Sailor's-Valentine Workshop Box — Hyperreal Pen Stippling & Watercolor Wash
// p5.js 2.x + p5.brush (WEBGL 1200x1200)

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);

  randomSeed(8472);
  noiseSeed(8472);

  // Custom pen-stippling brushes for hyperreal dot-modeling at high density
  brush.add("stippleDense", {
    type: "custom",
    weight: 1.5,
    scatter: 0.85,
    opacity: 225,
    spacing: 0.55,
    pressure: [0.9, 1.2, 0.9],
    tip: (_m) => {
      _m.circle(0, 0, 0.75);
      _m.circle(0.9, -0.6, 0.55);
      _m.circle(-0.7, 0.8, 0.5);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.3
  });

  brush.add("stippleMid", {
    type: "custom",
    weight: 1.35,
    scatter: 1.65,
    opacity: 185,
    spacing: 0.8,
    pressure: [0.7, 1.1, 0.7],
    tip: (_m) => {
      _m.circle(0, 0, 0.65);
      _m.circle(1.2, 0.7, 0.45);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.4
  });

  brush.add("stippleFine", {
    type: "custom",
    weight: 1.1,
    scatter: 2.6,
    opacity: 145,
    spacing: 1.05,
    pressure: [0.5, 1.0, 0.5],
    tip: (_m) => {
      _m.circle(0, 0, 0.5);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.5
  });

  brush.add("inkGlint", {
    type: "default",
    weight: 0.9,
    scatter: 0.05,
    sharpness: 0.9,
    grain: 0.1,
    opacity: 240,
    spacing: 0.25,
    pressure: [0.8, 1.2, 0.8],
    rotate: "natural"
  });

  background("#e8dcc6");
}

// Safe line wrapper to avoid zero-length tangent issues
function safeLine(x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) > 0.45) {
    brush.line(x1, y1, x2, y2);
  }
}

// Helper for closed polygon shapes via beginShape/vertex
function drawPoly(pts, curv = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Regular octagon vertices
function getOctagonPts(cx, cy, r, rotDeg = 0, aspectX = 1, aspectY = 1, shearX = 0) {
  let pts = [];
  for (let i = 0; i < 8; i++) {
    let a = 22.5 + i * 45;
    let lx = cos(a) * r * aspectX;
    let ly = sin(a) * r * aspectY;
    lx += ly * shearX;
    let rx = lx * cos(rotDeg) - ly * sin(rotDeg);
    let ry = lx * sin(rotDeg) + ly * cos(rotDeg);
    pts.push([cx + rx, cy + ry]);
  }
  return pts;
}

// Transform local lid coordinates to canvas coordinates
function lidPt(lx, ly, hingeX, hingeY, rotDeg) {
  // Foreshortened open lid tilted away at ~56 degrees
  let sx = lx * 0.97 + ly * 0.16;
  let sy = ly * 0.56;
  let rx = sx * cos(rotDeg) - sy * sin(rotDeg);
  let ry = sx * sin(rotDeg) + sy * cos(rotDeg);
  return [hingeX + rx, hingeY + ry];
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();
  brush.set("rotring", "#241a13", 0.35);

  // Master layout coordinates
  const BX = 650;
  const BY = 728;
  const BROT = -12; // Natural tabletop orientation
  const R_OUT = 416;
  const R_MID = 398;
  const R_IN = 374;

  // Hinge edge of main octagon is top edge (between vertex 5 at 247.5° and vertex 6 at 292.5°)
  // Distance from center to flat octagon face is R * cos(22.5)
  const faceDist = R_OUT * cos(22.5);
  const hingeMidX = BX + cos(-90 + BROT) * faceDist;
  const hingeMidY = BY + sin(-90 + BROT) * faceDist;
  // Center of the open lid in its local coordinate space (extending upward from hinge, ly < 0)
  const lidLocalCy = -faceDist - 8;

  // =========================================================================
  // 1. WORKBENCH GROUND, PAPER TEXTURE & CAST SHADOWS
  // =========================================================================
  renderWorkbenchGround(BX, BY, BROT, R_OUT, hingeMidX, hingeMidY, lidLocalCy);

  // =========================================================================
  // 2. PROPPED-OPEN OCTAGONAL WOOD & GLASS LID (WITH OILY FINGERPRINTS)
  // =========================================================================
  renderOpenLid(BX, BY, BROT, R_OUT, R_IN, hingeMidX, hingeMidY, lidLocalCy);

  // =========================================================================
  // 3. MAIN OCTAGONAL WOODEN BOX CASE & COMPARTMENT DIVIDERS
  // =========================================================================
  renderMainBoxCase(BX, BY, BROT, R_OUT, R_MID, R_IN);

  // =========================================================================
  // 4. GENERATE HARDWARE ROSETTE GEOMETRY & LOOSE BENCH ITEMS
  // =========================================================================
  const hardware = buildHardwareLayout(BX, BY, BROT);

  // =========================================================================
  // 5. BATCHED WATERCOLOR WASHES (SIENNA, BRASS-YELLOW, VERDIGRIS, EARTH)
  // =========================================================================
  renderHardwareWatercolors(hardware, BX, BY, BROT);

  // =========================================================================
  // 6. HYPERREAL PEN STIPPLING & MECHANICAL INK RENDERING
  // =========================================================================
  renderHardwareInkAndStipple(hardware, BX, BY, BROT);

  // =========================================================================
  // 7. HINGES, BRASS STAY-ARM & LATCH HARDWARE (OVERLAPPING BOX & LID)
  // =========================================================================
  renderHingesAndStay(BX, BY, BROT, R_OUT, R_IN, hingeMidX, hingeMidY, lidLocalCy);

  // =========================================================================
  // 8. LOOSE WORKBENCH CLUTTER, TWEEZERS & SPECULAR HIGHLIGHTS
  // =========================================================================
  renderWorkbenchClutter(BX, BY, BROT);

  noLoop();
}

// ===========================================================================
// PHASE 1: WORKBENCH GROUND & SHADOWS
// ===========================================================================
function renderWorkbenchGround(BX, BY, BROT, R_OUT, hingeMidX, hingeMidY, lidLocalCy) {
  // Warm antique rag paper / oiled workbench base washes
  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.55, 0.35);

  // Batch 1: Pale warm ochre & raw sienna washes across the bench
  brush.fill("#dcc7a6", 75);
  brush.rect(40, 40, 1120, 1120, "corner");

  brush.fill("#cfa97e", 52);
  drawPoly([[60, 80], [640, 50], [580, 520], [70, 620]]);
  drawPoly([[520, 680], [1150, 620], [1140, 1150], [450, 1140]]);

  // Subtle sienna & verdigris workshop stains on the tabletop
  brush.fill("#b56c3b", 35);
  brush.circle(210, 880, 155, 0.35);
  brush.circle(1030, 310, 130, 0.4);

  brush.fill("#568270", 28);
  brush.circle(185, 640, 95, 0.35);
  brush.circle(1055, 890, 85, 0.3);

  // Wood plank seams and grain on the workbench surface
  brush.set("2B", "#8c7358", 0.32);
  for (let p = 0; p < 5; p++) {
    let py = 165 + p * 235;
    safeLine(25, py - 35, 1175, py + 45);
    brush.set("HB", "#a38b70", 0.22);
    safeLine(25, py - 32, 1175, py + 48);
  }

  // Fine woodgrain flow lines across the tabletop
  brush.field("waves");
  brush.wiggle(1.5);
  brush.set("2H", "#b59d82", 0.24);
  for (let i = 0; i < 65; i++) {
    let gx = random(30, 1170);
    let gy = random(30, 1170);
    if (dist(gx, gy, BX, BY) > 370) {
      brush.flowLine(gx, gy, random(80, 210), 4);
    }
  }
  brush.noField();

  // Faint graphite workshop layout grid / compass calibration arcs in bottom-left & top-right
  brush.set("2H", "#7d6b57", 0.25);
  safeLine(55, 965, 360, 905);
  safeLine(145, 760, 215, 1130);
  brush.arc(180, 940, 75, 0, 270);
  brush.arc(180, 940, 115, -40, 190);
  // Ruler tick marks on bench
  for (let t = 0; t < 18; t++) {
    let tx = 75 + t * 15;
    let ty = 961 - t * 3;
    safeLine(tx, ty - 4, tx + 1.5, ty + 5);
  }

  // Oil ring stain from an old hardware tin in upper-right
  brush.noFill();
  brush.set("cpencil", "#8a532b", 0.45);
  brush.circle(1015, 225, 68, 0.15);
  brush.set("stippleFine", "#6e4120", 0.35);
  brush.circle(1018, 227, 70, 0.2);

  // Cast shadow of the propped-open lid (cast toward right / lower-right)
  let lidShadowPts1 = [];
  let lidShadowPts2 = [];
  for (let i = 0; i < 8; i++) {
    let a = 22.5 + i * 45;
    let lx = cos(a) * R_OUT;
    let ly = lidLocalCy + sin(a) * R_OUT;
    let p = lidPt(lx, ly, hingeMidX, hingeMidY, BROT);
    // Offset shadow to the right and down based on distance from hinge
    let distFromHinge = abs(ly);
    let shOffX = 48 + distFromHinge * 0.14;
    let shOffY = 34 + distFromHinge * 0.08;
    lidShadowPts1.push([p[0] + shOffX, p[1] + shOffY]);
    lidShadowPts2.push([p[0] + shOffX * 0.6, p[1] + shOffY * 0.6]);
  }

  // Cast shadow of the main octagonal box (cast toward lower-right)
  let boxShadowOuter = getOctagonPts(BX + 34, BY + 38, R_OUT + 10, BROT);
  let boxShadowInner = getOctagonPts(BX + 18, BY + 22, R_OUT + 3, BROT);

  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.3);
  brush.fill("#4a3a2c", 85);
  drawPoly(lidShadowPts1);
  drawPoly(boxShadowOuter);

  brush.fill("#2b2017", 125);
  drawPoly(lidShadowPts2);
  drawPoly(boxShadowInner);

  // Stippled pen shadow feathering around box perimeter
  brush.noFill();
  brush.set("stippleMid", "#2b1f16", 0.55);
  for (let i = 0; i < 4; i++) {
    let p1 = boxShadowInner[i];
    let p2 = boxShadowInner[(i + 1) % 8];
    safeLine(p1[0], p1[1], p2[0], p2[1]);
  }
}

// ===========================================================================
// PHASE 2: PROPPED-OPEN LID & GLASS PANE WITH OILY FINGERPRINTS
// ===========================================================================
function renderOpenLid(BX, BY, BROT, R_OUT, R_IN, hingeMidX, hingeMidY, lidLocalCy) {
  let outerPts = [];
  let bevelPts = [];
  let glassPts = [];
  let innerLipPts = [];

  const R_GLASS = R_IN - 8;
  for (let i = 0; i < 8; i++) {
    let a = 22.5 + i * 45;
    let ca = cos(a);
    let sa = sin(a);
    outerPts.push(lidPt(ca * R_OUT, lidLocalCy + sa * R_OUT, hingeMidX, hingeMidY, BROT));
    bevelPts.push(lidPt(ca * (R_OUT - 12), lidLocalCy + sa * (R_OUT - 12), hingeMidX, hingeMidY, BROT));
    glassPts.push(lidPt(ca * R_GLASS, lidLocalCy + sa * R_GLASS, hingeMidX, hingeMidY, BROT));
    innerLipPts.push(lidPt(ca * (R_GLASS - 8), lidLocalCy + sa * (R_GLASS - 8), hingeMidX, hingeMidY, BROT));
  }

  // 3D thickness rim along the bottom/right edges of the raised lid
  let rimPts = outerPts.map(p => [p[0] + 9, p[1] + 12]);
  brush.noStroke();
  brush. wash("#3b2415", 210);
  drawPoly(rimPts);

  // Wooden lid frame base wash (warm mahogany / burnt sienna)
  brush.noWash();
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7d4020", 185);
  drawPoly(outerPts);

  // Mitred wooden frame sectors with alternating warm grain tones
  for (let i = 0; i < 8; i++) {
    let n = (i + 1) % 8;
    let quad = [outerPts[i], outerPts[n], glassPts[n], glassPts[i]];
    let col = (i % 2 === 0) ? "#965129" : "#6b3418";
    brush.fill(col, 135);
    drawPoly(quad);
  }

  // Interior of the glass pane — translucent pale warm verdigris/ivory wash
  // First wash out the dark wood inside the glass opening so it looks transparent over the bench
  brush.noFill();
  brush.wash("#e3d8c3", 230);
  drawPoly(glassPts);
  brush.noWash();

  // Subtle green-tinted antique crown glass wash
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.35, 0.25);
  brush.fill("#cad6ce", 68);
  drawPoly(glassPts);

  brush.fill("#d8cdb8", 55);
  drawPoly(innerLipPts);

  // Ghosted bench plank line & faint hardware shadow seen through the glass pane
  let gLeft = lidPt(-R_GLASS * 0.85, lidLocalCy - 40, hingeMidX, hingeMidY, BROT);
  let gRight = lidPt(R_GLASS * 0.85, lidLocalCy + 20, hingeMidX, hingeMidY, BROT);
  brush.set("2H", "#9e9482", 0.25);
  safeLine(gLeft[0], gLeft[1], gRight[0], gRight[1]);

  // Diagonal glass reflection bands
  brush.noStroke();
  let ref1 = [
    lidPt(-220, lidLocalCy - 330, hingeMidX, hingeMidY, BROT),
    lidPt(-120, lidLocalCy - 350, hingeMidX, hingeMidY, BROT),
    lidPt(240, lidLocalCy + 260, hingeMidX, hingeMidY, BROT),
    lidPt(140, lidLocalCy + 290, hingeMidX, hingeMidY, BROT)
  ];
  let ref2 = [
    lidPt(-60, lidLocalCy - 350, hingeMidX, hingeMidY, BROT),
    lidPt(-20, lidLocalCy - 350, hingeMidX, hingeMidY, BROT),
    lidPt(300, lidLocalCy + 210, hingeMidX, hingeMidY, BROT),
    lidPt(265, lidLocalCy + 240, hingeMidX, hingeMidY, BROT)
  ];
  brush.wash("#f7f2e6", 85);
  drawPoly(ref1);
  brush.wash("#f7f2e6", 60);
  drawPoly(ref2);
  brush.noWash();

  // -------------------------------------------------------------------------
  // OILY FINGERPRINTS & GREASY WORKSHOP SMUDGES ON THE GLASS PANE
  // -------------------------------------------------------------------------
  const smudges = [
    // Right-top cluster where thumb & index gripped the lid near the top bezel
    { lx: 125, ly: lidLocalCy - 235, rx: 32, ry: 46, ang: 28, type: "whorl" },
    { lx: 185, ly: lidLocalCy - 185, rx: 27, ry: 40, ang: 42, type: "loop" },
    { lx: 220, ly: lidLocalCy - 115, rx: 24, ry: 36, ang: 52, type: "whorl" },
    // Left-upper thumb smudge
    { lx: -155, ly: lidLocalCy - 210, rx: 34, ry: 48, ang: -32, type: "whorl" },
    { lx: -205, ly: lidLocalCy - 140, rx: 26, ry: 38, ang: -45, type: "loop" },
    // Central-lower palm/knuckle grease rub
    { lx: 45, ly: lidLocalCy - 95, rx: 42, ry: 28, ang: 15, type: "smear" }
  ];

  // 1) Thin iridescent oil washes (sienna, brass-ochre, and faint verdigris sheen)
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.6, 0.45);

  for (let s of smudges) {
    let cp = lidPt(s.lx, s.ly, hingeMidX, hingeMidY, BROT);
    // Warm linseed/machine oil halo
    brush.fill("#c49342", 34);
    brush.circle(cp[0], cp[1], s.rx * 0.85, 0.35);
    // Sienna smudge core
    brush.fill("#9e582a", 26);
    brush.circle(cp[0] + 4, cp[1] - 3, s.rx * 0.6, 0.4);
    // Subtle verdigris-iridescent oil edge
    brush.fill("#588271", 22);
    brush.circle(cp[0] - 5, cp[1] + 4, s.rx * 0.72, 0.35);
  }
  brush.noFill();

  // 2) Meticulous stippled dermal ridges & oily whorl lines on each fingerprint
  for (let s of smudges) {
    let cp = lidPt(s.lx, s.ly, hingeMidX, hingeMidY, BROT);
    push();
    translate(cp[0], cp[1]);
    rotate(s.ang + BROT);
    scale(1.0, 0.64); // Foreshortened on the tilted glass plane

    // Stippled oil droplet halo
    brush.set("stippleFine", "#6e4b2a", 0.32);
    brush.circle(0, 0, s.rx * 0.9, 0.25);
    brush.circle(2, -2, s.rx * 0.65, 0.2);

    // Concentric fingerprint dermal ridges (whorls & loops)
    let numRidges = (s.type === "smear") ? 7 : 12;
    for (let r = 3; r <= numRidges * 2.4; r += 2.35) {
      let col = (r % 4 < 2) ? "#593e25" : "#785a3c";
      brush.set("rotring", col, 0.21);
      // Draw broken elliptical arcs to emulate real fingerprint ridge pores
      let segs = 5;
      for (let k = 0; k < segs; k++) {
        let a1 = k * (360 / segs) + random(-12, 12);
        let a2 = a1 + (360 / segs) * random(0.48, 0.78);
        if (s.type === "loop" && a1 > 140 && a1 < 240) continue;
        brush.arc(0, (s.type === "loop" ? r * 0.12 : 0), r, a1, a2);
      }
    }

    // Drag smear streaks where oily fingers slid across the glass
    if (s.type !== "smear") {
      brush.set("stippleFine", "#856340", 0.26);
      for (let d = -3; d <= 3; d++) {
        safeLine(d * 3.5, -s.rx * 0.4, d * 4.5 + 8, s.rx * 0.95);
      }
    } else {
      brush.set("stippleFine", "#735436", 0.3);
      for (let d = -5; d <= 5; d++) {
        safeLine(-s.rx * 0.8, d * 2.5, s.rx * 0.9, d * 3.2 + 6);
      }
    }

    // Tiny bright specular oil-film ridge glints
    brush.set("inkGlint", "#f5eedc", 0.24);
    brush.arc(0, 0, s.rx * 0.45, -70, 25);
    brush.arc(0, 0, s.rx * 0.7, 110, 195);
    pop();
  }

  // Pen & ink rendering of the octagonal lid frame, mitre joints, and inner brass glazing bead
  brush.set("rotring", "#241810", 0.48);
  drawPoly(outerPts);
  brush.set("rotring", "#241810", 0.36);
  drawPoly(bevelPts);
  drawPoly(glassPts);
  brush.set("rotring", "#543d28", 0.28);
  drawPoly(innerLipPts);

  // Mitre joint lines & brass corner splines on the lid
  for (let i = 0; i < 8; i++) {
    brush.set("rotring", "#241810", 0.4);
    safeLine(outerPts[i][0], outerPts[i][1], glassPts[i][0], glassPts[i][1]);

    // Wood grain lines along each of the 8 frame bars
    let n = (i + 1) % 8;
    brush.set("rotring", "#3d2516", 0.24);
    for (let f = 0.2; f <= 0.82; f += 0.2) {
      let x1 = lerp(outerPts[i][0], glassPts[i][0], f);
      let y1 = lerp(outerPts[i][1], glassPts[i][1], f);
      let x2 = lerp(outerPts[n][0], glassPts[n][0], f);
      let y2 = lerp(outerPts[n][1], glassPts[n][1], f);
      safeLine(x1, y1, x2, y2);
    }

    // Stippled shadow along inner glass rebate
    brush.set("stippleDense", "#21160e", 0.38);
    safeLine(glassPts[i][0], glassPts[i][1], glassPts[n][0], glassPts[n][1]);
  }

  // Brass mortise latch catch at the top-most edge of the open lid (edge 5..6 is top in local space)
  let catchL = lidPt(-36, lidLocalCy - faceDistOf(R_OUT) + 12, hingeMidX, hingeMidY, BROT);
  let catchR = lidPt(36, lidLocalCy - faceDistOf(R_OUT) + 12, hingeMidX, hingeMidY, BROT);
  let catchBL = lidPt(-36, lidLocalCy - faceDistOf(R_OUT) + 28, hingeMidX, hingeMidY, BROT);
  let catchBR = lidPt(36, lidLocalCy - faceDistOf(R_OUT) + 28, hingeMidX, hingeMidY, BROT);
  brush.noStroke();
  brush.wash("#c89b3c", 210);
  drawPoly([catchL, catchR, catchBR, catchBL]);
  brush.noWash();
  brush.set("rotring", "#241810", 0.36);
  drawPoly([catchL, catchR, catchBR, catchBL]);
}

function faceDistOf(r) {
  return r * cos(22.5);
}

// ===========================================================================
// PHASE 3: MAIN OCTAGONAL WOODEN BOX CASE & COMPARTMENT DIVIDERS
// ===========================================================================
function renderMainBoxCase(BX, BY, BROT, R_OUT, R_MID, R_IN) {
  let outerPts = getOctagonPts(BX, BY, R_OUT, BROT);
  let midPts = getOctagonPts(BX, BY, R_MID, BROT);
  let innerPts = getOctagonPts(BX, BY, R_IN, BROT);

  // 3D outer side wall visible on the bottom and right facets
  let baseDropPts = outerPts.map(p => [p[0] + 12, p[1] + 15]);
  brush.noStroke();
  brush.wash("#2e1c10", 235);
  drawPoly(baseDropPts);

  // Top wooden rim base wash
  brush.wash("#6e3619", 230);
  drawPoly(outerPts);

  // Dark recessed velvet/ebonized wood bed inside the box (so hardware pops with deep contrast)
  brush.wash("#231a14", 245);
  drawPoly(innerPts);
  brush.noWash();

  // Watercolor shading on the 8 mitred walnut walls of the box
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.5, 0.4);
  for (let i = 0; i < 8; i++) {
    let n = (i + 1) % 8;
    let wallQuad = [outerPts[i], outerPts[n], innerPts[n], innerPts[i]];
    // Directional lighting: upper-left walls warmer/lighter, lower-right deeper umber
    let wallColors = ["#80411e", "#633015", "#522610", "#693418", "#8f4b25", "#a85c30", "#9c532a", "#874520"];
    brush.fill(wallColors[i], 155);
    drawPoly(wallQuad);
  }
  brush.noFill();

  // Wood grain lines, mitre joints, and inlaid brass corner splines on the box rim
  for (let i = 0; i < 8; i++) {
    let n = (i + 1) % 8;
    // Wood grain lines along each octagon wall
    brush.set("rotring", "#331d0f", 0.26);
    for (let f = 0.15; f <= 0.88; f += 0.18) {
      let x1 = lerp(outerPts[i][0], innerPts[i][0], f);
      let y1 = lerp(outerPts[i][1], innerPts[i][1], f);
      let x2 = lerp(outerPts[n][0], innerPts[n][0], f);
      let y2 = lerp(outerPts[n][1], innerPts[n][1], f);
      safeLine(x1, y1, x2, y2);
    }

    // Stippled inner wall shadow
    brush.set("stippleDense", "#17100b", 0.55);
    safeLine(innerPts[i][0], innerPts[i][1], innerPts[n][0], innerPts[n][1]);

    // Mitre joint line at vertex i
    brush.set("rotring", "#1c110a", 0.48);
    safeLine(outerPts[i][0], outerPts[i][1], innerPts[i][0], innerPts[i][1]);

    // Brass corner spline inlays across the mitre joint
    for (let s of [0.32, 0.68]) {
      let mx = lerp(outerPts[i][0], innerPts[i][0], s);
      let my = lerp(outerPts[i][1], innerPts[i][1], s);
      let ang = 22.5 + i * 45 + BROT + 90;
      let sx1 = mx + cos(ang) * 9;
      let sy1 = my + sin(ang) * 9;
      let sx2 = mx - cos(ang) * 9;
      let sy2 = my - sin(ang) * 9;
      brush.set("rotring", "#d9b150", 0.65);
      safeLine(sx1, sy1, sx2, sy2);
      brush.set("rotring", "#241810", 0.25);
      safeLine(sx1, sy1, sx2, sy2);
    }
  }

  // Crisp outer, bevel, and inner octagon outlines
  brush.set("rotring", "#1c120b", 0.55);
  drawPoly(outerPts);
  brush.set("rotring", "#2e1d12", 0.34);
  drawPoly(midPts);
  brush.set("rotring", "#140d08", 0.5);
  drawPoly(innerPts);

  // Brass lock escutcheon plate on the front-bottom wall (between vertex 1 at 67.5° and vertex 2 at 112.5°)
  push();
  translate(BX, BY);
  rotate(BROT);
  let lockY = R_IN + (R_OUT - R_IN) * 0.5;
  brush.noStroke();
  brush.wash("#c99c3e", 230);
  brush.rect(0, lockY, 68, 16, "center");
  brush.noWash();
  brush.set("rotring", "#21160e", 0.35);
  brush.rect(0, lockY, 68, 16, "center");
  // Keyhole slot & 2 tiny brass screws
  brush.set("rotring", "#170f09", 0.5);
  brush.circle(0, lockY - 2, 3);
  safeLine(0, lockY - 2, 0, lockY + 5);
  brush.circle(-26, lockY, 2.5);
  brush.circle(26, lockY, 2.5);
  pop();

  // -------------------------------------------------------------------------
  // SAILOR'S-VALENTINE CONCENTRIC & RADIAL CEDAR DIVIDERS
  // -------------------------------------------------------------------------
  const ringRadii = [86, 136, 192, 256, 314];
  push();
  translate(BX, BY);
  rotate(BROT);

  // Radial sector dividers in the outer screw ring (r = 314..374) & center compass
  for (let i = 0; i < 8; i++) {
    let a = 22.5 + i * 45;
    let rOuter = R_IN;
    let x1 = cos(a) * 86;
    let y1 = sin(a) * 86;
    let x2 = cos(a) * rOuter;
    let y2 = sin(a) * rOuter;
    brush.set("rotring", "#7a4624", 0.75);
    safeLine(x1, y1, x2, y2);
    brush.set("rotring", "#b87a44", 0.32);
    safeLine(x1 + 1, y1 + 1, x2 + 1, y2 + 1);
  }

  // Concentric cedar & brass divider rings
  for (let rr of ringRadii) {
    // Draw octagonal divider for outer rings (314, 256) and circular for inner rings
    if (rr >= 256) {
      let divPts = getOctagonPts(0, 0, rr, 0);
      let divPtsIn = getOctagonPts(0, 0, rr - 3.5, 0);
      brush.set("rotring", "#8c5129", 0.65);
      drawPoly(divPts);
      brush.set("rotring", "#c9974c", 0.32);
      drawPoly(divPtsIn);
      brush.set("rotring", "#1a110b", 0.35);
      drawPoly(getOctagonPts(0, 0, rr + 2, 0));
    } else {
      brush.set("rotring", "#8c5129", 0.65);
      brush.circle(0, 0, rr, 0.03);
      brush.set("rotring", "#c9974c", 0.32);
      brush.circle(0, 0, rr - 2.5, 0.03);
      brush.set("rotring", "#1a110b", 0.35);
      brush.circle(0, 0, rr + 2, 0.03);
    }
  }
  pop();
}

// ===========================================================================
// PHASE 4: BUILD HARDWARE ROSETTE LAYOUT DATA
// ===========================================================================
function buildHardwareLayout(BX, BY, BROT) {
  let layout = {
    fuses: [],
    compassPins: [],
    rivets: [],
    washers: [],
    springs: [],
    hexNuts: [],
    screws: [],
    microFillers: []
  };

  // Helper to convert polar (r, angle in box space) to world coordinates
  function toWorld(r, angDeg) {
    let wa = angDeg + BROT;
    return {
      x: BX + cos(wa) * r,
      y: BY + sin(wa) * r,
      ang: wa
    };
  }

  // 1. CENTRAL COMPASS-ROSE OF RED-HANDLED FUSES (r = 22..82, 8 points)
  for (let i = 0; i < 8; i++) {
    let a = i * 45;
    let isCardinal = (i % 2 === 0);
    let p = toWorld(51, a);
    layout.fuses.push({
      x: p.x,
      y: p.y,
      ang: p.ang,
      len: isCardinal ? 54 : 46,
      w: isCardinal ? 14.5 : 12.5,
      isCardinal: isCardinal
    });

    // Interstitial copper compass needles between the 8 fuses
    let pa = a + 22.5;
    let pp = toWorld(54, pa);
    layout.compassPins.push({
      x: pp.x,
      y: pp.y,
      ang: pp.ang,
      len: 42
    });
  }

  // 2. RING 1: COPPER RIVETS (r = 90..132, 28 solid copper rivets arranged radially)
  const numRivets = 28;
  for (let i = 0; i < numRivets; i++) {
    let a = i * (360 / numRivets);
    let inward = (i % 2 === 0);
    let p = toWorld(111, a);
    layout.rivets.push({
      x: p.x,
      y: p.y,
      ang: inward ? p.ang + 180 : p.ang,
      headR: 7.2,
      shankLen: 21,
      shankW: 6.5,
      verdigris: (i % 3 === 0)
    });
  }

  // 3. RING 2: GALVANISED WASHERS (r = 140..188, 24 overlapping imbricated washers)
  const numWashers = 24;
  for (let i = 0; i < numWashers; i++) {
    let a = i * (360 / numWashers);
    let p = toWorld(164, a);
    layout.washers.push({
      x: p.x,
      y: p.y,
      ang: p.ang,
      outerR: 20.5,
      innerR: 8.5,
      index: i
    });
  }

  // 4. RING 3: COILED SPRINGS (r = 196..252, 32 radial helical compression/extension springs)
  const numSprings = 32;
  for (let i = 0; i < numSprings; i++) {
    let a = i * (360 / numSprings) + 5.625;
    let p = toWorld(224, a);
    layout.springs.push({
      x: p.x,
      y: p.y,
      ang: p.ang,
      len: 46,
      w: 11.2,
      coils: 9,
      isBrass: (i % 2 === 0)
    });
  }

  // 5. RING 4: HEX NUTS (r = 260..310, 32 faceted M10 hex nuts)
  const numNuts = 32;
  for (let i = 0; i < numNuts; i++) {
    let a = i * (360 / numNuts);
    // Follow subtle octagonal contour interpolation between r=258 and r=312
    let octFactor = 1 / cos(((a + 22.5) % 45) - 22.5);
    let rNut = lerp(284, 276 * octFactor, 0.55);
    let p = toWorld(rNut, a);
    layout.hexNuts.push({
      x: p.x,
      y: p.y,
      ang: p.ang + 30,
      r: 14.2,
      boreR: 6.8,
      isBrass: (i % 3 !== 0),
      hasVerdigris: (i % 4 === 1)
    });
  }

  // 6. RING 5: BRASS SCREWS IN THE 8 OUTER OCTAGONAL SECTORS (r = 318..370)
  // Each of the 8 trapezoidal sectors gets 7 tightly packed alternating brass wood screws
  for (let sec = 0; sec < 8; sec++) {
    let secMidAng = sec * 45;
    let tanAng = secMidAng + 90 + BROT;
    let radAng = secMidAng + BROT;

    // Center of sector in world space
    let secDist = 334;
    let sxCenter = BX + cos(radAng) * secDist;
    let syCenter = BY + sin(radAng) * secDist;

    const screwsPerSector = 7;
    for (let k = 0; k < screwsPerSector; k++) {
      let tOff = (k - (screwsPerSector - 1) / 2) * 18.2;
      let sx = sxCenter + cos(tanAng) * tOff;
      let sy = syCenter + sin(tanAng) * tOff;
      let pointOut = (k % 2 === 0);
      layout.screws.push({
        x: sx,
        y: sy,
        ang: pointOut ? radAng : radAng + 180,
        len: 43,
        headR: 7.4,
        shankW: 6.2
      });
    }

    // Pack the 8 octagon corner vertices with small copper/brass lock-nuts & washers
    let cornerAng = 22.5 + sec * 45;
    for (let cr of [328, 348, 364]) {
      let cp = toWorld(cr, cornerAng + (cr === 348 ? -4.2 : 4.2));
      layout.microFillers.push({
        x: cp.x,
        y: cp.y,
        r: (cr === 364) ? 5.5 : 6.4,
        isCopper: (sec % 2 === 0)
      });
      if (cr === 348) {
        let cp2 = toWorld(cr, cornerAng + 4.2);
        layout.microFillers.push({
          x: cp2.x,
          y: cp2.y,
          r: 6.4,
          isCopper: (sec % 2 !== 0)
        });
      }
    }
  }

  // Additional micro-fillers between rings for obsessive density
  for (let i = 0; i < 24; i++) {
    let a = (i + 0.5) * (360 / 24);
    let p1 = toWorld(143, a);
    let p2 = toWorld(185, a);
    layout.microFillers.push({ x: p1.x, y: p1.y, r: 4.2, isCopper: true });
    layout.microFillers.push({ x: p2.x, y: p2.y, r: 4.5, isCopper: false });
  }

  return layout;
}

// ===========================================================================
// PHASE 5: BATCHED WATERCOLOR WASHES (SIENNA, BRASS-YELLOW, VERDIGRIS)
// ===========================================================================
function renderHardwareWatercolors(hw, BX, BY, BROT) {
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.48, 0.38);

  // -------------------------------------------------------------------------
  // BATCH 1: TERRACOTTA / VENETIAN RED WASHES (Central Compass-Rose Fuses)
  // -------------------------------------------------------------------------
  brush.fill("#a33627", 195);
  for (let f of hw.fuses) {
    let pts = rectPts(f.x, f.y, f.len * 0.65, f.w, f.ang);
    drawPoly(pts);
  }

  // -------------------------------------------------------------------------
  // BATCH 2: BURNT & RAW SIENNA WASHES (Copper Rivets, Pins, Warm Shadows)
  // -------------------------------------------------------------------------
  brush.fill("#b85d2e", 185);
  for (let rv of hw.rivets) {
    let hx = rv.x - cos(rv.ang) * (rv.shankLen * 0.35);
    let hy = rv.y - sin(rv.ang) * (rv.shankLen * 0.35);
    brush.circle(hx, hy, rv.headR * 1.15, 0.15);
    let sPts = rectPts(rv.x + cos(rv.ang) * 4, rv.y + sin(rv.ang) * 4, rv.shankLen * 0.65, rv.shankW, rv.ang);
    drawPoly(sPts);
  }
  for (let cp of hw.compassPins) {
    drawPoly(rectPts(cp.x, cp.y, cp.len * 0.8, 4.5, cp.ang));
  }
  for (let mf of hw.microFillers) {
    if (mf.isCopper) brush.circle(mf.x, mf.y, mf.r, 0.1);
  }

  // Thin sienna glaze over alternating springs & screws for warm tonal depth
  brush.fill("#9c4820", 95);
  for (let i = 0; i < hw.screws.length; i += 2) {
    let sc = hw.screws[i];
    drawPoly(rectPts(sc.x, sc.y, sc.len * 0.85, sc.shankW * 1.3, sc.ang));
  }
  for (let i = 1; i < hw.springs.length; i += 2) {
    let sp = hw.springs[i];
    drawPoly(rectPts(sp.x, sp.y, sp.len * 0.9, sp.w * 0.95, sp.ang));
  }

  // -------------------------------------------------------------------------
  // BATCH 3: BRASS-YELLOW & OCHRE WASHES (Screws, Hex Nuts, Springs, Center Cap)
  // -------------------------------------------------------------------------
  brush.fill("#d4a43c", 180);
  // Central brass compass hub
  brush.circle(BX, BY, 21, 0.1);

  for (let sc of hw.screws) {
    drawPoly(rectPts(sc.x, sc.y, sc.len * 0.92, sc.shankW * 1.35, sc.ang));
  }
  for (let sp of hw.springs) {
    if (sp.isBrass) {
      drawPoly(rectPts(sp.x, sp.y, sp.len * 0.92, sp.w * 0.95, sp.ang));
    }
  }
  for (let nut of hw.hexNuts) {
    if (nut.isBrass) {
      brush.circle(nut.x, nut.y, nut.r * 0.95, 0.12);
    }
  }
  for (let mf of hw.microFillers) {
    if (!mf.isCopper) brush.circle(mf.x, mf.y, mf.r, 0.1);
  }

  // -------------------------------------------------------------------------
  // BATCH 4: GALVANISED ZINC / PEWTER EARTH WASHES (Washers, Steel Nuts & Springs)
  // -------------------------------------------------------------------------
  brush.fill("#a3a195", 175);
  for (let w of hw.washers) {
    brush.circle(w.x, w.y, w.outerR * 0.96, 0.1);
  }
  for (let nut of hw.hexNuts) {
    if (!nut.isBrass) {
      brush.circle(nut.x, nut.y, nut.r * 0.95, 0.12);
    }
  }
  for (let sp of hw.springs) {
    if (!sp.isBrass) {
      drawPoly(rectPts(sp.x, sp.y, sp.len * 0.9, sp.w * 0.9, sp.ang));
    }
  }

  // -------------------------------------------------------------------------
  // BATCH 5: VERDIGRIS WATERCOLOR WASHES (Patina on Copper, Brass & Crevices)
  // -------------------------------------------------------------------------
  brush.fillBleed(0.28, "out");
  brush.fill("#4f8572", 115);
  for (let rv of hw.rivets) {
    if (rv.verdigris) {
      brush.circle(rv.x, rv.y, 9.5, 0.25);
    }
  }
  for (let nut of hw.hexNuts) {
    if (nut.hasVerdigris) {
      brush.circle(nut.x + 3, nut.y - 3, 10.5, 0.25);
    }
  }
  for (let i = 0; i < hw.screws.length; i += 4) {
    let sc = hw.screws[i];
    brush.circle(sc.x, sc.y, 9, 0.3);
  }
  for (let i = 0; i < hw.washers.length; i += 3) {
    let w = hw.washers[i];
    brush.circle(w.x - 4, w.y + 4, 11, 0.3);
  }

  brush.noFill();
}

function rectPts(cx, cy, len, wid, angDeg) {
  let ca = cos(angDeg);
  let sa = sin(angDeg);
  let nx = -sa;
  let ny = ca;
  let hl = len * 0.5;
  let hw = wid * 0.5;
  return [
    [cx - ca * hl - nx * hw, cy - sa * hl - ny * hw],
    [cx + ca * hl - nx * hw, cy + sa * hl - ny * hw],
    [cx + ca * hl + nx * hw, cy + sa * hl + ny * hw],
    [cx - ca * hl + nx * hw, cy - sa * hl + ny * hw]
  ];
}

// ===========================================================================
// PHASE 6: HYPERREAL PEN STIPPLING & MECHANICAL INK RENDERING
// ===========================================================================
function renderHardwareInkAndStipple(hw, BX, BY, BROT) {
  // -------------------------------------------------------------------------
  // 1. MICRO-FILLERS (Corner nuts, interstitial eyelets & beads)
  // -------------------------------------------------------------------------
  for (let mf of hw.microFillers) {
    brush.set("rotring", "#1d140d", 0.34);
    brush.circle(mf.x, mf.y, mf.r, 0.05);
    brush.circle(mf.x, mf.y, mf.r * 0.42, 0.05);
    brush.set("stippleDense", "#1d140d", 0.32);
    brush.arc(mf.x, mf.y, mf.r * 0.75, 20, 200);
    brush.set("inkGlint", "#f7f0de", 0.28);
    brush.arc(mf.x, mf.y, mf.r * 0.7, 210, 290);
  }

  // -------------------------------------------------------------------------
  // 2. CENTRAL COMPASS-ROSE OF RED-HANDLED FUSES & BRASS HUB
  // -------------------------------------------------------------------------
  // Interstitial copper compass needles first
  for (let cp of hw.compassPins) {
    push();
    translate(cp.x, cp.y);
    rotate(cp.ang);
    let hl = cp.len * 0.5;
    brush.set("rotring", "#21160f", 0.32);
    drawPoly([[-hl, -2.6], [hl - 8, -1.8], [hl, 0], [hl - 8, 1.8], [-hl, 2.6]]);
    brush.set("stippleDense", "#241810", 0.3);
    safeLine(-hl + 2, 1.4, hl - 4, 0.9);
    brush.set("inkGlint", "#f5ebd6", 0.24);
    safeLine(-hl + 4, -1.1, hl - 9, -0.8);
    pop();
  }

  // The 8 Red-Handled Fuses
  for (let f of hw.fuses) {
    drawDetailedFuse(f.x, f.y, f.len, f.w, f.ang);
  }

  // Central Knurled Brass Compass Hub (r = 0..22)
  push();
  translate(BX, BY);
  rotate(BROT);
  brush.noStroke();
  brush.wash("#d6a840", 230);
  brush.circle(0, 0, 20);
  brush.wash("#b5622e", 210);
  brush.circle(0, 0, 10);
  brush.noWash();

  brush.set("rotring", "#1a110b", 0.45);
  brush.circle(0, 0, 21, 0.03);
  brush.circle(0, 0, 16, 0.03);
  brush.circle(0, 0, 10, 0.03);
  brush.circle(0, 0, 4, 0.03);
  // Knurled edge ticks
  brush.set("rotring", "#241810", 0.28);
  for (let a = 0; a < 360; a += 12) {
    safeLine(cos(a) * 16, sin(a) * 16, cos(a) * 21, sin(a) * 21);
  }
  // Center calibration screw slot
  brush.set("rotring", "#140c07", 0.6);
  safeLine(-9, -3, 9, 3);
  brush.set("stippleDense", "#1c120b", 0.38);
  brush.arc(0, 0, 13, 15, 195);
  brush.set("inkGlint", "#faf3e3", 0.35);
  brush.arc(0, 0, 14, 205, 315);
  pop();

  // -------------------------------------------------------------------------
  // 3. RING 1: COPPER RIVETS (Domed head, shank, verdigris & dense stippling)
  // -------------------------------------------------------------------------
  for (let rv of hw.rivets) {
    drawDetailedCopperRivet(rv.x, rv.y, rv.headR, rv.shankLen, rv.shankW, rv.ang, rv.verdigris);
  }

  // -------------------------------------------------------------------------
  // 4. RING 2: GALVANISED WASHERS (Imbricated overlapping ring with zinc spangle)
  // -------------------------------------------------------------------------
  for (let w of hw.washers) {
    drawDetailedGalvanisedWasher(w.x, w.y, w.outerR, w.innerR, w.ang);
  }

  // -------------------------------------------------------------------------
  // 5. RING 3: COILED SPRINGS (Helical wire turns, inner shadow & highlights)
  // -------------------------------------------------------------------------
  for (let sp of hw.springs) {
    drawDetailedCoiledSpring(sp.x, sp.y, sp.len, sp.w, sp.coils, sp.ang);
  }

  // -------------------------------------------------------------------------
  // 6. RING 4: HEX NUTS (6 chamfered facets, threaded bore & stippled shading)
  // -------------------------------------------------------------------------
  for (let nut of hw.hexNuts) {
    drawDetailedHexNut(nut.x, nut.y, nut.r, nut.boreR, nut.ang);
  }

  // -------------------------------------------------------------------------
  // 7. RING 5: BRASS SCREWS (Slotted countersunk head, tapered neck & threads)
  // -------------------------------------------------------------------------
  for (let sc of hw.screws) {
    drawDetailedBrassScrew(sc.x, sc.y, sc.len, sc.headR, sc.shankW, sc.ang);
  }
}

// ===========================================================================
// DETAILED HARDWARE COMPONENT RENDERERS (PEN & STIPPLE HYPERREALISM)
// ===========================================================================

function drawDetailedFuse(x, y, len, w, ang) {
  push();
  translate(x, y);
  rotate(ang);

  let hl = len * 0.5;
  let hw = w * 0.5;

  // Cast shadow onto recessed box bed
  brush.set("stippleDense", "#140d08", 0.45);
  safeLine(-hl + 3, hw + 2.2, hl - 3, hw + 2.2);

  // Brass end ferrules (left & right caps) and copper contact blade tip
  brush.noStroke();
  brush.wash("#d4a642", 215);
  brush.rect(-hl + 5, 0, 8, w * 0.86, "center");
  brush.rect(hl - 7, 0, 8, w * 0.86, "center");
  brush.wash("#bf6330", 225);
  drawPoly([[hl - 3, -w * 0.25], [hl + 5, -w * 0.12], [hl + 5, w * 0.12], [hl - 3, w * 0.25]]);
  // Red bakelite/ceramic handle body
  brush.wash("#9e3324", 210);
  brush.rect(-1, 0, len - 22, w, "center");
  brush.noWash();

  // Crisp pen contours
  brush.set("rotring", "#1c120b", 0.38);
  brush.rect(-1, 0, len - 22, w, "center");
  brush.rect(-hl + 5, 0, 8, w * 0.86, "center");
  brush.rect(hl - 7, 0, 8, w * 0.86, "center");
  drawPoly([[hl - 3, -w * 0.25], [hl + 5, -w * 0.12], [hl + 5, w * 0.12], [hl - 3, w * 0.25]]);

  // Molded grip ribs on the red fuse handle & central amperage window
  brush.set("rotring", "#2b1610", 0.28);
  for (let rx = -hl + 12; rx <= hl - 14; rx += 3.6) {
    if (abs(rx + 1) > 4.5) {
      safeLine(rx, -hw + 1, rx, hw - 1);
    }
  }
  // Tiny recessed amperage indicator window in center of red handle
  brush.set("rotring", "#1c120b", 0.32);
  brush.rect(-1, 0, 7.5, w * 0.48, "center");

  // Cylindrical pen stippling along shadow side of red handle
  brush.set("stippleDense", "#26110c", 0.36);
  safeLine(-hl + 10, hw * 0.65, hl - 12, hw * 0.65);
  brush.set("stippleMid", "#3b1b14", 0.3);
  safeLine(-hl + 10, hw * 0.25, hl - 12, hw * 0.25);

  // Specular highlight along top ridge of handle & brass ferrules
  brush.set("inkGlint", "#f7efe0", 0.3);
  safeLine(-hl + 10, -hw * 0.58, hl - 12, -hw * 0.58);
  safeLine(hl - 9, -hw * 0.45, hl + 3, -hw * 0.1);
  pop();
}

function drawDetailedCopperRivet(x, y, headR, shankLen, shankW, ang, hasVerdigris) {
  push();
  translate(x, y);
  rotate(ang);

  let hx = -shankLen * 0.32;
  let sxStart = hx + headR * 0.35;
  let sxEnd = sxStart + shankLen * 0.78;
  let hw = shankW * 0.5;

  // Cast shadow
  brush.set("stippleDense", "#140d08", 0.42);
  safeLine(sxStart, hw + 1.8, sxEnd, hw + 1.8);
  brush.arc(hx, 1.5, headR + 1, -70, 120);

  // Shank contour & cylindrical ring striations
  brush.set("rotring", "#1f140d", 0.36);
  drawPoly([[sxStart, -hw], [sxEnd, -hw * 0.92], [sxEnd, hw * 0.92], [sxStart, hw]]);
  // Beveled rivet tail end
  brush.arc(sxEnd - 1, 0, hw * 0.92, -85, 85);

  // Domed hemispherical copper head (arc + flat underside collar)
  brush.noStroke();
  brush.wash("#b85d2e", 215);
  brush.circle(hx, 0, headR * 0.95);
  brush.noWash();

  brush.set("rotring", "#1c120b", 0.4);
  brush.arc(hx + 1.5, 0, headR, 92, 268);
  safeLine(hx + 1.5, -headR, hx + 1.5, headR);

  // Dense crescent pen stippling on dome & shank shadow side
  brush.set("stippleDense", "#24150c", 0.36);
  brush.arc(hx + 0.5, 1.2, headR * 0.72, 100, 235);
  safeLine(sxStart + 1, hw * 0.55, sxEnd - 1, hw * 0.55);

  brush.set("stippleMid", "#4a2713", 0.28);
  safeLine(sxStart + 1, 0, sxEnd - 1, 0);

  // Verdigris patina stipple dots in collar crevice
  if (hasVerdigris) {
    brush.set("stippleMid", "#467a67", 0.35);
    safeLine(hx + 2.2, -headR * 0.7, hx + 2.2, headR * 0.7);
  }

  // Crisp metallic glint on upper-left of copper dome and shank ridge
  brush.set("inkGlint", "#fbf3e4", 0.32);
  brush.arc(hx, -1.5, headR * 0.58, 195, 255);
  safeLine(sxStart + 2, -hw * 0.55, sxEnd - 2, -hw * 0.52);
  pop();
}

function drawDetailedGalvanisedWasher(x, y, outerR, innerR, ang) {
  push();
  translate(x, y);
  rotate(ang);

  // Overlapping cast shadow onto neighbor washer & recessed bed
  brush.set("stippleDense", "#16100b", 0.48);
  brush.arc(2.2, 2.2, outerR + 1.2, -45, 155);
  brush.arc(-1.5, -1.5, innerR - 1, 120, 320);

  // Opaque galvanised body ring wash so overlapping order reads cleanly
  brush.noStroke();
  brush.wash("#a8a69a", 215);
  brush.circle(0, 0, outerR * 0.96);
  // Dark recessed hole in center of washer
  brush.wash("#1f1610", 240);
  brush.circle(0, 0, innerR * 0.96);
  brush.noWash();

  // Crystalline zinc spangle texture (characteristic of hot-dip galvanised steel)
  let midR = (outerR + innerR) * 0.5;
  brush.set("stippleFine", "#57554d", 0.32);
  brush.circle(0, 0, midR, 0.08);
  brush.set("rotring", "#6e6c63", 0.2);
  for (let s = 0; s < 10; s++) {
    let sa = s * 36 + 15;
    safeLine(cos(sa) * (innerR + 1.5), sin(sa) * (innerR + 1.5), cos(sa + 12) * (outerR - 1.5), sin(sa + 12) * (outerR - 1.5));
  }

  // Stippled tonal gradient across the flat washer face
  brush.set("stippleDense", "#2e2c27", 0.34);
  brush.arc(0, 0, midR, 15, 155);
  brush.set("stippleMid", "#4a4840", 0.28);
  brush.arc(0, 0, midR + 2.5, -25, 185);

  // Crisp double-bevel technical ink outlines
  brush.set("rotring", "#1c1611", 0.42);
  brush.circle(0, 0, outerR, 0.02);
  brush.circle(0, 0, innerR, 0.02);
  brush.set("rotring", "#45423b", 0.22);
  brush.circle(0, 0, outerR - 2.2, 0.02);

  // Bright zinc specular rim highlight
  brush.set("inkGlint", "#faf6eb", 0.34);
  brush.arc(0, 0, outerR - 1.2, 195, 295);
  brush.arc(0, 0, innerR + 1.2, 20, 115);
  pop();
}

function drawDetailedCoiledSpring(x, y, len, w, coils, ang) {
  push();
  translate(x, y);
  rotate(ang);

  let hl = len * 0.5;
  let hw = w * 0.5;

  // Deep core shadow inside the hollow of the spring coils
  brush.noStroke();
  brush.wash("#1a120c", 230);
  brush.rect(0, 0, len - 6, w * 0.72, "center");
  brush.noWash();

  // End hook loops at left and right ends of spring
  brush.set("rotring", "#1c130c", 0.38);
  brush.arc(-hl + 2, 0, hw * 0.65, 95, 265);
  brush.arc(hl - 2, 0, hw * 0.65, -85, 85);

  // Render each individual helical wire coil turn
  let startX = -hl + 3.5;
  let endX = hl - 3.5;
  let step = (endX - startX) / coils;

  for (let c = 0; c < coils; c++) {
    let x1 = startX + c * step;
    let x2 = x1 + step * 0.65;

    // Back-side dark wire segment
    brush.set("rotring", "#2b1d12", 0.32);
    safeLine(x2, hw * 0.85, x1 + step, -hw * 0.85);

    // Front-side illuminated coil wire (thick brass/steel wire with twin ink edges)
    brush.set("rotring", "#d4a846", 0.75);
    safeLine(x1, -hw, x2, hw);

    brush.set("rotring", "#19110a", 0.34);
    safeLine(x1 - 0.9, -hw, x2 - 0.9, hw);
    safeLine(x1 + 0.9, -hw, x2 + 0.9, hw);

    // Stippled shadow on lower half of each coil turn
    brush.set("stippleDense", "#1c130c", 0.32);
    safeLine(lerp(x1, x2, 0.55), 0, x2, hw);

    // Specular glint bead at top crest of each coil turn
    brush.set("inkGlint", "#fcf6e8", 0.35);
    safeLine(x1, -hw + 0.8, lerp(x1, x2, 0.35), -hw * 0.25);
  }
  pop();
}

function drawDetailedHexNut(x, y, r, boreR, ang) {
  push();
  translate(x, y);
  rotate(ang);

  // Hex vertices
  let hexPts = [];
  for (let i = 0; i < 6; i++) {
    let a = i * 60;
    hexPts.push([cos(a) * r, sin(a) * r]);
  }

  // Drop shadow under bottom-right facets
  brush.set("stippleDense", "#140d08", 0.45);
  safeLine(hexPts[0][0] + 2, hexPts[0][1] + 2, hexPts[1][0] + 2, hexPts[1][1] + 2);
  safeLine(hexPts[1][0] + 2, hexPts[1][1] + 2, hexPts[2][0] + 2, hexPts[2][1] + 2);

  // Dark threaded central bore
  brush.noStroke();
  brush.wash("#1a120c", 240);
  brush.circle(0, 0, boreR);
  brush.noWash();

  // Stippled shading on bottom-right 3 facets of the hexagon
  brush.set("stippleDense", "#24180f", 0.36);
  brush.arc(0, 0, r * 0.72, -10, 145);
  brush.set("stippleMid", "#3d2b1c", 0.28);
  brush.arc(0, 0, r * 0.72, 145, 225);

  // Outer hex outline & chamfer circle (classic M10 machined nut geometry)
  brush.set("rotring", "#19110a", 0.42);
  drawPoly(hexPts);
  brush.set("rotring", "#2b1d12", 0.3);
  brush.circle(0, 0, r * 0.82, 0.02);

  // Internal helical thread arcs inside the nut bore
  brush.set("rotring", "#170f09", 0.38);
  brush.circle(0, 0, boreR, 0.02);
  brush.set("rotring", "#8c6d32", 0.26);
  brush.arc(0.8, 0.8, boreR - 1.4, 150, 340);
  brush.arc(1.4, 1.4, boreR - 2.8, 165, 325);

  // Specular highlight on upper-left hex edges & chamfer ring
  brush.set("inkGlint", "#faf2e1", 0.32);
  safeLine(hexPts[3][0], hexPts[3][1], hexPts[4][0], hexPts[4][1]);
  brush.arc(0, 0, r * 0.8, 195, 285);
  pop();
}

function drawDetailedBrassScrew(x, y, len, headR, shankW, ang) {
  push();
  translate(x, y);
  rotate(ang);

  let hl = len * 0.5;
  let headX = -hl + 5;
  let neckX = headX + 6.5;
  let tipX = hl;
  let hw = shankW * 0.5;

  // Cast shadow along lower edge of screw
  brush.set("stippleDense", "#140d08", 0.42);
  safeLine(headX, headR + 1.2, tipX - 3, 2.2);

  // Countersunk / round-slotted brass head & tapered neck
  let headPts = [
    [headX, -headR],
    [headX + 2.5, -headR],
    [neckX, -hw],
    [neckX, hw],
    [headX + 2.5, headR],
    [headX, headR]
  ];
  brush.noStroke();
  brush.wash("#d6a63e", 215);
  drawPoly(headPts);
  // Tapered threaded shaft wash
  let shaftPts = [
    [neckX, -hw],
    [tipX - 7, -hw * 0.78],
    [tipX, 0],
    [tipX - 7, hw * 0.78],
    [neckX, hw]
  ];
  drawPoly(shaftPts);
  brush.noWash();

  // Crisp ink outline of head
  brush.set("rotring", "#1a110a", 0.38);
  drawPoly(headPts);

  // Driver slot notch cut into the screw head
  brush.set("rotring", "#120b06", 0.62);
  safeLine(headX, -1.2, headX + 3.2, -1.2);

  // Helical wood-screw thread ridges along the shank
  let numThreads = 8;
  let tStart = neckX + 2;
  let tEnd = tipX - 3.5;
  let tStep = (tEnd - tStart) / numThreads;

  brush.set("rotring", "#1c120b", 0.34);
  safeLine(neckX, -hw, tipX, 0);
  safeLine(neckX, hw, tipX, 0);

  for (let t = 0; t < numThreads; t++) {
    let tx = tStart + t * tStep;
    let taper = map(t, 0, numThreads, 1.0, 0.38);
    let thW = (hw + 1.6) * taper;
    // Diagonal sharp thread crest
    brush.set("rotring", "#1c120b", 0.34);
    safeLine(tx, -thW, tx + tStep * 0.45, thW);
    // Stippled flank shadow between thread teeth
    brush.set("stippleDense", "#26180d", 0.32);
    safeLine(tx + 0.8, 0, tx + tStep * 0.45 + 0.8, thW * 0.85);
  }

  // Stippled cylindrical shadow along bottom half of head & shaft
  brush.set("stippleDense", "#24160c", 0.36);
  safeLine(headX + 1, headR * 0.55, neckX, hw * 0.65);
  safeLine(neckX, hw * 0.6, tipX - 4, hw * 0.3);

  // Continuous bright brass highlight along top of head and thread crests
  brush.set("inkGlint", "#fcf5e6", 0.32);
  safeLine(headX + 0.8, -headR * 0.55, tipX - 5, -hw * 0.35);
  pop();
}

// ===========================================================================
// PHASE 7: BRASS HINGES & QUADRANT STAY-ARM (CONNECTING BOX & OPEN LID)
// ===========================================================================
function renderHingesAndStay(BX, BY, BROT, R_OUT, R_IN, hingeMidX, hingeMidY, lidLocalCy) {
  // Two heavy brass butt-hinges along the top hinged edge of the octagon
  for (let hOff of [-92, 92]) {
    let hx = hingeMidX + cos(BROT) * hOff;
    let hy = hingeMidY + sin(BROT) * hOff;

    push();
    translate(hx, hy);
    rotate(BROT);

    // Cast shadow of hinge knuckle
    brush.set("stippleDense", "#140d08", 0.48);
    safeLine(-22, 16, 22, 16);

    // Brass hinge leaves (upper leaf on lid, lower leaf on box rim) & 5-segment knuckle barrel
    brush.noStroke();
    brush.wash("#cfa03a", 235);
    brush.rect(0, -10, 44, 15, "center");
    brush.rect(0, 10, 44, 15, "center");
    brush.wash("#e3b954", 240);
    brush.rect(0, 0, 48, 7.5, "center");
    brush.noWash();

    // Verdigris touch at hinge pin ends
    brush.fillBleed(0.2, "out");
    brush.fill("#4d826f", 110);
    brush.circle(-21, 0, 6, 0.2);
    brush.circle(21, 0, 6, 0.2);
    brush.noFill();

    // Technical pen outlines & knuckle segments
    brush.set("rotring", "#1a110a", 0.42);
    brush.rect(0, -10, 44, 15, "center");
    brush.rect(0, 10, 44, 15, "center");
    brush.rect(0, 0, 48, 7.5, "center");

    for (let kx of [-14, -5, 5, 14]) {
      safeLine(kx, -3.7, kx, 3.7);
    }

    // 3 slotted brass wood screws on each hinge leaf
    for (let sx of [-14, 0, 14]) {
      for (let sy of [-10, 10]) {
        brush.set("rotring", "#1a110a", 0.35);
        brush.circle(sx, sy, 3.6);
        safeLine(sx - 2.5, sy - 1.2, sx + 2.5, sy + 1.2);
        brush.set("inkGlint", "#faf2e1", 0.28);
        brush.arc(sx, sy, 2.6, 190, 290);
      }
    }

    // Specular highlight along hinge barrel
    brush.set("inkGlint", "#fcf6e8", 0.36);
    safeLine(-22, -1.8, 22, -1.8);
    pop();
  }

  // Curved / Slotted Brass Stay-Arm on the right side propping the lid open
  let stayBoxPt = [
    BX + cos(-28 + BROT) * (R_IN + 18),
    BY + sin(-28 + BROT) * (R_IN + 18)
  ];
  let stayLidPt = lidPt(R_IN - 22, lidLocalCy + 95, hingeMidX, hingeMidY, BROT);

  // Shadow of the stay-arm
  brush.set("stippleDense", "#17100b", 0.5);
  safeLine(stayBoxPt[0] + 10, stayBoxPt[1] + 8, stayLidPt[0] + 10, stayLidPt[1] + 8);

  // Brass arm body
  let armAng = atan2(stayLidPt[1] - stayBoxPt[1], stayLidPt[0] - stayBoxPt[0]);
  let armLen = dist(stayBoxPt[0], stayBoxPt[1], stayLidPt[0], stayLidPt[1]);
  let armMidX = (stayBoxPt[0] + stayLidPt[0]) * 0.5;
  let armMidY = (stayBoxPt[1] + stayLidPt[1]) * 0.5;

  let armPoly = rectPts(armMidX, armMidY, armLen + 14, 12, armAng);
  brush.noStroke();
  brush.wash("#d4a640", 235);
  drawPoly(armPoly);
  brush.noWash();

  brush.set("rotring", "#1a110a", 0.42);
  drawPoly(armPoly);

  // Slotted guide track down the center of the brass stay-arm
  let slotPoly = rectPts(armMidX, armMidY, armLen - 18, 4.2, armAng);
  brush.noStroke();
  brush.wash("#241810", 220);
  drawPoly(slotPoly);
  brush.noWash();
  brush.set("rotring", "#1a110a", 0.32);
  drawPoly(slotPoly);

  // Brass pivot plates & knurled thumb-nut at both ends of stay-arm
  for (let pt of [stayBoxPt, stayLidPt]) {
    brush.noStroke();
    brush.wash("#dfb44f", 240);
    brush.circle(pt[0], pt[1], 8.5);
    brush.noWash();
    brush.set("rotring", "#1a110a", 0.4);
    brush.circle(pt[0], pt[1], 8.5);
    brush.circle(pt[0], pt[1], 4.5);
    safeLine(pt[0] - 3.5, pt[1] - 1.5, pt[0] + 3.5, pt[1] + 1.5);
    brush.set("inkGlint", "#fcf5e6", 0.34);
    brush.arc(pt[0], pt[1], 6.5, 195, 295);
  }

  brush.set("inkGlint", "#fcf5e6", 0.34);
  safeLine(
    stayBoxPt[0] - sin(armAng) * 4,
    stayBoxPt[1] + cos(armAng) * 4,
    stayLidPt[0] - sin(armAng) * 4,
    stayLidPt[1] + cos(armAng) * 4
  );
}

