// PHASE 8: WORKBENCH CLUTTER, SORTING TWEEZERS & LOOSE HARDWARE
// ===========================================================================
function renderWorkbenchClutter(BX, BY, BROT) {
  // Loose spare hardware scattered in warm order on the workbench (lower-left & upper-right)
  const looseScrews = [
    { x: 145, y: 835, len: 52, headR: 8.8, shankW: 7.4, ang: 34 },
    { x: 225, y: 1055, len: 48, headR: 8.2, shankW: 7.0, ang: -18 },
    { x: 1055, y: 395, len: 48, headR: 8.2, shankW: 7.0, ang: 128 }
  ];
  const looseWashers = [
    { x: 255, y: 905, outerR: 23, innerR: 9.5, ang: 15 },
    { x: 1015, y: 225, outerR: 22, innerR: 9.0, ang: 65 }
  ];
  const looseNuts = [
    { x: 135, y: 955, r: 16, boreR: 7.5, ang: 22 },
    { x: 315, y: 1095, r: 15.5, boreR: 7.2, ang: 48 },
    { x: 1085, y: 295, r: 15.5, boreR: 7.2, ang: 10 }
  ];
  const looseSprings = [
    { x: 195, y: 745, len: 54, w: 13, coils: 10, ang: -42 },
    { x: 1045, y: 1065, len: 52, w: 12.5, coils: 9, ang: 25 }
  ];
  const looseRivets = [
    { x: 285, y: 985, headR: 8.5, shankLen: 25, shankW: 7.5, ang: 145, verdigris: true },
    { x: 95, y: 890, headR: 8.2, shankLen: 24, shankW: 7.2, ang: -65, verdigris: false }
  ];
  const looseFuse = { x: 155, y: 650, len: 58, w: 16, ang: 18 };

  // Watercolor washes + cast shadows under loose items
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.35);

  // Soft cast shadows on bench
  brush.fill("#3d2e21", 110);
  for (let sc of looseScrews) brush.circle(sc.x + 6, sc.y + 7, 16, 0.3);
  for (let w of looseWashers) brush.circle(w.x + 6, w.y + 7, w.outerR, 0.2);
  for (let n of looseNuts) brush.circle(n.x + 6, n.y + 7, n.r, 0.2);
  for (let sp of looseSprings) brush.circle(sp.x + 6, sp.y + 7, 18, 0.3);
  for (let rv of looseRivets) brush.circle(rv.x + 5, rv.y + 6, 12, 0.3);
  brush.circle(looseFuse.x + 6, looseFuse.y + 7, 20, 0.3);

  // Verdigris & sienna puddles around loose hardware
  brush.fill("#4f8572", 75);
  brush.circle(275, 975, 22, 0.35);
  brush.circle(140, 845, 18, 0.35);
  brush.fill("#b85d2e", 70);
  brush.circle(195, 750, 24, 0.35);
  brush.noFill();

  // Render the loose hardware with full hyperreal stippling
  drawDetailedFuse(looseFuse.x, looseFuse.y, looseFuse.len, looseFuse.w, looseFuse.ang);
  for (let rv of looseRivets) drawDetailedCopperRivet(rv.x, rv.y, rv.headR, rv.shankLen, rv.shankW, rv.ang, rv.verdigris);
  for (let w of looseWashers) drawDetailedGalvanisedWasher(w.x, w.y, w.outerR, w.innerR, w.ang);
  for (let sp of looseSprings) drawDetailedCoiledSpring(sp.x, sp.y, sp.len, sp.w, sp.coils, sp.ang);
  for (let n of looseNuts) drawDetailedHexNut(n.x, n.y, n.r, n.boreR, n.ang);
  for (let sc of looseScrews) drawDetailedBrassScrew(sc.x, sc.y, sc.len, sc.headR, sc.shankW, sc.ang);

  // -------------------------------------------------------------------------
  // PRECISION BRASS/STEEL SORTING TWEEZERS IN LOWER-LEFT CORNER
  // (Used by the maker to pack the Sailor's Valentine hardware)
  // -------------------------------------------------------------------------
  push();
  translate(115, 1095);
  rotate(-36);

  // Cast shadow of tweezers on bench
  brush.set("stippleDense", "#291d14", 0.5);
  safeLine(-95, 14, 125, 9);
  safeLine(-95, 2, 125, 6);

  // Two spring-steel & brass arms converging to fine needle tips at right (x = 130)
  let topArm = [[-110, -8], [20, -9], [130, -1.5], [130, 0.2], [20, -3.5], [-110, -2]];
  let botArm = [[-110, -2], [20, 3.5], [130, 1.8], [130, 3.5], [20, 9], [-110, 4]];

  brush.noStroke();
  brush.wash("#b59a68", 225);
  drawPoly(topArm);
  brush.wash("#8f784d", 225);
  drawPoly(botArm);
  brush.noWash();

  brush.set("rotring", "#1c130c", 0.4);
  drawPoly(topArm);
  drawPoly(botArm);

  // Serrated grip ribs on the tweezer handle
  brush.set("rotring", "#2b1e14", 0.28);
  for (let gx = -55; gx <= 10; gx += 4.2) {
    safeLine(gx, -8.5, gx, -3.8);
    safeLine(gx, 3.8, gx, 8.5);
  }

  // Stippled shading & metallic highlight along tweezer blades
  brush.set("stippleMid", "#2b1e14", 0.32);
  safeLine(-105, 6.5, 115, 2.8);
  brush.set("inkGlint", "#fcf6e8", 0.35);
  safeLine(-105, -6.5, 122, -1.0);
  pop();

  // Small vintage workshop inventory tag / paper slip in top-right corner
  push();
  translate(1045, 115);
  rotate(14);
  brush.noStroke();
  brush.wash("#efe3c8", 215);
  brush.rect(0, 0, 145, 64, "center");
  brush.noWash();
  brush.fillBleed(0.2, "in");
  brush.fill("#c99d66", 55);
  brush.rect(0, 0, 145, 64, "center");
  brush.noFill();

  brush.set("rotring", "#3d2c1e", 0.34);
  brush.rect(0, 0, 145, 64, "center");
  brush.set("rotring", "#7a3624", 0.26);
  brush.rect(0, 0, 135, 54, "center");
  // Brass eyelet & string hole on tag
  brush.set("rotring", "#241810", 0.38);
  brush.circle(-54, 0, 6);
  brush.circle(-54, 0, 3);
  // Handwritten cursive/technical ink lines on label ("NO. 8 — ASSORTED BRASS & COPPER")
  brush.set("rotring", "#2e2015", 0.25);
  safeLine(-36, -12, 52, -12);
  safeLine(-36, 0, 44, 0);
  safeLine(-36, 12, 28, 12);
  brush.set("stippleFine", "#3d2c1e", 0.28);
  safeLine(-34, -13, 48, -11);
  safeLine(-34, 1, 40, -1);
  pop();
}

