    opacity: 235,
    spacing: 0.12,
    pressure: [0.45, 1.0, 0.45],
    noise: 0.18
  });

  brush.add("weave", {
    type: "default",
    weight: 0.4,
    scatter: 0.15,
    sharpness: 0.65,
    grain: 0.9,
    opacity: 140,
    spacing: 0.22,
    pressure: [0.8, 1.0, 0.8],
    noise: 0.4
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Solid, deep matte indigo-blue void ground
  background(PALETTES.indigo.void);
  buildSkydiverKinematics();
  drawMatteIndigoGround();

  // 2. Tiny high-altitude cloud wisps far below in the void
  drawDistantCloudWisps();

  // 3. Paracas repeating grid that breathes with the figures' aerodynamic movement
  drawBreathingParacasGrid();

  // 4. Outer Paracas textile embroidered border frame
  drawParacasMantleBorder();

  // 5. Render the 8 skydivers in layered anatomical passes
  // Pass A: Deep aerodynamic burble shadows over the grid
  for (let i = 0; i < 8; i++) {
    drawFigureShadow(skydivers[i]);
  }

  // Pass B: Lower legs, booties, thighs, leg-straps, torso, rig container, upper arms, helmet & goggles
  for (let i = 0; i < 8; i++) {
    drawSkydiverBody(skydivers[i]);
  }

  // Pass C: Forearms, wrist altimeters, and interlocking straining fingers at the 8 star grip points
  drawAllForearmsAndLinkedHands();

  // Pass D: Final hyperreal micro-stitches, 3-ring hardware glints, goggle highlights & thread tension ticks
  drawFinalMicroDetails();

  noLoop();
}

// ============================================================================
// 1. KINEMATICS & GEOMETRY OF THE 8-WAY STAR ON THE 3x3 PARACAS GRID
// ============================================================================

function buildSkydiverKinematics() {
  const cx = 600;
  const cy = 600;

  // 8 grip points around the central star ring (at mid-angles between adjacent figures)
  gripPoints = [];
  for (let k = 0; k < 8; k++) {
    let phi = -112.5 + k * 45 + sin(k * 90 + 25) * 1.4;
    let rGrip = 148 + cos(k * 135) * 3.5;
    gripPoints.push({
      x: cx + rGrip * cos(phi),
      y: cy + rGrip * sin(phi),
      angle: phi,
      r: rGrip
    });
  }

  skydivers = [];
  for (let i = 0; i < 8; i++) {
    let isDiagonal = (i % 2 === 1);
    let theta = -90 + i * 45;
    // Slight organic sway so the strict grid breathes
    let swayDeg = sin(i * 135 + 40) * 1.8;
    let bodyAngle = theta + swayDeg;

    let rad = (ang, r) => ({
      x: cx + r * cos(ang),
      y: cy + r * sin(ang)
    });

    // Diagonal figures reach slightly further into the 4 corner cells of the 3x3 grid
    let rHead = isDiagonal ? 210 : 194;
    let rShoulder = isDiagonal ? 250 : 230;
    let rTorso = isDiagonal ? 312 : 284;
    let rPelvis = isDiagonal ? 380 : 344;
    let rKnee = isDiagonal ? 476 : 426;
    let rAnkle = isDiagonal ? 560 : 492;
    let rToe = isDiagonal ? 592 : 518;

    // Local basis vectors: u = outward radial (head -> pelvis), v = lateral (left -> right when viewed from above)
    let ux = cos(bodyAngle);
    let uy = sin(bodyAngle);
    let vx = -uy; // clockwise tangent (Right side of skydiver's back)
    let vy = ux;

    let toWorld = (rAlong, latOffset) => ({
      x: cx + rAlong * ux + latOffset * vx,
      y: cy + rAlong * uy + latOffset * vy
    });

    let head = toWorld(rHead, sin(i * 70) * 3);
    let neck = toWorld(rHead + 20, sin(i * 70) * 2);
    let shoulderCenter = toWorld(rShoulder, 0);
    let torsoCenter = toWorld(rTorso, sin(i * 55) * 4);
    let pelvis = toWorld(rPelvis, -sin(i * 55) * 3);

    let shHalfW = isDiagonal ? 49 : 47;
    let hipHalfW = isDiagonal ? 39 : 37;

    // Note: viewed from above (dorsal view, head toward center):
    // Left side is counter-clockwise (-v), Right side is clockwise (+v)
    let leftShoulder = toWorld(rShoulder + 2, -shHalfW);
    let rightShoulder = toWorld(rShoulder + 2, shHalfW);

    let leftHip = toWorld(rPelvis, -hipHalfW);
    let rightHip = toWorld(rPelvis, hipHalfW);

    // Elbows bend outward into a resonant octagonal frame
    let rElbow = isDiagonal ? 204 : 190;
    let elbowSpread = isDiagonal ? 78 : 72;
    let leftElbow = toWorld(rElbow, -elbowSpread);
    let rightElbow = toWorld(rElbow, elbowSpread);

    // Left hand goes to gripPoints[i], Right hand goes to gripPoints[(i + 1) % 8]
    let leftGrip = gripPoints[i];
    let rightGrip = gripPoints[(i + 1) % 8];

    // Splayed frog/Paracas flying legs
    let kneeSpreadL = (isDiagonal ? 78 : 68) + sin(i * 95) * 5;
    let kneeSpreadR = (isDiagonal ? 78 : 68) - sin(i * 95) * 5;
    let leftKnee = toWorld(rKnee, -kneeSpreadL);
    let rightKnee = toWorld(rKnee, kneeSpreadR);

    let ankleSpreadL = (isDiagonal ? 54 : 48) + cos(i * 80) * 6;
    let ankleSpreadR = (isDiagonal ? 54 : 48) - cos(i * 80) * 6;
    let leftAnkle = toWorld(rAnkle, -ankleSpreadL);
    let rightAnkle = toWorld(rAnkle, ankleSpreadR);

    // Bootie toes flare slightly outward to catch the relative wind
    let leftToe = toWorld(rToe, -ankleSpreadL - 16);
    let rightToe = toWorld(rToe, ankleSpreadR + 16);

    let scheme = FIGURE_SCHEMES[i];

    skydivers.push({
      index: i,
      isDiagonal,
      theta,
      bodyAngle,
      ux, uy, vx, vy,
      toWorld,
      rHead, rShoulder, rTorso, rPelvis, rKnee, rAnkle,
      head, neck, shoulderCenter, torsoCenter, pelvis,
      leftShoulder, rightShoulder,
      leftHip, rightHip,
      leftElbow, rightElbow,
      leftGrip, rightGrip,
      leftKnee, rightKnee,
      leftAnkle, rightAnkle,
      leftToe, rightToe,
      palMain: PALETTES[scheme.main],
      palSec: PALETTES[scheme.sec],
      palRig: PALETTES[scheme.rig],
      scheme
    });
  }
}

// Aerodynamic displacement function so the strict Paracas grid breathes with the figures
function displaceGridPoint(x, y) {
  let dx = 0;
  let dy = 0;
  const cx = 600;
  const cy = 600;

  // Subtle central star inflow tension
  let dCenter = dist(x, y, cx, cy);
  if (dCenter > 40 && dCenter < 260) {
    let pull = -7.5 * sin(((dCenter - 40) / 220) * 180);
    dx += ((x - cx) / dCenter) * pull;
    dy += ((y - cy) / dCenter) * pull;
  }

  // Outward aerodynamic pressure wave around each falling skydiver
  for (let i = 0; i < skydivers.length; i++) {
    let s = skydivers[i];
    let dTorso = dist(x, y, s.torsoCenter.x, s.torsoCenter.y);
    if (dTorso < 190 && dTorso > 5) {
      let w = pow(1 - dTorso / 190, 2) * 15;
      dx += ((x - s.torsoCenter.x) / dTorso) * w;
      dy += ((y - s.torsoCenter.y) / dTorso) * w;
    }
    let dKnees = dist(x, y, s.pelvis.x, s.pelvis.y);
    if (dKnees < 150 && dKnees > 5) {
      let w = pow(1 - dKnees / 150, 2) * 10;
      dx += ((x - s.pelvis.x) / dKnees) * w;
      dy += ((y - s.pelvis.y) / dKnees) * w;
    }
  }

  // Gentle high-altitude harmonic wave
  dx += 2.2 * sin(y * 0.9 + x * 0.3);
  dy += 2.2 * cos(x * 0.9 - y * 0.3);

  return { x: x + dx, y: y + dy };
}

// ============================================================================
// 2. SOLID MATTE INDIGO GROUND & TINY CLOUD WISPS FAR BELOW
// ============================================================================

function drawMatteIndigoGround() {
  // Deep layered opaque washes for a rich, light-absorbing matte indigo ground
  brush.noStroke();
  brush.noFill();

  brush.wash(PALETTES.indigo.void, 255);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Subtle radial tonal deepening in the abyss
  const rings = [
    { r: 580, col: "#0c1426", op: 95 },
    { r: 420, col: "#0f1930", op: 85 },
    { r: 220, col: "#091020", op: 110 },
    { r: 135, col: "#060b16", op: 140 }
  ];
  for (let rg of rings) {
    brush.wash(rg.col, rg.op);
    brush.circle(600, 600, rg.r, 0.08);
    brush.noWash();
  }

  // Fine matte camelid-wool / abyssal warp-weft texture across the dark ground
  brush.set("weave", "#14203b", 0.38);
  for (let y = 62; y <= 1138; y += 14) {
    let x0 = 62;
    let x1 = 1138;
    brush.line(x0, y + random(-0.8, 0.8), x1, y + random(-0.8, 0.8));
  }
  brush.set("weave", "#050912", 0.35);
  for (let x = 62; x <= 1138; x += 16) {
    brush.line(x + random(-0.8, 0.8), 62, x + random(-0.8, 0.8), 1138);
  }
}

function drawDistantCloudWisps() {
  // Tiny stratocumulus wisps 12,000 feet below in the deep indigo void
  // Positioned in the central eye, between figures, and in the deep corners
  const cloudClusters = [
