    { x: 600, y: 600, count: 9, spread: 68, scale: 0.75 },
    { x: 565, y: 575, count: 6, spread: 42, scale: 0.6 },
    { x: 635, y: 628, count: 6, spread: 42, scale: 0.6 },
    // In the gaps between the 8 figures
    { x: 485, y: 315, count: 8, spread: 55, scale: 0.85 },
    { x: 715, y: 315, count: 7, spread: 50, scale: 0.8 },
    { x: 885, y: 485, count: 8, spread: 55, scale: 0.85 },
    { x: 885, y: 715, count: 7, spread: 50, scale: 0.8 },
    { x: 715, y: 885, count: 8, spread: 55, scale: 0.85 },
    { x: 485, y: 885, count: 7, spread: 50, scale: 0.8 },
    { x: 315, y: 715, count: 8, spread: 55, scale: 0.85 },
    { x: 315, y: 485, count: 7, spread: 50, scale: 0.8 },
    // Outer void corners & edges
    { x: 145, y: 155, count: 9, spread: 60, scale: 0.9 },
    { x: 1055, y: 150, count: 9, spread: 60, scale: 0.9 },
