function drawSingleCloudWisp(cx, cy, len, thick, angleDeg) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  let nx = -sa;
  let ny = ca;

  // Build tiny elongated cloud ribbon polygon
  let ptsShadow = [];
  let ptsLight = [];
  let steps = 8;
  for (let i = 0; i <= steps; i++) {
    let t = (i / steps) * 2 - 1; // -1..1
    let env = sqrt(max(0, 1 - t * t));
    let wave = sin(t * 180 + cx) * thick * 0.35;
    let px = cx + t * (len * 0.5) * ca + wave * nx;
    let py = cy + t * (len * 0.5) * sa + wave * ny;
    ptsLight.push([px - nx * thick * 0.45 * env, py - ny * thick * 0.45 * env]);
    ptsShadow.push([px + nx * thick * 0.55 * env, py + ny * thick * 0.55 * env]);
  }
  let poly = ptsLight.concat(ptsShadow.reverse());

  // Cloud shadow in deep slate-indigo
  brush.noStroke();
  brush.wash("#1b2a4a", 115);
  drawPoly(poly.map(p => [p[0] + 2.5, p[1] + 3.0]));
  brush.noWash();

  // Warm sunlit cloud body
  brush.wash("#9c9588", 95);
  drawPoly(poly);
  brush.noWash();

  // Tiny stitch-like cloud filament highlights in warm ivory & pale ochre
  brush.set("fine_needle", "#e3d2b2", 0.26);
  let nStitches = floor(map(len, 10, 40, 4, 9));
  for (let k = 0; k < nStitches; k++) {
    let u = map(k, 0, nStitches - 1, -0.75, 0.75);
    let env = sqrt(max(0, 1 - u * u));
    let sx = cx + u * (len * 0.45) * ca + sin(u * 160 + cy) * thick * 0.25 * nx;
    let sy = cy + u * (len * 0.45) * sa + sin(u * 160 + cy) * thick * 0.25 * ny;
    let sLen = random(4, 9) * env;
    brush.line(
      sx - ca * sLen * 0.5 - nx * thick * 0.2 * env,
      sy - sa * sLen * 0.5 - ny * thick * 0.2 * env,
      sx + ca * sLen * 0.5 - nx * thick * 0.2 * env,
      sy + sa * sLen * 0.5 - ny * thick * 0.2 * env
    );
  }
}

// ============================================================================
// 3. STRICT REPEATING PARACAS GRID THAT BREATHES WITH MOVEMENT
// ============================================================================

function drawBreathingParacasGrid() {
  // Primary 3x3 compartment boundaries + secondary subdivisions
  const mainCuts = [62, 421, 779, 1138];
  const subCuts = [152, 241, 331, 510, 600, 690, 869, 959, 1048];

  // 1. Subtle secondary warp/weft measurement grid lines
  for (let idx = 0; idx < subCuts.length; idx++) {
    let pos = subCuts[idx];
    let isCenterAxis = (pos === 600);
    let col = isCenterAxis ? "#3a4d70" : "#1f2e4d";
    let w = isCenterAxis ? 0.34 : 0.24;

    drawBreathingStitchedLine(pos, 62, pos, 1138, col, w, isCenterAxis ? 7 : 11, false);
    drawBreathingStitchedLine(62, pos, 1138, pos, col, w, isCenterAxis ? 7 : 11, false);
  }

  // 2. Diagonal Paracas octagram alignment threads through the star center
  const diagCoords = [
    [62, 62, 1138, 1138],
    [1138, 62, 62, 1138],
    [421, 62, 1138, 779],
    [62, 421, 779, 1138],
    [779, 62, 62, 779],
    [1138, 421, 421, 1138]
  ];
  for (let d of diagCoords) {
    drawBreathingStitchedLine(d[0], d[1], d[2], d[3], "#2b3b5c", 0.26, 10, true);
  }

  // 3. Concentric altitude / wind-rose rings inside the central hub cell (cell [1,1])
  const hubRadii = [52, 92, 132, 168];
  for (let rIdx = 0; rIdx < hubRadii.length; rIdx++) {
    let r = hubRadii[rIdx];
    let col = (rIdx % 2 === 0) ? PALETTES.ochre.dark : PALETTES.madder.dark;
    brush.set("fine_needle", col, 0.3);
    let nSegs = 64;
    for (let s = 0; s < nSegs; s += 2) {
      let a0 = (s / nSegs) * 360;
      let a1 = ((s + 1.2) / nSegs) * 360;
      let p0 = displaceGridPoint(600 + r * cos(a0), 600 + r * sin(a0));
      let p1 = displaceGridPoint(600 + r * cos(a1), 600 + r * sin(a1));
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // 4. Inset compartment register frames inside each of the 9 cells of the 3x3 grid
  for (let gx = 0; gx < 3; gx++) {
    for (let gy = 0; gy < 3; gy++) {
      let x0 = mainCuts[gx] + 18;
      let y0 = mainCuts[gy] + 18;
      let x1 = mainCuts[gx + 1] - 18;
      let y1 = mainCuts[gy + 1] - 18;
      let palKey = COLOR_KEYS[(gx + gy * 2) % 3];
      let pal = PALETTES[palKey];

      // Inset breathing frame
      drawBreathingStitchedLine(x0, y0, x1, y0, pal.dark, 0.34, 6, true);
      drawBreathingStitchedLine(x1, y0, x1, y1, pal.dark, 0.34, 6, true);
      drawBreathingStitchedLine(x1, y1, x0, y1, pal.dark, 0.34, 6, true);
      drawBreathingStitchedLine(x0, y1, x0, y0, pal.dark, 0.34, 6, true);

      // Stepped Paracas corner frets inside each compartment
      drawSteppedCornerFret(x0, y0, 1, 1, pal);
      drawSteppedCornerFret(x1, y0, -1, 1, pal);
      drawSteppedCornerFret(x1, y1, -1, -1, pal);
      drawSteppedCornerFret(x0, y1, 1, -1, pal);
    }
  }

  // 5. Primary 3x3 double-stitched Paracas grid dividers (the structural warp & weft)
  for (let i = 1; i <= 2; i++) {
    let cut = mainCuts[i];
    // Vertical double-stitched divider with cross-ties
    drawEmbroideredGridRibbon(cut, 62, cut, 1138, i === 1 ? PALETTES.ochre : PALETTES.madder);
    // Horizontal double-stitched divider with cross-ties
    drawEmbroideredGridRibbon(62, cut, 1138, cut, i === 1 ? PALETTES.olive : PALETTES.ochre);
  }

  // 6. Embroidered Paracas textile medallions in the far outer corners of the 4 corner cells
  const cornerMedallions = [
    { x: 122, y: 122, rot: 45,  pal1: PALETTES.madder, pal2: PALETTES.ochre },
    { x: 1078, y: 122, rot: 135, pal1: PALETTES.ochre,  pal2: PALETTES.olive },
    { x: 1078, y: 1078, rot: 225, pal1: PALETTES.olive,  pal2: PALETTES.madder },
    { x: 122, y: 1078, rot: 315, pal1: PALETTES.madder, pal2: PALETTES.olive }
  ];
  for (let cm of cornerMedallions) {
    drawParacasCornerGlyph(cm.x, cm.y, cm.rot, cm.pal1, cm.pal2);
  }
}

function drawBreathingStitchedLine(x0, y0, x1, y1, col, weight, stepPx, dashed) {
  let d = dist(x0, y0, x1, y1);
  let steps = max(2, floor(d / stepPx));
  brush.set("fine_needle", col, weight);
  for (let i = 0; i < steps; i++) {
    if (dashed && i % 2 === 1) continue;
    let t0 = i / steps;
    let t1 = (i + (dashed ? 0.72 : 1.0)) / steps;
    let p0 = displaceGridPoint(lerp(x0, x1, t0), lerp(y0, y1, t0));
    let p1 = displaceGridPoint(lerp(x0, x1, t1), lerp(y0, y1, t1));
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }
}

function drawEmbroideredGridRibbon(x0, y0, x1, y1, pal) {
  let d = dist(x0, y0, x1, y1);
  let steps = floor(d / 7);
  let tx = (x1 - x0) / d;
  let ty = (y1 - y0) / d;
  let nx = -ty;
  let ny = tx;
  let halfW = 3.2;

  for (let i = 0; i < steps; i++) {
    let t0 = i / steps;
    let t1 = (i + 1) / steps;
    let mx0 = lerp(x0, x1, t0);
    let my0 = lerp(y0, y1, t0);
    let mx1 = lerp(x0, x1, t1);
    let my1 = lerp(y0, y1, t1);

    let pA = displaceGridPoint(mx0 - nx * halfW, my0 - ny * halfW);
    let pB = displaceGridPoint(mx1 - nx * halfW, my1 - ny * halfW);
    let pC = displaceGridPoint(mx0 + nx * halfW, my0 + ny * halfW);
    let pD = displaceGridPoint(mx1 + nx * halfW, my1 + ny * halfW);

    brush.set("stitch", pal.mid, 0.34);
    brush.line(pA.x, pA.y, pB.x, pB.y);
    brush.line(pC.x, pC.y, pD.x, pD.y);

    // Alternating cross-stitch bar
    let barCol = (i % 3 === 0) ? PALETTES.ivory.mid : (i % 3 === 1 ? pal.bright : pal.dark);
    brush.set("fine_needle", barCol, 0.28);
    brush.line(pA.x, pA.y, pD.x, pD.y);
  }
}

function drawSteppedCornerFret(cx, cy, dirX, dirY, pal) {
  const s = 7;
  let pts = [
    [cx, cy],
    [cx + dirX * s * 4, cy],
    [cx + dirX * s * 4, cy + dirY * s],
    [cx + dirX * s * 2, cy + dirY * s],
    [cx + dirX * s * 2, cy + dirY * s * 2],
    [cx + dirX * s, cy + dirY * s * 2],
    [cx + dirX * s, cy + dirY * s * 4],
    [cx, cy + dirY * s * 4]
  ].map(p => {
    let dp = displaceGridPoint(p[0], p[1]);
    return [dp.x, dp.y];
  });

  brush.noStroke();
  brush.wash(pal.dark, 185);
  drawPoly(pts);
  brush.noWash();

  brush.set("fine_needle", pal.bright, 0.3);
  for (let i = 0; i < pts.length; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

function drawParacasCornerGlyph(cx, cy, rotDeg, pal1, pal2) {
  // Stepped diamond + avian chevron motif in the outer corner of corner cells
  let rOut = 26;
  let rIn = 13;
  let diamondOut = [];
  let diamondIn = [];
  for (let k = 0; k < 4; k++) {
    let a = k * 90;
    let pO = displaceGridPoint(cx + rOut * cos(a), cy + rOut * sin(a));
    let pI = displaceGridPoint(cx + rIn * cos(a), cy + rIn * sin(a));
    diamondOut.push([pO.x, pO.y]);
    diamondIn.push([pI.x, pI.y]);
  }

  brush.noStroke();
  brush.wash(pal1.dark, 210);
  drawPoly(diamondOut);
  brush.wash(pal2.mid, 230);
  drawPoly(diamondIn);
  brush.noWash();

  // Tight stitch hatching inside glyph
  brush.set("fine_needle", pal1.bright, 0.28);
  for (let t = -0.8; t <= 0.8; t += 0.2) {
    let span = (1 - abs(t)) * rOut * 0.85;
    let p0 = displaceGridPoint(cx + t * rOut * 0.85, cy - span);
    let p1 = displaceGridPoint(cx + t * rOut * 0.85, cy + span);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  brush.set("fine_needle", PALETTES.ivory.bright, 0.3);
  for (let k = 0; k < 4; k++) {
    let a = diamondIn[k];
    let b = diamondIn[(k + 1) % 4];
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

// ============================================================================
// 4. OUTER PARACAS TEXTILE EMBROIDERED BORDER FRAME
// ============================================================================

function drawParacasMantleBorder() {
  const m = 58; // border thickness

  // Dark woven border strips around the 4 sides
  brush.noStroke();
  brush.wash("#070b16", 250);
  brush.rect(0, 0, 1200, m, "corner");
  brush.rect(0, 1200 - m, 1200, m, "corner");
  brush.rect(0, m, m, 1200 - 2 * m, "corner");
  brush.rect(1200 - m, m, m, 1200 - 2 * m, "corner");
  brush.noWash();

  // Repeating embroidered geometric registers along Top, Bottom, Left, Right borders
  const nCells = 12;
  const span = 1200 - 2 * m;
  const cellLen = span / nCells;

  for (let i = 0; i < nCells; i++) {
    let p0 = m + i * cellLen;
    // Top border cell
    drawBorderCell(p0, 8, cellLen, m - 14, i, true);
    // Bottom border cell
    drawBorderCell(p0, 1200 - m + 6, cellLen, m - 14, i + 1, true);
    // Left border cell
    drawBorderCell(8, p0, m - 14, cellLen, i + 2, false);
    // Right border cell
    drawBorderCell(1200 - m + 6, p0, m - 14, cellLen, i, false);
  }

  // 4 Corner border square medallions
  drawBorderCornerSquare(8, 8, m - 14, 0);
  drawBorderCornerSquare(1200 - m + 6, 8, m - 14, 1);
  drawBorderCornerSquare(1200 - m + 6, 1200 - m + 6, m - 14, 2);
  drawBorderCornerSquare(8, 1200 - m + 6, m - 14, 3);

  // Double-stitched inner and outer border rules
  const rules = [
    { inset: 6, col: PALETTES.ochre.mid, w: 0.42 },
    { inset: 54, col: PALETTES.madder.mid, w: 0.45 },
    { inset: 58, col: PALETTES.ivory.mid, w: 0.35 }
  ];
  for (let r of rules) {
    let a = r.inset;
    let b = 1200 - r.inset;
    brush.set("stitch", r.col, r.w);
    brush.line(a, a, b, a);
    brush.line(b, a, b, b);
    brush.line(b, b, a, b);
    brush.line(a, b, a, a);
  }
}

function drawBorderCell(x, y, w, h, idx, horizontal) {
  let palMain = PALETTES[COLOR_KEYS[idx % 3]];
  let palSec = PALETTES[COLOR_KEYS[(idx + 1) % 3]];
  let palTer = PALETTES[COLOR_KEYS[(idx + 2) % 3]];

  let pad = 3;
  let bx = x + pad;
  let by = y + pad;
  let bw = w - pad * 2;
  let bh = h - pad * 2;

  // Background block of the register
  brush.noStroke();
  brush.wash(palMain.abyss, 235);
  brush.rect(bx, by, bw, bh, "corner");

  // Diagonal stepped bipartite split (classic Paracas interlocking fret)
  let tri1 = [
    [bx, by],
    [bx + bw * 0.65, by],
    [bx + bw * 0.35, by + bh],
    [bx, by + bh]
  ];
  brush.wash(palMain.dark, 225);
  drawPoly(tri1);

  let cx = bx + bw * 0.5;
  let cy = by + bh * 0.5;
  let rx = bw * 0.24;
  let ry = bh * 0.28;
  let dmd = [
    [cx, cy - ry],
    [cx + rx, cy],
    [cx, cy + ry],
    [cx - rx, cy]
  ];
  brush.wash(palSec.mid, 235);
  drawPoly(dmd);
  brush.noWash();

  // Stitch-hatched texture across the cell
  brush.set("fine_needle", palMain.bright, 0.26);
  if (horizontal) {
    for (let sx = bx + 3; sx < bx + bw - 2; sx += 5.5) {
      brush.line(sx, by + 2, sx, by + bh - 2);
    }
  } else {
    for (let sy = by + 3; sy < by + bh - 2; sy += 5.5) {
      brush.line(bx + 2, sy, bx + bw - 2, sy);
    }
  }

  // Highlighted center eye of the border motif
  brush.set("fine_needle", PALETTES.ivory.bright, 0.32);
  for (let k = 0; k < 4; k++) {
    brush.line(dmd[k][0], dmd[k][1], dmd[(k + 1) % 4][0], dmd[(k + 1) % 4][1]);
  }
  brush.set("stitch", palTer.bright, 0.38);
  brush.line(cx - rx * 0.4, cy, cx + rx * 0.4, cy);
}

function drawBorderCornerSquare(x, y, sz, idx) {
  let pal1 = PALETTES[COLOR_KEYS[idx % 3]];
  let pal2 = PALETTES[COLOR_KEYS[(idx + 1) % 3]];
  brush.noStroke();
  brush.wash(pal1.dark, 235);
  brush.rect(x + 2, y + 2, sz - 4, sz - 4, "corner");
  brush.wash(pal2.mid, 235);
  brush.rect(x + 11, y + 11, sz - 22, sz - 22, "corner");
  brush.noWash();

  brush.set("fine_needle", PALETTES.ivory.bright, 0.32);
  brush.line(x + 4, y + 4, x + sz - 4, y + sz - 4);
  brush.line(x + sz - 4, y + 4, x + 4, y + sz - 4);
}

// ============================================================================
// 5. HYPERREAL SKYDIVER ANATOMY, RIPPLING JUMPSUITS & STITCH-HATCHING ENGINE
// ============================================================================

function drawFigureShadow(fig) {
  // Deep indigo aerodynamic shadow beneath torso, limbs, and head
  brush.noStroke();
  brush.wash("#040710", 170);

  let shadowPts = [
    fig.toWorld(fig.rHead - 18, 0),
    fig.leftElbow,
    fig.leftShoulder,
    fig.leftHip,
    fig.leftKnee,
    fig.leftToe,
    fig.toWorld(fig.rPelvis + 32, 0),
    fig.rightToe,
    fig.rightKnee,
    fig.rightHip,
    fig.rightShoulder,
    fig.rightElbow
  ].map(p => [p.x + 6, p.y + 8]);

  drawPoly(shadowPts);
  brush.noWash();
}

function drawSkydiverBody(fig) {
  let seed = fig.index * 137 + 19;

  // 1. BOOTIES (Aerodynamic shoe covers with fin soles & toe caps)
  drawBootie(fig, fig.leftAnkle, fig.leftToe, -1, fig.palMain, fig.palRig);
  drawBootie(fig, fig.rightAnkle, fig.rightToe, 1, fig.palMain, fig.palRig);

  // 2. LOWER LEGS / CALVES (Rippling jumpsuit legs from knee to ankle + calf grippers)
  let lCalfCtrl = midPtOffset(fig.leftKnee, fig.leftAnkle, fig.vx, -12);
  let rCalfCtrl = midPtOffset(fig.rightKnee, fig.rightAnkle, fig.vx, 12);

  drawSculptedLimb(
    fig.leftKnee, lCalfCtrl, fig.leftAnkle,
    24, 22, 17,
    fig.palSec, fig.palRig, -1, seed + 11, true
  );
  drawSculptedLimb(
    fig.rightKnee, rCalfCtrl, fig.rightAnkle,
    24, 22, 17,
    fig.palSec, fig.palRig, 1, seed + 23, true
  );

  // 3. THIGHS (Rippling jumpsuit thighs from hip to knee + foam thigh grippers)
  let lThighCtrl = midPtOffset(fig.leftHip, fig.leftKnee, fig.vx, -10);
  let rThighCtrl = midPtOffset(fig.rightHip, fig.rightKnee, fig.vx, 10);

  drawSculptedLimb(
    fig.leftHip, lThighCtrl, fig.leftKnee,
    31, 28, 24,
    fig.palMain, fig.palSec, -1, seed + 37, true
  );
  drawSculptedLimb(
    fig.rightHip, rThighCtrl, fig.rightKnee,
    31, 28, 24,
    fig.palMain, fig.palSec, 1, seed + 51, true
  );

  // Articulated knee-pad reinforcement patches
  drawKneePatch(fig.leftKnee, fig.bodyAngle - 18, fig.palMain, fig.palRig);
  drawKneePatch(fig.rightKnee, fig.bodyAngle + 18, fig.palMain, fig.palRig);

  // 4. TORSO JUMPSUIT, SIDE GUSSETS & LEG-STRAP HARNESS WEBBING
  drawTorsoJumpsuit(fig, seed + 71);

  // 5. UPPER ARMS (Shoulders to Elbows + upper arm grippers)
  let lArmCtrl = midPtOffset(fig.leftShoulder, fig.leftElbow, fig.vx, -8);
  let rArmCtrl = midPtOffset(fig.rightShoulder, fig.rightElbow, fig.vx, 8);

  drawSculptedLimb(
    fig.leftShoulder, lArmCtrl, fig.leftElbow,
    22, 21, 18,
    fig.palSec, fig.palMain, -1, seed + 89, true
  );
  drawSculptedLimb(
    fig.rightShoulder, rArmCtrl, fig.rightElbow,
    22, 21, 18,
    fig.palSec, fig.palMain, 1, seed + 103, true
  );

  // 6. DORSAL PARACHUTE CONTAINER (RIG), HARNESS YOKE, 3-RING HARDWARE & BOC POUCH
  drawParachuteRig(fig);

  // 7. UPTURNED HEAD, HELMET & WIND-PINNED GOGGLES
  drawHeadAndGoggles(fig);
}

// ----------------------------------------------------------------------------
// 3D Stitch-Sculpted Limb Engine (Rippling Jumpsuit Fabric + Foam Grippers)
// ----------------------------------------------------------------------------
function drawSculptedLimb(p0, pCtrl, p1, r0, rMid, r1, pal, gripperPal, outerSide, seed, hasGripper) {
  const N = 16;
  let spine = [];
  let leftEdge = [];
  let rightEdge = [];
  let midLeft = [];
  let midRight = [];

  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let x = bezierPt(p0.x, pCtrl.x, p1.x, t);
    let y = bezierPt(p0.y, pCtrl.y, p1.y, t);
    let tx = bezierTan(p0.x, pCtrl.x, p1.x, t);
    let ty = bezierTan(p0.y, pCtrl.y, p1.y, t);
    let tl = hypot(tx, ty) || 1;
    tx /= tl;
    ty /= tl;
    let nx = -ty;
    let ny = tx;

    // Base radius profile
    let baseR = (t < 0.5)
      ? lerp(r0, rMid, t * 2)
      : lerp(rMid, r1, (t - 0.5) * 2);

    // 120mph wind-flutter silhouette ripples
    let flutterL = 1 + 0.13 * sin(t * 540 + seed) + 0.06 * cos(t * 920 - seed * 1.4);
    let flutterR = 1 + 0.13 * cos(t * 500 + seed * 1.3) + 0.06 * sin(t * 860 + seed);
    let wL = baseR * flutterL;
    let wR = baseR * flutterR;

    spine.push({ x, y, tx, ty, nx, ny, wL, wR, baseR, t });
    leftEdge.push([x - nx * wL, y - ny * wL]);
    rightEdge.push([x + nx * wR, y + ny * wR]);
    midLeft.push([x - nx * wL * 0.58, y - ny * wL * 0.58]);
    midRight.push([x + nx * wR * 0.65, y + ny * wR * 0.65]);
  }

  let fullPoly = leftEdge.concat(rightEdge.slice().reverse());
  let corePoly = midLeft.concat(midRight.slice().reverse());

  // 1. Opaque underpainting washes so colours glow on the dark indigo ground
  brush.noStroke();
  brush.wash(pal.abyss, 250);
  drawPoly(fullPoly);
  brush.wash(pal.dark, 235);
  drawPoly(fullPoly);
  brush.wash(pal.mid, 215);
  drawPoly(corePoly);
  brush.noWash();

  // 2. Longitudinal wind-ripple creases & inflated fabric ridges
  const foldOffsets = [-0.62, -0.22, 0.18, 0.56];
  for (let fIdx = 0; fIdx < foldOffsets.length; fIdx++) {
    let uBase = foldOffsets[fIdx];
    let creasePts = [];
    let ridgePts = [];
    for (let i = 0; i <= N; i++) {
      let sp = spine[i];
      let wave = 0.12 * sin(sp.t * 440 + fIdx * 85 + seed);
      let uC = uBase + wave;
      let uR = uBase + wave + 0.12;
      let wC = (uC < 0) ? sp.wL : sp.wR;
      let wR = (uR < 0) ? sp.wL : sp.wR;
      creasePts.push([sp.x + sp.nx * uC * wC, sp.y + sp.ny * uC * wC]);
      ridgePts.push([sp.x + sp.nx * uR * wR, sp.y + sp.ny * uR * wR]);
    }
    brush.set("stitch", pal.abyss, 0.42);
    brush.spline(creasePts, 0.35);
    brush.set("stitch", (fIdx === 1 || fIdx === 2) ? pal.bright : pal.mid, 0.45);
    brush.spline(ridgePts, 0.35);
  }

  // 3. Dense, tight, stitch-like cross-contour hatching across the 3D cylinder
  const stitchRows = 26;
  for (let r = 1; r < stitchRows; r++) {
    let t = r / stitchRows;
    let idxF = t * N;
    let i0 = floor(idxF);
    let i1 = min(N, i0 + 1);
    let frac = idxF - i0;
    let sp0 = spine[i0];
    let sp1 = spine[i1];

    let sx = lerp(sp0.x, sp1.x, frac);
    let sy = lerp(sp0.y, sp1.y, frac);
    let nx = lerp(sp0.nx, sp1.nx, frac);
    let ny = lerp(sp0.ny, sp1.ny, frac);
    let tx = lerp(sp0.tx, sp1.tx, frac);
    let ty = lerp(sp0.ty, sp1.ty, frac);
    let wL = lerp(sp0.wL, sp1.wL, frac);
    let wR = lerp(sp0.wR, sp1.wR, frac);

    // Slight 3D cylindrical curvature arch along the limb axis
    let arch = (wL + wR) * 0.11;
    let rippleMod = sin(t * 520 + seed) * 0.15;

    let ptAt = (u) => {
      let w = (u < 0) ? wL : wR;
      let bulge = (1 - u * u) * arch + sin(u * 260 + t * 360) * 1.6;
      return [
        sx + nx * (u * w) + tx * bulge,
        sy + ny * (u * w) + ty * bulge
      ];
    };

    // 4 overlapping tonal stitch bands across the cylinder width
    let pA = ptAt(-0.96);
    let pB = ptAt(-0.42 + rippleMod * 0.3);
    let pC = ptAt(0.16 + rippleMod * 0.4);
    let pD = ptAt(0.68);
    let pE = ptAt(0.96);

    // Shadow flank stitch
    brush.set("fine_needle", (r % 2 === 0) ? pal.abyss : pal.dark, 0.34);
    brush.line(pA[0], pA[1], pB[0], pB[1]);

    // Core mid-tone stitch
    brush.set("stitch", pal.mid, 0.38);
    brush.line(pB[0], pB[1], pC[0], pC[1]);

    // Lit crest stitch (alternating bright & warm highlight on wind-ripple peaks)
    let isPeak = sin(t * 500 + seed) > 0.25;
    brush.set("fine_needle", isPeak ? pal.highlight : pal.bright, 0.36);
    brush.line(pC[0], pC[1], pD[0], pD[1]);

    // Reflected edge stitch
    brush.set("fine_needle", pal.dark, 0.32);
    brush.line(pD[0], pD[1], pE[0], pE[1]);
  }

  // 4. Cylindrical FS foam gripper sewn along the outer flank of the limb
  if (hasGripper) {
    let gInner = [];
    let gOuter = [];
    for (let i = 2; i <= N - 2; i++) {
      let sp = spine[i];
      let w = (outerSide < 0) ? sp.wL : sp.wR;
      let gxIn = sp.x + sp.nx * outerSide * (w * 0.72);
      let gyIn = sp.y + sp.ny * outerSide * (w * 0.72);
      let gxOut = sp.x + sp.nx * outerSide * (w * 1.12);
      let gyOut = sp.y + sp.ny * outerSide * (w * 1.12);
      gInner.push([gxIn, gyIn]);
      gOuter.push([gxOut, gyOut]);
    }
    let gPoly = gInner.concat(gOuter.slice().reverse());
    brush.noStroke();
    brush.wash(gripperPal.mid, 235);
    drawPoly(gPoly);
    brush.noWash();

    // Ribbed stitch rings along the foam gripper cylinder
    for (let k = 0; k < gInner.length; k++) {
      let a = gInner[k];
      let b = gOuter[k];
      let mx = (a[0] + b[0]) * 0.5;
      let my = (a[1] + b[1]) * 0.5;
      brush.set("fine_needle", gripperPal.abyss, 0.32);
      brush.line(a[0], a[1], mx, my);
      brush.set("fine_needle", (k % 2 === 0) ? gripperPal.highlight : PALETTES.ivory.bright, 0.34);
      brush.line(mx, my, b[0], b[1]);
    }
    brush.set("fine_needle", gripperPal.abyss, 0.34);
    brush.spline(gInner, 0.3);
    brush.spline(gOuter, 0.3);
  }

  // Crisp stitched contour seam around the limb
  brush.set("fine_needle", pal.abyss, 0.34);
  brush.spline(leftEdge, 0.25);
  brush.spline(rightEdge, 0.25);
}

function drawBootie(fig, ankle, toe, sideSign, palBoot, palTrim) {
  let dx = toe.x - ankle.x;
  let dy = toe.y - ankle.y;
  let len = hypot(dx, dy) || 1;
  let tx = dx / len;
  let ty = dy / len;
  let nx = -ty * sideSign;
  let ny = tx * sideSign;

  // Aerodynamic wedge bootie shape
  let pts = [
    [ankle.x - nx * 13, ankle.y - ny * 13],
    [ankle.x + tx * len * 0.55 - nx * 11, ankle.y + ty * len * 0.55 - ny * 11],
    [toe.x + tx * 6, toe.y + ty * 6],
    [ankle.x + tx * len * 0.65 + nx * 16, ankle.y + ty * len * 0.65 + ny * 16],
    [ankle.x - tx * 6 + nx * 15, ankle.y - ty * 6 + ny * 15]
  ];

  brush.noStroke();
  brush.wash(PALETTES.charcoal.abyss, 245);
  drawPoly(pts);
  brush.wash(palBoot.dark, 225);
  drawPoly(pts.slice(0, 4));
  brush.noWash();

  // Stitched sole ribs & aerodynamic fin edge
  for (let i = 0; i <= 7; i++) {
    let t = i / 7;
    let sx = lerp(ankle.x, toe.x, t);
    let sy = lerp(ankle.y, toe.y, t);
    let w = lerp(13, 4, t);
    brush.set("fine_needle", (i % 2 === 0) ? palBoot.bright : palTrim.highlight, 0.32);
    brush.line(sx - nx * w * 0.8, sy - ny * w * 0.8, sx + nx * w, sy + ny * w);
  }

  // Ankle cuff strap
  brush.set("stitch", PALETTES.ivory.bright, 0.42);
  brush.line(ankle.x - nx * 14, ankle.y - ny * 14, ankle.x + nx * 14, ankle.y + ny * 14);
}

function drawKneePatch(knee, angDeg, palMain, palAccent) {
  let ca = cos(angDeg);
  let sa = sin(angDeg);
  let nx = -sa;
  let ny = ca;
  let rx = 16;
  let ry = 13;
  let pts = [];
  for (let a = 0; a < 360; a += 45) {
    pts.push([
      knee.x + ca * rx * cos(a) + nx * ry * sin(a),
      knee.y + sa * rx * cos(a) + ny * ry * sin(a)
    ]);
  }
  brush.noStroke();
  brush.wash(palAccent.dark, 225);
  drawPoly(pts);
  brush.noWash();

  // Cordura cross-stitching on knee pad
  for (let t = -0.7; t <= 0.7; t += 0.35) {
    brush.set("fine_needle", palAccent.bright, 0.28);
    brush.line(
      knee.x + ca * t * rx - nx * ry * 0.7,
      knee.y + sa * t * rx - ny * ry * 0.7,
      knee.x + ca * t * rx + nx * ry * 0.7,
      knee.y + sa * t * rx + ny * ry * 0.7
    );
  }
}

// ----------------------------------------------------------------------------
// Torso Jumpsuit, Wind Folds & Leg-Strap Harness Webbing
// ----------------------------------------------------------------------------
function drawTorsoJumpsuit(fig, seed) {
  let palM = fig.palMain;
  let palS = fig.palSec;

  // Build contoured torso polygon from shoulders through waist to pelvis
  let N = 14;
  let leftFlank = [];
  let rightFlank = [];
  let gussetL = [];
  let gussetR = [];

  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let r = lerp(fig.rShoulder - 4, fig.rPelvis + 10, t);
    // Hourglass taper at waist (t ~ 0.55) + wind inflation
    let baseW = lerp(50, 40, sin(t * 140)) + (1 - t) * 7;
    let wL = baseW * (1 + 0.08 * sin(t * 480 + seed));
    let wR = baseW * (1 + 0.08 * cos(t * 480 + seed));
    let sway = sin(t * 180) * 3;

    let pL = fig.toWorld(r, -wL + sway);
    let pR = fig.toWorld(r, wR + sway);
    let gL = fig.toWorld(r, -wL * 0.72 + sway);
    let gR = fig.toWorld(r, wR * 0.72 + sway);

    leftFlank.push([pL.x, pL.y]);
    rightFlank.push([pR.x, pR.y]);
    gussetL.push([gL.x, gL.y]);
    gussetR.push([gR.x, gR.y]);
  }

  let torsoPoly = leftFlank.concat(rightFlank.slice().reverse());
  let centerPoly = gussetL.concat(gussetR.slice().reverse());

  // Base washes: secondary textile colour on the side expansion gussets, primary colour on core
  brush.noStroke();
  brush.wash(palS.dark, 240);
  drawPoly(torsoPoly);
  brush.wash(palM.dark, 240);
  drawPoly(centerPoly);
  brush.wash(palM.mid, 215);
  drawPoly(centerPoly);
  brush.noWash();

  // Dense stitch-hatching radiating from under the rig across the torso & hips
  for (let i = 1; i < N; i++) {
    let t = i / N;
    let r = lerp(fig.rShoulder, fig.rPelvis + 6, t);
    let w = lerp(49, 41, t);
    for (let s = -4; s <= 4; s++) {
      let u0 = s / 4.5;
      let u1 = (s + 0.85) / 4.5;
      let isGusset = abs(u0) > 0.65;
      let pal = isGusset ? palS : palM;
      let ripple = sin(u0 * 320 + t * 500 + seed);
      let col = (ripple > 0.35) ? pal.highlight : (ripple > -0.2 ? pal.bright : pal.dark);

      let p0 = fig.toWorld(r + ripple * 2.5, u0 * w);
      let p1 = fig.toWorld(r - abs(u0) * 6 + ripple * 2.5, u1 * w);
      brush.set("fine_needle", col, 0.34);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Heavy-duty Parachute Leg-Strap Webbing wrapping from lower rig around both upper thighs
  drawHarnessStrap(
    fig.toWorld(fig.rPelvis - 18, -14),
    fig.toWorld(fig.rPelvis + 14, -42),
    10, PALETTES.charcoal, PALETTES.ivory.bright
  );
  drawHarnessStrap(
    fig.toWorld(fig.rPelvis - 18, 14),
    fig.toWorld(fig.rPelvis + 14, 42),
    10, PALETTES.charcoal, PALETTES.ivory.bright
  );
}

function drawHarnessStrap(p0, p1, widthPx, strapPal, stitchCol) {
  let dx = p1.x - p0.x;
  let dy = p1.y - p0.y;
  let len = hypot(dx, dy) || 1;
  let tx = dx / len;
  let ty = dy / len;
  let nx = -ty;
  let ny = tx;
  let hw = widthPx * 0.5;

  let poly = [
    [p0.x - nx * hw, p0.y - ny * hw],
    [p1.x - nx * hw, p1.y - ny * hw],
    [p1.x + nx * hw, p1.y + ny * hw],
    [p0.x + nx * hw, p0.y + ny * hw]
  ];

  brush.noStroke();
  brush.wash(strapPal.abyss, 245);
  drawPoly(poly);
  brush.noWash();

  // Edge piping & box-X reinforcement stitches
  brush.set("fine_needle", stitchCol, 0.28);
  brush.line(poly[0][0], poly[0][1], poly[1][0], poly[1][1]);
  brush.line(poly[3][0], poly[3][1], poly[2][0], poly[2][1]);

  let steps = max(3, floor(len / 5.5));
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let mx = lerp(p0.x, p1.x, t);
    let my = lerp(p0.y, p1.y, t);
    brush.set("fine_needle", (i % 2 === 0) ? strapPal.bright : stitchCol, 0.26);
    brush.line(mx - nx * hw * 0.75, my - ny * hw * 0.75, mx + nx * hw * 0.75, my + ny * hw * 0.75);
  }
}

// ----------------------------------------------------------------------------
// Dorsal Parachute Container (Rig), 4 Flaps, Closing Pin, BOC & 3-Ring Release
// ----------------------------------------------------------------------------
function drawParachuteRig(fig) {
  let palR = fig.palRig;
  let palM = fig.palMain;
  let palS = fig.palSec;

  let rTop = fig.rShoulder + 8;
  let rBot = fig.rPelvis - 8;
  let rMid = (rTop + rBot) * 0.5;
  let hwTop = 28;
  let hwBot = 31;

  // 1. Shoulder harness risers extending from top of rig over the shoulders
  drawHarnessStrap(
    fig.toWorld(rTop + 4, -20),
    fig.toWorld(fig.rShoulder - 10, -28),
    11, PALETTES.charcoal, palR.highlight
  );
  drawHarnessStrap(
    fig.toWorld(rTop + 4, 20),
    fig.toWorld(fig.rShoulder - 10, 28),
    11, PALETTES.charcoal, palR.highlight
  );

  // 3-Ring Release hardware on both shoulders (3 nested metallic rings + cutaway loop)
  drawThreeRingHardware(fig.toWorld(fig.rShoulder - 2, -24), fig.ux, fig.uy);
  drawThreeRingHardware(fig.toWorld(fig.rShoulder - 2, 24), fig.ux, fig.uy);

  // 2. Rig drop shadow on torso
  let cTL = fig.toWorld(rTop, -hwTop);
  let cTR = fig.toWorld(rTop, hwTop);
  let cBR = fig.toWorld(rBot, hwBot);
  let cBL = fig.toWorld(rBot, -hwBot);
  let rigBox = [[cTL.x, cTL.y], [cTR.x, cTR.y], [cBR.x, cBR.y], [cBL.x, cBL.y]];

  brush.noStroke();
  brush.wash("#050811", 210);
  drawPoly(rigBox.map(p => [p[0] + 4, p[1] + 5]));

  // 3. Base container body in the 3rd rotating textile colour
  brush.wash(palR.abyss, 250);
  drawPoly(rigBox);
  brush.wash(palR.dark, 235);
  drawPoly(rigBox);

  // 4. Four overlapping container closing flaps (Top Reserve, Bottom Main, Left & Right Flaps)
  let center = fig.toWorld(rMid + 4, 0);
  let topFlap = [
    [cTL.x, cTL.y],
    [cTR.x, cTR.y],
    [fig.toWorld(rMid - 2, 16).x, fig.toWorld(rMid - 2, 16).y],
    [center.x, center.y],
    [fig.toWorld(rMid - 2, -16).x, fig.toWorld(rMid - 2, -16).y]
  ];
  let botFlap = [
    [cBL.x, cBL.y],
    [cBR.x, cBR.y],
    [fig.toWorld(rMid + 12, 18).x, fig.toWorld(rMid + 12, 18).y],
    [center.x, center.y],
    [fig.toWorld(rMid + 12, -18).x, fig.toWorld(rMid + 12, -18).y]
  ];

  brush.wash(palR.mid, 230);
  drawPoly(topFlap);
  brush.wash(palM.dark, 215);
  drawPoly(botFlap);
  brush.noWash();

  // Directional stitch-hatching across the 4 flaps (orthogonal textile weave rhythm)
  for (let r = rTop + 4; r <= rBot - 4; r += 4.5) {
    let isUpper = r < rMid;
    let pL = fig.toWorld(r, -hwTop + 3);
    let pM1 = fig.toWorld(r, -12);
    let pM2 = fig.toWorld(r, 12);
    let pR = fig.toWorld(r, hwTop - 3);

    // Side flaps (diagonal/transverse stitches)
    brush.set("fine_needle", palR.bright, 0.32);
    brush.line(pL.x, pL.y, pM1.x, pM1.y);
    brush.set("fine_needle", palR.dark, 0.32);
    brush.line(pM2.x, pM2.y, pR.x, pR.y);

    // Center reserve/main flaps (contrasting Paracas stitch band)
    brush.set("stitch", isUpper ? palR.highlight : palM.bright, 0.34);
    brush.line(pM1.x, pM1.y, pM2.x, pM2.y);
  }

  // Crisp flap bevel seams & Cordura piping
  brush.set("fine_needle", PALETTES.charcoal.abyss, 0.42);
  drawClosedStroke(rigBox);
  drawClosedStroke(topFlap);
  drawClosedStroke(botFlap);

  brush.set("fine_needle", PALETTES.ivory.bright, 0.3);
  brush.line(cTL.x, cTL.y, center.x, center.y);
  brush.line(cTR.x, cTR.y, center.x, center.y);
  brush.line(cBL.x, cBL.y, center.x, center.y);
  brush.line(cBR.x, cBR.y, center.x, center.y);

  // 5. Center Pin-Protector Flap & Curved Stainless-Steel Closing Pin
  let pinFlap = [
    fig.toWorld(rMid - 10, -9),
    fig.toWorld(rMid - 10, 9),
    fig.toWorld(rMid + 14, 7),
    fig.toWorld(rMid + 14, -7)
  ].map(p => [p.x, p.y]);
  brush.noStroke();
  brush.wash(palS.mid, 240);
  drawPoly(pinFlap);
  brush.noWash();
  brush.set("fine_needle", PALETTES.ivory.highlight, 0.35);
  drawClosedStroke(pinFlap);
  // Metallic closing pin glint
  let pinPt = fig.toWorld(rMid + 2, 0);
  brush.set("fine_needle", "#ffffff", 0.45);
  brush.arc(pinPt.x, pinPt.y, 4.5, 0, 240);

  // 6. BOC (Bottom-of-Container) Pilot Chute Spandex Pouch & Leather Hackey Handle
  let bocL = fig.toWorld(rBot + 1, -hwBot + 2);
  let bocR = fig.toWorld(rBot + 1, hwBot - 2);
  let bocBL = fig.toWorld(rBot + 13, -hwBot + 5);
  let bocBR = fig.toWorld(rBot + 13, hwBot - 5);
  let bocPoly = [[bocL.x, bocL.y], [bocR.x, bocR.y], [bocBR.x, bocBR.y], [bocBL.x, bocBL.y]];

  brush.noStroke();
  brush.wash(PALETTES.charcoal.abyss, 250);
  drawPoly(bocPoly);
  brush.noWash();
  brush.set("fine_needle", PALETTES.charcoal.bright, 0.28);
  for (let k = 0; k <= 8; k++) {
    let t = k / 8;
    brush.line(
      lerp(bocL.x, bocR.x, t), lerp(bocL.y, bocR.y, t),
      lerp(bocBL.x, bocBR.x, t), lerp(bocBL.y, bocBR.y, t)
    );
  }

  // Protruding Hackey deployment handle on the right side of the BOC
  let hackey = fig.toWorld(rBot + 8, hwBot + 9);
  brush.noStroke();
  brush.wash(PALETTES.madder.bright, 245);
  brush.circle(hackey.x, hackey.y, 7.5, 0.1);
  brush.wash(PALETTES.ochre.highlight, 220);
  brush.circle(hackey.x - 1.5, hackey.y - 1.5, 4, 0.1);
  brush.noWash();
  brush.set("fine_needle", PALETTES.charcoal.abyss, 0.35);
  brush.circle(hackey.x, hackey.y, 7.5, 0.08);
}

function drawThreeRingHardware(pt, ux, uy) {
  // Three concentric interlocking rings stepping toward the center
  const radii = [4.6, 3.3, 2.2];
  for (let k = 0; k < 3; k++) {
    let rx = pt.x - ux * (k * 4.5);
    let ry = pt.y - uy * (k * 4.5);
    brush.set("fine_needle", PALETTES.ivory.highlight, 0.36);
    brush.circle(rx, ry, radii[k], 0.05);
  }
  // Yellow cutaway cable housing tick
  brush.set("fine_needle", PALETTES.ochre.highlight, 0.34);
  brush.line(pt.x - ux * 10, pt.y - uy * 10, pt.x + ux * 4, pt.y + uy * 4);
}

// ----------------------------------------------------------------------------
// Upturned Head, Helmet & Wind-Pinned Goggles
// ----------------------------------------------------------------------------
function drawHeadAndGoggles(fig) {
  let hc = fig.head;
  // Unit vector pointing INWARD toward the star center (the direction the skydiver's face looks)
  let fx = -fig.ux;
  let fy = -fig.uy;
  let lx = fig.vx; // lateral vector across the face/goggles
  let ly = fig.vy;

  // 1. Neck buff / collar folds between shoulders and helmet
  let collarPts = [];
  for (let a = -70; a <= 70; a += 20) {
    let rC = 22;
    collarPts.push([
      hc.x - fx * 12 + (-fx * cos(a) + lx * sin(a)) * rC,
      hc.y - fy * 12 + (-fy * cos(a) + ly * sin(a)) * rC
    ]);
  }
  brush.set("stitch", fig.palSec.dark, 0.55);
  brush.spline(collarPts, 0.35);
  brush.set("fine_needle", fig.palSec.bright, 0.35);
  brush.spline(collarPts, 0.35);

  // 2. Upturned Face (Forehead, Nose Bridge & Wind-Pinned Cheeks facing the center)
  let faceCenter = { x: hc.x + fx * 11, y: hc.y + fy * 11 };
  let facePoly = [];
  for (let a = -95; a <= 95; a += 19) {
    let rx = 16;
    let ry = 21;
    let px = faceCenter.x + fx * rx * cos(a) + lx * ry * sin(a);
    let py = faceCenter.y + fy * rx * cos(a) + ly * ry * sin(a);
    facePoly.push([px, py]);
  }
  brush.noStroke();
  brush.wash(PALETTES.terracotta.dark, 245);
  drawPoly(facePoly);
  brush.wash(PALETTES.terracotta.mid, 230);
  drawPoly(facePoly);
  brush.noWash();

  // Sculpted nose tip & cheek stitch-hatching
  for (let s = -4; s <= 4; s++) {
    let lat = s * 4.2;
    let p0 = { x: faceCenter.x + fx * 4 + lx * lat, y: faceCenter.y + fy * 4 + ly * lat };
    let p1 = { x: faceCenter.x + fx * (15 - abs(s) * 1.8) + lx * lat * 0.85, y: faceCenter.y + fy * (15 - abs(s) * 1.8) + ly * lat * 0.85 };
    brush.set("fine_needle", (abs(s) <= 1) ? PALETTES.terracotta.highlight : PALETTES.terracotta.bright, 0.32);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }
  // Nose bridge highlight
  brush.set("fine_needle", PALETTES.ivory.highlight, 0.36);
  brush.line(faceCenter.x + fx * 8, faceCenter.y + fy * 8, faceCenter.x + fx * 16, faceCenter.y + fy * 16);

  // 3. Open-Face Composite Helmet Dome (covering crown and back of head)
  let helmCenter = { x: hc.x - fx * 3, y: hc.y - fy * 3 };
  let helmPoly = [];
  for (let a = 0; a < 360; a += 20) {
    // Slightly flattened along the front brow rim so the face & goggles emerge cleanly
    let rFront = (cos(a) > 0.25) ? 18 : 26;
    let rSide = 25;
    let px = helmCenter.x + fx * rFront * cos(a) + lx * rSide * sin(a);
    let py = helmCenter.y + fy * rFront * cos(a) + ly * rSide * sin(a);
    helmPoly.push([px, py]);
  }

  brush.noStroke();
  brush.wash(fig.palMain.abyss, 250);
  drawPoly(helmPoly);
  brush.wash(fig.palMain.dark, 235);
  drawPoly(helmPoly);
  brush.noWash();

  // Spherical stitch-hatching on the helmet dome + central Paracas racing stripe
  for (let ring = 1; ring <= 6; ring++) {
    let frac = ring / 6.5;
    let rF = 16 * frac;
    let rS = 23 * frac;
    for (let a = -155; a <= 155; a += 22) {
      let a0 = a;
      let a1 = a + 16;
      let p0 = {
        x: helmCenter.x - fx * 3 + fx * rF * cos(a0) + lx * rS * sin(a0),
        y: helmCenter.y - fy * 3 + fy * rF * cos(a0) + ly * rS * sin(a0)
      };
      let p1 = {
        x: helmCenter.x - fx * 3 + fx * rF * cos(a1) + lx * rS * sin(a1),
        y: helmCenter.y - fy * 3 + fy * rF * cos(a1) + ly * rS * sin(a1)
      };
      let isStripe = abs(sin(a0)) < 0.24 && cos(a0) < 0;
      let col = isStripe
        ? PALETTES.ivory.bright
        : (cos(a0 - 45) > 0.2 ? fig.palMain.bright : fig.palMain.mid);
      brush.set("fine_needle", col, 0.34);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // 4. Wide Elastic Goggle Strap Pinned Around the Helmet
  let strapPts = [];
  for (let a = 75; a <= 285; a += 25) {
    strapPts.push([
      helmCenter.x + fx * 19 * cos(a) + lx * 26 * sin(a),
      helmCenter.y + fy * 19 * cos(a) + ly * 26 * sin(a)
    ]);
  }
  brush.set("stitch", PALETTES.charcoal.abyss, 0.85);
  brush.spline(strapPts, 0.35);
  brush.set("fine_needle", PALETTES.ochre.bright, 0.34);
  brush.spline(strapPts, 0.35);

  // 5. WIND-PINNED POLYCARBONATE GOGGLES (Dual Lenses + Frame Gasket + Specular Sky Glints)
  for (let side of [-1, 1]) {
    let lensC = {
      x: faceCenter.x + fx * 6 + lx * side * 11.5,
      y: faceCenter.y + fy * 6 + ly * side * 11.5
    };
    // Curved wrap-around lens polygon
    let lPoly = [
      [lensC.x - fx * 5 - lx * side * 8.5, lensC.y - fy * 5 - ly * side * 8.5],
      [lensC.x + fx * 6.5 - lx * side * 7.5, lensC.y + fy * 6.5 - ly * side * 7.5],
      [lensC.x + fx * 5.5 + lx * side * 9.5, lensC.y + fy * 5.5 + ly * side * 9.5],
      [lensC.x - fx * 4.5 + lx * side * 10.5, lensC.y - fy * 4.5 + ly * side * 10.5]
    ];

    // Dark tinted polycarbonate interior
    brush.noStroke();
    brush.wash("#0d182e", 245);
    drawPoly(lPoly);
    brush.noWash();

    // Subtle focused eye visible through the goggle lens
    let eyePt = { x: lensC.x + fx * 1.2 - lx * side * 1.0, y: lensC.y + fy * 1.2 - ly * side * 1.0 };
    brush.set("fine_needle", PALETTES.ivory.mid, 0.32);
    brush.line(eyePt.x - lx * 3, eyePt.y - ly * 3, eyePt.x + lx * 3, eyePt.y + ly * 3);
    brush.set("fine_needle", "#05070d", 0.45);
    brush.circle(eyePt.x, eyePt.y, 1.6, 0.02);

    // Bright curved sky & jumpsuit reflection glints across the convex lens
    brush.set("fine_needle", PALETTES.ivory.highlight, 0.38);
    brush.line(
      lensC.x + fx * 3.5 - lx * side * 5.5,
      lensC.y + fy * 3.5 - ly * side * 5.5,
      lensC.x + fx * 2.5 + lx * side * 5.5,
      lensC.y + fy * 2.5 + ly * side * 5.5
    );
    brush.set("fine_needle", fig.palSec.highlight, 0.32);
    brush.line(
      lensC.x - fx * 1.5 - lx * side * 4.5,
      lensC.y - fy * 1.5 - ly * side * 4.5,
      lensC.x - fx * 2.0 + lx * side * 4.5,
      lensC.y - fy * 2.0 + ly * side * 4.5
    );

    // Translucent vinyl goggle frame gasket pinned back by the wind
    brush.set("stitch", PALETTES.ivory.bright, 0.42);
    drawClosedStroke(lPoly);
    brush.set("fine_needle", PALETTES.charcoal.abyss, 0.32);
    drawClosedStroke(lPoly);
  }

  // Center goggle nose-bridge strap
  brush.set("stitch", PALETTES.ivory.highlight, 0.45);
  brush.line(
    faceCenter.x + fx * 7 - lx * 3.5,
    faceCenter.y + fy * 7 - ly * 3.5,
    faceCenter.x + fx * 7 + lx * 3.5,
    faceCenter.y + fy * 7 + ly * 3.5
  );
}

// ============================================================================
// 6. FOREARMS, WRIST ALTIMETERS & STRAINING INTERLOCKED HANDS
// ============================================================================

function drawAllForearmsAndLinkedHands() {
  // Pass 1: Draw all 16 forearms (Left & Right for each of the 8 skydivers)
  for (let i = 0; i < 8; i++) {
    let fig = skydivers[i];
    let seed = i * 97 + 31;

    // Left forearm: leftElbow -> leftGrip (gripPoints[i])
    let lWrist = pointAlong(fig.leftElbow, fig.leftGrip, 0.88);
    let lCtrl = midPtOffset(fig.leftElbow, lWrist, fig.vx, -6);
    drawSculptedLimb(
      fig.leftElbow, lCtrl, lWrist,
      17.5, 15.5, 11.5,
      fig.palMain, fig.palRig, -1, seed + 5, true
    );

    // Right forearm: rightElbow -> rightGrip (gripPoints[(i+1)%8])
    let rWrist = pointAlong(fig.rightElbow, fig.rightGrip, 0.88);
    let rCtrl = midPtOffset(fig.rightElbow, rWrist, fig.vx, 6);
    drawSculptedLimb(
      fig.rightElbow, rCtrl, rWrist,
      17.5, 15.5, 11.5,
      fig.palMain, fig.palRig, 1, seed + 17, true
    );
  }

  // Pass 2: Draw the 8 barometric wrist altimeters on every skydiver's LEFT wrist
  for (let i = 0; i < 8; i++) {
    let fig = skydivers[i];
    let lWrist = pointAlong(fig.leftElbow, fig.leftGrip, 0.78);
    drawWristAltimeter(fig.leftElbow, lWrist, fig.palRig);
  }

  // Pass 3: Draw the 16 straining hands & 80 articulated fingers interlocking at the 8 grip points
  for (let k = 0; k < 8; k++) {
    let figLeftOwner = skydivers[k];               // owns Left Hand at gripPoints[k]
    let figRightOwner = skydivers[(k + 7) % 8];    // owns Right Hand at gripPoints[k]
    let gp = gripPoints[k];

    // Partner wrist targets so each hand genuinely wraps around the neighbor's wrist/forearm
    let rightPartnerWrist = pointAlong(figRightOwner.rightElbow, gp, 0.85);
    let leftPartnerWrist = pointAlong(figLeftOwner.leftElbow, gp, 0.85);

    // Left hand of skydiver k reaching across gp to grasp skydiver (k-1)'s right wrist
    let lHandBase = pointAlong(figLeftOwner.leftElbow, gp, 0.86);
    drawStrainingHand(
      lHandBase, rightPartnerWrist,
      figRightOwner.rightElbow,
      -1, figLeftOwner.palSec
    );

    // Right hand of skydiver (k-1) reaching over gp to grasp skydiver k's left wrist
    let rHandBase = pointAlong(figRightOwner.rightElbow, gp, 0.86);
    drawStrainingHand(
      rHandBase, leftPartnerWrist,
      figLeftOwner.leftElbow,
      1, figRightOwner.palSec
    );
  }
}

function drawWristAltimeter(elbowPt, wristPt, accentPal) {
  let dx = wristPt.x - elbowPt.x;
  let dy = wristPt.y - elbowPt.y;
  let len = hypot(dx, dy) || 1;
  let tx = dx / len;
  let ty = dy / len;
  let nx = -ty;
  let ny = tx;

  // Wide black Velcro altimeter wrist strap
  let strapW = 14;
  let strapHalfL = 7;
  let sPoly = [
    [wristPt.x - tx * strapHalfL - nx * strapW, wristPt.y - ty * strapHalfL - ny * strapW],
    [wristPt.x + tx * strapHalfL - nx * strapW, wristPt.y + ty * strapHalfL - ny * strapW],
    [wristPt.x + tx * strapHalfL + nx * strapW, wristPt.y + ty * strapHalfL + ny * strapW],
    [wristPt.x - tx * strapHalfL + nx * strapW, wristPt.y - ty * strapHalfL + ny * strapW]
  ];
  brush.noStroke();
  brush.wash(PALETTES.charcoal.abyss, 250);
  drawPoly(sPoly);
  brush.noWash();

  // Stitched edges of the Velcro strap
  brush.set("fine_needle", PALETTES.charcoal.bright, 0.28);
  drawClosedStroke(sPoly);

  // Barometric Altimeter Casing & Luminous Dial Face
  let dialX = wristPt.x + nx * 1.5;
  let dialY = wristPt.y + ny * 1.5;
  let rCase = 11.5;
  let rDial = 8.8;

  brush.noStroke();
  brush.wash(PALETTES.charcoal.dark, 255);
  brush.circle(dialX, dialY, rCase, 0.04);
  brush.wash(PALETTES.ivory.highlight, 250);
  brush.circle(dialX, dialY, rDial, 0.03);
  brush.noWash();

  // Red break-off danger arc on the altimeter face
  brush.set("fine_needle", PALETTES.madder.bright, 0.38);
  brush.arc(dialX, dialY, rDial * 0.78, -60, 35);

  // 12 radial altitude graduation ticks around the dial perimeter
  brush.set("fine_needle", PALETTES.charcoal.abyss, 0.26);
  for (let a = 0; a < 360; a += 30) {
    brush.line(
      dialX + cos(a) * (rDial * 0.68),
      dialY + sin(a) * (rDial * 0.68),
      dialX + cos(a) * (rDial * 0.94),
      dialY + sin(a) * (rDial * 0.94)
    );
  }

  // Crisp altimeter indicator needle pointing to ~9,500 ft + glass bevel glint
  let needleAng = 145;
  brush.set("fine_needle", "#06080d", 0.38);
  brush.line(
    dialX - cos(needleAng) * 2.5,
    dialY - sin(needleAng) * 2.5,
    dialX + cos(needleAng) * (rDial * 0.82),
    dialY + sin(needleAng) * (rDial * 0.82)
  );
  brush.set("fine_needle", PALETTES.madder.mid, 0.35);
  brush.circle(dialX, dialY, 1.5, 0.02);

  // Metallic bezel rim
  brush.set("fine_needle", accentPal.highlight, 0.34);
  brush.circle(dialX, dialY, rCase, 0.04);
}

function drawStrainingHand(wristBase, targetGrip, partnerElbow, handSign, cuffPal) {
  let dx = targetGrip.x - wristBase.x;
  let dy = targetGrip.y - wristBase.y;
  let distGrip = hypot(dx, dy) || 1;
  let tx = dx / distGrip;
  let ty = dy / distGrip;
  let nx = -ty;
  let ny = tx;

  let palmLen = 15;
  let palmW = 9.5;
  let knucklesCenter = {
    x: wristBase.x + tx * palmLen,
    y: wristBase.y + ty * palmLen
  };

  // 1. Elastic glove cuff at wristBase
  brush.set("stitch", cuffPal.highlight, 0.55);
  brush.line(
    wristBase.x - nx * palmW, wristBase.y - ny * palmW,
    wristBase.x + nx * palmW, wristBase.y + ny * palmW
  );

  // 2. Dorsal hand / metacarpal palm with straining tendon ridges
  let palmPoly = [
    [wristBase.x - nx * (palmW * 0.88), wristBase.y - ny * (palmW * 0.88)],
    [knucklesCenter.x - nx * (palmW * 1.08), knucklesCenter.y - ny * (palmW * 1.08)],
    [knucklesCenter.x + tx * 3 + nx * (palmW * 1.08), knucklesCenter.y + ty * 3 + ny * (palmW * 1.08)],
    [wristBase.x + nx * (palmW * 0.88), wristBase.y + ny * (palmW * 0.88)]
  ];

  brush.noStroke();
  brush.wash(PALETTES.terracotta.abyss, 245);
  drawPoly(palmPoly);
  brush.wash(PALETTES.terracotta.mid, 235);
  drawPoly(palmPoly);
  brush.noWash();

  // 3. Articulated Thumb hooking around the partner's wrist
  let thumbSide = -handSign;
  let tBase = {
    x: wristBase.x + tx * 5 + nx * thumbSide * (palmW * 0.85),
    y: wristBase.y + ty * 5 + ny * thumbSide * (palmW * 0.85)
  };
  let tMid = {
    x: tBase.x + tx * 8 + nx * thumbSide * 6.5,
    y: tBase.y + ty * 8 + ny * thumbSide * 6.5
  };
  let tTip = {
    x: tMid.x + tx * 7 + nx * thumbSide * 1.5,
    y: tMid.y + ty * 7 + ny * thumbSide * 1.5
  };
  drawArticulatedFinger(tBase, tMid, tTip, 3.6);

  // 4. Four individual straining fingers (Index, Middle, Ring, Pinky) splayed & gripping
  const fingerSpecs = [
    { u: -0.78, len1: 8.5, len2: 7.0, splay: -0.26, w: 3.1 },
    { u: -0.26, len1: 9.8, len2: 8.0, splay: -0.08, w: 3.3 },
    { u:  0.26, len1: 9.2, len2: 7.5, splay:  0.10, w: 3.2 },
    { u:  0.78, len1: 7.5, len2: 6.0, splay:  0.28, w: 2.8 }
  ];

  for (let f of fingerSpecs) {
    let kPt = {
      x: knucklesCenter.x + nx * (f.u * palmW),
      y: knucklesCenter.y + ty * (1 - abs(f.u) * 2) + ny * (f.u * palmW)
    };
    // Dorsal tendon line running from wrist to knuckle
    let wPt = {
      x: wristBase.x + nx * (f.u * palmW * 0.7),
      y: wristBase.y + ny * (f.u * palmW * 0.7)
    };
    brush.set("fine_needle", PALETTES.terracotta.highlight, 0.3);
    brush.line(wPt.x, wPt.y, kPt.x, kPt.y);

    // Proximal and distal finger joints curving around partner's forearm cylinder
    let fDirX = tx + nx * f.splay;
    let fDirY = ty + ny * f.splay;
    let fl = hypot(fDirX, fDirY) || 1;
    fDirX /= fl;
    fDirY /= fl;

    let pipPt = {
      x: kPt.x + fDirX * f.len1,
      y: kPt.y + fDirY * f.len1
    };
    // Tip hooks slightly inward onto the partner's wrist fabric
    let tipPt = {
      x: pipPt.x + fDirX * f.len2 - nx * f.splay * 4.5,
      y: pipPt.y + fDirY * f.len2 - ny * f.splay * 4.5
    };

    drawArticulatedFinger(kPt, pipPt, tipPt, f.w);
  }
}

function drawArticulatedFinger(pKnuckle, pMid, pTip, widthPx) {
  let hw = widthPx * 0.5;
  let dx = pTip.x - pKnuckle.x;
  let dy = pTip.y - pKnuckle.y;
  let l = hypot(dx, dy) || 1;
  let nx = -dy / l;
  let ny = dx / l;

  let poly = [
    [pKnuckle.x - nx * hw, pKnuckle.y - ny * hw],
    [pMid.x - nx * hw * 0.92, pMid.y - ny * hw * 0.92],
    [pTip.x - nx * hw * 0.65, pTip.y - ny * hw * 0.65],
    [pTip.x + nx * hw * 0.65, pTip.y + ny * hw * 0.65],
    [pMid.x + nx * hw * 0.92, pMid.y + ny * hw * 0.92],
    [pKnuckle.x + nx * hw, pKnuckle.y + ny * hw]
  ];

  brush.noStroke();
  brush.wash(PALETTES.terracotta.dark, 250);
  drawPoly(poly);
  brush.noWash();

  // Dark separation outline between straining fingers
  brush.set("fine_needle", PALETTES.terracotta.abyss, 0.3);
  drawClosedStroke(poly);

  // Lit dorsal phalanges & knuckle crease stitches
  brush.set("fine_needle", PALETTES.terracotta.highlight, 0.34);
  brush.line(pKnuckle.x, pKnuckle.y, pMid.x, pMid.y);
  brush.set("fine_needle", PALETTES.ochre.highlight, 0.3);
  brush.line(pMid.x, pMid.y, pTip.x, pTip.y);

  // Knuckle highlight & fingernail glint at tip
  brush.set("fine_needle", PALETTES.ivory.highlight, 0.34);
  brush.line(pKnuckle.x - nx * hw * 0.6, pKnuckle.y - ny * hw * 0.6, pKnuckle.x + nx * hw * 0.6, pKnuckle.y + ny * hw * 0.6);
  brush.circle(pTip.x, pTip.y, 1.1, 0.02);
}

// ============================================================================
// 7. FINAL HYPERREAL MICRO-DETAILS & THREAD TENSION TICKS
// ============================================================================

function drawFinalMicroDetails() {
  // Subtle radial tension threads around the 8 linked-hand grips
  for (let k = 0; k < 8; k++) {
    let gp = gripPoints[k];
    brush.set("fine_needle", PALETTES.ivory.bright, 0.26);
    for (let a = 0; a < 360; a += 45) {
      let r0 = 15;
      let r1 = 22;
      brush.line(
        gp.x + cos(a) * r0, gp.y + sin(a) * r0,
        gp.x + cos(a) * r1, gp.y + sin(a) * r1
      );
    }
  }

  // Central nadir target crosshair far below in the void (at 600, 600)
  brush.set("fine_needle", PALETTES.ochre.mid, 0.28);
  brush.circle(600, 600, 14, 0.05);
  brush.circle(600, 600, 5, 0.05);
  brush.line(580, 600, 620, 600);
  brush.line(600, 580, 600, 620);
}

// ============================================================================
// GEOMETRY & DRAWING UTILITIES
// ============================================================================

function drawPoly(pts) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawClosedStroke(pts) {
  if (!pts || pts.length < 2) return;
  for (let i = 0; i < pts.length; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

function bezierPt(a, b, c, t) {
  let mt = 1 - t;
  return mt * mt * a + 2 * mt * t * b + t * t * c;
}

function bezierTan(a, b, c, t) {
  return 2 * (1 - t) * (b - a) + 2 * t * (c - b);
}

function pointAlong(p0, p1, t) {
  return {
    x: lerp(p0.x, p1.x, t),
    y: lerp(p0.y, p1.y, t)
  };
}

function midPtOffset(p0, p1, nx, ny, offsetDist) {
  // Overload when nx is a scalar and ny is offset
  if (offsetDist === undefined) return { x: (p0.x + p1.x) * 0.5, y: (p0.y + p1.y) * 0.5 };
  return {
    x: (p0.x + p1.x) * 0.5 + nx * offsetDist,
    y: (p0.y + p1.y) * 0.5 + ny * offsetDist
  };
}

// Hyperrealistic Kodachrome Watercolor — Girl in Red Gingham on White Porch Steps
// p5.js 2.x + p5.brush (WEBGL)

const WX1 = 115, WY1 = 100, WX2 = 1085, WY2 = 1050;

async function setup() {
