// Helper: draw polygon through p5.brush field-aware vertices
function polyShape(pts, curv = 0.06) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Helper: glassy watercolor glaze with clean pigment edges
function glazePoly(pts, col, alpha = 135, bleed = 0.035, tex = 0.32, border = 0.48, curv = 0.06) {
  brush.noStroke();
  brush.noWash();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  polyShape(pts, curv);
  brush.noFill();
}

// Helper: fast crisp wash pass for hard edges and deep shadows
function washPoly(pts, col, alpha = 220, curv = 0.03) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, alpha);
  polyShape(pts, curv);
  brush.noWash();
}

// Step perspective helper: slight upward tilt from left to right
function stepY(baseY, x) {
  return baseY - 0.024 * (x - 600);
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // Clip all painting inside the slide transparency aperture
  brush.clip([WX1, WY1, WX2, WY2]);

  // 1. HARD CYAN SKY & PORCH BACKGROUND
  drawCyanSkyAndPorchWall();

  // 2. WHITE PAINTED PORCH STEPS, DEEP BLACK UNDER-TREADS & LONG BLUE SHADOWS
  drawPorchSteps();

  // 3. LOWER LEGS & SUMMER SANDALS ON FOREGROUND STEP
  drawLegsAndSandals();

  // 4. RED GINGHAM SUNDRESS (BODICE, RUFFLED STRAPS & VOLUMINOUS PLEATED SKIRT)
  drawGinghamSundress();

  // 5. TORSO, NECK, SUNLIT HAIR, RED RIBBONS & FACE
  drawHeadAndFace();

  // 6. FOREARMS, HANDS & HYPER-DETAILED BUTTERED CORN ON THE COB
  drawForearmsAndCorn();

  // Remove clip and render the crisp white cardboard Kodachrome slide mount
  brush.noClip();
  drawSlideMountAndStamp();

  noLoop();
}

// ============================================================================
// 1. HARD CYAN SKY & DISTANT PORCH ARCHITECTURE
// ============================================================================
function drawCyanSkyAndPorchWall() {
  // Base ivory paper ground inside aperture
  washPoly([[WX1, WY1], [WX2, WY1], [WX2, WY2], [WX1, WY2]], "#fffcf5", 255, 0);

  // Hard Kodachrome cyan sky (upper-left to center-top)
  glazePoly([[WX1, WY1], [630, WY1], [630, 355], [WX1, 370]], "#008ed6", 190, 0.03, 0.28, 0.45, 0.02);
  glazePoly([[WX1, WY1], [610, WY1], [590, 260], [WX1, 285]], "#0062ad", 155, 0.04, 0.35, 0.5, 0.03);
  glazePoly([[WX1, 230], [580, 220], [580, 360], [WX1, 370]], "#1cb5e8", 110, 0.03, 0.25, 0.4, 0.02);

  // Right background: white clapboard house wall in warm afternoon sun & diagonal blue shadow
  washPoly([[545, WY1], [WX2, WY1], [WX2, 355], [545, 355]], "#fff8ec", 245, 0.01);
  // Long diagonal cobalt shadow cast by porch roof overhang
  glazePoly([[650, WY1], [WX2, WY1], [WX2, 355], [545, 355], [545, 210]], "#1c4078", 175, 0.02, 0.3, 0.52, 0.02);
  glazePoly([[760, WY1], [WX2, WY1], [WX2, 290], [640, 355]], "#122b57", 125, 0.02, 0.28, 0.45, 0.02);

  // Horizontal clapboard siding lap shadows on right wall
  for (let y = 135; y <= 315; y += 44) {
    let yR = y - 10;
    washPoly([[545, y], [WX2, yR], [WX2, yR + 6], [545, y + 6]], "#091326", 215, 0.01);
    washPoly([[545, y + 6], [WX2, yR + 6], [WX2, yR + 14], [545, y + 14]], "#264e8a", 120, 0.01);
  }

  // White painted porch spindles & turned newel post against the hard cyan sky
  const spindles = [
    { x: 162, w: 26 },
    { x: 256, w: 26 },
    { x: 350, w: 26 },
    { x: 462, w: 68 } // main newel post
  ];
  for (let s of spindles) {
    let x1 = s.x, x2 = s.x + s.w;
    let xMid = x1 + s.w * 0.52;
    // Sunlit warm white left face
    washPoly([[x1, WY1], [xMid, WY1], [xMid, 358], [x1, 358]], "#fffdf7", 250, 0.01);
    // Crisp Kodachrome blue shadow right face
    washPoly([[xMid, WY1], [x2, WY1], [x2, 358], [xMid, 358]], "#1d437d", 225, 0.01);
    glazePoly([[xMid - 2, WY1], [x2, WY1], [x2, 358], [xMid - 2, 358]], "#132c59", 110, 0.02, 0.3, 0.5, 0.01);
    // Subtle dark architectural edge on shadow side
    brush.set("microPen", "#0a1730", 1.1);
    brush.line(x2, WY1, x2, 358);
  }
}

// ============================================================================
// 2. WHITE PAINTED PORCH STEPS & DEEP NEAR-BLACK UNDER-TREADS
// ============================================================================
function drawPorchSteps() {
  const steps = [
    { treadTop: 332, treadBot: 386, noseBot: 406, blackBot: 428, riserBot: 558 },
    { treadTop: 558, treadBot: 642, noseBot: 666, blackBot: 694, riserBot: 856 },
    { treadTop: 856, treadBot: 966, noseBot: 992, blackBot: 1022, riserBot: 1060 }
  ];

  // Base sunlit warm white wood across all steps
  for (let idx = 0; idx < steps.length; idx++) {
    let st = steps[idx];
    let xL = WX1, xR = WX2;

    // 1) Tread top plane (warm sunlit white painted wood)
    washPoly([
      [xL, stepY(st.treadTop, xL)], [xR, stepY(st.treadTop, xR)],
      [xR, stepY(st.treadBot, xR)], [xL, stepY(st.treadBot, xL)]
    ], "#fffaf0", 250, 0.01);

    // Subtle warm golden sunlight glaze on left side of tread
    glazePoly([
      [xL, stepY(st.treadTop, xL)], [680, stepY(st.treadTop, 680)],
      [620, stepY(st.treadBot, 620)], [xL, stepY(st.treadBot, xL)]
    ], "#ffefd2", 95, 0.03, 0.25, 0.35, 0.02);

    // 2) Bullnose overhang lip (brightest sunlit strip along top half, blue-grey turn on bottom half)
    let noseMid = (st.treadBot + st.noseBot) * 0.5;
    washPoly([
      [xL, stepY(st.treadBot, xL)], [xR, stepY(st.treadBot, xR)],
      [xR, stepY(noseMid, xR)], [xL, stepY(noseMid, xL)]
    ], "#ffffff", 255, 0.01);
    washPoly([
      [xL, stepY(noseMid, xL)], [xR, stepY(noseMid, xR)],
      [xR, stepY(st.noseBot, xR)], [xL, stepY(st.noseBot, xL)]
    ], "#9eb4d1", 185, 0.01);

    // 3) Riser vertical plane (warm ivory in sun, ready for blue shadows)
    washPoly([
      [xL, stepY(st.blackBot, xL)], [xR, stepY(st.blackBot, xR)],
      [xR, stepY(st.riserBot, xR)], [xL, stepY(st.riserBot, xL)]
    ], "#f7f2e6", 248, 0.01);
  }

  // LONG COBALT-BLUE CAST SHADOWS ACROSS THE WHITE STEPS (low late-afternoon sun from left)
  // Shadow from porch balustrade on left edge + long diagonal shadow from the girl stretching right
  const blueShadows = [
    // Step 1 (upper) right shadow
    [[530, stepY(332, 530)], [WX2, stepY(332, WX2)], [WX2, stepY(558, WX2)], [575, stepY(558, 575)]],
    // Balustrade diagonal shadow slabs on left of Step 1 & Step 2
    [[WX1, stepY(332, WX1)], [255, stepY(332, 255)], [345, stepY(386, 345)], [WX1, stepY(386, WX1)]],
    [[WX1, stepY(410, WX1)], [335, stepY(410, 335)], [375, stepY(558, 375)], [WX1, stepY(558, WX1)]],
    [[WX1, stepY(558, WX1)], [290, stepY(558, 290)], [385, stepY(642, 385)], [WX1, stepY(642, WX1)]],
    // Girl's long cast shadow stretching right across Middle Step (Step 2) tread & riser
    [[580, stepY(558, 580)], [WX2, stepY(558, WX2)], [WX2, stepY(666, WX2)], [660, stepY(666, 660)]],
    [[620, stepY(690, 620)], [WX2, stepY(690, WX2)], [WX2, stepY(856, WX2)], [695, stepY(856, 695)]],
    // Girl's & dress's cast shadow across Foreground Step (Step 3) tread & riser
    [[460, stepY(856, 460)], [WX2, stepY(856, WX2)], [WX2, stepY(992, WX2)], [520, stepY(992, 520)]],
    [[510, stepY(1018, 510)], [WX2, stepY(1018, WX2)], [WX2, 1060], [545, 1060]]
  ];

  // Batch blue watercolor glazes for crisp, transparent Kodachrome shadows
  for (let sh of blueShadows) {
    glazePoly(sh, "#1f4785", 165, 0.025, 0.34, 0.55, 0.02);
  }
  // Second deeper cobalt glaze inside core shadow zones
  glazePoly([[650, stepY(558, 650)], [WX2, stepY(558, WX2)], [WX2, stepY(856, WX2)], [720, stepY(856, 720)]], "#122b59", 130, 0.03, 0.35, 0.5, 0.02);
  glazePoly([[560, stepY(856, 560)], [WX2, stepY(856, WX2)], [WX2, stepY(992, WX2)], [630, stepY(992, 630)]], "#142f61", 125, 0.03, 0.35, 0.5, 0.02);

  // DEEP NEAR-BLACK SHADOWS UNDER THE STEP TREADS (signature Kodachrome high-contrast detail)
  for (let st of steps) {
    let xL = WX1, xR = WX2;
    // Secondary dark Prussian blue penumbra just below the black band
    let penBot = st.blackBot + 14;
    washPoly([
      [xL, stepY(st.noseBot, xL)], [xR, stepY(st.noseBot, xR)],
      [xR, stepY(penBot, xR)], [xL, stepY(penBot, xL)]
    ], "#0f2347", 215, 0.01);

    // Core razor-sharp near-black shadow directly under each overhanging step nosing
    washPoly([
      [xL, stepY(st.noseBot, xL)], [xR, stepY(st.noseBot, xR)],
      [xR, stepY(st.blackBot, xR)], [xL, stepY(st.blackBot, xL)]
    ], "#050811", 252, 0.01);

    // Extra ink-black contact line right under the lip
    brush.set("rotring", "#020307", 1.8);
    brush.line(xL, stepY(st.noseBot + 2, xL), xR, stepY(st.noseBot + 2, xR));
  }

  // HYPER-REAL PAINTED WOOD TEXTURE: plank seams, paint checks, weathered chips & nail dimples
  for (let st of steps) {
    let midTread = (st.treadTop + st.treadBot) * 0.5;
    // Plank seam across each tread
    brush.set("microPen", "#172d52", 1.1);
    brush.line(WX1, stepY(midTread, WX1), WX2, stepY(midTread, WX2));
    brush.set("specular", "#ffffff", 0.9);
    brush.line(WX1, stepY(midTread + 2, WX1), 650, stepY(midTread + 2, 650));

    // Wood grain checks and subtle peeling white paint along the risers and nosings
    for (let i = 0; i < 28; i++) {
      let gx = random(WX1 + 15, WX2 - 15);
      let gy = stepY(random(st.blackBot + 12, st.riserBot - 8), gx);
      let len = random(18, 65);
      let col = gx < 560 ? "#9bb0cc" : "#0b1a36";
      brush.set("microPen", col, random(0.5, 0.95));
      brush.line(gx, gy, gx + len, stepY(gy - stepY(0, gx) + stepY(0, gx + len), gx));
    }

    // Chipped paint patches along the step nosing showing blue-grey primer
    for (let c = 0; c < 9; c++) {
      let cx = random(WX1 + 30, WX2 - 30);
      let cy = stepY(st.treadBot + random(-2, 5), cx);
      let cw = random(6, 18), ch = random(3, 6);
      washPoly([[cx, cy], [cx + cw, cy - 1], [cx + cw - 2, cy + ch], [cx - 1, cy + ch]], "#4e678a", 190, 0.02);
      brush.set("specular", "#ffffff", 0.7);
      brush.line(cx, cy + ch + 1, cx + cw, cy + ch);
    }

    // Countersunk porch nail dimples in pairs
    for (let nx = 190; nx < WX2 - 40; nx += 175) {
      for (let dy of [12, 36]) {
        let ny = stepY(st.treadTop + dy, nx);
        brush.set("microPen", "#182f54", 1.4);
        brush.circle(nx, ny, 2.2, 0.15);
      }
    }
  }
}

// ============================================================================
// 3. SUN-KISSED LOWER LEGS & SUMMER SANDALS
// ============================================================================
function drawLegsAndSandals() {
  const legs = [
    // Left leg (bright afternoon sun on left shin, cool blue core shadow on right)
    { xTopL: 425, xTopR: 518, xBotL: 438, xBotR: 504, yTop: 830, yBot: 1005 },
    // Right leg (angled slightly outward, deeper blue shadow)
    { xTopL: 632, xTopR: 726, xBotL: 648, xBotR: 714, yTop: 842, yBot: 1015 }
  ];

  for (let i = 0; i < legs.length; i++) {
    let L = legs[i];
    let xMidTop = lerp(L.xTopL, L.xTopR, 0.48);
    let xMidBot = lerp(L.xBotL, L.xBotR, 0.45);

    // Warm golden-amber sunlit skin glaze
    glazePoly([
      [L.xTopL, L.yTop], [L.xTopR, L.yTop],
      [L.xBotR, L.yBot], [L.xBotL, L.yBot]
    ], "#f29d74", 195, 0.03, 0.28, 0.4, 0.08);

    // Rich coral-gold subsurface glow along the terminator
    glazePoly([
      [xMidTop - 12, L.yTop], [xMidTop + 14, L.yTop],
      [xMidBot + 12, L.yBot], [xMidBot - 10, L.yBot]
    ], "#d95038", 130, 0.04, 0.3, 0.4, 0.06);

    // Cool Kodachrome slate-blue shadow on right half of leg
    glazePoly([
      [xMidTop, L.yTop], [L.xTopR, L.yTop],
      [L.xBotR, L.yBot], [xMidBot, L.yBot]
    ], "#3d4c73", 165, 0.03, 0.32, 0.48, 0.06);

    // Specular sunlit highlight strip down the left shin bone
    washPoly([
      [L.xTopL + 6, L.yTop + 10], [L.xTopL + 19, L.yTop + 10],
      [L.xBotL + 16, L.yBot - 15], [L.xBotL + 5, L.yBot - 15]
    ], "#ffe7cf", 180, 0.05);

    // Red-strapped summer sandals at bottom of frame
    let sy = L.yBot - 8;
    // White rubber sole
    washPoly([[L.xBotL - 8, sy + 28], [L.xBotR + 12, sy + 28], [L.xBotR + 10, sy + 44], [L.xBotL - 6, sy + 44]], "#fffaf0", 245, 0.04);
    washPoly([[L.xBotL + 20, sy + 28], [L.xBotR + 12, sy + 28], [L.xBotR + 10, sy + 44], [L.xBotL + 20, sy + 44]], "#254980", 190, 0.04);
    // Lipstick-red sandal straps across ankle and toes
    washPoly([[L.xBotL - 3, sy - 4], [L.xBotR + 4, sy - 2], [L.xBotR + 3, sy + 10], [L.xBotL - 4, sy + 8]], "#d91424", 235, 0.04);
