    // Tiny silver buckle highlight
    brush.set("specular", "#ffffff", 1.2);
    brush.rect(L.xBotL + 4, sy - 1, 7, 7, "corner");
  }
}

// ============================================================================
// 4. RED GINGHAM SUNDRESS (HYPER-REAL WARPED WEAVE & GLASSY FOLDS)
// ============================================================================
function drawGinghamSundress() {
  // Skirt silhouette coordinates (draping over knees on Step 2 down to Step 1 riser)
  const waistL = 448, waistR = 712, waistY = 555;
  const hemL = 308, hemR = 862, hemYBase = 862;

  // Function to compute 3D pleated skirt surface (x, y, and fold height z in [-1, 1])
  // u in [0, 1] across skirt width, v in [0, 1] from waist to hem
  function skirtPoint(u, v) {
    let topX = lerp(waistL, waistR, u);
    let botX = lerp(hemL, hemR, u);
    // Subtle outward billow over knees
    let kneeBulge = sin(v * 180) * (u < 0.5 ? -22 * (0.5 - u) : 24 * (u - 0.5));
    let x = lerp(topX, botX, pow(v, 0.88)) + kneeBulge;

    // 7 distinct gathered pleats radiating from waist
    let foldPhase = u * 7.0 * 360 - 25;
    let foldAmp = lerp(3, 18, v);
    let z = sin(foldPhase); // +1 = sunlit fold ridge, -1 = shadowed fold valley

    // Knee elevation: higher over left knee (u~0.26) and right knee (u~0.74), dipping in center lap (u~0.5)
    let lapProfile = -18 * sin(u * 180) + 14 * sin(u * 540);
    let y = lerp(waistY, hemYBase, v) + lapProfile * sin(v * 180) - z * foldAmp * 0.65;
    return { x, y, z };
  }

  // Build full skirt outline polygon
  let skirtOutline = [];
  for (let i = 0; i <= 32; i++) {
    let p = skirtPoint(i / 32, 0);
    skirtOutline.push([p.x, p.y]);
  }
  for (let i = 1; i <= 20; i++) {
    let p = skirtPoint(1, i / 20);
    skirtOutline.push([p.x, p.y]);
  }
  for (let i = 48; i >= 0; i--) {
    let p = skirtPoint(i / 48, 1);
    skirtOutline.push([p.x, p.y]);
  }
  for (let i = 19; i >= 1; i--) {
    let p = skirtPoint(0, i / 20);
    skirtOutline.push([p.x, p.y]);
  }

  // Cast shadow directly beneath the ruffled skirt hem onto the step riser
  let hemShadow = [];
  for (let i = 0; i <= 40; i++) {
    let p = skirtPoint(i / 40, 1);
    hemShadow.push([p.x + 6, p.y - 2]);
  }
  for (let i = 40; i >= 0; i--) {
    let p = skirtPoint(i / 40, 1);
    hemShadow.push([p.x + 14, p.y + 24]);
  }
  washPoly(hemShadow, "#08142b", 220, 0.05);

  // 1) Base white fabric ground of the skirt (warm white in sun, cool sky-blue in shadow)
  washPoly(skirtOutline, "#fffaf2", 252, 0.04);

  // Cool blue-slate shadow wash on the right half & deep center lap of the white gingham ground
  let shadowSide = [];
  for (let i = 15; i <= 32; i++) shadowSide.push([skirtPoint(i / 32, 0).x, skirtPoint(i / 32, 0).y]);
  for (let i = 1; i <= 20; i++) shadowSide.push([skirtPoint(1, i / 20).x, skirtPoint(1, i / 20).y]);
  for (let i = 32; i >= 14; i--) shadowSide.push([skirtPoint(i / 32, 1).x, skirtPoint(i / 32, 1).y]);
  glazePoly(shadowSide, "#6c86ad", 145, 0.03, 0.3, 0.45, 0.04);

  // 2) Bodice & Ruffled Shoulder Straps Base
  const bodicePts = [[442, 465], [718, 472], [712, 565], [448, 560]];
  washPoly(bodicePts, "#fff9f0", 250, 0.03);
  glazePoly([[575, 468], [718, 472], [712, 565], [568, 562]], "#6c86ad", 140, 0.02, 0.3, 0.4, 0.02);

  // Left & Right Ruffled Straps
  const leftStrap = [[410, 388], [482, 392], [492, 505], [432, 502]];
  const rightStrap = [[678, 396], [748, 402], [728, 512], [668, 508]];
  washPoly(leftStrap, "#fffaf2", 250, 0.05);
  washPoly(rightStrap, "#d4e0f0", 245, 0.05);

  // 3) WARPED GINGHAM WEAVE ON SKIRT (Lipstick-red warp & weft bands + deep crimson intersections)
  const numCols = 28; // vertical/radial gingham grid subdivisions
  const numRows = 18; // horizontal wave gingham grid subdivisions

  // Draw vertical/radial red stripes (odd columns)
  for (let c = 0; c < numCols; c++) {
    if (c % 2 === 1) {
      let u0 = c / numCols;
      let u1 = (c + 0.88) / numCols;
      for (let r = 0; r < numRows; r++) {
        let v0 = r / numRows;
        let v1 = (r + 1) / numRows;
        let p00 = skirtPoint(u0, v0), p10 = skirtPoint(u1, v0);
        let p11 = skirtPoint(u1, v1), p01 = skirtPoint(u0, v1);
        let inSun = (u0 < 0.56 && p00.z > -0.35);
        let col = inSun ? "#e6192e" : "#9c1025";
        washPoly([[p00.x, p00.y], [p10.x, p10.y], [p11.x, p11.y], [p01.x, p01.y]], col, inSun ? 160 : 175, 0.02);
      }
    }
  }

  // Draw horizontal undulating red stripes (odd rows) & deep crimson intersections (odd row + odd col)
  for (let r = 0; r < numRows; r++) {
    if (r % 2 === 1) {
      let v0 = r / numRows;
      let v1 = (r + 0.86) / numRows;
      for (let c = 0; c < numCols; c++) {
        let u0 = c / numCols;
        let u1 = (c + 1) / numCols;
        let p00 = skirtPoint(u0, v0), p10 = skirtPoint(u1, v0);
        let p11 = skirtPoint(u1, v1), p01 = skirtPoint(u0, v1);
        let inSun = (u0 < 0.56 && p00.z > -0.35);

        if (c % 2 === 1) {
          // Intersection of horizontal and vertical red stripes -> rich deep Kodachrome crimson!
          let darkCol = inSun ? "#990012" : "#52000b";
          washPoly([[p00.x, p00.y], [p10.x, p10.y], [p11.x, p11.y], [p01.x, p01.y]], darkCol, 235, 0.01);
        } else {
          // Single-layer horizontal red stripe over white ground
          let midCol = inSun ? "#e6192e" : "#9c1025";
          washPoly([[p00.x, p00.y], [p10.x, p10.y], [p11.x, p11.y], [p01.x, p01.y]], midCol, inSun ? 160 : 175, 0.01);
        }
      }
    }
  }

  // Gingham pattern on Bodice & Ruffled Shoulder Straps
  for (let bx = 446; bx < 712; bx += 22) {
    let inSun = bx < 575;
    washPoly([[bx, 468], [bx + 11, 468], [bx + 11, 562], [bx, 562]], inSun ? "#e6192e" : "#960f23", 165, 0.01);
  }
  for (let by = 472; by < 560; by += 22) {
    washPoly([[445, by], [714, by], [714, by + 11], [445, by + 11]], "#d61529", 165, 0.01);
    for (let bx = 446; bx < 712; bx += 22) {
      washPoly([[bx, by], [bx + 11, by], [bx + 11, by + 11], [bx, by + 11]], bx < 575 ? "#910011" : "#4d000a", 230, 0.01);
    }
  }

  // Straps gingham checks
  const strapBoxes = [
    { x0: 414, x1: 486, y0: 390, y1: 502, sun: true },
    { x0: 672, x1: 744, y0: 398, y1: 508, sun: false }
  ];
  for (let sb of strapBoxes) {
    for (let sx = sb.x0; sx < sb.x1; sx += 18) {
      washPoly([[sx, sb.y0], [sx + 9, sb.y0], [sx + 9, sb.y1], [sx, sb.y1]], sb.sun ? "#e6192e" : "#8f0e22", 170, 0.01);
    }
    for (let sy = sb.y0; sy < sb.y1; sy += 18) {
      washPoly([[sb.x0, sy], [sb.x1, sy], [sb.x1, sy + 9], [sb.x0, sy + 9]], sb.sun ? "#e6192e" : "#8f0e22", 170, 0.01);
      for (let sx = sb.x0; sx < sb.x1; sx += 18) {
        washPoly([[sx, sy], [sx + 9, sy], [sx + 9, sy + 9], [sx, sy + 9]], sb.sun ? "#910011" : "#4a0009", 230, 0.01);
      }
    }
  }

  // 4) GLASSY WATERCOLOR FOLD SHADOWS & SUNLIT PLEAT HIGHLIGHTS OVER THE GINGHAM
  for (let f = 0; f < 7; f++) {
    // Valley center occurs where sin(u * 7 * 360 - 25) == -1
    let uValley = ((f + 0.75) * 360 + 25) / (7.0 * 360);
    if (uValley > 0.04 && uValley < 0.96) {
      let valleyPts = [];
      for (let iv = 0; iv <= 12; iv++) {
        let p = skirtPoint(uValley - 0.025, iv / 12);
        valleyPts.push([p.x, p.y]);
      }
      for (let iv = 12; iv >= 0; iv--) {
        let p = skirtPoint(uValley + 0.028, iv / 12);
        valleyPts.push([p.x, p.y]);
      }
      glazePoly(valleyPts, "#1f081e", uValley < 0.5 ? 95 : 135, 0.03, 0.35, 0.45, 0.05);
    }

    // Sunlit ridge crest highlight on left-side pleats
    let uRidge = ((f + 0.25) * 360 + 25) / (7.0 * 360);
    if (uRidge > 0.05 && uRidge < 0.62) {
      brush.set("specular", "#fffdf7", 1.1);
      for (let iv = 1; iv < 14; iv += 2) {
        let pA = skirtPoint(uRidge, iv / 15);
        let pB = skirtPoint(uRidge, (iv + 0.7) / 15);
        brush.line(pA.x, pA.y, pB.x, pB.y);
      }
    }
  }

  // Crisp stitched hem & waist gather seam lines
  brush.set("microPen", "#4a000a", 1.1);
  for (let i = 0; i < 40; i++) {
    let p1 = skirtPoint(i / 40, 0.97);
    let p2 = skirtPoint((i + 1) / 40, 0.97);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
  // White mother-of-pearl buttons on the straps
  brush.set("specular", "#ffffff", 1.3);
  brush.circle(460, 478, 6.5, 0.1);
  brush.circle(698, 484, 6.5, 0.1);
  brush.set("microPen", "#5c6e8a", 0.9);
  brush.circle(460, 478, 6.5, 0.1);
  brush.circle(698, 484, 6.5, 0.1);
}

