// 6. FOREARMS, HANDS & HYPER-DETAILED BUTTERED CORN ON THE COB
// ============================================================================
function drawForearmsAndCorn() {
  // FOREARMS angling up from knees to hold the ends of the corn cob
  // Left forearm (warm golden sunlight on outer edge, cool shadow on inner edge)
