  glazePoly([[715, 445], [755, 435], [812, 645], [752, 655]], "#3b4970", 175, 0.03, 0.32, 0.48, 0.05);

  // THE CORN ON THE COB (x: 438..724, y: 364..456)
  const cobX1 = 440, cobX2 = 722, cobCY = 410;

  // 1) Deep warm burnt-amber cob matrix (visible in the crevices between kernels)
  washPoly([
    [cobX1, cobCY - 38], [580, cobCY - 46], [cobX2, cobCY - 37],
    [cobX2 + 6, cobCY + 37], [580, cobCY + 46], [cobX1 - 6, cobCY + 37]
