  // Pale green-ivory inner husk leaves / cob tips protruding at left and right ends
  washPoly([[408, 392], [444, 382], [444, 434], [404, 422]], "#d9e398", 240, 0.06);
  washPoly([[718, 384], [754, 396], [750, 428], [718, 436]], "#8ea668", 235, 0.06);

  // 2) HYPER-DETAILED ROWS OF EGG-YOLK KERNELS (7 rows around cylinder x 23 columns)
  const nCols = 23;
  const nRows = 7;
  const rowAngles = [-76, -50, -24, 0, 24, 50, 76];

  for (let r = 0; r < nRows; r++) {
    let aTop = rowAngles[r] - 11;
    let aBot = rowAngles[r] + 11;

    for (let c = 0; c < nCols; c++) {
      let u = c / nCols;
      let uNext = (c + 0.88) / nCols;
      let xA = lerp(cobX1, cobX2, u);
      let xB = lerp(cobX1, cobX2, uNext);

      // Cylinder radius tapers slightly toward the ends
      let rad = 45 * (1 - 0.16 * pow((u - 0.5) * 2, 2));
      let y1 = cobCY + sin(aTop) * rad + random(-0.8, 0.8);
      let y2 = cobCY + sin(aBot) * rad + random(-0.8, 0.8);

      // Check if this kernel is right under her front teeth (bitten-out socket!)
      let isBitten = (r <= 1 && c >= 9 && c <= 13);

      if (isBitten) {
        // Juicy pale-ivory bitten kernel pulp & ragged skin rim
        washPoly([[xA, y1 + 2], [xB, y1 + 2], [xB, y2], [xA, y2]], "#fff6ba", 245, 0.04);
        brush.set("specular", "#ffffff", 0.9);
        brush.line(xA + 1, y2 - 1, xB - 1, y2 - 1);
        continue;
      }

      // Determine Kodachrome egg-yolk tone based on cylinder angle and left-to-right sunlight
      let inSun = (u < 0.68 && r <= 4);
      let inDeepShadow = (r >= 5 || u > 0.78);
      let baseCol, rootCol;
      if (r <= 1 && u < 0.65) {
        baseCol = "#ffcc00"; // blinding sunlit lemon-yolk
        rootCol = "#e07b00";
      } else if (inSun) {
        baseCol = "#ffaa00"; // rich Kodachrome egg-yolk gold
        rootCol = "#b84a00";
      } else if (!inDeepShadow) {
        baseCol = "#d96b00"; // warm burnished amber-orange
        rootCol = "#7a2800";
      } else {
        baseCol = "#7d3808"; // shadowed deep amber-ochre
        rootCol = "#3d1604";
      }

      // Plump rounded-rectangular kernel body
      washPoly([
        [xA + 0.8, y1 + 0.8], [xB - 0.5, y1 + 0.8],
        [xB - 0.3, y2 - 0.6], [xA + 0.5, y2 - 0.6]
      ], baseCol, 248, 0.08);

      // Deeper orange-amber shading at bottom/right of each kernel for 3D volume
      let yMid = lerp(y1, y2, 0.58);
      washPoly([
        [xA + 1.2, yMid], [xB - 0.5, yMid],
        [xB - 0.5, y2 - 0.5], [xA + 1.0, y2 - 0.5]
      ], rootCol, 195, 0.05);

      // Translucent kernel skin rim & glossy specular micro-highlight on each kernel!
      if (!inDeepShadow) {
        brush.set("specular", r <= 2 ? "#ffffff" : "#fff2a6", r <= 2 ? 0.95 : 0.7);
        brush.line(xA + 2, y1 + 2.2, xB - 3, y1 + 2.2);
      }
    }
  }

  // 3) MELTED BUTTER GLAZE, SLIDING BUTTER PAT & DRIPPING DROPLETS
  // Translucent lemon-cream butter pool slathered across central rows (x: 505..645)
  glazePoly([
    [505, 382], [642, 384], [648, 438], [585, 454], [512, 436]
  ], "#fff380", 135, 0.04, 0.25, 0.4, 0.08);

  // Softly melting pat of pale butter resting on the front-center kernels
  washPoly([[556, 392], [604, 395], [598, 422], [550, 419]], "#fff8b8", 225, 0.08);
  washPoly([[560, 394], [596, 396], [592, 412], [556, 410]], "#ffffff", 235, 0.06);

  // Glossy streams of liquid butter running down between kernel columns & dripping off bottom
  const drips = [
    { x: 534, yStart: 405, yEnd: 462, dropY: 478 },
    { x: 578, yStart: 412, yEnd: 468, dropY: 494 },
    { x: 616, yStart: 402, yEnd: 460, dropY: 0 }
  ];
  for (let d of drips) {
    // Golden butter rivulet
    washPoly([[d.x - 4, d.yStart], [d.x + 4, d.yStart], [d.x + 5, d.yEnd], [d.x - 4, d.yEnd]], "#ffe042", 210, 0.06);
    // Razor-sharp wet white specular reflection down the rivulet
    brush.set("specular", "#ffffff", 1.15);
    brush.line(d.x - 1, d.yStart + 2, d.x - 1, d.yEnd - 2);
    brush.circle(d.x, d.yEnd, 4.2, 0.1);

    // Mid-air falling butter droplet catching the late-afternoon sun
    if (d.dropY > 0) {
      washPoly([[d.x, d.dropY - 8], [d.x + 5, d.dropY + 2], [d.x, d.dropY + 7], [d.x - 5, d.dropY + 2]], "#ffe85c", 235, 0.08);
      brush.set("specular", "#ffffff", 1.2);
      brush.circle(d.x - 1.5, d.dropY + 1, 2.2, 0.05);
    }
  }

  // 4) BOTH HANDS GRIPPING THE ENDS OF THE COB (with translucent coral subsurface glow)
  // Left Hand fingers curled around left end of cob (x: 406..476)
  const leftFingers = [
    { y: 374, x1: 414, x2: 472, h: 18 }, // Index finger
    { y: 393, x1: 408, x2: 476, h: 19 }, // Middle finger
    { y: 413, x1: 410, x2: 470, h: 18 }, // Ring finger
    { y: 432, x1: 416, x2: 462, h: 16 }  // Little finger
  ];
  for (let f of leftFingers) {
    // Warm sunlit finger top
    washPoly([[f.x1, f.y], [f.x2, f.y + 2], [f.x2, f.y + f.h], [f.x1, f.y + f.h - 2]], "#f7a881", 245, 0.08);
    // Fiery lipstick-red subsurface scattering line between fingers
    brush.set("kernelGlaze", "#cc1b24", 0.9);
    brush.line(f.x1 + 4, f.y + f.h, f.x2 - 2, f.y + f.h);
    // Bright sunlit highlight along top of finger & glossy fingernail
    brush.set("specular", "#fff2e2", 1.05);
    brush.line(f.x1 + 5, f.y + 3, f.x2 - 12, f.y + 4);
    washPoly([[f.x2 - 11, f.y + 3], [f.x2 - 2, f.y + 4], [f.x2 - 2, f.y + f.h - 4], [f.x2 - 11, f.y + f.h - 4]], "#fff7f0", 235, 0.05);
  }
  // Left thumb supporting bottom of cob
  washPoly([[422, 444], [478, 436], [482, 456], [426, 462]], "#d97654", 240, 0.08);

  // Right Hand fingers curled around right end of cob (x: 688..756)
  const rightFingers = [
    { y: 378, x1: 692, x2: 748, h: 18 },
    { y: 397, x1: 688, x2: 754, h: 19 },
    { y: 417, x1: 694, x2: 750, h: 18 },
    { y: 436, x1: 702, x2: 744, h: 16 }
  ];
  for (let f of rightFingers) {
    // Cool shadowed finger with warm golden reflection from the corn
    washPoly([[f.x1, f.y + 2], [f.x2, f.y], [f.x2, f.y + f.h - 2], [f.x1, f.y + f.h]], "#8c5c69", 242, 0.08);
    glazePoly([[f.x1, f.y + 2], [f.x1 + 26, f.y + 2], [f.x1 + 26, f.y + f.h], [f.x1, f.y + f.h]], "#e08538", 130, 0.03, 0.25, 0.35, 0.05);
    brush.set("microPen", "#3b1722", 1.0);
    brush.line(f.x1 + 2, f.y + f.h, f.x2 - 4, f.y + f.h - 1);
