// Parametric ladle bowl outer contour (includes subtle pouring-lip flare on upper sides)
function getBowlContourPt(deg, radScale = 1.0) {
  let rad = deg * (Math.PI / 180);
  let nx = Math.cos(rad);
  let ny = Math.sin(rad);

  // Ladle bowls flare slightly at the upper-left and upper-right pouring lips
  let lipFlare = 1.0 + 0.036 * Math.exp(-Math.pow((ny + 0.28) / 0.34, 2)) * Math.pow(nx, 2);
  // Slight bottom weight of deep soup bowl
  let bottomCurve = ny > 0 ? 1.0 + 0.02 * Math.sin(ny * Math.PI * 0.5) : 1.0 - 0.015 * Math.pow(-ny, 1.5);

  let x = BX + nx * RX * lipFlare * radScale;
  let y = BY + ny * RY * bottomCurve * radScale;
  return [x, y];
}

// Fisheye spherical projection mapping 3D room coordinates (u, v) onto the convex ladle bowl
function roomToBowl(u, v, maxR = 0.968) {
  // Optical center shifted slightly up-left for dynamic 3D dome curvature
  let u0 = u + 0.04;
  let v0 = v + 0.05;
  let rho = Math.hypot(u0, v0);
  if (rho < 1e-5) {
    return { x: BX - 8, y: BY - 10, r: 0, theta: 0 };
  }

  // Spherical wide-angle fisheye compression: magnifies center, pinches tightly at rim
  let normAtan = (2 / Math.PI) * Math.atan(0.92 * rho);
  let r = Math.min(maxR, Math.pow(normAtan, 0.86));
  let theta = Math.atan2(v0, u0);

  // Pinch reflections toward the horizontal rim poles and top handle neck junction
  let rimPinch = 1.0 - 0.032 * Math.pow(Math.cos(theta), 4) * Math.pow(r, 3);
  let neckPinch = 1.0 - 0.04 * Math.exp(-Math.pow((theta + Math.PI * 0.46) / 0.35, 2)) * Math.pow(r, 4);

  let nx = r * Math.cos(theta) * rimPinch;
  let ny = r * Math.sin(theta) * neckPinch;

  let lipFlare = 1.0 + 0.036 * Math.exp(-Math.pow((ny + 0.28) / 0.34, 2)) * Math.pow(nx / Math.max(0.01, r), 2);
  let bottomCurve = ny > 0 ? 1.0 + 0.02 * Math.sin(ny * Math.PI * 0.5) : 1.0 - 0.015 * Math.pow(-ny, 1.5);

  let x = BX + nx * RX * lipFlare;
  let y = BY + ny * RY * bottomCurve;
  return { x, y, r, theta, nx, ny };
}

// Draw a filled wash polygon warped through the fisheye lens
function fisheyeWashPoly(roomPts, col, opacity = 210, subdiv = 10, maxR = 0.968) {
  brush.noStroke();
  brush.noFill();
  brush. noHatch();
  brush.wash(col, opacity);
  brush.beginShape(0.15);
  for (let i = 0; i < roomPts.length; i++) {
    let p1 = roomPts[i];
    let p2 = roomPts[(i + 1) % roomPts.length];
    for (let s = 0; s < subdiv; s++) {
      let t = s / subdiv;
      let u = lerp(p1[0], p2[0], t);
      let v = lerp(p1[1], p2[1], t);
      let pt = roomToBowl(u, v, maxR);
      brush.vertex(pt.x, pt.y);
    }
  }
  brush.endShape(true);
  brush.noWash();
}

// Draw a warped spline stroke through room-space control points
function fisheyeSpline(roomPts, brushName, col, weight = 1, subdiv = 8, curvature = 0.5, maxR = 0.968) {
  let canvasPts = [];
  for (let i = 0; i < roomPts.length - 1; i++) {
    let p1 = roomPts[i];
    let p2 = roomPts[i + 1];
    let steps = (i === roomPts.length - 2) ? subdiv : subdiv - 1;
    for (let s = 0; s <= steps; s++) {
      if (i > 0 && s === 0) continue;
      let t = s / subdiv;
      let u = lerp(p1[0], p2[0], t);
      let v = lerp(p1[1], p2[1], t);
      let pt = roomToBowl(u, v, maxR);
      // Taper pressure slightly near the extreme rim for pinched look
      let p = p1[2] !== undefined ? lerp(p1[2], p2[2] ?? p1[2], t) : (1.05 - 0.45 * Math.pow(pt.r, 4));
      canvasPts.push([pt.x, pt.y, Math.max(0.15, p)]);
    }
  }
  if (canvasPts.length >= 2) {
    brush.noFill();
    brush.noWash();
    brush.set(brushName, col, weight);
    brush.spline(canvasPts, curvature);
  }
}

// Helper for drawing a straight screen-space spline with pressure profile
function drawScreenSpline(pts, brushName, col, weight = 1, curvature = 0.4) {
  brush.noFill();
  brush.noWash();
  brush.set(brushName, col, weight);
  brush.spline(pts, curvature);
}

// Helper for screen-space wash polygon
function drawWashPoly(pts, col, opacity = 220, curvature = 0.1) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#cbc7b8");
  brush.noField();

  // =========================================================================
  // 1. BLURRED BEIGE TILE BACKGROUND & DIFFUSED CAST SHADOW
  // =========================================================================
  drawBlurredTileBackground();
  drawBlurredWallRailAndShadow();

  // =========================================================================
  // 2. CONVEX LADLE BOWL — BASE METALLIC GROUND
  // =========================================================================
  drawBowlBaseGround();

  // =========================================================================
  // 3. FISHEYE DINER REFLECTION (SHARP, SATURATED MARKER BLENDS)
