  drawFisheyeWindowsAndNeon();
  drawFisheyeKitchenBackbar();
  drawFisheyeCookInApron();
  drawFisheyeDinerCounter();
  drawFisheyeFloorAndRedStools();

  // =========================================================================
  // 4. EXTREME RIM PINCHING, ROLLED LIP BEZEL & SPECULAR SLASHES
  // =========================================================================
  drawRimPinchReflections();
  drawBowlSpecularSlashes();

  // =========================================================================
  // 5. BRUSHED-STEEL HANDLE, FORGED NECK & S-HOOK
  // =========================================================================
  drawWallHookRear();
  drawLadleHandleAndNeck();
  drawWallHookFront();

  noLoop();
}

// ---------------------------------------------------------------------------
// STAGE 1: OUT-OF-FOCUS BEIGE TILE WALL & SOFT SHADOW
// ---------------------------------------------------------------------------
function drawBlurredTileBackground() {
  // Large, soft out-of-focus ceramic tiles (cool beige / greige palette)
  let tileW = 250;
  let tileH = 250;
  let offsetX = -35;
  let offsetY = -25;

  let tileTones = [
    "#d8d4c7", "#d0cdc0", "#c7c4b7", "#bfbdb0",
    "#b7b6aa", "#cfd0c4", "#c2c2b6", "#b2b4aa"
  ];

  // Batch watercolor washes for out-of-focus tile faces
  brush.noStroke();
  brush.noWash();
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.32, 0.12);

  for (let row = 0; row < 6; row++) {
    for (let col = 0; col < 6; col++) {
      let x = offsetX + col * tileW;
      let y = offsetY + row * tileH;

      // Skip tiles completely hidden deep under the center of the bowl
      let cx = x + tileW * 0.5;
      let cy = y + tileH * 0.5;
      if (Math.hypot((cx - BX) / (RX * 0.72), (cy - BY) / (RY * 0.72)) < 1.0) continue;

      // Ambient cool-to-warm gradient across the wall
      let toneIdx = (row * 3 + col * 5) % tileTones.length;
      let baseCol = (col + row < 5) ? tileTones[toneIdx] : "#b3b4ab";
      brush.fill(baseCol, 115);
      brush.rect(x + 14, y + 14, tileW - 28, tileH - 28, "corner");

      // Secondary soft out-of-focus glaze sheen on upper-left of each tile
      if ((row + col) % 2 === 0) {
        brush.fill("#e3dfd2", 75);
        brush.rect(x + 28, y + 24, tileW * 0.58, tileH * 0.45, "corner");
      } else {
        brush.fill("#a5a8a0", 65);
        brush.rect(x + 40, y + 50, tileW * 0.62, tileH * 0.55, "corner");
      }
    }
  }
  brush.noFill();

  // Out-of-focus grout lines rendered with wide, soft marker & spray passes (no hard edges)
  for (let i = 1; i <= 5; i++) {
    let gx = offsetX + i * tileW;
    let gy = offsetY + i * tileH;

    // Vertical blurred grout
    drawScreenSpline([[gx, 0, 1], [gx, 600, 1], [gx, 1200, 1]], "chiselMarker", "#9d9e95", 2.6, 0.1);
    drawScreenSpline([[gx - 5, 0, 0.8], [gx - 5, 600, 0.8], [gx - 5, 1200, 0.8]], "chiselMarker", "#b2b1a6", 1.8, 0.1);
    drawScreenSpline([[gx + 6, 0, 0.8], [gx + 6, 600, 0.8], [gx + 6, 1200, 0.8]], "chiselMarker", "#dfdCD0", 1.4, 0.1);
    drawScreenSpline([[gx, 0, 1], [gx, 600, 1], [gx, 1200, 1]], "spray", "#8c8e86", 1.6, 0.1);

    // Horizontal blurred grout
    drawScreenSpline([[0, gy, 1], [600, gy, 1], [1200, gy, 1]], "chiselMarker", "#9a9b92", 2.6, 0.1);
    drawScreenSpline([[0, gy - 5, 0.8], [600, gy - 5, 0.8], [1200, gy - 5, 0.8]], "chiselMarker", "#b2b1a6", 1.8, 0.1);
    drawScreenSpline([[0, gy + 6, 0.8], [600, gy + 6, 0.8], [1200, gy + 6, 0.8]], "chiselMarker", "#dfdcd0", 1.4, 0.1);
    drawScreenSpline([[0, gy, 1], [600, gy, 1], [1200, gy, 1]], "spray", "#8a8c84", 1.6, 0.1);
  }
}

function drawBlurredWallRailAndShadow() {
  // Out-of-focus horizontal stainless utensil rail across top of tile wall
  drawWashPoly([[0, 26], [1200, 18], [1200, 68], [0, 76]], "#7e8587", 125);
  drawWashPoly([[0, 32], [1200, 24], [1200, 48], [0, 56]], "#aeb5b7", 140);
  drawWashPoly([[0, 66], [1200, 58], [1200, 92], [0, 100]], "#697073", 95);
  drawScreenSpline([[0, 38, 1], [600, 34, 1], [1200, 30, 1]], "chiselMarker", "#dfe6e8", 1.8, 0.1);
  drawScreenSpline([[0, 62, 1], [600, 58, 1], [1200, 54, 1]], "chiselMarker", "#454d52", 1.9, 0.1);

  // Soft, multi-layered cast shadow of ladle on the beige tiles (shifted right & down)
  brush.noStroke();
  brush.noWash();
  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.28, 0.08);

  // Bowl cast shadow penumbra (outer to inner)
  let shadowLayers = [
    { dx: 64, dy: 42, scale: 1.07, col: "#8d928f", op: 85 },
    { dx: 50, dy: 34, scale: 1.03, col: "#717878", op: 95 },
    { dx: 36, dy: 24, scale: 0.99, col: "#535c60", op: 110 },
    { dx: 22, dy: 15, scale: 0.96, col: "#394349", op: 120 }
  ];

  for (let sl of shadowLayers) {
    brush.fill(sl.col, sl.op);
    brush.beginShape(0.35);
    for (let deg = -55; deg <= 235; deg += 15) {
      let pt = getBowlContourPt(deg, sl.scale);
      brush.vertex(pt[0] + sl.dx, pt[1] + sl.dy);
    }
    brush.endShape(true);
  }

  // Handle & hook cast shadow on tiles
  brush.fill("#747b7a", 105);
  brush.beginShape(0.2);
  brush.vertex(668, 45);
  brush.vertex(735, 55);
  brush.vertex(702, 415);
  brush.vertex(625, 415);
  brush.endShape(true);

  brush.fill("#4d565b", 115);
  brush.beginShape(0.2);
  brush.vertex(658, 55);
  brush.vertex(708, 62);
  brush.vertex(674, 405);
  brush.vertex(622, 405);
  brush.endShape(true);

  brush.noFill();

  // Extra spray diffusion around cast shadow edge for genuine optical blur
  let shadowArc = [];
  for (let deg = -40; deg <= 115; deg += 15) {
    let pt = getBowlContourPt(deg, 1.03);
    shadowArc.push([pt[0] + 44, pt[1] + 28, 1.0]);
  }
  drawScreenSpline(shadowArc, "spray", "#5f676a", 2.2, 0.4);
}

