function drawFisheyeCeilingAndTubes() {
  // Upper hemisphere ceiling gradient zones
  fisheyeWashPoly([[-2.8, -2.8], [2.8, -2.8], [2.8, -1.25], [-2.8, -1.25]], "#060b13", 250, 14);
  fisheyeWashPoly([[-2.8, -1.35], [2.8, -1.35], [2.8, -0.42], [-2.8, -0.42]], "#0d1a2b", 240, 14);

  // Cool blue-grey steel ceiling bays & acoustic ducts
  fisheyeWashPoly([[-1.8, -1.95], [1.9, -2.15], [1.9, -1.55], [-1.8, -1.42]], "#162942", 200, 12);
  fisheyeWashPoly([[-2.2, -1.08], [2.1, -1.28], [2.1, -0.82], [-2.2, -0.68]], "#1b3350", 195, 12);

  // Perspective cross-ribs of diner ceiling grid
  let ceilingCrossU = [-1.8, -1.1, -0.45, 0.2, 0.85, 1.55];
  for (let cu of ceilingCrossU) {
    fisheyeSpline([[cu * 1.15, -2.5], [cu, -1.2], [cu * 0.85, -0.45]], "pen", "#253f5e", 0.7, 10, 0.4);
    fisheyeSpline([[cu * 1.15 + 0.03, -2.5], [cu + 0.03, -1.2], [cu * 0.85 + 0.03, -0.45]], "rotring", "#05080f", 0.6, 10, 0.4);
  }

  // Four pairs of overhead fluorescent ceiling tube fixtures bending into dramatic arcs
  let tubeRows = [
    { vL: -2.05, vR: -2.25, w: 0.13, glowW: 1.5, coreW: 0.75 },
    { vL: -1.38, vR: -1.62, w: 0.12, glowW: 1.9, coreW: 0.95 },
    { vL: -0.86, vR: -1.08, w: 0.11, glowW: 2.2, coreW: 1.15 },
    { vL: -0.48, vR: -0.64, w: 0.09, glowW: 1.8, coreW: 0.95 }
  ];

  for (let tr of tubeRows) {
    // Dark metal ballast trough behind each fluorescent pair
    fisheyeWashPoly([
      [-2.6, tr.vL - tr.w],
      [2.6, tr.vR - tr.w],
      [2.6, tr.vR + tr.w],
      [-2.6, tr.vL + tr.w]
    ], "#060a12", 240, 16);

    // Saturated cyan-blue marker halo around fluorescent tubes
    fisheyeWashPoly([
      [-2.5, tr.vL - tr.w * 1.65],
      [2.5, tr.vR - tr.w * 1.65],
      [2.5, tr.vR + tr.w * 1.65],
      [-2.5, tr.vL + tr.w * 1.65]
    ], "#2989c9", 95, 16);

    // Chisel marker cyan bloom along the arc
    fisheyeSpline([[-2.55, tr.vL, 0.3], [-1.2, lerp(tr.vL, tr.vR, 0.25), 1.0], [0.0, lerp(tr.vL, tr.vR, 0.5), 1.15], [1.2, lerp(tr.vL, tr.vR, 0.75), 1.0], [2.55, tr.vR, 0.3]], "chiselMarker", "#54c4ff", tr.glowW, 10, 0.5);
    fisheyeSpline([[-2.5, tr.vL, 0.3], [0.0, lerp(tr.vL, tr.vR, 0.5), 1.1], [2.5, tr.vR, 0.3]], "chiselMarker", "#b5f0ff", tr.glowW * 0.65, 12, 0.5);

    // Twin razor-sharp pure white glowing fluorescent tubes
    let dv = tr.w * 0.36;
    fisheyeSpline([[-2.52, tr.vL - dv, 0.2], [-1.0, lerp(tr.vL, tr.vR, 0.3) - dv, 1.0], [0.2, lerp(tr.vL, tr.vR, 0.55) - dv, 1.15], [1.3, lerp(tr.vL, tr.vR, 0.78) - dv, 0.95], [2.52, tr.vR - dv, 0.2]], "specSlash", "#ffffff", tr.coreW, 10, 0.5);
    fisheyeSpline([[-2.52, tr.vL + dv, 0.2], [-1.0, lerp(tr.vL, tr.vR, 0.3) + dv, 1.0], [0.2, lerp(tr.vL, tr.vR, 0.55) + dv, 1.15], [1.3, lerp(tr.vL, tr.vR, 0.78) + dv, 0.95], [2.52, tr.vR + dv, 0.2]], "specSlash", "#ffffff", tr.coreW * 0.9, 10, 0.5);

    // Dark socket dividers breaking the tube into 3 fixture bays
    for (let bu of [-0.95, 0.35, 1.55]) {
      let bv = lerp(tr.vL, tr.vR, (bu + 2.5) / 5.0);
      fisheyeSpline([[bu, bv - tr.w * 1.1, 1], [bu + 0.04, bv + tr.w * 1.1, 1]], "rotring", "#070c14", 1.1, 4, 0.2);
    }
  }
}

