// STAGE 4: EXTREME RIM PINCHING, ROLLED LIP BEZEL & SPECULAR SLASHES
// ---------------------------------------------------------------------------
function drawRimPinchReflections() {
  // Around the outer 7% of the ladle bowl (radScale 0.93 to 1.005), the steel rolls
  // into the lip bezel. Reflections compress into high-contrast concentric streaks
  // that pinch at the left (180°), right (0°), and top neck (-84°).

  function drawRimArc(degStart, degEnd, radScale, brushName, col, weight, step = 4) {
    let pts = [];
    for (let d = degStart; d <= degEnd; d += step) {
      let pt = getBowlContourPt(d, radScale);
      let t = (d - degStart) / Math.max(1, degEnd - degStart);
      let press = Math.sin(t * Math.PI) * 1.15 + 0.15;
      pts.push([pt[0], pt[1], press]);
    }
    drawScreenSpline(pts, brushName, col, weight, 0.45);
  }

  // Deep inky near-black outer rim groove (creates extreme contrast at the rolled lip)
  drawRimArc(-75, 255, 0.992, "chiselMarker", "#04070d", 1.35, 4);
  drawRimArc(75, 290, 0.992, "chiselMarker", "#04070d", 1.35, 4);
  drawRimArc(0, 360, 0.968, "rotring", "#050912", 1.1, 4);

  // Compressed secondary reflection bands inside the rolled lip bezel:
  // Upper-left & left rim: compressed cyan sky & blinding fluorescent white
  drawRimArc(145, 258, 0.978, "chiselMarker", "#5fd0ff", 1.25, 4);
  drawRimArc(152, 252, 0.984, "specSlash", "#ffffff", 1.35, 4);
  drawRimArc(165, 235, 0.956, "specSlash", "#d6f6ff", 0.95, 4);

  // Upper-right & right rim: compressed steel hood, cyan tubes & sharp white rim slash
  drawRimArc(-72, 42, 0.978, "chiselMarker", "#4a8ab8", 1.2, 4);
  drawRimArc(-62, 32, 0.985, "specSlash", "#ffffff", 1.3, 4);
  drawRimArc(-45, 22, 0.958, "specSlash", "#bfeaff", 0.9, 4);

  // Lower-left & lower-right rim: compressed crimson-red vinyl stool streaks pinching along the bottom edge
  drawRimArc(25, 155, 0.976, "chiselMarker", "#9e081c", 1.25, 4);
  drawRimArc(38, 142, 0.962, "chiselMarker", "#e6122c", 0.95, 4);
  drawRimArc(48, 132, 0.985, "specSlash", "#ffccd4", 1.0, 4);
  drawRimArc(62, 118, 0.988, "specSlash", "#ffffff", 1.25, 4);

  // Outer extreme edge specular wire (the very lip of the stainless bowl against the blurred tile)
  drawRimArc(-72, 65, 1.001, "specSlash", "#ffffff", 0.95, 4);
  drawRimArc(115, 255, 1.001, "specSlash", "#f0faff", 0.9, 4);
  drawRimArc(55, 125, 1.001, "rotring", "#101924", 0.9, 4);

  // Pouring-lip double-highlight flare at left (195°) and right (-15°)
  drawRimArc(178, 214, 0.995, "specSlash", "#ffffff", 1.55, 3);
  drawRimArc(-32, 8, 0.995, "specSlash", "#ffffff", 1.55, 3);
}

function drawBowlSpecularSlashes() {
  // Grazing-angle pure white specular slashes and micro-polishing hairlines across the convex dome
  // 1. Blinding upper-left dome bloom where overhead fluorescent light hits the steel curvature
  fisheyeSpline([[-1.65, -0.92, 0.2], [-1.05, -0.78, 1.35], [-0.45, -0.68, 0.3]], "specSlash", "#ffffff", 1.9, 8, 0.5);
  fisheyeSpline([[-1.55, -0.52, 0.2], [-0.95, -0.44, 1.25], [-0.38, -0.39, 0.3]], "specSlash", "#ffffff", 1.6, 8, 0.5);

  // 2. Fine circular brushed/polished steel micro-scratches catching light around the specular hotspots
  for (let i = 0; i < 28; i++) {
    let baseDeg = random(185, 250);
    let span = random(14, 34);
    let rScale = random(0.42, 0.92);
    let pts = [];
    for (let d = baseDeg; d <= baseDeg + span; d += 4) {
      let pt = getBowlContourPt(d, rScale);
      let t = (d - baseDeg) / span;
      pts.push([pt[0], pt[1], Math.sin(t * Math.PI) * 0.9]);
    }
    let col = i % 3 === 0 ? "#ffffff" : "#9bdcff";
    drawScreenSpline(pts, "steelGrain", col, random(0.45, 0.85), 0.4);
  }

  for (let i = 0; i < 22; i++) {
    let baseDeg = random(-65, -10);
    let span = random(12, 30);
    let rScale = random(0.48, 0.93);
    let pts = [];
    for (let d = baseDeg; d <= baseDeg + span; d += 4) {
      let pt = getBowlContourPt(d, rScale);
      let t = (d - baseDeg) / span;
      pts.push([pt[0], pt[1], Math.sin(t * Math.PI) * 0.85]);
    }
    let col = i % 2 === 0 ? "#ffffff" : "#8bc8ed";
    drawScreenSpline(pts, "steelGrain", col, random(0.45, 0.8), 0.4);
  }

  // 3. Razor-sharp star-glints at peak specular points (rim lip, counter chrome, stool ring)
  let glintCenters = [
    roomToBowl(-0.92, -0.75),
    roomToBowl(-0.52, 0.33),
    roomToBowl(0.32, 0.33),
    roomToBowl(-0.46, 0.46),
    getBowlContourPt(198, 0.988),
    getBowlContourPt(-16, 0.988)
  ];

  for (let g of glintCenters) {
    let gx = Array.isArray(g) ? g[0] : g.x;
    let gy = Array.isArray(g) ? g[1] : g.y;
    drawScreenSpline([[gx - 18, gy, 0.1], [gx, gy, 1.3], [gx + 18, gy, 0.1]], "specSlash", "#ffffff", 0.85, 0.1);
    drawScreenSpline([[gx, gy - 14, 0.1], [gx, gy, 1.2], [gx, gy + 14, 0.1]], "specSlash", "#ffffff", 0.75, 0.1);
  }
}

// ---------------------------------------------------------------------------
// STAGE 5: BRUSHED-STEEL HANDLE, FORGED NECK & WALL HOOK
// ---------------------------------------------------------------------------
// Helper to compute centerline and half-width of the ladle handle from y = 65 (hook) to y = 435 (bowl neck)
function getHandleSection(t) {
  // t = 0 at top hook bend (y = 68), t = 1 at forged bowl neck (y = 432)
  let y = lerp(68, 432, t);
  // Slight natural tilt (~7.5 degrees) from top-right hook down to bowl neck
  let cx = lerp(646, 594, t) + Math.sin(t * Math.PI) * 3.5;

  // Handle flares at the top hook (t < 0.18), narrows in middle shaft, and flares into a teardrop tang at bowl (t > 0.76)
  let halfW = 24;
  if (t < 0.2) {
    halfW = lerp(31, 23, t / 0.2);
  } else if (t < 0.74) {
    halfW = lerp(23, 25, (t - 0.2) / 0.54);
  } else {
    let nt = (t - 0.74) / 0.26;
    halfW = 25 + 38 * Math.pow(nt, 1.85);
  }
  return { cx, y, halfW };
}

