  ], "#1c2836", 245, 0.2);
  drawScreenSpline([[642, 12, 0.9], [646, 52, 1.1], [642, 84, 0.9]], "specSlash", "#e3f2fc", 1.1, 0.3);
  drawScreenSpline([[656, 12, 0.9], [660, 52, 1.1], [654, 84, 0.9]], "rotring", "#060b12", 0.9, 0.3);
}

function drawLadleHandleAndNeck() {
  // Build handle polygon outline including the curved teardrop mounting tang at the bottom (t = 1.0)
  let leftEdge = [];
  let rightEdge = [];
  let steps = 36;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let sec = getHandleSection(t);
    leftEdge.push([sec.cx - sec.halfW, sec.y]);
    rightEdge.push([sec.cx + sec.halfW, sec.y]);
  }

  // Bottom teardrop weld contour curving onto the upper dome of the bowl
  let bottomCurve = [
    [594 + 63, 432],
    [594 + 44, 456],
    [594 + 16, 468],
    [594 - 16, 468],
    [594 - 44, 456],
    [594 - 63, 432]
  ];

  let fullHandlePoly = [...leftEdge, ...bottomCurve.reverse(), ...rightEdge.reverse()];

  // 1. Base brushed-steel midtone & dark shadow edges of the handle
  drawWashPoly(fullHandlePoly, "#4e6782", 252, 0.15);

  // Left bevel (lit by cool window light), center recessed channel, right bevel (in deep contrast)
  let leftBevelPoly = [];
  let centerChannelPoly = [];
  let rightBevelPoly = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let sec = getHandleSection(t);
    leftBevelPoly.push([sec.cx - sec.halfW, sec.y]);
    centerChannelPoly.push([sec.cx - sec.halfW * 0.42, sec.y]);
    rightBevelPoly.push([sec.cx + sec.halfW * 0.38, sec.y]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let sec = getHandleSection(t);
    leftBevelPoly.push([sec.cx - sec.halfW * 0.42, sec.y]);
    centerChannelPoly.push([sec.cx + sec.halfW * 0.38, sec.y]);
    rightBevelPoly.push([sec.cx + sec.halfW, sec.y]);
  }

  drawWashPoly(leftBevelPoly, "#a8c5de", 240, 0.1);
  drawWashPoly(centerChannelPoly, "#25394f", 240, 0.1);
  drawWashPoly(rightBevelPoly, "#121f2e", 245, 0.1);

  // Bright longitudinal highlight band inside the stamped center channel (right side of channel)
  let channelHighlight = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let sec = getHandleSection(t);
    channelHighlight.push([sec.cx + sec.halfW * 0.08, sec.y, 0.9]);
  }
  drawScreenSpline(channelHighlight, "chiselMarker", "#cde4f7", 1.35, 0.3);

  // 2. Transverse marker shading bands (horizon & ceiling reflections warped along the channelled handle)
  let bandRanges = [
    { t1: 0.02, t2: 0.11, col: "#09111c", op: 225 }, // dark shadow under top hook curve
    { t1: 0.11, t2: 0.19, col: "#e8f6ff", op: 220 }, // bright top bend reflection
    { t1: 0.28, t2: 0.38, col: "#7da2c4", op: 185 },
    { t1: 0.48, t2: 0.56, col: "#142336", op: 190 },
    { t1: 0.68, t2: 0.79, col: "#b8d7f0", op: 210 },
    { t1: 0.80, t2: 0.92, col: "#0c1624", op: 230 }, // dark neck bend inflection
    { t1: 0.92, t2: 1.00, col: "#d9effc", op: 220 }  // bright weld boss flare
  ];

  for (let br of bandRanges) {
    let s1 = getHandleSection(br.t1);
    let s2 = getHandleSection(br.t2);
    drawWashPoly([
      [s1.cx - s1.halfW * 0.92, s1.y],
      [s1.cx + s1.halfW * 0.92, s1.y],
      [s2.cx + s2.halfW * 0.92, s2.y],
      [s2.cx - s2.halfW * 0.92, s2.y]
    ], br.col, br.op, 0.1);
  }

  // 3. FINE BRUSHED-STEEL SCRATCHES running along the handle
  // Hundreds of fine longitudinal hairlines in cool silver, slate, charcoal, and pure white
  let numScratches = 135;
  for (let s = 0; s < numScratches; s++) {
    let lane = random(-0.92, 0.92);
    let tStart = random(0.03, 0.72);
    let tEnd = Math.min(1.0, tStart + random(0.18, 0.52));
    let scratchPts = [];
    let segs = 6;
    for (let k = 0; k <= segs; k++) {
      let tk = lerp(tStart, tEnd, k / segs);
      let sec = getHandleSection(tk);
      let sx = sec.cx + lane * sec.halfW;
      let sy = sec.y + (tk > 0.82 ? (1 - Math.abs(lane)) * 18 * ((tk - 0.82) / 0.18) : 0);
      let press = Math.sin((k / segs) * Math.PI) * 0.95 + 0.1;
      scratchPts.push([sx, sy, press]);
    }

    // Choose scratch color based on bevel zone for authentic metallic anisotropy
    let scratchCol;
    let scratchW = random(0.35, 0.78);
    if (lane < -0.45) {
      scratchCol = s % 3 === 0 ? "#ffffff" : (s % 2 === 0 ? "#d0e8fa" : "#415b76");
    } else if (lane < 0.0) {
      scratchCol = s % 4 === 0 ? "#9ec0de" : (s % 2 === 0 ? "#101b29" : "#304761");
    } else if (lane < 0.35) {
      scratchCol = s % 2 === 0 ? "#ffffff" : "#799ec2";
    } else {
      scratchCol = s % 4 === 0 ? "#85a8c9" : "#070c14";
    }
    drawScreenSpline(scratchPts, "steelGrain", scratchCol, scratchW, 0.25);
  }

  // Cross-grain micro-scratches near the neck bend where metal was stamped
  for (let c = 0; c < 18; c++) {
    let tc = random(0.76, 0.98);
    let sec = getHandleSection(tc);
    let x1 = sec.cx - sec.halfW * random(0.3, 0.85);
    let x2 = sec.cx + sec.halfW * random(0.3, 0.85);
    let ym = sec.y + random(4, 14);
    let col = c % 2 === 0 ? "#ffffff" : "#122030";
    drawScreenSpline([[x1, sec.y, 0.2], [(x1 + x2) * 0.5, ym, 0.9], [x2, sec.y, 0.2]], "steelGrain", col, 0.5, 0.4);
  }

  // 4. Forged Teardrop Neck Boss, Spot-Weld Dimples & Crisp Rim-to-Handle Junction
  // Dark shadow crescent under the teardrop boss on the bowl dome
  drawScreenSpline([
    [594 - 62, 432, 0.4],
    [594 - 38, 460, 1.1],
    [594, 471, 1.25],
    [594 + 38, 460, 1.1],
    [594 + 62, 432, 0.4]
  ], "rotring", "#05080f", 1.35, 0.45);

  drawScreenSpline([
    [594 - 56, 430, 0.4],
    [594 - 32, 454, 1.1],
    [594, 464, 1.3],
    [594 + 32, 454, 1.1],
    [594 + 56, 430, 0.4]
  ], "specSlash", "#ffffff", 1.15, 0.45);

  // Two authentic circular spot-weld indentations on the mounting tang
  for (let wx of [594 - 18, 594 + 18]) {
    let wy = 436;
    drawScreenSpline([[wx - 8, wy - 2, 0.6], [wx, wy - 7, 1.0], [wx + 8, wy - 2, 0.6]], "rotring", "#0c1624", 0.85, 0.4);
    drawScreenSpline([[wx - 8, wy + 2, 0.6], [wx, wy + 7, 1.0], [wx + 8, wy + 2, 0.6]], "specSlash", "#ffffff", 0.85, 0.4);
  }

  // 5. Razor-sharp left and right stamped edges & center channel ridges of the handle
  let leftRimPts = [];
  let leftRidgePts = [];
  let rightRidgePts = [];
  let rightRimPts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let sec = getHandleSection(t);
    leftRimPts.push([sec.cx - sec.halfW, sec.y, 1.0]);
    leftRidgePts.push([sec.cx - sec.halfW * 0.42, sec.y, 1.05]);
    rightRidgePts.push([sec.cx + sec.halfW * 0.36, sec.y, 1.05]);
    rightRimPts.push([sec.cx + sec.halfW, sec.y, 1.0]);
  }

  drawScreenSpline(leftRimPts, "specSlash", "#ffffff", 1.25, 0.3);
  drawScreenSpline(leftRidgePts, "specSlash", "#ffffff", 1.1, 0.3);
  drawScreenSpline(rightRidgePts, "rotring", "#060b13", 1.05, 0.3);
  drawScreenSpline(rightRimPts, "rotring", "#05080f", 1.2, 0.3);

  // Thin secondary specular reflection along the extreme right edge of the handle
  let rightEdgeGlint = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let sec = getHandleSection(t);
    rightEdgeGlint.push([sec.cx + sec.halfW - 2.2, sec.y, 0.85]);
  }
  drawScreenSpline(rightEdgeGlint, "specSlash", "#c9e6ff", 0.75, 0.3);
}

