// ============================================================================
// GEOMETRY & RELIEF HELPERS
// ============================================================================

function tracePoly(pts, curv = 0.12, closeShape = true) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

function makeRoundedBlock(x, y, w, h, r, nPerCorner = 3, wobble = 1.2) {
  let pts = [];
  let corners = [
    [x + w - r, y + r, -90, 0],
    [x + w - r, y + h - r, 0, 90],
    [x + r, y + h - r, 90, 180],
    [x + r, y + r, 180, 270]
  ];
  for (let c = 0; c < 4; c++) {
    let [cx, cy, a0, a1] = corners[c];
    for (let i = 0; i <= nPerCorner; i++) {
      let a = lerp(a0, a1, i / nPerCorner);
      let px = cx + cos(a) * r + (noise(cx * 0.02 + i, cy * 0.02) - 0.5) * wobble * 2;
      let py = cy + sin(a) * r + (noise(cy * 0.02 + i, cx * 0.02) - 0.5) * wobble * 2;
      pts.push([px, py]);
    }
  }
  return pts;
}

function offsetPts(pts, dx, dy) {
  return pts.map(p => [p[0] + dx, p[1] + dy]);
}

// Draws a 3D carved relief polygon with raking upper-left bevel and lower-right undercut
function drawCarvedReliefStroke(pts, undercutDepth = 6, weightScale = 1.0) {
  let n = pts.length;
  // Pass 1: Deep lower-right undercut edges
  for (let i = 0; i < n; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % n];
    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len = sqrt(dx * dx + dy * dy);
    if (len < 1) continue;
    // Outward normal for clockwise polygon
    let nx = dy / len;
    let ny = -dx / len;
    let dotL = nx * LX + ny * LY;

    if (dotL < -0.05) {
      let shAmt = map(dotL, -0.05, -1, 0.3, 1.0, true);
      let off = undercutDepth * shAmt;
      brush.set("charcoal", PAL.abyss, (1.1 + shAmt * 1.4) * weightScale);
      brush.line(p1[0] + off * 0.65, p1[1] + off * 0.65, p2[0] + off * 0.65, p2[1] + off * 0.65);
      brush.set("2B", PAL.undercut, (0.8 + shAmt * 0.9) * weightScale);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    } else if (dotL > 0.1) {
      let hiAmt = map(dotL, 0.1, 1, 0.3, 1.0, true);
      brush.set("chalk_highlight", PAL.stoneHighlight, (0.65 + hiAmt * 0.95) * weightScale);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.set("2H", PAL.stoneMid, 0.45 * weightScale);
      brush.line(p1[0] - nx * 1.5, p1[1] - ny * 1.5, p2[0] - nx * 1.5, p2[1] - ny * 1.5);
    } else {
      brush.set("HB", PAL.stoneDark, 0.55 * weightScale);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

// Draws an individual hyperreal sequin with undercut, cupped body, stitch hole, and specular glint
function drawSequin(x, y, r, lightBias = 0.5, tintHex = PAL.sangSoft) {
  // Undercut shadow arc on lower-right
  brush.set("chisel_fine", PAL.abyss, 0.75);
  brush.arc(x + r * 0.28, y + r * 0.28, r * 0.95, -25, 115);

  // Cupped metallic/nacreous rim
  brush.set("chisel_fine", tintHex, 0.85);
  brush.circle(x, y, r * 0.88, 0.12);

  // Raking highlight facet on upper-left
  if (lightBias > 0.22) {
    let hiCol = lightBias > 0.62 ? PAL.chromeSpec : PAL.stoneHighlight;
    brush.set("chalk_highlight", hiCol, 0.55 + lightBias * 0.55);
    brush.arc(x - r * 0.12, y - r * 0.12, r * 0.65, 165, 305);
    if (lightBias > 0.72) {
      brush.set("chalk_highlight", PAL.chromeSpec, 0.8);
      brush.line(x - r * 0.45, y - r * 0.45, x - r * 0.15, y - r * 0.15);
    }
  } else {
    brush.set("2H", PAL.stoneMid, 0.5);
    brush.arc(x - r * 0.1, y - r * 0.1, r * 0.6, 175, 290);
  }

  // Central thread pinhole & stitch tick
  brush.set("rotring", PAL.abyss, 0.65);
  brush.line(x - 0.8, y - 0.8, x + 0.9, y + 0.9);
}

// Draws a stitched leather/stone seam along a polyline
function drawStitchedSeam(pts, stitchStep = 8, stitchWidth = 4.5, doubleRow = true) {
  // 1. Deep incised seam channel
  brush.set("rotring", PAL.abyss, 0.95);
  brush.spline(pts, 0.35);

  // 2. Raised welt highlight on upper-left side & shadow on lower-right
  let weltHi = pts.map(p => [p[0] - 1.8, p[1] - 1.5]);
  let weltSh = pts.map(p => [p[0] + 1.8, p[1] + 1.5]);
  brush.set("chalk_highlight", PAL.stoneLight, 0.65);
  brush.spline(weltHi, 0.35);
  brush.set("2B", PAL.undercut, 0.65);
  brush.spline(weltSh, 0.35);

  // 3. Individual thread stitches along path
  for (let i = 0; i < pts.length - 1; i++) {
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let segLen = sqrt(dx * dx + dy * dy);
    if (segLen < 1) continue;
    let ux = dx / segLen;
    let uy = dy / segLen;
    let nx = -uy;
    let ny = ux;
    let steps = max(1, floor(segLen / stitchStep));

    for (let s = 0; s < steps; s++) {
      let t = (s + 0.5) / steps;
      let sx = lerp(p1[0], p2[0], t);
      let sy = lerp(p1[1], p2[1], t);

      if (doubleRow) {
        // Left row saddle stitch
        let lx1 = sx + nx * stitchWidth - ux * (stitchStep * 0.28);
        let ly1 = sy + ny * stitchWidth - uy * (stitchStep * 0.28);
        let lx2 = sx + nx * (stitchWidth * 0.65) + ux * (stitchStep * 0.28);
        let ly2 = sy + ny * (stitchWidth * 0.65) + uy * (stitchStep * 0.28);
        brush.set("rotring", PAL.undercut, 0.55);
        brush.line(lx1 + 0.7, ly1 + 0.7, lx2 + 0.7, ly2 + 0.7);
        brush.set("chalk_highlight", PAL.stoneHighlight, 0.52);
        brush.line(lx1, ly1, lx2, ly2);

        // Right row saddle stitch
        let rx1 = sx - nx * stitchWidth - ux * (stitchStep * 0.28);
        let ry1 = sy - ny * stitchWidth - uy * (stitchStep * 0.28);
        let rx2 = sx - nx * (stitchWidth * 0.65) + ux * (stitchStep * 0.28);
        let ry2 = sy - ny * (stitchWidth * 0.65) + uy * (stitchStep * 0.28);
        brush.set("rotring", PAL.undercut, 0.55);
        brush.line(rx1 + 0.7, ry1 + 0.7, rx2 + 0.7, ry2 + 0.7);
        brush.set("chalk_highlight", PAL.stoneLight, 0.48);
        brush.line(rx1, ry1, rx2, ry2);
      } else {
        // Cross whip-stitch
        let x1 = sx - nx * stitchWidth;
        let y1 = sy - ny * stitchWidth;
        let x2 = sx + nx * stitchWidth;
        let y2 = sy + ny * stitchWidth;
        brush.set("rotring", PAL.undercut, 0.6);
        brush.line(x1 + 0.8, y1 + 0.8, x2 + 0.8, y2 + 0.8);
        brush.set("chalk_highlight", PAL.stoneHighlight, 0.55);
        brush.line(x1, y1, x2, y2);
      }
    }
  }
}

