function drawGlyphColumns() {
  let glyphBoxes = [];

  // Left outer vertical column (6 stacked glyph blocks)
  for (let r = 0; r < 6; r++) {
    glyphBoxes.push({ x: 138, y: 62 + r * 172, w: 148, h: 158, type: r % 6, seed: r * 17 + 1 });
  }
  // Right outer vertical column (6 stacked glyph blocks)
  for (let r = 0; r < 6; r++) {
    glyphBoxes.push({ x: 902, y: 62 + r * 172, w: 148, h: 158, type: (r + 3) % 6, seed: r * 23 + 50 });
  }
  // Inner flanking glyph blocks (crowding around headdress, waist, and boots)
  glyphBoxes.push({ x: 298, y: 62, w: 130, h: 136, type: 1, seed: 101 });
  glyphBoxes.push({ x: 298, y: 210, w: 130, h: 136, type: 4, seed: 102 });
  glyphBoxes.push({ x: 760, y: 62, w: 130, h: 136, type: 2, seed: 103 });
  glyphBoxes.push({ x: 760, y: 210, w: 130, h: 136, type: 5, seed: 104 });

  glyphBoxes.push({ x: 298, y: 748, w: 124, h: 168, type: 0, seed: 105 });
  glyphBoxes.push({ x: 298, y: 928, w: 124, h: 168, type: 3, seed: 106 });
  glyphBoxes.push({ x: 766, y: 748, w: 124, h: 168, type: 4, seed: 107 });
  glyphBoxes.push({ x: 766, y: 928, w: 124, h: 168, type: 1, seed: 108 });

  // Batch 1: Sunken inter-glyph channel shadows
  brush.noStroke();
  brush.fill(PAL.undercut, 155);
  brush.fillBleed(0.08, "out");
  for (let g of glyphBoxes) {
    let shPts = makeRoundedBlock(g.x + 6, g.y + 6, g.w, g.h, 16, 2, 1.5);
    tracePoly(shPts, 0.12, true);
  }

  // Batch 2: Raised limestone glyph cartouche tablets
  brush.fill(PAL.stoneBase, 190);
  brush.fillBleed(0.1, "in");
  for (let g of glyphBoxes) {
    let pts = makeRoundedBlock(g.x, g.y, g.w, g.h, 16, 2, 1.5);
    g.pts = pts;
    tracePoly(pts, 0.12, true);
  }
  brush.noFill();

  // Batch 3: Carve each glyph block in high relief
  for (let g of glyphBoxes) {
    drawSingleMayaGlyph(g);
  }
}

function drawSingleMayaGlyph(g) {
  let { x, y, w, h, type, seed } = g;

  // Outer cartouche bevel & undercut
  drawCarvedReliefStroke(g.pts, 6, 0.85);

  // Inner recessed field
  let pad = 12;
  let ix = x + pad;
  let iy = y + pad;
  let iw = w - pad * 2;
  let ih = h - pad * 2;

  // Bar-and-dot Maya numeral along left margin of cartouche
  let numBars = 1 + (seed % 2);
  let numDots = 1 + (seed % 4);
  let dotSpan = ih / (numDots + 1);

  for (let d = 1; d <= numDots; d++) {
    let dx = ix + 7;
    let dy = iy + d * dotSpan;
    brush.set("charcoal", PAL.abyss, 0.9);
    brush.arc(dx + 2, dy + 2, 6, -30, 120);
    brush.set("2B", PAL.stoneDark, 0.7);
    brush.circle(dx, dy, 5.5, 0.15);
    brush.set("chalk_highlight", PAL.stoneHighlight, 0.7);
    brush.arc(dx - 1, dy - 1, 4.5, 160, 300);
  }

  for (let b = 0; b < numBars; b++) {
    let bx = ix + 17 + b * 10;
    let barPts = makeRoundedBlock(bx, iy + 4, 7, ih - 8, 3, 1, 0.6);
    drawCarvedReliefStroke(barPts, 3.5, 0.65);
    // Incised double lines at top/bottom of numeral bar
    brush.set("rotring", PAL.undercut, 0.55);
    brush.line(bx + 1, iy + 18, bx + 6, iy + 18);
    brush.line(bx + 1, iy + ih - 18, bx + 6, iy + ih - 18);
  }

  // Main glyph block area to the right of numerals
  let gx = ix + 18 + numBars * 10;
  let gy = iy + 2;
  let gw = iw - (18 + numBars * 10);
  let gh = ih - 4;

  // Main lobular cartouche head
  let mainLobe = makeRoundedBlock(gx, gy, gw, gh * 0.72, 14, 2, 1.0);
  drawCarvedReliefStroke(mainLobe, 4.5, 0.75);

  // Subfix lobules below main head
  let subLobeL = makeRoundedBlock(gx, gy + gh * 0.76, gw * 0.47, gh * 0.24, 6, 1, 0.6);
  let subLobeR = makeRoundedBlock(gx + gw * 0.53, gy + gh * 0.76, gw * 0.47, gh * 0.24, 6, 1, 0.6);
  drawCarvedReliefStroke(subLobeL, 3.5, 0.6);
  drawCarvedReliefStroke(subLobeR, 3.5, 0.6);

  // Cross-hatched sunken pocket inside glyph (authentic Classic Maya limestone motif)
  brush.hatchStyle("2H", PAL.undercut, 0.5);
  brush.hatch(4.5, 45, { rand: 0.05 });
  brush.noStroke();
  brush.circle(gx + gw * 0.35, gy + gh * 0.32, min(gw, gh) * 0.16, 0.1);
  brush.noHatch();

  // Specific Maya-Lucha hybrid iconography inside main lobe
  let cx = gx + gw * 0.5;
  let cy = gy + gh * 0.36;

  if (type === 0 || type === 3) {
    // Stylized Masked Lord / Jaguar profile with scroll eye & teeth
    brush.set("rotring", PAL.abyss, 0.75);
    brush.arc(cx - 4, cy - 6, 12, 0, 270);
    brush.set("chalk_highlight", PAL.stoneHighlight, 0.65);
    brush.arc(cx - 5, cy - 7, 10, 170, 310);
    // Earflare & speech scroll
    let earPts = makeRoundedBlock(gx + gw * 0.68, gy + gh * 0.18, gw * 0.22, gh * 0.32, 5, 1, 0.5);
    drawCarvedReliefStroke(earPts, 3, 0.55);
    // Teeth / jaw nodules
    for (let t = 0; t < 3; t++) {
      brush.set("rotring", PAL.undercut, 0.6);
      brush.rect(gx + 8 + t * 9, gy + gh * 0.52, 7, 8, "corner");
    }
  } else if (type === 1 || type === 4) {
    // Clenched Wrestler Fist Glyph (K'awiil / Tok' Pakal hand)
    let thumbPts = makeRoundedBlock(gx + 8, gy + 10, gw * 0.42, gh * 0.22, 6, 1, 0.5);
    drawCarvedReliefStroke(thumbPts, 3, 0.55);
    for (let k = 0; k < 3; k++) {
      let knPts = makeRoundedBlock(gx + gw * 0.52, gy + 10 + k * (gh * 0.18), gw * 0.36, gh * 0.15, 4, 1, 0.4);
      drawCarvedReliefStroke(knPts, 2.5, 0.5);
    }
    // Jade spiral on back of hand
    brush.set("rotring", PAL.undercut, 0.65);
    brush.arc(gx + gw * 0.32, gy + gh * 0.48, 9, 0, 300);
  } else {
    // K'in (Four-petalled Sun / Wrestling Ring Star) glyph
    brush.set("rotring", PAL.undercut, 0.7);
    brush.circle(cx, cy, min(gw, gh) * 0.24, 0.1);
    for (let a = 45; a < 360; a += 90) {
      let px = cx + cos(a) * min(gw, gh) * 0.24;
      let py = cy + sin(a) * min(gw, gh) * 0.24;
      brush.line(cx + cos(a) * 6, cy + sin(a) * 6, px, py);
    }
    brush.set("chalk_highlight", PAL.stoneHighlight, 0.65);
    brush.arc(cx - 2, cy - 2, min(gw, gh) * 0.21, 160, 290);
  }
}

// ============================================================================
// 3. TOWERING FEATHERED HEADDRESS (PENACHO)
// ============================================================================

function drawFeatherHeaddress() {
  let cx = 600;
  let cy = 245;

  // Tier 1: Long outer arching Quetzal plumes fanning across the top of the stele
  let outerCount = 26;
  for (let i = 0; i < outerCount; i++) {
    let f = i / (outerCount - 1);
    // Fan from left (-175 deg) across top (-90 deg) to right (-5 deg)
    let baseAngle = lerp(-174, -6, f);
    let len = 240 + sin(f * 180) * 85 + (i % 2) * 18;
    // Droop at tips away from center
    let droop = (f - 0.5) * 62;
    let r0 = 88;

    let x0 = cx + cos(baseAngle) * r0;
    let y0 = cy + sin(baseAngle) * (r0 * 0.85);
    let midAngle = baseAngle + droop * 0.35;
    let tipAngle = baseAngle + droop;

    let x1 = x0 + cos(baseAngle) * (len * 0.38);
    let y1 = y0 + sin(baseAngle) * (len * 0.36);
    let x2 = x1 + cos(midAngle) * (len * 0.36);
    let y2 = y1 + sin(midAngle) * (len * 0.34);
    let x3 = x2 + cos(tipAngle) * (len * 0.3);
    let y3 = y2 + sin(tipAngle) * (len * 0.3);

    let spine = [[x0, y0], [x1, y1], [x2, y2], [x3, y3]];
    let isLeftLit = f < 0.62;
    let plumeTone = i % 3 === 0 ? PAL.pastelJade : (i % 3 === 1 ? PAL.sangSoft : PAL.pastelOchre);

    drawSculptedFeather(spine, 22, plumeTone, isLeftLit);
  }

  // Tier 2: Mid-tier stiffer Eagle / Macaw plumes with notched vanes
  let midCount = 19;
  for (let i = 0; i < midCount; i++) {
    let f = i / (midCount - 1);
    let baseAngle = lerp(-166, -14, f);
    let len = 148 + sin(f * 180) * 42;
    let droop = (f - 0.5) * 28;
    let r0 = 76;

    let x0 = cx + cos(baseAngle) * r0;
    let y0 = cy + sin(baseAngle) * (r0 * 0.85);
    let x1 = x0 + cos(baseAngle) * (len * 0.45);
    let y1 = y0 + sin(baseAngle) * (len * 0.45);
    let x2 = x1 + cos(baseAngle + droop * 0.5) * (len * 0.35);
    let y2 = y1 + sin(baseAngle + droop * 0.5) * (len * 0.35);
    let x3 = x2 + cos(baseAngle + droop) * (len * 0.25);
    let y3 = y2 + sin(baseAngle + droop) * (len * 0.25);

    let spine = [[x0, y0], [x1, y1], [x2, y2], [x3, y3]];
    let plumeTone = i % 2 === 0 ? PAL.sangMid : PAL.stoneOchre;
    drawSculptedFeather(spine, 18, plumeTone, f < 0.65);
  }

  // Tier 3: Inner collar of carved stone/jade tubular beads & sequin rosettes framing the mask
  let beadCount = 17;
  for (let i = 0; i < beadCount; i++) {
    let f = i / (beadCount - 1);
    let a = lerp(-162, -18, f);
    let bx = cx + cos(a) * 92;
    let by = cy + sin(a) * 82;
    let bx2 = cx + cos(a) * 118;
    let by2 = cy + sin(a) * 106;

    // Tubular jade-limestone bead
    brush.set("charcoal", PAL.abyss, 2.2);
    brush.line(bx + 4, by + 4, bx2 + 4, by2 + 4);
    brush.set("marker", i % 2 === 0 ? PAL.pastelJade : PAL.sangSoft, 1.6);
    brush.line(bx, by, bx2, by2);
    brush.set("chalk_highlight", PAL.stoneHighlight, 0.85);
    brush.line(bx - 2, by - 2, bx2 - 2, by2 - 2);

    // Terminal sequin rosette at outer tip of each bead
    drawSequin(bx2, by2, 7.5, 1.0 - f * 0.65, PAL.pastelOchre);
  }
}

function drawSculptedFeather(spine, maxWidth, vaneCol, isLit) {
  // Interpolate points along spine
  let steps = 14;
  let leftEdge = [];
  let rightEdge = [];
  let rachis = [];

  for (let s = 0; s <= steps; s++) {
    let t = s / steps;
    // Piecewise linear interpolation along 4 control points
    let seg = min(2, floor(t * 3));
    let lt = (t * 3) - seg;
    let px = lerp(spine[seg][0], spine[seg + 1][0], lt);
    let py = lerp(spine[seg][1], spine[seg + 1][1], lt);
    rachis.push([px, py]);

    let dx = spine[seg + 1][0] - spine[seg][0];
    let dy = spine[seg + 1][1] - spine[seg][1];
    let dl = max(1, sqrt(dx * dx + dy * dy));
    let nx = -dy / dl;
    let ny = dx / dl;

    let w = maxWidth * sin(pow(t, 0.65) * 172) * (1 - 0.12 * (s === 7 ? 1 : 0));
    leftEdge.push([px + nx * w, py + ny * w]);
    rightEdge.push([px - nx * w, py - ny * w]);
  }

  let featherPoly = leftEdge.concat([...rightEdge].reverse());

  // 1. Deep cast undercut shadow beneath feather
  let shadowEdge = rightEdge.map(p => [p[0] + 6, p[1] + 6]);
  brush.set("charcoal", PAL.abyss, 1.35);
  brush.spline(shadowEdge, 0.35);

  // 2. Soft pastel wash on feather vane
  brush.noStroke();
  brush.fill(vaneCol, isLit ? 95 : 70);
  brush.fillBleed(0.08, "in");
  tracePoly(featherPoly, 0.15, true);
  brush.noFill();

  // 3. Individual diagonal feather barbs (hyperreal texture)
  for (let s = 1; s < steps; s++) {
    let cPt = rachis[s];
    let nPt = rachis[min(steps, s + 1)];
    let lPt = leftEdge[s];
    let rPt = rightEdge[s];

    // Upper-left vane barbs (brighter)
    brush.set("chisel_fine", isLit ? PAL.stoneHighlight : PAL.stoneLight, 0.6);
    brush.line(cPt[0], cPt[1], lerp(lPt[0], nPt[0], 0.25), lerp(lPt[1], nPt[1], 0.25));
    brush.set("2H", PAL.stoneDark, 0.45);
    brush.line(cPt[0] + 1, cPt[1] + 1, lPt[0], lPt[1]);

    // Lower-right vane barbs (shadowed)
    brush.set("2B", PAL.undercut, 0.65);
    brush.line(cPt[0], cPt[1], lerp(rPt[0], nPt[0], 0.25), lerp(rPt[1], nPt[1], 0.25));
  }

  // 4. Outer vane contour & central raised quill (rachis)
  brush.set("2B", PAL.undercut, 0.75);
  brush.spline(rightEdge, 0.3);
  brush.set("chalk_highlight", isLit ? PAL.stoneHighlight : PAL.stoneLight, 0.75);
  brush.spline(leftEdge, 0.3);

  // Central quill shaft: shadow line + bright chalk highlight
  let rachisSh = rachis.map(p => [p[0] + 1.6, p[1] + 1.6]);
  brush.set("rotring", PAL.abyss, 0.8);
  brush.spline(rachisSh, 0.35);
  brush.set("chalk_highlight", PAL.stoneHighlight, 0.9);
  brush.spline(rachis, 0.35);
}

