// 4. CEREMONIAL SEQUINNED & FLUTED CAPE (CAPA)
// ============================================================================

function drawCeremonialCape() {
  // Deep recessed shadow cavity inside the cape behind legs and torso
  let capeCavity = [
    [310, 380], [890, 380], [950, 1085], [250, 1085]
  ];
  brush.noStroke();
  brush.fill(PAL.undercut, 185);
  brush.fillBleed(0.15, "in");
  tracePoly(capeCavity, 0.08, true);
  brush.noFill();

  // Left and Right cascading drapery folds (5 major vertical fluted folds per side)
  let leftFolds = [
    { topX: 300, botX: 238, wTop: 28, wBot: 42, col: PAL.sangSoft, lit: 0.95 },
    { topX: 328, botX: 280, wTop: 26, wBot: 38, col: PAL.stoneBase, lit: 0.85 },
    { topX: 354, botX: 318, wTop: 26, wBot: 38, col: PAL.sangMid, lit: 0.75 },
    { topX: 380, botX: 356, wTop: 26, wBot: 38, col: PAL.stoneMid, lit: 0.65 },
    { topX: 406, botX: 394, wTop: 26, wBot: 38, col: PAL.sangDeep, lit: 0.55 }
  ];

  let rightFolds = [
    { topX: 794, botX: 806, wTop: 26, wBot: 38, col: PAL.sangMid, lit: 0.5 },
    { topX: 820, botX: 844, wTop: 26, wBot: 38, col: PAL.stoneMid, lit: 0.42 },
    { topX: 846, botX: 882, wTop: 26, wBot: 38, col: PAL.sangDeep, lit: 0.35 },
    { topX: 872, botX: 920, wTop: 26, wBot: 38, col: PAL.stoneDark, lit: 0.28 },
    { topX: 900, botX: 962, wTop: 28, wBot: 42, col: PAL.sangDeep, lit: 0.22 }
  ];

  let allFolds = leftFolds.concat(rightFolds);

  for (let f of allFolds) {
    let yTop = 415;
    let yBot = 1075;
    let pts = [
      [f.topX, yTop],
      [f.topX + f.wTop, yTop],
      [f.botX + f.wBot, yBot],
      [f.botX, yBot]
    ];

    // Watercolor wash for fold body
    brush.noStroke();
    brush.fill(f.col, 145);
    brush.fillBleed(0.12, "in");
    tracePoly(pts, 0.08, true);
    brush.noFill();

    // Cross-contour diagonal hatching along the cylindrical drapery fold
    brush.hatchStyle("2B", PAL.undercut, 0.55);
    brush.hatch(6.5, 32, { rand: 0.06, gradient: 0.6 });
    brush.noStroke();
    tracePoly(pts, 0.05, true);
    brush.noHatch();

    // Left raking highlight ridge of the flute
    let ridgeX1 = lerp(f.topX, f.topX + f.wTop, 0.28);
    let ridgeX2 = lerp(f.botX, f.botX + f.wBot, 0.28);
    brush.set("chalk_highlight", f.lit > 0.5 ? PAL.stoneHighlight : PAL.stoneLight, 0.75 + f.lit * 0.7);
    brush.line(ridgeX1, yTop, ridgeX2, yBot);
    brush.set("chalk_highlight", PAL.pastelPeach, 0.65);
    brush.line(f.topX + 2, yTop, f.botX + 2, yBot);

    // Right undercut crease of the flute
    brush.set("charcoal", PAL.abyss, 1.35);
    brush.line(f.topX + f.wTop, yTop, f.botX + f.wBot, yBot);
    brush.set("2B", PAL.sangDeep, 0.9);
    brush.line(f.topX + f.wTop - 4, yTop, f.botX + f.wBot - 4, yBot);
  }

  // Ornate Maya Stepped-Fret (Xicalcoliuhqui) & Sequin Borders down outer edges of Cape
  drawCapeOrnamentalBorder(298, 420, 234, 1068, true);
  drawCapeOrnamentalBorder(902, 420, 966, 1068, false);

  // Heavy Bullion Fringe along bottom hem of cape
  for (let side = 0; side < 2; side++) {
    let xStart = side === 0 ? 236 : 806;
    let xEnd = side === 0 ? 426 : 966;
    for (let x = xStart; x <= xEnd; x += 7.5) {
      let y0 = 1068 + sin(x * 3) * 3;
      let y1 = y0 + 28 + (x % 15 === 0 ? 6 : 0);
      brush.set("rotring", PAL.abyss, 0.75);
      brush.line(x + 2, y0 + 2, x + 1, y1 + 2);
      brush.set("chalk_highlight", side === 0 ? PAL.pastelOchre : PAL.stoneMid, 0.7);
      brush.line(x, y0, x - 1, y1);
    }
  }
}

function drawCapeOrnamentalBorder(x1, y1, x2, y2, isLeft) {
  let steps = 38;
  let dir = isLeft ? 1 : -1;
  let outerSpine = [];
  let innerSpine = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ox = lerp(x1, x2, t);
    let oy = lerp(y1, y2, t);
    let ix = ox + dir * 28;
    let iy = oy;
    outerSpine.push([ox, oy]);
    innerSpine.push([ix, iy]);

    // Double rows of glistening sequins along cape trim
    let lightAmt = isLeft ? lerp(0.95, 0.55, t) : lerp(0.48, 0.22, t);
    drawSequin(ox + dir * 6, oy, 4.8, lightAmt, PAL.pastelOchre);
    drawSequin(ox + dir * 21, oy, 4.5, lightAmt * 0.85, PAL.sangSoft);

    // Maya stepped fret motif between sequin rows every 4 steps
    if (i % 4 === 0 && i < steps - 2) {
      let ny = lerp(y1, y2, (i + 3) / steps);
      let nx = lerp(x1, x2, (i + 3) / steps);
      let mx = (ox + nx) * 0.5 + dir * 13.5;
      let my = (oy + ny) * 0.5;
      brush.set("rotring", PAL.abyss, 0.7);
      brush.rect(mx - 4, my - 6, 8, 12, "corner");
      brush.set("chalk_highlight", PAL.stoneHighlight, 0.65);
      brush.line(mx - 4, my - 6, mx + 4, my - 6);
      brush.line(mx - 4, my - 6, mx - 4, my + 6);
    }
  }

  drawStitchedSeam(outerSpine, 9, 3.5, false);
  drawStitchedSeam(innerSpine, 9, 3.5, false);
}

