function drawShoulderPauldron(cx, cy, isLeft) {
  let dir = isLeft ? -1 : 1;
  // 3 overlapping scalloped armor plates
  for (let tier = 2; tier >= 0; tier--) {
    let w = 135 - tier * 20;
    let h = 48 - tier * 6;
    let px = cx + dir * (tier * 14) - w * 0.5;
    let py = cy - 28 + tier * 18;

    let platePts = makeRoundedBlock(px, py, w, h, 16, 3, 1.2);
    brush.noStroke();
    brush.fill(tier % 2 === 0 ? PAL.sangSoft : PAL.stoneOchre, 195);
    brush.fillBleed(0.08, "in");
    tracePoly(platePts, 0.15, true);
    brush.noFill();

    drawCarvedReliefStroke(platePts, 7, 1.0);

    // Stitched inner border & row of sequins along each pauldron tier
    let numSeq = 9 - tier;
    for (let s = 0; s < numSeq; s++) {
      let f = (s + 0.5) / numSeq;
      let sx = lerp(px + 14, px + w - 14, f);
      let sy = py + h * 0.55 + sin(f * 180) * 6;
      let lit = isLeft ? lerp(0.95, 0.65, f) : lerp(0.6, 0.25, f);
      drawSequin(sx, sy, 5.5, lit, tier === 1 ? PAL.pastelJade : PAL.pastelOchre);
    }
  }

  // Circular Mayan Sun-Clasp Medallion anchoring cape to clavicle
  let mx = isLeft ? 458 : 742;
  let my = 418;
  brush.set("charcoal", PAL.abyss, 1.8);
  brush.arc(mx + 4, my + 4, 30, -30, 125);
  brush.noStroke();
  brush.fill(PAL.pastelOchre, 210);
  brush.circle(mx, my, 28, 0.1);
  brush.noFill();

  // Ring of sequins around medallion
  for (let a = 0; a < 360; a += 30) {
    let sx = mx + cos(a) * 21;
    let sy = my + sin(a) * 21;
    let lit = map(cos(a) * LX + sin(a) * LY, -1, 1, 0.15, 0.95);
    drawSequin(sx, sy, 4.2, lit, PAL.sangSoft);
  }
  // Central cabochon jewel in medallion
  brush.set("rotring", PAL.undercut, 0.85);
  brush.circle(mx, my, 12, 0.08);
  brush.set("chalk_highlight", PAL.chromeSpec, 1.1);
  brush.arc(mx - 2, my - 2, 9, 165, 290);
}

