  brush.noStroke();
  brush.fill(PAL.abyss, 215);
  tracePoly(offsetPts(outerPts, 4.5, 5.0), 0.1, true);

  // 2. Chrome base fill (cool silver-slate)
  brush.fill(PAL.chromeCool, 235);
  tracePoly(outerPts, 0.1, true);

  // Inner cutout of buckle frame (showing dark leather strap inside)
  if (hasProng) {
    let innerPts = makeRoundedBlock(x + frameThick, y + frameThick, w - frameThick * 2, h - frameThick * 2, 4, 1, 0.3);
    brush.fill(PAL.undercut, 225);
    tracePoly(innerPts, 0.08, true);
    brush.noFill();
    drawCarvedReliefStroke(innerPts, 2.5, 0.65);
  } else {
    brush.noFill();
  }

  // 3. Hyperreal Metallic Horizon Reflection Bands across the chrome surface
  // Dark charcoal horizon reflection band cutting diagonally across metal bars
  brush.set("marker", PAL.chromeDark, 1.5);
  brush.line(x + 2, cy - 2, x + frameThick - 1, cy - 4);
  brush.line(x + w - frameThick + 1, cy - 4, x + w - 2, cy - 2);
  brush.set("rotring", PAL.abyss, 0.9);
  brush.line(x + 2, cy + 1, x + frameThick - 1, cy - 1);
  brush.line(x + w - frameThick + 1, cy - 1, x + w - 2, cy + 1);

  // Warm sanguine bounce reflection on bottom inner bevel of chrome
  brush.set("chisel_fine", PAL.sangSoft, 1.1);
  brush.line(x + 6, y + h - 3, x + w - 6, y + h - 3);

  // Outer bevel & undercut of chrome frame
  drawCarvedReliefStroke(outerPts, 4.5, 0.85);

  // Razor-sharp white specular highlights on upper-left chrome rim & corner glints
  brush.set("chalk_highlight", PAL.chromeSpec, 1.35);
  brush.line(x + 5, y + 2.5, x + w - 7, y + 2.5);
  brush.line(x + 2.5, y + 5, x + 2.5, y + h - 7);
  // Starburst specular glint on top-left corner of chrome buckle
  brush.set("chalk_highlight", PAL.chromeSpec, 0.95);
  brush.line(x - 1, y + 4, x + 9, y + 4);
  brush.line(x + 4, y - 1, x + 4, y + 9);

  if (hasProng) {
    // Central vertical roller bar
    brush.set("rotring", PAL.abyss, 1.1);
    brush.line(cx + 2, y + 4, cx + 2, y + h - 4);
    brush.set("marker", PAL.chromeMid, 1.2);
    brush.line(cx, y + 4, cx, y + h - 4);
    brush.set("chalk_highlight", PAL.chromeSpec, 1.0);
    brush.line(cx - 1.5, y + 5, cx - 1.5, y + h * 0.48);

    // Punched grommet hole in leather where prong pokes through
    let holeX = cx - dir * (w * 0.32);
    brush.set("charcoal", PAL.abyss, 1.2);
    brush.circle(holeX, cy, 4.5, 0.05);

    // Heavy Chrome Prong Tongue resting across frame bar
    let prongTipX = cx + dir * (w * 0.42);
    let prongTipY = cy - 2;
    // Drop shadow of prong onto leather & frame
    brush.set("rotring", PAL.abyss, 1.2);
    brush.line(holeX + 2, cy + 3.5, prongTipX + 2, prongTipY + 3.5);
    // Chrome prong shaft
    brush.set("marker", PAL.chromeMid, 1.3);
    brush.line(holeX, cy, prongTipX, prongTipY);
    // Razor-sharp white highlight along top edge of prong
    brush.set("chalk_highlight", PAL.chromeSpec, 1.15);
    brush.line(holeX, cy - 1.5, prongTipX, prongTipY - 1.5);
  } else {
    // Central Mayan Sun-Warrior boss inside championship plate
    brush.set("rotring", PAL.abyss, 0.9);
    brush.circle(cx, cy, 22, 0.08);
    brush.set("chalk_highlight", PAL.chromeSpec, 1.15);
    brush.arc(cx - 2, cy - 2, 19, 155, 295);
    // Crossed lightning bolts / wrestling ring ropes inside boss
    brush.set("rotring", PAL.chromeDark, 0.8);
    brush.line(cx - 12, cy - 12, cx + 12, cy + 12);
    brush.line(cx - 12, cy + 12, cx + 12, cy - 12);
    drawSequin(cx, cy, 7.5, 0.95, PAL.sangSoft);
  }
}

