function drawHyperrealLacedBoots() {
  drawSingleBoot(512, true);
  drawSingleBoot(688, false);
}

function drawSingleBoot(cx, isLeft) {
  let yTop = 898;
  let yAnkle = 1068;
  let ySole = 1124;

  // 1. Boot Shaft & Toe Box Silhouette
  let toeDir = isLeft ? -1 : 1;
  let bootPts = [
    [cx - 58, yTop],
    [cx + 58, yTop],
    [cx + 52, yAnkle],
    [cx + 54 + (toeDir > 0 ? 18 : 4), ySole - 14],
    [cx + 50 + (toeDir > 0 ? 16 : 2), ySole],
    [cx - 50 + (toeDir < 0 ? -16 : -2), ySole],
    [cx - 54 + (toeDir < 0 ? -18 : -4), ySole - 14],
    [cx - 52, yAnkle]
  ];

  // Deep shadow cast by boot to the lower-right
  brush.noStroke();
  brush.fill(PAL.abyss, 210);
  tracePoly(offsetPts(bootPts, 8, 6), 0.12, true);

  // Leather boot base wash (toned limestone & sanguine)
  brush.fill(isLeft ? PAL.stoneBase : PAL.stoneMid, 230);
  brush.fillBleed(0.08, "in");
  tracePoly(bootPts, 0.12, true);

  // Raking upper-left highlight wash on left side of boot shaft & toe dome
  brush.fill(PAL.stoneHighlight, isLeft ? 150 : 105);
  brush.fillBleed(0.2, "out");
  brush.rect(cx - 50, yTop + 10, 32, 155, "corner");
  brush.circle(cx + toeDir * 18 - 12, ySole - 26, 28, 0.2);

  // Core shadow on right side of boot shaft
  brush.fill(PAL.stoneDark, 155);
  brush.rect(cx + 16, yTop + 10, 36, 165, "corner");
  brush.noFill();

  // Curved cross-hatching modeling the cylindrical calf & ankle leather
  brush.hatchStyle("HB", PAL.undercut, 0.52);
  brush.hatch(5.5, 16, { rand: 0.05, gradient: 0.65 });
  brush.noStroke();
  tracePoly(bootPts, 0.1, true);
  brush.noHatch();

  drawCarvedReliefStroke(bootPts, 7, 1.05);

  // 2. Winged Sequinned Calf Appliqué Panels on outer sides of boots
  let wingSide = isLeft ? -1 : 1;
  for (let r = 0; r < 8; r++) {
    let wy = yTop + 22 + r * 16;
    let wx = cx + wingSide * 38;
    drawSequin(wx, wy, 4.6, isLeft ? 0.88 : 0.42, r % 2 === 0 ? PAL.sangSoft : PAL.pastelOchre);
    drawSequin(wx - wingSide * 10, wy + 5, 4.2, isLeft ? 0.78 : 0.38, PAL.pastelJade);
  }

  // 3. Recessed Central Tongue Channel & Horizontal Leather Pleats
  let chanW = 21;
  let tonguePts = [
    [cx - chanW, yTop + 4], [cx + chanW, yTop + 4],
    [cx + chanW - 3, yAnkle + 6], [cx - chanW + 3, yAnkle + 6]
  ];
  brush.noStroke();
  brush.fill(PAL.stoneDark, 165);
  tracePoly(tonguePts, 0.05, true);
  brush.noFill();

  // Padded horizontal tongue creases visible behind laces
  for (let py = yTop + 12; py < yAnkle; py += 13) {
    brush.set("2B", PAL.abyss, 0.65);
    brush.arc(cx, py, chanW * 0.85, 200, 340);
    brush.set("chalk_highlight", PAL.stoneLight, 0.5);
    brush.arc(cx, py - 2, chanW * 0.8, 205, 335);
  }

  // 4. Stitched Leather Eyestay Flaps flanking the tongue
  drawStitchedSeam([[cx - chanW - 2, yTop + 4], [cx - chanW + 1, yAnkle + 8]], 7, 2.8, true);
  drawStitchedSeam([[cx + chanW + 2, yTop + 4], [cx + chanW - 1, yAnkle + 8]], 7, 2.8, true);

  // 5. 13 Pairs of Metallic Eyelets (Grommets) & Crisscross Woven Flat Laces
  let nPairs = 13;
  let eyeletsL = [];
  let eyeletsR = [];

  for (let i = 0; i < nPairs; i++) {
    let t = i / (nPairs - 1);
    let ey = lerp(yTop + 12, yAnkle + 2, t);
    let spread = lerp(chanW + 5, chanW + 1, t);
    let lx = cx - spread;
    let rx = cx + spread;
    eyeletsL.push([lx, ey]);
    eyeletsR.push([rx, ey]);

    // Draw Left & Right Metallic Eyelets
    for (let ex of [lx, rx]) {
      brush.set("rotring", PAL.abyss, 0.95);
      brush.circle(ex + 1, ey + 1, 3.8, 0.05);
      brush.set("chisel_fine", PAL.chromeCool, 0.85);
      brush.circle(ex, ey, 3.4, 0.05);
      brush.set("chalk_highlight", PAL.chromeSpec, 0.8);
      brush.arc(ex - 0.8, ey - 0.8, 3.0, 150, 300);
    }
  }

  // Crisscross Flat Woven Laces (Under-crossings first, then Over-crossings with tension shadows!)
  for (let i = 0; i < nPairs - 1; i++) {
    let l1 = eyeletsL[i];
    let r1 = eyeletsR[i];
    let l2 = eyeletsL[i + 1];
    let r2 = eyeletsR[i + 1];

    // Under-lace (Right i to Left i+1)
    drawFlatBootlace(r1[0], r1[1], l2[0], l2[1], false);

    // Cast shadow at center X-crossing where upper lace crosses over lower lace
    let mx = (l1[0] + r2[0]) * 0.5;
    let my = (l1[1] + r2[1]) * 0.5;
    brush.set("charcoal", PAL.abyss, 1.15);
    brush.line(mx - 4, my + 2, mx + 4, my + 2);

    // Over-lace (Left i to Right i+1)
    drawFlatBootlace(l1[0], l1[1], r2[0], r2[1], true);
  }

  // Top Horizontal Tie & Bow-Knot with Aglet Tips at yTop + 10
  let kx = cx;
  let ky = yTop + 10;
  // Left & Right Bow Loops
  brush.set("rotring", PAL.abyss, 1.1);
  brush.spline([[kx, ky + 2], [kx - 22, ky - 8], [kx - 26, ky + 8], [kx, ky + 4]], 0.5);
  brush.spline([[kx, ky + 2], [kx + 22, ky - 8], [kx + 26, ky + 8], [kx, ky + 4]], 0.5);
  brush.set("chalk_highlight", PAL.stoneHighlight, 1.15);
  brush.spline([[kx, ky], [kx - 22, ky - 10], [kx - 26, ky + 6], [kx, ky + 2]], 0.5);
  brush.spline([[kx, ky], [kx + 22, ky - 10], [kx + 26, ky + 6], [kx, ky + 2]], 0.5);

  // Hanging lace ends & metallic aglets
  let agletL = [[kx - 2, ky + 2], [kx - 14, ky + 24], [kx - 17, ky + 44]];
  let agletR = [[kx + 2, ky + 2], [kx + 15, ky + 22], [kx + 19, ky + 42]];
  brush.set("rotring", PAL.abyss, 1.0);
  brush.spline(offsetPts(agletL, 2, 2), 0.35);
  brush.spline(offsetPts(agletR, 2, 2), 0.35);
  brush.set("chalk_highlight", PAL.stoneHighlight, 1.05);
  brush.spline(agletL, 0.35);
  brush.spline(agletR, 0.35);
  // Metallic aglet tips
  brush.set("marker", PAL.chromeCool, 1.1);
  brush.line(kx - 16, ky + 38, kx - 17, ky + 46);
  brush.line(kx + 18, ky + 36, kx + 19, ky + 44);
  brush.set("chalk_highlight", PAL.chromeSpec, 0.9);
  brush.line(kx - 17, ky + 38, kx - 18, ky + 45);

  // 6. Natural Ankle Flexion Folds, Bulbous Toe Highlight & Lugged Sole
  for (let f = 0; f < 3; f++) {
    let fy = yAnkle - 4 + f * 7;
    brush.set("2B", PAL.abyss, 0.75);
    brush.spline([[cx - 44, fy], [cx, fy + 5], [cx + 44, fy]], 0.35);
    brush.set("chalk_highlight", PAL.stoneHighlight, 0.65);
    brush.spline([[cx - 42, fy - 2], [cx, fy + 3], [cx + 32, fy - 2]], 0.35);
  }

  // Specular highlight crescent on bulbous leather toe box
  let tx = cx + toeDir * 14 - 8;
  let ty = ySole - 26;
  brush.set("chalk_highlight", PAL.stoneHighlight, 1.35);
  brush.arc(tx, ty, 24, 175, 285);
  brush.set("chalk_highlight", PAL.chromeSpec, 0.95);
  brush.arc(tx - 2, ty - 2, 18, 190, 265);

  // Heavy Lugged Boot Sole with Vertical Tread Notches
  let soleX1 = cx - 54 + (toeDir < 0 ? -16 : -2);
  let soleX2 = cx + 54 + (toeDir > 0 ? 16 : 2);
  let solePts = makeRoundedBlock(soleX1, ySole - 14, soleX2 - soleX1, 16, 4, 1, 0.4);
  drawCarvedReliefStroke(solePts, 5, 0.95);
  for (let lx = soleX1 + 8; lx < soleX2 - 6; lx += 9) {
    brush.set("rotring", PAL.abyss, 0.95);
    brush.line(lx, ySole - 12, lx, ySole + 1);
    brush.set("chalk_highlight", PAL.stoneMid, 0.6);
    brush.line(lx - 2, ySole - 12, lx - 2, ySole);
  }
}

function drawFlatBootlace(x1, y1, x2, y2, isOver) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = max(1, sqrt(dx * dx + dy * dy));
  let nx = -dy / len;
  let ny = dx / len;
  let halfW = 2.1;

  // Lower-right drop shadow of flat lace ribbon onto tongue
  brush.set("rotring", PAL.abyss, isOver ? 0.95 : 0.75);
  brush.line(x1 + nx * halfW + 1.2, y1 + ny * halfW + 1.5, x2 + nx * halfW + 1.2, y2 + ny * halfW + 1.5);

  // Flat woven ribbon body
  brush.set("cpencil", isOver ? PAL.stoneLight : PAL.stoneMid, 1.35);
  brush.line(x1, y1, x2, y2);

  // Crisp upper-left raking highlight along top edge of lace
  brush.set("chalk_highlight", isOver ? PAL.stoneHighlight : PAL.stoneLight, isOver ? 0.95 : 0.65);
  brush.line(x1 - nx * (halfW * 0.75), y1 - ny * (halfW * 0.75), x2 - nx * (halfW * 0.75), y2 - ny * (halfW * 0.75));

  // Dark upper-left tuck line where lace enters eyelet
  brush.set("rotring", PAL.undercut, 0.55);
  brush.line(x1 - nx * halfW, y1 - ny * halfW, x2 - nx * halfW, y2 - ny * halfW);
}

function drawCarvedPedestal() {
  // Monumental Maya Witz (Earth Monster) Stepped Plinth under the boots (y: 1122..1162)
  let plinthPts = makeRoundedBlock(134, 1122, 932, 38, 6, 2, 1.5);
  brush.noStroke();
  brush.fill(PAL.stoneMid, 215);
  tracePoly(plinthPts, 0.08, true);
  brush.noFill();

  drawCarvedReliefStroke(plinthPts, 8, 1.15);

  // Carved geometric fret blocks along the plinth
  for (let bx = 152; bx < 1040; bx += 74) {
    let blk = makeRoundedBlock(bx, 1128, 64, 26, 4, 1, 0.6);
    drawCarvedReliefStroke(blk, 4, 0.7);
    brush.set("rotring", PAL.undercut, 0.65);
    brush.rect(bx + 14, 1135, 36, 12, "corner");
    brush.set("chalk_highlight", PAL.stoneHighlight, 0.65);
    brush.line(bx + 14, 1135, bx + 50, 1135);
  }
}

