function drawHyperrealMask() {
  let cx = 600;
  let cy = 268;

  // 1. Cranial Mask Dome Silhouette (anatomical head & jaw proportions)
  let maskPts = [
    [600, 172], [642, 177], [672, 202], [682, 245],
    [676, 294], [654, 336], [622, 360], [600, 364],
    [578, 360], [546, 336], [524, 294], [518, 245],
    [528, 202], [558, 177]
  ];

  // Deep cast shadow of the mask head onto the neck and collar to the lower-right
  let maskShadow = offsetPts(maskPts, 10, 12);
  brush.noStroke();
  brush.fill(PAL.abyss, 215);
  brush.fillBleed(0.15, "out");
  tracePoly(maskShadow, 0.2, true);

  // Limestone & Sanguine base fill of the mask
  brush.fill(PAL.stoneBase, 240);
  brush.fillBleed(0.08, "in");
  tracePoly(maskPts, 0.22, true);

  // Strong upper-left raking light wash on left forehead, brow & left cheek
  brush.fill(PAL.stoneHighlight, 175);
  brush.fillBleed(0.28, "out");
  brush.circle(565, 215, 52, 0.25);
  brush.circle(554, 282, 42, 0.25);

  // Soft pastel sanguine blush across nose bridge & cheeks
  brush.fill(PAL.sangSoft, 115);
  brush.fillBleed(0.3, "out");
  brush.circle(595, 272, 58, 0.25);

  // Deep chiaroscuro shadow across right temple, right cheek, and right jawline
  brush.fill(PAL.stoneDark, 165);
  brush.fillBleed(0.25, "out");
  brush.circle(648, 248, 52, 0.25);
  brush.fill(PAL.undercut, 155);
  brush.circle(642, 315, 48, 0.25);
  brush.noFill();

  // Curved cross-hatching modeling the 3D cranial sphere & cheekbones
  brush.hatchStyle("HB", PAL.undercut, 0.52);
  brush.hatch(5, 28, { rand: 0.05, gradient: 0.7 });
  brush.noStroke();
  tracePoly(maskPts, 0.2, true);
  brush.noHatch();

  // Outer carved relief contour of the mask
  drawCarvedReliefStroke(maskPts, 8, 1.15);

  // 2. Hyperreal Stitched Mask Seams (Sagittal crest, cheek panels, brow seams)
  // Central sagittal seam from forehead crown down to nose tip
  drawStitchedSeam([[600, 173], [600, 215], [600, 255], [600, 292]], 6.5, 3.6, true);
  // Left & Right temporal-cheek structural seams
  drawStitchedSeam([[555, 179], [536, 212], [532, 285], [556, 344]], 7, 3.2, true);
  drawStitchedSeam([[645, 179], [664, 212], [668, 285], [644, 344]], 7, 3.2, true);
  // Subtle leather tension puckers radiating from stitched seams
  for (let py = 185; py <= 235; py += 10) {
    brush.set("chisel_fine", PAL.stoneHighlight, 0.55);
    brush.line(592, py, 578, py - 3);
    brush.set("2H", PAL.undercut, 0.5);
    brush.line(608, py, 622, py + 3);
  }

  // 3. The Winged Antifaz (Aztec Eagle / Jaguar Butterfly Eye Appliqué)
  for (let side = 0; side < 2; side++) {
    let s = side === 0 ? -1 : 1; // -1 = Left, +1 = Right
    let wingPts = [
      [600 + s * 6, 224],
      [600 + s * 38, 206],
      [600 + s * 78, 192],
      [600 + s * 96, 214],
      [600 + s * 82, 238],
      [600 + s * 92, 258],
      [600 + s * 68, 282],
      [600 + s * 32, 286],
      [600 + s * 8, 268]
    ];

    brush.noStroke();
    brush.fill(side === 0 ? PAL.sangMid : PAL.sangDeep, 195);
    brush.fillBleed(0.08, "in");
    tracePoly(wingPts, 0.18, true);
    brush.noFill();

    drawCarvedReliefStroke(wingPts, 5.5, 0.9);
    drawStitchedSeam(wingPts.concat([wingPts[0]]), 6.5, 2.8, false);

    // Dense rows of hyperreal sequins paving the winged antifaz around the eye
    for (let ring = 0; ring < 3; ring++) {
      let rx = 30 + ring * 8;
      let ry = 19 + ring * 7;
      let ex = 600 + s * 42;
      let ey = 250;
      let nSeq = 12 + ring * 4;
      for (let k = 0; k < nSeq; k++) {
        let a = map(k, 0, nSeq, 0, 360);
        let sx = ex + cos(a) * rx + s * (ring * 3);
        let sy = ey + sin(a) * ry - (cos(a) * s > 0 ? sin(a) * 4 : 0);
        let lit = side === 0 ? map(sin(a), -1, 1, 0.98, 0.55) : map(sin(a), -1, 1, 0.65, 0.22);
        let col = ring === 1 ? PAL.pastelOchre : (ring === 0 ? PAL.pastelJade : PAL.sangSoft);
        drawSequin(sx, sy, 3.9, lit, col);
      }
    }
  }

  // 4. Deeply Recessed Expressive Human Eyes Inside Leather Eye-Slits
  for (let side = 0; side < 2; side++) {
    let s = side === 0 ? -1 : 1;
    let ex = 600 + s * 39;
    let ey = 251;

    // Thick leather eye aperture cutout
    let eyeAperture = [
      [ex - s * 20, ey + 2],
      [ex - s * 6, ey - 12],
      [ex + s * 16, ey - 10],
      [ex + s * 22, ey + 1],
      [ex + s * 8, ey + 11],
      [ex - s * 10, ey + 9]
    ];

    // Deep orbital shadow inside eye opening
    brush.noStroke();
    brush.fill(PAL.abyss, 235);
    tracePoly(eyeAperture, 0.25, true);
    brush.noFill();

    // Sclera (shaded eyeball sphere inside socket)
    brush.noStroke();
    brush.fill(side === 0 ? PAL.stoneLight : PAL.stoneMid, 210);
    brush.circle(ex, ey, 11, 0.1);
    brush.noFill();

    // Detailed Iris & Pupil
    brush.set("2B", PAL.sangDeep, 1.1);
    brush.circle(ex, ey - 0.5, 6.8, 0.05);
    // Radial iris striations
    for (let a = 0; a < 360; a += 45) {
      brush.set("chisel_fine", PAL.undercut, 0.5);
      brush.line(ex + cos(a) * 2.5, ey + sin(a) * 2.5, ex + cos(a) * 6.5, ey + sin(a) * 6.5);
    }
    // Dark pupil
    brush.set("rotring", PAL.abyss, 1.4);
    brush.circle(ex, ey - 0.5, 3.0, 0.02);

    // Upper eyelid shadow cast across top of eyeball
    brush.set("charcoal", PAL.abyss, 1.25);
    brush.spline([eyeAperture[0], eyeAperture[1], eyeAperture[2], eyeAperture[3]], 0.35);

    // Lower leather rim catching raking upper-left light!
    brush.set("chalk_highlight", PAL.stoneHighlight, 0.95);
    brush.spline([eyeAperture[3], eyeAperture[4], eyeAperture[5], eyeAperture[0]], 0.35);

    // Piercing corneal specular catchlight in upper-left of iris
    brush.set("chalk_highlight", PAL.chromeSpec, 1.35);
    brush.line(ex - 3.2, ey - 3.2, ex - 1.2, ey - 2.2);
    brush.circle(ex - 2.5, ey - 2.8, 1.6, 0.02);
  }

  // 5. Sculpted Nose Bridge & Stitched Mouth/Chin Aperture
  // Nose ridge highlights & nostril vents
  brush.set("chalk_highlight", PAL.stoneHighlight, 1.15);
  brush.line(596, 245, 588, 288);
  brush.set("2B", PAL.abyss, 1.0);
  brush.line(604, 245, 612, 288);
  brush.spline([[586, 290], [600, 296], [614, 290]], 0.35);

  // Mouth / Chin Opening with Stitched & Sequinned Trim
  let mouthOuter = makeRoundedBlock(556, 300, 88, 46, 16, 2, 0.6);
  let mouthInner = makeRoundedBlock(566, 308, 68, 30, 11, 2, 0.5);

  drawCarvedReliefStroke(mouthOuter, 5, 0.85);
  drawStitchedSeam(mouthOuter.concat([mouthOuter[0]]), 6, 2.5, false);

  // Sequins framing mouth border
  for (let i = 0; i < mouthOuter.length; i++) {
    let mp = mouthOuter[i];
    let ip = mouthInner[i % mouthInner.length];
    let sx = lerp(mp[0], ip[0], 0.5);
    let sy = lerp(mp[1], ip[1], 0.5);
    drawSequin(sx, sy, 3.6, sx < 600 ? 0.8 : 0.4, PAL.pastelOchre);
  }

  // Recessed mouth cavity & sculpted fierce lips inside opening
  brush.noStroke();
  brush.fill(PAL.abyss, 230);
  tracePoly(mouthInner, 0.15, true);
  // Upper and lower human lips inside mask opening
  brush.fill(PAL.sangMid, 200);
