function drawStoneWeatheringAndLichen() {
  // 1. Atmospheric Limestone Dust Stippling
  brush.set("stone_dust", PAL.stoneHighlight, 1.1);
  brush.line(130, 60, 560, 480);
  brush.line(140, 220, 480, 680);
  brush.set("stone_dust", PAL.undercut, 1.1);
  brush.line(680, 520, 1050, 1120);
  brush.line(420, 820, 960, 1140);

  // 2. Concave Limestone Pits (Inverted Normal Lighting: Shadow on Upper-Left, Highlight on Lower-Right!)
  for (let i = 0; i < 240; i++) {
    let px = random(115, 1075);
    let py = random(42, 1150);
    // Keep dense pitting slightly lighter right over the eyes/mouth so facial details stay razor-sharp
    if (dist(px, py, 600, 268) < 75 && random() < 0.75) continue;

    let pr = random(1.8, 5.8);
    // Upper-left inner wall is shadowed inside a concave pit!
    brush.set("rotring", PAL.undercut, random(0.55, 0.95));
    brush.arc(px, py, pr, 145, 305);
    // Lower-right inner rim catches the raking light!
    brush.set("chalk_highlight", PAL.stoneHighlight, random(0.55, 0.9));
    brush.arc(px, py, pr * 0.95, -35, 125);
  }

  // 3. Weathered Stone Fissures & Chisel Marks across Stele & Relief
  for (let c = 0; c < 24; c++) {
    let cx = random(120, 1060);
    let cy = random(55, 1135);
    if (dist(cx, cy, 600, 268) < 90) continue;

    let crackPts = [[cx, cy]];
    let curX = cx;
    let curY = cy;
    let baseAng = random(20, 160);
    let segs = floor(random(3, 6));
    for (let s = 0; s < segs; s++) {
      let a = baseAng + random(-35, 35);
      let l = random(14, 34);
      curX += cos(a) * l;
      curY += sin(a) * l;
      crackPts.push([curX, curY]);
    }
    // Deep fissure line + lower-right sunlit lip
    brush.set("rotring", PAL.abyss, random(0.65, 1.05));
    brush.spline(crackPts, 0.2);
    brush.set("chalk_highlight", PAL.stoneHighlight, random(0.55, 0.85));
    brush.spline(offsetPts(crackPts, 1.4, 1.4), 0.2);
  }

  // 4. Pastel Lichen Flecks & Crustose Rosette Colonies
  // Clustered naturally along glyph ledges, stele margins, plinth, cape folds, and pauldron crevices
  let lichenZones = [
    { x: 185, y: 120, r: 90, n: 18 },
    { x: 195, y: 420, r: 110, n: 20 },
    { x: 210, y: 780, r: 120, n: 22 },
    { x: 230, y: 1060, r: 110, n: 22 },
    { x: 960, y: 150, r: 95, n: 18 },
    { x: 950, y: 520, r: 115, n: 22 },
    { x: 940, y: 890, r: 125, n: 24 },
    { x: 600, y: 1135, r: 280, n: 28 },
    { x: 375, y: 395, r: 65, n: 12 },
    { x: 825, y: 410, r: 65, n: 12 },
    { x: 460, y: 695, r: 55, n: 10 },
    { x: 740, y: 695, r: 55, n: 10 }
  ];

  let lichenCols = [PAL.lichenSage, PAL.lichenMint, PAL.lichenChartreuse, PAL.pastelRose, PAL.pastelLavender];

  for (let z of lichenZones) {
    for (let i = 0; i < z.n; i++) {
      let ang = random(360);
      let rad = random(z.r);
      let lx = z.x + cos(ang) * rad;
      let ly = z.y + sin(ang) * rad * 0.75;
      let lr = random(2.2, 6.8);
      let lCol = lichenCols[floor(random(lichenCols.length))];

      // Crusty shadow rim under lichen fleck
      brush.set("chisel_fine", PAL.lichenCrust, 0.75);
      brush.arc(lx + 1.2, ly + 1.2, lr, -35, 130);

      // Soft pastel lichen thallus body
      brush.set("chalk_highlight", lCol, random(0.85, 1.35));
      brush.circle(lx, ly, lr * 0.82, 0.35);

      // Tiny pale spore highlight on upper-left of lichen fleck
      if (lr > 4.0) {
        brush.set("chalk_highlight", PAL.stoneHighlight, 0.65);
        brush.arc(lx - 0.8, ly - 0.8, lr * 0.5, 155, 290);
      }
    }
  }
}

// Hyperreal Xerox Platen Study: Worn Skate Shoe Sole
// p5.js 2.x + p5.brush (WEBGL)

const SEED = 40821;

// Palette — warm xerox paper, brutal black carbon toner, fluorescent orange overprint, masking tape buff
const COL_PAPER       = "#f4ecdc";
const COL_PAPER_HIGH  = "#fbf7ee";
const COL_PAPER_WARM  = "#e9dec7";
const COL_TONER_BLACK = "#11100e";
const COL_TONER_DEEP  = "#090807";
const COL_TONER_DARK  = "#221f1c";
const COL_TONER_MID   = "#4a443d";
const COL_TONER_LIGHT = "#8c8275";
const COL_FLUORO      = "#ff4800";
const COL_FLUORO_SOFT = "#ff6d24";
const COL_TAPE        = "#dec68d";
const COL_TAPE_DARK   = "#b5985b";
const COL_TAPE_EDGE   = "#826b3a";

// Sole global transform (fills 1200x1200 diagonally edge-to-edge)
const SOLE_CX = 592;
const SOLE_CY = 598;
const SOLE_ANGLE = -33.5; // degrees
const MISREG_DX = 14;     // fluorescent orange misregistration offset X (in screen px)
const MISREG_DY = -11;    // fluorescent orange misregistration offset Y (in screen px)

// Control stations for asymmetric skate shoe sole (local Y from -575 toe to +575 heel)
const SOLE_STATIONS = [
  { y: -575, med:   0, lat:   0, cx: -16 },
  { y: -558, med:  82, lat:  70, cx: -16 },
  { y: -520, med: 158, lat: 142, cx: -15 },
  { y: -450, med: 214, lat: 205, cx: -13 },
  { y: -350, med: 244, lat: 246, cx: -10 },
  { y: -230, med: 254, lat: 268, cx:  -6 }, // widest forefoot / ball of foot
  { y: -110, med: 232, lat: 258, cx:   2 },
  { y:   10, med: 188, lat: 234, cx:  14 },
  { y:  125, med: 158, lat: 214, cx:  22 }, // midfoot arch waist
  { y:  240, med: 174, lat: 210, cx:  16 },
  { y:  360, med: 202, lat: 212, cx:   6 }, // heel cup widest
  { y:  465, med: 184, lat: 190, cx:   0 },
  { y:  535, med: 128, lat: 132, cx:  -2 },
  { y:  565, med:  64, lat:  66, cx:  -2 },
  { y:  575, med:   0, lat:   0, cx:  -2 }
];

async function setup() {
