function draw() {
  translate(-width / 2, -height / 2);

  // 1. Base paper ground & warm platen undertone
  background(COL_PAPER);
  drawPaperGroundAndPlatenCorners();

  // 2. Misregistered Fluorescent Orange Overprint (Under-layer pass)
  drawFluorescentOverprintPass();

  // 3. Outer Sole Shadow, Foxing Wall, Toe/Heel Knurled Bumpers & Frayed Canvas Edge
  drawSolePerimeterAndFoxing();

  // 4. Waffle Tread Lattice, Arch Brand Plaque & Brutal Abrasion Zones
  drawWaffleTreadAndWear();

  // 5. Central Arch Brand Stamp Plaque (Molded Rubber & Rail Gouges)
  drawArchBrandPlaque();

  // 6. Hyperreal Incidents: Chewing-Gum Scar & Wedged Gravel Pebbles
  drawChewingGumScar();
  drawEmbeddedPebbles();

  // 7. Frayed Canvas Weave & Exploding Griptape-Shredded Threads
  drawFrayedCanvasAndThreads();

  // 8. Global Photocopier Drum Banding, Corona Wire Scratches & Toner Grit
  drawPhotocopierArtifacts();

  // 9. Corner Ephemera: Crooked Cut-and-Paste Typed Caption & Torn Masking Tape
  drawTopLeftRegistrationAndTape();
  drawCornerCaptionAndTape();

  noLoop();
}

// ============================================================================
// GEOMETRY & COORDINATE HELPERS
// ============================================================================

function soleToScreen(lx, ly, extraDx = 0, extraDy = 0) {
  let c = cos(SOLE_ANGLE);
  let s = sin(SOLE_ANGLE);
  return [
    SOLE_CX + lx * c - ly * s + extraDx,
    SOLE_CY + lx * s + ly * c + extraDy
  ];
}

function screenToSole(sx, sy) {
  let dx = sx - SOLE_CX;
  let dy = sy - SOLE_CY;
  let c = cos(-SOLE_ANGLE);
  let s = sin(-SOLE_ANGLE);
  return [
    dx * c - dy * s,
    dx * s + dy * c
  ];
}

// Interpolates medial (left, -x) and lateral (right, +x) bounds at local y
function getSoleSlice(ly) {
  if (ly <= -575 || ly >= 575) return { minX: 0, maxX: 0, cx: 0, valid: false };
  for (let i = 0; i < SOLE_STATIONS.length - 1; i++) {
    let a = SOLE_STATIONS[i];
    let b = SOLE_STATIONS[i + 1];
    if (ly >= a.y && ly <= b.y) {
      let t = (ly - a.y) / (b.y - a.y);
      // Smoothstep blend for organic curvature
      let st = t * t * (3 - 2 * t);
      // Near the tips, use square-root cap profile for rounded toe/heel
      if (i === 0) st = sqrt(constrain(t, 0, 1));
      if (i === SOLE_STATIONS.length - 2) st = 1 - sqrt(constrain(1 - t, 0, 1));
      let med = lerp(a.med, b.med, st);
      let lat = lerp(a.lat, b.lat, st);
      let cx  = lerp(a.cx,  b.cx,  st);
      return { minX: cx - med, maxX: cx + lat, cx: cx, med: med, lat: lat, valid: true };
    }
  }
  return { minX: 0, maxX: 0, cx: 0, valid: false };
}

// Returns signed distance inside the sole contour (positive = inside, negative = outside)
function soleSignedDist(lx, ly) {
  if (ly <= -575) return -(-575 - ly);
  if (ly >= 575)  return -(ly - 575);
  let s = getSoleSlice(ly);
  if (!s.valid) return -100;
  let dLeft  = lx - s.minX;
  let dRight = s.maxX - lx;
  let dEndToe  = ly - (-575);
  let dEndHeel = 575 - ly;
  return min(min(dLeft, dRight), min(dEndToe * 0.85, dEndHeel * 0.85));
}

// Computes local wear intensity [0 = crisp unworn, 1+ = ground flat to bald core]
function getSoleWear(lx, ly) {
  // 1. Ball-of-foot kickflip/pivot wear zone
  let dx1 = (lx - (-28)) / 148;
  let dy1 = (ly - (-235)) / 168;
  let d1 = sqrt(dx1 * dx1 + dy1 * dy1);
  let wBall = constrain(1.22 - d1 * 1.05, 0, 1.25);

  // 2. Lateral forefoot ollie/flick edge wear
  let dx2 = (lx - 185) / 95;
  let dy2 = (ly - (-295)) / 155;
  let d2 = sqrt(dx2 * dx2 + dy2 * dy2);
  let wOllie = constrain(1.05 - d2 * 1.1, 0, 1.05);

  // 3. Heel drag / braking wear zone (back lateral heel)
  let dx3 = (lx - 42) / 142;
  let dy3 = (ly - 462) / 118;
  let d3 = sqrt(dx3 * dx3 + dy3 * dy3);
  let wHeel = constrain(1.20 - d3 * 1.05, 0, 1.22);

  // 4. Toe tip flick abrasion
  let dx4 = (lx - (-35)) / 120;
  let dy4 = (ly - (-525)) / 68;
  let d4 = sqrt(dx4 * dx4 + dy4 * dy4);
  let wToe = constrain(0.95 - d4 * 1.05, 0, 0.95);

  let n = (noise(lx * 0.018 + 50, ly * 0.018 + 50) - 0.5) * 0.16;
  return max(max(wBall, wOllie), max(wHeel, wToe)) + n;
}

// Checks if point is inside the midfoot oval brand plaque
function isInsidePlaque(lx, ly, margin = 0) {
  let px = lx - 10;
  let py = ly - 88;
  let rx = 44 + margin;
  let ry = 94 + margin;
  // Stadium shape (vertical segment + rounded caps)
  let segY = constrain(py, -48, 48);
  let dy = py - segY;
  return (px * px) / (rx * rx) + (dy * dy) / ((ry - 48) * (ry - 48)) <= 1.0;
}

// ============================================================================
// 1. PAPER GROUND & PHOTOCOPIER PLATEN DARK CORNERS
// ============================================================================

function drawPaperGroundAndPlatenCorners() {
  brush.noField();
  brush.noStroke();

  // Warm paper irregularity wash
  brush.wash(COL_PAPER_WARM, 55);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Build dark photocopier open-lid platen corners around the shoe
  // Scan across horizontal scanlines and draw streaky black toner outside the shoe's light flare halo
  for (let sy = 4; sy < 1200; sy += 5) {
    let bandNoise = noise(sy * 0.04, 11.3);
    let streakWeight = map(bandNoise, 0, 1, 0.7, 2.1);

    let inRun = false;
    let runStart = 0;

    for (let sx = 0; sx <= 1204; sx += 8) {
      let [lx, ly] = screenToSole(sx, sy);
      let d = soleSignedDist(lx, ly);
      // Halo around the shoe where scanner lamp illuminates the glass near the white sidewall
      let haloWidth = 22 + noise(sx * 0.015, sy * 0.015) * 34;
      let isDarkPlaten = (d < -haloWidth) && sx <= 1200;

      if (isDarkPlaten && !inRun) {
        inRun = true;
        runStart = sx;
      } else if (!isDarkPlaten && inRun) {
        inRun = false;
        let runLen = sx - runStart;
        if (runLen > 6) {
          // Draw dense xerox toner scanline
          let inset = random(0, 14);
          brush.set("toner_block", COL_TONER_BLACK, streakWeight);
          brush.line(runStart, sy, sx - inset, sy);

          // Secondary ragged toner drag extending into the halo
          if (random() < 0.65) {
            brush.set("drum_band", COL_TONER_DARK, random(0.8, 1.6));
            let dragX = (runStart === 0) ? sx + random(8, 42) : runStart - random(8, 42);
            let anchorX = (runStart === 0) ? sx - 6 : runStart + 6;
            brush.line(anchorX, sy + random(-1.5, 1.5), dragX, sy + random(-1.5, 1.5));
          }
        }
      }
    }
  }

  // Heavy spray grain along the platen halo boundary (collapsing midtones into gritty speckle)
  for (let a = 0; a < 360; a += 1.2) {
    let ly = map(cos(a), -1, 1, -585, 585);
    let s = getSoleSlice(constrain(ly, -572, 572));
    if (!s.valid) continue;
    let side = (a < 180) ? -1 : 1;
    let baseLx = (side < 0) ? s.minX : s.maxX;
    let haloDist = random(10, 68);
    let lx = baseLx + side * haloDist;
    let [sx, sy] = soleToScreen(lx, ly);
    if (sx > -20 && sx < 1220 && sy > -20 && sy < 1220) {
      brush.set("toner_dust", COL_TONER_BLACK, random(0.9, 2.2));
      brush.line(sx, sy, sx + random(-18, 18), sy + random(-18, 18));
    }
  }
}

// ============================================================================
// 2. MISREGISTERED FLUORESCENT ORANGE OVERPRINT (PASS 1)
// ============================================================================

function drawFluorescentOverprintPass() {
  brush.noField();

  // A. Orange misregistered outer sole rim & bumper ribs
  let outlinePts = [];
  for (let ly = -572; ly <= 572; ly += 14) {
    let s = getSoleSlice(ly);
    if (s.valid) outlinePts.push(soleToScreen(s.minX, ly, MISREG_DX, MISREG_DY));
  }
  for (let ly = 572; ly >= -572; ly -= 14) {
    let s = getSoleSlice(ly);
    if (s.valid) outlinePts.push(soleToScreen(s.maxX, ly, MISREG_DX, MISREG_DY));
  }

  brush.set("fluoro_screen", COL_FLUORO, 2.2);
  brush.spline(outlinePts, 0.35);

  // Inner foxing line in fluorescent orange
  let innerPts = [];
  for (let ly = -548; ly <= 548; ly += 16) {
    let s = getSoleSlice(ly);
    if (s.valid) innerPts.push(soleToScreen(s.minX + 26, ly, MISREG_DX, MISREG_DY));
  }
  for (let ly = 548; ly >= -548; ly -= 16) {
    let s = getSoleSlice(ly);
    if (s.valid) innerPts.push(soleToScreen(s.maxX - 26, ly, MISREG_DX, MISREG_DY));
  }
  brush.set("fluoro_screen", COL_FLUORO, 1.4);
  brush.spline(innerPts, 0.35);

  // B. Orange overprint of the worn abrasion shadows (ball of foot & heel drag halftones)
  brush.hatchStyle("rotring", COL_FLUORO, 1.0);
  brush.hatch(7, SOLE_ANGLE + 45, { rand: 0.08 });
  brush.noStroke();

  // Forefoot orange halftone patch
  let [fx, fy] = soleToScreen(-25, -235, MISREG_DX, MISREG_DY);
  brush.circle(fx, fy, 118, 0.25);

  // Heel orange halftone patch
  let [hx, hy] = soleToScreen(42, 455, MISREG_DX, MISREG_DY);
  brush.circle(hx, hy, 92, 0.25);
  brush.noHatch();

  // C. Orange misregistered shadows inside every waffle diamond cavity
  let cellW = 36;
  let cellH = 50;
  let grooveInset = 4.6;

  for (let r = -23; r <= 23; r++) {
    let cy = r * (cellH * 0.5);
    if (cy < -545 || cy > 545) continue;

    for (let c = -8; c <= 8; c++) {
      let cx = c * cellW + ((abs(r) % 2 === 1) ? cellW * 0.5 : 0);
      if (isInsidePlaque(cx, cy, 4)) continue;

      let dEdge = soleSignedDist(cx, cy);
      if (dEdge < 30) continue;

      let wear = getSoleWear(cx, cy);
      if (wear > 0.88) continue; // completely worn bald here

      let scaleFactor = map(constrain(wear, 0, 0.88), 0, 0.88, 1.0, 0.32);
      let hw = (cellW * 0.5 - grooveInset) * scaleFactor;
      let hh = (cellH * 0.5 - grooveInset) * scaleFactor;
      if (hw < 3 || hh < 4) continue;

      let pTop    = soleToScreen(cx,      cy - hh, MISREG_DX, MISREG_DY);
      let pRight  = soleToScreen(cx + hw, cy,      MISREG_DX, MISREG_DY);
      let pBottom = soleToScreen(cx,      cy + hh, MISREG_DX, MISREG_DY);
      let pLeft   = soleToScreen(cx - hw, cy,      MISREG_DX, MISREG_DY);

      // Draw crisp fluorescent orange offset diamond
      brush.set("fluoro_screen", COL_FLUORO, 1.15);
      brush.line(pTop[0], pTop[1], pRight[0], pRight[1]);
      brush.line(pRight[0], pRight[1], pBottom[0], pBottom[1]);
      brush.line(pBottom[0], pBottom[1], pLeft[0], pLeft[1]);
      brush.line(pLeft[0], pLeft[1], pTop[0], pTop[1]);

      // Fill every second or edge diamond with bright orange screen wash
      if ((r + c) % 2 === 0 || wear > 0.45) {
        brush.set("fluoro_screen", COL_FLUORO_SOFT, 1.35);
        brush.line(pLeft[0], pLeft[1], pRight[0], pRight[1]);
      }
    }
  }
}

// ============================================================================
// 3. SOLE PERIMETER, FOXING WALL & KNURLED TOE/HEEL BUMPERS
// ============================================================================

function drawSolePerimeterAndFoxing() {
  brush.noField();

  // 1. Clean raw paper-white highlight on the vulcanized perimeter foxing band
  for (let ly = -568; ly <= 568; ly += 6) {
    let s = getSoleSlice(ly);
    if (!s.valid) continue;

    // Medial foxing highlight
    let [mOutX, mOutY] = soleToScreen(s.minX + 2, ly);
    let [mInX,  mInY]  = soleToScreen(s.minX + 25, ly);
    brush.set("toner_block", COL_PAPER_HIGH, 1.8);
    brush.line(mOutX, mOutY, mInX, mInY);

    // Lateral foxing highlight
    let [lOutX, lOutY] = soleToScreen(s.maxX - 2, ly);
    let [lInX,  lInY]  = soleToScreen(s.maxX - 25, ly);
    brush.set("toner_block", COL_PAPER_HIGH, 1.8);
    brush.line(lOutX, lOutY, lInX, lInY);
  }

  // 2. Heavy black toner outer contour and inner foxing channel
  for (let pass = 0; pass < 2; pass++) {
    let offset = (pass === 0) ? 0 : 25;
    for (let side of [-1, 1]) {
      let pts = [];
      for (let ly = -568; ly <= 568; ly += 10) {
        let s = getSoleSlice(ly);
        if (!s.valid) continue;
        let xVal = (side < 0) ? (s.minX + offset) : (s.maxX - offset);
        if (side < 0 && xVal > s.cx) continue;
        if (side > 0 && xVal < s.cx) continue;

        // Add griptape gouge jitter in the lateral ollie zone
        let isOllieZone = (side > 0 && ly > -430 && ly < -90);
        let jitter = isOllieZone ? (noise(ly * 0.08, pass * 10) - 0.5) * 14 : (noise(ly * 0.05, side) - 0.5) * 3;
        pts.push(soleToScreen(xVal + jitter, ly));
      }
      if (pts.length > 2) {
        brush.set("toner_block", COL_TONER_BLACK, pass === 0 ? 1.6 : 1.1);
        brush.spline(pts, 0.35);
      }
    }
  }

  // 3. Toe Bumper & Heel Bumper perpendicular knurling / ribbing grooves
  for (let ly = -568; ly <= 568; ly += 6.5) {
    let isToeBumper  = (ly < -350);
    let isHeelBumper = (ly > 380);
    let s = getSoleSlice(ly);
    if (!s.valid) continue;

    for (let side of [-1, 1]) {
      let xOuter = (side < 0) ? s.minX : s.maxX;
      let xInner = (side < 0) ? s.minX + 25 : s.maxX - 25;

      // Wear check on the perimeter wall
      let w = getSoleWear(xOuter, ly);

      if (isToeBumper || isHeelBumper) {
        // Deep ribbed bumper striations
        let [p1x, p1y] = soleToScreen(xOuter + side * 1.5, ly);
        let [p2x, p2y] = soleToScreen(xInner - side * 2.0, ly);
        brush.set("rotring", COL_TONER_BLACK, w > 0.7 ? 0.8 : 1.5);
        brush.line(p1x, p1y, p2x, p2y);

        // Secondary double-foxing step line at toe and heel
        let [p3x, p3y] = soleToScreen(xOuter - side * 12, ly);
        let [p4x, p4y] = soleToScreen(xOuter - side * 14, ly + 5);
        brush.set("razor_ink", COL_TONER_BLACK, 1.1);
        brush.line(p3x, p3y, p4x, p4y);
      } else {
        // Midfoot foxing texture: fine rubber molding seams & wear scuffs
        if (random() < 0.55 || w > 0.5) {
          let [p1x, p1y] = soleToScreen(xOuter - side * random(1, 10), ly);
          let [p2x, p2y] = soleToScreen(xInner + side * random(2, 12), ly + random(-4, 4));
          brush.set("2B", COL_TONER_DARK, random(0.6, 1.3));
          brush.line(p1x, p1y, p2x, p2y);
        }
      }
    }
  }
}

// ============================================================================
// 4. WAFFLE TREAD LATTICE & BRUTAL ABRASION ZONES
// ============================================================================

function drawWaffleTreadAndWear() {
  brush.noField();

  let cellW = 36;
  let cellH = 50;
  let grooveInset = 4.4;

  // Iterate over all waffle diamond cells inside the sole
  for (let r = -24; r <= 24; r++) {
    let cy = r * (cellH * 0.5);
    if (cy < -555 || cy > 555) continue;

    for (let c = -9; c <= 9; c++) {
      let cx = c * cellW + ((abs(r) % 2 === 1) ? cellW * 0.5 : 0);

      // Skip inside the central arch brand plaque
      if (isInsidePlaque(cx, cy, 2)) continue;

      // Distance inside the inner foxing wall (26px inside outer edge)
      let dEdge = soleSignedDist(cx, cy) - 26;
      if (dEdge < -8) continue;

      let wear = getSoleWear(cx, cy);

      // Compute vertices of the recessed diamond cavity, clipped to the inner sole edge
      // As wear increases from 0.35 to 0.90, the raised rubber wears down and the dark cavity shrinks and deforms
      let shrink = map(constrain(wear, 0.25, 0.92), 0.25, 0.92, 1.0, 0.08);
      let hw = (cellW * 0.5 - grooveInset) * shrink;
      let hh = (cellH * 0.5 - grooveInset) * shrink;

      if (wear < 0.90 && hw > 2.2 && hh > 3.0) {
        // Build 8-point octagonal/diamond polygon (classic Vans star-waffle lugs have slightly truncated tips in forefoot)
        let isStarZone = (cy > -370 && cy < 20);
        let tipCut = isStarZone ? 0.82 : 0.96;

        let localPoly = [
          [cx - hw * 0.22, cy - hh * tipCut],
          [cx + hw * 0.22, cy - hh * tipCut],
          [cx + hw * tipCut, cy - hh * 0.18],
          [cx + hw * tipCut, cy + hh * 0.18],
          [cx + hw * 0.22, cy + hh * tipCut],
          [cx - hw * 0.22, cy + hh * tipCut],
          [cx - hw * tipCut, cy + hh * 0.18],
          [cx - hw * tipCut, cy - hh * 0.18]
        ];

        // Clip vertices against inner sole perimeter & add organic wear distortion
        let screenPoly = [];
        let validCount = 0;
        for (let k = 0; k < localPoly.length; k++) {
          let vx = localPoly[k][0];
          let vy = localPoly[k][1];
          if (wear > 0.35) {
            vx += (noise(vx * 0.08, vy * 0.08, k) - 0.5) * wear * 10;
            vy += (noise(vy * 0.08, vx * 0.08, k) - 0.5) * wear * 10;
          }
          let s = getSoleSlice(vy);
          if (!s.valid) continue;
          let minAllowed = s.minX + 27;
          let maxAllowed = s.maxX - 27;
          if (vx >= minAllowed - 6 && vx <= maxAllowed + 6) validCount++;
          vx = constrain(vx, minAllowed, maxAllowed);
          screenPoly.push(soleToScreen(vx, vy));
        }

        if (validCount >= 3) {
          // 1. Draw deep pitch-black toner cavity
          // Fill cavity with dense parallel toner strokes
          let pTop = screenPoly[0];
          let pBot = screenPoly[4];
          let pLeft = screenPoly[6];
          let pRight = screenPoly[2];

          let steps = floor(map(shrink, 0.1, 1.0, 3, 9));
          brush.set("toner_block", COL_TONER_BLACK, map(shrink, 0.1, 1.0, 0.9, 1.65));
          for (let st = 0; st <= steps; st++) {
            let t = st / steps;
            let ax = lerp(screenPoly[7][0], screenPoly[5][0], t);
            let ay = lerp(screenPoly[7][1], screenPoly[5][1], t);
            let bx = lerp(screenPoly[1][0], screenPoly[3][0], t);
            let by = lerp(screenPoly[1][1], screenPoly[3][1], t);
            brush.line(ax, ay, bx, by);
          }

          // Crisp black rim around the diamond pocket
          brush.set("rotring", COL_TONER_DEEP, 1.35);
          for (let k = 0; k < screenPoly.length; k++) {
            let a = screenPoly[k];
            let b = screenPoly[(k + 1) % screenPoly.length];
            brush.line(a[0], a[1], b[0], b[1]);
          }

          // 2. Inner stepped bevel inside unworn/lightly worn waffle pockets
          if (wear < 0.48 && dEdge > 14) {
            let ihw = hw * 0.46;
            let ihh = hh * 0.46;
            let iTop = soleToScreen(cx, cy - ihh);
            let iRight = soleToScreen(cx + ihw, cy);
            let iBot = soleToScreen(cx, cy + ihh);
            let iLeft = soleToScreen(cx - ihw, cy);

            // Faint blown-out highlight spec on one edge of the inner shelf
            brush.set("razor_ink", COL_PAPER, 0.95);
            brush.line(iTop[0], iTop[1], iRight[0], iRight[1]);
            brush.line(iLeft[0], iLeft[1], iTop[0], iTop[1]);
          }

          // 3. Blown-out raw paper-white highlight along the raised rubber grid bar next to the pocket
          let rimA = soleToScreen(cx - hw - 2.2, cy);
          let rimB = soleToScreen(cx, cy - hh - 2.2);
          let rimC = soleToScreen(cx + hw + 2.2, cy);
          brush.set("toner_block", COL_PAPER_HIGH, 0.9);
          brush.line(rimA[0], rimA[1], rimB[0], rimB[1]);
          brush.line(rimB[0], rimB[1], rimC[0], rimC[1]);
        }
      } else if (wear >= 0.75) {
        // WORN BALD / ABRADED ZONE:
        // The waffle cavities have collapsed into gritty rubber crumbs, friction scratches, and exposed black core!
        let [scx, scy] = soleToScreen(cx, cy);

        // Blown-out raw paper white patch where smooth worn rubber presses flat on glass
        brush.set("toner_block", COL_PAPER_HIGH, 2.2);
        brush.line(scx - 10, scy - 8, scx + 10, scy + 8);

        // Ghostly remnant pit of the vanished diamond corner
        if (wear < 1.04) {
          brush.set("rotring", COL_TONER_BLACK, random(0.9, 1.7));
          let pitR = map(wear, 0.75, 1.04, 7, 1.5);
          brush.line(scx - pitR, scy, scx + pitR, scy + random(-3, 3));
          brush.line(scx, scy - pitR, scx + random(-3, 3), scy + pitR);
        }

        // Dense gritty toner stipple + asphalt drag scratches
        brush.set("toner_dust", COL_TONER_BLACK, random(0.8, 1.6));
        brush.line(scx - 12, scy + random(-8, 8), scx + 12, scy + random(-8, 8));
      }
    }
  }

  // Draw detailed abrasion craters at the center of the Ball-of-Foot & Heel Drag zones
  // (where outer gum rubber is worn all the way through to the black sponge/canvas midsole!)
  drawDeepAbrasionCore(-28, -238, 62, 78, 18); // Ball of foot core tear
  drawDeepAbrasionCore(46, 468, 58, 42, -25);  // Heel drag core tear
}

function drawDeepAbrasionCore(coreLx, coreLy, rx, ry, scratchAngleOffset) {
  // Concentric ragged contour rings showing layers of worn vulcanized rubber
  for (let ring = 3; ring >= 0; ring--) {
    let scaleR = map(ring, 0, 3, 0.38, 1.45);
    let pts = [];
    for (let a = 0; a < 360; a += 12) {
      let n = noise(cos(a) * 1.5 + coreLx * 0.02, sin(a) * 1.5 + coreLy * 0.02, ring * 5);
      let radX = rx * scaleR * (0.72 + n * 0.55);
      let radY = ry * scaleR * (0.72 + n * 0.55);
      let lx = coreLx + cos(a) * radX;
      let ly = coreLy + sin(a) * radY;
      let s = getSoleSlice(ly);
      if (s.valid) {
        lx = constrain(lx, s.minX + 18, s.maxX - 18);
        pts.push(soleToScreen(lx, ly));
      }
    }

    if (pts.length > 4) {
      pts.push(pts[0]);
      if (ring === 0) {
        // Deepest inner hole: exposed dark sponge/canvas midsole with cross-hatching
        let [cx, cy] = soleToScreen(coreLx, coreLy);
        brush.set("toner_block", COL_TONER_BLACK, 2.0);
        for (let i = 0; i < pts.length - 1; i++) {
          brush.line(cx, cy, pts[i][0], pts[i][1]);
        }
        // Exposed inner canvas weave lines in white toner-resist inside the hole
        for (let t = -22; t <= 22; t += 5.5) {
          let [ax, ay] = soleToScreen(coreLx - 20, coreLy + t * 0.8);
          let [bx, by] = soleToScreen(coreLx + 20, coreLy + t * 0.8);
          brush.set("razor_ink", COL_PAPER_HIGH, 0.85);
          brush.line(ax, ay, bx, by);
        }
      } else if (ring === 1) {
        // Fluorescent orange misregistered inner tear rim
        brush.set("fluoro_screen", COL_FLUORO, 1.5);
        brush.spline(pts, 0.4);
        brush.set("rotring", COL_TONER_BLACK, 1.4);
        brush.spline(pts, 0.4);
      } else {
        // Outer delamination contour & rubber crumbs
        brush.set("2B", COL_TONER_DARK, 1.15);
        brush.spline(pts, 0.45);
      }
    }
  }

  // Intense asphalt friction striations across the bald spot
  for (let i = 0; i < 65; i++) {
    let ang = random(360);
    let distR = random(0.1, 1.55);
    let lx = coreLx + cos(ang) * rx * distR;
    let ly = coreLy + sin(ang) * ry * distR;
    if (soleSignedDist(lx, ly) < 14) continue;

    let [sx, sy] = soleToScreen(lx, ly);
    let scAng = SOLE_ANGLE + scratchAngleOffset + random(-18, 18);
    let scLen = random(14, 48);
    let ex = sx + cos(scAng) * scLen;
    let ey = sy + sin(scAng) * scLen;

    brush.set(random() < 0.4 ? "razor_ink" : "2B", COL_TONER_BLACK, random(0.6, 1.35));
    brush.line(sx, sy, ex, ey);
  }
}

// ============================================================================
// 5. CENTRAL MIDFOOT BRAND STAMP PLAQUE & RAIL GOUGES
// ============================================================================

function drawArchBrandPlaque() {
  let cx = 10;
  let cy = 88;
  let rx = 42;
  let ry = 92;

  // Build stadium outline points
  let outerPts = [];
  let innerPts = [];
  let orangePts = [];
  for (let a = 0; a <= 360; a += 10) {
    let px = cos(a) * rx;
    let py = sin(a) * (ry - 44) + (sin(a) >= 0 ? 44 : -44);
    outerPts.push(soleToScreen(cx + px, cy + py));
    innerPts.push(soleToScreen(cx + px * 0.82, cy + py * 0.90));
    orangePts.push(soleToScreen(cx + px * 0.90, cy + py * 0.94, MISREG_DX * 0.85, MISREG_DY * 0.85));
  }

  // 1. Misregistered fluorescent orange plaque shadow
  brush.set("fluoro_screen", COL_FLUORO, 1.8);
  brush.spline(orangePts, 0.3);

  // 2. Dark recessed interior of the brand stamp
  for (let ly = cy - 82; ly <= cy + 82; ly += 3.5) {
    for (let lx = cx - 34; lx <= cx + 34; lx += 8) {
      if (isInsidePlaque(lx, ly, -7)) {
        let [p1x, p1y] = soleToScreen(lx - 4, ly);
        let [p2x, p2y] = soleToScreen(lx + 4, ly);
        brush.set("toner_block", COL_TONER_BLACK, 1.35);
        brush.line(p1x, p1y, p2x, p2y);
      }
    }
  }

  // 3. Raised white rubber stadium rim & crisp black borders
  brush.set("toner_block", COL_PAPER_HIGH, 2.2);
  brush.spline(outerPts, 0.3);
  brush.set("rotring", COL_TONER_DEEP, 1.5);
  brush.spline(outerPts, 0.3);
  brush.set("rotring", COL_TONER_DEEP, 1.2);
  brush.spline(innerPts, 0.3);

  // 4. Molded rubber typography inside the plaque ("VULC // 10.5")
  // Drawn along the vertical axis of the sole in raised paper-white + orange ghost
  push();
  let [pcx, pcy] = soleToScreen(cx, cy);
  translate(pcx, pcy);
  rotate(SOLE_ANGLE + 90);

  // Orange misregistered molded text shadow
  drawVectorText("VULC-PRO", -56 + 6, -12 - 5, 11, 1.4, COL_FLUORO, "fluoro_screen");
  drawVectorText("US 10.5", -44 + 6,   6 - 5,  9, 1.2, COL_FLUORO, "fluoro_screen");

  // Blown-out raw paper white molded letters
  drawVectorText("VULC-PRO", -56, -12, 11, 1.6, COL_PAPER_HIGH, "toner_block");
  drawVectorText("US 10.5", -44,   6,  9, 1.3, COL_PAPER_HIGH, "toner_block");
  pop();

  // 5. Brutal horizontal board-slide / rail gouges cutting across the arch & plaque
  for (let g = 0; g < 9; g++) {
    let gy = cy + random(-65, 75);
    let gx1 = cx - random(45, 95);
    let gx2 = cx + random(45, 105);
    let [p1x, p1y] = soleToScreen(gx1, gy);
    let [p2x, p2y] = soleToScreen(gx2, gy + random(-14, 14));
    brush.set("rotring", COL_TONER_BLACK, random(1.1, 2.0));
    brush.line(p1x, p1y, p2x, p2y);
    brush.set("razor_ink", COL_PAPER_HIGH, 0.9);
    brush.line(p1x, p1y + 2, p2x, p2y + 2);
  }
}

// ============================================================================
// 6. HYPERREAL INCIDENTS: CHEWING-GUM SCAR & EMBEDDED PEBBLES
// ============================================================================

function drawChewingGumScar() {
  // Stepped-on chewing gum smeared across the medial forefoot/arch transition
  let gcx = -66;
  let gcy = -38;
  let grx = 58;
  let gry = 44;

  // 1. Stretched viscoelastic gum strands bridging across surrounding dark waffle grooves
  for (let i = 0; i < 38; i++) {
    let a1 = random(360);
    let r1 = random(0.55, 0.95);
    let r2 = random(1.05, 1.68);
    let lx1 = gcx + cos(a1) * grx * r1;
    let ly1 = gcy + sin(a1) * gry * r1;
    let lx2 = gcx + cos(a1 + random(-15, 15)) * grx * r2;
    let ly2 = gcy + sin(a1 + random(-15, 15)) * gry * r2;

    let [s1x, s1y] = soleToScreen(lx1, ly1);
    let [s2x, s2y] = soleToScreen(lx2, ly2);
    let [smx, smy] = soleToScreen((lx1 + lx2) * 0.5 + random(-6, 6), (ly1 + ly2) * 0.5 + random(-6, 6));

    // Black shadow under the taut gum strand
    brush.set("rotring", COL_TONER_DEEP, random(1.5, 2.6));
    brush.spline([[s1x + 2, s1y + 2], [smx + 2, smy + 2], [s2x + 2, s2y + 2]], 0.4);

    // Bright stretched gum filament
    brush.set("toner_block", COL_PAPER_HIGH, random(0.8, 1.5));
    brush.spline([[s1x, s1y], [smx, smy], [s2x, s2y]], 0.4);
  }

  // 2. Organic lobular contour of the flattened gum wad
  let gumPts = [];
  let gumOrangePts = [];
  for (let a = 0; a <= 360; a += 10) {
    let n = noise(cos(a) * 1.8 + 12, sin(a) * 1.8 + 34);
    let radX = grx * (0.62 + n * 0.62);
    let radY = gry * (0.62 + n * 0.62);
    let lx = gcx + cos(a) * radX;
    let ly = gcy + sin(a) * radY;
    gumPts.push(soleToScreen(lx, ly));
    gumOrangePts.push(soleToScreen(lx, ly, MISREG_DX * 0.75, MISREG_DY * 0.75));
  }

  // Misregistered fluorescent orange rim around the gum wad
  brush.set("fluoro_screen", COL_FLUORO, 2.0);
  brush.spline(gumOrangePts, 0.45);

  // Opaque raw-paper white mass where the gum is squashed flat against the scanner glass
  let [centerSx, centerSy] = soleToScreen(gcx, gcy);
  brush.set("toner_block", COL_PAPER_HIGH, 3.2);
  for (let i = 0; i < gumPts.length; i++) {
    brush.line(centerSx, centerSy, gumPts[i][0], gumPts[i][1]);
  }

  // Crusty black toner rim & internal compression folds / trapped street grit on the gum surface
  brush.set("rotring", COL_TONER_BLACK, 1.85);
  brush.spline(gumPts, 0.45);

  for (let ring = 0.35; ring <= 0.8; ring += 0.22) {
    let foldPts = [];
    for (let a = 20; a <= 310; a += 20) {
      let n = noise(cos(a) * 2 + ring * 10, sin(a) * 2);
      let lx = gcx + cos(a) * grx * ring * (0.7 + n * 0.5);
      let ly = gcy + sin(a) * gry * ring * (0.7 + n * 0.5);
      foldPts.push(soleToScreen(lx, ly));
    }
    brush.set("2B", COL_TONER_DARK, 1.0);
    brush.spline(foldPts, 0.45);
  }

  // Tiny trapped dirt specks and teeth/asphalt pockmarks in the gum
  for (let s = 0; s < 45; s++) {
    let a = random(360);
    let r = sqrt(random()) * 0.82;
    let [px, py] = soleToScreen(gcx + cos(a) * grx * r, gcy + sin(a) * gry * r);
    brush.set("razor_ink", COL_TONER_BLACK, random(0.7, 1.5));
    brush.line(px, py, px + random(-3, 3), py + random(-3, 3));
  }
}

function drawEmbeddedPebbles() {
  // 6 angular gravel stones wedged tightly into waffle cavities, distending the rubber walls
  const pebbles = [
    { lx:  72, ly: -150, r: 17 },
    { lx: -90, ly: -325, r: 15 },
    { lx:  90, ly: -350, r: 13 },
    { lx: -54, ly:  250, r: 16 },
    { lx:  54, ly:  200, r: 14 },
    { lx: -18, ly: -425, r: 13 }
  ];

  for (let p of pebbles) {
    let [cx, cy] = soleToScreen(p.lx, p.ly);

    // 1. Deep black rubber-distortion shadow around the wedged stone
    let rimPts = [];
    let facetPts = [];
    let numVerts = 6;
    for (let i = 0; i < numVerts; i++) {
      let a = i * (360 / numVerts) + random(-14, 14);
      let rad = p.r * random(0.82, 1.22);
      let vx = p.lx + cos(a) * rad;
      let vy = p.ly + sin(a) * rad;
      facetPts.push(soleToScreen(vx, vy));
      rimPts.push(soleToScreen(p.lx + cos(a) * (rad + 4.5), p.ly + sin(a) * (rad + 4.5)));
    }
    rimPts.push(rimPts[0]);
    facetPts.push(facetPts[0]);

    // Distended black cavity seat
    brush.set("toner_block", COL_TONER_DEEP, 2.4);
    for (let i = 0; i < rimPts.length - 1; i++) {
      brush.line(cx, cy, rimPts[i][0], rimPts[i][1]);
      brush.line(rimPts[i][0], rimPts[i][1], rimPts[i + 1][0], rimPts[i + 1][1]);
    }

    // Misregistered fluorescent orange mineral glint
    let [ox, oy] = soleToScreen(p.lx, p.ly, MISREG_DX * 0.6, MISREG_DY * 0.6);
    brush.set("fluoro_screen", COL_FLUORO, 1.6);
    brush.line(ox - p.r * 0.6, oy - p.r * 0.4, ox + p.r * 0.6, oy + p.r * 0.4);

    // 2. Angular crystal cleavage facets:
    // Ridge point slightly off-center
    let [rx, ry] = soleToScreen(p.lx + random(-3, 3), p.ly + random(-3, 3));

    for (let i = 0; i < numVerts; i++) {
      let v1 = facetPts[i];
      let v2 = facetPts[i + 1];

      if (i < 3) {
        // Bright blown-out white mineral face pressed flat against the glass
        for (let t = 0; t <= 1; t += 0.16) {
          let tx = lerp(v1[0], v2[0], t);
          let ty = lerp(v1[1], v2[1], t);
          brush.set("toner_block", COL_PAPER_HIGH, 1.35);
          brush.line(rx, ry, tx, ty);
        }
      } else {
        // Shadowed/hatched mineral facet
        for (let t = 0; t <= 1; t += 0.2) {
          let tx = lerp(v1[0], v2[0], t);
          let ty = lerp(v1[1], v2[1], t);
          brush.set("razor_ink", COL_PAPER, 0.8);
          brush.line(rx, ry, tx, ty);
        }
      }

      // Crisp black facet ridge lines
      brush.set("rotring", COL_TONER_BLACK, 1.25);
      brush.line(rx, ry, v1[0], v1[1]);
      brush.line(v1[0], v1[1], v2[0], v2[1]);
    }

    // Rubber stress cracks radiating from the wedged pebble into the surrounding waffle lugs
    for (let c = 0; c < 4; c++) {
      let ca = random(360);
      let [c1x, c1y] = soleToScreen(p.lx + cos(ca) * p.r, p.ly + sin(ca) * p.r);
      let [c2x, c2y] = soleToScreen(p.lx + cos(ca) * (p.r + 12), p.ly + sin(ca) * (p.r + 12));
      brush.set("razor_ink", COL_TONER_BLACK, 1.1);
      brush.line(c1x, c1y, c2x, c2y);
    }
  }
}

// ============================================================================
// 7. FRAYED CANVAS EDGE & EXPLODING GRIPTAPE-SHREDDED THREADS
// ============================================================================

function drawFrayedCanvasAndThreads() {
  // Around the lateral forefoot (ollie/kickflip zone, ly in [-450, -70]), medial toe, and heel counter,
  // the canvas upper peeks past the worn vulcanized bumper with frayed weave and exploding threads.
  const frayZones = [
    { yStart: -450, yEnd: -65,  side:  1, density: 1.0 }, // Lateral ollie & kickflip abrasion zone
    { yStart: -535, yEnd: -320, side: -1, density: 0.7 }, // Medial toe drag
    { yStart:  340, yEnd:  525, side:  1, density: 0.5 }  // Lateral heel scuff
  ];

  for (let z of frayZones) {
    // 1. Shredded canvas weave tufts peeking out along the shoe edge
    for (let ly = z.yStart; ly <= z.yEnd; ly += 4.5) {
      if (random() > z.density) continue;
      let s = getSoleSlice(ly);
      if (!s.valid) continue;

      let baseLx = (z.side > 0) ? s.maxX : s.minX;
      let tuftOut = random(6, 26) * z.density;

      // Cross-hatched warp & weft canvas threads
      let [p1x, p1y] = soleToScreen(baseLx - z.side * 4, ly);
      let [p2x, p2y] = soleToScreen(baseLx + z.side * tuftOut, ly + random(-6, 6));

      // Misregistered orange thread shadow on some tufts
      if (random() < 0.35) {
        brush.set("fluoro_screen", COL_FLUORO, 0.9);
        brush.line(p1x + MISREG_DX * 0.6, p1y + MISREG_DY * 0.6, p2x + MISREG_DX * 0.6, p2y + MISREG_DY * 0.6);
      }

      // Black shadow behind tuft
      brush.set("rotring", COL_TONER_BLACK, 1.4);
      brush.line(p1x + 2, p1y + 2, p2x + 2, p2y + 2);

      // Bright blown-out white cotton thread tuft
      brush.set("razor_ink", COL_PAPER_HIGH, 1.15);
      brush.line(p1x, p1y, p2x, p2y);
    }

    // 2. Long curly exploding cotton threads lying on the copier glass
    let numThreads = floor(42 * z.density);
    for (let t = 0; t < numThreads; t++) {
      let ly = random(z.yStart, z.yEnd);
      let s = getSoleSlice(ly);
      if (!s.valid) continue;

      let curLx = (z.side > 0) ? s.maxX - random(-2, 6) : s.minX + random(-2, 6);
      let curLy = ly;

      let threadPts = [];
      let shadowPts = [];
      let segs = floor(random(4, 8));
      let angle = (z.side > 0) ? random(-55, 55) : random(125, 235);

      for (let k = 0; k < segs; k++) {
        threadPts.push(soleToScreen(curLx, curLy));
        shadowPts.push(soleToScreen(curLx + 3.5, curLy + 3.5));
        let stepLen = random(8, 18);
        angle += random(-42, 42);
        curLx += cos(angle) * stepLen;
        curLy += sin(angle) * stepLen;
      }

      // Crisp black photocopy shadow of the thread on the glass
      brush.set("rotring", COL_TONER_BLACK, random(0.9, 1.45));
      brush.spline(shadowPts, 0.5);

      // Bright white cotton fiber
      brush.set("razor_ink", COL_PAPER_HIGH, random(0.85, 1.3));
      brush.spline(threadPts, 0.5);
    }
  }
}

