// 8. GLOBAL PHOTOCOPIER DRUM BANDING, CORONA SCRATCHES & TONER GRIT
// ============================================================================

function drawPhotocopierArtifacts() {
  brush.noField();

  // 1. Horizontal drum roller banding streaks across the entire page
  for (let band = 0; band < 18; band++) {
    let by = random(30, 1170);
    let bandH = random(8, 28);
    let linesInBand = floor(random(5, 14));

    for (let i = 0; i < linesInBand; i++) {
      let y = by + random(-bandH * 0.5, bandH * 0.5);
      let x1 = random(0, 350);
      let x2 = random(850, 1200);
      brush.set("drum_band", COL_TONER_DARK, random(0.5, 1.15));
      brush.line(x1, y, x2, y);
    }
  }

  // 2. Vertical corona-wire toner dropout scratches (razor-thin white & black streaks running full height)
  const scratchX = [184, 462, 465, 818, 1042];
  for (let sx of scratchX) {
    let isWhiteDropout = (sx === 462 || sx === 818);
    for (let y = 0; y < 1200; y += random(90, 220)) {
      let yEnd = min(1200, y + random(70, 195));
      if (isWhiteDropout) {
        brush.set("razor_ink", COL_PAPER_HIGH, 0.95);
      } else {
        brush.set("razor_ink", COL_TONER_BLACK, 0.85);
      }
      brush.line(sx + random(-0.5, 0.5), y, sx + random(-0.5, 0.5), yEnd);
    }
  }

  // 3. Heavy spray speckle & glass platen dust specks across midtones and dark corners
  for (let i = 0; i < 420; i++) {
    let sx = random(15, 1185);
    let sy = random(15, 1185);
    let [lx, ly] = screenToSole(sx, sy);
    let d = soleSignedDist(lx, ly);

    if (d < -15) {
      // White glass dust specks & scratches in the dark platen corners
      if (random() < 0.45) {
        brush.set("razor_ink", COL_PAPER, random(0.7, 1.4));
        brush.line(sx, sy, sx + random(-5, 5), sy + random(-5, 5));
      } else {
        brush.set("toner_dust", COL_TONER_BLACK, random(0.8, 1.8));
        brush.line(sx, sy, sx + random(-14, 14), sy + random(-6, 6));
      }
    } else {
      // Gritty toner speckle inside the sole
      if (random() < 0.35) {
        brush.set("toner_dust", COL_TONER_BLACK, random(0.5, 1.2));
        brush.line(sx, sy, sx + random(-10, 10), sy + random(-10, 10));
      }
    }
  }

  // 4. Rough xerox border frame / edge burn around all 4 sides of the 1200x1200 page
  for (let i = 0; i < 4; i++) {
    brush.set("toner_block", COL_TONER_DEEP, 2.6);
    brush.line(0, 4 + i * 3, 1200, 4 + i * 3);
    brush.line(0, 1196 - i * 3, 1200, 1196 - i * 3);
    brush.line(4 + i * 3, 0, 4 + i * 3, 1200);
    brush.line(1196 - i * 3, 0, 1196 - i * 3, 1200);
  }
}

