function drawTornMaskingTape(cx, cy, w, h, ang) {
  push();
  translate(cx, cy);
  rotate(ang);

  let x0 = -w / 2;
  let y0 = -h / 2;

  // Build jagged serrated torn ends on left and right, smooth crepe sides on top and bottom
  let tapePoly = [];
  let stepsX = 14;
  for (let i = 0; i <= stepsX; i++) {
    let px = lerp(x0, x0 + w, i / stepsX);
    let py = y0 + (noise(i * 0.6, cy) - 0.5) * 3.5;
    tapePoly.push([px, py]);
  }
  // Right torn serrated edge
  let teeth = 7;
  for (let i = 1; i <= teeth; i++) {
    let py = lerp(y0, y0 + h, i / teeth);
    let jag = (i % 2 === 1) ? random(5, 11) : random(-6, -2);
    tapePoly.push([x0 + w + jag, py]);
  }
  // Bottom edge
  for (let i = stepsX; i >= 0; i--) {
    let px = lerp(x0, x0 + w, i / stepsX);
    let py = y0 + h + (noise(i * 0.6, cx) - 0.5) * 3.5;
    tapePoly.push([px, py]);
  }
  // Left torn serrated edge
  for (let i = teeth - 1; i >= 1; i--) {
    let py = lerp(y0, y0 + h, i / teeth);
    let jag = (i % 2 === 1) ? random(-11, -5) : random(2, 6);
    tapePoly.push([x0 + jag, py]);
  }

  // 1. Dark toner shadow along bottom and torn edges of the tape
  brush.set("rotring", COL_TONER_BLACK, 1.6);
  for (let i = 0; i < tapePoly.length; i++) {
    let a = tapePoly[i];
    let b = tapePoly[(i + 1) % tapePoly.length];
    brush.line(a[0] + 2.5, a[1] + 2.5, b[0] + 2.5, b[1] + 2.5);
  }

  // 2. Semi-opaque warm buff masking tape wash + watercolor bleed
  brush.noStroke();
  brush.wash(COL_TAPE, 215);
  brush.rect(x0, y0, w, h, "corner");
  brush.noWash();

  brush.fill(COL_TAPE_DARK, 75);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.55, 0.65);
  brush.rect(x0 + 2, y0 + 2, w - 4, h - 4, "corner");
  brush.noFill();

  // 3. Crepe paper texture & diagonal pressure wrinkles across the tape
  brush.hatchStyle("2B", COL_TAPE_EDGE, 0.75);
  brush.hatch(4.5, 12, { rand: 0.12 });
  brush.noStroke();
  brush.rect(x0 + 3, y0 + 3, w - 6, h - 6, "corner");
  brush.noHatch();

  for (let k = 0; k < 5; k++) {
    let wx1 = random(x0 + 18, x0 + w - 25);
    let wx2 = wx1 + random(-22, 22);
    brush.set("razor_ink", COL_PAPER_HIGH, 1.0);
    brush.line(wx1, y0 + 2, wx2, y0 + h - 2);
    brush.set("2B", COL_TAPE_EDGE, 0.9);
    brush.line(wx1 + 1.5, y0 + 2, wx2 + 1.5, y0 + h - 2);
  }

  // 4. Crisp fibrous outline around the torn tape perimeter
  brush.set("2B", COL_TONER_DARK, 1.15);
  for (let i = 0; i < tapePoly.length; i++) {
    let a = tapePoly[i];
    let b = tapePoly[(i + 1) % tapePoly.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }

  pop();
}

