function drawVectorText(str, startX, startY, charH, weight, col, brushName) {
  let charW = charH * 0.62;
  let spacing = charH * 0.92;

  for (let idx = 0; idx < str.length; idx++) {
    let ch = str[idx].toUpperCase();
    let paths = GLYPHS[ch];
    if (!paths) continue;

    // Slight typewriter key baseline hop & ribbon ink variation
    let ox = startX + idx * spacing + (noise(idx * 3.1, startY) - 0.5) * 1.4;
    let oy = startY + (noise(idx * 7.3, startX) - 0.5) * 2.2;
    let wMult = weight * random(0.88, 1.18);

    brush.set(brushName, col, wMult);
    for (let path of paths) {
      for (let i = 0; i < path.length - 1; i++) {
        let x1 = ox + path[i][0] * charW;
        let y1 = oy + path[i][1] * charH;
        let x2 = ox + path[i + 1][0] * charW;
        let y2 = oy + path[i + 1][1] * charH;
        brush.line(x1, y1, x2, y2);
      }
    }

    // Occasional typewriter overstrike / ink blob on heavy letters
    if (random() < 0.28) {
      let path = paths[0];
      let x1 = ox + path[0][0] * charW + 0.6;
      let y1 = oy + path[0][1] * charH + 0.6;
      let x2 = ox + path[1][0] * charW + 0.6;
      let y2 = oy + path[1][1] * charH + 0.6;
      brush.set(brushName, col, wMult * 1.15);
      brush.line(x1, y1, x2, y2);
    }
  }
}

