async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4289);
  noiseSeed(1733);

  // Tapering rosemaling liner brush: starts fat when pressed, flicks to a razor hairline
  brush.add("rosemaling_liner", {
    type: "default",
    weight: 2.3,
    scatter: 0.06,
    sharpness: 0.82,
    grain: 14,
    opacity: 225,
    spacing: 0.14,
    pressure: (t) => Math.pow(1 - t, 1.65) * 1.65 + 0.03,
    rotate: "natural",
    noise: 0.25
  });

  // Swelling rosemaling leaf/scroll brush: fat belly, tapered start and hairline flick end
  brush.add("rosemaling_quill", {
    type: "default",
    weight: 3.6,
    scatter: 0.08,
    sharpness: 0.74,
    grain: 18,
    opacity: 210,
    spacing: 0.16,
    pressure: (t) => {
      if (t < 0.18) return map(t, 0, 0.18, 0.45, 1.65);
      return Math.pow(1 - (t - 0.18) / 0.82, 1.55) * 1.65 + 0.03;
    },
    rotate: "natural",
    noise: 0.3
  });

  // Chalky dry brush for the spongy albedo pith underside
  brush.add("pith_chalk", {
    type: "default",
    weight: 3.0,
    scatter: 0.32,
    sharpness: 0.35,
    grain: 52,
    opacity: 165,
    spacing: 0.24,
    pressure: [0.85, 1.35, 0.55, 0.12],
    rotate: "natural",
    noise: 0.55
  });

  // Fine fibrous brush for vascular threads on the pith
  brush.add("pith_thread", {
    type: "default",
    weight: 0.95,
    scatter: 0.12,
    sharpness: 0.88,
    grain: 28,
    opacity: 205,
    spacing: 0.13,
    pressure: [0.15, 1.25, 0.75, 0.04],
    rotate: "natural",
    noise: 0.45
  });

  // Crisp highlight liner for specular ridges and oil pore dimples
  brush.add("specular_liner", {
    type: "default",
    weight: 1.65,
    scatter: 0.03,
    sharpness: 0.92,
    grain: 8,
    opacity: 245,
    spacing: 0.12,
    pressure: (t) => Math.pow(1 - t, 1.4) * 1.5 + 0.04,
    rotate: "natural",
    noise: 0.15
  });

  // Soft wide glaze brush for wooden panel grain and atmospheric depth
  brush.add("panel_glaze", {
    type: "default",
    weight: 10.0,
    scatter: 0.65,
    sharpness: 0.18,
    grain: 32,
    opacity: 38,
    spacing: 0.35,
    pressure: [0.35, 1.15, 0.35],
    rotate: "natural",
    noise: 0.3
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.bgDeep);

  // 1. Deep Norwegian Blue-Green Painted Wood Panel Ground
  drawNorwegianGround();

  // 2. Thin Margin & Soft Vermilion Rosemaling Acanthus Corner Flourishes
  drawMarginAndAcanthusCorners();

  // 3. Build 3D Spiraling Rosemaling Lemon Peel Geometry
  const peelData = buildPeelGeometry();

  // 4. Ambient Cast Shadow & Warm Reflected Glow on the Panel
  drawPeelCastShadows(peelData);

  // 5. Paring Knife (Main Blade & Handle before the top peel hook wraps over the tip)
  drawParingKnifeBase();

  // 6. The Single Unbroken Spiraling Lemon Peel
  drawLemonPeel(peelData);

  // 7. Paring Knife Tip Bevel Over-Pass & Lemon Oil Droplet
  drawParingKnifeTipOverlay();

  noLoop();
}

// ============================================================================
// 1. NORWEGIAN BLUE-GREEN GROUND
// ============================================================================
function drawNorwegianGround() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Base solid wash
  brush.wash(PALETTE.bgDark, 255);
  brush.rect(0, 0, width, height, "corner");
  brush.noWash();

  // Batched watercolor luminous glazes in the center-upper light zone
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.55, 0.22);

  brush.fill(PALETTE.bgMid, 95);
  brush.circle(590, 540, 490, 0.18);
  brush.circle(580, 380, 410, 0.2);

  brush.fill(PALETTE.bgTeal, 78);
  brush.circle(575, 470, 360, 0.22);
  brush.circle(610, 710, 330, 0.22);

  brush.fill(PALETTE.bgLight, 52);
  brush.circle(560, 340, 250, 0.25);
  brush.circle(590, 610, 260, 0.25);

  // Deep Prussian-pine corner vignettes
  brush.fill(PALETTE.bgDeep, 130);
  brush.rect(0, 0, 1200, 110, "corner");
  brush.rect(0, 1090, 1200, 110, "corner");
  brush.rect(0, 0, 110, 1200, "corner");
  brush.rect(1090, 0, 110, 1200, "corner");
  brush.noFill();

  // Fine vertical painted wood-panel grain and bristle texture
  for (let i = 0; i < 240; i++) {
    let x = map(i, 0, 239, 15, 1185) + random(-4, 4);
    let y1 = random(0, 180);
    let y2 = random(1020, 1200);
    let distFromCenter = dist(x, 600, 585, 520);
    let col =
      distFromCenter < 380
        ? random([PALETTE.bgTeal, PALETTE.bgLight, PALETTE.bgMid, PALETTE.bgGlow])
        : random([PALETTE.bgDeep, PALETTE.bgDark, PALETTE.bgMid]);
    brush.set("panel_glaze", col, random(0.6, 1.45));
    let midY = (y1 + y2) * 0.5 + random(-60, 60);
    let wobble = sin(i * 4.5) * 6;
    brush.spline(
      [
        [x, y1, 0.4],
        [x + wobble, midY, 0.9],
        [x - wobble * 0.5, y2, 0.4]
      ],
      0.35
    );
  }

  // Subtle horizontal cross-brushed tempera tooth
  for (let i = 0; i < 95; i++) {
    let y = random(20, 1180);
    let x1 = random(20, 350);
    let x2 = random(850, 1180);
    let col = random([PALETTE.bgDark, PALETTE.bgMid, PALETTE.bgTeal]);
    brush.set("2B", col, random(0.35, 0.7));
    brush.line(x1, y, x2, y + random(-3, 3));
  }
}

