// ============================================================================
// 3. 3D SPIRALING ROSEMALING LEMON PEEL GEOMETRY
// ============================================================================
function catmullRomVal(p0, p1, p2, p3, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  return (
    0.5 *
    (2 * p1 +
      (-p0 + p2) * t +
      (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 +
      (-p0 + 3 * p1 - 3 * p2 + p3) * t3)
  );
}

function buildPeelGeometry() {
  // 31 control nodes defining a single unbroken peel hanging from the knife tip (595, 192)
  // and spiraling down in swelling Norwegian rosemaling C- and S-scrolls.
  // Fields: [x, y, halfWidth, faceSign (-1 = pith, +1 = zest), zDepth, crossAngleOffset]
  const nodes = [
    // Top hook around the paring knife tip at (595, 192)
    [572, 168, 14, -0.75, -15, 0],
    [608, 188, 20, -0.25, 18, 10],
    [588, 218, 27, 0.78, 25, -8],
    [515, 236, 33, 0.95, 15, -12],

    // Scroll 1: Upper-Left Swelling C-Scroll -> S-Bridge Right
    [422, 266, 40, 0.88, 5, -5],
    [388, 326, 36, 0.15, -8, 12],
    [462, 376, 34, -0.88, -22, 18],
    [608, 348, 37, -0.92, -12, 8],

    // Scroll 2: Upper-Right Swelling C-Scroll
    [742, 368, 42, -0.22, 8, -10],
    [792, 434, 46, 0.92, 24, -16],
    [712, 496, 42, 0.96, 20, -10],
    [555, 470, 36, 0.42, 6, 6],

    // Scroll 3: Great Mid-Left Rosemaling C-Scroll Belly
    [382, 492, 44, -0.78, -16, 15],
    [318, 574, 48, 0.25, 8, -10],
    [392, 652, 49, 0.98, 28, -18],
    [548, 622, 40, 0.86, 18, -8],
    [668, 598, 35, -0.45, -10, 12],

    // Scroll 4: Great Mid-Right Rosemaling C-Scroll Belly
    [795, 626, 44, -0.92, -20, 16],
    [852, 708, 48, -0.15, 5, -8],
    [775, 792, 47, 0.96, 26, -15],
    [602, 764, 38, 0.88, 16, -6],

    // Scroll 5: Lower-Left Swelling Scroll
    [432, 782, 40, -0.25, -8, 12],
    [368, 858, 44, -0.92, -22, 18],
    [452, 928, 42, 0.28, 6, -10],
    [612, 896, 39, 0.94, 22, -12],

    // Scroll 6: Lower-Right Scroll -> Terminal Snail Volute
    [744, 924, 42, 0.88, 18, -8],
    [774, 996, 38, 0.15, -6, 10],
    [676, 1062, 34, -0.82, -18, 14],
    [542, 1054, 30, 0.55, 12, -10],
    [492, 994, 23, 0.92, 24, -12],
    [546, 948, 15, 0.75, 28, -6],
    [594, 978, 5, 0.45, 30, 0]
  ];

  const totalSamples = 820;
  const numSegs = nodes.length - 1;
  const raw = [];

  for (let i = 0; i <= totalSamples; i++) {
    let u = (i / totalSamples) * numSegs;
    let idx = Math.min(Math.floor(u), numSegs - 1);
    let lt = u - idx;

    let n0 = nodes[Math.max(0, idx - 1)];
    let n1 = nodes[idx];
    let n2 = nodes[Math.min(numSegs, idx + 1)];
    let n3 = nodes[Math.min(numSegs, idx + 2)];

    let x = catmullRomVal(n0[0], n1[0], n2[0], n3[0], lt);
    let y = catmullRomVal(n0[1], n1[1], n2[1], n3[1], lt);
    let w = catmullRomVal(n0[2], n1[2], n2[2], n3[2], lt);
    let face = constrain(catmullRomVal(n0[3], n1[3], n2[3], n3[3], lt), -1, 1);
    let z = catmullRomVal(n0[4], n1[4], n2[4], n3[4], lt);
    let angOff = catmullRomVal(n0[5], n1[5], n2[5], n3[5], lt);

    // Add subtle rosemaling leaf-lobe swelling along the scroll bellies
    let normT = i / totalSamples;
    let lobeSwell = 1.0 + 0.14 * Math.sin(normT * Math.PI * 22) * Math.sin(normT * Math.PI);
    w *= lobeSwell;

    raw.push({ t: normT, x, y, w, face, z, angOff });
  }

  // Compute smooth tangents, 2D normals, and 3D solid-ribbon rails (zest rails + pith rails)
  for (let i = 0; i < raw.length; i++) {
    let pPrev = raw[Math.max(0, i - 2)];
    let pNext = raw[Math.min(raw.length - 1, i + 2)];
    let dx = pNext.x - pPrev.x;
    let dy = pNext.y - pPrev.y;
    let len = Math.hypot(dx, dy) || 1;
    let tx = dx / len;
    let ty = dy / len;

    // 2D perpendicular vector rotated slightly by calligraphic angle offset
    let baseNx = -ty;
    let baseNy = tx;
    let rad = (raw[i].angOff * Math.PI) / 180;
    let nx = baseNx * Math.cos(rad) - baseNy * Math.sin(rad);
    let ny = baseNx * Math.sin(rad) + baseNy * Math.cos(rad);

    raw[i].tx = tx;
    raw[i].ty = ty;
    raw[i].nx = nx;
    raw[i].ny = ny;

    // Apparent projected half-width of the ribbon face
    // Keep a minimum foreshortened width so transitions are smooth and organic
    let f = raw[i].face;
    let projHalfW = raw[i].w * (0.14 + 0.86 * Math.abs(f));

    // Cut rind thickness (chalky white pith layer under the yellow flavedo skin)
    // Tapers slightly at the very ends of the peel
    let endTaper = constrain(Math.sin(raw[i].t * Math.PI) * 2.5, 0.35, 1.0);
    let thickness = 8.5 * endTaper;

    // Direction of the cut thickness rim in 2D screen space
    let rimSign = f >= 0 ? 1 : -1;
    let rimDx = (nx * 0.72 + tx * 0.28) * thickness * rimSign;
    let rimDy = (ny * 0.72 + ty * 0.28 + 0.35) * thickness * rimSign;

    // Top (visible) face rails
    raw[i].leftX = raw[i].x - nx * projHalfW;
    raw[i].leftY = raw[i].y - ny * projHalfW;
    raw[i].rightX = raw[i].x + nx * projHalfW;
    raw[i].rightY = raw[i].y + ny * projHalfW;

    // Cut thickness offset rails (underside edge of the rind slab)
    raw[i].underLeftX = raw[i].leftX + rimDx;
    raw[i].underLeftY = raw[i].leftY + rimDy;
    raw[i].underRightX = raw[i].rightX + rimDx;
    raw[i].underRightY = raw[i].rightY + rimDy;
    raw[i].projHalfW = projHalfW;
    raw[i].thickness = thickness;
  }

  return raw;
}

// ============================================================================
// 4. CAST SHADOWS & WARM LEMON BOUNCE GLOW ON THE GROUND
// ============================================================================
function drawPeelCastShadows(samples) {
  // Soft warm yellow-green reflected bounce light under the largest zest bellies
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.15);
  brush.fill("#284f48", 55);
  brush.circle(415, 585, 130, 0.25);
  brush.circle(785, 715, 135, 0.25);
  brush.circle(730, 440, 115, 0.25);
  brush.circle(590, 960, 120, 0.25);
  brush.noFill();

  // Deep atmospheric cast shadow from the peel & knife onto the wooden panel
  for (let i = 4; i < samples.length - 4; i += 3) {
    let s0 = samples[i - 3];
    let s1 = samples[i];
    let s2 = samples[i + 3];

    // Shadow offset depends slightly on 3D height z above the panel
    let zLift = map(s1.z, -25, 30, 10, 32);
    let ox = zLift * 0.78;
    let oy = zLift * 1.05;

    brush.set("panel_glaze", PALETTE.bgDeep, map(s1.projHalfW, 8, 50, 0.65, 2.1));
    brush.spline(
      [
        [s0.x + ox, s0.y + oy, 0.6],
        [s1.x + ox, s1.y + oy, 1.1],
        [s2.x + ox, s2.y + oy, 0.6]
      ],
      0.5
    );
  }

  // Knife cast shadow on the upper-left panel
  brush.set("panel_glaze", PALETTE.bgDeep, 2.2);
  brush.spline(
    [
      [180, 55, 1.2],
      [395, 142, 1.1],
      [612, 222, 0.4]
    ],
    0.3
  );
}

