    brush.set("rosemaling_liner", col, random(0.45, 0.85));
    brush.spline(
      [
        [x1, y1, 0.8],
        [(x1 + x2) * 0.5, (y1 + y2) * 0.5, 1.1],
        [x2, y2, 0.5]
      ],
      0.25
    );
  }

  // Brass Rivets on Handle
  drawRivet(218, 42, 6.5);
  drawRivet(292, 72, 6.5);

  // 2. Forged Brass/Steel Bolster (Ferrule)
  brush.noStroke();
  brush.wash(PALETTE.brassDark, 255);
  brush.beginShape(0.1);
  brush.vertex(354, 73);
  brush.vertex(376, 82);
  brush.vertex(358, 120);
  brush.vertex(338, 113);
  brush.endShape(true);
  brush.noWash();

  brush.set("rosemaling_quill", PALETTE.brassMid, 0.75);
  brush.spline(
    [
      [355, 76, 1.3],
      [366, 88, 1.0],
      [352, 116, 0.3]
    ],
    0.3
  );
  brush.set("specular_liner", PALETTE.brassLight, 0.7);
  brush.spline(
    [
      [357, 77, 1.4],
      [368, 84, 0.9],
      [362, 98, 0.1]
    ],
    0.3
  );

  // 3. Forged Carbon-Steel Paring Blade
  brush.noStroke();
  brush.wash(PALETTE.steelSlate, 255);
  brush.beginShape(0.12);
  brush.vertex(374, 82);
  brush.vertex(490, 138);
  brush.vertex(595, 192);
  brush.vertex(525, 178);
  brush.vertex(435, 152);
  brush.vertex(358, 119);
  brush.endShape(true);
  brush.noWash();

  // Layered metallic steel planes (cool sky reflection top, dark slate mid, warm lemon bounce bottom)
  for (let i = 0; i < 42; i++) {
    let f = i / 41; // 0 = spine, 1 = cutting edge
    let xStart = lerp(374, 358, f);
    let yStart = lerp(82, 119, f);
    let xMid = lerp(488, 468, f);
    let yMid = lerp(137, 162, f);
    let xEnd = 595;
    let yEnd = 192;

    let col;
    if (f < 0.15) {
      col = PALETTE.steelBright; // Forged spine catch-light
    } else if (f < 0.42) {
      col = lerpColor(color(PALETTE.steelDark), color(PALETTE.steelMid), (f - 0.15) / 0.27);
    } else if (f < 0.78) {
      col = lerpColor(color(PALETTE.steelMid), color(PALETTE.steelLight), (f - 0.42) / 0.36);
    } else {
      // Warm cadmium-yellow reflection from the lemon peel onto the lower bevel!
      col = lerpColor(color(PALETTE.steelBright), color(PALETTE.zestLemon), (f - 0.78) / 0.22 * 0.75);
    }

    brush.set("rosemaling_liner", col, map(f, 0, 1, 0.65, 0.45));
    brush.spline(
      [
        [xStart, yStart, 1.2],
        [xMid, yMid, 0.85],
        [xEnd, yEnd, 0.12]
      ],
      0.35
    );
  }

  // Fine vertical grind striations on the steel blade
  for (let i = 0; i < 36; i++) {
    let t = random(0.06, 0.92);
    let sx = lerp(374, 595, t);
    let sy = lerp(82, 192, t);
    let ex = lerp(358, 595, t);
    let ey = lerp(119, 192, t) + (1 - t) * 8 * Math.sin(t * Math.PI);
    let col = random([PALETTE.steelDark, PALETTE.steelLight, PALETTE.steelBright]);
    brush.set("pith_thread", col, random(0.25, 0.5));
    brush.line(sx, sy, ex, ey);
  }

  // Crisp spine highlight & razor bevel edge
  brush.set("specular_liner", PALETTE.steelEdge, 0.75);
  brush.spline(
    [
      [374, 82, 1.3],
      [488, 137, 0.95],
      [595, 192, 0.35]
    ],
    0.25
  );
  brush.set("specular_liner", PALETTE.zestCream, 0.6);
  brush.spline(
    [
      [360, 119, 0.9],
      [468, 162, 1.2],
      [595, 192, 0.4]
    ],
    0.35
  );
}

