// ============================================================================
// 6. THE SINGLE UNBROKEN SPIRALING LEMON PEEL
// ============================================================================
function drawLemonPeel(samples) {
  // Break the continuous 820-sample ribbon into overlapping chunks of 10 samples,
  // and sort chunks by average 3D z-depth so back turns pass cleanly behind front turns!
  const chunkSize = 10;
  const chunks = [];
  for (let start = 0; start < samples.length - 1; start += chunkSize) {
    let end = Math.min(samples.length - 1, start + chunkSize + 2); // +2 overlap for seamless joins
    let sumZ = 0;
    for (let k = start; k <= end; k++) sumZ += samples[k].z;
    let avgZ = sumZ / (end - start + 1);
    chunks.push({ start, end, avgZ });
  }

  chunks.sort((a, b) => a.avgZ - b.avgZ);

  for (let c of chunks) {
    renderPeelChunk(samples, c.start, c.end);
  }

  // After all depth-sorted chunks establish the solid 3D unbroken ribbon,
  // we paint the long, sweeping Rosemaling Liner-Brush Rind Strokes, Oily Pore Dimples,
  // Pith Fibrous Threads, Scalloped Rosemaling Tendrils, and Glossy Specular Ridges
  // across the front-most scroll faces so every stroke has maximum calligraphic continuity!
  drawLongRosemalingRindStrokes(samples);
  drawOilyPoreDimples(samples);
  drawPithFibrousThreads(samples);
  drawGlossySpecularRidges(samples);
  drawRosemalingRindTendrils(samples);
}

function renderPeelChunk(samples, startIdx, endIdx) {
  let midIdx = Math.floor((startIdx + endIdx) * 0.5);
  let sMid = samples[midIdx];
  let isZest = sMid.face >= 0;

  // 1. Draw the 3D Cut-Rind Thickness Slab first (the cut edge of the peel)
  // On zest-facing segments, the cut edge is chalky ivory pith;
  // on pith-facing segments, the cut edge shows a thin rim of golden-yellow zest!
  brush.noStroke();
  let cutEdgeBaseCol = isZest ? PALETTE.pithWarmMid : PALETTE.zestCadmiumDeep;
  brush.wash(cutEdgeBaseCol, 250);
  brush.beginShape(0.2);
  for (let i = startIdx; i <= endIdx; i += 2) {
    brush.vertex(samples[i].leftX, samples[i].leftY);
  }
  for (let i = startIdx; i <= endIdx; i += 2) {
    brush.vertex(samples[i].rightX, samples[i].rightY);
  }
  for (let i = endIdx; i >= startIdx; i -= 2) {
    brush.vertex(samples[i].underRightX, samples[i].underRightY);
  }
  for (let i = endIdx; i >= startIdx; i -= 2) {
    brush.vertex(samples[i].underLeftX, samples[i].underLeftY);
  }
  brush.endShape(true);
  brush.noWash();

  // Texture the cut thickness rim with fine liner/chalk strokes
  let s0 = samples[startIdx];
  let s1 = samples[midIdx];
  let s2 = samples[endIdx];
  let rimCol1 = isZest ? PALETTE.pithIvory : PALETTE.zestCadmium;
  let rimCol2 = isZest ? PALETTE.pithCoolShadow : PALETTE.zestAmber;

  brush.set("pith_chalk", rimCol2, 0.72);
  brush.spline(
    [
      [s0.underLeftX, s0.underLeftY, 0.9],
      [s1.underLeftX, s1.underLeftY, 1.1],
      [s2.underLeftX, s2.underLeftY, 0.8]
    ],
    0.45
  );
  brush.set("rosemaling_liner", rimCol1, 0.78);
  brush.spline(
    [
      [(s0.leftX + s0.underLeftX) * 0.5, (s0.leftY + s0.underLeftY) * 0.5, 1.0],
      [(s1.leftX + s1.underLeftX) * 0.5, (s1.leftY + s1.underLeftY) * 0.5, 1.2],
      [(s2.leftX + s2.underLeftX) * 0.5, (s2.leftY + s2.underLeftY) * 0.5, 0.8]
    ],
    0.45
  );
  brush.spline(
    [
      [(s0.rightX + s0.underRightX) * 0.5, (s0.rightY + s0.underRightY) * 0.5, 1.0],
      [(s1.rightX + s1.underRightX) * 0.5, (s1.rightY + s1.underRightY) * 0.5, 1.2],
      [(s2.rightX + s2.underRightX) * 0.5, (s2.rightY + s2.underRightY) * 0.5, 0.8]
    ],
    0.45
  );

  // 2. Draw the Main Ribbon Face (Zest or Pith)
  brush.noStroke();
  let faceBaseCol = isZest ? PALETTE.zestCadmiumDeep : PALETTE.pithWarmMid;
  brush.wash(faceBaseCol, 255);
  brush.beginShape(0.2);
  for (let i = startIdx; i <= endIdx; i++) {
    brush.vertex(samples[i].leftX, samples[i].leftY);
  }
  for (let i = endIdx; i >= startIdx; i--) {
    brush.vertex(samples[i].rightX, samples[i].rightY);
  }
  brush.endShape(true);
  brush.noWash();

  // 3. Sculptural Cross-Contour Volume Strokes within the chunk
  const numBands = 7;
  for (let b = 0; b < numBands; b++) {
    let u = map(b, 0, numBands - 1, -0.88, 0.88); // position across ribbon width
    let pA = pointOnRibbon(s0, u);
    let pB = pointOnRibbon(s1, u);
    let pC = pointOnRibbon(s2, u);

    if (isZest) {
      // Zest tonal modeling: cool olive/amber at edges, brilliant cadmium yellow at crown
      let col;
      if (u < -0.6) col = PALETTE.zestAmber;
      else if (u < -0.25) col = PALETTE.zestCadmium;
      else if (u < 0.25) col = PALETTE.zestCadmiumLight;
      else if (u < 0.65) col = PALETTE.zestCadmiumDeep;
      else col = PALETTE.zestCoolHalftone;

      brush.set("rosemaling_quill", col, map(s1.projHalfW, 6, 48, 0.45, 0.95));
      brush.spline(
        [
          [pA.x, pA.y, 1.2],
          [pB.x, pB.y, 1.0],
          [pC.x, pC.y, 0.5]
        ],
        0.5
      );
    } else {
      // Pith tonal modeling: cool slate-ivory shadow at edges, chalky warm ivory in center
      let col;
      if (u < -0.55) col = PALETTE.pithCoolShadow;
      else if (u < -0.15) col = PALETTE.pithChalk;
      else if (u < 0.35) col = PALETTE.pithIvory;
      else if (u < 0.7) col = PALETTE.pithWarmMid;
      else col = PALETTE.pithCoolMid;

      brush.set("pith_chalk", col, map(s1.projHalfW, 6, 48, 0.45, 0.92));
      brush.spline(
        [
          [pA.x, pA.y, 1.1],
          [pB.x, pB.y, 1.2],
          [pC.x, pC.y, 0.6]
        ],
        0.5
      );
    }
  }
}

function pointOnRibbon(sample, u) {
  // u in [-1, 1] interpolates between left edge and right edge
  let f = (u + 1) * 0.5;
  return {
    x: lerp(sample.leftX, sample.rightX, f),
    y: lerp(sample.leftY, sample.rightY, f)
  };
}

// ============================================================================
// 6A. TAPERING ROSEMALING LINER-BRUSH STROKES ON THE ZEST
// ============================================================================
function drawLongRosemalingRindStrokes(samples) {
  // "The rind is built from tapering liner-brush strokes that start fat and flick
  // to hairlines, the way rosemaling leaves are laid."
  // We sweep diagonal & curved calligraphic strokes along every zest scroll segment!
  const stride = 7;
  for (let i = 6; i < samples.length - 28; i += stride) {
    let sStart = samples[i];
    if (sStart.face < -0.05) continue; // Only on zest-facing or twisting-into-zest turns

    let span = Math.min(24, samples.length - 1 - i);
    let sMid1 = samples[i + Math.floor(span * 0.33)];
    let sMid2 = samples[i + Math.floor(span * 0.66)];
    let sEnd = samples[i + span];

    if (sMid1.face < -0.15 || sEnd.face < -0.25) continue;

    // Lay a fan of 4 to 6 tapering rosemaling leaf strokes that start fat near the outer
    // rim of the scroll and curve inward to a hairline flick toward the spine/inner rim!
    let curveSign = sStart.nx * sStart.tx + sStart.ny * sStart.ty >= 0 ? 1 : -1;
    let numFan = 5;

    for (let f = 0; f < numFan; f++) {
      let u0 = map(f, 0, numFan - 1, -0.82, 0.68);
      // Stroke sweeps diagonally across the ribbon as it travels down the scroll
      let u1 = constrain(u0 + 0.18 * curveSign, -0.88, 0.88);
      let u2 = constrain(u0 + 0.34 * curveSign, -0.9, 0.9);
      let u3 = constrain(u0 + 0.46 * curveSign, -0.92, 0.92);

      let p0 = pointOnRibbon(sStart, u0);
      let p1 = pointOnRibbon(sMid1, u1);
      let p2 = pointOnRibbon(sMid2, u2);
      let p3 = pointOnRibbon(sEnd, u3);

      // Select cadmium hue based on cross-ribbon position and scroll light angle
      let lightDot = sMid1.nx * -0.65 + sMid1.ny * -0.75; // upper-left warm light
      let col;
      if (u0 < -0.55) {
        col = lightDot > 0 ? PALETTE.zestCadmium : PALETTE.zestAmber;
      } else if (u0 < -0.15) {
        col = lightDot > -0.2 ? PALETTE.zestCadmiumLight : PALETTE.zestCadmium;
      } else if (u0 < 0.3) {
        col = PALETTE.zestLemon;
      } else if (u0 < 0.6) {
        col = PALETTE.zestCadmiumDeep;
      } else {
        col = random([PALETTE.zestCadmiumOrange, PALETTE.zestCoolHalftone]);
      }

      let bName = f % 2 === 0 ? "rosemaling_quill" : "rosemaling_liner";
      let wMult = map(sMid1.projHalfW, 8, 48, 0.42, 0.92);

      brush.set(bName, col, wMult);
      brush.spline(
        [
          [p0.x, p0.y, 1.65],
          [p1.x, p1.y, 1.25],
          [p2.x, p2.y, 0.55],
          [p3.x, p3.y, 0.04]
        ],
        0.55
      );
    }

    // Crisp chalky ivory cut-pith rim strokes along the zest borders
    let rimL0 = sStart,
      rimL1 = sMid1,
      rimL2 = sMid2,
      rimL3 = sEnd;
    brush.set("rosemaling_liner", PALETTE.pithBright, 0.68);
    brush.spline(
      [
        [rimL0.leftX, rimL0.leftY, 1.45],
        [rimL1.leftX, rimL1.leftY, 1.1],
        [rimL2.leftX, rimL2.leftY, 0.55],
        [rimL3.leftX, rimL3.leftY, 0.04]
      ],
      0.5
    );

    brush.set("rosemaling_liner", PALETTE.pithChalk, 0.62);
    brush.spline(
      [
        [rimL0.rightX, rimL0.rightY, 1.4],
        [rimL1.rightX, rimL1.rightY, 1.0],
        [rimL2.rightX, rimL2.rightY, 0.5],
        [rimL3.rightX, rimL3.rightY, 0.04]
      ],
      0.5
    );
  }
}

// ============================================================================
// 6B. OILY PORE DIMPLES PICKED OUT IN PALE CREAM
// ============================================================================
function drawOilyPoreDimples(samples) {
  // "The zest is cadmium yellow with oily pore dimples picked out in pale cream"
  // Real lemon flavedo oil glands are tiny concave dimples: each has a warm amber/ochre
  // shadow crescent on the upper-left and a pale cream highlight crescent on the lower-right.
  for (let i = 8; i < samples.length - 8; i += 2) {
    let s = samples[i];
    if (s.face <= 0.12) continue; // Only visible on zest-facing surfaces

    // Number of pores scales with visible foreshortened width
    let numPores = Math.floor(map(s.projHalfW, 6, 48, 1, 4.2));
    for (let p = 0; p < numPores; p++) {
      let u = random(-0.8, 0.8);
      let pos = pointOnRibbon(s, u);
      let jitterX = random(-2.2, 2.2);
      let jitterY = random(-2.2, 2.2);
      let px = pos.x + jitterX;
      let py = pos.y + jitterY;

      // Foreshorten the pore near the edges of the ribbon or twist points
      let edgeFactor = (1 - Math.abs(u) * 0.65) * s.face;
      let r = random(1.3, 2.7) * constrain(edgeFactor, 0.4, 1.0);

      // 1. Recessed amber/cadmium-deep dimple pit (upper-left crescent)
      let pitCol = u > 0.35 ? PALETTE.zestShadowDeep : PALETTE.zestAmber;
      brush.set("rosemaling_liner", pitCol, 0.32 * r);
      brush.spline(
        [
          [px - r, py + r * 0.3, 0.8],
          [px - r * 0.4, py - r * 0.85, 1.3],
          [px + r * 0.7, py - r * 0.3, 0.15]
        ],
        0.5
      );

      // 2. Pale cream highlight lip on the lower-right rim of the dimple
      let creamCol =
        Math.abs(u + 0.1) < 0.35 ? PALETTE.zestSpecular : PALETTE.zestCream;
      brush.set("specular_liner", creamCol, 0.36 * r);
      brush.spline(
        [
          [px - r * 0.5, py + r * 0.55, 1.35],
          [px + r * 0.35, py + r * 0.85, 1.0],
          [px + r * 0.95, py - r * 0.1, 0.08]
        ],
        0.5
      );
    }
  }
}

// ============================================================================
// 6C. CHALKY IVORY PITH UNDERSIDE & FIBROUS VASCULAR THREADS
// ============================================================================
function drawPithFibrousThreads(samples) {
  // "and the pith underside is chalky ivory with fibrous threads."
  // 1. Chalky ivory rosemaling C-strokes and vascular bundles on pith-facing segments
  for (let i = 6; i < samples.length - 22; i += 5) {
    let s0 = samples[i];
    if (s0.face > 0.08) continue; // Only on pith-facing underside segments

    let span = Math.min(20, samples.length - 1 - i);
    let s1 = samples[i + Math.floor(span * 0.35)];
    let s2 = samples[i + Math.floor(span * 0.7)];
    let s3 = samples[i + span];

    if (s2.face > 0.2) continue;

    // Chalky ivory cross-textured strokes
    for (let k = 0; k < 4; k++) {
      let uStart = map(k, 0, 3, -0.78, 0.78) + random(-0.08, 0.08);
      let uEnd = constrain(uStart + random(-0.28, 0.28), -0.88, 0.88);
      let p0 = pointOnRibbon(s0, uStart);
      let p1 = pointOnRibbon(s1, lerp(uStart, uEnd, 0.35));
      let p2 = pointOnRibbon(s2, lerp(uStart, uEnd, 0.7));
      let p3 = pointOnRibbon(s3, uEnd);

      let col =
        Math.abs(uStart) > 0.52
          ? random([PALETTE.pithCoolShadow, PALETTE.pithCoolMid, PALETTE.pithWarmMid])
          : random([PALETTE.pithChalk, PALETTE.pithIvory, PALETTE.pithBright]);

      brush.set("pith_chalk", col, random(0.45, 0.82));
      brush.spline(
        [
          [p0.x, p0.y, 1.3],
          [p1.x, p1.y, 1.1],
          [p2.x, p2.y, 0.65],
          [p3.x, p3.y, 0.1]
        ],
        0.55
      );
    }

    // Fine branching fibrous vascular threads (albedo veins) in bright chalk-white
    for (let t = 0; t < 5; t++) {
      let uA = random(-0.82, 0.82);
      let uB = constrain(uA + random(-0.35, 0.35), -0.92, 0.92);
      let p0 = pointOnRibbon(s0, uA);
      let p1 = pointOnRibbon(s1, lerp(uA, uB, 0.4) + random(-0.1, 0.1));
      let p2 = pointOnRibbon(s2, lerp(uA, uB, 0.75) + random(-0.1, 0.1));
      let p3 = pointOnRibbon(s3, uB);

      let threadCol = random([PALETTE.pithBright, PALETTE.pithWhite, PALETTE.pithIvory]);
      brush.set("pith_thread", threadCol, random(0.55, 0.95));
      brush.spline(
        [
          [p0.x, p0.y, 0.4],
          [p1.x, p1.y, 1.35],
          [p2.x, p2.y, 0.85],
          [p3.x, p3.y, 0.05]
        ],
        0.65
      );
    }
  }

  // 2. Delicate loose fibrous pith threads curling off the cut edges along the entire peel
  for (let i = 12; i < samples.length - 16; i += 6) {
    let s0 = samples[i];
    let s1 = samples[i + 4];
    let s2 = samples[i + 9];

    // Pick left or right cut edge
    let onLeft = i % 12 === 0;
    let bx0 = onLeft ? s0.leftX : s0.rightX;
    let by0 = onLeft ? s0.leftY : s0.rightY;
    let bx1 = onLeft ? s1.leftX : s1.rightX;
    let by1 = onLeft ? s1.leftY : s1.rightY;
    let bx2 = onLeft ? s2.leftX : s2.rightX;
    let by2 = onLeft ? s2.leftY : s2.rightY;

    let outSign = onLeft ? -1 : 1;
    let flare = random(3.5, 9.5) * outSign;

    brush.set("pith_thread", PALETTE.pithBright, random(0.45, 0.78));
    brush.spline(
      [
        [bx0, by0, 1.1],
        [bx1 + s1.nx * flare * 0.55, by1 + s1.ny * flare * 0.55, 0.85],
        [bx2 + s2.nx * flare, by2 + s2.ny * flare + random(-3, 4), 0.04]
      ],
      0.65
    );
  }
}

// ============================================================================
// 6D. GLOSSY SPECULAR RIDGE ALONG EACH STRIP
// ============================================================================
function drawGlossySpecularRidges(samples) {
  // "The light is warm and even, and each strip carries a glossy specular ridge."
  // Across every zest turn, we trace a gleaming continuous specular ridge offset slightly
  // toward the upper-left warm light source, built from fat-to-hairline liner strokes.
  for (let i = 8; i < samples.length - 20; i += 8) {
    let s0 = samples[i];
    let s1 = samples[i + 6];
    let s2 = samples[i + 12];
    let s3 = samples[i + 18];

    if (s0.face > 0.18 && s1.face > 0.18 && s2.face > 0.1) {
      // Zest Specular Ridge: warm pale cream halo + brilliant ivory-white core
      let uRidge0 = -0.18 + 0.15 * Math.sin(s0.t * Math.PI * 10);
      let uRidge1 = -0.15 + 0.15 * Math.sin(s1.t * Math.PI * 10);
      let uRidge2 = -0.12 + 0.15 * Math.sin(s2.t * Math.PI * 10);
      let uRidge3 = -0.08 + 0.15 * Math.sin(s3.t * Math.PI * 10);

      let p0 = pointOnRibbon(s0, uRidge0);
      let p1 = pointOnRibbon(s1, uRidge1);
      let p2 = pointOnRibbon(s2, uRidge2);
      let p3 = pointOnRibbon(s3, uRidge3);

      // Soft warm cream glow band
      brush.set("rosemaling_quill", PALETTE.zestCream, map(s1.projHalfW, 10, 48, 0.45, 0.88));
      brush.spline(
        [
          [p0.x, p0.y, 1.5],
          [p1.x, p1.y, 1.25],
          [p2.x, p2.y, 0.65],
          [p3.x, p3.y, 0.05]
        ],
        0.55
      );

      // Razor-crisp high-gloss specular core
      brush.set("specular_liner", PALETTE.zestSpecular, map(s1.projHalfW, 10, 48, 0.5, 0.95));
      brush.spline(
        [
          [p0.x, p0.y, 1.6],
          [p1.x, p1.y, 1.2],
          [p2.x, p2.y, 0.5],
          [p3.x, p3.y, 0.03]
        ],
        0.55
      );

      // Secondary parallel wet-oil glint line
      let p0b = pointOnRibbon(s0, uRidge0 + 0.14);
      let p1b = pointOnRibbon(s1, uRidge1 + 0.14);
      let p2b = pointOnRibbon(s2, uRidge2 + 0.14);
      brush.set("specular_liner", PALETTE.zestCream, 0.52);
      brush.spline(
        [
          [p0b.x, p0b.y, 1.2],
          [p1b.x, p1b.y, 0.8],
          [p2b.x, p2b.y, 0.04]
        ],
        0.55
      );
    } else if (s0.face < -0.25 && s1.face < -0.25 && s2.face < -0.15) {
      // On pith underside turns, a softer chalky-white ridge catches the warm light
      let p0 = pointOnRibbon(s0, -0.12);
      let p1 = pointOnRibbon(s1, -0.08);
      let p2 = pointOnRibbon(s2, -0.04);
      let p3 = pointOnRibbon(s3, 0.0);

      brush.set("rosemaling_liner", PALETTE.pithWhite, 0.68);
      brush.spline(
        [
          [p0.x, p0.y, 1.4],
          [p1.x, p1.y, 1.05],
          [p2.x, p2.y, 0.45],
          [p3.x, p3.y, 0.04]
        ],
        0.55
      );
    }
  }
}

// ============================================================================
// 6E. ROSEMALING CALLIGRAPHIC RIND SERIFS & CURLING ZEST SHAVINGS
// ============================================================================
function drawRosemalingRindTendrils(samples) {
  // At the outer shoulders of the major C- and S-scrolls, where a paring knife rocks
  // in rhythmic strokes, small calligraphic rind serifs / leaf-scroll curls flare out,
  // uniting hyperrealistic lemon peel parings with Norwegian rosemaling leaf calligraphy.
  const scrollShoulders = [
    { idx: 112, side: -1, len: 46, curl: -1 },
    { idx: 245, side: 1, len: 52, curl: 1 },
    { idx: 368, side: -1, len: 58, curl: -1 },
    { idx: 495, side: 1, len: 56, curl: 1 },
    { idx: 605, side: -1, len: 48, curl: -1 },
    { idx: 702, side: 1, len: 44, curl: 1 }
  ];

  for (let sh of scrollShoulders) {
    let s0 = samples[sh.idx];
    let s1 = samples[Math.min(samples.length - 1, sh.idx + 12)];
    let edgeX = sh.side < 0 ? s0.leftX : s0.rightX;
    let edgeY = sh.side < 0 ? s0.leftY : s0.rightY;

    let nx = s0.nx * sh.side;
    let ny = s0.ny * sh.side;
    let tx = s0.tx;
    let ty = s0.ty;

    let p1x = edgeX + (nx * 0.45 + tx * 0.85) * sh.len * 0.45;
    let p1y = edgeY + (ny * 0.45 + ty * 0.85) * sh.len * 0.45;
    let p2x = edgeX + (nx * 0.85 + tx * 0.55) * sh.len * 0.85;
    let p2y = edgeY + (ny * 0.85 + ty * 0.55) * sh.len * 0.85;
    let p3x = p2x + (nx * 0.4 - tx * 0.7 * sh.curl) * sh.len * 0.38;
    let p3y = p2y + (ny * 0.4 - ty * 0.7 * sh.curl) * sh.len * 0.38;

    // Chalky pith underside of the small pared curl
    brush.set("rosemaling_quill", PALETTE.pithIvory, 0.75);
    brush.spline(
      [
        [edgeX, edgeY + 3, 1.4],
        [p1x, p1y + 3, 1.1],
        [p2x, p2y + 2, 0.55],
        [p3x, p3y + 1, 0.05]
      ],
      0.65
    );

    // Cadmium yellow zest stroke starting fat and flicking to a hairline
    brush.set("rosemaling_quill", PALETTE.zestCadmium, 0.82);
    brush.spline(
      [
        [edgeX, edgeY, 1.6],
        [p1x, p1y, 1.25],
        [p2x, p2y, 0.6],
        [p3x, p3y, 0.04]
      ],
      0.65
    );

    // Specular ridge along the curl
    brush.set("specular_liner", PALETTE.zestCream, 0.55);
    brush.spline(
      [
        [edgeX, edgeY - 1, 1.3],
        [p1x, p1y - 1, 0.9],
        [p2x, p2y - 1, 0.35],
        [p3x, p3y, 0.03]
      ],
      0.65
    );
  }
}

// Hyperrealistic Halved Red Onion on Offset Translucent Vellum Sheets
// Rendered with p5.js v2 + p5.brush in WEBGL

const SEED = 4219;

