function draw() {
  translate(-width / 2, -height / 2);

  // 1. Cool drafting-table off-white ground
  background("#e5ecef");
  drawDraftingTableGround();
  drawMarginalConstructionAndCrosses();

  // 2. Stack of 7 offset translucent vellum sheets + concentric onion layers
  for (let L = 0; L < SHEETS.length; L++) {
    const sheet = SHEETS[L];

    // Draw the vellum sheet, its milky perimeter haze, border, and sheet registration marks
    drawVellumSheet(sheet, L);

    // If L > 0, draw the ghost outlines of the previous ring peeking through on this sheet
    if (L > 0) {
      drawGhostRingFromPrevious(SHEETS[L - 1], sheet, L);
    }

    // Draw the active concentric onion layer for this sheet
    if (L === 0) {
      drawOuterPaperySkins(sheet);
      drawConcentricRingLayer(sheet, L);
    } else if (L <= 4) {
      drawConcentricRingLayer(sheet, L);
      // Show-through contour where this shifted ring overlaps the previous ring below
      drawOverlapPeekThrough(SHEETS[L - 1], sheet, L);
    } else if (L === 5) {
      drawTwinHeartOuterLayer(sheet);
      drawOverlapPeekThrough(SHEETS[4], sheet, 5);
    } else if (L === 6) {
      drawTwinHeartCentralCore(sheet);
    }
  }

  // 3. Final top-level drafting hairlines, caliper annotations, and crispest central juice gleams
  drawTopDraftingAnnotations();
  drawFinalCentralHighlights(SHEETS[5], SHEETS[6]);

  noLoop();
}

// ============================================================================
// GEOMETRY & BOTANICAL MORPHOLOGY HELPERS
// ============================================================================

function transformPt(localX, localY, cx, cy, rotDeg) {
  const c = cos(rotDeg);
  const s = sin(rotDeg);
  return [
    cx + localX * c - localY * s,
    cy + localX * s + localY * c
  ];
}

// Organic radial contour of the halved red onion for outer rings (Layers 0..4)
function onionRadius(angleDeg, baseR, layerIdx, isInnerBoundary) {
  const a = angleDeg;
  // Slight horizontal ellipticity + natural 3-lobed & 5-lobed bulb undulation
  const ellip = 1.0 + 0.036 * cos(2 * (a - 14));
  const lobes =
    0.028 * cos(3 * (a + 22)) +
    0.016 * sin(2 * (a - 38)) +
    0.009 * cos(5 * (a + 15));

  // Fine organic irregularity
  const n = (noise(
    2.0 + 0.35 * layerIdx + 0.6 * cos(a),
    2.0 + 0.35 * layerIdx + 0.6 * sin(a)
  ) - 0.5) * 0.032;

  // Median septum pinch as rings approach the twin-heart bifurcation (Layers 3 & 4)
  let pinchAmt = 0;
  if (layerIdx === 3) {
    pinchAmt = isInnerBoundary ? 0.055 : 0.018;
  } else if (layerIdx === 4) {
    pinchAmt = isInnerBoundary ? 0.185 : 0.075;
  }
  const septumCos = max(0, cos(2 * (a - 78)));
  const pinch = -pinchAmt * pow(septumCos, 2.4);

  return baseR * (ellip + lobes + n + pinch);
}

function getRingPoint(sheet, angleDeg, t, layerIdx) {
  const rIn = onionRadius(angleDeg, sheet.rIn, layerIdx, true);
  const rOut = onionRadius(angleDeg, sheet.rOut, layerIdx, false);
  const r = lerp(rIn, rOut, t);
  const lx = r * cos(angleDeg);
  const ly = r * sin(angleDeg);
  return transformPt(lx, ly, 600 + sheet.ox, 600 + sheet.oy, sheet.rot);
}

// Twin-heart kidney contour for Layers 5 & 6
// heartId = 0 (Left-Upper Primary Heart A) or 1 (Right-Lower Secondary Heart B)
function getHeartPoint(sheet, heartId, angleDeg, rBase) {
  const hcx = heartId === 0 ? -43 : 44;
  const hcy = heartId === 0 ? -9 : 9;
  const septumAngle = heartId === 0 ? -12 : 168;

  // Flatten the side facing the median septum so the two hearts press together
  const faceCos = max(0, cos(angleDeg - septumAngle));
  const flat = 1.0 - 0.29 * pow(faceCos, 1.75);

  const organic =
    1.0 +
    0.055 * cos(2 * (angleDeg - 78)) +
    (heartId === 0 ? 0.028 : -0.028) * sin(3 * angleDeg);

  const r = rBase * organic * flat;
  const lx = hcx + r * cos(angleDeg);
  const ly = hcy + r * sin(angleDeg);
  return transformPt(lx, ly, 600 + sheet.ox, 600 + sheet.oy, sheet.rot);
}

function drawClosedShape(pts, curvature = 0.25) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// ============================================================================
// 1. DRAFTING TABLE GROUND & MARGINAL CONSTRUCTION LINES
// ============================================================================

function drawDraftingTableGround() {
  brush.noStroke();
  // Subtle cool architectural surface tone variations at board edges
  brush.wash("#dde6eb", 55);
  drawClosedShape([[0, 0], [1200, 0], [1200, 140], [0, 140]], 0);
  drawClosedShape([[0, 1060], [1200, 1060], [1200, 1200], [0, 1200]], 0);
  brush.noWash();

  // Faint drafting-paper tooth lines
  brush.set("2H", "#d2dce3", 0.32);
  for (let i = 0; i < 48; i++) {
    const y = 30 + i * 24 + random(-4, 4);
    brush.line(25, y, 1175, y + random(-2, 2));
  }
}

function drawMarginalConstructionAndCrosses() {
  // Primary orthogonal & diagonal construction axes
  brush.set("2H", "#9aa8b5", 0.35);
  brush.line(32, 600, 1168, 600);
  brush.line(600, 32, 600, 1168);

  brush.set("2H", "#adb9c4", 0.28);
  brush.line(85, 85, 1115, 1115);
  brush.line(1115, 85, 85, 1115);

  // Tangent projection lines marking outer onion ring bounds at the margins
  const projRadii = [392, 340, 280, 218, 159, 106];
  for (let i = 0; i < projRadii.length; i++) {
    const r = projRadii[i];
    brush.set("2H", i % 2 === 0 ? "#a4b1bd" : "#b3bfc9", 0.26);
    // Top & bottom margin projection ticks
    brush.line(600 - r, 48, 600 - r, 155);
    brush.line(600 + r, 48, 600 + r, 155);
    brush.line(600 - r, 1045, 600 - r, 1152);
    brush.line(600 + r, 1045, 600 + r, 1152);
    // Left & right margin projection ticks
    brush.line(48, 600 - r, 155, 600 - r);
    brush.line(48, 600 + r, 155, 600 + r);
    brush.line(1045, 600 - r, 1152, 600 - r);
    brush.line(1045, 600 + r, 1152, 600 + r);
  }

  // Faint compass construction arcs near the outer corners
  brush.set("2H", "#9caab7", 0.3);
  for (let r of [420, 392, 346, 286]) {
    brush.arc(600, 600, r, -68, -22);
    brush.arc(600, 600, r, 22, 68);
    brush.arc(600, 600, r, 112, 158);
    brush.arc(600, 600, r, 202, 248);
  }

  // Faint magenta/violet colour-separation test bars in top-left & bottom-right margins
  const swatchColors = ["#3b0047", "#73008a", "#b80058", "#f50076", "#f788c2", "#cbe096"];
  for (let i = 0; i < swatchColors.length; i++) {
    brush.noStroke();
    brush.wash(swatchColors[i], 130);
    const bx = 148 + i * 22;
    const by = 52;
    drawClosedShape([[bx, by], [bx + 18, by], [bx + 18, by + 10], [bx, by + 10]], 0);
    brush.noWash();
    brush.set("2H", "#8997a4", 0.25);
    brush.rect(bx, by, 18, 10, "corner");
  }

  // Graduated caliper scale along left and bottom margins
  brush.set("2H", "#83929f", 0.35);
  brush.line(58, 160, 58, 1040);
  for (let y = 160; y <= 1040; y += 10) {
    const len = (y - 600) % 50 === 0 ? 14 : ((y - 600) % 20 === 0 ? 9 : 5);
    brush.line(58, y, 58 + len, y);
  }
  brush.line(160, 1142, 1040, 1142);
  for (let x = 160; x <= 1040; x += 10) {
    const len = (x - 600) % 50 === 0 ? 14 : ((x - 600) % 20 === 0 ? 9 : 5);
    brush.line(x, 1142, x, 1142 - len);
  }

  // 8 Master Registration Crosses at corners and cardinal margin centers
  const masterCrosses = [
    [76, 76], [1124, 76], [1124, 1124], [76, 1124],
    [600, 56], [1144, 600], [600, 1144], [56, 600]
  ];
  for (let [cx, cy] of masterCrosses) {
    drawRegistrationMark(cx, cy, 22, 0, "#6d7b88", "#b33676", true);
  }
}

function drawRegistrationMark(cx, cy, size, rotDeg, colMain, colAccent, withCircles) {
  const p1 = transformPt(-size, 0, cx, cy, rotDeg);
  const p2 = transformPt(size, 0, cx, cy, rotDeg);
  const p3 = transformPt(0, -size, cx, cy, rotDeg);
  const p4 = transformPt(0, size, cx, cy, rotDeg);

  brush.set("2H", colMain, 0.42);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
  brush.line(p3[0], p3[1], p4[0], p4[1]);

  // Fine tick marks on cross arms
  for (let d of [-size * 0.65, size * 0.65]) {
    const t1 = transformPt(d, -3.5, cx, cy, rotDeg);
    const t2 = transformPt(d, 3.5, cx, cy, rotDeg);
    const t3 = transformPt(-3.5, d, cx, cy, rotDeg);
    const t4 = transformPt(3.5, d, cx, cy, rotDeg);
    brush.line(t1[0], t1[1], t2[0], t2[1]);
    brush.line(t3[0], t3[1], t4[0], t4[1]);
  }

  if (withCircles) {
    brush.set("2H", colMain, 0.35);
    brush.circle(cx, cy, size * 0.42, 0.08);
    brush.set("fine_cpencil", colAccent, 0.32);
    brush.circle(cx, cy, size * 0.68, 0.1);
  }
}

// ============================================================================
// 2. TRANSLUCENT VELLUM SHEETS (BUILDING UP MILKY HAZE AT EDGES)
// ============================================================================

function drawVellumSheet(sheet, layerIdx) {
  const hw = sheet.sw / 2;
  const hh = sheet.sh / 2;
  const cx = sheet.sx;
  const cy = sheet.sy;
  const rot = sheet.srot;

  const cTL = transformPt(-hw, -hh, cx, cy, rot);
  const cTR = transformPt(hw, -hh, cx, cy, rot);
  const cBR = transformPt(hw, hh, cx, cy, rot);
  const cBL = transformPt(-hw, hh, cx, cy, rot);

  // Subtle drop shadow under bottom and right edges of the vellum sheet
  brush.set("2H", "#c4d0d9", 0.75);
  brush.line(cBL[0] + 2.5, cBL[1] + 3.5, cBR[0] + 2.5, cBR[1] + 3.5);
  brush.line(cTR[0] + 2.5, cTR[1] + 3.5, cBR[0] + 2.5, cBR[1] + 3.5);

  // Inner boundary of the perimeter vellum haze band (leaves central cut sharp and clear)
  const bandW = 215 - layerIdx * 8;
  const iTL = transformPt(-hw + bandW, -hh + bandW, cx, cy, rot);
  const iTR = transformPt(hw - bandW, -hh + bandW, cx, cy, rot);
  const iBR = transformPt(hw - bandW, hh - bandW, cx, cy, rot);
  const iBL = transformPt(-hw + bandW, hh - bandW, cx, cy, rot);

  // 4 overlapping perimeter trapezoids create the milky vellum buildup at the sheet edges
  brush.noStroke();
  brush.fill("#f6f9fb", sheet.edgeHazeAlpha);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.32, 0.12);
  brush.wash("#fafcfe", sheet.edgeHazeAlpha + 12);

  // Top, Bottom, Left, Right vellum margin bands
  drawClosedShape([cTL, cTR, iTR, iTL], 0.05);
  drawClosedShape([iBL, iBR, cBR, cBL], 0.05);
  drawClosedShape([cTL, iTL, iBL, cBL], 0.05);
  drawClosedShape([iTR, cTR, cBR, iBR], 0.05);

  // Secondary narrower edge band right near the sheet perimeter for extra milky density at edges
  const rimW = 95;
  const rTL = transformPt(-hw + rimW, -hh + rimW, cx, cy, rot);
  const rTR = transformPt(hw - rimW, -hh + rimW, cx, cy, rot);
  const rBR = transformPt(hw - rimW, hh - rimW, cx, cy, rot);
  const rBL = transformPt(-hw + rimW, hh - rimW, cx, cy, rot);

  brush.noFill();
  brush.wash("#fcfdfe", 36);
  drawClosedShape([cTL, cTR, rTR, rTL], 0);
  drawClosedShape([rBL, rBR, cBR, cBL], 0);
  drawClosedShape([cTL, rTL, rBL, cBL], 0);
  drawClosedShape([rTR, cTR, cBR, rBR], 0);

  // Very delicate vellum veil over the interior only on lower sheets so lower rings peek through softly
  if (sheet.centerVeilAlpha > 0) {
    brush.wash("#f5f9fb", sheet.centerVeilAlpha);
    drawClosedShape([iTL, iTR, iBR, iBL], 0);
  }
  brush.noWash();

  // Powdery vellum spray along sheet borders
  brush.set("vellum_haze", "#ffffff", 1.1);
  brush.line(cTL[0], cTL[1], cTR[0], cTR[1]);
  brush.line(cTR[0], cTR[1], cBR[0], cBR[1]);
  brush.line(cBR[0], cBR[1], cBL[0], cBL[1]);
  brush.line(cBL[0], cBL[1], cTL[0], cTL[1]);

  // Crisp bright white cut-vellum border highlight + fine grey edge line
  brush.set("wet_highlight", "#ffffff", 0.65);
  brush.line(cTL[0], cTL[1], cTR[0], cTR[1]);
  brush.line(cTL[0], cTL[1], cBL[0], cBL[1]);
  brush.set("2H", "#b6c3ce", 0.35);
  brush.line(cTL[0], cTL[1], cTR[0], cTR[1]);
  brush.line(cTR[0], cTR[1], cBR[0], cBR[1]);
  brush.line(cBR[0], cBR[1], cBL[0], cBL[1]);
  brush.line(cBL[0], cBL[1], cTL[0], cTL[1]);

  // Sheet-specific registration crosses at all 4 corners of this sheet (shifted & rotated with the sheet)
  const inset = 30;
  const regCorners = [
    transformPt(-hw + inset, -hh + inset, cx, cy, rot),
    transformPt(hw - inset, -hh + inset, cx, cy, rot),
    transformPt(hw - inset, hh - inset, cx, cy, rot),
    transformPt(-hw + inset, hh - inset, cx, cy, rot)
  ];
  const regCol = layerIdx % 2 === 0 ? "#8a98a6" : "#9685a3";
  const accentCol = layerIdx % 2 === 0 ? "#cf6ba0" : "#9c62b5";
  for (let rc of regCorners) {
    drawRegistrationMark(rc[0], rc[1], 13, rot, regCol, accentCol, true);
  }

  // Faint construction crosshairs on this vellum sheet showing its shifted onion center
  const ocx = 600 + sheet.ox;
  const ocy = 600 + sheet.oy;
  const axL = transformPt(-hw + 18, 0, ocx, ocy, sheet.rot);
  const axR = transformPt(hw - 18, 0, ocx, ocy, sheet.rot);
  const axT = transformPt(0, -hh + 18, ocx, ocy, sheet.rot);
  const axB = transformPt(0, hh - 18, ocx, ocy, sheet.rot);
  brush.set("2H", "#b9c5cf", 0.24);
  brush.line(axL[0], axL[1], transformPt(-sheet.rOut - 15, 0, ocx, ocy, sheet.rot)[0], transformPt(-sheet.rOut - 15, 0, ocx, ocy, sheet.rot)[1]);
  brush.line(transformPt(sheet.rOut + 15, 0, ocx, ocy, sheet.rot)[0], transformPt(sheet.rOut + 15, 0, ocx, ocy, sheet.rot)[1], axR[0], axR[1]);
  brush.line(axT[0], axT[1], transformPt(0, -sheet.rOut - 15, ocx, ocy, sheet.rot)[0], transformPt(0, -sheet.rOut - 15, ocx, ocy, sheet.rot)[1]);
  brush.line(transformPt(0, sheet.rOut + 15, ocx, ocy, sheet.rot)[0], transformPt(0, sheet.rOut + 15, ocx, ocy, sheet.rot)[1], axB[0], axB[1]);
}

// ============================================================================
// 3. GHOST OUTLINES OF PREVIOUS RING PEEKING THROUGH
// ============================================================================

function drawGhostRingFromPrevious(prevSheet, currSheet, currIdx) {
  const prevIdx = currIdx - 1;

  // Ghost trace A: Previous ring's geometry drawn at current sheet's shifted registration
  // Ghost trace B: Previous ring's geometry at a half-way registration drift
  const ghostConfigs = [
    {
      ox: currSheet.ox,
      oy: currSheet.oy,
      rot: currSheet.rot,
      colOuter: "#df84b5",
      colInner: "#aa8ec2",
      colCell: "#eab3d1",
      w: 0.42
    },
    {
      ox: lerp(prevSheet.ox, currSheet.ox, 0.45),
      oy: lerp(prevSheet.oy, currSheet.oy, 0.45),
      rot: lerp(prevSheet.rot, currSheet.rot, 0.45),
      colOuter: "#c496b8",
      colInner: "#9ba8b8",
      colCell: "#d2b8cf",
      w: 0.3
    }
  ];

  for (let gc of ghostConfigs) {
    const tempSheet = {
      ox: gc.ox,
      oy: gc.oy,
      rot: gc.rot,
      rOut: prevSheet.rOut,
      rIn: prevSheet.rIn
    };

    if (prevIdx <= 4) {
      const outerPts = [];
      const innerPts = [];
      for (let a = 0; a <= 360; a += 5) {
        outerPts.push(getRingPoint(tempSheet, a, 1.0, prevIdx));
        innerPts.push(getRingPoint(tempSheet, a, 0.0, prevIdx));
      }

      brush.set("fine_cpencil", gc.colOuter, gc.w);
      brush.spline(outerPts, 0.35);
      brush.set("2H", gc.colInner, gc.w * 0.85);
      brush.spline(innerPts, 0.35);

      // Faint radial ghost cell striations
      brush.set("cell_liner", gc.colCell, 0.28);
      for (let a = 0; a < 360; a += 6) {
        const p1 = getRingPoint(tempSheet, a, 0.15, prevIdx);
        const p2 = getRingPoint(tempSheet, a, 0.95, prevIdx);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    } else if (prevIdx === 5) {
      // Ghost of twin hearts on Sheet 6
      for (let hId = 0; hId < 2; hId++) {
        const rO = hId === 0 ? 57 : 51;
        const rI = hId === 0 ? 33 : 29;
        const ptsO = [];
        const ptsI = [];
        for (let a = 0; a <= 360; a += 8) {
          ptsO.push(getHeartPoint(tempSheet, hId, a, rO));
          ptsI.push(getHeartPoint(tempSheet, hId, a, rI));
        }
        brush.set("fine_cpencil", gc.colOuter, gc.w);
        brush.spline(ptsO, 0.35);
        brush.set("2H", gc.colInner, gc.w * 0.85);
        brush.spline(ptsI, 0.35);
      }
    }
  }
}

// Re-asserts the veiled ghost contour of the lower ring where the upper shifted ring overlaps it
function drawOverlapPeekThrough(prevSheet, currSheet, currIdx) {
  const prevIdx = currIdx - 1;
  if (prevIdx > 4) return;

  // Trace the inner rim of prevSheet in delicate misty rose-violet so it peeks through currSheet's flesh
  const segPts = [];
  for (let a = 0; a <= 360; a += 4) {
    segPts.push(getRingPoint(prevSheet, a, 0.0, prevIdx));
  }
  brush.set("fine_cpencil", "#c774a8", 0.45);
  brush.spline(segPts, 0.35);

  const outerGhost = [];
  for (let a = 0; a <= 360; a += 4) {
    outerGhost.push(getRingPoint(prevSheet, a, 0.92, prevIdx));
  }
  brush.set("cell_liner", "#d98cb8", 0.32);
  brush.spline(outerGhost, 0.35);
}

// ============================================================================
// 4. OUTER PAPERY TUNICS & FLAKING CRIMSON-VIOLET SKINS (SHEET 0)
// ============================================================================

function drawOuterPaperySkins(sheet) {
  // 11 curling, brittle dry red-onion skin shards flaring around the perimeter
  const shards = [
    { aStart: -15, aSpan: 34, rPeak: 446, colWash: "#7a003c", colVein: "#3b0028", colHi: "#e84a90" },
    { aStart: 22, aSpan: 28, rPeak: 432, colWash: "#9e0048", colVein: "#4f0030", colHi: "#ff2e88" },
    { aStart: 56, aSpan: 38, rPeak: 452, colWash: "#590042", colVein: "#290024", colHi: "#d43b85" },
    { aStart: 102, aSpan: 30, rPeak: 436, colWash: "#a8064e", colVein: "#4a002b", colHi: "#ff4d9b" },
    { aStart: 138, aSpan: 36, rPeak: 448, colWash: "#6b0048", colVein: "#330026", colHi: "#e03888" },
    { aStart: 178, aSpan: 32, rPeak: 438, colWash: "#8f0044", colVein: "#3d0022", colHi: "#f25298" },
    { aStart: 215, aSpan: 35, rPeak: 450, colWash: "#52003d", colVein: "#26001f", colHi: "#c9347c" },
    { aStart: 256, aSpan: 28, rPeak: 430, colWash: "#b00055", colVein: "#4d0029", colHi: "#ff4797" },
    { aStart: 290, aSpan: 36, rPeak: 445, colWash: "#730046", colVein: "#360025", colHi: "#e3408b" },
    { aStart: 328, aSpan: 24, rPeak: 428, colWash: "#99004c", colVein: "#450026", colHi: "#f54996" }
  ];

  for (let sh of shards) {
    const pts = [];
    const steps = 10;
    // Inner base along Ring 0 outer boundary
    for (let i = 0; i <= steps; i++) {
      const a = sh.aStart + (i / steps) * sh.aSpan;
      pts.push(getRingPoint(sheet, a, 0.96, 0));
    }
    // Outer ragged papery contour
    for (let i = steps; i >= 0; i--) {
      const u = i / steps;
      const a = sh.aStart + u * sh.aSpan;
      const profile = sin(u * 180);
      const jagged = (noise(a * 0.15, sh.rPeak * 0.1) - 0.5) * 18;
      const r = onionRadius(a, sheet.rOut, 0, false) + profile * (sh.rPeak - sheet.rOut) + jagged;
      const lx = r * cos(a);
      const ly = r * sin(a);
      pts.push(transformPt(lx, ly, 600 + sheet.ox, 600 + sheet.oy, sheet.rot));
    }

    // Cast shadow of curling dry skin onto vellum sheet
    const shadowPts = pts.map(p => [p[0] + 3.5, p[1] + 4.5]);
    brush.noStroke();
    brush.wash("#b8bec7", 65);
    drawClosedShape(shadowPts, 0.2);

    // Translucent carmine-violet skin wash
    brush.fill(sh.colWash, 125);
    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.45, 0.35);
    brush.wash(sh.colWash, 95);
    drawClosedShape(pts, 0.22);
    brush.noFill();
    brush.noWash();

    // Fine longitudinal onion-skin venation & papery crack lines
    for (let i = 1; i < steps; i++) {
      const u = i / steps;
      const a = sh.aStart + u * sh.aSpan;
      const profile = sin(u * 180);
      const rBase = onionRadius(a, sheet.rOut, 0, false);
      const rTip = rBase + profile * (sh.rPeak - sheet.rOut);
      const p1 = transformPt(rBase * cos(a), rBase * sin(a), 600 + sheet.ox, 600 + sheet.oy, sheet.rot);
      const pMid = transformPt(((rBase + rTip) * 0.5) * cos(a + 1.2), ((rBase + rTip) * 0.5) * sin(a + 1.2), 600 + sheet.ox, 600 + sheet.oy, sheet.rot);
      const p2 = transformPt(rTip * cos(a + 2.0), rTip * sin(a + 2.0), 600 + sheet.ox, 600 + sheet.oy, sheet.rot);

      brush.set("cell_liner", sh.colVein, 0.45);
      brush.spline([p1, pMid, p2], 0.3);
      if (i % 2 === 0) {
        brush.set("fine_cpencil", sh.colHi, 0.38);
        brush.line(p1[0], p1[1], pMid[0], pMid[1]);
      }
    }

    // Crisp dark plum outer shard edge
    brush.set("fine_cpencil", sh.colVein, 0.55);
    drawClosedShape(pts, 0.2);
  }
}

// ============================================================================
// 5. HYPERREALISTIC CONCENTRIC FLESHY RINGS (LAYERS 0..4)
// ============================================================================

function drawConcentricRingLayer(sheet, layerIdx) {
  const numSectors = 24;
  const degPerSector = 360 / numSectors;

  // --- STEP A: Luminous Wet White Flesh Wash + Saturated Magenta Outer Bleed ---
  for (let s = 0; s < numSectors; s++) {
    const a0 = s * degPerSector;
    const a1 = (s + 1) * degPerSector;
    const aMid = (a0 + a1) * 0.5;

    // 1. Full ring wet white flesh cushion (brighter than vellum & drafting table)
    const fleshPts = [];
    for (let a = a0; a <= a1; a += 3) fleshPts.push(getRingPoint(sheet, a, 0.94, layerIdx));
    for (let a = a1; a >= a0; a -= 3) fleshPts.push(getRingPoint(sheet, a, 0.02, layerIdx));

    brush.noStroke();
    brush.wash("#ffffff", 185);
    drawClosedShape(fleshPts, 0.15);

    // Subtle chartreuse-cream blush on inner layers (Layers 3 & 4)
    if (layerIdx >= 3) {
      const innerTintPts = [];
      for (let a = a0; a <= a1; a += 5) innerTintPts.push(getRingPoint(sheet, a, 0.42, layerIdx));
      for (let a = a1; a >= a0; a -= 5) innerTintPts.push(getRingPoint(sheet, a, 0.04, layerIdx));
      brush.wash("#eff6df", layerIdx === 4 ? 85 : 50);
      drawClosedShape(innerTintPts, 0.15);
    }

    // 2. Outer magenta-violet pigment bleed band (variable penetration into white flesh)
    const bleedInward = 1.0 - sheet.skinDepth - (noise(layerIdx * 3 + cos(aMid), sin(aMid)) - 0.5) * 0.18;
    const magPts = [];
    for (let a = a0; a <= a1; a += 3) magPts.push(getRingPoint(sheet, a, 1.0, layerIdx));
    for (let a = a1; a >= a0; a -= 3) magPts.push(getRingPoint(sheet, a, bleedInward, layerIdx));

    const isShadedSide = sin(aMid - 45) > 0;
    const magCol = isShadedSide ? "#c90062" : "#eb147a";
    brush.fill(magCol, 95);
    brush.fillBleed(0.16, "in");
    brush.fillTexture(0.35, 0.2);
    brush.wash("#f558a6", 75);
    drawClosedShape(magPts, 0.15);
    brush.noFill();
    brush.noWash();
  }

  // --- STEP B: Coloured-Pencil Radial Modeling (Wet White -> Orchid Rose -> Magenta -> Royal Violet) ---
  const angleStep = map(sheet.rOut, 159, 392, 1.1, 0.65);
  for (let a = 0; a < 360; a += angleStep) {
    const nVal = noise(layerIdx * 7.1 + cos(a) * 1.8, sin(a) * 1.8);
    const nFine = noise(layerIdx * 13.3 + a * 0.12);

    // 1. Burnished wet white flesh strokes (inner 75% of ring)
    const pIn = getRingPoint(sheet, a, 0.04, layerIdx);
    const pMidWhite = getRingPoint(sheet, a + 0.25, 0.72 + (nFine - 0.5) * 0.12, layerIdx);
    brush.set("cpencil", "#ffffff", 0.85);
    brush.line(pIn[0], pIn[1], pMidWhite[0], pMidWhite[1]);

    // Cool watery parenchyma shadow fibrils between white cells
    if (floor(a / angleStep) % 3 === 0) {
      const pCell1 = getRingPoint(sheet, a, 0.08 + nFine * 0.15, layerIdx);
      const pCell2 = getRingPoint(sheet, a, 0.48 + nVal * 0.18, layerIdx);
      const waterCol = layerIdx >= 3 && nFine > 0.55 ? "#d2e0be" : "#c6d6e4";
      brush.set("cell_liner", waterCol, 0.42);
      brush.line(pCell1[0], pCell1[1], pCell2[0], pCell2[1]);
    }

    // 2. Sub-epidermal rose & lavender-pink gradient strokes bleeding inward
    const reachT = constrain(0.38 + (1.0 - sheet.skinDepth) * 0.45 + (nVal - 0.5) * 0.28, 0.28, 0.78);
    const pBleedStart = getRingPoint(sheet, a, 0.92, layerIdx);
    const pBleedEnd = getRingPoint(sheet, a + (nFine - 0.5) * 0.6, reachT, layerIdx);
    const midCol = nFine > 0.5 ? "#f56eb4" : (nFine > 0.25 ? "#e078c2" : "#faa8d8");
    brush.set("fine_cpencil", midCol, 0.55);
    brush.line(pBleedStart[0], pBleedStart[1], pBleedEnd[0], pBleedEnd[1]);

    // 3. Vivid saturated electric magenta & crimson skin strokes (outer 30% of ring)
    const pMagStart = getRingPoint(sheet, a, 0.99, layerIdx);
    const pMagEnd = getRingPoint(sheet, a, 0.66 + (nVal - 0.5) * 0.16, layerIdx);
    const vividCol = nVal > 0.52 ? "#d90066" : (nFine > 0.5 ? "#ff1280" : "#b30056");
    brush.set("fine_cpencil", vividCol, 0.68);
    brush.line(pMagStart[0], pMagStart[1], pMagEnd[0], pMagEnd[1]);

    // 4. Deep royal violet & plum epidermal rim strokes (outermost 14% of ring)
    if (floor(a / angleStep) % 2 === 0) {
      const pViolEnd = getRingPoint(sheet, a, 0.84 + (nFine - 0.5) * 0.08, layerIdx);
      const violCol = nFine > 0.45 ? "#57006b" : "#380047";
      brush.set("fine_cpencil", violCol, 0.62);
      brush.line(pMagStart[0], pMagStart[1], pViolEnd[0], pViolEnd[1]);
    }
  }

  // --- STEP C: Glistening Cellular Brickwork & Vascular Bundles ---
  // Concentric cellular tracks
  const tracks = [0.16, 0.29, 0.43, 0.58, 0.73, 0.85];
  for (let ti = 0; ti < tracks.length; ti++) {
    const t = tracks[ti];
    const cellArcSpan = map(sheet.rOut, 159, 392, 6.5, 3.8);
    for (let a = (ti * 2.3) % 360; a < 360; a += cellArcSpan * 1.35) {
      const tJitter = t + (noise(a * 0.2, ti * 3.1 + layerIdx) - 0.5) * 0.06;
      const pA = getRingPoint(sheet, a, tJitter, layerIdx);
      const pM = getRingPoint(sheet, a + cellArcSpan * 0.5, tJitter + 0.032, layerIdx);
      const pB = getRingPoint(sheet, a + cellArcSpan, tJitter, layerIdx);

      // Cell membrane arc
      const cellCol = t > 0.65 ? "#d94698" : (t > 0.45 ? "#dba0c8" : "#bfd1e0");
      brush.set("cell_liner", cellCol, 0.35);
      brush.spline([pA, pM, pB], 0.4);

      // Glistening convex turgid cell highlight right inside the cell arc
      if (noise(a * 0.35, ti + layerIdx * 5) > 0.36) {
        const pH1 = getRingPoint(sheet, a + cellArcSpan * 0.2, tJitter - 0.015, layerIdx);
        const pH2 = getRingPoint(sheet, a + cellArcSpan * 0.8, tJitter - 0.015, layerIdx);
        brush.set("wet_highlight", "#ffffff", 0.48);
        brush.line(pH1[0], pH1[1], pH2[0], pH2[1]);
      }
    }
  }

  // Mid-ring Vascular Bundle Dots (t ≈ 0.44)
  const vascStep = map(sheet.rOut, 159, 392, 11, 6.5);
  for (let a = 3; a < 360; a += vascStep) {
    const tv = 0.43 + (noise(a * 0.1, layerIdx * 4) - 0.5) * 0.06;
    const vp = getRingPoint(sheet, a, tv, layerIdx);
    // Tiny celadon-olive / rose-violet vascular core + white wet halo
    brush.set("fine_cpencil", "#98b382", 0.65);
    brush.circle(vp[0], vp[1], 2.2, 0.15);
    brush.set("cell_liner", "#8c4b7e", 0.4);
    brush.circle(vp[0] + 0.6, vp[1] + 0.6, 1.3, 0.1);
    brush.set("wet_highlight", "#ffffff", 0.45);
    brush.arc(vp[0], vp[1], 3.2, -150, 20);
  }

  // --- STEP D: Crisp Epidermal Boundaries (Outer Violet-Magenta Skin & Inner Membrane) ---
  const outerContour = [];
  const outerSubSkin = [];
  const innerContour = [];
  for (let a = 0; a <= 360; a += 3) {
    outerContour.push(getRingPoint(sheet, a, 1.0, layerIdx));
    outerSubSkin.push(getRingPoint(sheet, a, 0.94, layerIdx));
    innerContour.push(getRingPoint(sheet, a, 0.0, layerIdx));
  }

  // Vivid magenta sub-skin rim
  brush.set("cpencil", "#d90066", 0.85);
  brush.spline(outerSubSkin, 0.35);

  // Deep royal violet & dark plum outer epidermis
  brush.set("fine_cpencil", "#4a0059", 0.95);
  brush.spline(outerContour, 0.35);
  brush.set("cell_liner", "#24002e", 0.65);
  brush.spline(outerContour, 0.35);

  // Inner adaxial membrane (delicate violet-rose & cool grey crevice)
  brush.set("fine_cpencil", "#9e5088", 0.58);
  brush.spline(innerContour, 0.35);
  brush.set("cell_liner", "#6d597a", 0.42);
  brush.spline(innerContour, 0.35);

  // --- STEP E: Moist Specular Highlights, Meniscus Gleams & Juice Droplets ---
  drawRingMoistHighlights(sheet, layerIdx);
}

function drawRingMoistHighlights(sheet, layerIdx) {
  // 1. Broken liquid meniscus gleams along inner rim (t ≈ 0.06) and outer bevel (t ≈ 0.89)
  for (let a = 0; a < 360; a += 16) {
    const lightBias = cos(a - 225); // Upper-left studio lamp bias
    if (noise(a * 0.08, layerIdx * 9.2) + lightBias * 0.28 > 0.32) {
      const span = random(6, 13);
      const rimPts = [];
      const tRim = random() > 0.38 ? 0.065 : 0.885;
      for (let da = 0; da <= span; da += 2.5) {
        rimPts.push(getRingPoint(sheet, a + da, tRim, layerIdx));
      }
      brush.set("wet_highlight", "#ffffff", random(0.65, 1.05));
      brush.spline(rimPts, 0.35);
    }
  }

  // 2. Beaded translucent juice droplets sitting on the cut flesh
  const numDrops = floor(map(sheet.rOut, 159, 392, 9, 18));
  for (let i = 0; i < numDrops; i++) {
    const a = (i * (360 / numDrops) + random(-8, 8) + 360) % 360;
    const t = random(0.14, 0.82);
    const dp = getRingPoint(sheet, a, t, layerIdx);
    const rDrop = random(2.2, 4.8);

    // Subtle dark violet/cool-grey underside shadow crescent
    brush.set("cell_liner", t > 0.6 ? "#6e144f" : "#8fa3b5", 0.48);
    brush.arc(dp[0] + 0.8, dp[1] + 1.0, rDrop, 15, 165);

    // Crisp pure white specular bead on upper-left of droplet
    brush.set("wet_highlight", "#ffffff", 0.85);
    brush.arc(dp[0] - 0.5, dp[1] - 0.6, rDrop * 0.85, 195, 345);
    brush.line(dp[0] - rDrop * 0.35, dp[1] - rDrop * 0.35, dp[0] + 0.2, dp[1] - rDrop * 0.45);
  }
}

