// 6. BIFURCATED TWIN HEARTS & SHARP JUICY CENTRAL CUT (LAYERS 5 & 6)
// ============================================================================

function drawTwinHeartOuterLayer(sheet) {
  // Layer 5: Two asymmetrical kidney-shaped heart rings pressed across a deep violet-magenta septum
  const hearts = [
    { id: 0, rOut: 57, rIn: 32 },
    { id: 1, rOut: 51, rIn: 28 }
  ];

  // Draw the folded median septum membrane between Heart A and Heart B first
  const sepPts = [];
  for (let y = -66; y <= 66; y += 12) {
    const lx = 1.5 * sin(y * 3.5);
    const ly = y;
    sepPts.push(transformPt(lx, ly, 600 + sheet.ox, 600 + sheet.oy, sheet.rot));
  }
  brush.set("cpencil", "#b8005b", 0.9);
  brush.spline(sepPts, 0.35);
  brush.set("fine_cpencil", "#3b0047", 0.75);
  brush.spline(sepPts, 0.35);

  for (let h of hearts) {
    drawSingleHeartRing(sheet, h.id, h.rOut, h.rIn, false);
  }
}

function drawTwinHeartCentralCore(sheet) {
  // Layer 6: Topmost sharp, juicy central cut inside both twin hearts
  // Outer inner-ring + innermost chartreuse-ivory vegetative shoot bud for each heart
  const innerRings = [
    { id: 0, rOut: 29.5, rIn: 14.0 },
    { id: 1, rOut: 25.5, rIn: 12.0 }
  ];
  for (let ir of innerRings) {
    drawSingleHeartRing(sheet, ir.id, ir.rOut, ir.rIn, true);
  }

  // Innermost coiled baby shoot cores (Heart A & Heart B)
  const buds = [
    { id: 0, rOut: 12.2, rIn: 2.2 },
    { id: 1, rOut: 10.2, rIn: 2.0 }
  ];
  for (let b of buds) {
    const ptsOut = [];
    for (let a = 0; a <= 360; a += 12) {
      ptsOut.push(getHeartPoint(sheet, b.id, a, b.rOut));
    }

    // Tender chartreuse-yellow-green & wet white core wash
    brush.noStroke();
    brush.wash("#ffffff", 210);
    drawClosedShape(ptsOut, 0.25);
    brush.fill("#d5e89c", 135);
    brush.fillBleed(0.1, "in");
    brush.wash("#e4f2b8", 120);
    drawClosedShape(ptsOut, 0.25);
    brush.noFill();
    brush.noWash();

    // Radial chartreuse, celadon, rose-magenta & snow-white coloured pencil strokes
    for (let a = 0; a < 360; a += 6) {
      const p1 = getHeartPoint(sheet, b.id, a, b.rIn);
      const p2 = getHeartPoint(sheet, b.id, a, b.rOut * 0.88);
      const p3 = getHeartPoint(sheet, b.id, a, b.rOut);

      brush.set("fine_cpencil", a % 12 === 0 ? "#a9c760" : "#ffffff", 0.58);
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      brush.set("fine_cpencil", "#d90b68", 0.52);
      brush.line(p2[0], p2[1], p3[0], p3[1]);
    }

    // Crisp magenta-violet outer rim of the baby bud
    brush.set("fine_cpencil", "#63006e", 0.65);
    brush.spline(ptsOut, 0.35);

    // Coiled chartreuse-white center fold + wet specular droplet
    const cPt = getHeartPoint(sheet, b.id, 0, 0);
    brush.set("fine_cpencil", "#7d993d", 0.55);
    brush.arc(cPt[0], cPt[1], 4.2, -40, 210);
    brush.set("wet_highlight", "#ffffff", 0.95);
    brush.circle(cPt[0] - 1.2, cPt[1] - 1.2, 2.4, 0.1);
  }
}

function drawSingleHeartRing(sheet, heartId, rOut, rIn, isInnerCore) {
  const numSec = 12;
  const stepA = 360 / numSec;

  // 1. Wet white + chartreuse-ivory + outer magenta-violet wash per sector
  for (let s = 0; s < numSec; s++) {
    const a0 = s * stepA;
    const a1 = (s + 1) * stepA;

    const bandPts = [];
    for (let a = a0; a <= a1; a += 6) bandPts.push(getHeartPoint(sheet, heartId, a, rOut * 0.95));
    for (let a = a1; a >= a0; a -= 6) bandPts.push(getHeartPoint(sheet, heartId, a, rIn));

    brush.noStroke();
    brush.wash("#ffffff", 205);
    drawClosedShape(bandPts, 0.2);

    if (isInnerCore) {
      brush.wash("#e8f4c4", 95);
      drawClosedShape(bandPts, 0.2);
    }

    const skinPts = [];
    for (let a = a0; a <= a1; a += 6) skinPts.push(getHeartPoint(sheet, heartId, a, rOut));
    for (let a = a1; a >= a0; a -= 6) skinPts.push(getHeartPoint(sheet, heartId, a, lerp(rIn, rOut, 0.64)));

    brush.fill("#d90066", 110);
    brush.fillBleed(0.12, "in");
    brush.wash("#f2388f", 85);
    drawClosedShape(skinPts, 0.2);
    brush.noFill();
    brush.noWash();
  }

  // 2. Dense coloured-pencil radial strokes & cellular texture
  const dAngle = isInnerCore ? 3.0 : 2.0;
  for (let a = 0; a < 360; a += dAngle) {
    const pIn = getHeartPoint(sheet, heartId, a, rIn + 1.0);
    const pMid = getHeartPoint(sheet, heartId, a, lerp(rIn, rOut, 0.68));
    const pOut = getHeartPoint(sheet, heartId, a, rOut);

    // Wet white & pale chartreuse inner flesh
    const fleshCol = isInnerCore && (floor(a / dAngle) % 3 === 0) ? "#d5e69e" : "#ffffff";
    brush.set("cpencil", fleshCol, 0.72);
    brush.line(pIn[0], pIn[1], pMid[0], pMid[1]);

    // Vivid rose-magenta & royal violet outer skin
    const pBleed = getHeartPoint(sheet, heartId, a, lerp(rIn, rOut, 0.46));
    brush.set("fine_cpencil", "#f23892", 0.52);
    brush.line(pOut[0], pOut[1], pBleed[0], pBleed[1]);

    brush.set("fine_cpencil", a % 4 === 0 ? "#520066" : "#d40062", 0.64);
    brush.line(pOut[0], pOut[1], pMid[0], pMid[1]);
  }

  // 3. Sharp outer & inner boundaries + glistening meniscus highlights
  const ptsO = [];
  const ptsI = [];
  for (let a = 0; a <= 360; a += 5) {
    ptsO.push(getHeartPoint(sheet, heartId, a, rOut));
    ptsI.push(getHeartPoint(sheet, heartId, a, rIn));
  }
  brush.set("fine_cpencil", "#380047", 0.88);
  brush.spline(ptsO, 0.35);
  brush.set("fine_cpencil", "#9c3b7a", 0.55);
  brush.spline(ptsI, 0.35);

  // Crisp wet white highlights around the heart rings
  for (let a = 15; a < 360; a += 28) {
    const hPts = [];
    const rH = lerp(rIn, rOut, a % 56 === 15 ? 0.14 : 0.86);
    for (let da = 0; da <= 14; da += 3.5) {
      hPts.push(getHeartPoint(sheet, heartId, a + da, rH));
    }
    brush.set("wet_highlight", "#ffffff", 0.88);
    brush.spline(hPts, 0.35);
  }
}

