// Hyperrealist Watercolour & Fine Stipple:
// Sponge Cake Wedge in Iridescent Cling Film on Oatmeal Laminate

const DEG2RAD = Math.PI / 180;

// 3D-to-2D projection for consistent perspective across saucer, cake wedge, and cling wrap
function proj(x, y, z) {
  const pitch = 32 * DEG2RAD;
  const cosP = Math.cos(pitch);
  const sinP = Math.sin(pitch);
  const camDist = 1750;
  const depth = camDist / (camDist - y * cosP + z * sinP);
  const sx = 605 + x * depth;
  const sy = 715 + (y * sinP - z * cosP) * depth;
  return [sx, sy];
}

// Helper for drawing closed/open shapes via beginShape/vertex/endShape
function drawShapePts(pts, curvature = 0.15, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Ellipse point generator
function getEllipsePts(cx, cy, rx, ry, n = 36, rotDeg = 0, jitter = 0) {
  const pts = [];
  const cosR = Math.cos(rotDeg * DEG2RAD);
  const sinR = Math.sin(rotDeg * DEG2RAD);
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const jx = jitter ? (random(-1, 1) * jitter) : 0;
    const jy = jitter ? (random(-1, 1) * jitter) : 0;
    const lx = Math.cos(a) * rx + jx;
    const ly = Math.sin(a) * ry + jy;
    pts.push([
      cx + lx * cosR - ly * sinR,
      cy + lx * sinR + ly * cosR
    ]);
  }
  return pts;
}

// 3D Cake Wedge coordinate evaluator
// u in [0, 1]: radial position from Tip (0) to Outer Crust (1)
// v in [0, 1]: angular position from Front Cut Face (0) to Back Cut Face (1)
// w in [0, 1]: vertical position from Bottom (0) to Top (1)
function cakePoint3D(u, v, w) {
  const tipX = -255;
  const tipY = -12;
  const radius = 485;
  const angFront = 22.5 * DEG2RAD;
  const angBack = -33.5 * DEG2RAD;
  const ang = angFront + (angBack - angFront) * v;

  // Slight outward curve along the crust and subtle pinch at the tip from tight cling wrap
  const r = u * radius;
  let x = tipX + r * Math.cos(ang);
  let y = tipY + r * Math.sin(ang);

  // Height Compression: cling film pulls down the tip and outer edges slightly, doming the center
  const baseH = 248;
  const tipCompress = 0.88 + 0.12 * Math.pow(u, 0.45);
  const edgePillow = 1.0 + 0.065 * Math.sin(u * Math.PI) * Math.sin(v * Math.PI);
  // Subtle waist indentation at the soft middle buttercream layer under plastic tension
  const waistBulge = Math.sin(w * Math.PI) * 5 * (1 - 0.5 * Math.abs(v - 0.5));

  const z = w * baseH * tipCompress * edgePillow;
  x += waistBulge * Math.cos(ang - 0.3);
  y += waistBulge * Math.sin(ang - 0.3);

  return [x, y, z];
}

function cakePoint2D(u, v, w) {
  const p3 = cakePoint3D(u, v, w);
  return proj(p3[0], p3[1], p3[2]);
}

// Interpolate 2D points
function lerpPt(p1, p2, t) {
  return [p1[0] + (p2[0] - p1[0]) * t, p1[1] + (p2[1] - p1[1]) * t];
}

// Evaluate quadratic bezier
function quadPt(p0, p1, p2, t) {
  const mt = 1 - t;
  return [
    mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0],
    mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1]
  ];
}

// Evaluate cubic bezier
function cubicPt(p0, p1, p2, p3, t) {
  const mt = 1 - t;
  const mt2 = mt * mt;
  const t2 = t * t;
  return [
    mt2 * mt * p0[0] + 3 * mt2 * t * p1[0] + 3 * mt * t2 * p2[0] + t2 * t * p3[0],
    mt2 * mt * p0[1] + 3 * mt2 * t * p1[1] + 3 * mt * t2 * p2[1] + t2 * t * p3[1]
  ];
}

