function draw() {
  translate(-width / 2, -height / 2);

  // Warm-neutral oatmeal base
  background("#ddd5c7");

  // 1. Dull kitchen counter in oatmeal laminate
  drawOatmealLaminateCounter();

  // 2. Multi-layered watercolor cast shadows & refracted opal caustics on counter
  drawCounterShadowsAndCaustics();

  // 3. Glazed porcelain saucer with reflected cake & opal tints
  drawPorcelainSaucer();

  // 4. Back/underneath layers of the cling film skirt on the saucer
  drawBackClingFilmSkirt();

  // 5. The Sponge Cake Wedge (blurred watercolour crumb, pale buttercream, berry jam, golden crust)
  drawSpongeCakeWedge();

  // 6. Soft milk-white watercolour veils & translucent plastic wraps over the cake
  drawMilkyWatercolourVeils();

  // 7. Opal play-of-colour watercolour glazes floating in the milky haze
  drawOpalPlayOfColourWashes();

  // 8. Sharp, broken spectral flecks along each fold (fine spray & stipple)
  drawBrokenSpectralFlecks();

  // 9. Hyper-precise trapped air bubbles and stretched tension wrinkles
  drawHyperPreciseAirBubbles();
  drawHyperPreciseStretchedWrinkles();

  // 10. Final specular highlights & foreground crumpled edge details
  drawFinalSpecularHighlights();

  noLoop();
}

// ============================================================================
// 1. OATMEAL LAMINATE KITCHEN COUNTER
// ============================================================================
function drawOatmealLaminateCounter() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Broad subtle tonal graduations across the dull matte counter
  const counterWashes = [
    { col: "#e6dfd2", alpha: 75, bleed: 0.35, pts: [[-40, -40], [820, -40], [640, 560], [-40, 680]] },
    { col: "#cfc6b6", alpha: 65, bleed: 0.38, pts: [[520, -40], [1240, -40], [1240, 650], [440, 480]] },
    { col: "#c4baa8", alpha: 70, bleed: 0.35, pts: [[-40, 620], [1240, 520], [1240, 1240], [-40, 1240]] },
    { col: "#b8ae9c", alpha: 60, bleed: 0.32, pts: [[560, 720], [1240, 640], [1240, 1240], [320, 1240]] },
    { col: "#ebe5da", alpha: 55, bleed: 0.3, pts: [[60, 160], [680, 190], [540, 540], [40, 500]] }
  ];

  for (const w of counterWashes) {
    brush.fill(w.col, w.alpha);
    brush.fillBleed(w.bleed, "out");
    brush.fillTexture(0.45, 0.2);
    drawShapePts(w.pts, 0.1, true);
  }
  brush.noFill();

  // Subtle rear counter seam / backsplash shadow near top of frame (y ~ 135..165)
  brush.wash("#b5ab9b", 55);
  drawShapePts([[-20, -20], [1220, -20], [1220, 148], [-20, 178]], 0.05, true);
  brush.wash("#9c9283", 45);
  drawShapePts([[-20, 142], [1220, 112], [1220, 154], [-20, 184]], 0.05, true);
  brush.noWash();

  // Fine matte directional laminate weave (very low contrast horizontal/slight-angle lines)
  brush.set("2H", "#c6bdb0", 0.55);
  for (let i = 0; i < 160; i++) {
    const y = random(160, 1190);
    const x1 = random(-20, 1050);
    const len = random(80, 260);
    const col = i % 3 === 0 ? "#e8e2d6" : (i % 3 === 1 ? "#c2b8a8" : "#b3a999");
    brush.set("2H", col, random(0.35, 0.65));
    brush.line(x1, y, x1 + len, y - len * 0.025 + random(-1.5, 1.5));
  }

  // Characteristic oatmeal Formica/laminate particulate fleck texture
  const fleckColors = [
    { col: "#ede8de", weight: 1.1, count: 150 },
    { col: "#c4baaa", weight: 1.0, count: 160 },
    { col: "#a89e8e", weight: 0.85, count: 140 },
    { col: "#8f8475", weight: 0.65, count: 95 },
    { col: "#f4f0e6", weight: 0.8, count: 110 }
  ];

  for (const fc of fleckColors) {
    brush.set("micro_stipple", fc.col, fc.weight);
    for (let i = 0; i < fc.count; i++) {
      const x = random(15, 1185);
      const y = random(15, 1185);
      // Skip center saucer interior to save render budget
      const dx = (x - 605) / 410;
      const dy = (y - 715) / 220;
      if (dx * dx + dy * dy < 0.72) continue;
      const l = random(4, 18);
      const a = random(-15, 15) * DEG2RAD;
      brush.line(x, y, x + Math.cos(a) * l, y + Math.sin(a) * l);
    }
  }
}

