    { cx: 790, cy: 695, rx: 310, ry: 175, col: "#8c8072", alpha: 72, bleed: 0.35 },
    // Deep contact core shadow directly beneath saucer foot-ring & rim
    { cx: 625, cy: 742, rx: 380, ry: 196, col: "#594f47", alpha: 95, bleed: 0.18 },
    { cx: 615, cy: 735, rx: 340, ry: 175, col: "#3d3530", alpha: 105, bleed: 0.14 }
  ];

  for (const s of shadowLayers) {
    brush.fill(s.col, s.alpha);
    brush.fillBleed(s.bleed, "out");
