  }

  // Subtle refracted opal caustics transmitted through the overhanging cling film into the shadow
  const caustics = [
    { cx: 955, cy: 685, rx: 75, ry: 38, rot: -12, col: "#ff6d24", alpha: 42 },
    { cx: 985, cy: 725, rx: 68, ry: 34, rot: 8, col: "#00e676", alpha: 38 },
    { cx: 925, cy: 755, rx: 82, ry: 40, rot: 18, col: "#d500f9", alpha: 36 },
    { cx: 880, cy: 810, rx: 70, ry: 30, rot: 25, col: "#ff9100", alpha: 35 },
    { cx: 1015, cy: 695, rx: 52, ry: 25, rot: -5, col: "#f0f7ff", alpha: 48 }
  ];

  for (const c of caustics) {
    brush.fill(c.col, c.alpha);
    brush.fillBleed(0.4, "out");
    brush.fillTexture(0.35, 0.15);
    drawShapePts(getEllipsePts(c.cx, c.cy, c.rx, c.ry, 24, c.rot, 2), 0.25, true);
  }
  brush.noFill();
}

// ============================================================================
// 3. GLAZED PORCELAIN SAUCER
// ============================================================================
function drawPorcelainSaucer() {
  brush.noStroke();

  const scx = 605;
  const scy = 708;
  const outerRx = 442;
  const outerRy = 234;
  const wellCx = 605;
  const wellCy = 720;
  const wellRx = 292;
  const wellRy = 154;

  // Underside bevel of saucer (dark warm-cool ceramic edge)
  brush.wash("#6b635b", 160);
  drawShapePts(getEllipsePts(scx + 4, scy + 11, outerRx, outerRy, 52), 0.15, true);

  // Main porcelain body wash
  brush.wash("#f4f1ea", 235);
  drawShapePts(getEllipsePts(scx, scy, outerRx, outerRy, 56), 0.15, true);
  brush.noWash();

  // Rim shading: upper-left rim slope slightly shaded, lower-right rim catching warm light
  brush.fill("#d5dce3", 78);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.4, 0.25);
  drawShapePts(getEllipsePts(scx - 22, scy - 12, outerRx * 0.94, outerRy * 0.92, 44), 0.15, true);

  brush.fill("#fcfaf5", 110);
