// ============================================================================
// 5. THE SPONGE CAKE WEDGE (WATERCOLOUR CRUMB, BUTTERCREAM & BERRY JAM)
// ============================================================================
function drawSpongeCakeWedge() {
  brush.noStroke();

  // Helper to build a quad strip on the Front Cut Face (v = 0) between height w0 and w1
  function frontFaceBand(w0, w1, steps = 10) {
    const pts = [];
    for (let i = 0; i <= steps; i++) {
      pts.push(cakePoint2D(i / steps, 0, w0));
    }
    for (let i = steps; i >= 0; i--) {
      pts.push(cakePoint2D(i / steps, 0, w1));
    }
    return pts;
  }

  // Helper to build a quad strip on the Curved Outer Crust Face (u = 1) between height w0 and w1
  function crustFaceBand(w0, w1, vStart = 0, vEnd = 1, steps = 10) {
    const pts = [];
    for (let i = 0; i <= steps; i++) {
      const v = vStart + (vEnd - vStart) * (i / steps);
      pts.push(cakePoint2D(1, v, w0));
    }
    for (let i = steps; i >= 0; i--) {
      const v = vStart + (vEnd - vStart) * (i / steps);
      pts.push(cakePoint2D(1, v, w1));
    }
    return pts;
  }

  // Helper for the Top Surface (w = 1)
  function topSurfacePoly(steps = 12) {
    const pts = [];
    for (let i = 0; i <= steps; i++) pts.push(cakePoint2D(i / steps, 0, 1));
    for (let i = 1; i <= steps; i++) pts.push(cakePoint2D(1, i / steps, 1));
    for (let i = steps - 1; i >= 1; i--) pts.push(cakePoint2D(i / steps, 1, 1));
    return pts;
  }

  // --- 5A. OPAQUE UNDERPAINTING WASHES TO ANCHOR THE CAKE VOLUME ---
  brush.wash("#f2dfa0", 195);
  drawShapePts(frontFaceBand(0, 0.92), 0.08, true);
  brush.wash("#c98a3e", 190);
  drawShapePts(crustFaceBand(0, 0.94, 0, 0.92), 0.12, true);
  brush.wash("#fbf6e6", 215);
  drawShapePts(topSurfacePoly(), 0.1, true);
  brush.noWash();

  // --- 5B. WATERCOLOUR LAYERS OF THE CAKE (BLURRED BENEATH FILM) ---
  // 1. Golden-brown bottom bake line (w: 0 .. 0.05)
  brush.fill("#9e6324", 115);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.35);
  drawShapePts(frontFaceBand(0, 0.055), 0.1, true);

  // 2. Bottom Yellow Sponge Layer (w: 0.04 .. 0.41)
  brush.fill("#e8c86b", 125);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.6, 0.35);
  drawShapePts(frontFaceBand(0.04, 0.42), 0.1, true);

  // Richer golden-ochre sponge variations
  for (let k = 0; k < 5; k++) {
    const u0 = k * 0.18;
    const u1 = u0 + 0.26;
    const col = k % 2 === 0 ? "#d9b04c" : "#f0d786";
    brush.fill(col, 85);
    brush.fillBleed(0.35, "out");
    drawShapePts([
      cakePoint2D(u0, 0, 0.06),
      cakePoint2D(u1, 0, 0.06),
      cakePoint2D(u1, 0, 0.41),
      cakePoint2D(u0, 0, 0.41)
    ], 0.18, true);
  }

  // 3. Top Yellow Sponge Layer (w: 0.56 .. 0.90)
  brush.fill("#edd17a", 125);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.6, 0.35);
  drawShapePts(frontFaceBand(0.56, 0.91), 0.1, true);

  for (let k = 0; k < 5; k++) {
    const u0 = k * 0.18;
    const u1 = u0 + 0.25;
    const col = k % 2 === 0 ? "#cca03f" : "#f5de93";
    brush.fill(col, 82);
    brush.fillBleed(0.35, "out");
    drawShapePts([
      cakePoint2D(u0, 0, 0.57),
      cakePoint2D(u1, 0, 0.57),
      cakePoint2D(u1, 0, 0.89),
      cakePoint2D(u0, 0, 0.89)
    ], 0.18, true);
  }

  // 4. Middle Pale Buttercream Filling Band (w: 0.40 .. 0.52)
  brush.fill("#fff9e6", 155);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.4, 0.25);
  drawShapePts(frontFaceBand(0.39, 0.53), 0.12, true);

  // Subtle warm vanilla shadow along bottom of middle buttercream
  brush.fill("#dfd1b0", 95);
  brush.fillBleed(0.25, "out");
  drawShapePts(frontFaceBand(0.39, 0.44), 0.12, true);

  // 5. Raspberry-Apricot Jam Vein above the middle buttercream (w: 0.50 .. 0.57)
  brush.fill("#c9243f", 135);
  brush.fillBleed(0.36, "out");
  brush.fillTexture(0.55, 0.4);
  drawShapePts(frontFaceBand(0.50, 0.575), 0.15, true);

  // Deep ruby jam clots bleeding softly into the crumb
  for (let k = 0; k < 6; k++) {
    const u0 = 0.06 + k * 0.15;
    const u1 = u0 + 0.13;
    brush.fill(k % 2 === 0 ? "#911229" : "#e34258", 110);
    brush.fillBleed(0.38, "out");
    drawShapePts([
      cakePoint2D(u0, 0, 0.49),
      cakePoint2D(u1, 0, 0.50),
      cakePoint2D(u1, 0, 0.585),
      cakePoint2D(u0, 0, 0.575)
    ], 0.2, true);
  }

  // 6. Curved Outer Golden-Caramelized Crust (u = 1)
  brush.fill("#bd792c", 130);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.6, 0.4);
  drawShapePts(crustFaceBand(0.02, 0.41, 0, 0.9), 0.12, true);
  drawShapePts(crustFaceBand(0.56, 0.91, 0, 0.9), 0.12, true);

  // Darker toasted caramel crust shading on right/back turn
  brush.fill("#8c4f14", 115);
  brush.fillBleed(0.3, "out");
  drawShapePts(crustFaceBand(0.02, 0.90, 0.35, 0.92), 0.12, true);

  // Buttercream & jam peeking out along the curved crust middle seam
  brush.fill("#f7eed4", 140);
  brush.fillBleed(0.22, "out");
  drawShapePts(crustFaceBand(0.40, 0.53, 0, 0.85), 0.12, true);
  brush.fill("#b81d38", 120);
  brush.fillBleed(0.3, "out");
  drawShapePts(crustFaceBand(0.51, 0.57, 0, 0.82), 0.12, true);

  // 7. Top Pale Buttercream Icing Layer (w: 0.90 .. 1.0 + Top Surface)
  brush.fill("#fdf8eb", 150);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.38, 0.2);
  drawShapePts(frontFaceBand(0.89, 1.0), 0.1, true);
  drawShapePts(topSurfacePoly(), 0.12, true);

  // Subtle buttercream palette-knife depressions on the top face (warm ivory-beige)
  const topSwirls = [
    { u0: 0.15, u1: 0.55, v0: 0.08, v1: 0.45, col: "#e8dec3", alpha: 80 },
    { u0: 0.48, u1: 0.88, v0: 0.12, v1: 0.62, col: "#dfd2b2", alpha: 75 },
    { u0: 0.62, u1: 0.96, v0: 0.45, v1: 0.88, col: "#d4c4a1", alpha: 85 },
    { u0: 0.25, u1: 0.72, v0: 0.52, v1: 0.92, col: "#efe6ce", alpha: 70 }
  ];
  for (const sw of topSwirls) {
    brush.fill(sw.col, sw.alpha);
    brush.fillBleed(0.28, "out");
    drawShapePts([
      cakePoint2D(sw.u0, sw.v0, 1),
      cakePoint2D(sw.u1, sw.v0, 1),
      cakePoint2D(sw.u1, sw.v1, 1),
      cakePoint2D(sw.u0, sw.v1, 1)
    ], 0.22, true);
  }
  brush.noFill();

  // --- 5C. AERATED SPONGE CRUMB TEXTURE (VISIBLE BUT BLURRED BENEATH FILM) ---
  // Soft spray granulation + small cellular crumb pores across both sponge layers
  const crumbZones = [
    { wMin: 0.06, wMax: 0.39 },
    { wMin: 0.58, wMax: 0.88 }
  ];

  for (const zone of crumbZones) {
    // Pass 1: Soft blurred crumb spray
    for (let i = 0; i < 95; i++) {
      const u = random(0.03, 0.97);
      const w = random(zone.wMin, zone.wMax);
      const p = cakePoint2D(u, 0, w);
      const col = i % 3 === 0 ? "#b88a2e" : (i % 3 === 1 ? "#fae69e" : "#cfa242");
      brush.set("crumb_spray", col, random(0.9, 1.7));
      brush.line(p[0] - 4, p[1] - 1, p[0] + 4, p[1] + 1);
    }

    // Pass 2: Aerated sponge cells / pockets (sharper where film clings, softer where veiled)
    for (let i = 0; i < 190; i++) {
      const u = random(0.02, 0.98);
      const w = random(zone.wMin, zone.wMax);
      const p = cakePoint2D(u, 0, w);
      const isDarkPore = random() < 0.62;
      const col = isDarkPore
        ? (random() < 0.45 ? "#9c6d1c" : "#b88930")
        : "#fff2be";
      brush.set("2B", col, random(0.55, 1.25));
      const rx = random(1.2, 3.8);
      const ry = random(0.9, 2.6);
      drawShapePts(getEllipsePts(p[0], p[1], rx, ry, 7, random(-25, 25)), 0.25, true);
    }
  }

  // Crust side texture (toasted golden pores on curved outer face)
  for (let i = 0; i < 85; i++) {
    const v = random(0.02, 0.85);
    const w = random() < 0.5 ? random(0.05, 0.39) : random(0.58, 0.88);
    const p = cakePoint2D(1.0, v, w);
    const col = i % 2 === 0 ? "#783f0c" : "#d99b4c";
    brush.set("crumb_spray", col, random(0.8, 1.4));
    brush.line(p[0] - 3, p[1] - 2, p[0] + 3, p[1] + 2);
  }
}

