// ============================================================================
// 8. SHARP, BROKEN SPECTRAL FLECKS ALONG EACH FOLD (SPRAY & STIPPLE)
// ============================================================================
function drawBrokenSpectralFlecks() {
  const creases = getCreaseDefinitions();

  // Cyclic opal interference spectrum:
  // Electric Green -> Cyan-Mint -> Lilac -> Orchid-Magenta -> Flame Orange -> Amber-Chartreuse
  const spectrum = [
    "#00ff88",
    "#00e676",
    "#00e5ff",
    "#b388ff",
    "#d500f9",
    "#ea80fc",
    "#ff1744",
    "#ff3d00",
    "#ff6d00",
    "#ffab00",
    "#76ff03"
  ];

  for (const cr of creases) {
    const segments = 34;
    for (let i = 0; i < segments; i++) {
      // Leave slight broken gaps so the flecks read as broken spectral shards along the fold
      if (random() < 0.14) continue;

      const t0 = i / segments;
      const t1 = (i + 0.85) / segments;
      const pt0 = cubicPt(cr.p0, cr.p1, cr.p2, cr.p3, t0);
      const pt1 = cubicPt(cr.p0, cr.p1, cr.p2, cr.p3, t1);

      // Tangent & normal vector along the fold
      const dx = pt1[0] - pt0[0];
      const dy = pt1[1] - pt0[1];
      const len = Math.hypot(dx, dy) || 1;
      const nx = -dy / len;
      const ny = dx / len;

      // Color shifts continuously along the fold so it changes as your eye moves
      const specIdx = Math.floor(((t0 * 2.6 + cr.phase) % 1.0) * spectrum.length);
      const colMain = spectrum[specIdx];
      const colComp = spectrum[(specIdx + 4) % spectrum.length];

      // 1. Fine spray burst along the crease flank
      const flankOffset = random(-cr.width * 0.35, cr.width * 0.35);
      const sx0 = pt0[0] + nx * flankOffset;
      const sy0 = pt0[1] + ny * flankOffset;
      const sx1 = pt1[0] + nx * flankOffset;
      const sy1 = pt1[1] + ny * flankOffset;

      brush.set("fine_spray", colMain, random(0.85, 1.55));
      brush.line(sx0, sy0, sx1, sy1);

      // 2. Tighter high-saturation micro-stipple right on the bevel edge
      const bevelOff = random(-4.5, 4.5);
      brush.set("micro_stipple", colComp, random(0.75, 1.35));
      brush.line(
        pt0[0] + nx * bevelOff,
        pt0[1] + ny * bevelOff,
        pt1[0] + nx * bevelOff,
        pt1[1] + ny * bevelOff
      );

      // 3. Sharp broken spectral shard flecks (custom diamond tip)
      if (random() < 0.72) {
        const shardOff = random(-6, 6);
        brush.set("spectral_shard", colMain, random(0.7, 1.35));
        brush.line(
          pt0[0] + nx * shardOff,
          pt0[1] + ny * shardOff,
          pt1[0] + nx * shardOff + random(-2, 2),
          pt1[1] + ny * shardOff + random(-2, 2)
        );
      }

      // 4. Tiny pinpoint stipple dots clustered near fold kinks
      for (let d = 0; d < 3; d++) {
        const dotCol = d === 0 ? colMain : (d === 1 ? colComp : "#ffffff");
        const rOff = random(-cr.width * 0.45, cr.width * 0.45);
        const px = pt0[0] + dx * random(0, 1) + nx * rOff;
        const py = pt0[1] + dy * random(0, 1) + ny * rOff;
        brush.set("needle", dotCol, random(0.7, 1.3));
        brush.line(px, py, px + dx * 0.18 + random(-1.5, 1.5), py + dy * 0.18 + random(-1.5, 1.5));
      }
    }
  }
}

// ============================================================================
// 9A. HYPER-PRECISE TRAPPED AIR BUBBLES
// ============================================================================
function drawHyperPreciseAirBubbles() {
  // Trapped air pockets between the buttercream/sponge and the tight cling film
  const bubbles = [];

  // Cluster A: Top pale buttercream surface (flattened elliptical perspective)
  const topBubbleSeeds = [
    { u: 0.22, v: 0.18, rx: 16, ry: 9, rot: -12 },
    { u: 0.29, v: 0.24, rx: 8, ry: 4.5, rot: -8 },
    { u: 0.34, v: 0.15, rx: 5.5, ry: 3.2, rot: -15 },
    { u: 0.52, v: 0.28, rx: 21, ry: 11.5, rot: 6 },
    { u: 0.59, v: 0.36, rx: 11, ry: 6, rot: 10 },
    { u: 0.46, v: 0.38, rx: 6.5, ry: 3.8, rot: 4 },
    { u: 0.74, v: 0.22, rx: 14, ry: 7.5, rot: 15 },
    { u: 0.81, v: 0.30, rx: 7.5, ry: 4.2, rot: 18 },
    { u: 0.68, v: 0.56, rx: 18, ry: 9.5, rot: -6 },
    { u: 0.76, v: 0.64, rx: 9, ry: 5, rot: -4 },
    { u: 0.38, v: 0.62, rx: 13, ry: 7, rot: -18 },
    { u: 0.16, v: 0.42, rx: 9.5, ry: 5.2, rot: -20 }
  ];

  for (const b of topBubbleSeeds) {
    const p = cakePoint2D(b.u, b.v, 1.0);
    bubbles.push({ cx: p[0], cy: p[1], rx: b.rx, ry: b.ry, rot: b.rot });
  }

  // Cluster B: Front Cut Face (especially along the smooth middle & top buttercream and clinging sponge zones)
  const frontBubbleSeeds = [
    { u: 0.18, w: 0.46, rx: 13, ry: 9.5, rot: 12 },
    { u: 0.24, w: 0.49, rx: 6.5, ry: 4.8, rot: 8 },
    { u: 0.44, w: 0.45, rx: 17, ry: 11, rot: 14 },
    { u: 0.51, w: 0.48, rx: 8.5, ry: 5.5, rot: 10 },
    { u: 0.72, w: 0.47, rx: 14, ry: 9, rot: 16 },
    { u: 0.79, w: 0.44, rx: 6, ry: 4.2, rot: 12 },
    { u: 0.32, w: 0.76, rx: 15, ry: 10.5, rot: -10 },
    { u: 0.38, w: 0.82, rx: 7.5, ry: 5.2, rot: -6 },
    { u: 0.62, w: 0.74, rx: 19, ry: 12.5, rot: 18 },
    { u: 0.69, w: 0.68, rx: 9, ry: 6, rot: 22 },
    { u: 0.26, w: 0.22, rx: 12, ry: 8.5, rot: 8 },
    { u: 0.58, w: 0.24, rx: 14.5, ry: 9.5, rot: -14 },
    { u: 0.86, w: 0.64, rx: 11, ry: 8, rot: 25 },
    { u: 0.12, w: 0.68, rx: 8, ry: 5.5, rot: -12 }
  ];

  for (const b of frontBubbleSeeds) {
    const p = cakePoint2D(b.u, 0, b.w);
    bubbles.push({ cx: p[0], cy: p[1], rx: b.rx, ry: b.ry, rot: b.rot });
  }

  // Cluster C: Small satellite micro-blisters around the main bubbles
  const mainCount = bubbles.length;
  for (let i = 0; i < mainCount; i++) {
    const mb = bubbles[i];
    const subCount = 2 + (i % 2);
    for (let s = 0; s < subCount; s++) {
      const ang = random(0, 360) * DEG2RAD;
      const dist = mb.rx * random(1.15, 1.9);
      bubbles.push({
        cx: mb.cx + Math.cos(ang) * dist,
        cy: mb.cy + Math.sin(ang) * dist * 0.75,
        rx: random(2.2, 4.8),
        ry: random(1.8, 3.8),
        rot: mb.rot + random(-15, 15)
      });
    }
  }

  // Render every air bubble with hyper-precise optical anatomy:
  // 1. Milky translucent interior lift
  // 2. Dark outer contact compression rim
  // 3. Split spectral interference rim (electric green on one side, flame orange / lilac on the other)
  // 4. Razor-sharp curved white specular highlight + opposite bounce dot
  for (let i = 0; i < bubbles.length; i++) {
    const b = bubbles[i];
    const pts = getEllipsePts(b.cx, b.cy, b.rx, b.ry, 20, b.rot, 0.25);

    // 1. Milky interior wash for larger bubbles
    if (b.rx > 5) {
      brush.noStroke();
      brush.wash("#f2f7ff", 48);
      drawShapePts(pts, 0.2, true);
      brush.noWash();
    }

    // 2. Crisp dark-warm refractive contact shadow ring
    brush.set("needle", "#5c4d42", 0.55);
    drawShapePts(pts, 0.2, true);

    // 3. Prismatic thin-film interference rim arcs
    const col1 = i % 3 === 0 ? "#00ff88" : (i % 3 === 1 ? "#ff5722" : "#d500f9");
    const col2 = i % 3 === 0 ? "#e040fb" : (i % 3 === 1 ? "#00e676" : "#ff9100");

    const upperArc = pts.slice(0, 11);
    const lowerArc = pts.slice(10, 20);

    brush.set("needle", col1, 0.85);
    drawShapePts(upperArc, 0.2, false);

    brush.set("needle", col2, 0.8);
    drawShapePts(lowerArc, 0.2, false);

    // 4. Specular highlight crescent on upper-left of bubble dome
    const hlPts = getEllipsePts(b.cx - b.rx * 0.15, b.cy - b.ry * 0.18, b.rx * 0.72, b.ry * 0.68, 16, b.rot);
    brush.set("specular", "#ffffff", b.rx > 8 ? 1.05 : 0.7);
    drawShapePts(hlPts.slice(9, 14), 0.25, false);

    // Pinpoint bounce reflection on lower-right of bubble
    const bx = b.cx + b.rx * 0.45;
    const by = b.cy + b.ry * 0.42;
    brush.set("specular", "#ffffff", 0.65);
    brush.line(bx, by, bx + 1.5, by - 1.0);
  }
}

