// ============================================================================
// 10. FINAL SPECULAR HIGHLIGHTS & FOREGROUND CRUMPLED PLASTIC EDGES
// ============================================================================
function drawFinalSpecularHighlights() {
  const creases = getCreaseDefinitions();

  // Sharp, broken white specular ridges along the main folds
  for (const cr of creases) {
    const sub = 6;
    for (let s = 0; s < sub; s++) {
      if (s % 2 === 1 && random() < 0.35) continue;
      const tA = (s + 0.08) / sub;
      const tB = (s + 0.46) / sub;
      const tC = (s + 0.84) / sub;
      const pA = cubicPt(cr.p0, cr.p1, cr.p2, cr.p3, tA);
      const pB = cubicPt(cr.p0, cr.p1, cr.p2, cr.p3, tB);
      const pC = cubicPt(cr.p0, cr.p1, cr.p2, cr.p3, tC);

      brush.set("specular", "#ffffff", random(0.95, 1.45));
      brush.spline([
        [pA[0], pA[1], 0.2],
        [pB[0], pB[1], 1.4],
        [pC[0], pC[1], 0.2]
      ], 0.35);
    }
  }

  // Crisp polygonal crinkle facets around the outer cling film skirt on the saucer
  const outerSkirtOutline = [
    [222, 705], [255, 658], [308, 632], [352, 565],
    cakePoint2D(0.0, 0.0, 1.0),
    cakePoint2D(0.45, 0.88, 1.01),
    cakePoint2D(1.0, 0.92, 1.0),
    [835, 512], [902, 595], [958, 688], [932, 768],
    [858, 804], [735, 808], [585, 795], [435, 772],
    [305, 755], [238, 732], [222, 705]
  ];

  for (let i = 0; i < outerSkirtOutline.length - 1; i++) {
    const p1 = outerSkirtOutline[i];
    const p2 = outerSkirtOutline[i + 1];
    const mid = lerpPt(p1, p2, 0.5);

    // Subtle dark edge definition where plastic skirt meets porcelain/air
    brush.set("needle", "#6d655e", 0.55);
    brush.line(p1[0] + 1, p1[1] + 1.5, p2[0] + 1, p2[1] + 1.5);

    // Spectral rim glint on the cut/folded edge of the cling wrap
    const edgeSpec = i % 3 === 0 ? "#00ff88" : (i % 3 === 1 ? "#ff5722" : "#d500f9");
    brush.set("needle", edgeSpec, 0.8);
    brush.line(p1[0] - 1, p1[1] - 1, mid[0] - 1, mid[1] - 1);

    // Pure white edge highlight
    brush.set("specular", "#ffffff", 1.05);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

