function draw() {
  translate(-width / 2, -height / 2);
  background("#f5ede2");

  // 1. Directional tabletop surface & soft paper/stone grain
  drawTabletopSurface();

  // 2. Cast shadows & translucent emerald/ruby caustics on the tabletop
  drawTabletopShadowsAndCaustics(scene);

  // 3. Green translucent moulded punnet: back & floor walls (behind interior berries)
  drawPunnetBackAndFloor(scene.punnet);

  // 4. Raspberries deep inside the punnet (veiled behind the translucent front/top wall)
  const insideBerries = scene.berries.filter(b => b.layerGroup === "inside_punnet");
  drawBerryBatchHalos(insideBerries);
  for (let b of insideBerries) {
    drawSingleBerry(b, scene.berries);
  }

  // 5. Green translucent moulded punnet: upper/front walls, ribs, vent slots & rim flange
  drawPunnetFrontAndRim(scene.punnet);

  // 6. Main tumbling heap of raspberries across the full frame (sorted back-to-front)
  const mainBerries = scene.berries.filter(b => b.layerGroup === "main_heap");
  // Group into depth tiers so watercolor halos batch efficiently while preserving depth order
  const tierSize = 8;
  for (let i = 0; i < mainBerries.length; i += tierSize) {
    const slice = mainBerries.slice(i, i + tierSize);
    drawInterBerryShadowWashes(slice);
    drawBerryBatchHalos(slice);
    for (let b of slice) {
      drawSingleBerry(b, scene.berries);
    }
  }

  // 7. Loose detached drupelets and bleeding madder juice stains on the foreground surface
  drawLooseDrupelets(scene.looseDrupelets);

  // 8. Final specular silver hair glints and punnet rim highlights
  drawFinalAccents(scene);

  noLoop();
}

