function buildScene() {
  // 3D parametric punnet definition: tilted on its side in upper-right, spilling toward lower-left
  const punnet = {
    // u: width [-1, 1], v: height [-1 (top wall), 1 (tabletop wall)], w: depth [0 (back base), 1 (open mouth)]
    pt: function(u, v, w) {
      // Taper from base (w=0) to mouth (w=1)
      let flare = 0.76 + 0.24 * w;
      let uu = u * flare;
      let vv = v * flare;

      // Center spine from back-right (w=0) to mouth-center (w=1)
      let cx = 975 - w * 275;
      let cy = 235 + w * 145;

      // Basis vectors in 2D screen space (isometric/perspective projection)
      // u-axis spans diagonally down-right to up-left
      let ux = 152, uy = 148;
      // v-axis spans from elevated top wall (v=-1) to tabletop lower wall (v=+1)
      let vx = -78, vy = 132;

      let x = cx + uu * ux + vv * vx;
      let y = cy + uu * uy + vv * vy;
      let z = (1 - vv) * 85 + (1 - w) * 20;
      return { x, y, z };
    }
  };

