function createBerryGeometry(spec, idx) {
  let [bx, by, bz, R, aspect, ax, ay, az, palKey, showHollow, hasCalyx, layerGroup] = spec;
  let alen = Math.hypot(ax, ay, az);
  ax /= alen; ay /= alen; az /= alen;

  // Orthonormal basis (U, V, A) for the berry
  let tx = Math.abs(ax) < 0.8 ? 1 : 0;
  let ty = Math.abs(ax) < 0.8 ? 0 : 1;
  let tz = 0;
  let ux = ay * tz - az * ty;
  let uy = az * tx - ax * tz;
  let uz = ax * ty - ay * tx;
  let ulen = Math.hypot(ux, uy, uz);
  ux /= ulen; uy /= ulen; uz /= ulen;

  let vx = uy * az - uz * ay;
  let vy = uz * ax - ux * az;
  let vz = ux * ay - uy * ax;

  let drupelets = [];
  let innerDrupelets = [];

  // Staggered rings along the berry axis t in [-0.78, 1.0]
  const numRings = 8;
  for (let rIdx = 0; rIdx <= numRings; rIdx++) {
    let frac = rIdx / numRings;
    let t = -0.78 + frac * 1.78;

    // If hollow receptacle is open at the base (t near -0.78), leave opening
    if (showHollow && rIdx === 0) continue;

    // Conical-ovoid silhouette profile of a ripe raspberry
    let profR;
    if (t < 0) {
      profR = Math.cos(t * 0.92);
    } else {
      profR = Math.pow(Math.max(0.02, Math.cos(t * Math.PI * 0.485)), 0.76);
    }

    let count = rIdx === numRings ? 1 : Math.max(4, Math.round(14.5 * profR));
    let angleOffset = (rIdx % 2) * (Math.PI / count) + idx * 0.37;

    for (let c = 0; c < count; c++) {
      let phi = angleOffset + (c / count) * Math.PI * 2 + (noise(idx * 10 + rIdx, c) - 0.5) * 0.14;
      let cosphi = Math.cos(phi);
      let sinphi = Math.sin(phi);

      // Local normal on the berry surface
      let nx = (ux * cosphi + vx * sinphi) * profR + ax * (t * 0.55);
      let ny = (uy * cosphi + vy * sinphi) * profR + ay * (t * 0.55);
      let nz = (uz * cosphi + vz * sinphi) * profR + az * (t * 0.55);
      let nlen = Math.hypot(nx, ny, nz);
      nx /= nlen; ny /= nlen; nz /= nlen;

      // Cull back-facing drupelets on the hidden rear hemisphere
      if (nz < -0.22) continue;

      // 3D position on the berry surface
      let px = bx + R * (ux * cosphi * profR + vx * sinphi * profR + ax * t * aspect * 0.74);
      let py = by + R * (uy * cosphi * profR + vy * sinphi * profR + ay * t * aspect * 0.74);
      let pz = bz + R * (uz * cosphi * profR + vz * sinphi * profR + az * t * aspect * 0.74);

      // Drupelet bead radius
      let baseDr = R * (0.215 - 0.035 * Math.max(0, t)) * (0.92 + 0.16 * noise(idx, rIdx * 3, c));
      let foreshorten = 0.72 + 0.28 * Math.max(0, nz);

      // Slight per-drupelet color variation (some berries have coral-to-madder ombré)
      let dPalKey = palKey;
      if (palKey === "coral" && t < -0.15 && noise(idx, c) > 0.45) {
        dPalKey = "madder";
      } else if (palKey === "madder" && t > 0.45 && (idx % 3 === 0) && noise(idx, c) > 0.4) {
        dPalKey = "coral";
      }

      drupelets.push({
        x: px,
        y: py,
        z: pz,
        nx, ny, nz,
        r: baseDr,
        foreshorten,
        palKey: dPalKey,
        ringIdx: rIdx,
        colIdx: c,
        seed: idx * 1000 + rIdx * 31 + c
      });
    }
  }

  // If showHollow is true, generate inner cavity rim drupelets visible inside the hollow thimble
  if (showHollow) {
    let innerCount = 10;
    let t = -0.52;
    let profR = 0.52;
    for (let c = 0; c < innerCount; c++) {
      let phi = (c / innerCount) * Math.PI * 2;
      let cosphi = Math.cos(phi);
      let sinphi = Math.sin(phi);
      let px = bx + R * (ux * cosphi * profR + vx * sinphi * profR + ax * t * aspect * 0.72);
      let py = by + R * (uy * cosphi * profR + vy * sinphi * profR + ay * t * aspect * 0.72);
      let pz = bz + R * (uz * cosphi * profR + vz * sinphi * profR + az * t * aspect * 0.72);
      innerDrupelets.push({
        x: px,
        y: py,
        z: pz,
        r: R * 0.14
      });
    }
  }

  // Sort drupelets back-to-front by z so front beads overlap rear beads cleanly
  drupelets.sort((a, b) => a.z - b.z);

  return {
    idx,
    x: bx, y: by, z: bz,
    R, aspect,
    ax, ay, az,
    ux, uy, uz,
    vx, vy, vz,
    palKey,
    showHollow,
    hasCalyx,
    layerGroup,
    drupelets,
    innerDrupelets
  };
}

// =============================================================================
// 1. TABLETOP SURFACE & DIRECTIONAL LIGHT
// =============================================================================

function drawTabletopSurface() {
  brush.noStroke();

  // Warm sunlit upper-left glow and deeper warm stone shadow toward bottom-right
  const washes = [
    { x: 250, y: 220, r: 520, col: "#fffbf5", alpha: 75 },
    { x: 920, y: 880, r: 580, col: "#e0d0c1", alpha: 65 },
    { x: 640, y: 680, r: 540, col: "#eadccf", alpha: 45 },
    { x: 1050, y: 420, r: 460, col: "#e3d4c6", alpha: 55 }
  ];

  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.45, 0.2);
  for (let w of washes) {
    brush.fill(w.col, w.alpha);
    brush.circle(w.x, w.y, w.r, 0.25);
  }
  brush.noFill();

  // Subtle directional stone/linen surface texture strokes
  brush.set("2H", "#dccbc0", 0.7);
  for (let i = 0; i < 65; i++) {
    let x1 = random(20, 1180);
    let y1 = random(20, 1180);
    let len = random(60, 190);
    let ang = -25 + random(-8, 8);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }
}

// =============================================================================
// 2. CAST SHADOWS & TRANSLUCENT CAUSTICS ON THE TABLETOP
// =============================================================================

function drawTabletopShadowsAndCaustics(scene) {
  const p = scene.punnet;
  brush.noStroke();

  // A. Punnet cast shadow (shifted down-right along directional light)
  let s1 = p.pt(-1.05, 1.0, 1.0);
  let s2 = p.pt(1.05, 1.0, 1.0);
  let s3 = p.pt(1.05, 1.0, 0.0);
  let s4 = p.pt(-1.05, 1.0, 0.0);
  let shOffX = 68, shOffY = 58;

  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.5, 0.35);
  brush.fill("#113b29", 68);
  brush.beginShape(0.25);
  brush.vertex(s1.x + 15, s1.y + 12);
  brush.vertex(s2.x + shOffX, s2.y + shOffY);
  brush.vertex(s3.x + shOffX + 25, s3.y + shOffY + 15);
  brush.vertex(s4.x + 25, s4.y + 30);
  brush.endShape(true);

  // Translucent emerald-chartreuse light caustic transmitted through the green punnet
  brush.fillBleed(0.48, "out");
  brush.fill("#24b86e", 52);
  brush.beginShape(0.35);
  brush.vertex(s1.x + 30, s1.y + 20);
  brush.vertex(s2.x + 48, s2.y + 42);
  brush.vertex(s3.x + 45, s3.y + 35);
  brush.vertex(s4.x + 35, s4.y + 25);
  brush.endShape(true);

  brush.fill("#68f0a3", 38);
  brush.circle((s1.x + s2.x + s3.x + s4.x) * 0.25 + 32, (s1.y + s2.y + s3.y + s4.y) * 0.25 + 28, 125, 0.3);

  // B. Batched cast shadows under the raspberry heap
  const tableBerries = scene.berries.filter(b => b.z < 92);

  // Pass 1: Soft outer ruby-plum shadow bleed + caustic glow
  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.5, 0.3);
  brush.fill("#8c1138", 40);
  for (let b of tableBerries) {
    let sx = b.x + 38 + b.z * 0.35;
    let sy = b.y + 34 + b.z * 0.32;
    brush.circle(sx, sy, b.R * 1.12, 0.28);
  }

  // Pass 2: Rich damson-wine directional cast shadow
  brush.fillBleed(0.36, "out");
  brush.fill("#45061d", 72);
  for (let b of tableBerries) {
    let sx = b.x + 26 + b.z * 0.22;
    let sy = b.y + 24 + b.z * 0.2;
    brush.circle(sx, sy, b.R * 0.92, 0.24);
  }

  // Pass 3: Core contact occlusion directly beneath each resting berry
  brush.fillBleed(0.22, "out");
  brush.fill("#21010d", 105);
  for (let b of tableBerries) {
    if (b.z < 75) {
      brush.circle(b.x + 12, b.y + 12, b.R * 0.68, 0.18);
    }
  }

  brush.noFill();
}

// =============================================================================
// 3 & 5. GREEN TRANSLUCENT MOULDED PUNNET (BACK/FLOOR & FRONT/RIM)
// =============================================================================

function drawQuadFill(p1, p2, p3, p4, curv = 0.08) {
  brush.beginShape(curv);
  brush.vertex(p1.x, p1.y);
  brush.vertex(p2.x, p2.y);
  brush.vertex(p3.x, p3.y);
  brush.vertex(p4.x, p4.y);
  brush.endShape(true);
}

function drawPunnetBackAndFloor(p) {
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.42, 0.32);

  // 1. Back base wall (w = 0)
  let bTL = p.pt(-1, -1, 0);
  let bTR = p.pt(1, -1, 0);
  let bBR = p.pt(1, 1, 0);
  let bBL = p.pt(-1, 1, 0);
  brush.fill("#0b6e41", 88);
  drawQuadFill(bTL, bTR, bBR, bBL, 0.06);

  // Recessed moulded square panel inside back base
  let rTL = p.pt(-0.68, -0.68, 0.02);
  let rTR = p.pt(0.68, -0.68, 0.02);
  let rBR = p.pt(0.68, 0.68, 0.02);
  let rBL = p.pt(-0.68, 0.68, 0.02);
  brush.fill("#199e5e", 72);
  drawQuadFill(rTL, rTR, rBR, rBL, 0.08);

  // 2. Lower wall resting on tabletop (v = +1, w in [0, 1])
  let fBL = p.pt(-1, 1, 0);
  let fBR = p.pt(1, 1, 0);
  let fFR = p.pt(1, 1, 1);
  let fFL = p.pt(-1, 1, 1);
  brush.fill("#06522f", 95);
  drawQuadFill(fBL, fBR, fFR, fFL, 0.05);

  // 3. Far right wall (u = +1, w in [0, 1])
  let rBTop = p.pt(1, -1, 0);
  let rBBot = p.pt(1, 1, 0);
  let rFBot = p.pt(1, 1, 1);
  let rFTop = p.pt(1, -1, 1);
  brush.fill("#0d7a47", 82);
  drawQuadFill(rBTop, rBBot, rFBot, rFTop, 0.05);

  brush.noFill();

  // Moulded ribs and ventilation slots on the floor & far wall
  for (let i = -3; i <= 3; i++) {
    let u = i * 0.24;
    let p1 = p.pt(u, 1, 0.12);
    let p2 = p.pt(u, 1, 0.88);
    brush.set("plastic_glaze", "#043820", 0.9);
    brush.line(p1.x, p1.y, p2.x, p2.y);
    brush.set("pen", "#5ce69b", 0.7);
    brush.line(p1.x - 2, p1.y - 2, p2.x - 2, p2.y - 2);
  }

  // Recessed base crease outline
  brush.set("rotring", "#043b21", 1.1);
  brush.line(rTL.x, rTL.y, rTR.x, rTR.y);
  brush.line(rTR.x, rTR.y, rBR.x, rBR.y);
  brush.line(rBR.x, rBR.y, rBL.x, rBL.y);
  brush.line(rBL.x, rBL.y, rTL.x, rTL.y);
}

function drawPunnetFrontAndRim(p) {
  brush.noStroke();
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.38, 0.35);

  // 1. Left-facing translucent wall (u = -1, w in [0, 1]) catching the directional light
  let lBTop = p.pt(-1, -1, 0);
  let lBBot = p.pt(-1, 1, 0);
  let lFBot = p.pt(-1, 1, 1);
  let lFTop = p.pt(-1, -1, 1);
  brush.fill("#1fb86c", 78);
  drawQuadFill(lBTop, lBBot, lFBot, lFTop, 0.05);

  // 2. Top-facing translucent wall (v = -1, w in [0, 1]) overlapping interior berries
  let tBL = p.pt(-1, -1, 0);
  let tBR = p.pt(1, -1, 0);
  let tFR = p.pt(1, -1, 1);
  let tFL = p.pt(-1, -1, 1);
  brush.fill("#149958", 84);
  drawQuadFill(tBL, tBR, tFR, tFL, 0.05);

  // Sunlit chartreuse-emerald sheen across upper corner
  let sBL = p.pt(-1, -1, 0.08);
  let sBR = p.pt(-0.15, -1, 0.08);
  let sFR = p.pt(-0.15, -1, 0.92);
  let sFL = p.pt(-1, -1, 0.92);
  brush.fill("#62f0a0", 52);
  drawQuadFill(sBL, sBR, sFR, sFL, 0.06);

  brush.noFill();

  // 3. Moulded structural flutes (ribs) along the top wall (v = -1) & left wall (u = -1)
  const ribPositions = [-0.72, -0.36, 0.0, 0.36, 0.72];
  for (let u of ribPositions) {
    let a = p.pt(u - 0.05, -1, 0.1);
    let b = p.pt(u - 0.05, -1, 0.92);
    let c = p.pt(u + 0.05, -1, 0.92);
    let d = p.pt(u + 0.05, -1, 0.1);

    // Translucent emerald rib body
    brush.set("plastic_glaze", "#085932", 1.1);
    brush.line(d.x, d.y, c.x, c.y);
    brush.set("plastic_glaze", "#72f5ad", 0.95);
    brush.line(a.x, a.y, b.x, b.y);

    // Crisp specular ridge on each moulded flute
    brush.set("rotring", "#e0ffef", 0.85);
    brush.line(a.x, a.y, b.x, b.y);
    brush.set("rotring", "#053d22", 0.75);
    brush.line(d.x, d.y, c.x, c.y);
  }

  for (let v of [-0.6, -0.2, 0.2, 0.6]) {
    let a = p.pt(-1, v, 0.12);
    let b = p.pt(-1, v, 0.92);
    brush.set("plastic_glaze", "#82f7b6", 0.9);
    brush.line(a.x, a.y, b.x, b.y);
    brush.set("rotring", "#084f2c", 0.7);
    brush.line(a.x + 3, a.y + 3, b.x + 3, b.y + 3);
  }

  // 4. Elongated rounded ventilation slots along the corner bevels (w = 0.04..0.18)
  for (let u of [-0.65, -0.22, 0.22, 0.65]) {
    let v1 = p.pt(u - 0.11, -1, 0.03);
    let v2 = p.pt(u + 0.11, -1, 0.03);
    let v3 = p.pt(u + 0.11, -0.82, 0.03);
    let v4 = p.pt(u - 0.11, -0.82, 0.03);
    brush.noStroke();
    brush.wash("#d8ede0", 145);
    drawQuadFill(v1, v2, v3, v4, 0.25);
    brush.noWash();
    brush.set("rotring", "#054024", 0.8);
    brush.line(v1.x, v1.y, v2.x, v2.y);
    brush.line(v3.x, v3.y, v4.x, v4.y);
  }

  // 5. Moulded Double-Lip Rim Flange around the Open Mouth (w = 1.0)
  const innerRim = [
    p.pt(-1.0, -1.0, 1.0),
    p.pt(1.0, -1.0, 1.0),
    p.pt(1.0, 1.0, 1.0),
    p.pt(-1.0, 1.0, 1.0)
  ];
  const outerRim = [
    p.pt(-1.12, -1.12, 1.02),
    p.pt(1.12, -1.12, 1.02),
    p.pt(1.12, 1.12, 1.02),
    p.pt(-1.12, 1.12, 1.02)
  ];

  brush.noStroke();
  brush.fillBleed(0.1, "in");
  // Draw the 4 flange strips around the mouth
  const flangeColors = ["#28cc78", "#0d7d47", "#064d2b", "#38db86"];
  for (let side = 0; side < 4; side++) {
    let nxt = (side + 1) % 4;
    brush.fill(flangeColors[side], 115);
    drawQuadFill(innerRim[side], innerRim[nxt], outerRim[nxt], outerRim[side], 0.04);
  }
  brush.noFill();

  // Crisp moulded rim contours and bright specular highlights
  for (let side = 0; side < 4; side++) {
    let nxt = (side + 1) % 4;
    brush.set("rotring", "#03331c", 1.25);
    brush.line(innerRim[side].x, innerRim[side].y, innerRim[nxt].x, innerRim[nxt].y);
    brush.line(outerRim[side].x, outerRim[side].y, outerRim[nxt].x, outerRim[nxt].y);

    // Bright mint-white highlight on upper/left sunlit flange edges
    if (side === 0 || side === 3) {
      brush.set("silver_hair", "#ffffff", 1.9);
      brush.line(outerRim[side].x, outerRim[side].y, outerRim[nxt].x, outerRim[nxt].y);
      brush.set("pen", "#b5ffd6", 1.1);
      brush.line(innerRim[side].x, innerRim[side].y, innerRim[nxt].x, innerRim[nxt].y);
    }
  }
}

// =============================================================================
// 6. RASPBERRIES: HALOS, BANDHANI DRUPELETS, STIPPLING & SILVER HAIRS
// =============================================================================

function drawInterBerryShadowWashes(berrySlice) {
  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.45, 0.3);
  brush.fill("#26010f", 78);

  for (let b of berrySlice) {
    // Cast a directional shadow onto the berries slightly behind/below-right of this berry
    if (b.z > 55) {
      brush.circle(b.x + 18, b.y + 16, b.R * 0.88, 0.22);
    }
  }
  brush.noFill();
}

function drawBerryBatchHalos(berrySlice) {
  // Batch watercolor fills by palette color for high performance & lush bleeding halos
  brush.noStroke();
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.55, 0.35);

  const byPal = {};
  for (let b of berrySlice) {
    if (!byPal[b.palKey]) byPal[b.palKey] = [];
    byPal[b.palKey].push(b);
  }

  for (let palKey of Object.keys(byPal)) {
    let pal = PALETTES[palKey];
    let group = byPal[palKey];

    // 1. Sunlit upper-left bleeding dye halo
    brush.fill(pal.haloLight, 70);
    for (let b of group) {
      brush.circle(b.x - b.R * 0.16, b.y - b.R * 0.16, b.R * 0.86, 0.32);
    }

    // 2. Saturated midtone core wash
    brush.fill(pal.haloMid, 88);
    for (let b of group) {
      brush.circle(b.x + b.R * 0.04, b.y + b.R * 0.04, b.R * 0.88, 0.28);
    }

    // 3. Deep wine lower-right shadow wash
    brush.fill(pal.haloShadow, 95);
    for (let b of group) {
      brush.circle(b.x + b.R * 0.22, b.y + b.R * 0.22, b.R * 0.72, 0.26);
    }
  }

  brush.noFill();
}

function computeShadowOcclusion(px, py, pz, selfIdx, allBerries) {
  // Check if any other berry lies along the ray from (px, py, pz) toward LIGHT
  let occ = 0;
  for (let i = 0; i < allBerries.length; i++) {
    let other = allBerries[i];
    if (other.idx === selfIdx) continue;
    let dx = other.x - px;
    let dy = other.y - py;
    let dz = other.z - pz;

    // Project onto LIGHT direction
    let proj = dx * LIGHT.x + dy * LIGHT.y + dz * LIGHT.z;
    if (proj <= 8 || proj > 190) continue;

    let perpSq = (dx * dx + dy * dy + dz * dz) - proj * proj;
    let rad = other.R * 0.92;
    if (perpSq < rad * rad) {
      let distFactor = 1.0 - Math.sqrt(perpSq) / rad;
      occ = Math.max(occ, distFactor * 0.78);
    }
  }
  return occ;
}

function drawSingleBerry(berry, allBerries) {
  // 1. If the hollow central receptacle is visible, draw the inner cavity & inner ring first
  if (berry.showHollow) {
    drawHollowReceptacle(berry);
  }

  // 2. Render every visible drupelet as a bandhani tie-dye dot
  for (let d of berry.drupelets) {
    let occ = computeShadowOcclusion(d.x, d.y, d.z, berry.idx, allBerries);
    drawBandhaniDrupelet(d, berry, occ);
  }

  // 3. Render fine silver pistillate hairs catching the light
  drawBerrySilverHairs(berry);

  // 4. If this berry still has its green calyx/pedicel attached, draw it
  if (berry.hasCalyx) {
    drawBerryCalyx(berry);
  }
}

function drawHollowReceptacle(berry) {
  // Center of the base opening (t = -0.68)
  let cx = berry.x - berry.ax * berry.R * 0.45;
  let cy = berry.y - berry.ay * berry.R * 0.45;
  let cavR = berry.R * 0.44;

  // Inner shadowed drupelets lining the cavity walls
  for (let id of berry.innerDrupelets) {
    brush.set("bead_velvet", "#380112", 1.1);
    brush.arc(id.x, id.y, id.r * 0.7, 0, 360);
    brush.set("water_dab", "#700625", 0.85);
    brush.line(id.x - 2, id.y - 2, id.x + 2, id.y + 2);
  }

  // Deep velvety hollow interior
  brush.noStroke();
  brush.fillBleed(0.22, "in");
  brush.fill("#2b010e", 135);
  brush.circle(cx, cy, cavR, 0.2);

  // Warm coral-rose inner receptacle cone shadow
  brush.fill("#8c2335", 95);
  brush.circle(cx + 4, cy + 4, cavR * 0.65, 0.18);

  brush.fill("#e08b7e", 75);
  brush.circle(cx + 7, cy + 6, cavR * 0.34, 0.15);
  brush.noFill();

  // Fine inner texture stipples
  brush.set("micro_stipple", "#1c0008", 0.9);
  brush.arc(cx - 3, cy - 3, cavR * 0.5, 110, 310);
}

function drawBandhaniDrupelet(d, berry, occ) {
  const pal = PALETTES[d.palKey];
  const dr = d.r;

  // Directional lighting on this drupelet (combining berry normal + local bead curvature)
  let rawDot = d.nx * LIGHT.x + d.ny * LIGHT.y + d.nz * LIGHT.z;
  let lightVal = constrain((rawDot + 0.55) / 1.5, 0, 1) * (1.0 - occ * 0.72);

  // Veiled berries inside the translucent green punnet are slightly cooler/dimmer
  if (berry.layerGroup === "inside_punnet") {
    lightVal *= 0.72;
  }

  // --- STAGE A: FAINT DYE HALO BLEEDING INTO THE NEXT ---
  let haloCol = lightVal > 0.58 ? pal.haloLight : (lightVal > 0.28 ? pal.haloMid : pal.haloShadow);
  brush.set("dye_halo", haloCol, (dr / 14) * 1.15);
  brush.line(d.x - dr * 0.18, d.y - dr * 0.14, d.x + dr * 0.18, d.y + dr * 0.14);

  // --- STAGE B: ROUNDED MADDER-RED BEAD & WATERCOLOUR DAB ---
  // 1. Dark wine/claret crevice shadow on the lower-right / outer curve of the bead
  let shadowCol = lightVal > 0.45 ? pal.dabDark : pal.dabDeep;
  brush.set("bead_velvet", shadowCol, (dr / 15) * 0.92);
  brush.arc(d.x + dr * 0.06, d.y + dr * 0.06, dr * 0.78, -25, 165);

  // 2. Plump watercolor dab for the bead body
  let bodyCol = lightVal > 0.62 ? pal.dabLight : (lightVal > 0.32 ? pal.dabMid : pal.dabDark);
  brush.set("water_dab", bodyCol, (dr / 13.5) * 1.18);
  brush.line(d.x - dr * 0.14, d.y - dr * 0.12, d.x + dr * 0.12, d.y + dr * 0.12);

  // Secondary warm subsurface dab on well-lit beads
  if (lightVal > 0.38) {
    let subCol = lightVal > 0.68 ? pal.haloLight : pal.dabLight;
    brush.set("bead_velvet", subCol, (dr / 14) * 0.88);
    brush.line(d.x - dr * 0.2, d.y - dr * 0.18, d.x + dr * 0.04, d.y + dr * 0.04);
  }

  // --- STAGE C: DENSE SPRAY STIPPLING ---
  // Shadow-side stippling
  brush.set("dense_stipple", pal.stippleDark, (dr / 15) * 0.85);
  brush.arc(d.x + dr * 0.12, d.y + dr * 0.12, dr * 0.55, 10, 145);

  // Crown stippling (crimson / madder / coral)
  let stippleCol = lightVal > 0.55 ? pal.stippleLight : pal.stippleMid;
  brush.set("micro_stipple", stippleCol, (dr / 14) * 0.95);
  brush.arc(d.x - dr * 0.08, d.y - dr * 0.08, dr * 0.46, 160, 350);

  // --- STAGE D: BANDHANI TIE-DYE RESIST CORE (WHERE THE HIGHLIGHT SITS) ---
  // Highlight offset toward the upper-left light + slight normal displacement
  let hx = d.x + (LIGHT.x * 0.26 + d.nx * 0.14) * dr;
  let hy = d.y + (LIGHT.y * 0.26 + d.ny * 0.14) * dr;

  // 1. Concentrated dye collar ring immediately surrounding the pinched resist point
  let collarCol = lightVal > 0.45 ? pal.collarLight : pal.collarMid;
  let ringR = dr * (0.31 + 0.08 * lightVal);
  brush.set("bandhani_ring", collarCol, (dr / 15) * 0.82);
  brush.arc(hx, hy, ringR, 0, 360);

  // 2. Pale blush / coral tie-dye resist transition halo
  let blushCol = lightVal > 0.6 ? pal.blushLight : (lightVal > 0.28 ? pal.blushMid : pal.blushShadow);
  let resistScale = (0.45 + 0.55 * lightVal) * (dr / 15);
  brush.set("resist_core", blushCol, resistScale * 1.12);
  // Slight bandhani diamond/pinched stroke
  brush.line(hx - dr * 0.07, hy - dr * 0.04, hx + dr * 0.07, hy + dr * 0.04);

  // 3. Tiny crisp white resist core right at the highlight center
  let coreCol = lightVal > 0.55 ? pal.coreLight : (lightVal > 0.25 ? pal.coreMid : pal.coreShadow);
  let coreWeight = (0.38 + 0.58 * lightVal) * (dr / 15);
  brush.set("resist_core", coreCol, coreWeight * 0.78);
  brush.line(hx - dr * 0.03, hy - dr * 0.02, hx + dr * 0.03, hy + dr * 0.02);

  // On larger sunlit drupelets, add the authentic bandhani pinched 4-cornered resist ring & center eye
  if (dr > 14.5 && lightVal > 0.42) {
    brush.set("pen", "#ffffff", 0.95);
    let sq = dr * 0.13 * (0.7 + 0.3 * lightVal);
    brush.line(hx - sq, hy, hx, hy - sq);
    brush.line(hx, hy - sq, hx + sq, hy);
    brush.line(hx + sq, hy, hx, hy + sq);
    brush.line(hx, hy + sq, hx - sq, hy);

    // Tiny bandhani center dye pin-dot inside the white resist ring on hero beads
    if (dr > 16.2 && lightVal > 0.55 && (d.seed % 3 !== 0)) {
      brush.set("rotring", collarCol, 0.75);
      brush.line(hx, hy, hx + 0.5, hy + 0.5);
    }
  }
}

function drawBerrySilverHairs(berry) {
  // Fine pistillate hairs emerging from drupelet crowns and crevices, catching the light
  for (let d of berry.drupelets) {
    let rawDot = d.nx * LIGHT.x + d.ny * LIGHT.y + d.nz * LIGHT.z;
    let lightVal = constrain((rawDot + 0.55) / 1.5, 0, 1);

    // Outward 2D direction from berry center through drupelet
    let outX = d.x - berry.x;
    let outY = d.y - berry.y;
    let outLen = Math.hypot(outX, outY) || 1;
    outX /= outLen;
    outY /= outLen;

    // Base angle pointing outward from the drupelet crown
    let baseAng = atan2(outY, outX) + (noise(d.seed) - 0.5) * 38;
    let isRim = d.nz < 0.38;
    let hairLen = d.r * (isRim ? 0.92 : 0.62) * (0.8 + 0.4 * noise(d.seed + 7));

    // Start point on the outer slope of the drupelet
    let sx = d.x + outX * d.r * 0.48;
    let sy = d.y + outY * d.r * 0.48;
    let curl = (d.seed % 2 === 0 ? 1 : -1) * (18 + 16 * noise(d.seed + 13));

    let mx = sx + cos(baseAng + curl * 0.4) * (hairLen * 0.55);
    let my = sy + sin(baseAng + curl * 0.4) * (hairLen * 0.55);
    let ex = sx + cos(baseAng + curl) * hairLen;
    let ey = sy + sin(baseAng + curl) * hairLen;

    // Choose silver tone based on light & rim grazing angle
    let hairCol;
    let weightMult;
    if (lightVal > 0.62 || (isRim && lightVal > 0.35)) {
      hairCol = "#f7fbff";
      weightMult = 1.15;
    } else if (lightVal > 0.32) {
      hairCol = "#cfdbe8";
      weightMult = 0.92;
    } else {
      hairCol = "#8a96a6";
      weightMult = 0.75;
    }

    brush.set("silver_hair", hairCol, weightMult);
    brush.spline([[sx, sy, 1.0], [mx, my, 0.7], [ex, ey, 0.2]], 0.5);

    // Rim-lit drupelets get a second delicate silver hair filament
    if (isRim && lightVal > 0.4) {
      let ang2 = baseAng - curl * 0.8;
      let ex2 = sx + cos(ang2) * (hairLen * 0.82);
      let ey2 = sy + sin(ang2) * (hairLen * 0.82);
      brush.set("rotring", "#eae4dc", 0.45);
      brush.line(sx, sy, ex2, ey2);
    }
  }
}

function drawBerryCalyx(berry) {
  // Star-shaped green botanical calyx & stem stub attached to the base of select berries
  let cx = berry.x - berry.ax * berry.R * 0.72;
  let cy = berry.y - berry.ay * berry.R * 0.72;

  // 5 pointed sepals arching over the base drupelets
  const sepalAngles = [-145, -95, -45, 15, 165];
  brush.noStroke();
  brush.fillBleed(0.18, "out");

  for (let i = 0; i < sepalAngles.length; i++) {
    let ang = sepalAngles[i];
    let len = berry.R * (0.68 + 0.18 * (i % 2));
    let tipX = cx + cos(ang) * len;
    let tipY = cy + sin(ang) * len;
    let perpX = -sin(ang) * berry.R * 0.16;
    let perpY = cos(ang) * berry.R * 0.16;

    brush.fill(i < 3 ? "#4db844" : "#1e6e24", 155);
    brush.beginShape(0.35);
    brush.vertex(cx - perpX * 0.6, cy - perpY * 0.6);
    brush.vertex(cx + cos(ang) * len * 0.45 + perpX, cy + sin(ang) * len * 0.45 + perpY);
    brush.vertex(tipX, tipY);
    brush.vertex(cx + cos(ang) * len * 0.45 - perpX, cy + sin(ang) * len * 0.45 - perpY);
    brush.endShape(true);

    brush.noFill();
    brush.set("pen", "#104515", 0.8);
    brush.line(cx, cy, tipX, tipY);
    brush.set("silver_hair", "#c8f7b0", 0.8);
    brush.line(cx, cy, (cx + tipX) * 0.5, (cy + tipY) * 0.5);
  }

  // Woody green stem pedicel
  let stemAng = -115;
  let stX = cx + cos(stemAng) * berry.R * 0.52;
  let stY = cy + sin(stemAng) * berry.R * 0.52;
  brush.set("water_dab", "#3a8c2f", 0.9);
  brush.line(cx, cy, stX, stY);
  brush.set("rotring", "#8ae868", 0.85);
  brush.line(cx - 2, cy - 2, stX - 2, stY - 2);
}

// =============================================================================
// 7. LOOSE DETACHED DRUPELETS & BLEEDING JUICE STAINS
// =============================================================================

function drawLooseDrupelets(looseList) {
  // Batch bleeding juice halos on the tabletop first
  brush.noStroke();
  brush.fillBleed(0.55, "out");
  brush.fillTexture(0.6, 0.4);

  for (let ld of looseList) {
    let pal = PALETTES[ld.pal];
    // Cast shadow
    brush.fill("#360315", 85);
    brush.circle(ld.x + 8, ld.y + 7, ld.r * 1.15, 0.25);
    if (ld.twin) {
      brush.circle(ld.x + ld.r * 1.25 + 8, ld.y + 6 + 7, ld.r * 1.05, 0.25);
    }

    // Bleeding madder/coral dye puddle on the tabletop
    brush.fill(pal.haloLight, 65);
    brush.circle(ld.x - 2, ld.y + 2, ld.r * 1.65, 0.38);
  }
  brush.noFill();

  // Render each detached drupelet as a jewel-like bandhani bead
  for (let i = 0; i < looseList.length; i++) {
    let ld = looseList[i];
    let dummyBerry = { x: ld.x, y: ld.y + 10, layerGroup: "main_heap" };

    drawBandhaniDrupelet({
      x: ld.x,
      y: ld.y,
      z: 20,
      nx: -0.35,
      ny: -0.35,
      nz: 0.87,
      r: ld.r,
      foreshorten: 1.0,
      palKey: ld.pal,
      seed: 9000 + i * 17
    }, dummyBerry, 0);

    // Fine silver hair on the loose drupelet
    brush.set("silver_hair", "#f2f7fc", 1.1);
    brush.spline([
      [ld.x + ld.r * 0.4, ld.y - ld.r * 0.3, 1.0],
      [ld.x + ld.r * 0.85, ld.y - ld.r * 0.65, 0.6],
      [ld.x + ld.r * 1.2, ld.y - ld.r * 0.5, 0.15]
    ], 0.5);

    if (ld.twin) {
      drawBandhaniDrupelet({
        x: ld.x + ld.r * 1.22,
        y: ld.y + 5,
        z: 18,
        nx: -0.25,
        ny: -0.3,
        nz: 0.92,
        r: ld.r * 0.92,
        foreshorten: 1.0,
        palKey: ld.pal,
        seed: 9500 + i * 23
      }, dummyBerry, 0.1);
    }
  }
}

