function drawFinalAccents(scene) {
  // Extra-crisp silver-white rim hairs and bandhani resist sparkles on the closest foreground berries
  const frontBerries = scene.berries.slice(-10);
  for (let b of frontBerries) {
    for (let k = 0; k < b.drupelets.length; k += 4) {
      let d = b.drupelets[k];
      let rawDot = d.nx * LIGHT.x + d.ny * LIGHT.y + d.nz * LIGHT.z;
      if (rawDot > 0.35) {
        let hx = d.x + (LIGHT.x * 0.26 + d.nx * 0.14) * d.r;
        let hy = d.y + (LIGHT.y * 0.26 + d.ny * 0.14) * d.r;
        brush.set("resist_core", "#ffffff", 0.55);
        brush.line(hx - 0.8, hy - 0.8, hx + 0.8, hy + 0.8);
      }
    }
  }
}

