// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function tableHorizonY(x) {
  let t = constrain(x / width, 0, 1);
  return lerp(TABLE_Y_LEFT, TABLE_Y_RIGHT, t) + sin(t * 180) * 18;
}

// Maps local wedge coordinates (where Apex is at (0, 0) and bottom arc is around y = R * yScale)
// into canvas coordinates with coherent hand-cut cloth irregularity
function wedgeLocalToWorld(w, lx, ly, wobbleAmt = 2.2) {
  let pivotY = w.R * 0.52 * w.yScale;
  let dy = ly - pivotY;
  let ca = cos(w.rot);
  let sa = sin(w.rot);
  let wx = w.cx + lx * ca - dy * sa;
  let wy = w.cy + lx * sa + dy * ca;

  if (wobbleAmt > 0) {
    let n1 = noise(wx * 0.014 + w.id * 37, wy * 0.014 + 19) - 0.5;
    let n2 = noise(wx * 0.014 + 101, wy * 0.014 + w.id * 53) - 0.5;
    wx += n1 * wobbleAmt * 2.2;
    wy += n2 * wobbleAmt * 2.2;
  }
  return [wx, wy];
}

// Exact Euclidean-inset circular sector in local coordinates (Apex at (0,0), scaled vertically by yScale)
function getSectorPolygon(w, dSide, rInner, wobbleAmt = 2.2, cornerRound = 0.08, scallopFreq = 0, scallopAmp = 0) {
  let sinH = sin(w.halfAngle);
  let s = dSide / sinH;
  if (s >= rInner - 8) return [];

  let alphaL = 90 + w.halfAngle;
  let alphaR = 90 - w.halfAngle;

  // Ray from (0, s) at angle alphaL intersecting circle x^2 + y^2 = rInner^2
  let bTerm = s * sin(alphaL);
  let disc = bTerm * bTerm - (s * s - rInner * rInner);
  if (disc <= 0) return [];
  let rRayMax = -bTerm + sqrt(disc);

  // Corner points in unscaled circle coordinates
  let xL = rRayMax * cos(alphaL);
  let yL = s + rRayMax * sin(alphaL);
  let xR = rRayMax * cos(alphaR);
  let yR = s + rRayMax * sin(alphaR);

  let angL = atan2(yL, xL);
  let angR = atan2(yR, xR);

  let pts = [];
  let stepsSide = 16;
  let stepsArc = 34;

  // Left cut edge: from near shifted apex (0, s) down to left arc corner
  for (let i = 1; i < stepsSide; i++) {
    let t = map(i, 0, stepsSide, cornerRound, 1 - cornerRound);
    let rRay = t * rRayMax;
    let lx = rRay * cos(alphaL);
    let ly = (s + rRay * sin(alphaL)) * w.yScale;
    pts.push(wedgeLocalToWorld(w, lx, ly, wobbleAmt));
  }

  // Bottom arc: from angL down to angR
  for (let i = 0; i <= stepsArc; i++) {
    let t = i / stepsArc;
    let ang = lerp(angL, angR, t);
    let sc = scallopFreq > 0 ? sin(t * 180 * scallopFreq) * scallopAmp : 0;
    let rad = rInner + sc;
    let lx = rad * cos(ang);
    let ly = rad * sin(ang) * w.yScale;
    pts.push(wedgeLocalToWorld(w, lx, ly, wobbleAmt));
  }

  // Right cut edge: from right arc corner up to near shifted apex (0, s)
  for (let i = 1; i < stepsSide; i++) {
    let t = map(i, 0, stepsSide, 1 - cornerRound, cornerRound);
    let rRay = t * rRayMax;
    let lx = rRay * cos(alphaR);
    let ly = (s + rRay * sin(alphaR)) * w.yScale;
    pts.push(wedgeLocalToWorld(w, lx, ly, wobbleAmt));
  }

  // Top rounded apex fillet
  let apexPull = rRayMax * cornerRound * 0.45;
  let lxApex = 0;
  let lyApex = (s + apexPull) * w.yScale;
  pts.push(wedgeLocalToWorld(w, lxApex, lyApex, wobbleAmt));

  return pts;
}

// Arc strip polygon between rOuter and rInner (for rind and white pith contour bands)
function getArcBandPolygon(w, rOuter, rInner, trimDeg = 0, wobbleAmt = 2.0, serrateInner = 0) {
  let alphaL = 90 + w.halfAngle - trimDeg;
  let alphaR = 90 - w.halfAngle + trimDeg;
  let steps = 40;
  let pts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = lerp(alphaL, alphaR, t);
    let lx = rOuter * cos(ang);
    let ly = rOuter * sin(ang) * w.yScale;
    pts.push(wedgeLocalToWorld(w, lx, ly, wobbleAmt));
  }

  let innerSteps = serrateInner > 0 ? steps * 2 : steps;
  for (let i = innerSteps; i >= 0; i--) {
    let t = i / innerSteps;
    let ang = lerp(alphaL, alphaR, t);
    let tooth = serrateInner > 0 ? (i % 2 === 0 ? serrateInner : -serrateInner * 0.6) : 0;
    let rad = rInner + tooth;
    let lx = rad * cos(ang);
    let ly = rad * sin(ang) * w.yScale;
    pts.push(wedgeLocalToWorld(w, lx, ly, wobbleAmt * 0.8));
  }

  return pts;
}

function drawPoly(pts, washCol, washAlpha = 255, strokeBrush = null, strokeCol = "#080a10", strokeW = 1, curvature = 0.08) {
  if (!pts || pts.length < 3) return;
  brush.noFill();
  brush.noHatch();
  if (washCol) {
    brush.wash(washCol, washAlpha);
  } else {
    brush.noWash();
  }
  if (strokeBrush) {
    brush.set(strokeBrush, strokeCol, strokeW);
  } else {
    brush.noStroke();
  }
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
  brush.noStroke();
}

// Adds bold marker texture strokes inside a polygon using hatching
function drawMarkerFillPass(pts, col, angleDeg, spacing = 11, weight = 1.1) {
  if (!pts || pts.length < 3) return;
  brush.noWash();
  brush.noFill();
  brush.noStroke();
  brush.hatchStyle("molaMarker", col, weight);
  brush.hatch(spacing, angleDeg, { rand: 0.04, continuous: true });
  brush.beginShape(0.05);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

// Draws crisp, slightly uneven outline with hand-stitched reverse-appliqué thread ticks
function drawStitchedContour(pts, closed = true, outlineCol = "#080a10", outlineW = 0.95, stitchCol = null, stitchSpacing = 13, stitchLen = 4.5) {
  if (!pts || pts.length < 2) return;
  brush.noWash();
  brush.noFill();
  brush.noHatch();

  let path = pts.slice();
  if (closed) path.push(pts[0]);

  brush.set("rotring", outlineCol, outlineW);
  brush.spline(path, 0.15);

  if (stitchCol) {
    brush.set("pen", stitchCol, outlineW * 0.72);
    let accum = 0;
    for (let i = 0; i < path.length - 1; i++) {
      let p0 = path[i];
      let p1 = path[i + 1];
      let dx = p1[0] - p0[0];
      let dy = p1[1] - p0[1];
      let segLen = sqrt(dx * dx + dy * dy);
      if (segLen < 0.5) continue;
      let ux = dx / segLen;
      let uy = dy / segLen;
      let nx = -uy;
      let ny = ux;

      let d = stitchSpacing - accum;
      while (d <= segLen) {
        let sx = p0[0] + ux * d;
        let sy = p0[1] + uy * d;
        let jitterA = random(-0.25, 0.25);
        let jLen = stitchLen * random(0.8, 1.22);
        let tx = nx * cos(jitterA * 40) - ny * sin(jitterA * 40);
        let ty = nx * sin(jitterA * 40) + ny * cos(jitterA * 40);
        brush.line(
          sx - tx * jLen * 0.35,
          sy - ty * jLen * 0.35,
          sx + tx * jLen * 0.85,
          sy + ty * jLen * 0.85
        );
        d += stitchSpacing * random(0.85, 1.18);
      }
      accum = segLen - (d - stitchSpacing);
    }
  }
  brush.noStroke();
}

// Draws a rounded pill-shaped Guna mola slit (tasba) with nested contrasting cloth rim and stitches
function drawMolaSlit(cx, cy, len, wid, angleDeg, outerRimCol, innerCol, stitchCol = null) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  let nx = -sa;
  let ny = ca;

  let buildPill = (L, W) => {
    let p = [];
    let hl = max(2, L * 0.5 - W * 0.5);
    let r = W * 0.5;
    for (let a = -90; a <= 90; a += 45) {
      let lx = hl + r * cos(a);
      let ly = r * sin(a);
      p.push([cx + lx * ca + ly * nx, cy + lx * sa + ly * ny]);
    }
    for (let a = 90; a <= 270; a += 45) {
      let lx = -hl + r * cos(a);
      let ly = r * sin(a);
      p.push([cx + lx * ca + ly * nx, cy + lx * sa + ly * ny]);
    }
    return p;
  };

  let outerPts = buildPill(len, wid);
  drawPoly(outerPts, outerRimCol, 255, "rotring", PAL.jetBlack, 0.85, 0.2);

  if (innerCol && wid > 7) {
    let innerPts = buildPill(len - 6, wid - 5.5);
    drawPoly(innerPts, innerCol, 255, "pen", PAL.jetBlack, 0.65, 0.2);
  }

  if (stitchCol) {
    drawStitchedContour(outerPts, true, PAL.jetBlack, 0.75, stitchCol, 11, 3.8);
  }
}

// ============================================================================
// 1. DEEP ORANGE MOLA BACKGROUND & DARK TABLETOP
// ============================================================================

function minWedgeDist(x, y) {
  let bestD = 9999;
  let bestAng = 0;
  for (let w of wedges) {
    let dx = x - w.cx;
    let dy = y - w.cy;
    let d = sqrt(dx * dx + dy * dy) - w.R * 0.74;
    if (d < bestD) {
      bestD = d;
      bestAng = atan2(dy, dx) + 90;
    }
  }
  return { d: bestD, ang: bestAng };
}

function drawMolaBackgroundAndTabletop() {
  // Upper Deep Orange Backdrop Plane
  let bgPoly = [[0, 0], [width, 0], [width, TABLE_Y_RIGHT + 45], [0, TABLE_Y_LEFT + 45]];
  drawPoly(bgPoly, PAL.bgOrangeDeep, 255);
  drawMarkerFillPass(bgPoly, PAL.bgOrangeMid, -12, 16, 1.4);

  // Nested orange contour waves in the upper backdrop
  for (let band = 0; band < 6; band++) {
    let yBase = 65 + band * 72;
    let wavePts = [];
    for (let x = -20; x <= width + 20; x += 40) {
      let info = minWedgeDist(x, yBase);
      let pushUp = constrain(map(info.d, -40, 260, -55, 0), -65, 0);
      let wy = yBase + pushUp + sin(x * 0.45 + band * 40) * 14;
      wavePts.push([x, wy]);
    }
    // Thin dark crimson-orange & black mola seam lines across backdrop
    brush.set("rotring", PAL.jetBlack, 1.0);
    brush.spline(wavePts, 0.25);
    brush.set("pen", PAL.bgOrangeBright, 0.8);
    let offsetWave = wavePts.map(p => [p[0], p[1] - 4]);
    brush.spline(offsetWave, 0.25);
  }

  // Echoing Guna Mola Slits (Tasba) across the Deep Orange Background
  let coolUnderColors = [PAL.chanTeal, PAL.chanCobalt, PAL.leafGreen, PAL.chalkIce, PAL.chanCyan, PAL.melonRed];
  let gridStepX = 76;
  let gridStepY = 34;

  for (let row = 0; row < 15; row++) {
    let y0 = 26 + row * gridStepY;
    let xOffset = (row % 2) * (gridStepX * 0.5);
    for (let col = -1; col < 17; col++) {
      let x = col * gridStepX + xOffset + random(-8, 8);
      let y = y0 + random(-4, 4);
      if (y > tableHorizonY(x) - 24) continue;

      let info = minWedgeDist(x, y);
      // Skip slits that are deep inside the wedges to save render budget
      if (info.d < -60) continue;

      // Slit angle echoes the nearest wedge contour
      let slitAng = info.ang + sin(x * 0.3 + y * 0.3) * 12;
      let slitLen = random(46, 68);
      let slitWid = random(11, 15.5);
      let cInner = coolUnderColors[(row * 3 + col + 7) % coolUnderColors.length];
      let cOuter = (row + col) % 2 === 0 ? PAL.jetBlack : PAL.bgOrangeBright;
      let innerFill = cOuter === PAL.jetBlack ? cInner : PAL.jetBlack;

      drawMolaSlit(x, y, slitLen, slitWid, slitAng, cOuter, innerFill, PAL.bgOrangeBright);
    }
  }

  // Dark Tabletop Surface (Lower Plane)
  let tablePoly = [];
  for (let x = 0; x <= width; x += 40) {
    tablePoly.push([x, tableHorizonY(x)]);
  }
  tablePoly.push([width, height], [0, height]);
  drawPoly(tablePoly, PAL.tableDark1, 255);
  drawMarkerFillPass(tablePoly, PAL.tableDark2, 4, 15, 1.35);

  // Multi-layered Guna Mola Border Band along the Tabletop Horizon
  let borderColors = [PAL.jetBlack, PAL.chanTeal, PAL.jetBlack, PAL.bgOrangeBright, PAL.chalkIce, PAL.jetBlack];
  let borderOffsets = [-16, -11, -5, 0, 6, 12];
  for (let b = 0; b < borderColors.length - 1; b++) {
    let strip = [];
    for (let x = 0; x <= width; x += 35) {
      strip.push([x, tableHorizonY(x) + borderOffsets[b]]);
    }
    for (let x = width; x >= 0; x -= 35) {
      strip.push([x, tableHorizonY(x) + borderOffsets[b + 1]]);
    }
    drawPoly(strip, borderColors[b], 255, "rotring", PAL.jetBlack, 0.85, 0.1);
  }

  // Subtle echoing slits on the dark tabletop
  for (let row = 0; row < 11; row++) {
    let ty = 555 + row * 58;
    for (let col = 0; col < 13; col++) {
      let tx = 45 + col * 92 + (row % 2) * 44 + random(-10, 10);
      let info = minWedgeDist(tx, ty);
      if (info.d < -40) continue;
      let tAng = constrain(info.ang * 0.25, -22, 22);
      let c1 = (row + col) % 3 === 0 ? PAL.chanCobalt : PAL.tableDark3;
      let c2 = (row + col) % 4 === 0 ? PAL.bgOrangeDeep : PAL.chanTeal;
      drawMolaSlit(tx, ty, random(52, 78), random(9, 12.5), tAng, PAL.jetBlack, (row + col) % 2 === 0 ? c1 : c2, PAL.tableDark3);
    }
  }
}

// ============================================================================
// 2. TABLETOP CAST SHADOWS & WET JUICE PUDDLES
// ============================================================================

function drawTabletopShadowsAndPuddles() {
  for (let w of wedges) {
    // Deep cast shadow polygon underneath each thick wedge
    let shPts = [];
    let alphaL = 90 + w.halfAngle;
    let alphaR = 90 - w.halfAngle;
    for (let i = 0; i <= 28; i++) {
      let ang = lerp(alphaL, alphaR, i / 28);
      let r = w.R * 1.03;
      let p = wedgeLocalToWorld(w, r * cos(ang), r * sin(ang) * w.yScale, 1.5);
      shPts.push([p[0] + w.extX + 24, p[1] + w.extY + 34]);
    }
    let apexP = wedgeLocalToWorld(w, 0, w.R * 0.25 * w.yScale, 1.0);
    shPts.push([apexP[0] + w.extX + 15, apexP[1] + w.extY + 25]);

    drawPoly(shPts, PAL.tableShadow, 235);

    // Secondary cool indigo-black shadow rim
    brush.fill(PAL.tableShadow, 140);
    brush.fillBleed(0.25, "out");
    brush.noStroke();
    brush.beginShape(0.2);
    for (let p of shPts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    brush.noFill();
  }

  // Glossy spilled watermelon juice puddles on the dark tabletop
  let puddles = [
    { x: 310, y: 895, rx: 68, ry: 22 },
    { x: 620, y: 1095, rx: 95, ry: 26 },
    { x: 920, y: 865, rx: 62, ry: 20 },
    { x: 445, y: 1040, rx: 48, ry: 16 }
  ];

  for (let pd of puddles) {
    let pPts = [];
    for (let a = 0; a < 360; a += 20) {
      let radScale = 1 + 0.18 * sin(a * 3 + pd.x) + 0.1 * cos(a * 2);
      pPts.push([
        pd.x + pd.rx * radScale * cos(a),
        pd.y + pd.ry * radScale * sin(a)
      ]);
    }
    drawPoly(pPts, PAL.crystalRuby, 230, "rotring", PAL.jetBlack, 0.9, 0.3);

    let innerPts = pPts.map(pt => [
      lerp(pd.x, pt[0], 0.72),
      lerp(pd.y - 2, pt[1], 0.68)
    ]);
    drawPoly(innerPts, PAL.melonRed, 210, null, null, 0, 0.3);

    // Razor-sharp wet specular reflection on the puddle
    brush.set("pen", PAL.specWhite, 1.3);
    brush.arc(pd.x - pd.rx * 0.15, pd.y - pd.ry * 0.2, pd.rx * 0.45, 200, 315);
    brush.set("pen", PAL.specIce, 0.9);
    brush.line(pd.x + pd.rx * 0.2, pd.y - pd.ry * 0.32, pd.x + pd.rx * 0.42, pd.y - pd.ry * 0.25);
    brush.noStroke();
  }
}

// ============================================================================
// 3. THICK WATERMELON WEDGES IN GUNA MOLA REVERSE APPLIQUÉ
// ============================================================================

function drawThickMolaWedge(w) {
  // ---- A. 3D THICKNESS SLAB (RIND UNDERSIDE & SIDE CUT PLANE) ----
  drawWedge3DThickness(w);

  // ---- B. JET BLACK MOLA BASE LAYER (UNDER-FABRIC OF FRONT FACE) ----
  let fullBasePts = getSectorPolygon(w, 0, w.R, 2.2, 0.04);
  drawPoly(fullBasePts, PAL.jetBlack, 255, "rotring", PAL.jetBlack, 1.4, 0.08);

  // ---- C. RIND & WHITE PITH NESTED CONTOUR BANDS (ALONG CURVED ARC) ----
  drawRindAndPithBands(w);

  // ---- D. WATERMELON RED FLESH NESTED SECTOR BANDS & CHANNELS ----
  drawRedFleshMolaBands(w);

  // ---- E. GUNA MOLA SEED CORRIDORS & WET SEED GLOSS ----
  drawWedgeSeedsAndSlits(w);

  // ---- F. SUGARY CRYSTALLINE GRAIN ACROSS FLESH & PITH ----
  drawSugaryCrystallineGrain(w);

  // ---- G. HYPERREAL 3D JUICE BEADS ACROSS ALL FILLS ----
  drawWedgeJuiceBeads(w);
}

function drawWedge3DThickness(w) {
  let alphaL = 90 + w.halfAngle;
  let alphaR = 90 - w.halfAngle;
  let steps = 36;

  // 1. Optional 3D Side Cut Plane (gives tangible slab thickness to the cut face)
  if (w.showLeftCutSide || w.showRightCutSide) {
    let ang = w.showLeftCutSide ? alphaL : alphaR;
    let pApex = wedgeLocalToWorld(w, 0, 0, 1.5);
    let pCorner = wedgeLocalToWorld(w, w.R * cos(ang), w.R * sin(ang) * w.yScale, 1.5);
    let pPith = wedgeLocalToWorld(w, w.R * 0.72 * cos(ang), w.R * 0.72 * sin(ang) * w.yScale, 1.5);
    let pRind = wedgeLocalToWorld(w, w.R * 0.85 * cos(ang), w.R * 0.85 * sin(ang) * w.yScale, 1.5);

    // Side Red Flesh bevel
    let sideFlesh = [
      pApex,
      pPith,
      [pPith[0] + w.extX, pPith[1] + w.extY],
      [pApex[0] + w.extX * 0.7, pApex[1] + w.extY * 0.7]
    ];
    drawPoly(sideFlesh, PAL.melonRedDeep, 255, "rotring", PAL.jetBlack, 1.1, 0.05);
    drawStitchedContour(sideFlesh, true, PAL.jetBlack, 0.9, PAL.melonRose, 13, 4);

    // Side White Pith bevel
    let sidePith = [
      pPith,
      pRind,
      [pRind[0] + w.extX, pRind[1] + w.extY],
      [pPith[0] + w.extX, pPith[1] + w.extY]
    ];
    drawPoly(sidePith, PAL.chalkShadow, 255, "rotring", PAL.jetBlack, 1.0, 0.05);

    // Side Green Rind bevel
    let sideRind = [
      pRind,
      pCorner,
      [pCorner[0] + w.extX, pCorner[1] + w.extY],
      [pRind[0] + w.extX, pRind[1] + w.extY]
    ];
    drawPoly(sideRind, PAL.leafGreenDark, 255, "rotring", PAL.jetBlack, 1.1, 0.05);
  }

  // 2. Thick Curved Outer Rind Underside (3D Cylindrical Rind with Mola Stripes)
  let rindSlab = [];
  for (let i = 0; i <= steps; i++) {
    let ang = lerp(alphaL, alphaR, i / steps);
    rindSlab.push(wedgeLocalToWorld(w, w.R * cos(ang), w.R * sin(ang) * w.yScale, 1.8));
  }
  for (let i = steps; i >= 0; i--) {
    let ang = lerp(alphaL, alphaR, i / steps);
    let p = wedgeLocalToWorld(w, w.R * cos(ang), w.R * sin(ang) * w.yScale, 1.8);
    rindSlab.push([p[0] + w.extX, p[1] + w.extY]);
  }

  drawPoly(rindSlab, PAL.leafGreenDark, 255, "rotring", PAL.jetBlack, 1.3, 0.08);
  drawMarkerFillPass(rindSlab, PAL.leafGreen, w.rot + 90, 12, 1.2);

  // Mola Reverse-Appliqué Rind Stripes along the 3D Underside
  let stripeCount = 11;
  for (let s = 0; s < stripeCount; s++) {
    let t0 = (s + 0.18) / stripeCount;
    let t1 = (s + 0.72) / stripeCount;
    let a0 = lerp(alphaL, alphaR, t0);
    let a1 = lerp(alphaL, alphaR, t1);
    let aMid = (a0 + a1) * 0.5;

    let pTop0 = wedgeLocalToWorld(w, w.R * cos(a0), w.R * sin(a0) * w.yScale, 1.0);
    let pTop1 = wedgeLocalToWorld(w, w.R * cos(a1), w.R * sin(a1) * w.yScale, 1.0);
    let pBot1 = [pTop1[0] + w.extX * 0.88, pTop1[1] + w.extY * 0.88];
    let pBot0 = [pTop0[0] + w.extX * 0.88, pTop0[1] + w.extY * 0.88];

    let patch = [
      [lerp(pTop0[0], pBot0[0], 0.15), lerp(pTop0[1], pBot0[1], 0.15)],
      [lerp(pTop1[0], pBot1[0], 0.15), lerp(pTop1[1], pBot1[1], 0.15)],
      pBot1,
      pBot0
    ];
    let stripeCol = s % 2 === 0 ? PAL.leafGreen : PAL.chanTeal;
    drawPoly(patch, PAL.jetBlack, 255, null, null, 0, 0.1);

    let innerPatch = patch.map(pt => [
      lerp(pt[0], (pTop0[0] + pBot1[0]) * 0.5, 0.18),
      lerp(pt[1], (pTop0[1] + pBot1[1]) * 0.5, 0.18)
    ]);
    drawPoly(innerPatch, stripeCol, 255, "rotring", PAL.jetBlack, 0.8, 0.1);
  }

  drawStitchedContour(rindSlab, true, PAL.jetBlack, 1.1, PAL.leafMint, 14, 4.2);
}

function drawRindAndPithBands(w) {
  let R = w.R;

  // Band 1: Outer Leaf Green Rind (0.915 R to 0.992 R)
  let greenBand1 = getArcBandPolygon(w, R * 0.992, R * 0.915, 0.4, 2.0, 0);
  drawPoly(greenBand1, PAL.leafGreen, 255);
  drawMarkerFillPass(greenBand1, PAL.leafGreenDark, w.rot, 10, 1.1);
  drawStitchedContour(greenBand1, true, PAL.jetBlack, 0.95, PAL.leafMint, 13, 4.0);

  // Slits inside Outer Leaf Green Rind
  let alphaL = 90 + w.halfAngle - 3;
  let alphaR = 90 - w.halfAngle + 3;
  let numRindSlits = 12;
  for (let i = 0; i < numRindSlits; i++) {
    let t = (i + 0.5) / numRindSlits;
    let ang = lerp(alphaL, alphaR, t);
    let rMid = R * 0.953;
    let p = wedgeLocalToWorld(w, rMid * cos(ang), rMid * sin(ang) * w.yScale, 0.8);
    let tangentAng = w.rot + (ang - 90);
    let cReveal = i % 2 === 0 ? PAL.leafMint : PAL.chalkWhite;
    drawMolaSlit(p[0], p[1], 32, 9.5, tangentAng, PAL.jetBlack, cReveal, null);
  }

  // Contrasting Channel 1 between Green Bands (0.896 R to 0.913 R) -> Reveals Deep Orange / Cyan
  let chanRind = getArcBandPolygon(w, R * 0.912, R * 0.896, 0.6, 1.6, 0);
  drawPoly(chanRind, PAL.bgOrangeBright, 255, "rotring", PAL.jetBlack, 0.85, 0.08);

  // Band 2: Inner Bright Leaf Green Rind (0.840 R to 0.893 R)
  let greenBand2 = getArcBandPolygon(w, R * 0.893, R * 0.840, 0.7, 2.0, 0);
  drawPoly(greenBand2, PAL.leafGreenBright, 255);
  drawMarkerFillPass(greenBand2, PAL.leafGreen, w.rot + 12, 10, 1.0);
  drawStitchedContour(greenBand2, true, PAL.jetBlack, 0.9, PAL.chalkWhite, 14, 3.8);

  // Continuous undulating Mola Channel inside Band 2 revealing Jet Black & Cool Teal
  let waveArc = getArcBandPolygon(w, R * 0.873, R * 0.858, 1.8, 1.5, 3.2);
  drawPoly(waveArc, PAL.chanTeal, 255, "rotring", PAL.jetBlack, 0.8, 0.05);

  // Band 3: Outer Chalk White Pith Band (0.778 R to 0.828 R)
  let pithBand1 = getArcBandPolygon(w, R * 0.828, R * 0.778, 0.8, 2.0, 0);
  drawPoly(pithBand1, PAL.chalkWhite, 255);
  drawMarkerFillPass(pithBand1, PAL.chalkIce, w.rot, 9, 1.0);
  drawStitchedContour(pithBand1, true, PAL.jetBlack, 0.9, PAL.chanTeal, 12, 3.8);

  // Contrasting Pith Channel (0.760 R to 0.775 R) -> Reveals Cool Cyan-Teal
  let chanPith = getArcBandPolygon(w, R * 0.775, R * 0.760, 1.0, 1.5, 0);
  drawPoly(chanPith, PAL.chanCyan, 255, "rotring", PAL.jetBlack, 0.85, 0.08);

  // Band 4: Inner Chalk White Pith Band with Serrated Mola Teeth (0.708 R to 0.757 R)
  let pithBand2 = getArcBandPolygon(w, R * 0.757, R * 0.708, 1.0, 1.8, 5.5);
  drawPoly(pithBand2, PAL.chalkIce, 255);
  drawStitchedContour(pithBand2, true, PAL.jetBlack, 0.95, PAL.melonRed, 11, 4.0);
}

function drawRedFleshMolaBands(w) {
  let R = w.R;

  // Painter's algorithm from outermost Red Flesh Sector inward to the Apex Core,
  // leaving thin cut channels of Jet Black + Contrasting Cloth between each nested band!

  // 1. Outermost Watermelon Red Flesh Band (dSide: 0 -> 16, r: 0.696 R -> 0.635 R)
  let red1 = getSectorPolygon(w, 2, R * 0.696, 2.2, 0.05);
  drawPoly(red1, PAL.melonRed, 255);
  drawMarkerFillPass(red1, PAL.melonRedDeep, w.rot + 35, 11, 1.15);
  drawStitchedContour(red1, true, PAL.jetBlack, 1.05, PAL.chalkWhite, 12, 4.2);

  // Channel 1 (dSide: 16 -> 27, r: 0.635 R -> 0.602 R): Jet Black rim + Chalk White & Cool Teal reveal
  let ch1Black = getSectorPolygon(w, 16, R * 0.635, 1.8, 0.06);
  drawPoly(ch1Black, PAL.jetBlack, 255);
  let ch1Color = getSectorPolygon(w, 19.5, R * 0.625, 1.6, 0.06);
  drawPoly(ch1Color, PAL.chalkWhite, 255, "rotring", PAL.jetBlack, 0.75, 0.08);
  let ch1InnerBlack = getSectorPolygon(w, 24.5, R * 0.610, 1.8, 0.06);
  drawPoly(ch1InnerBlack, PAL.jetBlack, 255);

  // 2. Second Watermelon Red Flesh Band — Main Seed Corridor (dSide: 28 -> 55, r: 0.600 R -> 0.482 R)
  let red2 = getSectorPolygon(w, 28, R * 0.600, 2.0, 0.07);
  drawPoly(red2, PAL.melonRedBright, 255);
  drawMarkerFillPass(red2, PAL.melonRed, w.rot - 30, 11, 1.1);
  drawStitchedContour(red2, true, PAL.jetBlack, 0.95, PAL.melonRose, 12, 4.0);

  // Channel 2 (dSide: 55 -> 66, r: 0.482 R -> 0.448 R) with Scalloped Arc echoing the Seeds!
  let ch2Black = getSectorPolygon(w, 55, R * 0.482, 1.8, 0.08, w.seedCountOuter, 5.5);
  drawPoly(ch2Black, PAL.jetBlack, 255);
  let ch2Color = getSectorPolygon(w, 58.5, R * 0.472, 1.6, 0.08, w.seedCountOuter, 5.0);
  drawPoly(ch2Color, PAL.leafGreenBright, 255, "rotring", PAL.jetBlack, 0.75, 0.08);
  let ch2InnerBlack = getSectorPolygon(w, 63, R * 0.457, 1.8, 0.08, w.seedCountOuter, 4.5);
  drawPoly(ch2InnerBlack, PAL.jetBlack, 255);

  // 3. Third Watermelon Red Flesh Band — Inner Seed Corridor (dSide: 66.5 -> 88, r: 0.446 R -> 0.352 R)
  let red3 = getSectorPolygon(w, 66.5, R * 0.446, 1.8, 0.09, w.seedCountOuter, 4.0);
  drawPoly(red3, PAL.melonRed, 255);
  drawMarkerFillPass(red3, PAL.melonRedDeep, w.rot + 15, 10, 1.05);
  drawStitchedContour(red3, true, PAL.jetBlack, 0.9, PAL.chalkWhite, 11, 3.8);

  // Channel 3 (dSide: 88 -> 97, r: 0.352 R -> 0.322 R): Reveals Deep Orange / Cool Cyan
  let ch3Black = getSectorPolygon(w, 88, R * 0.352, 1.5, 0.1);
  drawPoly(ch3Black, PAL.jetBlack, 255);
  let ch3Color = getSectorPolygon(w, 91, R * 0.342, 1.4, 0.1);
  drawPoly(ch3Color, PAL.chanCyan, 255, "rotring", PAL.jetBlack, 0.7, 0.08);
  let ch3InnerBlack = getSectorPolygon(w, 95, R * 0.329, 1.5, 0.1);
  drawPoly(ch3InnerBlack, PAL.jetBlack, 255);

  // 4. Innermost Heart Core Sector (dSide: 98, r: 0.320 R)
  let redCore = getSectorPolygon(w, 98, R * 0.320, 1.5, 0.12);
  drawPoly(redCore, PAL.melonRedBright, 255);
  drawStitchedContour(redCore, true, PAL.jetBlack, 0.85, PAL.chalkWhite, 10, 3.5);

  // Tiny center mola jewel slit inside the heart core
  let pCore = wedgeLocalToWorld(w, 0, R * 0.255 * w.yScale, 0.5);
  drawMolaSlit(pCore[0], pCore[1], 28, 10, w.rot + 90, PAL.jetBlack, PAL.chalkWhite, PAL.melonRose);
}

function drawWedgeSeedsAndSlits(w) {
  let R = w.R;

  // 1. Slits along Outermost Red Band 1
  let alphaL1 = 90 + w.halfAngle - 7;
  let alphaR1 = 90 - w.halfAngle + 7;
  let slitsBand1 = 9;
  for (let i = 0; i < slitsBand1; i++) {
    let t = (i + 0.5) / slitsBand1;
    let ang = lerp(alphaL1, alphaR1, t);
    let rMid = R * 0.665;
    let p = wedgeLocalToWorld(w, rMid * cos(ang), rMid * sin(ang) * w.yScale, 0.8);
    let tang = w.rot + (ang - 90);
    let col = i % 2 === 0 ? PAL.chalkWhite : PAL.chanTeal;
    drawMolaSlit(p[0], p[1], 28, 8.5, tang, PAL.jetBlack, col, null);
  }

  // 2. Outer Seed Corridor (Red Band 2, around r = 0.542 R)
  let alphaL2 = 90 + w.halfAngle - 13;
  let alphaR2 = 90 - w.halfAngle + 13;
  let nOuter = w.seedCountOuter;
  for (let i = 0; i < nOuter; i++) {
    let t = (i + 0.5) / nOuter;
    let ang = lerp(alphaL2, alphaR2, t);
    let rSeed = R * 0.542;
    let p = wedgeLocalToWorld(w, rSeed * cos(ang), rSeed * sin(ang) * w.yScale, 0.6);
    let radialAng = w.rot + (ang - 90) + 90;
    let haloCol = i % 2 === 0 ? PAL.chalkWhite : PAL.bgOrangeBright;
    drawMolaSeedMotif(p[0], p[1], 19, 11.5, radialAng, haloCol);

    // Radial mola slit between seeds
    if (i < nOuter - 1) {
      let angMid = lerp(alphaL2, alphaR2, (i + 1) / nOuter);
      let pSlit = wedgeLocalToWorld(w, rSeed * cos(angMid), rSeed * sin(angMid) * w.yScale, 0.6);
      let rAng = w.rot + (angMid - 90) + 90;
      drawMolaSlit(pSlit[0], pSlit[1], 24, 7.5, rAng, PAL.jetBlack, PAL.leafMint, null);
    }
  }

  // 3. Inner Seed Corridor (Red Band 3, around r = 0.398 R)
  let alphaL3 = 90 + w.halfAngle - 20;
  let alphaR3 = 90 - w.halfAngle + 20;
  let nInner = w.seedCountInner;
  for (let i = 0; i < nInner; i++) {
    let t = (i + 0.5) / nInner;
    let ang = lerp(alphaL3, alphaR3, t);
    let rSeed = R * 0.398;
    let p = wedgeLocalToWorld(w, rSeed * cos(ang), rSeed * sin(ang) * w.yScale, 0.5);
    let radialAng = w.rot + (ang - 90) + 90;
    let haloCol = i % 2 === 0 ? PAL.chanCyan : PAL.chalkWhite;
    drawMolaSeedMotif(p[0], p[1], 16, 10, radialAng, haloCol);
  }

  // 4. Lateral cut-edge slits running along the left and right edges of Red Band 1 & 2
  for (let side of [-1, 1]) {
    let ang = 90 + side * (w.halfAngle - 3.5);
    for (let k = 0; k < 5; k++) {
      let rPos = map(k, 0, 4, R * 0.22, R * 0.58);
      let p = wedgeLocalToWorld(w, rPos * cos(ang), rPos * sin(ang) * w.yScale, 0.6);
      let edgeAng = w.rot + side * w.halfAngle + 90;
      drawMolaSlit(p[0], p[1], 25, 7.5, edgeAng, PAL.jetBlack, k % 2 === 0 ? PAL.chalkWhite : PAL.bgOrangeBright, null);
    }
  }
}

// Draws a single Guna Mola reverse-appliqué seed pocket with wet hyperreal seed gloss
function drawMolaSeedMotif(cx, cy, len, wid, angleDeg, haloCol) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  let nx = -sa;
  let ny = ca;

  // Teardrop/almond generator pointing toward the wedge apex (-ca, -sa)
  let buildTeardrop = (L, W) => {
    let pts = [];
    for (let a = 0; a < 360; a += 24) {
      // Teardrop profile: narrower at -90 (apex end), plumper at +90 (rind end)
      let taper = 0.78 + 0.26 * sin(a);
      let lx = L * cos(a);
      let ly = W * sin(a) * taper;
      pts.push([cx + lx * ca + ly * nx, cy + lx * sa + ly * ny]);
    }
    return pts;
  };

  // 1. Outer Black Mola Cut Channel
  let outerBlack = buildTeardrop(len + 6.5, wid + 5.5);
  drawPoly(outerBlack, PAL.jetBlack, 255);

  // 2. Contrasting Cloth Halo (Chalk White, Cyan, or Orange)
  let haloPts = buildTeardrop(len + 3.8, wid + 3.0);
  drawPoly(haloPts, haloCol, 255, "rotring", PAL.jetBlack, 0.75, 0.2);

  // 3. Inner Dark Crimson Cavity Meniscus
  let cavityPts = buildTeardrop(len + 1.0, wid + 0.8);
  drawPoly(cavityPts, PAL.crystalRuby, 255);

  // 4. Jet Black Seed Body
  let seedPts = buildTeardrop(len - 1.5, wid - 1.5);
  drawPoly(seedPts, PAL.jetBlack, 255, "rotring", PAL.jetBlack, 0.8, 0.25);

  // 5. Cool Indigo Sheen on Seed Body
  let sheenPts = buildTeardrop(len * 0.62, wid * 0.52);
  drawPoly(sheenPts, PAL.tableDark3, 210, null, null, 0, 0.25);

  // 6. Hyperreal Wet Seed Gloss (Razor-sharp curved white highlight + pinpoint glint)
  let h1x = cx - ca * (len * 0.25) - nx * (wid * 0.22);
  let h1y = cy - sa * (len * 0.25) - ny * (wid * 0.22);
  let h2x = cx + ca * (len * 0.22) - nx * (wid * 0.18);
  let h2y = cy + sa * (len * 0.22) - ny * (wid * 0.18);
  let hMidX = (h1x + h2x) * 0.5 - nx * (wid * 0.14);
  let hMidY = (h1y + h2y) * 0.5 - ny * (wid * 0.14);

  brush.set("pen", PAL.specIce, 1.5);
  brush.spline([[h1x, h1y], [hMidX, hMidY], [h2x, h2y]], 0.4);
  brush.set("rotring", PAL.specWhite, 1.15);
  brush.line(h1x, h1y, hMidX, hMidY);

  // Wet meniscus highlight on the opposite rim
  let m1x = cx + ca * (len * 0.35) + nx * (wid * 0.32);
  let m1y = cy + sa * (len * 0.35) + ny * (wid * 0.32);
  brush.set("pen", PAL.melonRose, 0.9);
  brush.line(m1x, m1y, m1x - ca * 4, m1y - sa * 4);
  brush.noStroke();
}

// ============================================================================
// 4. SUGARY CRYSTALLINE GRAIN OVER FLESH & PITH
// ============================================================================

function drawSugaryCrystallineGrain(w) {
  let R = w.R;
  let alphaL = 90 + w.halfAngle - 2;
  let alphaR = 90 - w.halfAngle + 2;

  // 1. Fine spray stipple & custom crystal facets across the Watermelon Red Flesh
  let crystalPoints = 220;
  for (let i = 0; i < crystalPoints; i++) {
    // Bias distribution slightly toward the juicy apex & middle flesh
    let u = random(-0.92, 0.92);
    let v = pow(random(0.06, 0.69), 0.85);
    let ang = 90 - u * (w.halfAngle - 3);
    let rad = v * R;
    let p = wedgeLocalToWorld(w, rad * cos(ang), rad * sin(ang) * w.yScale, 0);

    // Draw micro-cellular crystal facet cluster
    let rChoice = random();
    if (rChoice < 0.38) {
      brush.set("crystal", PAL.specWhite, random(0.65, 1.25));
    } else if (rChoice < 0.72) {
      brush.set("crystal", PAL.crystalPink, random(0.7, 1.3));
    } else {
      brush.set("crystal", PAL.crystalRuby, random(0.7, 1.2));
    }
    let jitter = random(3, 7);
    let a = random(360);
    brush.line(p[0], p[1], p[0] + cos(a) * jitter, p[1] + sin(a) * jitter);
  }

  // 2. Pinpoint icy sugar glints (crisp high-contrast sparkles on red flesh & white pith)
  brush.set("rotring", PAL.specWhite, 0.85);
  for (let i = 0; i < 95; i++) {
    let u = random(-0.94, 0.94);
    let v = random(0.05, 0.82);
    let ang = 90 - u * (w.halfAngle - 2);
    let rad = v * R;
    let p = wedgeLocalToWorld(w, rad * cos(ang), rad * sin(ang) * w.yScale, 0);
    brush.line(p[0], p[1], p[0] + 1.8, p[1] + 1.2);
  }

  // 3. Cellular frost grain along the White Pith Band
  brush.set("cpencil", PAL.chalkShadow, 0.9);
  for (let i = 0; i < 45; i++) {
    let t = random(0.03, 0.97);
    let ang = lerp(alphaL, alphaR, t);
    let rad = random(R * 0.715, R * 0.825);
    let p = wedgeLocalToWorld(w, rad * cos(ang), rad * sin(ang) * w.yScale, 0);
    brush.line(p[0] - 2, p[1] - 2, p[0] + 2, p[1] + 2);
  }
  brush.noStroke();
}

// ============================================================================
// 5. HYPERREAL 3D JUICE BEADS (DROPLETS WITH CAUSTICS & SPECULARS)
// ============================================================================

function drawHyperrealJuiceBead(x, y, r, surfaceType = "red") {
  // Light comes from upper-left (-50 deg); shadow and caustic project to bottom-right (+0.45r, +0.45r)
  let shadowCol = PAL.crystalRuby;
  let causticCol = PAL.melonRose;
  let bodyCol = PAL.melonRed;
  let crescentCol = PAL.melonRedDeep;

  if (surfaceType === "green") {
    shadowCol = "#032617";
    causticCol = PAL.leafMint;
    bodyCol = PAL.leafGreen;
    crescentCol = PAL.leafGreenDark;
  } else if (surfaceType === "white") {
    shadowCol = "#6b8c99";
    causticCol = PAL.specWhite;
    bodyCol = PAL.chalkIce;
    crescentCol = PAL.chalkShadow;
  } else if (surfaceType === "table") {
    shadowCol = PAL.tableShadow;
    causticCol = PAL.melonRedBright;
    bodyCol = PAL.melonRedDeep;
    crescentCol = PAL.jetBlack;
  }

  let buildCircle = (cx, cy, rad, squash = 1.0, rotA = 35) => {
    let pts = [];
    let ca = cos(rotA);
    let sa = sin(rotA);
    for (let a = 0; a < 360; a += 30) {
      let lx = rad * cos(a);
      let ly = rad * sin(a) * squash;
      pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
    }
    return pts;
  };

  // 1. Cast Shadow on bottom-right
  let shPts = buildCircle(x + r * 0.42, y + r * 0.44, r * 0.95, 0.85, 40);
  drawPoly(shPts, shadowCol, 225);

  // 2. Refracted Caustic Glow inside the cast shadow (signature of hyperreal water droplets!)
  let caustPts = buildCircle(x + r * 0.28, y + r * 0.30, r * 0.62, 0.78, 40);
  drawPoly(caustPts, causticCol, 240);

  // 3. Droplet Dome Base
  let domePts = buildCircle(x, y, r, 0.94, -35);
  drawPoly(domePts, bodyCol, 235, "pen", shadowCol, 0.65, 0.25);

  // 4. Upper-Left Internal Fresnel Darkening Crescent
  let darkPts = buildCircle(x - r * 0.16, y - r * 0.16, r * 0.72, 0.85, -45);
  drawPoly(darkPts, crescentCol, 215);

  // 5. Lower-Right Internal Luminous Refraction
  let glowPts = buildCircle(x + r * 0.18, y + r * 0.18, r * 0.55, 0.75, -45);
  drawPoly(glowPts, causticCol, 230);

  // 6. Crisp Primary Specular Highlight at Upper-Left (-0.34r, -0.34r)
  let specPts = buildCircle(x - r * 0.32, y - r * 0.32, max(1.8, r * 0.32), 0.65, -45);
  drawPoly(specPts, PAL.specWhite, 255);

  // Extra razor-sharp pinpoint glint & secondary rim bounce arc
  brush.set("rotring", PAL.specWhite, max(0.8, r * 0.12));
  brush.line(x - r * 0.38, y - r * 0.36, x - r * 0.22, y - r * 0.24);

  if (r > 5.5) {
    brush.set("pen", PAL.specIce, 0.75);
    brush.arc(x, y, r * 0.82, 20, 80);
  }
  brush.noStroke();
}

function drawWedgeJuiceBeads(w) {
  let R = w.R;

  // 1. Plump Juice Beads on the Watermelon Red Flesh & Black Channels
  let redDrops = 14;
  for (let i = 0; i < redDrops; i++) {
