// Hyperreal Outsider-Art Tortoise on Brown Kraft Cardboard
// Rendered with p5.js 2.x and p5.brush

const W = 1200;
const H = 1200;

// Shared edge cache so adjacent shell scutes share identical organic suture curves
const sharedEdgeCache = new Map();

async function setup() {
  createCanvas(W, H, WEBGL);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Register custom waxy crayon brush before scaling
  brush.add("crayon", {
    type: "default",
    weight: 2.1,
    scatter: 0.32,
    sharpness: 0.42,
    grain: 15,
    opacity: 205,
    spacing: 0.16,
    pressure: [0.85, 1.2, 0.85],
    rotate: "natural",
    noise: 0.75
  });

  brush.scaleBrushes(3);
}

function draw() {
  translate(-width / 2, -height / 2);

  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();

  // 1. Brown Kraft Cardboard Ground (corrugated ribs + wood-pulp fibers)
  drawKraftCardboard();

  // 2. Dense Surrounding Ground: Repeated Lettuce Leaves & Dandelions
  drawBotanicalGround(false);

  // 3. Tortoise Ground Shadows, Far Foreleg & Tail
  drawTortoiseUnderShadow();
  drawFarForeleg();
  drawTail();

  // 4. Huge Tortoise Shell: Plastron Bridge & Carapace Scutes with Concentric Waxy Rings
  drawCarapaceAndPlastron();

  // 5. Hind Leg (emerges from rear shell cavity)
  drawHindLeg();

  // 6. Leathery Neck & Head (hundreds of individually outlined felt-tip scales)
  drawNeckAndHead();

  // 7. Foreground Armored Foreleg (thick overlapping megascales & 5 heavy claws)
  drawForegroundForeleg();

  // 8. A few foreground botanical accents near the claws + Wobbly Hand-Ruled Border
  drawBotanicalGround(true);
  drawWobblyBorder();

  noLoop();
}

// ============================================================================
// GEOMETRY & SHARED SUTURE HELPERS
// ============================================================================

function ptKey(p) {
  return `${Math.round(p[0] * 10)}_${Math.round(p[1] * 10)}`;
}

function getSharedSubdividedEdge(p1, p2, steps = 6, wobbleAmp = 2.8) {
  const k1 = ptKey(p1);
  const k2 = ptKey(p2);
  const forward = k1 < k2;
  const key = forward ? `${k1}|${k2}` : `${k2}|${k1}`;

  if (!sharedEdgeCache.has(key)) {
    const a = forward ? p1 : p2;
    const b = forward ? p2 : p1;
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len;
    const ny = dx / len;

    const pts = [];
    const seed = (a[0] * 0.13 + a[1] * 0.29 + b[0] * 0.17 + b[1] * 0.31);
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const env = Math.sin(t * 180);
      const nVal = (noise(seed + t * 2.4, seed * 0.7) - 0.5) * 2.0;
      const offset = env * wobbleAmp * nVal;
      pts.push([
        a[0] + dx * t + nx * offset,
        a[1] + dy * t + ny * offset
      ]);
    }
    sharedEdgeCache.set(key, pts);
  }

  const cached = sharedEdgeCache.get(key);
  if (forward) {
    return cached.slice(0, -1);
  } else {
    return cached.slice().reverse().slice(0, -1);
  }
}

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function polyCentroid(pts) {
  let sx = 0, sy = 0;
  for (let p of pts) {
    sx += p[0];
    sy += p[1];
  }
  return [sx / pts.length, sy / pts.length];
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1];
    const xj = poly[j][0], yj = poly[j][1];
    const intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-6) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function distToEllipse(x, y, cx, cy, rx, ry, rotDeg = 0) {
  const rad = -rotDeg * Math.PI / 180;
  const dx = x - cx;
  const dy = y - cy;
  const lx = dx * Math.cos(rad) - dy * Math.sin(rad);
  const ly = dx * Math.sin(rad) + dy * Math.cos(rad);
  return Math.hypot(lx / rx, ly / ry);
}

function isInsideTortoiseZone(x, y, pad = 1.0) {
  // Main carapace dome
  if (distToEllipse(x, y, 668, 515, 385 * pad, 290 * pad, 3) < 1.0) return true;
  // Plastron & belly
  if (distToEllipse(x, y, 635, 745, 240 * pad, 85 * pad, 0) < 1.0) return true;
  // Head & neck
  if (distToEllipse(x, y, 232, 605, 142 * pad, 85 * pad, -14) < 1.0) return true;
  // Foreground left foreleg
  if (distToEllipse(x, y, 345, 825, 96 * pad, 145 * pad, 14) < 1.0) return true;
  // Far right foreleg
  if (distToEllipse(x, y, 228, 790, 62 * pad, 105 * pad, 10) < 1.0) return true;
  // Hind left leg
  if (distToEllipse(x, y, 922, 825, 95 * pad, 135 * pad, -12) < 1.0) return true;
  // Tail
  if (distToEllipse(x, y, 1042, 718, 58 * pad, 42 * pad, 22) < 1.0) return true;
  return false;
}

// ============================================================================
// 1. KRAFT CARDBOARD SURFACE
// ============================================================================

function drawKraftCardboard() {
  // Base warm brown kraft paper tone
  background("#926e47");

  // Corrugated cardboard horizontal fluting lines (alternating shadow & highlight ribs)
  for (let y = 8; y < H; y += 8.5) {
    const n = noise(y * 0.03);
    const wave = (noise(y * 0.015, 10) - 0.5) * 3;
    // Darker flute trough
    brush.set("charcoal", n > 0.5 ? "#785735" : "#805e3b", 0.55 + n * 0.25);
    brush.line(4, y + wave, W - 4, y - wave * 0.7);

    // Lighter flute crown
    brush.set("cpencil", "#a9855c", 0.45);
    brush.line(4, y + 3.8 + wave * 0.5, W - 4, y + 3.8 - wave * 0.4);
  }

  // Subtle vertical corrugation pressure lines & cardboard creases
  for (let x = 25; x < W; x += 28) {
    if (random() < 0.65) {
      brush.set("2H", "#7d5b38", random(0.3, 0.55));
      brush.line(x + random(-4, 4), 10, x + random(-4, 4), H - 10);
    }
  }

  // Raw wood-pulp fibers and recycled kraft flecks across the board
  for (let i = 0; i < 650; i++) {
    const fx = random(12, W - 12);
    const fy = random(12, H - 12);
    const ang = random(360);
    const len = random(4, 18);
    const col = random(["#634527", "#755331", "#ad8a62", "#bfa07a", "#4f361d"]);
    brush.set("2B", col, random(0.35, 0.75));
    brush.line(
      fx,
      fy,
      fx + cos(ang) * len,
      fy + sin(ang) * len
    );
  }
}

// ============================================================================
// 2. DENSE BOTANICAL GROUND: LETTUCE LEAVES & DANDELIONS
// ============================================================================

function drawBotanicalGround(foregroundPass = false) {
  if (!foregroundPass) {
    // Generate packed sites around the tortoise inside the hand-ruled border
    const lettuceSites = [];
    const dandelionLeafSites = [];
    const flowerSites = [];
    const puffSites = [];

    // 1. Place Romaine / Frilly Lettuce Leaves around the field
    for (let attempt = 0; attempt < 900 && lettuceSites.length < 32; attempt++) {
      const x = random(95, W - 95);
      const y = random(95, H - 95);
      if (isInsideTortoiseZone(x, y, 0.90)) continue;

      let tooClose = false;
      for (let s of lettuceSites) {
        if (dist(x, y, s.x, s.y) < 118) {
          tooClose = true;
          break;
        }
      }
      if (!tooClose) {
        // Angle generally points away from or tangent to tortoise center
        const baseAng = atan2(y - 580, x - 610) + random(-55, 55);
        lettuceSites.push({
          x,
          y,
          ang: baseAng,
          len: random(115, 168),
          wid: random(68, 98),
          variant: floor(random(3))
        });
      }
    }

    for (let s of lettuceSites) {
      drawLettuceLeaf(s.x, s.y, s.ang, s.len, s.wid, s.variant);
    }

    // 2. Place Jagged Dandelion Leaves ("Dent-de-lion") in the gaps
    for (let attempt = 0; attempt < 900 && dandelionLeafSites.length < 38; attempt++) {
      const x = random(85, W - 85);
      const y = random(85, H - 85);
      if (isInsideTortoiseZone(x, y, 0.92)) continue;

      let tooClose = false;
      for (let s of dandelionLeafSites) {
        if (dist(x, y, s.x, s.y) < 88) {
          tooClose = true;
          break;
        }
      }
      if (!tooClose) {
        dandelionLeafSites.push({
          x,
          y,
          ang: random(360),
          len: random(85, 135)
        });
      }
    }

    for (let s of dandelionLeafSites) {
      drawDandelionLeaf(s.x, s.y, s.ang, s.len);
    }

    // 3. Place Golden Dandelion Flower Heads & Seed Puffballs
    for (let attempt = 0; attempt < 1000 && flowerSites.length < 28; attempt++) {
      const x = random(92, W - 92);
      const y = random(92, H - 92);
      if (isInsideTortoiseZone(x, y, 0.96)) continue;

      let tooClose = false;
      for (let s of flowerSites) {
        if (dist(x, y, s.x, s.y) < 92) {
          tooClose = true;
          break;
        }
      }
      if (!tooClose) {
        flowerSites.push({
          x,
          y,
          r: random(30, 48),
          isPuff: flowerSites.length % 5 === 4
        });
      }
    }

    for (let f of flowerSites) {
      if (f.isPuff) {
        drawDandelionPuff(f.x, f.y, f.r * 0.95);
      } else {
        drawDandelionFlower(f.x, f.y, f.r);
      }
    }
  } else {
    // Foreground snacks right near the tortoise's mouth and claws
    drawLettuceLeaf(142, 712, 155, 112, 66, 0);
    drawDandelionLeaf(455, 925, -18, 105);
    drawDandelionLeaf(770, 915, -155, 102);
    drawDandelionFlower(195, 928, 36);
    drawDandelionFlower(505, 912, 34);
    drawDandelionFlower(795, 925, 35);
  }
}

function drawLettuceLeaf(cx, cy, angleDeg, len, wid, variant = 0) {
  push();
  translate(cx, cy);
  rotate(angleDeg);

  const halfL = len * 0.5;
  const outlinePts = [];
  const numSteps = 28;

  // Build frilly, ruffled romaine contour from stalk base (-halfL) to broad apex (+halfL)
  for (let side of [-1, 1]) {
    const startIdx = side === 1 ? 0 : numSteps;
    const endIdx = side === 1 ? numSteps : 0;
    const stepDir = side === 1 ? 1 : -1;

    for (let i = startIdx; side === 1 ? i <= endIdx : i >= endIdx; i += stepDir) {
      const t = i / numSteps; // 0 = cut stalk, 1 = ruffled tip
      const x = -halfL + t * len;
      // Spatulate romaine envelope: narrow stem base, wide bulbous ruffled top
      const env = t < 0.18
        ? (0.14 + t * 1.1)
        : Math.sin(Math.pow(t, 0.72) * 168) * 1.05;
      const ruffle = t > 0.15
        ? (Math.sin(t * 950 + variant * 70 + side * 40) * 0.16 +
           Math.cos(t * 1750 + side * 90) * 0.09)
        : 0;
      const y = side * wid * 0.5 * Math.max(0.06, env + ruffle);
      outlinePts.push([x, y]);
    }
  }

  // Waxy crayon leaf blade ribs (leaving kraft grain peeking between strokes)
  const bladeCols = ["#385917", "#4f7a21", "#6c9e2d", "#8fc240", "#b3db5e"];
  for (let i = 3; i < numSteps - 1; i++) {
    const t = i / numSteps;
    const xBase = -halfL + t * len;
    const env = t < 0.18 ? (0.14 + t * 1.1) : Math.sin(Math.pow(t, 0.72) * 168);
    const maxY = wid * 0.48 * env;

    for (let side of [-1, 1]) {
      const colIdx = constrain(floor(t * 4.2 + (side === -1 ? 0.6 : 0)), 0, bladeCols.length - 1);
      brush.set("crayon", bladeCols[colIdx], 1.15);
      brush.line(
        xBase - len * 0.04,
        side * maxY * 0.12,
        xBase + len * 0.05,
        side * maxY * 0.94
      );

      // Darker olive-viridian fold shadow between ruffles
      if (i % 2 === 0 && t > 0.25) {
        brush.set("cpencil", "#243b0e", 0.9);
        brush.line(
          xBase,
          side * maxY * 0.35,
          xBase + len * 0.04,
          side * maxY * 0.88
        );
      }
      // Bright chartreuse-cream highlight on outer ruffle crests
      if (i % 2 === 1 && t > 0.35) {
        brush.set("crayon", "#d2eb78", 0.85);
        brush.line(
          xBase + len * 0.02,
          side * maxY * 0.68,
          xBase + len * 0.05,
          side * maxY * 0.95
        );
      }
    }
  }

  // Crisp, fleshy pale cream-green central midrib (wider at base, tapering to tip)
  for (let s = -2; s <= 2; s++) {
    const col = Math.abs(s) <= 1 ? "#f4f7d7" : "#cde38a";
    brush.set("crayon", col, 1.05);
    brush.line(-halfL + 4, s * 2.1, halfL * 0.82, s * 0.35);
  }
  // Oxidized pinkish-tan cut stem scar at base
  brush.set("crayon", "#c97a53", 1.1);
  brush.line(-halfL + 2, -5, -halfL + 2, 5);

  // Branching lateral cream veins + fine dark felt-tip vein outlines
  for (let v = 0.24; v <= 0.84; v += 0.13) {
    const vx = -halfL + v * len;
    const reach = wid * 0.42 * Math.sin(Math.pow(v, 0.72) * 165);
    for (let side of [-1, 1]) {
      const pts = [
        [vx, side * 1.8],
        [vx + len * 0.06, side * reach * 0.48],
        [vx + len * 0.11, side * reach * 0.82]
      ];
      brush.set("crayon", "#e9f2c2", 0.8);
      brush.spline(pts, 0.35);
      brush.set("rotring", "#1d2b0d", 0.45);
      brush.spline(pts, 0.35);
    }
  }

  // Obsessive felt-tip outline around every ruffle of the lettuce leaf
  brush.set("rotring", "#121a09", 0.78);
  for (let i = 0; i < outlinePts.length; i++) {
    const p1 = outlinePts[i];
    const p2 = outlinePts[(i + 1) % outlinePts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  pop();
}

function drawDandelionLeaf(cx, cy, angleDeg, len) {
  push();
  translate(cx, cy);
  rotate(angleDeg);

  const halfL = len * 0.5;
  const numLobes = 4;
  const ptsLeft = [[-halfL, -2]];
  const ptsRight = [[-halfL, 2]];

  // Construct jagged runcinate ("lion's tooth") lobes pointing slightly backward
  for (let k = 0; k < numLobes; k++) {
    const t0 = 0.12 + k * 0.20;
    const tPeak = t0 + 0.11;
    const tNotch = t0 + 0.18;
    const lobeW = (12 + k * 5.5) * (len / 110);
    const notchW = (3.5 + k * 1.2) * (len / 110);

    // Backward-angled tooth tip + deep V-notch
    ptsLeft.push([-halfL + tPeak * len, -lobeW]);
    ptsLeft.push([-halfL + (tPeak - 0.03) * len, -lobeW * 0.75]);
    ptsLeft.push([-halfL + tNotch * len, -notchW]);

    ptsRight.push([-halfL + tPeak * len, lobeW]);
    ptsRight.push([-halfL + (tPeak - 0.03) * len, lobeW * 0.75]);
    ptsRight.push([-halfL + tNotch * len, notchW]);

    // Waxy olive/viridian crayon fill inside each tooth lobe
    const xNotch0 = -halfL + t0 * len;
    const xPeak = -halfL + tPeak * len;
    brush.set("crayon", k % 2 === 0 ? "#3c5e19" : "#567d24", 1.15);
    brush.line(xNotch0, 0, xPeak, -lobeW * 0.88);
    brush.line(xNotch0, 0, xPeak, lobeW * 0.88);
    brush.set("cpencil", "#7da636", 0.85);
    brush.line(xNotch0 + 4, 0, xPeak - 2, -lobeW * 0.65);
    brush.line(xNotch0 + 4, 0, xPeak - 2, lobeW * 0.65);
  }

  // Spearhead terminal lobe
  ptsLeft.push([halfL * 0.78, -14 * (len / 110)]);
  ptsLeft.push([halfL, 0]);
  ptsRight.push([halfL * 0.78, 14 * (len / 110)]);
  ptsRight.push([halfL, 0]);

  brush.set("crayon", "#4b701f", 1.2);
  brush.line(halfL * 0.55, 0, halfL * 0.82, -10 * (len / 110));
  brush.line(halfL * 0.55, 0, halfL * 0.82, 10 * (len / 110));

  // Pale cream-chartreuse central midvein
  brush.set("crayon", "#dfeb9d", 0.95);
  brush.line(-halfL, 0, halfL * 0.92, 0);

  // Crisp black felt-tip outline
  brush.set("rotring", "#111708", 0.72);
  for (let i = 0; i < ptsLeft.length - 1; i++) {
    brush.line(ptsLeft[i][0], ptsLeft[i][1], ptsLeft[i + 1][0], ptsLeft[i + 1][1]);
  }
  for (let i = 0; i < ptsRight.length - 1; i++) {
    brush.line(ptsRight[i][0], ptsRight[i][1], ptsRight[i + 1][0], ptsRight[i + 1][1]);
  }

  pop();
}

function drawDandelionFlower(cx, cy, radius) {
  // Dark shadow halo on cardboard under the flower head
  brush.set("charcoal", "#4a3319", 1.1);
  brush.circle(cx + 2, cy + 3, radius * 0.92, 0.25);

  // 3 Concentric tiers of strap-shaped florets, each individually outlined in felt-tip
  const tiers = [
    { count: 28, rIn: radius * 0.28, rOut: radius * 1.02, fill: "#ffbe0b", hi: "#ffe14d", w: 3.4 },
    { count: 22, rIn: radius * 0.18, rOut: radius * 0.74, fill: "#ffd629", hi: "#fff48f", w: 3.0 },
    { count: 16, rIn: radius * 0.06, rOut: radius * 0.44, fill: "#e07b00", hi: "#ffba19", w: 2.5 }
  ];

  for (let tIdx = 0; tIdx < tiers.length; tIdx++) {
    const tier = tiers[tIdx];
    const stepAng = 360 / tier.count;
    for (let i = 0; i < tier.count; i++) {
      const ang = i * stepAng + tIdx * 8 + random(-2.2, 2.2);
      const r0 = tier.rIn;
      const r1 = tier.rOut * random(0.93, 1.05);
      const ca = cos(ang), sa = sin(ang);
      const nx = -sa * tier.w, ny = ca * tier.w;

      const x0 = cx + ca * r0, y0 = cy + sa * r0;
      const x1 = cx + ca * r1, y1 = cy + sa * r1;

      // Waxy yellow/gold crayon fill pressed hard
      brush.set("crayon", tier.fill, 1.15);
      brush.line(x0, y0, x1, y1);
      brush.set("crayon", tier.hi, 0.8);
      brush.line(x0 + nx * 0.25, y0 + ny * 0.25, x1 - ca * 2, y1 - sa * 2);

      // Individual strap-petal felt-tip outline
      brush.set("rotring", "#1a1207", 0.52);
      brush.line(x0 - nx * 0.5, y0 - ny * 0.5, x1 - nx * 0.85, y1 - ny * 0.85);
      brush.line(x0 + nx * 0.5, y0 + ny * 0.5, x1 + nx * 0.85, y1 + ny * 0.85);
      // Square notched strap tip
      brush.line(x1 - nx * 0.85, y1 - ny * 0.85, x1 + nx * 0.85, y1 + ny * 0.85);
    }
  }

  // Dense orange-umber eye center with bright golden stamen dots
  for (let i = 0; i < 14; i++) {
    const a = random(360);
    const rr = random(0, radius * 0.22);
    const px = cx + cos(a) * rr;
    const py = cy + sin(a) * rr;
    brush.set("crayon", i % 2 === 0 ? "#b84e00" : "#fff275", 0.9);
    brush.line(px - 1.5, py - 1.5, px + 1.5, py + 1.5);
  }
}

function drawDandelionPuff(cx, cy, radius) {
  // Delicate radial seed clock (pappus sphere) glowing cream-white against kraft board
  const spokes = 32;
  for (let i = 0; i < spokes; i++) {
    const ang = (i * 360) / spokes + random(-2, 2);
    const rOut = radius * random(0.88, 1.04);
    const x0 = cx + cos(ang) * (radius * 0.14);
    const y0 = cy + sin(ang) * (radius * 0.14);
    const x1 = cx + cos(ang) * rOut;
    const y1 = cy + sin(ang) * rOut;

    // Fine dark stalk
    brush.set("2H", "#332619", 0.45);
    brush.line(x0, y0, x1, y1);

    // Cream-white parachute tuft at outer tip
    for (let f = -24; f <= 24; f += 12) {
      const fa = ang + f;
      brush.set("cpencil", "#fffdf0", 0.72);
      brush.line(x1, y1, x1 + cos(fa) * 8.5, y1 + sin(fa) * 8.5);
    }
  }

  // Inner ring of secondary fluff
  for (let i = 0; i < 20; i++) {
    const ang = (i * 360) / 20 + 9;
    const rr = radius * 0.58;
    const x1 = cx + cos(ang) * rr;
    const y1 = cy + sin(ang) * rr;
    brush.set("crayon", "#fff9de", 0.75);
    brush.line(x1 - 4, y1, x1 + 4, y1);
    brush.line(x1, y1 - 4, x1, y1 + 4);
  }

  // Dark receptacle core + tiny brown achenes (seeds)
  brush.set("crayon", "#3d2e1b", 1.1);
  brush.circle(cx, cy, radius * 0.14, 0.2);
  brush.set("rotring", "#140e08", 0.65);
  brush.circle(cx, cy, radius * 0.15, 0.2);
}

