function drawTortoiseUnderShadow() {
  // Heavy grounded charcoal & dark umber shadow beneath plastron, feet & neck
  const shadowZones = [
    { x0: 210, x1: 1030, y: 815, rx: 410, ry: 75 },
    { x0: 250, x1: 425, y: 942, rx: 92, ry: 28 },
    { x0: 840, x1: 1015, y: 938, rx: 88, ry: 26 },
    { x0: 175, x1: 285, y: 878, rx: 58, ry: 20 }
  ];

  for (let z of shadowZones) {
    const cx = (z.x0 + z.x1) * 0.5;
    for (let r = 1.0; r >= 0.2; r -= 0.12) {
      const col = r > 0.6 ? "#3d2916" : (r > 0.35 ? "#24170c" : "#120b06");
      brush.set("charcoal", col, 1.25);
      const rx = z.rx * r;
      const ry = z.ry * r;
      const pts = [];
      for (let a = 0; a <= 360; a += 20) {
        pts.push([cx + cos(a) * rx, z.y + sin(a) * ry]);
      }
      brush.spline(pts, 0.35);
    }
  }
}

function drawIndividualScale(cx, cy, rx, ry, rotDeg, fillCol, hiCol, shadowCol, weight = 0.72) {
  const sides = 7;
  const pts = [];
  const rad = rotDeg * Math.PI / 180;
  const c = Math.cos(rad), s = Math.sin(rad);

  for (let i = 0; i < sides; i++) {
    const a = (i * 360) / sides;
    const jitter = 0.88 + noise(cx * 0.08 + i, cy * 0.08) * 0.24;
    const lx = cos(a) * rx * jitter;
    const ly = sin(a) * ry * jitter;
    pts.push([
      cx + lx * c - ly * s,
      cy + lx * s + ly * c
    ]);
  }

  // Waxy base fill
  brush.set("crayon", fillCol, Math.max(0.65, Math.min(1.4, (rx + ry) * 0.095)));
  brush.line(
    cx - rx * 0.55 * c,
    cy - rx * 0.55 * s,
    cx + rx * 0.55 * c,
    cy + rx * 0.55 * s
  );

  // Lower shadow crescent inside scale
  if (shadowCol) {
    brush.set("cpencil", shadowCol, Math.max(0.55, (rx + ry) * 0.07));
    brush.line(pts[2][0], pts[2][1], pts[4][0], pts[4][1]);
  }

  // Upper waxy highlight glint
  if (hiCol) {
    brush.set("crayon", hiCol, Math.max(0.55, (rx + ry) * 0.075));
    brush.line(
      cx - rx * 0.35,
      cy - ry * 0.35,
      cx + rx * 0.25,
      cy - ry * 0.25
    );
  }

  // Obsessive individual felt-tip scale outline
  brush.set("rotring", "#110c07", weight);
  for (let i = 0; i < sides; i++) {
    const p1 = pts[i];
    const p2 = pts[(i + 1) % sides];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawClaw(xBase, yBase, xTip, yTip, baseWidth) {
  const dx = xTip - xBase;
  const dy = yTip - yBase;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;

  const pLeft = [xBase - nx * baseWidth * 0.5, yBase - ny * baseWidth * 0.5];
  const pRight = [xBase + nx * baseWidth * 0.5, yBase + ny * baseWidth * 0.5];
  const pMidL = [
    xBase + dx * 0.55 - nx * (baseWidth * 0.36 + 3),
    yBase + dy * 0.55 - ny * (baseWidth * 0.36 + 3)
  ];
  const pMidR = [
    xBase + dx * 0.55 + nx * (baseWidth * 0.18),
    yBase + dy * 0.55 + ny * (baseWidth * 0.18)
  ];

  // Keratin longitudinal ridges from dark root to warm horn-amber tip
  for (let s = -4; s <= 4; s++) {
    const f = s / 4;
    const col = f < -0.2 ? "#e8c574" : (f < 0.3 ? "#9c6d2c" : "#291a0d");
    brush.set("crayon", col, 0.95);
    const sx = xBase + nx * f * baseWidth * 0.42;
    const sy = yBase + ny * f * baseWidth * 0.42;
    brush.line(sx, sy, xTip + nx * f * 1.8, yTip + ny * f * 1.8);
  }

  // Dark root cuff
  brush.set("charcoal", "#170f08", 0.95);
  brush.line(pLeft[0], pLeft[1], pRight[0], pRight[1]);

  // Sharp felt-tip claw outline
  brush.set("rotring", "#0f0a06", 0.85);
  brush.spline([pLeft, pMidL, [xTip, yTip]], 0.3);
  brush.spline([pRight, pMidR, [xTip, yTip]], 0.3);
}

function drawFarForeleg() {
  // Far right foreleg (tucked in shadow behind neck/throat)
  for (let row = 0; row < 8; row++) {
    const t = row / 7;
    const cy = 695 + t * 155;
    const cxCenter = 242 - t * 28;
    const halfW = 38 - t * 6;
    const cols = 4;
    for (let c = 0; c < cols; c++) {
      const u = (c / (cols - 1)) * 2 - 1;
      const sx = cxCenter + u * halfW + (row % 2) * 4;
      const sy = cy + Math.abs(u) * 5;
      const fillCol = u < 0 ? "#6e5525" : "#382813";
      const hiCol = u < -0.2 ? "#b08938" : null;
      drawIndividualScale(sx, sy, 9.5, 7.5, 15, fillCol, hiCol, "#1c1209", 0.68);
    }
  }
  // 4 claws on far right foot
  for (let k = 0; k < 4; k++) {
    const bx = 186 + k * 16;
    const by = 856 + k * 4;
    drawClaw(bx, by, bx - 14, by + 26, 12);
  }
}

function drawTail() {
  // Stubby conical tail emerging under rear supracaudal scute
  const rings = 7;
  for (let r = 0; r < rings; r++) {
    const t = r / (rings - 1);
    const cx = 1005 + t * 76;
    const cy = 688 + t * 54;
    const span = (1 - t * 0.72) * 26;
    const count = Math.max(2, Math.round(5 - t * 3));
    for (let i = 0; i < count; i++) {
      const f = count === 1 ? 0 : (i / (count - 1)) * 2 - 1;
      const sx = cx - f * span * 0.45;
      const sy = cy + f * span * 0.85;
      const fillCol = f < 0 ? "#9c7832" : "#4a3818";
      const hiCol = f < 0 ? "#dbb256" : null;
      drawIndividualScale(
        sx,
        sy,
        (1 - t * 0.45) * 8,
        (1 - t * 0.45) * 6,
        32,
        fillCol,
        hiCol,
        "#21150b",
        0.65
      );
    }
  }
}

