function drawShellScute(polyVerts, areola, numRings, scuteType, scuteIndex) {
  const nSides = polyVerts.length;
  const subSteps = 5;

  // Build shared subdivided boundary sides so adjacent scutes interlock seamlessly
  const sideCurves = [];
  const allOuterPts = [];
  for (let s = 0; s < nSides; s++) {
    const p1 = polyVerts[s];
    const p2 = polyVerts[(s + 1) % nSides];
    const edgePts = getSharedSubdividedEdge(p1, p2, subSteps, 2.5);
    sideCurves.push([...edgePts, p2]);
    for (let pt of edgePts) allOuterPts.push(pt);
  }

  const scuteCenter = polyCentroid(polyVerts);

  // Compute global dome illumination factor for this scute (brighter near top-left crown)
  const domeDist = dist(scuteCenter[0], scuteCenter[1], 565, 340) / 480;
  const domeLight = constrain(1.15 - domeDist * 0.85, 0.25, 1.15);

  // Palette for concentric waxy growth rings:
  // Deep umber, burnt umber, dark olive, warm olive, golden ochre, amber-gold, shining cream
  const darkBandCols = ["#1c1108", "#2e1a0c", "#3b2310", "#303d14"];
  const midBandCols = ["#4d3014", "#44571d", "#5e6e24", "#8a5a19"];
  const warmBandCols = ["#b87a1c", "#d69824", "#748228", "#9c6d1e"];
  const shineBandCols = ["#eeb838", "#f7d35c", "#fff2b3", "#fffbe0"];

  // 1. Draw Concentric Growth Rings facet-by-facet from outer suture (t=0.98) to areola (t=0.19)
  for (let r = 0; r < numRings; r++) {
    const u = r / Math.max(1, numRings - 1); // 0 = outer edge, 1 = inner areola rim
    const t = lerp(0.97, 0.19, u);

    // Ring banding rhythm (periodic growth rings of ochre, olive, umber, and cream)
    const ringWave = Math.sin(r * 58 + scuteIndex * 37) * 0.5 +
                     Math.cos(r * 115 + scuteIndex * 19) * 0.5;

    for (let s = 0; s < nSides; s++) {
      const curve = sideCurves[s];
      const pStart = curve[0];
      const pEnd = curve[curve.length - 1];
      const midEdge = lerpPt(pStart, pEnd, 0.5);

      // Outward normal of this facet relative to the areola
      const fx = midEdge[0] - areola[0];
      const fy = midEdge[1] - areola[1];
      const flen = Math.hypot(fx, fy) || 1;
      const nx = fx / flen;
      const ny = fy / flen;

      // Overhead-left studio light vector (-0.48, -0.88)
      const facetDot = (-nx * 0.48 + -ny * 0.88); // -1 (deep shadow) to +1 (direct specular shine)

      // Tortoise-shell radial ray modulation (dark umber wedges vs golden-ochre rays)
      const rayAngle = atan2(fy, fx);
      const rayMod = Math.sin(rayAngle * 3.0 + scuteIndex * 55);

      // Combine ring band + 3D facet orientation + dome light + radial ray pattern
      let lum = domeLight * 0.42 + facetDot * 0.34 + ringWave * 0.26 + rayMod * 0.16;

      // Outer 2 rings near the suture are always deep dark umber/black growth seams
      if (r <= 1) lum = -0.65;
      // Inner areola collar often has a bright waxy ochre/cream halo
      if (r >= numRings - 3 && facetDot > -0.2) lum += 0.38;

      let col;
      if (lum < -0.15) {
        col = darkBandCols[(r + s + scuteIndex) % darkBandCols.length];
      } else if (lum < 0.22) {
        col = midBandCols[(r + s * 2 + scuteIndex) % midBandCols.length];
      } else if (lum < 0.58) {
        col = warmBandCols[(r + s + scuteIndex) % warmBandCols.length];
      } else {
        col = shineBandCols[(r + s) % shineBandCols.length];
      }

      // Compute ring points for this facet, slightly smoothing toward the inner areola
      const ringPts = [];
      for (let k = 0; k < curve.length; k++) {
        const pt = curve[k];
        // Slight inward curve rounding as rings approach the central areola
        const cornerRound = (1 - t) * 0.18 * Math.sin((k / (curve.length - 1)) * 180);
        const effT = t * (1 + cornerRound);
        ringPts.push([
          areola[0] + (pt[0] - areola[0]) * effT,
          areola[1] + (pt[1] - areola[1]) * effT
        ]);
      }

      // Draw pressed-hard waxy crayon growth ring
      const weight = lum > 0.55 ? 1.35 : 1.15;
      brush.set("crayon", col, weight);
      brush.spline(ringPts, 0.25);

      // Extra high-contrast waxy sheen pass on sunlit upper-left facets so the shell shines!
      if (lum > 0.62 && r % 2 === 0 && scuteType !== "plastron") {
        brush.set("cpencil", "#fff9de", 0.92);
        brush.spline(ringPts, 0.25);
      }

      // Fine dark growth-annulus groove every 3rd ring for hyperreal relief
      if (r % 3 === 0 && r > 0) {
        brush.set("2B", "#1f1309", 0.48);
        brush.spline(ringPts, 0.25);
      }
    }
  }

  // 2. Radial Mitre Ridges (from each polygon vertex inward to the areola corners)
  for (let s = 0; s < nSides; s++) {
    const vPt = polyVerts[s];
    const aCorner = lerpPt(areola, vPt, 0.19);
    const vx = vPt[0] - areola[0];
    const vy = vPt[1] - areola[1];
    const isLit = (vx * -0.4 + vy * -0.8) > 0;

    brush.set("cpencil", isLit ? "#f5d76e" : "#26170b", 0.75);
    brush.line(vPt[0], vPt[1], aCorner[0], aCorner[1]);
  }

  // 3. Central Embryonic Areola (t < 0.19): finely pitted leathery ochre/olive/umber texture
  const areolaRim = [];
  for (let s = 0; s < nSides; s++) {
    const p1 = polyVerts[s];
    const p2 = polyVerts[(s + 1) % nSides];
    const mid = lerpPt(p1, p2, 0.5);
    areolaRim.push(lerpPt(areola, p1, 0.18));
    areolaRim.push(lerpPt(areola, mid, 0.19));
  }
  areolaRim.push(areolaRim[0]);

  // Granular stippled pits inside the areola
  const numGranules = scuteType === "costal" || scuteType === "vertebral" ? 36 : 16;
  for (let g = 0; g < numGranules; g++) {
    const ang = (g * 137.5) % 360;
    const radFrac = Math.sqrt((g + 0.5) / numGranules) * 0.155;
    const refIdx = g % polyVerts.length;
    const refPt = polyVerts[refIdx];
    const gx = areola[0] + (refPt[0] - areola[0]) * radFrac + cos(ang) * 3.5;
    const gy = areola[1] + (refPt[1] - areola[1]) * radFrac + sin(ang) * 3.5;

    const gCol = g % 3 === 0 ? "#e6ab2e" : (g % 3 === 1 ? "#5c6922" : "#331f0e");
    brush.set("crayon", gCol, 0.95);
    brush.line(gx - 2, gy - 1, gx + 2, gy + 1);
    brush.set("rotring", "#1c1209", 0.42);
    brush.circle(gx, gy, 2.2, 0.25);
  }

  // Bright waxy specular highlight on the upper-left rim of the areola
  brush.set("crayon", "#fff7cf", 1.1);
  brush.line(areola[0] - 8, areola[1] - 5, areola[0] + 5, areola[1] - 8);

  // Inner areola outline
  brush.set("rotring", "#1c1108", 0.65);
  brush.spline(areolaRim, 0.35);

  // 4. Deep, Obsessive Suture Trench Outline around the Scute Perimeter
  for (let s = 0; s < nSides; s++) {
    const curve = sideCurves[s];
    brush.set("charcoal", "#1a1008", 1.15);
    brush.spline(curve, 0.25);
    brush.set("rotring", "#0d0804", 0.95);
    brush.spline(curve, 0.25);
  }
}

// ============================================================================
// 5. HIND LEFT LEG (WRINKLED THIGH SCALES + ARMORED ANKLE + 4 CLAWS)
// ============================================================================

function drawHindLeg() {
  // Dark rear shell opening cavity shadow
  for (let i = 0; i < 12; i++) {
    brush.set("charcoal", "#120b06", 1.3);
    brush.line(830 + i * 8, 690, 845 + i * 11, 755);
  }

  // Pack ~85 scales down the muscular hind leg (x: 840..1005, y: 705..910)
  const rows = 12;
  for (let r = 0; r < rows; r++) {
    const v = r / (rows - 1); // 0 = upper thigh under shell, 1 = ankle above claws
    const cy = 708 + v * 195;
    const centerX = 905 + Math.sin(v * 150) * 18 + v * 14;
    const halfW = lerp(52, 66, v);

    // Scales grow from small leathery thigh pebbles to larger armored heel plates
    const scaleRx = lerp(6.2, 11.5, v);
    const scaleRy = lerp(4.8, 8.8, v);
    const cols = Math.round((halfW * 2) / (scaleRx * 1.65));

    // Skin fold wave on upper thigh
    const foldWave = Math.sin(v * 540);

    for (let c = 0; c < cols; c++) {
      const u = cols === 1 ? 0 : (c / (cols - 1)) * 2 - 1;
      const sx = centerX + u * halfW + (r % 2) * (scaleRx * 0.45);
      const sy = cy + (1 - u * u) * 7 + random(-1.5, 1.5);

      // Lighting: left/front of hind leg catches warm ochre light, right/back is deep olive-umber
      const lightVal = -u * 0.55 + foldWave * 0.25 - (1 - v) * 0.2;
      let fillCol, hiCol = null, shCol = "#1f140a";

      if (lightVal > 0.25) {
        fillCol = "#d4982a";
        hiCol = "#fae28c";
      } else if (lightVal > -0.1) {
        fillCol = "#6b7324";
        hiCol = "#b89635";
      } else {
        fillCol = "#3d3316";
      }

      drawIndividualScale(
        sx,
        sy,
        scaleRx * (0.9 + foldWave * 0.1),
        scaleRy * (0.9 + foldWave * 0.1),
        -12 + u * 18,
        fillCol,
        hiCol,
        shCol,
        0.72
      );
    }
  }

  // 4 Heavy Hind Claws planted on the ground
  const clawBases = [
    [856, 902, 838, 945, 16],
    [892, 908, 878, 954, 17],
    [932, 908, 922, 954, 17],
    [972, 900, 968, 944, 15]
  ];
  for (let cl of clawBases) {
    drawClaw(cl[0], cl[1], cl[2], cl[3], cl[4]);
  }
}

// ============================================================================
// 6. LEATHERY NECK & HEAD (HUNDREDS OF TINY FELT-TIP SCALES + EYE + BEAK)
// ============================================================================

function drawNeckAndHead() {
  // 1. Deep dark cavity inside the anterior shell opening (behind the neck)
  for (let i = 0; i < 18; i++) {
    const t = i / 17;
    brush.set("charcoal", "#110a05", 1.45);
    brush.line(305 + t * 55, 505 + t * 40, 335 + t * 65, 695 + t * 25);
  }

  // 2. Leathery Neck Underpainting & Loose Skin Folds (x: 205..365, y: 535..715)
  const neckCols = 22;
  for (let i = 0; i <= neckCols; i++) {
    const u = i / neckCols; // 0 = base of head, 1 = deep in shell opening
    const topX = lerp(212, 342, u);
    const topY = lerp(532, 522, u) + Math.sin(u * 360) * 8;
    const botX = lerp(218, 368, u);
    const botY = lerp(642, 712, u) + Math.sin(u * 540) * 10;

    // 5 major transverse skin folds along the leathery neck
    const fold = Math.sin(u * 920 + 25);
    const underCol = fold < -0.25 ? "#1c1209" : (fold < 0.25 ? "#4a521d" : "#8f6d29");
    brush.set("crayon", underCol, 1.35);
    brush.line(topX, topY, botX, botY);

    // Deep crease line in fold troughs
    if (fold < -0.55) {
      brush.set("rotring", "#120b06", 0.85);
      brush.line(topX, topY + 4, botX, botY - 4);
    }
  }

  // 3. Pack ~330 Tiny Felt-Tip Scales across the Leathery Neck following the skin folds!
  const numNeckStrips = 21;
  for (let c = 0; c < numNeckStrips; c++) {
    const u = c / (numNeckStrips - 1); // 0 = near skull/throat, 1 = entering shell cavity
    const topX = lerp(216, 344, u);
    const topY = lerp(534, 524, u) + Math.sin(u * 360) * 7;
    const botX = lerp(222, 366, u);
    const botY = lerp(640, 710, u) + Math.sin(u * 540) * 9;

    const foldWave = Math.sin(u * 920 + 25);
    const stripLen = dist(topX, topY, botX, botY);
    // Scales compress in the fold creases and plump up on the lit fold crowns
    const scaleRx = lerp(3.8, 6.2, (foldWave + 1) * 0.5) * (1 - u * 0.12);
    const scaleRy = lerp(3.2, 5.2, (foldWave + 1) * 0.5);
    const numInStrip = Math.floor(stripLen / (scaleRy * 1.72));

    for (let r = 0; r <= numInStrip; r++) {
      const v = r / Math.max(1, numInStrip); // 0 = dorsal neck ridge, 1 = hanging gular throat pouch
      const jitterU = (c % 2 === 0 ? 0 : 0.015) + random(-0.008, 0.008);
      const sx = lerp(topX, botX, v) + jitterU * 110;
      const sy = lerp(topY, botY, v) + Math.sin(v * 180) * (foldWave * 3.5);

      // Cylindrical neck lighting + skin fold crest lighting + shell cavity shadow
      const cylLight = Math.cos(v * 165) * 0.55;
      const cavityShadow = u > 0.72 ? -(u - 0.72) * 2.2 : 0;
      const lum = cylLight + foldWave * 0.35 + cavityShadow;

      let fillCol, hiCol = null, shCol = "#1a1108";
      if (lum > 0.42) {
        fillCol = "#e0a934";
        hiCol = "#fff3b8";
      } else if (lum > 0.08) {
        fillCol = "#968c2b";
        hiCol = "#dfbe4c";
      } else if (lum > -0.25) {
        fillCol = "#4f5c1e";
      } else {
        fillCol = "#2b2011";
      }

      const rot = -18 + v * 28 + foldWave * 12;
      drawIndividualScale(sx, sy, scaleRx, scaleRy, rot, fillCol, hiCol, shCol, 0.62);
    }
  }

  // 4. Hyperreal Tortoise Head (x: 108..235, y: 518..645)
  drawTortoiseHead();
}

function drawTortoiseHead() {
  // Head silhouette & anatomical landmarks:
  // Snout tip: (110, 578), Cranial dome: (178, 520), Occiput: (224, 534)
  // Upper beak tomium: (110, 594) -> (145, 608) -> (188, 614)
  // Lower jaw chin: (118, 612) -> (165, 636) -> (220, 638)
