    { x: 185, y: 526, rx: 14, ry: 8.0, rot: -4,  fill: "#d49e2a", hi: "#fae89b" },
    { x: 208, y: 531, rx: 12, ry: 7.5, rot: 8,   fill: "#9c8228", hi: "#e8c658" },
    // Supraocular (heavy brow ridge scales over the eye)
    { x: 152, y: 549, rx: 10, ry: 5.8, rot: -18, fill: "#b88a28", hi: "#f5dc7a" },
    { x: 170, y: 546, rx: 11, ry: 6.0, rot: -4,  fill: "#c9982c", hi: "#fae48e" },
    { x: 188, y: 549, rx: 10, ry: 6.0, rot: 12,  fill: "#857a24", hi: "#d9b448" },
    // Posterior parietal / temporal scales behind eye
    { x: 204, y: 548, rx: 10, ry: 6.8, rot: 5,   fill: "#6e7322", hi: "#b89c38" },
    { x: 218, y: 548, rx: 9,  ry: 6.5, rot: 12,  fill: "#575e1d", hi: "#94822b" },
    { x: 196, y: 565, rx: 9.5, ry: 6.8, rot: 8,  fill: "#676e22", hi: "#b59b3b" },
    { x: 212, y: 566, rx: 9.5, ry: 7.0, rot: 14, fill: "#4e541b", hi: null },
    { x: 196, y: 581, rx: 9.0, ry: 6.5, rot: 6,  fill: "#59541c", hi: "#9e842e" },
    // Tympanum (circular ear drum scale behind jaw corner) + surrounding rim scales
    { x: 214, y: 595, rx: 11.5, ry: 10.5, rot: 10, fill: "#453919", hi: "#826b2a" },
    { x: 201, y: 604, rx: 6.5, ry: 5.0, rot: -15, fill: "#4d421a", hi: null },
    { x: 214, y: 612, rx: 7.0, ry: 5.0, rot: 0,   fill: "#3b2e14", hi: null },
    { x: 224, y: 583, rx: 6.5, ry: 5.5, rot: 25,  fill: "#423817", hi: null },
    // Subocular & cheek scales
    { x: 150, y: 583, rx: 8.5, ry: 5.5, rot: 12,  fill: "#7d6b24", hi: "#c4a342" },
    { x: 168, y: 586, rx: 9.0, ry: 5.5, rot: 6,   fill: "#6b5e20", hi: "#ad9136" },
    { x: 184, y: 588, rx: 8.5, ry: 5.8, rot: 10,  fill: "#594e1c", hi: null },
    // Gular / submandibular scales under lower jaw
    { x: 148, y: 626, rx: 8.0, ry: 5.0, rot: 14,  fill: "#473717", hi: null },
    { x: 165, y: 631, rx: 8.5, ry: 5.2, rot: 10,  fill: "#3f3014", hi: null },
    { x: 183, y: 634, rx: 8.5, ry: 5.5, rot: 6,   fill: "#362811", hi: null },
