  ];

  for (let sc of headScales) {
    drawIndividualScale(sc.x, sc.y, sc.rx, sc.ry, sc.rot, sc.fill, sc.hi, "#1a1108", 0.72);
  }

  // Concentric skin ring inside the Tympanum (ear drum)
  brush.set("rotring", "#170f08", 0.58);
