  brush.spline([[111, 596], [126, 599], [146, 606], [168, 608], [189, 612]], 0.25);
  brush.set("charcoal", "#140c06", 0.9);
  brush.spline([[113, 598], [146, 608], [189, 613]], 0.25);
  // Lower jaw contour
  brush.set("rotring", "#120b06", 0.85);
  brush.spline([[114, 598], [118, 613], [145, 625], [182, 634], [218, 634]], 0.3);

