  brush.circle(122, 569, 2.4, 0.1);

  // THE EYE: Surrounded by tiny granular palpebral (eyelid) scales + glossy dark orb + living glint
  const ex = 168, ey = 566;
  // Outer ring of 14 tiny eyelid scales
  for (let i = 0; i < 14; i++) {
    const a = (i * 360) / 14;
    const px = ex + cos(a) * 14.5;
    const py = ey + sin(a) * 11.5;
    const isUpper = sin(a) < 0;
    drawIndividualScale(
      px,
      py,
      3.8,
      2.8,
      a + 90,
      isUpper ? "#c4962c" : "#6e5c1f",
      isUpper ? "#f7df86" : null,
      "#1c1209",
      0.58
    );
  }

  // Dark obsidian eyeball & warm dark-amber iris ring
  for (let r = 10.5; r >= 1.5; r -= 1.5) {
    const col = r > 7.5 ? "#3d200a" : "#0b0705";
    brush.set("crayon", col, 1.15);
    brush.circle(ex, ey, r, 0.1);
  }
  brush.set("rotring", "#080503", 0.95);
  brush.circle(ex, ey, 10.8, 0.12);

  // Wet lower eyelid tear-film reflection
  brush.set("cpencil", "#ebd494", 0.75);
  brush.arc(ex, ey, 9.2, 25, 145);

  // Brilliant double corneal catchlight (pressed-hard waxy white & cream)
  brush.set("crayon", "#fffef5", 1.35);
  brush.line(ex - 5.5, ey - 5.0, ex - 2.0, ey - 3.5);
  brush.line(ex - 5.0, ey - 3.8, ex - 2.5, ey - 2.5);
  brush.set("cpencil", "#fff4b8", 0.95);
  brush.line(ex + 2.5, ey + 2.5, ex + 4.5, ey + 3.5);
}

// ============================================================================
// 7. FOREGROUND ARMORED FORELEG (THICK OVERLAPPING MEGASCALES & 5 CLAWS)
// ============================================================================

function drawForegroundForeleg() {
  // Deep shoulder fold shadow where the foreleg emerges from under marginals M2..M4
  for (let i = 0; i < 14; i++) {
    brush.set("charcoal", "#140c06", 1.35);
    brush.line(338 + i * 7.5, 645 + i * 3.5, 315 + i * 7.5, 705 + i * 3.5);
  }

  // Draw 11 tiers of thick, overlapping, shield-like osteoderm scales from shoulder to claws
  const rows = 11;
  for (let r = 0; r < rows; r++) {
    const v = r / (rows - 1); // 0 = upper shoulder, 1 = wrist above the 5 claws
    const cy = 678 + v * 228;
    // The foreleg angles slightly forward/left from shoulder (385) down to foot (322)
    const centerX = lerp(382, 324, v) - Math.sin(v * 180) * 14;
    const halfW = lerp(52, 68, Math.sin(v * 140) * 0.6 + 0.4);

    // Foreleg megascales are large, armored, overlapping shields in the middle tiers
    const isMegaTier = v > 0.18 && v < 0.85;
    const scaleRx = isMegaTier ? 14.5 : 10.5;
    const scaleRy = isMegaTier ? 11.2 : 8.2;
    const cols = isMegaTier ? 5 : 6;

    for (let c = 0; c < cols; c++) {
      const u = (c / (cols - 1)) * 2 - 1; // -1 = anterior lit edge, +1 = posterior shadow edge
      const sx = centerX + u * halfW + (r % 2) * (scaleRx * 0.42);
      const sy = cy + (1 - u * u) * 9;

      drawArmoredForelegScale(sx, sy, scaleRx, scaleRy, u, v, r + c);
    }
  }

  // 5 Stout, Blunt Keratin Claws along the bottom of the foreground foot
  const foreClaws = [
    [258, 902, 240, 948, 17],
    [288, 912, 272, 960, 18],
    [322, 916, 310, 964, 19],
    [356, 914, 348, 960, 18],
    [388, 904, 384, 948, 16]
  ];
  for (let cl of foreClaws) {
    drawClaw(cl[0], cl[1], cl[2], cl[3], cl[4]);
  }
}

function drawArmoredForelegScale(cx, cy, rx, ry, uPos, vPos, seedIdx) {
  // Shield-shaped overlapping osteoderm scale (rounded upper arch, pointed/beveled lower overlap tip)
  const pts = [
    [cx - rx * 0.85, cy - ry * 0.45],
    [cx - rx * 0.35, cy - ry * 0.92],
    [cx + rx * 0.35, cy - ry * 0.92],
    [cx + rx * 0.85, cy - ry * 0.45],
    [cx + rx * 0.92, cy + ry * 0.35],
    [cx + rx * 0.15, cy + ry * 1.05],
    [cx - rx * 0.65, cy + ry * 0.55]
  ];

  // Cast shadow directly beneath the overlapping lower edge of the shield scale
  brush.set("charcoal", "#170f08", 1.05);
  brush.spline([pts[6], pts[5], pts[4]], 0.25);

  // Illumination across the curved armored foreleg cylinder
  const light = -uPos * 0.62 + (vPos > 0.15 && vPos < 0.8 ? 0.25 : -0.15);

  let baseCol, midCol, tipCol;
  if (light > 0.22) {
    baseCol = "#59631e";
    midCol = "#d99b26";
    tipCol = "#fff4bd";
  } else if (light > -0.15) {
    baseCol = "#3d4717";
    midCol = "#9e7422";
    tipCol = "#ebca65";
  } else {
    baseCol = "#24180c";
    midCol = "#4f3918";
    tipCol = "#8a6b29";
  }

  // Concentric waxy crayon bands inside the megascale
  for (let ring = 0.88; ring >= 0.22; ring -= 0.22) {
    const rPts = pts.map(p => [
      cx + (p[0] - cx) * ring,
      cy + (p[1] - cy) * ring
    ]);
    rPts.push(rPts[0]);
    const col = ring > 0.68 ? baseCol : (ring > 0.4 ? midCol : tipCol);
    brush.set("crayon", col, 1.15);
    brush.spline(rPts, 0.25);
  }

  // Pressed-hard waxy cream shine on the convex crown of the scale
  if (light > 0.05) {
    brush.set("crayon", "#fff9d6", 1.0);
    brush.line(cx - rx * 0.38, cy - ry * 0.15, cx + rx * 0.12, cy + ry * 0.25);
  }

  // Obsessive black felt-tip scale outline
  brush.set("rotring", "#0f0a06", 0.82);
  for (let i = 0; i < pts.length; i++) {
    const p1 = pts[i];
    const p2 = pts[(i + 1) % pts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// ============================================================================
// 8. WOBBLY HAND-RULED OUTSIDER-ART BORDER
// ============================================================================

function drawWobblyBorder() {
  const mOut = 38;
  const mIn = 58;

  // Helper to draw a hand-ruled line in ruler-length segments (~140px) with slight slips & corner overshoots
  function drawHandRuledLine(x1, y1, x2, y2, brushName, col, w, wobble = 2.8) {
    const dx = x2 - x1;
    const dy = y2 - y1;
    const len = Math.hypot(dx, dy);
    const nx = -dy / len;
    const ny = dx / len;
    const segs = 9;

    let prevX = x1 - (dx / len) * 7; // Slight ruler corner overshoot
    let prevY = y1 - (dy / len) * 7;

    for (let i = 1; i <= segs; i++) {
      const t = i / segs;
      const slip = (noise(x1 * 0.02 + i * 1.7, y1 * 0.02 + i * 2.3) - 0.5) * 2 * wobble;
      const curX = x1 + dx * t + nx * slip + (i === segs ? (dx / len) * 7 : 0);
      const curY = y1 + dy * t + ny * slip + (i === segs ? (dy / len) * 7 : 0);

      brush.set(brushName, col, w);
      brush.line(prevX, prevY, curX, curY);

      // Slight ruler-repositioning tick or overlap
      prevX = curX + nx * random(-0.9, 0.9);
      prevY = curY + ny * random(-0.9, 0.9);
    }
  }

  // Waxy crayon alternating ochre, olive, and umber compartment bars inside the double-ruled border band
  const bandPalette = ["#d99824", "#4a611d", "#4f2d13", "#f0c94d", "#29180b"];
  const step = 18;

  // Top & Bottom border bands
  for (let x = mIn; x < W - mIn; x += step) {
    const idx = Math.floor(x / step);
    const cTop = bandPalette[idx % bandPalette.length];
    const cBot = bandPalette[(idx + 2) % bandPalette.length];

    // Waxy fill strokes inside top & bottom border tracks
    brush.set("crayon", cTop, 1.25);
    brush.line(x + 3, mOut + 3, x + step - 2, mIn - 3);
    brush.line(x + 3, mIn - 3, x + step - 2, mOut + 3);

    brush.set("crayon", cBot, 1.25);
    brush.line(x + 3, H - mIn + 3, x + step - 2, H - mOut - 3);
    brush.line(x + 3, H - mOut - 3, x + step - 2, H - mIn + 3);

    // Hand-ruled felt-tip compartment divider ticks
    brush.set("rotring", "#140d07", 0.72);
    brush.line(x + random(-1.5, 1.5), mOut, x + random(-1.5, 1.5), mIn);
    brush.line(x + random(-1.5, 1.5), H - mIn, x + random(-1.5, 1.5), H - mOut);
  }

  // Left & Right border bands
  for (let y = mIn; y < H - mIn; y += step) {
    const idx = Math.floor(y / step);
    const cLeft = bandPalette[(idx + 1) % bandPalette.length];
    const cRight = bandPalette[(idx + 3) % bandPalette.length];

    brush.set("crayon", cLeft, 1.25);
    brush.line(mOut + 3, y + 3, mIn - 3, y + step - 2);
    brush.line(mIn - 3, y + 3, mOut + 3, y + step - 2);

    brush.set("crayon", cRight, 1.25);
    brush.line(W - mIn + 3, y + 3, W - mOut - 3, y + step - 2);
    brush.line(W - mOut - 3, y + 3, W - mIn + 3, y + step - 2);

    brush.set("rotring", "#140d07", 0.72);
    brush.line(mOut, y + random(-1.5, 1.5), mIn, y + random(-1.5, 1.5));
    brush.line(W - mIn, y + random(-1.5, 1.5), W - mOut, y + random(-1.5, 1.5));
  }

  // Corner target squares in shining waxy yellow-ochre and black felt-tip
  const corners = [
    [mOut, mOut],
    [W - mIn, mOut],
    [mOut, H - mIn],
    [W - mIn, H - mIn]
  ];
  for (let [cx, cy] of corners) {
    brush.set("crayon", "#ffd438", 1.35);
    brush.line(cx + 3, cy + 10, cx + 17, cy + 10);
    brush.line(cx + 10, cy + 3, cx + 10, cy + 17);
    brush.set("rotring", "#120b06", 0.85);
    brush.circle(cx + 10, cy + 10, 6, 0.25);
  }

  // Outer & Inner Wobbly Hand-Ruled Double Border Lines (charcoal under-rule + thick felt-tip pen)
  const rules = [
    // Outer frame
    [mOut, mOut, W - mOut, mOut],
    [W - mOut, mOut, W - mOut, H - mOut],
    [W - mOut, H - mOut, mOut, H - mOut],
    [mOut, H - mOut, mOut, mOut],
    // Inner frame
    [mIn, mIn, W - mIn, mIn],
    [W - mIn, mIn, W - mIn, H - mIn],
    [W - mIn, H - mIn, mIn, H - mIn],
    [mIn, H - mIn, mIn, mIn]
  ];

  for (let [x1, y1, x2, y2] of rules) {
    drawHandRuledLine(x1, y1, x2, y2, "charcoal", "#24160b", 1.15, 3.2);
    drawHandRuledLine(x1, y1, x2, y2, "rotring", "#0e0905", 1.05, 2.6);
  }
}

// Hyperrealism in p5.brush:
// Overhead banana leaf with a neat grid of kolam-looped string hoppers (idiyappam),
// exact parallel veins and tears, glistening steam beads, and off-centre coral-pink coconut sambol.

const SEED = 4219;

// Leaf spine (midrib) and vein direction geometry
const LEAF_X_MIN = 48;
const LEAF_X_MAX = 1152;

// Exact botanical tears along parallel veins (midrib anchor x0, depth ratio, outer gap width)
const UPPER_TEARS = [
  { x0: 205, depth: 0.28, gap: 12 },
  { x0: 412, depth: 0.64, gap: 24 },
  { x0: 738, depth: 0.48, gap: 18 },
  { x0: 1035, depth: 0.31, gap: 13 }
];

const LOWER_TEARS = [
  { x0: 148, depth: 0.26, gap: 14 },
  { x0: 404, depth: 0.56, gap: 26 },
  { x0: 732, depth: 0.44, gap: 20 },
  { x0: 995, depth: 0.24, gap: 13 }
];

// 3x3 Grid stations on the leaf: 8 string hoppers + 1 off-centre coral-pink sambol dish
const GRID_COLS = [265, 595, 922];
const GRID_ROWS = [252, 622, 944];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Fine white pen for the unbroken kolam noodle thread
  brush.add("kolam_pen", {
    type: "default",
    weight: 0.48,
    scatter: 0.04,
    sharpness: 0.85,
    grain: 5,
    opacity: 235,
    spacing: 0.16,
    pressure: [0.85, 1.15, 0.85],
    noise: 0.22
  });

  // Translucent steamed rice-noodle body brush
  brush.add("noodle_body", {
    type: "default",
    weight: 1.15,
    scatter: 0.1,
    sharpness: 0.32,
    grain: 9,
    opacity: 82,
    spacing: 0.22,
    pressure: [0.75, 1.1, 0.75],
    noise: 0.3
  });

  // Botanical stylus for exact parallel leaf veins
  brush.add("vein_stylus", {
    type: "default",
    weight: 0.36,
    scatter: 0.02,
    sharpness: 0.9,
    grain: 4,
    opacity: 195,
    spacing: 0.18,
    pressure: [0.6, 1.0, 0.55],
    noise: 0.12
  });

  // Shredded coconut texture brush for the sambol
  brush.add("coconut_shred", {
    type: "default",
    weight: 0.75,
    scatter: 0.12,
    sharpness: 0.65,
    grain: 12,
    opacity: 215,
    spacing: 0.18,
    pressure: [0.5, 1.25, 0.45],
    noise: 0.45
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#050e09");

  // 1. Dark stone/mat under-surface
  drawUnderSurface();

  // 2. Deep glossy green watercolour banana leaf with undulations, veins, midrib, and exact tears
  drawBananaLeafBase();
  drawLeafGlossAndShadowBands();
  drawParallelVeinsAndTears();
  drawCentralMidrib();

  // 3. Neat 3x3 grid: 8 Kolam String Hoppers (Idiyappam) + 1 off-centre Coconut Sambol dish
  const hopperCenters = [];
  let hopperIdx = 0;
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      const gx = GRID_COLS[c] + (r === 1 ? -4 : 3) * (c - 1);
      const gy = GRID_ROWS[r];
      // Upper-right station holds the off-centre dish of coral-pink coconut sambol
      if (r === 0 && c === 2) continue;
      hopperCenters.push({ x: gx, y: gy, idx: hopperIdx++ });
    }
  }

  // First pass: soft leaf-contact shadows & translucent steamed-rice cushions
  drawHopperShadowsAndCushions(hopperCenters);

  // Dish of coconut sambol in coral-pink at upper-right station (922, 252)
  drawCoconutSambolDish(GRID_COLS[2] + 4, GRID_ROWS[0] + 4, 102);

  // Second pass: continuous unbroken kolam white line for each string hopper
  for (const h of hopperCenters) {
    drawKolamStringHopper(h.x, h.y, 132, h.idx);
  }

  // 4. Glistening steam beads (condensation droplets) and subtle warm steam sheen
  drawSteamBeads(hopperCenters, { x: GRID_COLS[2] + 4, y: GRID_ROWS[0] + 4 });

  noLoop();
}

// ============================================================================
// GEOMETRY HELPERS FOR THE BANANA LEAF, VEINS & TEARS
// ============================================================================

function midribY(x) {
  const u = constrain((x - LEAF_X_MIN) / (LEAF_X_MAX - LEAF_X_MIN), 0, 1);
  return 436 - 14 * sin(u * 180) + 10 * (u - 0.5);
}

function midribHalfWidth(x) {
  const u = constrain((x - LEAF_X_MIN) / (LEAF_X_MAX - LEAF_X_MIN), 0, 1);
  return lerp(8.5, 3.2, pow(u, 0.85));
}

function upperMarginDist(x0) {
  const u = constrain((x0 - LEAF_X_MIN) / (LEAF_X_MAX - LEAF_X_MIN), 0, 1);
  const arch = sin(pow(u, 0.92) * 180);
  const base = 345 * pow(max(0.02, arch), 0.26);
  const waviness = 6 * sin(u * 540 + 25) + 4 * cos(u * 900);
  return max(28, base + waviness);
}

function lowerMarginDist(x0) {
  const u = constrain((x0 - LEAF_X_MIN) / (LEAF_X_MAX - LEAF_X_MIN), 0, 1);
  const arch = sin(pow(u, 0.9) * 180);
  const base = 682 * pow(max(0.02, arch), 0.24);
  const waviness = 8 * sin(u * 480 - 40) + 5 * cos(u * 820 + 15);
  return max(36, base + waviness);
}

// Point along an upper-blade vein originating at midrib x0, distance s
function upperVeinPoint(x0, s) {
  const yStart = midribY(x0) - midribHalfWidth(x0) * 0.7;
  // Veins sweep upward and slightly right (~ -78 deg) with subtle natural curve
  const ang = -78.5 - 3.2 * (s / 380);
  const px = x0 + s * cos(ang);
  const py = yStart + s * sin(ang);
  return [px, py];
}

// Point along a lower-blade vein originating at midrib x0, distance s
function lowerVeinPoint(x0, s) {
  const yStart = midribY(x0) + midribHalfWidth(x0) * 0.7;
  // Veins sweep downward and slightly right (~ +76.5 deg) with subtle natural curve
  const ang = 76.5 + 3.5 * (s / 700);
  const px = x0 + s * cos(ang);
  const py = yStart + s * sin(ang);
  return [px, py];
}

// Returns effective outer distance along vein at x0, accounting for exact V-slit tears
function upperEffectiveDist(x0) {
  let d = upperMarginDist(x0);
  for (const t of UPPER_TEARS) {
    const halfGap = t.gap * 0.5;
    const distX = abs(x0 - t.x0);
    if (distX < halfGap) {
      const tearApex = d * (1 - t.depth);
      const frac = distX / halfGap;
      d = min(d, lerp(tearApex, d, pow(frac, 0.75)));
    }
  }
  return d;
}

function lowerEffectiveDist(x0) {
  let d = lowerMarginDist(x0);
  for (const t of LOWER_TEARS) {
    const halfGap = t.gap * 0.5;
    const distX = abs(x0 - t.x0);
    if (distX < halfGap) {
      const tearApex = d * (1 - t.depth);
      const frac = distX / halfGap;
      d = min(d, lerp(tearApex, d, pow(frac, 0.75)));
    }
  }
  return d;
}

// ============================================================================
// 1. DARK TABLE / MAT UNDER-SURFACE
// ============================================================================

function drawUnderSurface() {
  brush.noStroke();
  brush.wash("#040b07", 255);
  brush.rect(0, 0, width, height);
  brush.noWash();

  // Subtle dark slate grain lines on the table surface
  brush.set("charcoal", "#091710", 0.7);
  for (let y = 18; y < height; y += 22) {
    const jy = y + random(-4, 4);
    brush.line(0, jy, width, jy + random(-6, 6));
  }

  // Deep shadow cast by the banana leaf onto the dark table
  brush.noStroke();
  brush.wash("#020503", 210);
  drawLeafBladePolygon(true, 10, 14, false);
  drawLeafBladePolygon(false, 10, 14, false);
  brush.noWash();
}

// ============================================================================
// 2. BANANA LEAF WATERCOLOUR BASE, GLOSS SHEEN, VEINS & EXACT TEARS
// ============================================================================

function drawLeafBladePolygon(isUpper, ox = 0, oy = 0, includeTears = true) {
  const step = 10;
  brush.beginShape(0.18);
  // Trace along midrib from left to right
  for (let x0 = LEAF_X_MIN; x0 <= LEAF_X_MAX; x0 += step * 2) {
    const p = isUpper ? upperVeinPoint(x0, 0) : lowerVeinPoint(x0, 0);
    brush.vertex(p[0] + ox, p[1] + oy);
  }
  // Trace outer margin (with or without exact V-tears) from right to left
  for (let x0 = LEAF_X_MAX; x0 >= LEAF_X_MIN; x0 -= step) {
    let d = isUpper
      ? (includeTears ? upperEffectiveDist(x0) : upperMarginDist(x0))
      : (includeTears ? lowerEffectiveDist(x0) : lowerMarginDist(x0));
    const p = isUpper ? upperVeinPoint(x0, d) : lowerVeinPoint(x0, d);
    brush.vertex(p[0] + ox, p[1] + oy);
  }
  brush.endShape(true);
}

function drawBananaLeafBase() {
  // Opaque deep chlorophyll base so the leaf reads rich and solid over the dark ground
  brush.noStroke();
  brush.wash("#0d2819", 250);
  drawLeafBladePolygon(true, 0, 0, true);
  drawLeafBladePolygon(false, 0, 0, true);
  brush.noWash();

  // Layered watercolour washes across the leaf blades (batched by colour for speed)
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.68, 0.38);

  // Batch 1: Rich emerald-viridian watercolor body
  brush.fill("#133b25", 135);
  drawLeafBladePolygon(true, 0, 0, true);
  drawLeafBladePolygon(false, 0, 0, true);

  // Batch 2: Deep forest green shadow patches along vein corridors
  brush.fill("#092114", 125);
  const darkBandsU = [
    [95, 230], [380, 520], [690, 830], [960, 1110]
  ];
  for (const [xa, xb] of darkBandsU) {
    drawVeinBandShape(true, xa, xb, 0.03, 0.96);
  }
  const darkBandsL = [
    [85, 220], [360, 515], [680, 845], [970, 1120]
  ];
  for (const [xa, xb] of darkBandsL) {
    drawVeinBandShape(false, xa, xb, 0.03, 0.96);
  }

  // Batch 3: Warm sap-emerald midtone swells
  brush.fill("#1d5436", 110);
  const midBandsU = [
    [190, 360], [500, 680], [810, 975]
  ];
  for (const [xa, xb] of midBandsU) {
    drawVeinBandShape(true, xa, xb, 0.05, 0.92);
  }
  const midBandsL = [
    [180, 355], [495, 675], [815, 985]
  ];
  for (const [xa, xb] of midBandsL) {
    drawVeinBandShape(false, xa, xb, 0.05, 0.92);
  }

  brush.noFill();
}

function drawVeinBandShape(isUpper, xStart, xEnd, sFracMin, sFracMax) {
  const pts = [];
  const step = 16;
  for (let x = xStart; x <= xEnd; x += step) {
    const d = (isUpper ? upperEffectiveDist(x) : lowerEffectiveDist(x)) * sFracMin;
    pts.push(isUpper ? upperVeinPoint(x, d) : lowerVeinPoint(x, d));
  }
  for (let x = xEnd; x >= xStart; x -= step) {
    const d = (isUpper ? upperEffectiveDist(x) : lowerEffectiveDist(x)) * sFracMax;
    pts.push(isUpper ? upperVeinPoint(x, d) : lowerVeinPoint(x, d));
  }
  brush.beginShape(0.25);
  for (const p of pts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
}

function drawLeafGlossAndShadowBands() {
  // Glossy cylindrical sheen bands catching overhead light parallel to the veins
  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.5, 0.22);

  // Soft celadon-jade gloss swells
  brush.fill("#2f734d", 95);
  drawVeinBandShape(true, 225, 335, 0.12, 0.85);
  drawVeinBandShape(true, 535, 650, 0.1, 0.88);
  drawVeinBandShape(true, 835, 935, 0.14, 0.82);

  drawVeinBandShape(false, 215, 330, 0.1, 0.88);
  drawVeinBandShape(false, 525, 655, 0.08, 0.9);
  drawVeinBandShape(false, 835, 945, 0.12, 0.85);

  // Brighter wet-leaf specular sheen cores
  brush.fill("#589e74", 78);
  drawVeinBandShape(true, 255, 305, 0.18, 0.76);
  drawVeinBandShape(true, 565, 620, 0.16, 0.78);
  drawVeinBandShape(false, 245, 300, 0.16, 0.76);
  drawVeinBandShape(false, 555, 620, 0.14, 0.82);
  drawVeinBandShape(false, 865, 915, 0.18, 0.74);

  // Luminous pale jade-mint reflection highlights along the convex leaf swells
  brush.fill("#8cc7a3", 55);
  drawVeinBandShape(true, 270, 292, 0.24, 0.65);
  drawVeinBandShape(true, 580, 605, 0.22, 0.68);
  drawVeinBandShape(false, 260, 285, 0.22, 0.64);
  drawVeinBandShape(false, 575, 602, 0.2, 0.72);

  brush.noFill();
}

// Determines how much specular light a vein catches at midrib coordinate x0
function leafGlossFactor(x0) {
  const c1 = exp(-sq((x0 - 275) / 62));
  const c2 = exp(-sq((x0 - 590) / 68));
  const c3 = exp(-sq((x0 - 890) / 58));
  return constrain(c1 + c2 + c3 * 0.85, 0, 1);
}

function drawParallelVeinsAndTears() {
  // 1. Carve out the exact V-slit tears cleanly to the dark surface below,
  //    with cast shadows and dried yellow-green split leaf margins
  for (const t of UPPER_TEARS) {
    renderExactTear(true, t);
  }
  for (const t of LOWER_TEARS) {
    renderExactTear(false, t);
  }

  // 2. Fine secondary striations (every 4.5 px along midrib)
  for (let x0 = LEAF_X_MIN + 8; x0 <= LEAF_X_MAX - 8; x0 += 4.5) {
    // Skip if primary vein interval
    if ( round(x0) % 13 < 4 ) continue;
    const gloss = leafGlossFactor(x0);
    const col = gloss > 0.45 ? "#2e6b48" : "#153d26";
    brush.set("vein_stylus", col, 0.52);

    // Upper blade striation
    const du = upperEffectiveDist(x0);
    if (du > 22) {
      const p1 = upperVeinPoint(x0, 4);
      const pMid = upperVeinPoint(x0, du * 0.52);
      const p2 = upperVeinPoint(x0, du - 3);
      brush.spline([p1, pMid, p2], 0.25);
    }

    // Lower blade striation
    const dl = lowerEffectiveDist(x0);
    if (dl > 26) {
      const q1 = lowerVeinPoint(x0, 4);
      const qMid = lowerVeinPoint(x0, dl * 0.52);
      const q2 = lowerVeinPoint(x0, dl - 3);
      brush.spline([q1, qMid, q2], 0.25);
    }
  }

  // 3. Primary parallel lateral veins (every 13.5 px): paired dark furrow + luminous ridge
  for (let x0 = LEAF_X_MIN + 10; x0 <= LEAF_X_MAX - 10; x0 += 13.5) {
    const gloss = leafGlossFactor(x0);
    const isMajor = (round(x0 / 13.5) % 2 === 0);

    // UPPER BLADE PRIMARY VEIN
    const du = upperEffectiveDist(x0);
    if (du > 24) {
      const u1 = upperVeinPoint(x0, 2);
      const u2 = upperVeinPoint(x0, du * 0.35);
      const u3 = upperVeinPoint(x0, du * 0.7);
      const u4 = upperVeinPoint(x0, du - 2);

      // Dark trough furrow
      brush.set("vein_stylus", "#06170e", isMajor ? 0.95 : 0.72);
      brush.spline([u1, u2, u3, u4], 0.3);

      // Adjacent sunlit ridge (+1.6 px offset)
      const ridgeCol = gloss > 0.55 ? "#7ec49a" : (gloss > 0.25 ? "#4b8c65" : "#2b6141");
      brush.set("vein_stylus", ridgeCol, isMajor ? 0.85 : 0.65);
      brush.spline([
        [u1[0] + 1.5, u1[1], 0.8],
        [u2[0] + 1.6, u2[1], 1.1],
        [u3[0] + 1.6, u3[1], 1.0],
        [u4[0] + 1.3, u4[1], 0.6]
      ], 0.3);

      // Extra bright specular glint across glossy zone
      if (gloss > 0.42) {
        const gStart = upperVeinPoint(x0 + 1.6, du * 0.22);
        const gMid = upperVeinPoint(x0 + 1.6, du * 0.48);
        const gEnd = upperVeinPoint(x0 + 1.6, du * 0.72);
        brush.set("vein_stylus", "#b5e6c8", 0.75 * gloss);
        brush.spline([gStart, gMid, gEnd], 0.25);
      }
    }

    // LOWER BLADE PRIMARY VEIN
    const dl = lowerEffectiveDist(x0);
    if (dl > 28) {
      const v1 = lowerVeinPoint(x0, 2);
      const v2 = lowerVeinPoint(x0, dl * 0.35);
      const v3 = lowerVeinPoint(x0, dl * 0.7);
      const v4 = lowerVeinPoint(x0, dl - 2);

      // Dark trough furrow
      brush.set("vein_stylus", "#06170e", isMajor ? 1.0 : 0.75);
      brush.spline([v1, v2, v3, v4], 0.3);

      // Adjacent sunlit ridge (+1.6 px offset)
      const ridgeCol = gloss > 0.55 ? "#7ec49a" : (gloss > 0.25 ? "#4b8c65" : "#2b6141");
      brush.set("vein_stylus", ridgeCol, isMajor ? 0.88 : 0.68);
      brush.spline([
        [v1[0] + 1.5, v1[1], 0.8],
        [v2[0] + 1.7, v2[1], 1.15],
        [v3[0] + 1.7, v3[1], 1.0],
        [v4[0] + 1.3, v4[1], 0.6]
      ], 0.3);

      // Extra bright specular glint across glossy zone
      if (gloss > 0.42) {
        const gStart = lowerVeinPoint(x0 + 1.7, dl * 0.2);
        const gMid = lowerVeinPoint(x0 + 1.7, dl * 0.48);
        const gEnd = lowerVeinPoint(x0 + 1.7, dl * 0.74);
        brush.set("vein_stylus", "#b5e6c8", 0.8 * gloss);
        brush.spline([gStart, gMid, gEnd], 0.25);
      }
    }
  }

  // 4. Crisp outer leaf margin & split tear edges
  drawLeafOuterMarginsAndTearRims();
}

function renderExactTear(isUpper, tear) {
  const halfGap = tear.gap * 0.5;
  const xL = tear.x0 - halfGap;
  const xR = tear.x0 + halfGap;
  const dMax = isUpper ? upperMarginDist(tear.x0) : lowerMarginDist(tear.x0);
  const dApex = dMax * (1 - tear.depth);

  const pEdgeL = isUpper ? upperVeinPoint(xL, upperMarginDist(xL) + 4) : lowerVeinPoint(xL, lowerMarginDist(xL) + 4);
  const pMidL  = isUpper ? upperVeinPoint(lerp(tear.x0, xL, 0.55), lerp(dApex, dMax, 0.5)) : lowerVeinPoint(lerp(tear.x0, xL, 0.55), lerp(dApex, dMax, 0.5));
  const pApex  = isUpper ? upperVeinPoint(tear.x0, dApex) : lowerVeinPoint(tear.x0, dApex);
  const pMidR  = isUpper ? upperVeinPoint(lerp(tear.x0, xR, 0.55), lerp(dApex, dMax, 0.5)) : lowerVeinPoint(lerp(tear.x0, xR, 0.55), lerp(dApex, dMax, 0.5));
  const pEdgeR = isUpper ? upperVeinPoint(xR, upperMarginDist(xR) + 4) : lowerVeinPoint(xR, lowerMarginDist(xR) + 4);

  // Dark table visible inside the tear slit
  brush.noStroke();
  brush.wash("#040a06", 255);
  brush.beginShape(0.15);
  brush.vertex(pEdgeL[0], pEdgeL[1]);
  brush.vertex(pMidL[0], pMidL[1]);
  brush.vertex(pApex[0], pApex[1]);
  brush.vertex(pMidR[0], pMidR[1]);
  brush.vertex(pEdgeR[0], pEdgeR[1]);
  brush.endShape(true);
  brush.noWash();
}

function drawLeafOuterMarginsAndTearRims() {
  // Highlight and dry-fiber edge along every tear slit
  for (const isUpper of [true, false]) {
    const tears = isUpper ? UPPER_TEARS : LOWER_TEARS;
    for (const t of tears) {
      const halfGap = t.gap * 0.5;
      const xL = t.x0 - halfGap;
      const xR = t.x0 + halfGap;
      const dL = isUpper ? upperMarginDist(xL) : lowerMarginDist(xL);
      const dR = isUpper ? upperMarginDist(xR) : lowerMarginDist(xR);
      const dApex = (isUpper ? upperMarginDist(t.x0) : lowerMarginDist(t.x0)) * (1 - t.depth);

      const pEdgeL = isUpper ? upperVeinPoint(xL, dL) : lowerVeinPoint(xL, dL);
      const pMidL  = isUpper ? upperVeinPoint(lerp(t.x0, xL, 0.55), lerp(dApex, dL, 0.5)) : lowerVeinPoint(lerp(t.x0, xL, 0.55), lerp(dApex, dL, 0.5));
      const pApex  = isUpper ? upperVeinPoint(t.x0, dApex) : lowerVeinPoint(t.x0, dApex);
      const pMidR  = isUpper ? upperVeinPoint(lerp(t.x0, xR, 0.55), lerp(dApex, dR, 0.5)) : lowerVeinPoint(lerp(t.x0, xR, 0.55), lerp(dApex, dR, 0.5));
      const pEdgeR = isUpper ? upperVeinPoint(xR, dR) : lowerVeinPoint(xR, dR);

      // Cast shadow just inside the tear on the left edge
      brush.set("cpencil", "#020604", 1.1);
      brush.spline([
        [pEdgeL[0] + 2.5, pEdgeL[1] + 2],
        [pMidL[0] + 2, pMidL[1] + 1.5],
        [pApex[0] + 1, pApex[1] + 1]
      ], 0.25);

      // Dry fibrous olive-celadon edge on both sides of the split tear
      brush.set("vein_stylus", "#6a9e78", 0.9);
      brush.spline([pEdgeL, pMidL, pApex], 0.25);
      brush.set("vein_stylus", "#98cca8", 0.85);
      brush.spline([pApex, pMidR, pEdgeR], 0.25);

      // Tiny bright tension fiber at the apex of the tear
      brush.set("kolam_pen", "#c8ebd3", 0.55);
      const pIn = isUpper ? upperVeinPoint(t.x0, dApex - 14) : lowerVeinPoint(t.x0, dApex - 14);
      brush.line(pApex[0], pApex[1], pIn[0], pIn[1]);
    }
  }

  // Outer leaf blade margin rim between tears
  const step = 18;
  for (const isUpper of [true, false]) {
    let seg = [];
    for (let x0 = LEAF_X_MIN; x0 <= LEAF_X_MAX; x0 += step) {
      const d = isUpper ? upperEffectiveDist(x0) : lowerEffectiveDist(x0);
      const dFull = isUpper ? upperMarginDist(x0) : lowerMarginDist(x0);
      if (abs(d - dFull) < 3) {
        seg.push(isUpper ? upperVeinPoint(x0, d) : lowerVeinPoint(x0, d));
      } else {
        if (seg.length >= 3) {
          brush.set("vein_stylus", isUpper ? "#58916b" : "#3a704d", 0.95);
          brush.spline(seg, 0.3);
        }
        seg = [];
      }
    }
    if (seg.length >= 3) {
      brush.set("vein_stylus", isUpper ? "#58916b" : "#3a704d", 0.95);
      brush.spline(seg, 0.3);
    }
  }
}

function drawCentralMidrib() {
  // 1. Cast shadow immediately below the raised central midrib ridge
  const shadowPts = [];
  for (let x = LEAF_X_MIN; x <= LEAF_X_MAX; x += 28) {
    const hw = midribHalfWidth(x);
    shadowPts.push([x, midribY(x) + hw + 3.5, 1.0]);
  }
  brush.set("charcoal", "#05140c", 1.35);
  brush.spline(shadowPts, 0.35);

  // 2. Opaque celadon-jade midrib body polygon
  brush.noStroke();
  brush.wash("#588f69", 240);
  brush.beginShape(0.2);
  for (let x = LEAF_X_MIN; x <= LEAF_X_MAX; x += 24) {
    brush.vertex(x, midribY(x) - midribHalfWidth(x));
  }
  for (let x = LEAF_X_MAX; x >= LEAF_X_MIN; x -= 24) {
    brush.vertex(x, midribY(x) + midribHalfWidth(x));
  }
  brush.endShape(true);
  brush.noWash();

  // 3. Sculpted 3D cylindrical longitudinal fibers along the midrib
  const offsets = [-0.75, -0.45, -0.15, 0.15, 0.45, 0.8];
  const cols    = ["#4b825d", "#88bf98", "#bce3c7", "#daf2e1", "#7ab089", "#2c5e3e"];
  const weights = [0.85, 1.05, 1.2, 0.95, 0.9, 0.85];

  for (let i = 0; i < offsets.length; i++) {
    const pts = [];
    for (let x = LEAF_X_MIN; x <= LEAF_X_MAX; x += 30) {
      const hw = midribHalfWidth(x);
      pts.push([x, midribY(x) + offsets[i] * hw, lerp(1.15, 0.55, (x - LEAF_X_MIN) / 1100)]);
    }
    brush.set("vein_stylus", cols[i], weights[i]);
    brush.spline(pts, 0.35);
  }

  // Cut petiole end on the left & tapered tip on the right
  const yL = midribY(LEAF_X_MIN);
  const hwL = midribHalfWidth(LEAF_X_MIN);
  brush.set("cpencil", "#a6ccb0", 1.1);
  brush.line(LEAF_X_MIN, yL - hwL, LEAF_X_MIN, yL + hwL);
}

// ============================================================================
// 3. KOLAM STRING HOPPERS (IDIYAPPAM) — ONE UNBROKEN THREAD PER NEST
// ============================================================================

function drawHopperShadowsAndCushions(hopperCenters) {
  // Soft drop shadow on the banana leaf beneath each string hopper
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.15);

  brush.fill("#04120a", 145);
  for (const h of hopperCenters) {
    brush.circle(h.x + 6, h.y + 8, 124, 0.18);
  }

  // Translucent jade-tinted steamed rice-flour aura where outer strands meet the green leaf
  brush.fill("#5f9478", 52);
  for (const h of hopperCenters) {
    brush.circle(h.x, h.y, 112, 0.22);
  }

  // Soft warm translucent rice cushion in the compressed middle of each nest
  brush.fill("#a8cfb9", 62);
  for (const h of hopperCenters) {
    brush.circle(h.x - 2, h.y - 2, 84, 0.18);
  }

  brush.fill("#dcefe4", 68);
  for (const h of hopperCenters) {
    brush.circle(h.x - 3, h.y - 3, 54, 0.15);
  }

  brush.noFill();
}

// Evaluates a point along the SINGLE UNBROKEN CLOSED KOLAM THREAD for parameter t in [0, 360] deg.
// Because M, L, and all harmonic modulations are exact integers on [0, 360],
// C(360) === C(0) with exact C^infinity smoothness: one unbroken loop circling the center and returning to itself.
function evalKolamThreadPoint(cx, cy, maxR, tDeg, params) {
  const { M, L, rotOffset, a1, b1, a2, b2, a3 } = params;

  // u goes smoothly from 0 (outer lacy rim) at t=0, to 1 (tight central rosette) at t=180,
  // and back to 0 (outer lacy rim) at t=360.
  const u = (1 - cos(tDeg)) * 0.5;

  // Organic periodic symmetry modulation (strictly 360-deg periodic)
  const organicR = a1 * cos(tDeg) + b1 * sin(tDeg) + a2 * cos(2 * tDeg) + b2 * sin(2 * tDeg) + a3 * cos(3 * tDeg);

  // Mean ring radius & kolam petal loop amplitude
  const rMid = maxR * (0.81 * (1 - 0.77 * pow(u, 0.92))) + 3.2 * cos(4 * tDeg) + organicR;
  const rAmp = maxR * (0.19 * (1 - 0.42 * u)) + 1.8 * sin(3 * tDeg);

  // Kolam epitrochoidal radial & azimuthal modulation
  const loopPhase = L * tDeg;
  const r = rMid + rAmp * cos(loopPhase) + 2.4 * cos(2 * loopPhase);

  // Retrograde azimuthal swing forms genuine rounded kolam loops / noodle coils
  const swingDeg = (12.2 + 4.8 * u) * sin(loopPhase) + 1.8 * sin(2 * loopPhase);
  const theta = rotOffset + M * tDeg + swingDeg + 2.2 * sin(2 * tDeg);

  const px = cx + r * cos(theta);
  const py = cy + r * sin(theta);
  return { x: px, y: py, r: r, u: u, loopCos: cos(loopPhase), theta: theta };
}

function drawKolamStringHopper(cx, cy, maxR, seedIdx) {
  randomSeed(SEED + seedIdx * 137);

  // Parameters for the single unbroken closed curve:
  // M = 11 revolutions per closed cycle; L = 104 kolam petal loops along the single thread.
  // gcd(11, 104) = 1, so adjacent rings interleave their kolam petals into a sacred lattice!
  const params = {
    M: 11,
    L: 104,
    rotOffset: seedIdx * 42 + random(-8, 8),
    a1: random(-2.2, 2.2),
    b1: random(-2.2, 2.2),
    a2: random(-1.8, 1.8),
    b2: random(-1.8, 1.8),
    a3: random(-1.4, 1.4)
  };

  // Sample the entire closed continuous curve C(t) for t in [0, 360]
  const totalSamples = 832; // 8 points per kolam loop * 104 loops
  const pts = [];
  for (let i = 0; i <= totalSamples; i++) {
    const tDeg = (i / totalSamples) * 360;
    pts.push(evalKolamThreadPoint(cx, cy, maxR, tDeg, params));
  }

  // Partition the unbroken curve into 32 contiguous overlapping segments so we can modulate
  // translucency (jade-tinted outer noodle edges vs crisp opaque white inner crown)
  // while keeping the line 100% continuous and unbroken.
  const numSegs = 32;
  const segLen = totalSamples / numSegs;

  // PASS 1: Subtle under-strand separation shadow (+1.3, +1.6 px) so overlapping coils have 3D relief
  for (let s = 0; s < numSegs; s++) {
    const iStart = floor(s * segLen);
    const iEnd = min(totalSamples, ceil((s + 1) * segLen) + 1);
    const uMid = pts[floor((iStart + iEnd) * 0.5)].u;

    const shadowCol = uMid < 0.28 ? "#103320" : (uMid < 0.62 ? "#3e6e54" : "#6c9980");
    brush.set("vein_stylus", shadowCol, 0.72);

    const segPts = [];
    for (let i = iStart; i <= iEnd; i++) {
      segPts.push([pts[i].x + 1.3, pts[i].y + 1.6, 0.9]);
    }
    brush.spline(segPts, 0.45);
  }

  // PASS 2: Translucent steamed rice-noodle body along the continuous thread
  // At outer loops (u < 0.3), the green banana leaf glows through the gelatinized rice starch.
  for (let s = 0; s < numSegs; s++) {
    const iStart = floor(s * segLen);
    const iEnd = min(totalSamples, ceil((s + 1) * segLen) + 1);
    const uMid = pts[floor((iStart + iEnd) * 0.5)].u;

    let bodyCol, bodyWt;
    if (uMid < 0.22) {
      bodyCol = "#7eb096"; // Translucent jade-tinted noodle edge over green leaf
      bodyWt = 0.88;
    } else if (uMid < 0.48) {
      bodyCol = "#b2d6c3"; // Semi-translucent celadon-white noodle
      bodyWt = 0.98;
    } else {
      bodyCol = "#e0f0e7"; // Warm steamed rice-flour body
      bodyWt = 1.05;
    }

    brush.set("noodle_body", bodyCol, bodyWt);
    const segPts = [];
    for (let i = iStart; i <= iEnd; i++) {
      segPts.push([pts[i].x, pts[i].y, 0.95]);
    }
    brush.spline(segPts, 0.45);
  }

  // PASS 3: THE UNBROKEN FINE WHITE PEN KOLAM LINE
  // Drawn continuously from i = 0 to totalSamples (where point[totalSamples] === point[0]).
  for (let s = 0; s < numSegs; s++) {
    const iStart = floor(s * segLen);
    const iEnd = min(totalSamples, ceil((s + 1) * segLen) + 1);
    const midPt = pts[floor((iStart + iEnd) * 0.5)];
    const uMid = midPt.u;

    // Outer loops have a fine, luminous translucent-white pen edge; inner loops are crisp pure white
    let penCol, penWt;
    if (uMid < 0.2) {
      penCol = "#dff2e7";
      penWt = 0.76;
    } else if (uMid < 0.45) {
      penCol = "#f2faf5";
      penWt = 0.88;
    } else {
      penCol = "#ffffff";
      penWt = 0.98;
    }

    brush.set("kolam_pen", penCol, penWt);
    const segPts = [];
    for (let i = iStart; i <= iEnd; i++) {
      // Slight pressure swell on outer crests of each kolam loop catching overhead light
      const p = 0.85 + 0.25 * max(0, pts[i].loopCos);
      segPts.push([pts[i].x, pts[i].y, p]);
    }
    brush.spline(segPts, 0.48);
  }

  // PASS 4: Specular light glints on the translucent outer noodle loop crests & central kolam eye
  brush.set("kolam_pen", "#ffffff", 1.05);
  for (let k = 0; k < params.L; k++) {
    // Index near the outer crest of loop k
    const idx = round((k / params.L) * totalSamples);
    if (idx >= 2 && idx <= totalSamples - 2) {
      const pA = pts[idx - 1];
      const pB = pts[idx];
      const pC = pts[idx + 1];
      // Highlight loops facing top-left light or on the outer translucent rim
      const lightFacing = cos(pB.theta + 135);
      if (pB.u < 0.26 || lightFacing > 0.25) {
        brush.spline([
          [pA.x, pA.y, 0.6],
          [pB.x, pB.y, 1.15],
          [pC.x, pC.y, 0.6]
        ], 0.4);
      }
    }
  }

  // Central kolam focal point (pulli) circled by the innermost rosette
  brush.set("kolam_pen", "#ffffff", 0.9);
  brush.circle(cx, cy, 4.5, 0.08);
}

// ============================================================================
// 4. OFF-CENTRE SMALL DISH OF COCONUT SAMBOL IN CORAL-PINK
// ============================================================================

function drawCoconutSambolDish(cx, cy, bowlR) {
  const innerR = bowlR - 11;

  // 1. Deep cast shadow of the ceramic dish on the banana leaf
  brush.noStroke();
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.45, 0.2);
  brush.fill("#020805", 210);
  brush.circle(cx + 10, cy + 13, bowlR + 6, 0.1);

  brush.fill("#05140c", 140);
  brush.circle(cx + 16, cy + 20, bowlR + 10, 0.14);
  brush.noFill();

  // 2. Dark matte celadon-charcoal stoneware bowl rim (stays in monochrome green-black family)
  brush.noStroke();
  brush.wash("#0d1f16", 255);
  brush.circle(cx, cy, bowlR, 0.06);

  brush.wash("#193628", 245);
  brush.circle(cx - 1.5, cy - 1.5, bowlR - 3.5, 0.05);

  // Dark inner bowl cavity shadow before the sambol mound
  brush.wash("#261010", 250);
  brush.circle(cx, cy, innerR, 0.05);
  brush.noWash();

  // Ceramic rim highlights (glossy dark green glaze catching top-left light)
  brush.set("kolam_pen", "#7eb398", 1.05);
  brush.arc(cx, cy, bowlR - 3, 185, 295);
  brush.set("kolam_pen", "#d7f2e4", 0.8);
  brush.arc(cx, cy, bowlR - 3, 210, 265);

  // Reflected bounce light on bottom-right rim
  brush.set("vein_stylus", "#3d6b52", 0.9);
  brush.arc(cx, cy, bowlR - 2.5, 15, 85);

  // 3. Base watercolour & wash layers of the Coral-Pink Coconut Sambol mound
  brush.noStroke();
  brush.wash("#9e302e", 250);
  brush.circle(cx + 1, cy + 1, innerR - 3, 0.12);
  brush.noWash();

  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.72, 0.45);

  // Deep crushed-chili coral shadow on bottom-right slope
  brush.fill("#872221", 170);
  brush.circle(cx + 10, cy + 10, innerR - 14, 0.2);

  // Vibrant midtone coral-pink body
  brush.fill("#d95650", 175);
  brush.circle(cx - 2, cy - 2, innerR - 7, 0.18);

  // Warm salmon-coral sunlit dome on upper-left
  brush.fill("#f27d75", 160);
  brush.circle(cx - 12, cy - 12, innerR * 0.66, 0.22);

  // Soft blush-coral peak highlight
  brush.fill("#fca69f", 125);
  brush.circle(cx - 18, cy - 18, innerR * 0.38, 0.2);
  brush.noFill();

  // 4. Hyperreal grated coconut shreds, crushed red chili flecks, shallots & curry leaf
  randomSeed(SEED + 999);

  // Draw 680 individual curved grated coconut shreds across the mound
  const shredCount = 680;
  for (let i = 0; i < shredCount; i++) {
    // Distribute denser toward the center dome
    const r = (innerR - 5) * pow(random(), 0.58);
    const ang = random(360);
    const sx = cx + r * cos(ang);
    const sy = cy + r * sin(ang);

    // 3D dome illumination (top-left light at -135 deg) + local clump bumpiness
    const nx = (sx - (cx - 14)) / innerR;
    const ny = (sy - (cy - 14)) / innerR;
    const clump = noise(sx * 0.06, sy * 0.06);
    const illum = constrain(0.68 - 0.48 * (nx * 0.7 + ny * 0.7) + (clump - 0.5) * 0.45, 0, 1);

    let col;
    if (illum < 0.26) {
      col = "#7d1e1d"; // Deep chili-coral crevice
    } else if (illum < 0.44) {
      col = "#b83c39"; // Rich terracotta coral
    } else if (illum < 0.62) {
      col = "#e3625b"; // Vibrant coral-pink
    } else if (illum < 0.78) {
      col = "#f58b84"; // Luminous salmon-coral shred
    } else if (illum < 0.91) {
      col = "#fcbab4"; // Pale blush-pink grated coconut
    } else {
      col = "#ffebe8"; // Fresh white-blush coconut catching direct glint
    }

    const len = random(4.5, 10.5);
    const sAng = random(360);
    const curveAng = sAng + random(-38, 38);
    const p1 = [sx - 0.5 * len * cos(sAng), sy - 0.5 * len * sin(sAng), 0.7];
    const p2 = [sx, sy, 1.15];
    const p3 = [sx + 0.5 * len * cos(curveAng), sy + 0.5 * len * sin(curveAng), 0.6];

    brush.set("coconut_shred", col, random(0.65, 1.1));
    brush.spline([p1, p2, p3], 0.45);
  }

  // Crushed dried red chili skin flecks & tiny golden chili seeds
  for (let i = 0; i < 48; i++) {
    const r = (innerR - 9) * sqrt(random());
    const ang = random(360);
    const fx = cx + r * cos(ang);
    const fy = cy + r * sin(ang);
    const fAng = random(360);

    // Dark crimson chili flake
    brush.set("coconut_shred", i % 2 === 0 ? "#570d0f" : "#781517", random(0.85, 1.25));
    brush.line(fx, fy, fx + 3.8 * cos(fAng), fy + 3.8 * sin(fAng));

    // Tiny golden-ochre chili seed beside some flakes
    if (i % 5 === 0) {
      brush.set("kolam_pen", "#ebc88d", 0.95);
      brush.circle(fx + 2, fy - 1, 1.4, 0.1);
    }
  }

  // Tiny translucent rose-mauve shallot pieces
  for (let i = 0; i < 18; i++) {
    const r = (innerR - 14) * sqrt(random());
    const ang = random(360);
    const mx = cx + r * cos(ang);
    const my = cy + r * sin(ang);
    const mAng = random(360);
    brush.set("coconut_shred", "#e8b5be", 0.9);
    brush.line(mx, my, mx + 5 * cos(mAng), my + 5 * sin(mAng));
    brush.set("kolam_pen", "#fff0f3", 0.55);
    brush.line(mx, my, mx + 3.5 * cos(mAng), my + 3.5 * sin(mAng));
  }

  // Small glossy dark green curry leaf resting on the coral-pink mound (ties accent to monochrome leaf)
  const lx = cx + 12;
  const ly = cy - 6;
  brush.noStroke();
  brush.wash("#0b2415", 245);
  brush.beginShape(0.35);
  brush.vertex(lx - 16, ly + 6);
  brush.vertex(lx - 5, ly - 5);
  brush.vertex(lx + 14, ly - 8);
  brush.vertex(lx + 4, ly + 5);
  brush.endShape(true);
  brush.noWash();

  // Curry leaf central vein & glossy highlight
  brush.set("vein_stylus", "#5ca177", 0.75);
  brush.spline([[lx - 15, ly + 5.5], [lx - 1, ly - 1], [lx + 13, ly - 7.5]], 0.3);
  brush.set("kolam_pen", "#c5edd4", 0.55);
  brush.line(lx - 6, ly - 1.5, lx + 4, ly - 4.5);

  // Stray coral-pink sambol crumbs on the bowl rim and fallen onto the banana leaf
  const strayCrumbs = [
    [cx - bowlR + 5, cy + 18, "#f07c74"],
    [cx - bowlR + 3, cy + 22, "#fcc0b9"],
    [cx - bowlR - 14, cy + 38, "#e6675f"],
    [cx - bowlR - 18, cy + 42, "#fab2aa"],
    [cx + 28, cy + bowlR + 12, "#eb7169"]
  ];
  for (const [sx, sy, scol] of strayCrumbs) {
    brush.set("coconut_shred", "#06140c", 0.9);
    brush.line(sx + 1, sy + 1.5, sx + 4.5, sy + 2.5);
    brush.set("coconut_shred", scol, 0.95);
    brush.line(sx, sy, sx + 3.5, sy + 1);
  }
}

// ============================================================================
// 5. STEAM BEADS (CONDENSATION DROPLETS) CATCHING THE LIGHT
// ============================================================================

function drawSteamBeads(hopperCenters, sambolCenter) {
  randomSeed(SEED + 2025);

  const beads = [];

  // Cluster warm condensation beads on the glossy banana leaf around the string hoppers
  for (const h of hopperCenters) {
    const count = 11;
    for (let i = 0; i < count; i++) {
      const ang = random(360);
      const dist = random(135, 178);
      const bx = h.x + dist * cos(ang);
      const by = h.y + dist * sin(ang);
      const rad = random(1.8, 5.6);
      beads.push({ x: bx, y: by, r: rad, onNoodle: false });
    }

    // Tiny glistening moisture beads clinging right to the translucent outer noodle loops
    for (let i = 0; i < 5; i++) {
      const ang = random(360);
      const dist = random(108, 130);
      const bx = h.x + dist * cos(ang);
      const by = h.y + dist * sin(ang);
      beads.push({ x: bx, y: by, r: random(1.5, 3.0), onNoodle: true });
    }
  }

  // A few larger jewel-like condensation droplets along the midrib & glossy leaf swells
  const heroDrops = [
    { x: 435, y: 422, r: 7.2 },
    { x: 752, y: 446, r: 6.4 },
    { x: 158, y: 448, r: 5.8 },
    { x: 442, y: 782, r: 6.8 },
    { x: 760, y: 774, r: 6.0 },
    { x: 768, y: 128, r: 5.5 },
    { x: 1068, y: 412, r: 5.2 }
  ];
  for (const d of heroDrops) {
    beads.push({ x: d.x, y: d.y, r: d.r, onNoodle: false });
  }

  // Filter out any bead that lands inside the sambol dish or outside the leaf bounds
  const validBeads = beads.filter(b => {
    if (b.x < 75 || b.x > 1125 || b.y < 85 || b.y > 1115) return false;
    if (dist(b.x, b.y, sambolCenter.x, sambolCenter.y) < 116) return false;
    if (!b.onNoodle) {
      for (const h of hopperCenters) {
        if (dist(b.x, b.y, h.x, h.y) < 131) return false;
      }
    }
    return true;
  });

  // Render each steam bead with optical lens refraction, emerald caustic & crisp white glint
  for (const b of validBeads) {
    const { x, y, r, onNoodle } = b;

    if (onNoodle) {
      // Tiny luminous moisture bead on a translucent noodle strand
      brush.set("vein_stylus", "#598c72", 0.65);
      brush.circle(x + 0.8, y + 0.8, r, 0.05);
      brush.set("kolam_pen", "#ffffff", 0.95);
      brush.line(x - r * 0.35, y - r * 0.35, x - r * 0.1, y - r * 0.1);
      continue;
    }

    // 1. Dark cast shadow on bottom-right of water drop
    brush.noStroke();
    brush.wash("#020804", 215);
    brush.circle(x + r * 0.38, y + r * 0.42, r * 0.95, 0.08);

    // 2. Dark refracted interior on upper-left half of droplet
    brush.wash("#0a2415", 230);
    brush.circle(x, y, r, 0.06);

    // 3. Luminous refracted emerald-chartreuse caustic on lower-right inside of droplet
    brush.wash("#5bb880", 210);
    brush.circle(x + r * 0.22, y + r * 0.24, r * 0.62, 0.06);

    if (r > 3.2) {
      brush.wash("#a8f0c2", 195);
      brush.circle(x + r * 0.28, y + r * 0.3, r * 0.35, 0.05);
    }
    brush.noWash();

    // 4. Crisp droplet contour & bright specular pinpoint highlight on upper-left dome
    brush.set("vein_stylus", "#1f5436", 0.6);
    brush.circle(x, y, r, 0.05);

    brush.set("kolam_pen", "#ffffff", r > 4.5 ? 1.15 : 0.85);
    brush.line(x - r * 0.38, y - r * 0.38, x - r * 0.15, y - r * 0.22);

    // Secondary reflected rim glint on bottom-right edge
    if (r > 3.8) {
      brush.set("kolam_pen", "#d7fae4", 0.6);
      brush.arc(x, y, r * 0.82, 20, 75);
    }
  }
}

// Hyperrealistic Graphite & Charcoal on Pewter-Silver Plate:
// Open Cardboard Egg Carton with Cracked Egg & Slumped Glossy Yolk
// Enclosed in a Tarnished Oval & Faint Gilt Brass Mat Frame

const OVAL_CX = 600;
const OVAL_CY = 600;
const OVAL_RX = 456;
const OVAL_RY = 492;

// 3D Camera parameters
const CAM_POS = { x: 0.0, y: -4.55, z: 3.48 };
const CAM_TAR = { x: 0.0, y: -0.02, z: 0.04 };
const FOCAL_PX = 1190;
const SCREEN_CX = 600;
const SCREEN_CY = 572;
const ROT_Z = -13.5 * (Math.PI / 180);
const COS_RZ = Math.cos(ROT_Z);
const SIN_RZ = Math.sin(ROT_Z);

let camF, camR, camU, focalDist;
let zBuf;
const Z_RES = 400; // 400x400 depth buffer over 1200x1200 canvas

function initCamera() {
  let dx = CAM_TAR.x - CAM_POS.x;
  let dy = CAM_TAR.y - CAM_POS.y;
  let dz = CAM_TAR.z - CAM_POS.z;
  let len = Math.hypot(dx, dy, dz);
  camF = { x: dx / len, y: dy / len, z: dz / len };
  camR = { x: 1, y: 0, z: 0 };
  camU = {
    x: camR.y * camF.z - camR.z * camF.y,
    y: camR.z * camF.x - camR.x * camF.z,
    z: camR.x * camF.y - camR.y * camF.x
  };
  // Focal plane centered squarely on the cracked egg and slumped yolk in front-center cup
  let eggP = worldToCam(0.08, -0.60, -0.04);
  focalDist = eggP.d;
  zBuf = new Float32Array(Z_RES * Z_RES);
  zBuf.fill(1e9);
}

function worldToCam(wx, wy, wz) {
  let rx = wx * COS_RZ - wy * SIN_RZ;
  let ry = wx * SIN_RZ + wy * COS_RZ;
  let rz = wz;
  let vx = rx - CAM_POS.x;
  let vy = ry - CAM_POS.y;
  let vz = rz - CAM_POS.z;
  let d = vx * camF.x + vy * camF.y + vz * camF.z;
  let r = vx * camR.x + vy * camR.y + vz * camR.z;
  let u = vx * camU.x + vy * camU.y + vz * camU.z;
  return {
    sx: SCREEN_CX + (r / d) * FOCAL_PX,
    sy: SCREEN_CY - (u / d) * FOCAL_PX,
    d: d,
    defocus: Math.abs(d - focalDist),
    rx, ry, rz
  };
}

function insideOval(sx, sy, margin = 0) {
  let nx = (sx - OVAL_CX) / (OVAL_RX - margin);
  let ny = (sy - OVAL_CY) / (OVAL_RY - margin);
  return nx * nx + ny * ny <= 1.0;
}

function ovalNormDist(sx, sy) {
  let nx = (sx - OVAL_CX) / OVAL_RX;
  let ny = (sy - OVAL_CY) / OVAL_RY;
  return Math.hypot(nx, ny);
}

function sCurve(t) {
  t = Math.max(0, Math.min(1, t));
  return t * t * (3 - 2 * t);
}

// 3D analytical model of the moulded pulp 6-egg carton body
function cartonSurface(x, y) {
  // Base rim height
  let z = 0.14;
  let cupDepression = 0;
  let minCupDist = 99;
  let nearestCol = 0, nearestRow = 0;

  // 6 Egg cups: 3 columns (-1.15, 0, 1.15) x 2 rows (-0.57, 0.57)
  for (let c = -1; c <= 1; c++) {
    let cx = c * 1.15;
    for (let r = 0; r <= 1; r++) {
      let cy = r === 0 ? -0.57 : 0.57;
      let dx = x - cx;
      let dy = y - cy;
      let d = Math.hypot(dx, dy);
      if (d < minCupDist) {
        minCupDist = d;
        nearestCol = c;
        nearestRow = r;
      }
      if (d < 0.64) {
        let ang = Math.atan2(dy, dx);
        // Moulded cushion flutes inside each cup wall
        let flute = 1.0 + 0.055 * Math.cos(4 * ang) * sCurve(d / 0.55);
        let q = (d * flute) / 0.61;
        if (q < 1.0) {
          let bowl = Math.pow(1.0 - q * q, 1.55);
          // Flat bottom pad at very bottom of cup
          if (bowl > 0.82) bowl = 0.82 + (bowl - 0.82) * 0.25;
          cupDepression += 0.66 * bowl;
        }
      }
    }
  }
  z -= cupDepression;

  // 2 Tall central separator cones at (-0.575, 0) and (+0.575, 0) + 2 half side posts
  const cones = [
    { x: -0.575, y: 0.0, h: 0.56, rad: 0.44 },
    { x: 0.575, y: 0.0, h: 0.56, rad: 0.44 },
    { x: -1.68, y: 0.0, h: 0.26, rad: 0.32 },
    { x: 1.68, y: 0.0, h: 0.26, rad: 0.32 }
  ];
  let coneLift = 0;
  for (let k = 0; k < cones.length; k++) {
    let cn = cones[k];
    let dx = x - cn.x;
    let dy = y - cn.y;
    // Slightly elliptical base compressed in y
    let d = Math.hypot(dx * 0.95, dy * 1.08);
    if (d < cn.rad) {
      let q = 1.0 - d / cn.rad;
      let profile = sCurve(q);
      // Flat dimpled crown on the tall separator cones
      if (q > 0.72) {
        let crownT = (q - 0.72) / 0.28;
        profile = sCurve(0.72) + 0.04 * Math.sin(crownT * Math.PI) - 0.055 * crownT * crownT;
      }
      coneLift = Math.max(coneLift, cn.h * profile);
    }
  }
  z += coneLift;

  // Transverse ribs between cups
  let ribY = Math.exp(-Math.pow(y / 0.16, 2)) * 0.09;
  let ribX = (Math.exp(-Math.pow((x + 0.575) / 0.14, 2)) + Math.exp(-Math.pow((x - 0.575) / 0.14, 2))) * 0.08;
  z += Math.max(ribY, ribX) * (1.0 - sCurve(Math.max(0, (Math.abs(x) - 1.55) / 0.25)));

  // Outer flanged rim and rolled deckle lip
  let bx = Math.max(0, Math.abs(x) - 1.62);
  let by = Math.max(0, Math.abs(y) - 1.05);
  let rimDist = Math.hypot(bx, by);
  if (rimDist > 0) {
    // Flatten toward flange plane z = 0.15, then roll down at edge
    let flangeBlend = sCurve(rimDist / 0.16);
    z = z * (1 - flangeBlend) + 0.16 * flangeBlend;
    if (rimDist > 0.14) {
      let drop = (rimDist - 0.14) / 0.12;
      z -= 0.09 * drop * drop;
    }
  }

  // Front locking apron flap (y < -1.12)
  let isFlap = false;
  let flapHole = false;
  if (y < -1.12 && Math.abs(x) < 1.66) {
    isFlap = true;
    let fy = (-1.12 - y) / 0.36; // 0 to 1
    // Crease groove at hinge line y = -1.12
    let crease = -0.025 * Math.exp(-Math.pow(fy / 0.08, 2));
    z = 0.15 - fy * 0.44 + crease;
    // Two stamped locking tab recesses on the front apron
    for (let tx of [-0.62, 0.62]) {
      let tdx = (x - tx) / 0.19;
      let tdy = (fy - 0.52) / 0.25;
      let td = Math.hypot(tdx, tdy);
      if (td < 1.0) {
        z -= 0.06 * sCurve(1.0 - td);
        if (td < 0.62) flapHole = true;
      }
    }
  }

  // Moulded papier-mache micro-bumpiness
  let n1 = noise(x * 8.5 + 10, y * 8.5 + 10) - 0.5;
  let n2 = noise(x * 24.0 + 30, y * 24.0 + 30) - 0.5;
  z += n1 * 0.018 + n2 * 0.007;

  return { z, minCupDist, nearestCol, nearestRow, isFlap, flapHole };
}

// 3D analytical model of the open hinged lid rising at the back
function lidSurface(u, v) {
  // u in [-1.76, 1.76], v in [0, 1.52] along lid upward slant
  let hingeY = 1.14;
  let hingeZ = 0.15;
  let tiltAngle = 64 * (Math.PI / 180);
  // Slight organic bow in cardboard lid
  let bow = -0.04 * Math.pow(u / 1.75, 2) * sCurve(v / 1.2);

  // Depth recession into the lid tray (deep flat-topped cover)
  let mx = Math.max(0, 1.0 - Math.pow(u / 1.56, 6));
  let my = Math.sin(Math.min(1, Math.max(0, (v - 0.08) / 1.32)) * Math.PI);
  let trayDepth = 0.28 * sCurve(mx) * sCurve(my);

  // Central stiffening groove down the middle of the lid (matching split-top egg cartons)
  let centerGroove = Math.exp(-Math.pow(u / 0.14, 2)) * 0.09 * sCurve(my);
  // Two vertical indent ribs at u = +-0.58
  let sideIndent = (Math.exp(-Math.pow((u - 0.58) / 0.12, 2)) + Math.exp(-Math.pow((u + 0.58) / 0.12, 2))) * 0.06 * sCurve(my);

  let localNormalOffset = trayDepth - centerGroove - sideIndent + bow;

  // Locking nubs on top front lip of lid (v near 1.38)
  for (let nx of [-0.62, 0.62]) {
    let nd = Math.hypot((u - nx) / 0.16, (v - 1.44) / 0.09);
    if (nd < 1.0) {
      localNormalOffset -= 0.09 * sCurve(1.0 - nd);
    }
  }

  let n1 = (noise(u * 7 + 50, v * 7 + 50) - 0.5) * 0.018;
  localNormalOffset += n1;

  let wx = u;
  let wy = hingeY + v * Math.cos(tiltAngle) + localNormalOffset * Math.sin(tiltAngle);
  let wz = hingeZ + v * Math.sin(tiltAngle) - localNormalOffset * Math.cos(tiltAngle);

  return { x: wx, y: wy, z: wz, trayDepth };
}

function getCartonNormal(x, y) {
  let eps = 0.015;
  let z0 = cartonSurface(x, y).z;
  let zx = cartonSurface(x + eps, y).z;
  let zy = cartonSurface(x, y + eps).z;
  let nx = -(zx - z0) / eps;
  let ny = -(zy - z0) / eps;
  let nz = 1.0;
  let l = Math.hypot(nx, ny, nz);
  return { x: nx / l, y: ny / l, z: nz / l, z0 };
}

// Compute Daguerreotype silver-plate illumination (with solarized highlight reversal)
function computePlateLight(wx, wy, wz, nx, ny, nz) {
  // Primary upper-left studio skylight
  let l1x = -0.46, l1y = -0.38, l1z = 0.80;
  // Secondary soft fill from right-front
  let l2x = 0.62, l2y = -0.25, l2z = 0.35;

  let diff1 = Math.max(0, nx * l1x + ny * l1y + nz * l1z);
  let diff2 = Math.max(0, nx * l2x + ny * l2y + nz * l2z);

  // Ambient occlusion inside deep cups and behind cones
  let ao = sCurve((wz + 0.52) / 0.92);
  ao = 0.25 + 0.75 * ao;

  // Wet pulp darkening under the cracked egg & spilled albumen in front-center cup
  let wetDist = Math.hypot((wx - 0.10) * 1.1, (wy + 0.59) * 1.0);
  let wetFactor = 1.0;
  if (wetDist < 0.48 && wz < 0.05) {
    wetFactor = 0.62 + 0.38 * sCurve(wetDist / 0.48);
  }

  let rawLight = (0.14 + 0.74 * diff1 + 0.22 * diff2) * ao * wetFactor;

  // Specular component for silver-plate highlight reversal
  let hx = l1x - 0.05, hy = l1y - 0.55, hz = l1z + 0.45;
  let hl = Math.hypot(hx, hy, hz);
  hx /= hl; hy /= hl; hz /= hl;
  let spec = Math.pow(Math.max(0, nx * hx + ny * hy + nz * hz), 14);

  let val = rawLight + spec * 0.38 * ao;
  let reversed = false;
  if (val > 0.90) {
    // Daguerreotype highlight reversal (solarization into cool pewter core)
    reversed = true;
    val = 0.90 - (val - 0.90) * 0.85;
  }
  return { val: Math.max(0.04, Math.min(0.98, val)), rawLight, spec, ao, reversed, wetFactor };
}

function recordZ(sx, sy, d) {
  let gx = Math.floor((sx / 1200) * Z_RES);
  let gy = Math.floor((sy / 1200) * Z_RES);
  if (gx >= 0 && gx < Z_RES && gy >= 0 && gy < Z_RES) {
    for (let oy = -1; oy <= 1; oy++) {
      let yy = gy + oy;
      if (yy < 0 || yy >= Z_RES) continue;
      for (let ox = -1; ox <= 1; ox++) {
        let xx = gx + ox;
        if (xx < 0 || xx >= Z_RES) continue;
        let idx = yy * Z_RES + xx;
        if (d < zBuf[idx]) zBuf[idx] = d;
      }
    }
  }
}

function isVisible(sx, sy, d, tol = 0.085) {
  let gx = Math.floor((sx / 1200) * Z_RES);
  let gy = Math.floor((sy / 1200) * Z_RES);
  if (gx < 0 || gx >= Z_RES || gy < 0 || gy >= Z_RES) return false;
  return d <= zBuf[gy * Z_RES + gx] + tol;
}

// Helper for fracture rim height on main cracked eggshell at (0.01, -0.56)
function mainShellCrackZ(ang) {
  // Low saddle on front-right (-1.3 to +0.4 rad) where yolk slumps out,
  // jagged high peaks on left and back
  let saddle = -0.11 * Math.exp(-Math.pow((ang + 0.42) / 0.85, 2));
  let jag =
    0.032 * Math.sin(ang * 3.0 + 0.4) +
    0.022 * Math.cos(ang * 7.0 - 0.8) +
    0.014 * Math.sin(ang * 13.0 + 1.9);
  // Sharp triangular tooth on left-front
  let tooth = 0.045 * Math.exp(-Math.pow((ang + 1.85) / 0.28, 2));
  return -0.01 + saddle + jag + tooth;
}

function buildDepthBuffer() {
  // 1. Carton lower body
  for (let ix = 0; ix <= 220; ix++) {
    let x = -1.78 + (ix / 220) * 3.56;
    for (let iy = 0; iy <= 180; iy++) {
      let y = -1.48 + (iy / 180) * 2.64;
      if (Math.abs(x) > 1.66 && y < -1.14) continue;
      let surf = cartonSurface(x, y);
      if (surf.flapHole) continue;
      let p = worldToCam(x, y, surf.z);
      recordZ(p.sx, p.sy, p.d);
    }
  }
  // 2. Open lid in back
  for (let iu = 0; iu <= 150; iu++) {
    let u = -1.74 + (iu / 150) * 3.48;
    for (let iv = 0; iv <= 110; iv++) {
      let v = (iv / 110) * 1.48;
      if (Math.abs(u) > 1.62 && v > 1.38) continue;
      let lp = lidSurface(u, v);
      let p = worldToCam(lp.x, lp.y, lp.z);
      recordZ(p.sx, p.sy, p.d);
    }
  }
  // 3. Main cracked eggshell + slumped yolk in front-center cup
  for (let ia = 0; ia < 90; ia++) {
    let ang = -Math.PI + (ia / 90) * Math.PI * 2;
    let zTop = mainShellCrackZ(ang);
    for (let iz = 0; iz <= 25; iz++) {
      let z = -0.34 + (iz / 25) * (zTop + 0.34);
      let hNorm = (z + 0.12) / 0.32;
      let rad = 0.39 * Math.sqrt(Math.max(0.05, 1.0 - 0.55 * hNorm * hNorm));
      let wx = -0.01 + Math.cos(ang) * rad;
      let wy = -0.56 + Math.sin(ang) * rad * 0.94;
      let p = worldToCam(wx, wy, z);
      recordZ(p.sx, p.sy, p.d - 0.02);
    }
  }
  // Slumped yolk dome
  for (let ix = -30; ix <= 30; ix++) {
    for (let iy = -30; iy <= 30; iy++) {
      let ux = ix / 30;
      let uy = iy / 30;
      let r2 = ux * ux + uy * uy;
      if (r2 > 1.0) continue;
      let wx = 0.11 + ux * 0.28;
      let wy = -0.61 + uy * 0.25;
      let wz = -0.09 + 0.19 * Math.pow(1.0 - r2, 0.65) - 0.04 * uy;
      let p = worldToCam(wx, wy, wz);
      recordZ(p.sx, p.sy, p.d - 0.03);
    }
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8419);
  noiseSeed(8419);
  initCamera();
  buildDepthBuffer();
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Base pewter-silver metallic ground
  background("#767c83");
  renderPewterPlateGround();

  // 2. Out-of-focus open carton lid in upper background
  renderOpenLid();

  // 3. Moulded pulp carton body: tonal washes & charcoal underpainting
  renderCartonUnderpainting();

  // 4. Moulded pulp fibres rendered grain-by-grain with shallow DOF
  renderCartonPulpFibres();

  // 5. Detached left eggshell half (in front-left cup)
  renderDetachedLeftShell();

  // 6. Cracked main eggshell, spilled albumen & slumped glossy amber yolk
  renderMainCrackedEggAndYolk();

  // 7. Iridescent tarnish blooms (peacock blue, bronze, rose) around oval edge
  renderTarnishBlooms();

  // 8. Faint gilt brass mat frame & beveled oval window enclosing everything
  renderGiltBrassMatFrame();

  noLoop();
}

// ============================================================================
// LAYER 1: PEWTER-SILVER PLATE GROUND & DIAGONAL BUFFING STRIATIONS
// ============================================================================
function renderPewterPlateGround() {
  brush.noStroke();

  // Soft cloudy metallic pewter washes inside the oval
  const groundBatches = [
    { col: "#61676f", op: 55, bleed: 0.42, count: 8, rad: [190, 320] },
    { col: "#899098", op: 48, bleed: 0.38, count: 7, rad: [160, 290] },
    { col: "#525860", op: 50, bleed: 0.40, count: 6, rad: [140, 250] },
    { col: "#9ea5ad", op: 38, bleed: 0.35, count: 5, rad: [120, 220] }
  ];

  for (let b of groundBatches) {
    brush.fill(b.col, b.op);
    brush.fillBleed(b.bleed, "out");
    brush.fillTexture(0.65, 0.35);
    for (let i = 0; i < b.count; i++) {
      let ang = random(360);
      let dist = random(40, 360);
      let cx = OVAL_CX + cos(ang) * dist * 0.85;
      let cy = OVAL_CY + sin(ang) * dist;
      let rx = random(b.rad[0], b.rad[1]);
      let ry = rx * random(0.65, 1.15);
      drawSoftEllipsePoly(cx, cy, rx, ry, 14);
    }
  }
  brush.noFill();

  // Fine diagonal silver-plate polishing striations (27 degrees)
  brush.set("2H", "#adb4bc", 0.14);
  for (let i = 0; i < 240; i++) {
    let sx = random(150, 1050);
    let sy = random(120, 1080);
    if (!insideOval(sx, sy, 15)) continue;
    let len = random(45, 180);
    let ex = sx + cos(27) * len;
    let ey = sy + sin(27) * len;
    if (!insideOval(ex, ey, 15)) continue;
    if (i % 2 === 0) {
      brush.set("2H", "#9ca3ab", random(0.11, 0.17));
    } else {
      brush.set("2H", "#5f656d", random(0.11, 0.16));
    }
    brush.line(sx, sy, ex, ey);
  }
}

function drawSoftEllipsePoly(cx, cy, rx, ry, steps = 14) {
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let rMod = 1.0 + (noise(cx * 0.01 + i, cy * 0.01) - 0.5) * 0.22;
    let px = cx + cos(a) * rx * rMod;
    let py = cy + sin(a) * ry * rMod;
    // Clamp inside oval
    let nd = ovalNormDist(px, py);
    if (nd > 0.98) {
      px = OVAL_CX + ((px - OVAL_CX) / nd) * 0.98;
      py = OVAL_CY + ((py - OVAL_CY) / nd) * 0.98;
    }
    brush.vertex(px, py);
  }
  brush.endShape(true);
}

// ============================================================================
// LAYER 2: OUT-OF-FOCUS OPEN CARTON LID (BACKGROUND)
// ============================================================================
function renderOpenLid() {
  brush.noStroke();

  // Large tonal wash planes for the recessed lid tray and bright lid rim
  // Left, center, and right lid recess washes
  const lidZones = [
    { u0: -1.52, u1: -0.10, v0: 0.12, v1: 1.32, col: "#50565e", op: 88 },
    { u0: 0.10, u1: 1.52, v0: 0.12, v1: 1.32, col: "#585e67", op: 82 },
    { u0: -1.68, u1: 1.68, v0: 1.26, v1: 1.48, col: "#9aa2aa", op: 75 },
    { u0: -0.22, u1: 0.22, v0: 0.10, v1: 1.36, col: "#858c94", op: 70 },
    { u0: -1.72, u1: -1.42, v0: 0.05, v1: 1.42, col: "#8e969e", op: 68 }
  ];

  for (let z of lidZones) {
    brush.fill(z.col, z.op);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.55, 0.3);
    brush.beginShape(0.35);
    const pts = [
      lidSurface(z.u0, z.v0),
      lidSurface((z.u0 + z.u1) * 0.5, z.v0),
      lidSurface(z.u1, z.v0),
      lidSurface(z.u1, (z.v0 + z.v1) * 0.5),
      lidSurface(z.u1, z.v1),
      lidSurface((z.u0 + z.u1) * 0.5, z.v1),
      lidSurface(z.u0, z.v1),
      lidSurface(z.u0, (z.v0 + z.v1) * 0.5)
    ];
    for (let pt of pts) {
      let sp = worldToCam(pt.x, pt.y, pt.z);
      brush.vertex(sp.sx, sp.sy);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // Out-of-focus charcoal and soft graphite strokes on the lid
  for (let i = 0; i < 950; i++) {
    let u = random(-1.72, 1.72);
    let v = random(0.02, 1.48);
    if (Math.abs(u) > 1.60 && v > 1.38) continue;

    let lp = lidSurface(u, v);
    let sp = worldToCam(lp.x, lp.y, lp.z);
    if (!insideOval(sp.sx, sp.sy, 22)) continue;
    if (!isVisible(sp.sx, sp.sy, sp.d, 0.14)) continue;

    // Estimate lid shading: recessed interior is darker, outer flange & center rib are lighter
    let rimLight = 1.0 - sCurve(lp.trayDepth / 0.26);
    let sideGrad = 0.55 - 0.18 * (u / 1.7);
    let shade = rimLight * 0.52 + sideGrad * 0.48 + (noise(u * 4, v * 4) - 0.5) * 0.18;

    // Shallow DOF: lid is far behind focal plane (defocus ~ 0.6 to 1.2)
    let blurW = map(sp.defocus, 0.3, 1.3, 0.32, 0.72, true);
    let len = random(8, 22);
    let ang = random(-18, 18) + (Math.abs(u) > 1.42 ? 78 : 0);

    if (shade < 0.42) {
      brush.set("charcoal", shade < 0.28 ? "#32373e" : "#484e56", blurW * 0.75);
    } else if (shade > 0.68) {
      brush.set("cpencil", shade > 0.80 ? "#c2c9d1" : "#9fa7b0", blurW * 0.7);
    } else {
      brush.set("cpencil", "#697078", blurW * 0.65);
    }

    let x2 = sp.sx + cos(ang) * len;
    let y2 = sp.sy + sin(ang) * len;
    brush.line(sp.sx, sp.sy, x2, y2);
  }

  // Soft blurred upper deckle edge of the open lid
  for (let pass = 0; pass < 3; pass++) {
    let vOff = 1.46 + (pass - 1) * 0.018;
    brush.set("cpencil", pass === 1 ? "#b8c0c8" : "#889098", 0.48 - pass * 0.08);
    let pts = [];
    for (let iu = 0; iu <= 28; iu++) {
      let u = -1.62 + (iu / 28) * 3.24;
      let lp = lidSurface(u, vOff);
      let sp = worldToCam(lp.x, lp.y, lp.z);
      if (insideOval(sp.sx, sp.sy, 18)) {
        pts.push([sp.sx + random(-2, 2), sp.sy + random(-2, 2)]);
      }
    }
    if (pts.length > 3) brush.spline(pts, 0.4);
  }
}

// ============================================================================
// LAYER 3: MOULDED PULP CARTON BODY — TONAL WASHES & CHARCOAL MASSING
// ============================================================================
function renderCartonUnderpainting() {
  brush.noStroke();

  // 1. Deep shadow washes inside the 6 moulded egg cups
  const cupCenters = [
    { c: -1, r: 1, col: "#2e333a", op: 115, rx: 0.48 },
    { c: 0,  r: 1, col: "#2b3037", op: 120, rx: 0.48 },
    { c: 1,  r: 1, col: "#343941", op: 110, rx: 0.48 },
    { c: -1, r: 0, col: "#282c33", op: 130, rx: 0.50 },
    { c: 0,  r: 0, col: "#24282f", op: 135, rx: 0.50 },
    { c: 1,  r: 0, col: "#30353d", op: 120, rx: 0.50 }
  ];

  for (let cup of cupCenters) {
    let cx = cup.c * 1.15;
    let cy = cup.r === 0 ? -0.57 : 0.57;
    brush.fill(cup.col, cup.op);
    brush.fillBleed(0.22, "in");
    brush.fillTexture(0.65, 0.45);
    brush.beginShape(0.4);
    for (let i = 0; i < 14; i++) {
      let a = (i / 14) * Math.PI * 2;
      // Offset shadow toward upper-left (away from light)
      let wx = cx - 0.05 + Math.cos(a) * cup.rx;
      let wy = cy + 0.04 + Math.sin(a) * cup.rx * 0.9;
      let wz = cartonSurface(wx, wy).z;
      let sp = worldToCam(wx, wy, wz);
      brush.vertex(sp.sx, sp.sy);
    }
    brush.endShape(true);
  }

  // 2. Luminous silver-pewter washes on the sunlit right walls of cups & separator cones
  brush.fill("#b4bcc4", 82);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.35);
  for (let c = -1; c <= 1; c++) {
    for (let r = 0; r <= 1; r++) {
      let cx = c * 1.15 + 0.18;
      let cy = (r === 0 ? -0.57 : 0.57) + 0.08;
      brush.beginShape(0.4);
      for (let i = 0; i < 10; i++) {
        let a = -0.9 + (i / 9) * 1.9;
        let rad = i < 5 ? 0.44 : 0.22;
        let ang = i < 5 ? a : (1.0 - (i - 5) / 4 * 1.9);
        let wx = cx + Math.cos(ang) * rad;
        let wy = cy + Math.sin(ang) * rad;
        let wz = cartonSurface(wx, wy).z;
        let sp = worldToCam(wx, wy, wz);
        brush.vertex(sp.sx, sp.sy);
      }
      brush.endShape(true);
    }
  }

  // 3. Bright silver crowns & dark right-side shadow slopes of the 2 tall separator cones
  for (let cx of [-0.575, 0.575]) {
    // Sunlit left-front slope of cone
    brush.fill("#cfd6de", 95);
    brush.fillBleed(0.15, "out");
    brush.beginShape(0.38);
    for (let i = 0; i < 12; i++) {
      let a = (i / 12) * Math.PI * 2;
      let wx = cx - 0.08 + Math.cos(a) * 0.25;
      let wy = -0.05 + Math.sin(a) * 0.22;
      let wz = cartonSurface(wx, wy).z;
      let sp = worldToCam(wx, wy, wz);
      brush.vertex(sp.sx, sp.sy);
    }
    brush.endShape(true);

    // Reversed-highlight cool pewter dimple on flat top of cone
    brush.fill("#858e98", 90);
    brush.fillBleed(0.1, "in");
    brush.beginShape(0.4);
    for (let i = 0; i < 10; i++) {
      let a = (i / 10) * Math.PI * 2;
      let wx = cx + Math.cos(a) * 0.11;
      let wy = Math.sin(a) * 0.095;
      let wz = cartonSurface(wx, wy).z;
      let sp = worldToCam(wx, wy, wz);
      brush.vertex(sp.sx, sp.sy);
    }
    brush.endShape(true);
  }

  // 4. Shaded front locking apron flap along the foreground
  brush.fill("#3b4048", 95);
  brush.fillBleed(0.16, "in");
  brush.beginShape(0.25);
  const flapPts = [
    [-1.62, -1.13], [0, -1.13], [1.62, -1.13],
    [1.58, -1.46], [0, -1.46], [-1.58, -1.46]
  ];
  for (let fp of flapPts) {
    let wz = cartonSurface(fp[0], fp[1]).z;
    let sp = worldToCam(fp[0], fp[1], wz);
    brush.vertex(sp.sx, sp.sy);
  }
  brush.endShape(true);

  brush.noFill();
}

// ============================================================================
// LAYER 4: MOULDED PULP FIBRES — RENDERED GRAIN BY GRAIN WITH SHALLOW DOF
// ============================================================================
function renderCartonPulpFibres() {
  // Palette from deep charcoal crevices to reversed pewter & bright silver-white highlights
  const darkBuckets = ["#1b1e23", "#272b32", "#343942", "#434952", "#535a64"];
  const lightBuckets = ["#8c949e", "#a2aab4", "#b8c0ca", "#cfd7e0", "#e6ecf2", "#f4f7fa"];

  // Pass A: Underlying structural contour shading across the 3D carton surface
  for (let i = 0; i < 2400; i++) {
    let x = random(-1.76, 1.76);
    let y = random(-1.46, 1.15);
    if (Math.abs(x) > 1.64 && y < -1.13) continue;

    // Leave room for the main cracked egg & yolk in front-center cup
    let distEgg = Math.hypot((x - 0.04) * 1.05, (y + 0.58) * 1.05);
    if (distEgg < 0.34) continue;

    let surf = cartonSurface(x, y);
    if (surf.flapHole) continue;
    let nrm = getCartonNormal(x, y);
    let sp = worldToCam(x, y, nrm.z0);
    if (!insideOval(sp.sx, sp.sy, 14)) continue;
    if (!isVisible(sp.sx, sp.sy, sp.d, 0.075)) continue;

    let lt = computePlateLight(x, y, nrm.z0, nrm.x, nrm.y, nrm.z);

    // Compute local contour tangent in screen space
    let tx = -nrm.y, ty = nrm.x;
    let tl = Math.hypot(tx, ty);
    if (tl < 0.001) { tx = 1; ty = 0; } else { tx /= tl; ty /= tl; }
    let sp2 = worldToCam(x + tx * 0.06, y + ty * 0.06, nrm.z0);
    let baseAng = atan2(sp2.sy - sp.sy, sp2.sx - sp.sx) + random(-28, 28);

    // Shallow DOF modulation: sharp near focal plane, wider & softer away
    let dof = sp.defocus;
    let strokeLen = map(dof, 0, 0.9, random(6, 14), random(12, 24), true);
    let weightMod = map(dof, 0, 0.9, 1.0, 1.65, true);

    if (lt.val < 0.46) {
      let idx = Math.floor(map(lt.val, 0.04, 0.46, 0, 4.99, true));
      let bName = dof > 0.42 || lt.val < 0.24 ? "charcoal" : "2B";
      brush.set(bName, darkBuckets[idx], (0.20 + (1 - lt.val) * 0.22) * weightMod);
      brush.line(
        sp.sx - cos(baseAng) * strokeLen * 0.5,
        sp.sy - sin(baseAng) * strokeLen * 0.5,
        sp.sx + cos(baseAng) * strokeLen * 0.5,
        sp.sy + sin(baseAng) * strokeLen * 0.5
      );
    } else if (lt.val > 0.56) {
      let idx = Math.floor(map(lt.val, 0.56, 0.98, 0, 5.99, true));
      let col = lt.reversed ? "#929ba6" : lightBuckets[idx];
      let bName = dof > 0.45 ? "cpencil" : "HB";
      brush.set(bName, col, (0.18 + (lt.val - 0.5) * 0.20) * weightMod);
      brush.line(
        sp.sx - cos(baseAng) * strokeLen * 0.5,
        sp.sy - sin(baseAng) * strokeLen * 0.5,
        sp.sx + cos(baseAng) * strokeLen * 0.5,
        sp.sy + sin(baseAng) * strokeLen * 0.5
      );
    }
  }

  // Pass B: High-focus grain-by-grain cellulose pulp fibres, flecks & vacuum-mould pinholes
  // Dense concentration in the sharp focal band (y in [-1.25, +0.35])
  for (let i = 0; i < 4200; i++) {
    // Bias sampling toward the focal zone around the front cups, cones, and rim
    let x = random(-1.74, 1.74);
    let uRand = random();
    let y = uRand < 0.72 ? random(-1.28, 0.28) : random(-1.46, 1.12);
    if (Math.abs(x) > 1.64 && y < -1.13) continue;

    let distEgg = Math.hypot((x - 0.04) * 1.08, (y + 0.58) * 1.08);
    if (distEgg < 0.35) continue;

    let surf = cartonSurface(x, y);
    if (surf.flapHole) continue;
    let nrm = getCartonNormal(x, y);
    let sp = worldToCam(x, y, nrm.z0);
    if (!insideOval(sp.sx, sp.sy, 14)) continue;
    if (!isVisible(sp.sx, sp.sy, sp.d, 0.065)) continue;

    let dof = sp.defocus;
    // Skip ultra-fine grain where out of focus
    if (dof > 0.58 && random() < 0.72) continue;

    let lt = computePlateLight(x, y, nrm.z0, nrm.x, nrm.y, nrm.z);

    // Individual short pressed-pulp fibre (3px to 10px, slightly bent)
    let fibreAng = random(360);
    let fLen = map(dof, 0, 0.55, random(3.2, 8.5), random(7, 14), true);
    let fWeight = map(dof, 0, 0.55, random(0.12, 0.22), random(0.22, 0.34), true);

    // Micro-relief of pressed pulp: each fibre catches light on one side and casts a micro-shadow
    let isHighlightFibre = random() < lt.val;
    let col;
    let bType;

    if (isHighlightFibre) {
      bType = dof < 0.26 ? "2H" : "HB";
      if (lt.reversed) {
        col = random() < 0.45 ? "#f0f4f8" : "#8b949f"; // Reversed silver-pewter highlight
      } else if (lt.val > 0.78) {
        col = random() < 0.6 ? "#eef3f8" : "#d2dae2";
      } else {
        col = random() < 0.5 ? "#b8c0ca" : "#9ea7b1";
      }
    } else {
      bType = dof < 0.28 ? "HB" : "2B";
      if (lt.val < 0.28) {
        col = random() < 0.6 ? "#181b20" : "#262a31";
      } else {
        col = random() < 0.5 ? "#383d46" : "#4d535d";
      }
    }

    brush.set(bType, col, fWeight);
    let mx = sp.sx + cos(fibreAng) * (fLen * 0.5);
    let my = sp.sy + sin(fibreAng) * (fLen * 0.5);
    let bendAng = fibreAng + random(-32, 32);
    let ex = mx + cos(bendAng) * (fLen * 0.5);
    let ey = my + sin(bendAng) * (fLen * 0.5);
    brush.line(sp.sx, sp.sy, mx, my);
    brush.line(mx, my, ex, ey);

    // Paired micro-crevice or pulp nodule speck in the sharpest zone (dof < 0.24)
    if (dof < 0.24 && random() < 0.28) {
      let offX = sp.sx + random(-2.2, 2.2);
      let offY = sp.sy + random(-2.2, 2.2);
      brush.set("2H", isHighlightFibre ? "#2a2e36" : "#dce3eb", 0.13);
      brush.line(offX, offY, offX + random(-2.5, 2.5), offY + random(-2.5, 2.5));
    }
  }

  // Pass C: Characteristic vacuum-mould aeration pinholes & pressed creases on cones and rims
  for (let cx of [-0.575, 0.575]) {
    // Small drainage/vacuum hole in the top dimple of each separator cone
    let spHole = worldToCam(cx, 0.0, cartonSurface(cx, 0.0).z);
    brush.set("2B", "#1e2228", 0.32);
    brush.circle(spHole.sx, spHole.sy, 4.5, 0.25);
    brush.set("2H", "#e8eef5", 0.18);
    brush.arc(spHole.sx, spHole.sy, 5.5, 20, 195);

    // Pressed vertical flute seams on the separator cones
    for (let fl = 0; fl < 6; fl++) {
      let ang = (fl / 6) * Math.PI * 2 + 0.3;
      let pts = [];
      for (let s = 0; s <= 8; s++) {
        let r = 0.09 + (s / 8) * 0.29;
        let wx = cx + Math.cos(ang) * r;
        let wy = Math.sin(ang) * r * 0.92;
        let wz = cartonSurface(wx, wy).z;
        let p = worldToCam(wx, wy, wz);
        if (isVisible(p.sx, p.sy, p.d, 0.07)) pts.push([p.sx, p.sy]);
      }
      if (pts.length > 2) {
        brush.set("HB", Math.cos(ang) < 0 ? "#dce3ec" : "#363b44", 0.16);
        brush.spline(pts, 0.35);
      }
    }
  }

  // Pass D: Fuzzy raw deckle fibres along the front carton crease, outer flange rim, and locking tabs
  for (let ix = 0; ix <= 160; ix++) {
    let x = -1.64 + (ix / 160) * 3.28;
    // Front hinge crease (y = -1.12) and bottom edge of locking apron (y = -1.46)
    for (let edgeY of [-1.12, -1.46]) {
      let surf = cartonSurface(x, edgeY);
      if (surf.flapHole) continue;
      let sp = worldToCam(x, edgeY, surf.z);
      if (!insideOval(sp.sx, sp.sy, 14)) continue;
      if (!isVisible(sp.sx, sp.sy, sp.d, 0.08)) continue;

      let col = edgeY === -1.12
        ? (random() < 0.7 ? "#e4eaf1" : "#969fa9") // Reversed silver highlight on front crease
        : (random() < 0.6 ? "#242830" : "#8a929c");
      brush.set("2H", col, random(0.13, 0.22));
      let a = random(-35, 35) + (edgeY === -1.46 ? 70 : 5);
      let l = random(3, 8);
      brush.line(sp.sx, sp.sy, sp.sx + cos(a) * l, sp.sy + sin(a) * l);
    }
  }

  // Crisp rim outlines of the two locking tab cutouts on the front apron
  for (let tx of [-0.62, 0.62]) {
    for (let i = 0; i < 36; i++) {
      let a = (i / 36) * Math.PI * 2;
      let wx = tx + Math.cos(a) * 0.14;
      let wy = -1.12 - (0.52 + Math.sin(a) * 0.18) * 0.36;
      let wz = cartonSurface(wx, wy).z;
      let sp = worldToCam(wx, wy, wz);
      if (!insideOval(sp.sx, sp.sy, 14)) continue;
      let isTopEdge = Math.sin(a) < 0;
      brush.set("HB", isTopEdge ? "#1d2026" : "#cfd7e0", 0.20);
      brush.line(sp.sx, sp.sy, sp.sx + random(-4, 4), sp.sy + random(-2, 2));
    }
  }
}

// ============================================================================
// LAYER 5: DETACHED UPPER EGGSHELL CAP (IN FRONT-LEFT CUP)
// ============================================================================
function renderDetachedLeftShell() {
  // Tipped hollow shell half resting in the front-left cup (-1.08, -0.55)
  let cx = -1.06, cy = -0.55, cz = -0.15;
  let spCenter = worldToCam(cx, cy, cz);

  // Build 2D projected polygon for the outer dome (left) and concave interior (right)
  let outerPts = [];
  let innerPts = [];
  const N = 28;
  for (let i = 0; i < N; i++) {
    let a = (i / N) * Math.PI * 2;
    let jag = 0.018 * Math.sin(a * 5 + 1.2) + 0.012 * Math.cos(a * 9 - 0.5);
    let rx = (0.31 + jag) * Math.cos(a);
    let ry = (0.27 + jag) * Math.sin(a);
    let rz = 0.14 * Math.cos(a - 0.6) + jag * 1.4;
    let p = worldToCam(cx + rx, cy + ry, cz + rz);
    outerPts.push([p.sx, p.sy]);

    // Inner hollow offset shifted right
    let irx = (0.21 + jag * 0.8) * Math.cos(a) + 0.05;
    let iry = (0.21 + jag * 0.8) * Math.sin(a);
    let irz = -0.05 + 0.06 * Math.sin(a);
    let ip = worldToCam(cx + irx, cy + iry, cz + irz);
    innerPts.push([ip.sx, ip.sy]);
  }

  // 1. Cast shadow inside the front-left cup under the shell cap
  brush.noStroke();
  brush.fill("#1d2026", 130);
  brush.fillBleed(0.18, "out");
  brush.beginShape(0.35);
  for (let pt of outerPts) {
    brush.vertex(pt[0] + 6, pt[1] + 9);
  }
  brush.endShape(true);

  // 2. Luminous silver-pearl outer shell wash
  brush.fill("#ced5dd", 125);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.45, 0.3);
  brush.beginShape(0.3);
  for (let pt of outerPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // 3. Concave shadowy pearlescent interior of the detached shell
  brush.fill("#484f58", 135);
  brush.fillBleed(0.12, "in");
  brush.beginShape(0.25);
  for (let pt of innerPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);
  brush.noFill();

  // 4. Fine graphite shading & reversed highlight on the left dome of the shell cap
  for (let i = 0; i < 280; i++) {
    let r = sqrt(random()) * 0.29;
    let a = random(Math.PI * 2);
    let wx = cx + Math.cos(a) * r;
    let wy = cy + Math.sin(a) * r * 0.88;
    let wz = cz + 0.16 * Math.sqrt(Math.max(0, 1 - (r / 0.30) * (r / 0.30))) - 0.08 * Math.cos(a);
    let p = worldToCam(wx, wy, wz);

    // Check if inside the concave opening on the right side
    let isInsideHollow = (wx - (cx + 0.05)) > -0.04 && Math.hypot(wx - (cx + 0.05), wy - cy) < 0.20;
    let tangent = atan2(wy - cy, wx - cx) + 90 + random(-15, 15);
    let len = random(4, 10);

    if (isInsideHollow) {
      // Concave interior shading: dark on left under-lip, pearly bounce on right inner wall
      let bounce = (wx - cx) / 0.25;
      let col = bounce > 0.35 ? "#929ba5" : (bounce > 0.0 ? "#3c424b" : "#20242b");
      brush.set("HB", col, 0.18);
    } else {
      // Convex exterior dome shading with reversed silver highlight
      let lightPos = Math.hypot((wx - (cx - 0.12)), (wy - (cy - 0.08)));
      let col;
      if (lightPos < 0.07) {
        col = "#939ca7"; // Reversed pewter core
      } else if (lightPos < 0.15) {
        col = "#f2f6fa"; // Bright silver halo
      } else {
        col = "#abb3bd";
      }
      brush.set("2H", col, 0.16);
    }
    brush.line(p.sx, p.sy, p.sx + cos(tangent) * len, p.sy + sin(tangent) * len);
  }

  // 5. Crisp calcified fracture edge of the detached shell cap
  brush.set("2H", "#f4f7fa", 0.24);
  brush.spline(innerPts, 0.15);
  brush.set("2B", "#1a1d22", 0.19);
  for (let i = 0; i < innerPts.length; i += 2) {
    let p1 = innerPts[i];
    let p2 = innerPts[(i + 1) % innerPts.length];
    brush.line(p1[0] + 1.5, p1[1] + 1.8, p2[0] + 1.5, p2[1] + 1.8);
  }
}

// ============================================================================
// LAYER 6: CRACKED EGG, SPILLED ALBUMEN & SLUMPED GLOSSY YOLK (HERO ELEMENT)
// ============================================================================
function renderMainCrackedEggAndYolk() {
  const eggX = -0.01;
  const eggY = -0.56;

  // --------------------------------------------------------------------------
  // STEP 6A: Wet Spilled Albumen (Egg White) Pooling in the Pulp Cup
  // --------------------------------------------------------------------------
  brush.noStroke();
  // Darkened wet cardboard pulp ring where albumen soaks into fibres
  brush.fill("#2c3138", 95);
  brush.fillBleed(0.16, "out");
  brush.beginShape(0.45);
  for (let i = 0; i < 16; i++) {
    let a = (i / 16) * Math.PI * 2;
    let r = 0.42 + 0.06 * Math.sin(a * 3 + 0.5);
    let wx = 0.09 + Math.cos(a) * r;
    let wy = -0.60 + Math.sin(a) * r * 0.92;
    let wz = cartonSurface(wx, wy).z;
    let p = worldToCam(wx, wy, wz);
    brush.vertex(p.sx, p.sy);
  }
  brush.endShape(true);
  brush.noFill();

  // Glossy silver meniscus threads along the viscous albumen edge
  let albEdgePts = [];
  for (let i = 0; i <= 24; i++) {
    let a = -1.4 + (i / 24) * 2.9; // Front and right spilled lobe
    let r = 0.38 + 0.045 * Math.cos(a * 4);
    let wx = 0.09 + Math.cos(a) * r;
    let wy = -0.60 + Math.sin(a) * r * 0.92;
    let wz = cartonSurface(wx, wy).z + 0.015;
    let p = worldToCam(wx, wy, wz);
    albEdgePts.push([p.sx, p.sy]);
  }
  brush.set("2H", "#e8eef5", 0.22);
  brush.spline(albEdgePts, 0.4);
  brush.set("2H", "#959ea8", 0.14);
  for (let i = 0; i < albEdgePts.length - 1; i += 2) {
    brush.line(albEdgePts[i][0] - 1.5, albEdgePts[i][1] - 1.5, albEdgePts[i + 1][0] - 1.5, albEdgePts[i + 1][1] - 1.5);
  }

  // --------------------------------------------------------------------------
  // STEP 6B: Back Wall Inside the Cracked Eggshell (Behind the Yolk)
  // --------------------------------------------------------------------------
  let backRimPts = [];
  let frontRimPts = [];
  const R_STEPS = 48;
  for (let i = 0; i <= R_STEPS; i++) {
    let ang = -Math.PI + (i / R_STEPS) * Math.PI * 2;
    let zTop = mainShellCrackZ(ang);
    let hNorm = (zTop + 0.12) / 0.32;
    let rad = 0.39 * Math.sqrt(Math.max(0.05, 1.0 - 0.55 * hNorm * hNorm));
    let wx = eggX + Math.cos(ang) * rad;
    let wy = eggY + Math.sin(ang) * rad * 0.94;
    let p = worldToCam(wx, wy, zTop);
    if (ang >= 0.05 && ang <= Math.PI - 0.15) {
      backRimPts.push([p.sx, p.sy, ang, wx, wy, zTop]);
    } else {
      frontRimPts.push([p.sx, p.sy, ang, wx, wy, zTop]);
    }
  }

  // Dark hollow interior of the back shell rim
  brush.noStroke();
  brush.fill("#262b32", 160);
  brush.fillBleed(0.08, "in");
  brush.beginShape(0.2);
  for (let pt of backRimPts) brush.vertex(pt[0], pt[1]);
  let pRight = worldToCam(eggX + 0.36, eggY, -0.08);
  let pLeft = worldToCam(eggX - 0.36, eggY, -0.08);
  brush.vertex(pRight.sx, pRight.sy + 18);
  brush.vertex(pLeft.sx, pLeft.sy + 18);
  brush.endShape(true);
  brush.noFill();

  // Crisp jagged back shell rim & translucent torn membrane
  if (backRimPts.length > 2) {
    let coords = backRimPts.map(p => [p[0], p[1]]);
    brush.set("2H", "#edf2f7", 0.25);
    brush.spline(coords, 0.12);
    brush.set("2B", "#16191e", 0.20);
    for (let i = 0; i < coords.length - 1; i++) {
      brush.line(coords[i][0], coords[i][1] + 2.2, coords[i + 1][0], coords[i + 1][1] + 2.2);
    }
  }

  // --------------------------------------------------------------------------
  // STEP 6C: THE SLUMPED, STILL-GLOSSY AMBER YOLK
  // "The only near-colour is a dim, desaturated yolk amber. Color hint: soft pastels"
  // --------------------------------------------------------------------------
  // Compute exact 2D screen outline of the slumped cushion-shaped yolk
  // Nested in the shell hollow and slumping forward-right over the broken lip
  let yolkOutline = [];
  const Y_STEPS = 44;
  for (let i = 0; i < Y_STEPS; i++) {
    let a = (i / Y_STEPS) * Math.PI * 2;
    // Asymmetric slumped profile: wider and drooping on the lower-right (+x, -y)
    let slumpR = 1.0 + 0.14 * Math.cos(a - 0.55) + 0.05 * Math.sin(2 * a + 0.4);
    let ux = Math.cos(a) * slumpR;
    let uy = Math.sin(a) * slumpR;
    let wx = 0.10 + ux * 0.265;
    let wy = -0.60 + uy * 0.235;
    // Droops down slightly where it spills over the right-front shell saddle
    let wz = -0.05 - 0.045 * Math.cos(a - 0.6);
    let p = worldToCam(wx, wy, wz);
    yolkOutline.push([p.sx, p.sy]);
  }

  // 1. Deep warm umber-charcoal cushion shadow directly beneath the slumped yolk belly
  brush.noStroke();
  brush.fill("#28231e", 145);
  brush.fillBleed(0.14, "out");
  brush.beginShape(0.35);
  for (let pt of yolkOutline) {
    brush.vertex(pt[0] + 3.5, pt[1] + 6.5);
  }
  brush.endShape(true);

  // 2. Layered soft pastel amber washes for the slumped yolk body
  // Base muted antique ochre-amber
  brush.fill("#ab8e68", 155);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.42, 0.28);
  brush.beginShape(0.38);
  for (let pt of yolkOutline) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Second warmer desaturated yolk-amber core pass
  brush.fill("#c4a57b", 135);
  brush.fillBleed(0.12, "in");
  brush.beginShape(0.4);
  for (let i = 0; i < Y_STEPS; i++) {
    let pt = yolkOutline[i];
    let cx = 618, cy = 665;
    brush.vertex(cx + (pt[0] - cx) * 0.84 - 4, cy + (pt[1] - cy) * 0.84 - 4);
  }
  brush.endShape(true);

  // Luminous soft pastel buff-gold crown on upper-central dome
  brush.fill("#dbc29e", 115);
  brush.fillBleed(0.15, "out");
  brush.beginShape(0.45);
  for (let i = 0; i < Y_STEPS; i++) {
    let pt = yolkOutline[i];
    let cx = 610, cy = 656;
    brush.vertex(cx + (pt[0] - cx) * 0.56 - 8, cy + (pt[1] - cy) * 0.54 - 7);
  }
  brush.endShape(true);

  // Shaded lower-right slump belly (smoky amber-grey shadow)
  brush.fill("#735d44", 110);
  brush.fillBleed(0.16, "in");
  brush.beginShape(0.4);
  for (let i = 0; i < Y_STEPS; i++) {
    let a = (i / Y_STEPS) * Math.PI * 2;
    let pt = yolkOutline[i];
    let cx = 626, cy = 674;
    let rScale = a < 0 || a > 2.2 ? 0.94 : 0.42;
    brush.vertex(cx + (pt[0] - cx) * rScale, cy + (pt[1] - cy) * rScale);
  }
  brush.endShape(true);
  brush.noFill();

  // 3. Ultra-fine coloured-pencil & graphite contour shading across the 3D yolk membrane
  const yolkColors = ["#524332", "#6e5941", "#8c7253", "#a88b67", "#c2a57f", "#d6be9c", "#e6d4b8"];
  for (let i = 0; i < 720; i++) {
    let r = sqrt(random()) * 0.96;
    let a = random(Math.PI * 2);
    let slumpR = 1.0 + 0.14 * Math.cos(a - 0.55) + 0.05 * Math.sin(2 * a + 0.4);
    let ux = Math.cos(a) * r * slumpR;
    let uy = Math.sin(a) * r * slumpR;

    let wx = 0.10 + ux * 0.265;
    let wy = -0.60 + uy * 0.235;
    let domeH = Math.pow(Math.max(0, 1.0 - r * r), 0.58);
    let wz = -0.05 + 0.175 * domeH - 0.045 * uy;

    let p = worldToCam(wx, wy, wz);

    // Normal on yolk dome
    let nx = -ux * 0.75;
    let ny = -uy * 0.75 + 0.18;
    let nz = domeH + 0.25;
    let nl = Math.hypot(nx, ny, nz);
    nx /= nl; ny /= nl; nz /= nl;

    let diff = Math.max(0, nx * (-0.42) + ny * (-0.38) + nz * 0.82);
    // Subsurface glow in the mid-belly of the yolk
    let sss = (1.0 - r * 0.6) * 0.18;
    let shade = Math.min(0.99, diff * 0.82 + sss);

    let cIdx = Math.floor(shade * (yolkColors.length - 0.01));
    let tangent = atan2(uy, ux) + 90 + random(-10, 10);
    let sLen = random(4, 9.5);

    brush.set(i % 3 === 0 ? "2H" : "cpencil", yolkColors[cIdx], random(0.13, 0.21));
    brush.line(
      p.sx - cos(tangent) * sLen * 0.5,
      p.sy - sin(tangent) * sLen * 0.5,
      p.sx + cos(tangent) * sLen * 0.5,
      p.sy + sin(tangent) * sLen * 0.5
    );
  }

  // Delicate vitelline membrane tension folds where the yolk stretches over the shell break
  for (let f = 0; f < 14; f++) {
    let a0 = -1.25 + (f / 13) * 1.45;
    let foldPts = [];
    for (let s = 0; s <= 5; s++) {
      let r = 0.62 + (s / 5) * 0.35;
      let a = a0 + (s / 5) * 0.18;
      let slumpR = 1.0 + 0.14 * Math.cos(a - 0.55);
      let ux = Math.cos(a) * r * slumpR;
      let uy = Math.sin(a) * r * slumpR;
      let wx = 0.10 + ux * 0.265;
      let wy = -0.60 + uy * 0.235;
      let wz = -0.05 + 0.175 * Math.pow(Math.max(0, 1 - r * r), 0.58) - 0.045 * uy;
      let p = worldToCam(wx, wy, wz);
      foldPts.push([p.sx, p.sy]);
    }
    brush.set("2H", f % 2 === 0 ? "#e8dac2" : "#6b563e", 0.14);
    brush.spline(foldPts, 0.35);
  }

  // 4. GLOSSY MIRROR-SILVER SPECULAR HIGHLIGHTS ON THE YOLK (WITH SOLARIZED REVERSAL)
  // Curved window reflection across the upper-left crown of the glossy yolk
  for (let pane = 0; pane < 2; pane++) {
    let aStart = pane === 0 ? 1.95 : 2.52;
    let aEnd = pane === 0 ? 2.42 : 2.96;
    let specOuter = [];
    let specInner = [];

    for (let s = 0; s <= 10; s++) {
      let a = aStart + (s / 10) * (aEnd - aStart);
      let r1 = 0.42, r2 = 0.64;
      for (let [r, arr] of [[r1, specOuter], [r2, specInner]]) {
        let ux = Math.cos(a) * r;
        let uy = Math.sin(a) * r;
        let wx = 0.10 + ux * 0.265;
        let wy = -0.60 + uy * 0.235;
        let wz = -0.05 + 0.175 * Math.pow(1 - r * r, 0.58) - 0.045 * uy;
        let p = worldToCam(wx, wy, wz);
        arr.push([p.sx, p.sy]);
      }
    }
    let poly = specOuter.concat(specInner.reverse());

    // Reversed metallic pewter-silver interior of the specular reflection
    brush.noStroke();
    brush.fill("#9ba4ae", 165);
    brush.fillBleed(0.04, "in");
    brush.beginShape(0.25);
    for (let pt of poly) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
    brush.noFill();

    // Blazing silver-white solarized halo around the specular window pane
    brush.set("2H", "#f7f9fc", 0.28);
    brush.spline(poly.concat([poly[0]]), 0.25);
    brush.set("pen", "#ffffff", 0.16);
    brush.spline(specOuter, 0.3);
  }

  // Secondary wet meniscus silver thread along the lower-right slumped yolk belly
  let lowerGloss = [];
  for (let s = 0; s <= 16; s++) {
    let a = -1.15 + (s / 16) * 1.35;
    let r = 0.89;
    let slumpR = 1.0 + 0.14 * Math.cos(a - 0.55) + 0.05 * Math.sin(2 * a + 0.4);
    let ux = Math.cos(a) * r * slumpR;
    let uy = Math.sin(a) * r * slumpR;
    let wx = 0.10 + ux * 0.265;
    let wy = -0.60 + uy * 0.235;
    let wz = -0.05 + 0.175 * Math.pow(1 - r * r, 0.58) - 0.045 * uy;
    let p = worldToCam(wx, wy, wz);
    lowerGloss.push([p.sx, p.sy]);
  }
  brush.set("2H", "#eef2f7", 0.21);
  brush.spline(lowerGloss, 0.35);

  // --------------------------------------------------------------------------
  // STEP 6D: FRONT CRACKED EGGSHELL WALL (CRADLING THE YOLK)
  // --------------------------------------------------------------------------
  // Build polygon of the front shell wall between the fracture line and the cup base
  let shellTopPts = [];
  let shellBotPts = [];
  for (let i = 0; i <= 36; i++) {
    let ang = -Math.PI + 0.12 + (i / 36) * (Math.PI + 0.02); // Front half: -3.02 to +0.14
    let zTop = mainShellCrackZ(ang);
    let hNorm = (zTop + 0.12) / 0.32;
    let rad = 0.39 * Math.sqrt(Math.max(0.05, 1.0 - 0.55 * hNorm * hNorm));
    let wx = eggX + Math.cos(ang) * rad;
    let wy = eggY + Math.sin(ang) * rad * 0.94;
    let pTop = worldToCam(wx, wy, zTop);
    shellTopPts.push([pTop.sx, pTop.sy, ang, wx, wy, zTop]);

    let zBot = -0.26 + 0.04 * Math.sin(ang * 2);
    let radBot = 0.31;
    let bwx = eggX + Math.cos(ang) * radBot;
    let bwy = eggY + Math.sin(ang) * radBot * 0.94;
    let pBot = worldToCam(bwx, bwy, zBot);
    shellBotPts.push([pBot.sx, pBot.sy]);
  }

  // 1. Base wash of the front eggshell exterior
  brush.noStroke();
  brush.fill("#c5cdd6", 150);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.4, 0.3);
  brush.beginShape(0.2);
  for (let pt of shellTopPts) brush.vertex(pt[0], pt[1]);
  for (let i = shellBotPts.length - 1; i >= 0; i--) {
    brush.vertex(shellBotPts[i][0], shellBotPts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();

  // 2. Hyper-detailed graphite shading & calcified pores on the front eggshell
  for (let i = 0; i < 650; i++) {
    let ang = random(-3.02, 0.14);
    let zTop = mainShellCrackZ(ang);
    let zBot = -0.26;
    let t = random(0.02, 0.98);
    let z = zBot + t * (zTop - zBot);
    let hNorm = (z + 0.12) / 0.32;
    let rad = 0.39 * Math.sqrt(Math.max(0.05, 1.0 - 0.55 * hNorm * hNorm));
    let wx = eggX + Math.cos(ang) * rad;
    let wy = eggY + Math.sin(ang) * rad * 0.94;
    let p = worldToCam(wx, wy, z);

    // Normal of egg sphere
    let nx = Math.cos(ang) * 0.88;
    let ny = Math.sin(ang) * 0.88;
    let nz = hNorm * 0.65;
    let nl = Math.hypot(nx, ny, nz);
    nx /= nl; ny /= nl; nz /= nl;

    let lt = computePlateLight(wx, wy, z, nx, ny, nz);
    let col;
    if (lt.reversed || (ang > -2.35 && ang < -1.55 && t > 0.35 && t < 0.82)) {
      // Solarized mirror-silver highlight on the left-front bulge of the shell
      let coreDist = Math.hypot(ang + 1.95, (t - 0.60) * 1.4);
      col = coreDist < 0.25 ? "#8c96a2" : "#f4f7fb";
    } else if (lt.val > 0.68) {
      col = "#dfe6ee";
    } else if (lt.val > 0.45) {
      col = "#9ca5b0";
    } else if (lt.val > 0.28) {
      col = "#59606a";
    } else {
      col = "#2b3038";
    }

    let tangent = atan2(Math.sin(ang), Math.cos(ang)) + 90 + random(-14, 14);
    let len = random(3.5, 8.0);
    brush.set(lt.val > 0.5 ? "2H" : "HB", col, random(0.12, 0.19));
    brush.line(p.sx, p.sy, p.sx + cos(tangent) * len, p.sy + sin(tangent) * len);
  }

  // 3. Razor-sharp jagged calcified fracture rim & hairline radial cracks
  let topCoords = shellTopPts.map(p => [p[0], p[1]]);
  // Dark shadow line directly under the broken shell thickness lip
  brush.set("2B", "#171a20", 0.24);
  for (let i = 0; i < topCoords.length - 1; i++) {
    brush.line(topCoords[i][0], topCoords[i][1] + 2.4, topCoords[i + 1][0], topCoords[i + 1][1] + 2.4);
  }
  // Bright white calcified shell thickness rim
  brush.set("2H", "#f6f9fc", 0.30);
  brush.spline(topCoords, 0.08);
  brush.set("pen", "#ffffff", 0.15);
  brush.spline(topCoords, 0.08);

  // Hairline radial fracture craze lines spiderwebbing down from the break
  const crackAngles = [-2.55, -1.85, -1.22, -0.68, -0.22];
  for (let ca of crackAngles) {
    let zTop = mainShellCrackZ(ca);
    let cPts = [];
    let curA = ca;
    for (let s = 0; s <= 7; s++) {
      let z = zTop - (s / 7) * 0.15;
      curA += (noise(ca * 10, s) - 0.5) * 0.09;
      let hNorm = (z + 0.12) / 0.32;
      let rad = 0.39 * Math.sqrt(Math.max(0.05, 1.0 - 0.55 * hNorm * hNorm));
      let wx = eggX + Math.cos(curA) * rad;
      let wy = eggY + Math.sin(curA) * rad * 0.94;
      let p = worldToCam(wx, wy, z);
      cPts.push([p.sx, p.sy]);
    }
    brush.set("2B", "#22262e", 0.16);
    brush.spline(cPts, 0.15);
    // Faint silver edge highlight right beside the hairline crack
    brush.set("2H", "#eef3f8", 0.12);
    let offsetPts = cPts.map(pt => [pt[0] + 1.2, pt[1] + 0.5]);
    brush.spline(offsetPts, 0.15);
  }

  // Tiny fallen shell splinters resting in the pulp crease near the egg base
  const shards = [
    { x: -0.34, y: -0.82, s: 7.5, a: 22 },
    { x: 0.36,  y: -0.78, s: 6.0, a: -35 },
    { x: -0.46, y: -0.64, s: 5.2, a: 55 },
    { x: 0.24,  y: -0.92, s: 4.5, a: 12 }
  ];
  for (let sh of shards) {
    let wz = cartonSurface(sh.x, sh.y).z + 0.01;
    let sp = worldToCam(sh.x, sh.y, wz);
    brush.set("2B", "#1d2026", 0.22);
    brush.line(sp.sx - 2, sp.sy + 2, sp.sx + sh.s, sp.sy + 3);
    brush.set("2H", "#f0f4f9", 0.28);
    brush.line(sp.sx, sp.sy, sp.sx + cos(sh.a) * sh.s, sp.sy + sin(sh.a) * sh.s);
    brush.line(sp.sx, sp.sy, sp.sx + cos(sh.a + 65) * (sh.s * 0.7), sp.sy + sin(sh.a + 65) * (sh.s * 0.7));
  }
}

// ============================================================================
// LAYER 7: IRIDESCENT TARNISH BLOOMS AROUND THE OVAL MAT EDGE
// "Around the oval mat edge, tarnish blooms in iridescent peacock blue,
//  bronze and rose, applied as soft stained halos."
// ============================================================================
function renderTarnishBlooms() {
  brush.noStroke();

  // Soft pastel tarnish palettes: peacock blue, tarnished bronze, dusty rose, sulphide violet-slate
  const tarnishHalos = [
    // Peacock Blue / Iridescent Teal-Cyan
    { col: "#5a8d9e", op: 58, bleed: 0.46, angles: [18, 42, 128, 155, 215, 295, 335], rIn: 0.83, rOut: 1.02 },
    { col: "#76a9b8", op: 48, bleed: 0.42, angles: [28, 140, 205, 248, 315], rIn: 0.79, rOut: 0.99 },
    // Antique Bronze / Warm Amber-Gold Tarnish
    { col: "#a88f69", op: 55, bleed: 0.44, angles: [5, 68, 95, 178, 240, 275, 350], rIn: 0.82, rOut: 1.02 },
    { col: "#bfa782", op: 44, bleed: 0.40, angles: [55, 112, 190, 260, 325], rIn: 0.78, rOut: 0.98 },
    // Soft Pastel Rose / Mauve-Copper Bloom
    { col: "#b5838e", op: 54, bleed: 0.45, angles: [32, 82, 148, 200, 255, 305], rIn: 0.81, rOut: 1.01 },
    { col: "#cba0aa", op: 44, bleed: 0.40, angles: [12, 105, 168, 228, 285, 342], rIn: 0.77, rOut: 0.97 },
    // Deep Sulphide Violet-Slate right against the mat rim
    { col: "#4c5264", op: 68, bleed: 0.35, angles: [0, 45, 90, 135, 180, 225, 270, 315], rIn: 0.91, rOut: 1.03 }
  ];

  for (let group of tarnishHalos) {
    brush.fill(group.col, group.op);
    brush.fillBleed(group.bleed, "in");
    brush.fillTexture(0.75, 0.50);

    for (let baseAng of group.angles) {
      let span = random(18, 34);
      let rInner = group.rIn * random(0.94, 1.04);
      let rOuter = group.rOut;

      brush.beginShape(0.45);
      // Outer arc along the oval edge
      for (let s = 0; s <= 6; s++) {
        let a = (baseAng - span * 0.5) + (s / 6) * span;
        let px = OVAL_CX + cos(a) * OVAL_RX * rOuter;
        let py = OVAL_CY + sin(a) * OVAL_RY * rOuter;
        brush.vertex(px, py);
      }
      // Scalloped inner halo bleeding into the silver plate
      for (let s = 6; s >= 0; s--) {
        let a = (baseAng - span * 0.5) + (s / 6) * span;
        let wave = Math.sin((s / 6) * Math.PI) * 0.08 + (noise(baseAng, s) - 0.5) * 0.06;
        let r = rInner - wave;
        let px = OVAL_CX + cos(a) * OVAL_RX * r;
        let py = OVAL_CY + sin(a) * OVAL_RY * r;
        brush.vertex(px, py);
      }
      brush.endShape(true);
    }
  }
  brush.noFill();

  // Delicate tide-line stain contours & iridescent micro-stipple along the tarnish frontier
  const stainCols = ["#588999", "#a88e68", "#b3828d", "#6c8c99", "#9c7e65"];
  for (let i = 0; i < 420; i++) {
    let a = random(360);
    let r = random(0.82, 0.99);
    let px = OVAL_CX + cos(a) * OVAL_RX * r;
    let py = OVAL_CY + sin(a) * OVAL_RY * r;
    let col = stainCols[i % stainCols.length];
    brush.set("spray", col, random(0.22, 0.42));
    let tang = a + 90 + random(-25, 25);
    brush.line(px, py, px + cos(tang) * random(8, 22), py + sin(tang) * random(8, 22));
  }
}

// ============================================================================
// LAYER 8: FAINT GILT BRASS MAT FRAME & BEVELED OVAL WINDOW
// "A faint gilt brass mat frame encloses everything."
// ============================================================================
function renderGiltBrassMatFrame() {
  // 1. Solid opaque wash & textured watercolor sectors outside the oval window
  //    Using 36 radial sectors from the oval perimeter out to a generous outer box
  const SECTORS = 36;
  const OUTER_R = 920;

  brush.noStroke();
  // First pass: opaque wash in warm muted antique gilt brass to cleanly frame the oval
  brush.wash("#9a917f", 245);
  for (let i = 0; i < SECTORS; i++) {
    let a0 = (i / SECTORS) * 360;
    let a1 = ((i + 1) / SECTORS) * 360;
    let am = (a0 + a1) * 0.5;
    brush.beginShape(0);
    brush.vertex(OVAL_CX + cos(a0) * OVAL_RX, OVAL_CY + sin(a0) * OVAL_RY);
    brush.vertex(OVAL_CX + cos(am) * OVAL_RX, OVAL_CY + sin(am) * OVAL_RY);
    brush.vertex(OVAL_CX + cos(a1) * OVAL_RX, OVAL_CY + sin(a1) * OVAL_RY);
    brush.vertex(OVAL_CX + cos(a1) * OUTER_R, OVAL_CY + sin(a1) * OUTER_R);
    brush.vertex(OVAL_CX + cos(a0) * OUTER_R, OVAL_CY + sin(a0) * OUTER_R);
    brush.endShape(true);
  }
  brush.noWash();

  // Second pass: Soft mottled gilt-brass & pastel patina washes across the mat
  const matTones = [
    { col: "#aca28e", op: 65 },
    { col: "#857c6a", op: 55 },
    { col: "#bbae98", op: 50 },
    { col: "#7c8e8c", op: 28 }, // Faint verdigris whisper
    { col: "#a8898c", op: 25 }  // Faint rose patina whisper
  ];
  for (let t = 0; t < matTones.length; t++) {
    brush.fill(matTones[t].col, matTones[t].op);
    brush.fillBleed(0.35, "in");
    brush.fillTexture(0.65, 0.40);
    for (let i = 0; i < 10; i++) {
      let a0 = random(360);
      let a1 = a0 + random(24, 48);
      let r1 = random(1.03, 1.18);
      let r2 = random(1.25, 1.65);
      brush.beginShape(0.35);
      brush.vertex(OVAL_CX + cos(a0) * OVAL_RX * r1, OVAL_CY + sin(a0) * OVAL_RY * r1);
      brush.vertex(OVAL_CX + cos(a1) * OVAL_RX * r1, OVAL_CY + sin(a1) * OVAL_RY * r1);
      brush.vertex(OVAL_CX + cos(a1) * OVAL_RX * r2, OVAL_CY + sin(a1) * OVAL_RY * r2);
      brush.vertex(OVAL_CX + cos(a0) * OVAL_RX * r2, OVAL_CY + sin(a0) * OVAL_RY * r2);
      brush.endShape(true);
    }
  }
  brush.noFill();

  // 2. Fine brushed gilt-brass metallic grain lines across the exterior mat
  for (let i = 0; i < 900; i++) {
    let sx = random(10, 1190);
    let sy = random(10, 1190);
    if (insideOval(sx, sy, -8)) continue;

    // Subtle directional sheen across the brass plate
    let sheen = Math.cos((sx - sy) * 0.004);
    let col;
    if (sheen > 0.35) {
      col = random() < 0.5 ? "#cbc0ab" : "#dcd3c0";
    } else if (sheen < -0.35) {
      col = random() < 0.5 ? "#756c5b" : "#635b4c";
    } else {
      col = random() < 0.5 ? "#8e8573" : "#afa592";
    }

    brush.set("2H", col, random(0.14, 0.24));
    let len = random(18, 55);
    // Vertical brushed brass grain mixed with slight radial chasing
    let ex = sx + random(-2, 2);
    let ey = sy + len;
    if (insideOval(ex, ey, -8)) continue;
    brush.line(sx, sy, ex, ey);
  }

  // 3. The Recessed Gilt-Brass Inner Bevel of the Oval Window
  const BEVEL_W = 13;
  const B_STEPS = 120;
  for (let i = 0; i < B_STEPS; i++) {
    let a0 = (i / B_STEPS) * 360;
    let a1 = ((i + 1) / B_STEPS) * 360;
    let am = (a0 + a1) * 0.5;

    // Upper-left bevel is in deep antique bronze shadow; lower-right catches champagne gilt light
    let lightDir = cos(am - 42); // Peaks at lower-right (42 deg)
    let bevelCol, innerRimCol, outerRimCol;

    if (lightDir > 0.25) {
      bevelCol = lightDir > 0.65 ? "#e6decb" : "#cdc3ae";
      innerRimCol = "#f5efe2";
      outerRimCol = "#786f5d";
    } else if (lightDir < -0.20) {
      bevelCol = lightDir < -0.60 ? "#3d382e" : "#544d40";
      innerRimCol = "#26231d";
      outerRimCol = "#b8ae99";
    } else {
      bevelCol = "#8a806d";
      innerRimCol = "#635c4e";
      outerRimCol = "#aba18d";
    }

    let x0_in = OVAL_CX + cos(a0) * (OVAL_RX - 2);
    let y0_in = OVAL_CY + sin(a0) * (OVAL_RY - 2);
    let x1_in = OVAL_CX + cos(a1) * (OVAL_RX - 2);
    let y1_in = OVAL_CY + sin(a1) * (OVAL_RY - 2);

    let x0_out = OVAL_CX + cos(a0) * (OVAL_RX + BEVEL_W);
    let y0_out = OVAL_CY + sin(a0) * (OVAL_RY + BEVEL_W);
    let x1_out = OVAL_CX + cos(a1) * (OVAL_RX + BEVEL_W);
    let y1_out = OVAL_CY + sin(a1) * (OVAL_RY + BEVEL_W);

    // Fill bevel facet with dense cross-strokes
    brush.set("HB", bevelCol, 0.36);
    for (let s = 0; s <= 4; s++) {
      let t = s / 4;
      let xi = x0_in + (x1_in - x0_in) * t;
      let yi = y0_in + (y1_in - y0_in) * t;
      let xo = x0_out + (x1_out - x0_out) * t;
      let yo = y0_out + (y1_out - y0_out) * t;
      brush.line(xi, yi, xo, yo);
    }

    // Inner lip where bevel meets the silver plate
    brush.set("2H", innerRimCol, 0.28);
    brush.line(x0_in, y0_in, x1_in, y1_in);

    // Outer ridge of the bevel
    brush.set("2H", outerRimCol, 0.24);
    brush.line(x0_out, y0_out, x1_out, y1_out);
  }

  // 4. Faint Stamped Concentric Double-Oval Groove & Outer Rectangular Mat Border
  for (let offset of [24, 31]) {
    let ptsLight = [];
    let ptsDark = [];
    for (let i = 0; i <= 90; i++) {
      let a = (i / 90) * 360;
      let px = OVAL_CX + cos(a) * (OVAL_RX + offset);
      let py = OVAL_CY + sin(a) * (OVAL_RY + offset);
      ptsDark.push([px, py]);
      ptsLight.push([px + 1.5, py + 1.5]);
    }
    brush.set("2H", "#5e5648", 0.16);
    brush.spline(ptsDark, 0.4);
    brush.set("2H", "#d4cbb8", 0.14);
    brush.spline(ptsLight, 0.4);
  }

  // Faint embossed outer rectangular border with chamfered corners (at margin 38px)
  const M = 38;
  const C = 68; // Corner chamfer
  const framePts = [
    [M + C, M], [1200 - M - C, M],
    [1200 - M, M + C], [1200 - M, 1200 - M - C],
    [1200 - M - C, 1200 - M], [M + C, 1200 - M],
    [M, 1200 - M - C], [M, M + C],
    [M + C, M]
  ];
  for (let i = 0; i < framePts.length - 1; i++) {
    let p1 = framePts[i];
    let p2 = framePts[i + 1];
    brush.set("2H", "#5c5446", 0.19);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("2H", "#d8cfbc", 0.16);
    brush.line(p1[0] + 1.8, p1[1] + 1.8, p2[0] + 1.8, p2[1] + 1.8);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Cool crisp engraving paper ground
  background("#eef3f8");

  const cx = 600;
  const cy = 600;
  const R_MUG_OUTER = 372;
  const R_MUG_LIP_IN = 336;
  const R_COFFEE = 312;

  // =========================================================================
  // 1. WASHING MACHINE LID: TONAL WASHES, BRUSHED STEEL & STIPPLE TEXTURE
  // =========================================================================
  drawWashingMachineLid(cx, cy, R_MUG_OUTER);

  // =========================================================================
  // 2. STRAY SOCK EDGE (TOP-LEFT CORNER OVERLAPPING LID SEAM)
  // =========================================================================
  drawStraySock();

  // =========================================================================
  // 3. MUG CAST SHADOW & HIGH-FREQUENCY JUDDER RINGS ON THE LID
  // =========================================================================
  drawMugShadowAndJudder(cx, cy, R_MUG_OUTER);

  // =========================================================================
  // 4. WHITE ENAMEL MUG HANDLE & ROLLED RIM (SEEN STRAIGHT DOWN)
  // =========================================================================
  drawMugHandle(cx, cy, R_MUG_OUTER);
  drawMugRimAndInnerWall(cx, cy, R_MUG_OUTER, R_MUG_LIP_IN, R_COFFEE);

  // =========================================================================
  // 5. TAN CREMA CRESCENTS AT THE RIM (TOUCHED WITH AMBER MARKER)
  // =========================================================================
  drawCremaCrescentsUnderlayer(cx, cy, R_COFFEE);

  // =========================================================================
  // 6. BLACK COFFEE: FINE-PEN CONCENTRIC ENGRAVING & FARADAY STANDING WAVES
  // =========================================================================
  drawCoffeeStandingWaves(cx, cy, R_COFFEE);

  // =========================================================================
  // 7. CREMA MICRO-BUBBLES & EXACT MENISCUS SPECULAR REFLECTIONS
  // =========================================================================
  drawCremaDetailAndMeniscus(cx, cy, R_COFFEE);

  noLoop();
}

// ---------------------------------------------------------------------------
// MATHEMATICAL MODEL: FARADAY STANDING WAVES, PETAL NODES & CREMA CRESCENTS
// ---------------------------------------------------------------------------

function gaussian(u, center, width) {
  let d = (u - center) / width;
  return Math.exp(-d * d);
}

// Returns thickness (in pixels inward from R_COFFEE) of the tan crema at angle theta (radians)
function getCremaWidth(theta) {
  let deg = ((theta * 180) / Math.PI + 360) % 360;

  // 4 asymmetrical crescent rafts pushed to the rim by the standing waves
  let c1 = 23 * Math.pow(Math.max(0, 1 - Math.pow((deg - 48) / 36, 2)), 1.6);
  let c2 = 17 * Math.pow(Math.max(0, 1 - Math.pow((deg - 136) / 30, 2)), 1.7);
  let c3 = 13 * Math.pow(Math.max(0, 1 - Math.pow((deg - 206) / 20, 2)), 1.8);
  let c4 = 25 * Math.pow(Math.max(0, 1 - Math.pow((deg - 298) / 44, 2)), 1.5);

  // Secondary tail on crescent 4
  let c4b = 14 * Math.pow(Math.max(0, 1 - Math.pow((deg - 342) / 18, 2)), 1.6);

  let base = Math.max(c1, c2, c3, c4, c4b);
  if (base <= 0.2) return 0;

  // Scalloped inner edge shaped by the 24-petal and 36-petal capillary wave nodes
  let scallop =
    1.0 +
    0.22 * Math.cos(24 * theta) +
    0.14 * Math.sin(36 * theta) +
    0.1 * Math.cos(12 * theta - 0.4);

  return base * scallop;
}

// Evaluates standing wave height H, radial slope dH, and engraving darkness D at (r, theta)
function evalStandingWave(r, theta, R_COFFEE) {
  let u = r / R_COFFEE; // 0..1

  // Radial wavenumber increases slightly toward the meniscus
  let alpha = Math.PI * (17.2 * u + 2.6 * u * u * u);
  let cosA = Math.cos(alpha);
  let sinA = Math.sin(alpha);

  // 1. Concentric standing rings (9+ rings from center bullseye to rim)
  let ringWave = 0.72 * cosA;

  // 2. Petal-like Faraday nodes (harmonically locked 6, 12, 24, 36-fold rotational symmetry)
  let envInner = gaussian(u, 0.23, 0.14) * Math.sin(Math.PI * Math.min(1, u * 3.5));
  let envMid = gaussian(u, 0.54, 0.20);
  let envOuter = gaussian(u, 0.81, 0.13);

  // On-ring petal beading
  let modeOnRing =
    (0.24 * envInner * Math.cos(12 * theta) +
      0.28 * envMid * Math.cos(24 * theta) +
      0.22 * envOuter * Math.cos(36 * theta)) *
    cosA;

  // Inter-ring diamond/petal standing mounds rising out of the troughs (where sinA is strong)
  let modeBetween =
    (0.68 * envInner * Math.cos(12 * theta + Math.PI) +
      0.72 * envMid * Math.cos(24 * theta) +
      0.56 * envOuter * Math.cos(36 * theta + Math.PI) +
      0.25 * gaussian(u, 0.11, 0.06) * Math.cos(6 * theta)) *
    sinA;

  // Meniscus capillary compression (u > 0.90)
  let meniscusWave = 0;
  if (u > 0.89) {
    let um = (u - 0.89) / 0.11;
    meniscusWave = 0.55 * Math.cos(um * 5.0 * Math.PI) * (1 + 0.25 * Math.cos(36 * theta));
  }

  let H = ringWave + modeOnRing + modeBetween + meniscusWave;

  // Approximate radial slope for overhead/angled window reflection
  let dH =
    -0.72 * sinA +
    (0.45 * envInner * Math.cos(12 * theta + Math.PI) +
      0.50 * envMid * Math.cos(24 * theta)) *
      cosA;

  // Overhead cool studio window light at 230 deg (top-left) and bounce at 50 deg (bottom-right)
  let lightAngle = (230 * Math.PI) / 180;
  let dirLight = Math.cos(theta - lightAngle);

  // Exact anamorphic window reflection factor on wave slopes
  let deg = ((theta * 180) / Math.PI + 360) % 360;
  let inMainWindow =
    deg > 202 && deg < 258 && Math.abs(deg - 230) > 2.4; // Split twin-tube / two-pane window
  let inBounceWindow = deg > 34 && deg < 66 && Math.abs(deg - 50) > 2.0;

  let windowSpec = 0;
  if (inMainWindow && dH < -0.18 && H > -0.15) {
    windowSpec = 0.36;
  } else if (inBounceWindow && dH > 0.22 && H > 0.0) {
    windowSpec = 0.24;
  }

  // Meniscus steep concave reflection right at the rim
  if (u > 0.955 && (inMainWindow || inBounceWindow)) {
    windowSpec += 0.45;
  }

  // Combined crest brightness
  let crestScore = H - 0.26 * dH * (0.65 + 0.35 * dirLight) + windowSpec;

  // Central bullseye peak highlight
  if (u < 0.032) {
    crestScore += 0.35 * (1 - u / 0.032);
  }

  // Check if inside crema crescent near rim
  let cremaW = getCremaWidth(theta);
  let distFromRim = R_COFFEE - r;
  let inCrema = distFromRim < cremaW && distFromRim >= 0;

  // White paper crest threshold: when crestScore > 0.54, pen lifts completely!
  let isWhiteCrest = crestScore > 0.54;

  // Darkness D in [0, 1] for engraving density and pressure
  let D = 0;
  if (!isWhiteCrest && !inCrema) {
    D = constrain(map(crestScore, 0.54, -1.15, 0.08, 1.0), 0, 1);
    // Slight overall darkening in the deep middle annulus of the black coffee
    D = Math.pow(D, 0.85);
  }

  return {
    H: H,
    dH: dH,
    crestScore: crestScore,
    isWhiteCrest: isWhiteCrest,
    inCrema: inCrema,
    cremaW: cremaW,
    D: D
  };
}

// ---------------------------------------------------------------------------
// 1. WASHING MACHINE LID (BRUSHED STEEL, STIPPLE, SEAMS & VIBRATING DROPLETS)
// ---------------------------------------------------------------------------
function drawWashingMachineLid(cx, cy, R_MUG_OUTER) {
  // Subtle cool steel-blue watercolor washes around the outer corners of the lid
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.45, 0.2);

  // Batch cool slate-blue corner washes
  brush.fill("#dbe5f0", 75);
  brush.beginShape(0.2);
  brush.vertex(0, 0);
  brush.vertex(1200, 0);
  brush.vertex(1200, 220);
  brush.vertex(0, 260);
  brush.endShape(true);

  brush.beginShape(0.2);
  brush.vertex(0, 960);
  brush.vertex(1200, 900);
  brush.vertex(1200, 1200);
  brush.vertex(0, 1200);
  brush.endShape(true);
  brush.noFill();

  // Horizontal brushed-steel micro-lines across the lid (skipping inside the mug!)
  let mugSafeR = R_MUG_OUTER - 2;
  for (let y = 12; y < 1192; y += 4.2) {
    let dy = y - cy;
    let judderY = y + random(-0.6, 0.6);

    // Choose cool steel tone
    if (int(y) % 3 === 0) {
      brush.set("2H", "#9eb0c2", random(0.22, 0.36));
    } else if (int(y) % 3 === 1) {
      brush.set("rotring", "#b4c3d2", random(0.18, 0.28));
    } else {
      brush.set("2H", "#7e91a6", random(0.2, 0.32));
    }

    // Break horizontal brushed lines cleanly around the circular mug
    if (Math.abs(dy) >= mugSafeR) {
      let x1 = 10;
      let x2 = 1190;
      // Add subtle segmentation for brushed metal sheen
      let mid1 = random(320, 480);
      let mid2 = random(720, 880);
      brush.line(x1, judderY, mid1, judderY + random(-0.4, 0.4));
      brush.line(mid1 + random(8, 28), judderY, mid2, judderY + random(-0.4, 0.4));
      brush.line(mid2 + random(8, 28), judderY, x2, judderY + random(-0.4, 0.4));
    } else {
      let dx = Math.sqrt(mugSafeR * mugSafeR - dy * dy);
      let leftEnd = cx - dx;
      let rightStart = cx + dx;
      if (leftEnd > 20) {
        brush.line(10, judderY, leftEnd, judderY + random(-0.3, 0.3));
      }
      if (rightStart < 1180) {
        brush.line(rightStart, judderY, 1190, judderY + random(-0.3, 0.3));
      }
    }
  }

  // Stippled brushed-steel grain using spray brush in cool steel-grey arc bands outside the mug
  for (let i = 0; i < 65; i++) {
    let ang = random(0, 360);
    let rad = random(R_MUG_OUTER + 18, 760);
    let sx = cx + rad * cos(ang);
    let sy = cy + rad * sin(ang);
    if (sx > 20 && sx < 1180 && sy > 20 && sy < 1180) {
      brush.set("spray", i % 2 === 0 ? "#6d8094" : "#8fa1b5", random(0.35, 0.65));
      let len = random(40, 110);
      brush.line(sx - len / 2, sy, sx + len / 2, sy + random(-1.5, 1.5));
    }
  }

  // Fine pen stipple dots and harmonic chladni vibration dust on the lid around the mug
  brush.set("rotring", "#54667a", 0.35);
  for (let ring = 0; ring < 5; ring++) {
    let rVib = R_MUG_OUTER + 28 + ring * 38;
    let steps = 160;
    for (let s = 0; s < steps; s++) {
      let a = (s / steps) * 360;
      // Harmonic nodal clustering on the vibrating steel sheet
      let nodeFactor = Math.sin(12 * (a * Math.PI) / 180) * Math.cos(ring * 1.3);
      if (random() < 0.38 + 0.35 * nodeFactor) {
        let px = cx + (rVib + random(-6, 6)) * cos(a);
        let py = cy + (rVib + random(-6, 6)) * sin(a);
        if (px > 15 && px < 1185 && py > 15 && py < 1185) {
          brush.line(px, py, px + random(1.2, 2.8), py + random(-0.8, 0.8));
        }
      }
    }
  }

  // Washing machine top-loader recessed lid seam (top horizontal & left vertical with rounded corner)
  // Drawn with a subtle high-frequency judder ghost offset to show the machine vibrating!
  const seamY = 92;
  const seamX = 76;
  const cornerR = 44;

  // Soft shadow inside the lid seam
  brush.set("charcoal", "#8fa2b5", 0.9);
  brush.line(seamX + cornerR, seamY + 3, 1190, seamY + 3);
  brush.line(seamX + 3, seamY + cornerR, seamX + 3, 1190);

  // Crisp double-ghosted judder seam lines
  let offsets = [
    { dx: 0, dy: 0, col: "#253342", w: 0.65 },
    { dx: 2.6, dy: 1.4, col: "#6c7f94", w: 0.32 },
    { dx: -2.0, dy: -1.1, col: "#8fa2b5", w: 0.25 }
  ];

  for (let o of offsets) {
    brush.set("rotring", o.col, o.w);
    brush.line(seamX + cornerR + o.dx, seamY + o.dy, 1190, seamY + o.dy);
    brush.line(seamX + o.dx, seamY + cornerR + o.dy, seamX + o.dx, 1190);
    brush.arc(seamX + cornerR + o.dx, seamY + cornerR + o.dy, cornerR, 180, 270);
  }

  // Specular highlight lip along the bottom/right edge of the recessed lid gap
  brush.set("rotring", "#f8fbff", 0.55);
  brush.line(seamX + cornerR, seamY + 5.5, 1190, seamY + 5.5);
  brush.line(seamX + 5.5, seamY + cornerR, seamX + 5.5, 1190);

  // Small engraved lid-lock / spin status indicator etched on top-right bezel
  drawLidLockIndicator(1035, 48);

  // Two tiny vibrating water droplets on the steel lid (top-right and bottom-left)
  drawVibratingDroplet(1015, 265, 16);
  drawVibratingDroplet(1055, 302, 9.5);
  drawVibratingDroplet(195, 985, 12.5);
}

function drawLidLockIndicator(x, y) {
  // Subtle judder-doubled technical markings on the top bezel
  for (let pass = 0; pass < 2; pass++) {
    let dx = pass * 2.2;
    let dy = pass * 1.1;
    let col = pass === 0 ? "#3c4e61" : "#8a9cb0";
    let w = pass === 0 ? 0.38 : 0.22;

    brush.set("rotring", col, w);
    brush.rect(x + dx, y + dy, 84, 24, "center");
    brush.circle(x - 24 + dx, y + dy, 5.5, 0.05);
    // Tiny lock shackle arc
    brush.arc(x - 24 + dx, y - 5 + dy, 3.5, 180, 360);
    // Etched status bars representing text
    brush.line(x - 8 + dx, y - 3 + dy, x + 30 + dx, y - 3 + dy);
    brush.line(x - 8 + dx, y + 4 + dy, x + 18 + dx, y + 4 + dy);
  }
}

function drawVibratingDroplet(dx, dy, rad) {
  // Cast shadow of droplet
  brush.set("rotring", "#687b8f", 0.3);
  for (let i = -rad * 0.8; i <= rad * 0.8; i += 2.0) {
    let half = Math.sqrt(Math.max(0, rad * rad - i * i));
    brush.line(dx + 3 - half * 0.7, dy + 4 + i, dx + 3 + half * 0.9, dy + 4 + i);
  }
  // Concentric standing micro-ripples inside the water droplet
  brush.set("rotring", "#334457", 0.32);
  brush.circle(dx, dy, rad, 0.08);
  brush.set("rotring", "#63778c", 0.24);
  brush.circle(dx + 1.4, dy + 0.8, rad, 0.08); // judder ghost
  for (let r = rad * 0.35; r < rad * 0.9; r += 2.6) {
    brush.set("rotring", "#475a6e", 0.25);
    brush.arc(dx, dy, r, 15, 195);
    brush.arc(dx, dy, r, 265, 345);
  }
  // Crisp white specular crescent on upper-left of droplet
  brush.set("rotring", "#ffffff", 0.55);
  brush.arc(dx - rad * 0.15, dy - rad * 0.15, rad * 0.65, 200, 260);
}

// ---------------------------------------------------------------------------
// 2. STRAY SOCK EDGE (RIBBED COTTON CUFF IN TOP-LEFT CORNER)
// ---------------------------------------------------------------------------
function drawStraySock() {
  // The sock cuff enters from the top-left corner, curving from (0, 355) to (335, 0)
  // 1. Cast shadow of the sock onto the washing machine lid
  brush.noStroke();
  brush.fillBleed(0.2, "out");
  brush.fill("#8c9fb3", 110);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(352, 0);
  brush.vertex(310, 95);
  brush.vertex(225, 215);
  brush.vertex(115, 305);
  brush.vertex(0, 372);
  brush.endShape(true);
  brush.noFill();

  // Cross-hatched pen shadow under the sock edge
  brush.set("rotring", "#3d4f63", 0.32);
  for (let s = 0; s <= 1; s += 0.012) {
    let bx = lerp(0, 335, s);
    let by = lerp(352, 0, s) + 28 * Math.sin(s * Math.PI);
    brush.line(bx, by, bx + 18, by + 22);
    if (int(s * 100) % 2 === 0) {
      brush.line(bx + 3, by + 8, bx + 24, by + 12);
    }
  }

  // 2. Opaque base wash for the cool off-white cotton sock so it covers the lid seam
  brush.noStroke();
  brush.wash("#e7edf4", 245);
  brush.beginShape(0.25);
  brush.vertex(0, 0);
  brush.vertex(332, 0);
  brush.vertex(288, 82);
  brush.vertex(205, 194);
  brush.vertex(102, 282);
  brush.vertex(0, 348);
  brush.endShape(true);
  brush.noWash();

  // Cool shadow tone wash along the folded cuff ridge
  brush.fillBleed(0.15, "in");
  brush.fill("#c5d2e0", 120);
  brush.beginShape(0.25);
  brush.vertex(0, 260);
  brush.vertex(165, 140);
  brush.vertex(275, 0);
  brush.vertex(332, 0);
  brush.vertex(205, 194);
  brush.vertex(0, 348);
  brush.endShape(true);
  brush.noFill();

  // 3. Ribbed knit geometry of the athletic sock cuff
  const numRibs = 22;
  for (let i = 0; i < numRibs; i++) {
    let t0 = i / numRibs;
    let t1 = (i + 1) / numRibs;
    let tm = (t0 + t1) * 0.5;

    // Outer cuff edge coordinates
    let xEdge = lerp(0, 330, tm);
    let yEdge = lerp(346, 0, tm) + 24 * Math.sin(tm * Math.PI);

    // Direction perpendicular to cuff edge (pointing inward toward top-left)
    let dirX = -0.72;
    let dirY = -0.69;

    // Draw two cool navy/slate athletic stripes woven across the ribs
    for (let st = 0; st < 2; st++) {
      let dStart = st === 0 ? 52 : 96;
      let dEnd = st === 0 ? 78 : 120;
      let stripeCol = st === 0 ? "#284363" : "#446487";
      brush.set("marker", stripeCol, 0.75);
      // Slight rib arch on each stripe segment
      let sx1 = xEdge + dirX * dStart;
      let sy1 = yEdge + dirY * dStart;
      let sx2 = xEdge + dirX * dEnd;
      let sy2 = yEdge + dirY * dEnd;
      brush.line(sx1, sy1, sx2, sy2);
    }

    // Fine-pen engraving of the rib valleys and knit stitches
    let xVal = lerp(0, 330, t0);
    let yVal = lerp(346, 0, t0) + 24 * Math.sin(t0 * Math.PI);
    brush.set("rotring", "#495c70", 0.36);
    let ribPts = [];
    for (let d = 0; d <= 185; d += 18) {
      let px = xVal + dirX * d + 2.5 * Math.sin(d * 0.06);
      let py = yVal + dirY * d - 2.5 * Math.cos(d * 0.06);
      if (px >= -5 && py >= -5) {
        ribPts.push([px, py, map(d, 0, 185, 1.1, 0.4)]);
      }
    }
    if (ribPts.length >= 3) {
      brush.spline(ribPts, 0.3);
    }

    // Cross-contour knit v-stitches along each rib
    brush.set("2H", "#6f8296", 0.26);
    for (let d = 8; d < 170; d += 7.5) {
      let cxRib = xEdge + dirX * d;
      let cyRib = yEdge + dirY * d;
      if (cxRib > 2 && cyRib > 2) {
        brush.line(cxRib - 5, cyRib + 2, cxRib, cyRib - 3);
        brush.line(cxRib, cyRib - 3, cxRib + 4, cyRib + 4);
      }
    }

    // Scalloped rib silhouette at the sock edge + fuzzy stray cotton fiber loops
    brush.set("rotring", "#2b3b4d", 0.45);
    let xNext = lerp(0, 330, t1);
    let yNext = lerp(346, 0, t1) + 24 * Math.sin(t1 * Math.PI);
    brush.spline(
      [
        [xVal, yVal, 0.7],
        [xEdge + 3.5, yEdge + 3.5, 1.1],
        [xNext, yNext, 0.7]
      ],
      0.5
    );

    // Microscopic cotton fuzz hairs catching the light along the edge
    brush.set("rotring", "#566a80", 0.2);
    for (let f = 0; f < 5; f++) {
      let ft = lerp(t0, t1, f / 5);
      let fx = lerp(0, 330, ft);
      let fy = lerp(346, 0, ft) + 24 * Math.sin(ft * Math.PI);
      brush.line(fx, fy, fx + random(3, 8), fy + random(3, 8));
    }
  }
}

// ---------------------------------------------------------------------------
// 3. MUG CAST SHADOW & HIGH-FREQUENCY JUDDER RINGS ON THE LID
// ---------------------------------------------------------------------------
function drawMugShadowAndJudder(cx, cy, R_MUG_OUTER) {
  // Cool directional cast shadow shifted slightly toward bottom-right (away from 230 deg light)
  const shX = cx + 22;
  const shY = cy + 26;
  const shR = R_MUG_OUTER + 14;

  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fill("#8ea2b8", 95);
  brush.circle(shX, shY, shR, 0.03);
  brush.noFill();

  // Engraved radial and tangential cross-hatching in the mug's cast shadow Crescent
  for (let r = R_MUG_OUTER - 2; r < R_MUG_OUTER + 56; r += 2.6) {
    let tNorm = (r - R_MUG_OUTER) / 58;
    // Shadow is strongest on bottom-right (angle -35 to +135 deg) and tighter on top-left
    let span = lerp(115, 52, tNorm);
    let startA = 50 - span;
    let endA = 50 + span;

    let col = tNorm < 0.35 ? "#1e2b3a" : tNorm < 0.7 ? "#43566b" : "#75899e";
    let w = map(tNorm, 0, 1, 0.52, 0.22);
    brush.set("rotring", col, w);
    brush.arc(cx + lerp(2, 16, tNorm), cy + lerp(2, 18, tNorm), r, startA, endA);
  }

  // Ambient occlusion hatching all around the base of the mug
  for (let a = 0; a < 360; a += 1.6) {
    let rad = (a * Math.PI) / 180;
    let shadowSide = Math.max(0, Math.cos(rad - (50 * Math.PI) / 180));
    let len = 10 + 38 * Math.pow(shadowSide, 1.5);
    brush.set("rotring", shadowSide > 0.4 ? "#273647" : "#566a80", 0.3);
    let x1 = cx + (R_MUG_OUTER - 1) * cos(a);
    let y1 = cy + (R_MUG_OUTER - 1) * sin(a);
    let x2 = cx + (R_MUG_OUTER + len) * cos(a + 2.5);
    let y2 = cy + (R_MUG_OUTER + len) * sin(a + 2.5);
    brush.line(x1, y1, x2, y2);
  }

  // High-frequency judder ghost contours around the mug perimeter
  let judderArcs = [
    { dx: 4.2, dy: 2.1, col: "#5a6e82", w: 0.32, a1: -40, a2: 140 },
    { dx: -3.6, dy: -1.8, col: "#72869b", w: 0.28, a1: 140, a2: 320 },
    { dx: 6.8, dy: 3.4, col: "#8da0b4", w: 0.22, a1: -20, a2: 115 },
    { dx: -5.5, dy: 2.8, col: "#96a8bc", w: 0.20, a1: 110, a2: 245 }
  ];
  for (let j of judderArcs) {
    brush.set("rotring", j.col, j.w);
    brush.arc(cx + j.dx, cy + j.dy, R_MUG_OUTER + 1.5, j.a1, j.a2);
  }
}

// ---------------------------------------------------------------------------
// 4. WHITE ENAMEL MUG HANDLE & ROLLED RIM
// ---------------------------------------------------------------------------
function drawMugHandle(cx, cy, R_MUG_OUTER) {
  // Handle projects outward at 38 degrees (bottom-right)
  const hAngle = 38;
  push();
  translate(cx, cy);
  rotate(hAngle);

  // 1. Cast shadow of the handle on the washing machine lid
  brush.noStroke();
  brush.fillBleed(0.2, "out");
  brush.fill("#7c90a6", 115);
  brush.beginShape(0.2);
  brush.vertex(R_MUG_OUTER - 5, -28);
  brush.vertex(R_MUG_OUTER + 132, -24);
  brush.vertex(R_MUG_OUTER + 138, 62);
  brush.vertex(R_MUG_OUTER - 5, 58);
  brush.endShape(true);
  brush.noFill();

  // Cross-hatched pen shadow under the handle
  brush.set("rotring", "#2f4052", 0.32);
  for (let x = R_MUG_OUTER + 4; x < R_MUG_OUTER + 132; x += 4.5) {
    brush.line(x, 34, x + 12, 62);
    brush.line(x + 2, 42, x - 8, 60);
  }

  // Judder ghost outline of the vibrating handle
  brush.set("rotring", "#6d8094", 0.28);
  brush.rect(R_MUG_OUTER + 58 + 3.5, 2 + 2.2, 128, 74, "center");

  // 2. Opaque white enamel wash for the handle top surface
  brush.noStroke();
  brush.wash("#eef3f8", 255);
  brush.beginShape(0.15);
  brush.vertex(R_MUG_OUTER - 12, -38);
  brush.vertex(R_MUG_OUTER + 116, -34);
  brush.vertex(R_MUG_OUTER + 124, 0);
  brush.vertex(R_MUG_OUTER + 116, 34);
  brush.vertex(R_MUG_OUTER - 12, 38);
  brush.endShape(true);
  brush.noWash();

  // 3. Curved contour hatching modeling the rounded 3D spine of the white enamel handle
  // Leave the upper-center ridge (y around -12 to -3) as pure white paper specular highlight!
  for (let x = R_MUG_OUTER - 6; x <= R_MUG_OUTER + 118; x += 3.0) {
    let t = (x - (R_MUG_OUTER - 6)) / 124;
    let halfW = lerp(37, 33, Math.sin(t * Math.PI));

    // Lower shaded slope of handle spine
    brush.set("rotring", "#53677d", 0.3);
    brush.line(x, 2, x, halfW - 4);
    brush.set("rotring", "#2b3b4e", 0.38);
    brush.line(x, halfW * 0.45, x, halfW - 2);

    // Upper bevel of handle spine
    brush.set("2H", "#7c90a6", 0.26);
    brush.line(x, -halfW + 4, x, -15);
  }

  // Dark navy-black enameled edge trim along the two sides and outer curve of the handle
  brush.set("rotring", "#131d2b", 0.95);
  brush.spline(
    [
      [R_MUG_OUTER - 10, -37, 0.9],
      [R_MUG_OUTER + 60, -35, 1.0],
      [R_MUG_OUTER + 116, -32, 1.1],
      [R_MUG_OUTER + 123, 0, 1.2],
      [R_MUG_OUTER + 116, 32, 1.1],
      [R_MUG_OUTER + 60, 35, 1.0],
      [R_MUG_OUTER - 10, 37, 0.9]
    ],
    0.35
  );

  // Crisp white specular reflection streak down the center of the glossy handle
  brush.set("rotring", "#425569", 0.24);
  brush.line(R_MUG_OUTER - 2, -13, R_MUG_OUTER + 108, -11);
  brush.line(R_MUG_OUTER - 2, -3, R_MUG_OUTER + 108, -3);

  pop();
}

function drawMugRimAndInnerWall(cx, cy, R_MUG_OUTER, R_MUG_LIP_IN, R_COFFEE) {
  // 1. Dark Navy-Black Rolled Enamel Outer Rim Band (r = 362..372)
  for (let r = R_MUG_OUTER - 9.5; r <= R_MUG_OUTER; r += 1.35) {
    let isMidRim = Math.abs(r - (R_MUG_OUTER - 4.5)) < 2.2;
    for (let seg = 0; seg < 72; seg++) {
      let a1 = seg * 5;
      let a2 = (seg + 1) * 5;
      let am = (a1 + a2) * 0.5;

      // Specular white paper breaks on the dark enamel rim band at ~230 deg and ~50 deg
      let specRim =
        (isMidRim && am > 212 && am < 248 && Math.abs(am - 230) > 3) ||
        (isMidRim && am > 42 && am < 58);

      if (!specRim) {
        let col = isMidRim ? "#1e2e42" : "#0d1520";
        brush.set("rotring", col, 0.62);
        brush.arc(cx, cy, r, a1, a2);
      }
    }
  }

  // Two tiny hyperreal chipped-enamel / wear flecks on the dark rim
  brush.set("rotring", "#3a4c5e", 0.35);
  brush.circle(cx + (R_MUG_OUTER - 5) * cos(142), cy + (R_MUG_OUTER - 5) * sin(142), 3.2, 0.2);
  brush.circle(cx + (R_MUG_OUTER - 5) * cos(312), cy + (R_MUG_OUTER - 5) * sin(312), 2.5, 0.2);

  // 2. White Porcelain-Enamel Rolled Lip (r = 336..362)
  // Keep bright white paper for the highlight crown (r = 345..354), engrave subtle torus curvature
  for (let r = R_MUG_LIP_IN; r < R_MUG_OUTER - 9.5; r += 2.2) {
    let uLip = (r - R_MUG_LIP_IN) / (R_MUG_OUTER - 9.5 - R_MUG_LIP_IN); // 0..1 across lip
    // Highlight crown sits around uLip = 0.35..0.68
    if (uLip < 0.32 || uLip > 0.72) {
      let col = uLip < 0.32 ? "#6d8196" : "#7e92a7";
      brush.set("2H", col, 0.25);
      // Break into soft arcs away from the main 230 deg light source
      brush.arc(cx, cy, r, 275, 445);
      brush.arc(cx, cy, r, 75, 185);
    }
  }

  // Fine radial torus cross-hatching on the white enamel lip
  for (let a = 0; a < 360; a += 2.0) {
    let rad = (a * Math.PI) / 180;
    // Leave pure white paper at the specular window reflections (210..250 and 35..65)
    let inSpec = (a > 208 && a < 252) || (a > 36 && a < 64);
    if (!inSpec) {
      let shade = 0.5 + 0.5 * Math.sin(rad * 2 - 0.6);
      if (shade > 0.35) {
        brush.set("2H", shade > 0.7 ? "#6b7f94" : "#96a8bc", 0.24);
        let r1 = R_MUG_LIP_IN + 1;
        let r2 = R_MUG_LIP_IN + 6 + 6 * shade;
        brush.line(cx + r1 * cos(a), cy + r1 * sin(a), cx + r2 * cos(a), cy + r2 * sin(a));
      }
    }
  }

  // 3. Steep Inner Wall of the White Enamel Mug Above the Coffee (r = 312..336)
  // Upper-left wall (around 230 deg) is in shadow from the mug lip; lower-right wall catches the light!
  for (let r = R_COFFEE; r <= R_MUG_LIP_IN; r += 1.5) {
    let wallT = (r - R_COFFEE) / (R_MUG_LIP_IN - R_COFFEE); // 0 at coffee edge, 1 at lip
    // Reflected standing-wave ripples on the glossy inner porcelain wall!
    let rippleMod = Math.sin(wallT * Math.PI * 5);

    for (let seg = 0; seg < 90; seg++) {
      let a1 = seg * 4;
      let a2 = (seg + 1) * 4;
      let am = ((a1 + a2) * 0.5 * Math.PI) / 180;

      // Shadow strongest around 230 deg (top-left inner wall)
      let wallShadow = 0.55 + 0.45 * Math.cos(am - (230 * Math.PI) / 180) + 0.12 * rippleMod;

      // Bright window reflection on lower-right inner wall (around 35..68 deg) stays pure white paper
      let deg = (a1 + a2) * 0.5;
      let innerWallSpec = deg > 30 && deg < 72 && Math.abs(deg - 50) > 2.5 && rippleMod > -0.2;

      if (!innerWallSpec && wallShadow > 0.28) {
        let col =
          wallShadow > 0.78
            ? "#2d3e52"
            : wallShadow > 0.52
            ? "#55687d"
            : "#8598ad";
        let w = map(wallShadow, 0.28, 1.1, 0.22, 0.48);
        brush.set("rotring", col, w);
        brush.arc(cx, cy, r, a1, a2);
      }
    }
  }

  // Vertical curved shading lines down the steep inner mug wall
  for (let a = 0; a < 360; a += 1.8) {
    let rad = (a * Math.PI) / 180;
    let wallShadow = 0.5 + 0.5 * Math.cos(rad - (230 * Math.PI) / 180);
    if (wallShadow > 0.45) {
      brush.set("rotring", wallShadow > 0.75 ? "#384a5e" : "#6c8096", 0.26);
      let x1 = cx + R_MUG_LIP_IN * cos(a);
      let y1 = cy + R_MUG_LIP_IN * sin(a);
      let x2 = cx + (R_COFFEE + 1) * cos(a);
      let y2 = cy + (R_COFFEE + 1) * sin(a);
      brush.line(x1, y1, x2, y2);
    }
  }
}

// ---------------------------------------------------------------------------
// 5. TAN CREMA CRESCENTS AT THE RIM (TOUCHED WITH AMBER MARKER)
// ---------------------------------------------------------------------------
function drawCremaCrescentsUnderlayer(cx, cy, R_COFFEE) {
  // First: warm tan watercolor fill along the 4 crescent zones
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.5, 0.35);

  const crescentRanges = [
    { start: 12, end: 84 },
    { start: 106, end: 166 },
    { start: 186, end: 226 },
    { start: 254, end: 356 }
  ];

  brush.fill("#e8b478", 155);
  for (let cr of crescentRanges) {
    brush.beginShape(0.25);
    // Outer edge along R_COFFEE - 1.5
    for (let a = cr.start; a <= cr.end; a += 3) {
      let rad = (a * Math.PI) / 180;
      let rOut = R_COFFEE - 1.5;
      brush.vertex(cx + rOut * Math.cos(rad), cy + rOut * Math.sin(rad));
    }
    // Scalloped inner edge
    for (let a = cr.end; a >= cr.start; a -= 3) {
      let rad = (a * Math.PI) / 180;
      let w = getCremaWidth(rad);
      let rIn = R_COFFEE - Math.max(2, w);
      brush.vertex(cx + rIn * Math.cos(rad), cy + rIn * Math.sin(rad));
    }
    brush.endShape(true);
  }
  brush.noFill();

  // Second: Touches of warm AMBER MARKER along the crema crescents
  for (let cr of crescentRanges) {
    // Outer warm amber band
    brush.set("marker", "#d47e2a", 0.68);
    let ptsOuter = [];
    for (let a = cr.start + 3; a <= cr.end - 3; a += 2.5) {
      let rad = (a * Math.PI) / 180;
      let w = getCremaWidth(rad);
      if (w > 4) {
        let rMid = R_COFFEE - w * 0.42;
        ptsOuter.push([cx + rMid * Math.cos(rad), cy + rMid * Math.sin(rad), 0.9]);
      }
    }
    if (ptsOuter.length >= 3) {
      brush.spline(ptsOuter, 0.35);
    }

    // Golden-tan marker highlight touches inside the thicker crescents
    brush.set("marker", "#e8a352", 0.52);
    let ptsInner = [];
    for (let a = cr.start + 6; a <= cr.end - 6; a += 3) {
      let rad = (a * Math.PI) / 180;
      let w = getCremaWidth(rad);
      if (w > 8) {
        let rIn = R_COFFEE - w * 0.72;
        ptsInner.push([cx + rIn * Math.cos(rad), cy + rIn * Math.sin(rad), 0.75]);
      }
    }
    if (ptsInner.length >= 3) {
      brush.spline(ptsInner, 0.35);
    }

    // Rich burnt-amber marker accents at the crescent tips and deeper scalloped bays
    brush.set("marker", "#a85216", 0.42);
    for (let a = cr.start + 2; a <= cr.end - 2; a += 7.5) {
      let rad1 = (a * Math.PI) / 180;
      let rad2 = ((a + 4.5) * Math.PI) / 180;
      let w1 = getCremaWidth(rad1);
      let w2 = getCremaWidth(rad2);
      if (w1 > 3 && w2 > 3) {
        let r1 = R_COFFEE - w1 * 0.88;
        let r2 = R_COFFEE - w2 * 0.88;
        brush.line(
          cx + r1 * Math.cos(rad1),
          cy + r1 * Math.sin(rad1),
          cx + r2 * Math.cos(rad2),
          cy + r2 * Math.sin(rad2)
        );
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 6. BLACK COFFEE: FINE-PEN CONCENTRIC ENGRAVING & FARADAY STANDING WAVES
// ---------------------------------------------------------------------------
function drawCoffeeStandingWaves(cx, cy, R_COFFEE) {
  // Helper to trace concentric engraved rings that warp over the 3D wave height H
  // and lift cleanly over every white paper ring crest, petal crest, and crema crescent
  function traceEngravingPass(rStart, rEnd, rStep, minD, brushName, colorHex, baseWeight, warpScale, angleOffsetDeg) {
    brush.set(brushName, colorHex, baseWeight);
    const numSteps = 180; // every 2 degrees around the circle

    for (let rBase = rStart; rBase <= rEnd; rBase += rStep) {
      let currentPts = [];

      for (let i = 0; i <= numSteps; i++) {
        let deg = i * (360 / numSteps) + angleOffsetDeg;
        let theta = (deg * Math.PI) / 180;

        let state = evalStandingWave(rBase, theta, R_COFFEE);

        if (!state.isWhiteCrest && !state.inCrema && state.D >= minD) {
          // Displace radius slightly by 3D wave height H for authentic burin/engraving swell
          let rWarped = rBase + warpScale * state.H;
          rWarped = constrain(rWarped, 1.5, R_COFFEE - 1.2);

          let px = cx + rWarped * Math.cos(theta);
          let py = cy + rWarped * Math.sin(theta);

          // Modulate pen pressure along the spline according to local darkness D
          let pressure = map(state.D, minD, 1.0, 0.55, 1.35);
          currentPts.push([px, py, pressure]);
        } else {
          // Flush accumulated segment before the white paper crest!
          if (currentPts.length >= 3) {
            brush.spline(currentPts, 0.25);
          } else if (currentPts.length === 2) {
            brush.line(currentPts[0][0], currentPts[0][1], currentPts[1][0], currentPts[1][1]);
          }
          currentPts = [];
        }
      }

      if (currentPts.length >= 3) {
        brush.spline(currentPts, 0.25);
      } else if (currentPts.length === 2) {
        brush.line(currentPts[0][0], currentPts[0][1], currentPts[1][0], currentPts[1][1]);
      }
    }
  }

  // PASS 1: Deep Trough Undertone Rings (Rich cool blue-black ink in the deepest wave valleys)
  traceEngravingPass(4.0, R_COFFEE - 2.0, 3.0, 0.62, "pen", "#101926", 0.78, 1.2, 0);

  // PASS 2: Primary Fine-Pen Concentric Engraving (Defines all rings and petal nodes up to white crests)
  traceEngravingPass(2.5, R_COFFEE - 1.5, 1.85, 0.12, "rotring", "#162233", 0.44, 1.85, 0);

  // PASS 3: Interleaved Sub-Pixel Engraving Pass (Builds velvety black coffee density)
  traceEngravingPass(3.4, R_COFFEE - 1.8, 1.85, 0.28, "rotring", "#090e17", 0.48, -1.35, 1.0);

  // PASS 4: Deep Espresso-Black Core Engraving in the Darkest Wave Troughs
  traceEngravingPass(5.0, R_COFFEE - 3.0, 2.5, 0.50, "rotring", "#0d0908", 0.56, 0.6, 0.5);

  // PASS 5: Razor-Sharp Specular Boundary Hairlines & Petal Node Cusp Accents
  // In classical steel engraving, a whisper-thin line hugs the edge of white highlights
  brush.set("rotring", "#2b3e54", 0.24);
  const boundarySteps = 216;
  for (let rBase = 14; rBase < R_COFFEE - 6; rBase += 3.6) {
    for (let i = 0; i < boundarySteps; i++) {
      let theta1 = (i / boundarySteps) * Math.PI * 2;
      let theta2 = ((i + 1) / boundarySteps) * Math.PI * 2;
      let s1 = evalStandingWave(rBase, theta1, R_COFFEE);
      let s2 = evalStandingWave(rBase, theta2, R_COFFEE);

      // If transitioning into or out of a white paper petal crest, add a crisp radial/diagonal tick
      if (s1.isWhiteCrest !== s2.isWhiteCrest && !s1.inCrema && !s2.inCrema) {
        let rW = rBase + 1.5 * s1.H;
        let x1 = cx + rW * Math.cos(theta1);
        let y1 = cy + rW * Math.sin(theta1);
        let x2 = cx + (rW + 2.2) * Math.cos(theta2);
        let y2 = cy + (rW + 2.2) * Math.sin(theta2);
        brush.line(x1, y1, x2, y2);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 7. CREMA MICRO-BUBBLES & EXACT MENISCUS SPECULAR REFLECTIONS
// ---------------------------------------------------------------------------
function drawCremaDetailAndMeniscus(cx, cy, R_COFFEE) {
  // 1. Fine-pen engraving & micro-bubble stippling along the scalloped tan crema crescents
  for (let a = 0; a < 360; a += 0.9) {
    let rad = (a * Math.PI) / 180;
    let w = getCremaWidth(rad);

    if (w > 1.5) {
      // Scalloped inner boundary where tan crema meets black coffee
      let rInner = R_COFFEE - w;
      let ix = cx + rInner * Math.cos(rad);
      let iy = cy + rInner * Math.sin(rad);

      // Dark espresso-sepia pen stipple right at the crema-coffee interface
      brush.set("rotring", "#2b180a", 0.35);
      brush.line(ix, iy, ix + random(-2.2, 2.2), iy + random(-2.2, 2.2));

      // Warm sepia concentric hatching inside the crema foam
      if (w > 5 && int(a * 10) % 2 === 0) {
        brush.set("rotring", "#6e3d18", 0.25);
        for (let d = 2.5; d < w - 1.5; d += 3.2) {
          let rBubble = R_COFFEE - d;
          let bx = cx + rBubble * Math.cos(rad);
          let by = cy + rBubble * Math.sin(rad);
          brush.line(
            bx,
            by,
            cx + rBubble * Math.cos(rad + 0.015),
            cy + rBubble * Math.sin(rad + 0.015)
          );
        }
      }

      // Microscopic foam bubble rings trapped in the crema rafts
      if (w > 7 && random() < 0.32) {
        let rBub = R_COFFEE - random(2.5, w - 2.0);
        let bx = cx + rBub * Math.cos(rad);
        let by = cy + rBub * Math.sin(rad);
        brush.set("rotring", random() < 0.5 ? "#542c0e" : "#8c4f20", 0.22);
        brush.circle(bx, by, random(1.2, 2.8), 0.15);
      }
    }
  }

  // Satellite crema micro-bubbles drifting in the outer meniscus nodes between the main crescents
  const satelliteAngles = [4, 92, 96, 174, 179, 236, 242, 248];
  for (let sa of satelliteAngles) {
    for (let k = 0; k < 5; k++) {
      let a = sa + random(-3.5, 3.5);
      let r = R_COFFEE - random(2.0, 7.5);
      let bx = cx + r * cos(a);
      let by = cy + r * sin(a);
      brush.set("marker", "#d98a3c", 0.35);
      brush.line(bx, by, bx + 1.5, by + 1.5);
      brush.set("rotring", "#4a270d", 0.24);
      brush.circle(bx, by, random(1.4, 2.6), 0.1);
    }
  }

  // 2. Exact Meniscus Reflections at the Outer Perimeter (r = R_COFFEE - 5 to R_COFFEE)
  // The steep concave meniscus acts like an anamorphic mirror reflecting the room's ceiling lights
  // Draw razor-sharp white specular arcs beaded by the 36-fold capillary wave nodes
  const meniscusRadii = [R_COFFEE - 1.2, R_COFFEE - 3.6, R_COFFEE - 6.2];
  for (let mr of meniscusRadii) {
    for (let deg = 0; deg < 360; deg += 2.5) {
      let rad = (deg * Math.PI) / 180;
      let capBead = Math.cos(36 * rad);

      // Primary window reflection sector (196..264 deg) and secondary bounce sector (28..72 deg)
      let inSpecSector =
        (deg > 196 && deg < 264 && Math.abs(deg - 230) > 2.2) ||
        (deg > 28 && deg < 72 && Math.abs(deg - 50) > 2.0);

      if (inSpecSector && capBead > -0.25) {
        // Crisp white highlight arc on the meniscus
        brush.set("rotring", "#f5f9ff", 0.52);
        brush.arc(cx, cy, mr, deg, deg + 1.9);

        // Dark engraving hairline framing the meniscus reflection for hyperreal contrast
        brush.set("rotring", "#0b121c", 0.28);
        brush.arc(cx, cy, mr - 0.9, deg, deg + 1.9);
      } else if (capBead > 0.55) {
        // Pinpoint specular beads on the capillary wave crests all around the meniscus
        brush.set("rotring", "#eef4fa", 0.38);
        brush.arc(cx, cy, mr, deg, deg + 1.2);
      }
    }
  }

  // Final razor-sharp dark contact line where the liquid meniscus meets the vertical mug wall
  brush.set("rotring", "#090f17", 0.45);
  for (let s = 0; s < 36; s++) {
    let a1 = s * 10;
    let a2 = a1 + 8.5;
    // Leave tiny white gaps at the brightest window reflection angles
    if (Math.abs(a1 - 230) > 12 && Math.abs(a1 - 50) > 8) {
      brush.arc(cx, cy, R_COFFEE + 0.4, a1, a2);
    }
  }
}

// Monumental Hyperrealism in p5.brush
// Elderly woman in a faded cerise floral housecoat leaning against a board-marked concrete wall

const PLANK_H = 134;
const NUM_PLANKS = 9;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(831);

  // Custom fine incised charcoal/graphite brush for poured-seam wrinkles & concrete fissures
  brush.add("seam_etch", {
    type: "default",
    weight: 0.9,
    scatter: 0.08,
    sharpness: 0.78,
    grain: 14,
    opacity: 195,
    spacing: 0.14,
    pressure: [0.35, 1.15, 0.3],
    rotate: "natural",
    noise: 0.75
  });

  // Custom dry chalk/lime brush for concrete efflorescence & skin highlights
  brush.add("lime_chalk", {
    type: "default",
    weight: 2.2,
    scatter: 0.45,
    sharpness: 0.32,
    grain: 22,
    opacity: 110,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.15],
    rotate: "random",
    noise: 0.9
  });

  // Custom aggregate stipple brush for concrete sand pores & lentigines (age spots)
  brush.add("aggregate", {
    type: "spray",
    weight: 5.5,
    scatter: 1.6,
    opacity: 95,
    spacing: 0.45,
    pressure: [0.6, 1.1, 0.5],
    rotate: "random",
    noise: 1.0
  });

  // Vector field emulating horizontal timber shuttering grain with knot deflections
  brush.addField("plank_grain", (t, field) => {
    let cols = field.length;
    let rows = field[0].length;
    for (let c = 0; c < cols; c++) {
      for (let r = 0; r < rows; r++) {
        let x = (c / cols) * 1200;
        let y = (r / rows) * 1200;
        let pIdx = Math.floor(y / PLANK_H);
        let localY = (y % PLANK_H) - PLANK_H * 0.5;
        let kx = ((pIdx * 397 + 210) % 760) + 140;
        let ky = ((pIdx * 173) % 56) - 28;
        let dx = x - kx;
        let dy = localY - ky;
        let dSq = dx * dx + dy * dy * 5.5;
        let knotDeflect = ((dy * dx) / (dSq + 1100)) * 68;
        let wave = Math.sin(x * 0.007 + pIdx * 2.1) * 3.2 + (noise(c * 0.14, r * 0.18 + pIdx * 7) - 0.5) * 7.5;
        field[c][r] = wave + knotDeflect;
      }
    }
    return field;
  });

  // Subtle contour field for weathered skin weave and fabric texture
  brush.addField("skin_weave", (t, field) => {
    let cols = field.length;
    let rows = field[0].length;
    for (let c = 0; c < cols; c++) {
      for (let r = 0; r < rows; r++) {
        let n = noise(c * 0.12, r * 0.12);
        field[c][r] = -18 + (n - 0.5) * 42;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. DUSKY TWILIGHT ASH GROUND
  background("#7f8489");

  // 2. MONUMENTAL BOARD-MARKED CONCRETE WALL
  drawConcreteWallBase();
  drawTimberPlankImpressions();
  drawPlankSeamsAndJoints();
  drawTieHolesAndLimeBleeds();

  // 3. OVERCAST AMBIENT OCCLUSION AGAINST THE WALL
  drawWallOcclusionShadow();

  // 4. ELDERLY WOMAN — HOUSECOAT & FADED CERISE ROSES
  drawHousecoatBase();
  drawFadedCeriseRoses();
  drawHousecoatDraperyAndWeave();

  // 5. NECK, COLLAR & WISPY SILVER HAIR
  drawNeckAndCollar();
  drawHairUnderlayer();

  // 6. FACE — WRINKLES LIKE POURED SEAMS, AGE SPOTS LIKE AGGREGATE
  drawFaceSculpture();
  drawEyesAndBrows();
  drawNoseAndMouth();
  drawFacialPouredSeamWrinkles();
  drawFacialAggregateAndPores();
  drawSilverHairStrands();

  // 7. HANDS — MONUMENTAL GRANULAR REALISM
  drawFoldedHands();

  // 8. FINAL OVERCAST ATMOSPHERIC UNIFICATION
  drawAtmosphericGrain();

  noLoop();
}

// =============================================================================
// GEOMETRY & TEXTURE HELPERS
// =============================================================================

function drawShapePoly(pts, curvature = 0.15, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    if (pts[i].length > 2) {
      brush.vertex(pts[i][0], pts[i][1], pts[i][2]);
    } else {
      brush.vertex(pts[i][0], pts[i][1]);
    }
  }
  brush.endShape(closed);
}

// Draws a "poured-seam" wrinkle or concrete fissure: shadow trough, incised core, and raised light-catching rim
function drawPouredSeam(pts, weight = 1.0, lightDx = 0.0, lightDy = 1.6, darkCol = "#221e1d", midCol = "#524a46", lightCol = "#c2bcb7") {
  if (pts.length < 2) return;

  // Soft bevel shadow along the upper/inner margin
  let shadowPts = pts.map(p => [p[0] - lightDx * 0.7, p[1] - lightDy * 0.7, (p[2] || 0.7) * 0.85]);
  brush.set("cpencil", midCol, weight * 1.15);
  brush.spline(shadowPts, 0.35);

  // Raised skin/mortar lip catching overcast top-light
  let ridgePts = pts.map(p => [p[0] + lightDx, p[1] + lightDy, (p[2] || 0.7) * 0.9]);
  brush.set("lime_chalk", lightCol, weight * 0.75);
  brush.spline(ridgePts, 0.35);

  // Deep incised poured-seam core
  brush.set("seam_etch", darkCol, weight * 0.85);
  brush.spline(pts, 0.35);
}

// Draws aggregate-like lentigines (age spots) or mineral concrete flecks
function drawAggregateSpot(x, y, rad, colDark, colMid, colLight) {
  let pts = [];
  let steps = 7;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let r = rad * random(0.65, 1.28);
    pts.push([x + cos(a) * r, y + sin(a) * r * random(0.75, 1.15)]);
  }
  brush.noStroke();
  brush.wash(colMid, random(55, 105));
  drawShapePoly(pts, 0.25, true);
  brush.noWash();

  // Granular rim & adjacent pale mineral fleck
  brush.set("cpencil", colDark, 0.55);
  brush.point ? brush.line(x - rad * 0.3, y, x + rad * 0.3, y + 0.4) : null;
  brush.line(x - rad * 0.4, y - rad * 0.2, x + rad * 0.35, y + rad * 0.25);

  brush.set("2H", colLight, 0.5);
  brush.line(x + rad * 0.5, y + rad * 0.6, x + rad * 1.1, y + rad * 0.7);
}

// =============================================================================
// 1. CONCRETE WALL RENDERING
// =============================================================================

function drawConcreteWallBase() {
  brush.noStroke();

  // Batch 1: Deep damp slate concrete washes
  brush.fill("#585d63", 85);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.65, 0.35);
  for (let p of [0, 2, 5, 7]) {
    brush.rect(-20, p * PLANK_H - 4, 1240, PLANK_H + 8, "corner");
  }

  // Batch 2: Cooler mid-ash boards
  brush.fill("#6d737a", 75);
  brush.fillBleed(0.3, "out");
  for (let p of [1, 4, 8]) {
    brush.rect(-20, p * PLANK_H - 4, 1240, PLANK_H + 8, "corner");
  }

  // Batch 3: Weathered pale mineral boards
  brush.fill("#93999f", 65);
  brush.fillBleed(0.28, "out");
  for (let p of [3, 6]) {
    brush.rect(-20, p * PLANK_H - 4, 1240, PLANK_H + 8, "corner");
  }

  // Batch 4: Broad damp twilight mineral clouds across the wall
  brush.fill("#454a50", 52);
  brush.fillBleed(0.45, "out");
  brush.circle(260, 310, 290, 0.35);
  brush.circle(180, 920, 340, 0.4);
  brush.circle(640, 160, 260, 0.35);

  brush.fill("#a8aeb4", 48);
  brush.fillBleed(0.4, "out");
  brush.circle(470, 580, 280, 0.35);
  brush.circle(820, 190, 220, 0.3);
  brush.noFill();

  // Dry-media charcoal massing per plank for tactile concrete density
  let plankMassCols = ["#4f545a", "#6e747a", "#484d53", "#888e94", "#5d6369", "#4a4f55", "#838990", "#555a60", "#656b72"];
  for (let p = 0; p < NUM_PLANKS; p++) {
    let y0 = p * PLANK_H;
    brush.noStroke();
    brush.mass("charcoal", plankMassCols[p], {
      precision: 0.35,
      strength: 0.32,
      gradient: 0.45,
      outline: false
    });
    // Restrict mass to left/visible wall on lower planks to save render budget behind the figure
    let maxW = p >= 4 ? 760 : 1200;
    brush.rect(0, y0 + 4, maxW, PLANK_H - 8, "corner");
    brush.noMass();
  }
}

function drawTimberPlankImpressions() {
  // Fine vertical shuttering vibration & saw-cut marks using hatch
  for (let p = 0; p < NUM_PLANKS; p++) {
    let y0 = p * PLANK_H;
    let maxW = p >= 5 ? 690 : 1200;
    brush.noStroke();
    brush.hatchStyle("2H", p % 2 === 0 ? "#474c52" : "#969ca2", 0.65);
    brush.hatch(14, 88 + (p % 3 - 1) * 3, { rand: 0.12, gradient: 0.35 });
    brush.rect(0, y0 + 2, maxW, PLANK_H - 4, "corner");
    brush.noHatch();
  }

  // Activate custom plank_grain vector field for raised timber grain ridges
  brush.field("plank_grain");

  for (let p = 0; p < NUM_PLANKS; p++) {
    let y0 = p * PLANK_H;
    let maxW = p >= 5 ? 720 : 1190;

    // Dark timber grain grooves pressed into concrete
    for (let i = 0; i < 68; i++) {
      let sx = random(0, maxW - 90);
      let sy = y0 + random(6, PLANK_H - 6);
      let len = random(70, 240);
      let col = random(["#2f3439", "#3d4248", "#4e545a", "#60666c"]);
      let bName = random(["charcoal", "2B", "HB"]);
      brush.set(bName, col, random(0.45, 1.05));
      brush.flowLine(sx, sy, len, 0);
    }

    // Pale calcified/ash grain ridges catching top overcast light
    for (let i = 0; i < 42; i++) {
      let sx = random(0, maxW - 80);
      let sy = y0 + random(8, PLANK_H - 8);
      let len = random(55, 190);
      let col = random(["#9ea4aa", "#b2b8be", "#c6ccd1"]);
      brush.set(random(["2H", "cpencil", "lime_chalk"]), col, random(0.4, 0.85));
      brush.flowLine(sx, sy, len, 0);
    }

    // Timber knots & cathedral grain rings per plank
    let kx = ((p * 397 + 210) % 760) + 140;
    let ky = y0 + PLANK_H * 0.5 + ((p * 173) % 56) - 28;
    if (kx < maxW - 40) {
      drawTimberKnot(kx, ky, p);
    }
  }

  brush.noField();

  // Concrete sand aggregate & air-void pinholes across the wall
  for (let i = 0; i < 240; i++) {
    let x = random(15, 1180);
    let y = random(15, 1180);
    if (x > 640 && y > 480) continue; // skip behind figure torso
    brush.set("aggregate", random(["#34393e", "#52575d", "#a6acb2", "#696662"]), random(0.5, 1.2));
    brush.line(x, y, x + random(4, 16), y + random(-3, 3));
  }
}

function drawTimberKnot(kx, ky, pIdx) {
  // Nested elliptical cathedral rings around the knot core
  for (let ring = 1; ring <= 6; ring++) {
    let rx = ring * 18 + ring * ring * 2.4;
    let ry = ring * 4.2 + 2;
    let topPts = [];
    let botPts = [];
    for (let s = -5; s <= 5; s++) {
      let t = s / 5;
      let px = kx + t * rx;
      let pyOff = sqrt(max(0, 1 - t * t)) * ry;
      topPts.push([px, ky - pyOff + sin(t * 90) * 1.5, 0.8 - abs(t) * 0.4]);
      botPts.push([px, ky + pyOff + cos(t * 90) * 1.5, 0.8 - abs(t) * 0.4]);
    }
    brush.set("2B", ring % 2 === 0 ? "#32373c" : "#4b5056", 0.65);
    brush.spline(topPts, 0.4);
    brush.spline(botPts, 0.4);

    brush.set("2H", "#adb3b9", 0.5);
    let hiPts = botPts.map(pt => [pt[0], pt[1] + 1.5, pt[2]]);
    brush.spline(hiPts, 0.4);
  }
  // Dark knot center
  brush.noStroke();
  brush.wash("#2a2e33", 140);
  brush.circle(kx, ky, 7, 0.3);
  brush.noWash();
  brush.set("charcoal", "#1f2327", 0.9);
  brush.circle(kx, ky, 8, 0.35);
}

function drawPlankSeamsAndJoints() {
  let buttJoints = [790, 330, 960, 440, 230, 610, 380, 510, 290];

  for (let p = 1; p < NUM_PLANKS; p++) {
    let sy = p * PLANK_H;
    let maxW = p >= 5 ? 730 : 1200;

    // 1. Cast-concrete slurry fin (extruded mortar ridge along horizontal board seam)
    let segs = 28;
    let stepX = maxW / segs;
    let seamPts = [];
    for (let i = 0; i <= segs; i++) {
      let x = i * stepX;
      let y = sy + (noise(i * 0.4, p * 3.7) - 0.5) * 4.5;
      seamPts.push([x, y, random(0.6, 1.1)]);
    }

    // Shadow directly under the proud board lip
    let underPts = seamPts.map(pt => [pt[0], pt[1] + 2.4, pt[2]]);
    brush.set("charcoal", "#2c3035", 1.15);
    brush.spline(underPts, 0.25);

    // Pale extruded mortar fin catching top overcast light
    let finPts = seamPts.map(pt => [pt[0], pt[1] - 1.6, pt[2]]);
    brush.set("lime_chalk", "#c4c9ce", 1.05);
    brush.spline(finPts, 0.25);

    // Razor-sharp formwork seam line
    brush.set("seam_etch", "#1a1d21", 0.95);
    brush.spline(seamPts, 0.25);

    // Chipped concrete edges & trapped air pockets (bug holes) along seam
    for (let b = 0; b < 36; b++) {
      let bx = random(10, maxW - 15);
      let by = sy + random(-9, 9);
      let br = random(1.2, 4.2);
      brush.set("rotring", "#1d2024", 0.7);
      brush.arc(bx, by, br, 190, 355);
      brush.set("2H", "#bfc5ca", 0.55);
      brush.arc(bx, by, br, 15, 165);
    }

    // Vertical board butt-joint on this plank
    let jx = buttJoints[p - 1];
    if (jx < maxW - 30) {
      let yTop = (p - 1) * PLANK_H;
      let jPts = [
        [jx, yTop + 2, 0.8],
        [jx + random(-2, 2), yTop + PLANK_H * 0.5, 1.0],
        [jx + random(-1.5, 1.5), sy - 2, 0.8]
      ];
      drawPouredSeam(jPts, 0.95, 1.8, 0.0, "#1c2024", "#474c52", "#b8bec4");

      // Splintered vertical end-grain near butt-joint
      for (let k = 0; k < 12; k++) {
        let gy = yTop + random(8, PLANK_H - 8);
        brush.set("HB", "#373c42", 0.55);
        brush.line(jx - random(4, 28), gy, jx + random(4, 28), gy + random(-1.5, 1.5));
      }
    }
  }
}

function drawTieHolesAndLimeBleeds() {
  // Disciplined architectural grid of shuttering tie-holes
  let tieCols = [188, 548, 918];
  let tieRows = [
    PLANK_H * 1.5, // y = 201
    PLANK_H * 3.5, // y = 469
    PLANK_H * 5.5, // y = 737
    PLANK_H * 7.5  // y = 1005
  ];

  // Also add minor seam lime-bleeds at intervals along horizontal seams
  let seamBleeds = [
    [112, PLANK_H * 2, 170],
    [378, PLANK_H * 3, 220],
    [684, PLANK_H * 2, 160],
    [435, PLANK_H * 6, 240],
    [82,  PLANK_H * 5, 190],
    [295, PLANK_H * 8, 175]
  ];

  for (let sb of seamBleeds) {
    drawLimeBleedStreak(sb[0], sb[1], sb[2], 0.65);
  }

  for (let r = 0; r < tieRows.length; r++) {
    for (let c = 0; c < tieCols.length; c++) {
      let tx = tieCols[c];
      let ty = tieRows[r];
      // Skip tie-holes covered by the woman's head/torso on the right column
      if (c === 2 && r >= 1) continue;

      // 1. Grey lime bleed weeping down from the tie-hole
      let bleedLen = random(185, 310);
      drawLimeBleedStreak(tx, ty + 14, bleedLen, 1.0);

      // 2. Recessed conical form tie-hole
      drawSingleTieHole(tx, ty);
    }
  }
}

function drawLimeBleedStreak(x, y, len, intensity) {
  // Soft pale calcium hydroxide efflorescence wash
  brush.noStroke();
  brush.fill("#c5cbd0", 52 * intensity);
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.55, 0.45);
  let w = 12 * intensity;
  let pts = [
    [x - w * 0.7, y],
    [x + w * 0.7, y],
    [x + w * 0.45 + random(-3, 3), y + len * 0.45],
    [x + w * 0.18 + random(-2, 2), y + len],
    [x - w * 0.18 + random(-2, 2), y + len],
    [x - w * 0.45 + random(-3, 3), y + len * 0.45]
  ];
  drawShapePoly(pts, 0.2, true);
  brush.noFill();

  // Crusted vertical chalky mineral trails
  let numTracks = floor(8 * intensity) + 4;
  for (let i = 0; i < numTracks; i++) {
    let ox = x + random(-w * 0.65, w * 0.65);
    let trackLen = len * random(0.35, 1.05);
    let segPts = [];
    let steps = 6;
    for (let s = 0; s <= steps; s++) {
      let sy = y + (s / steps) * trackLen;
      let sx = ox + (noise(ox * 0.1, sy * 0.03) - 0.5) * 6;
      // Slight horizontal jog when crossing a plank seam
      if ( sy % PLANK_H < 6 ) sx += random(-2.5, 2.5);
      segPts.push([sx, sy, (1 - s / steps) * 0.9 + 0.15]);
    }
    let col = i % 3 === 0 ? "#dce1e5" : (i % 2 === 0 ? "#b8bfc5" : "#9aa1a8");
    brush.set(i % 2 === 0 ? "lime_chalk" : "cpencil", col, random(0.45, 0.9) * intensity);
    brush.spline(segPts, 0.25);
  }

  // Dark damp border edge beside the calcified crust
  brush.set("2H", "#50565c", 0.5 * intensity);
  brush.line(x - w * 0.68, y + 6, x - w * 0.25, y + len * 0.75);
  brush.line(x + w * 0.68, y + 6, x + w * 0.25, y + len * 0.75);
}

function drawSingleTieHole(tx, ty) {
  let outerR = 23;
  let innerR = 9;

  // Chipped concrete spall ring around the cone
  brush.noStroke();
  brush.wash("#50555b", 120);
  brush.circle(tx, ty, outerR + 3, 0.28);
  brush.noWash();

  // Upper interior cone in deep overcast shadow
  let topCrescent = [];
  for (let a = 165; a <= 375; a += 25) {
    topCrescent.push([tx + cos(a) * outerR, ty + sin(a) * outerR]);
  }
  for (let a = 375; a >= 165; a -= 35) {
    topCrescent.push([tx + cos(a) * innerR, ty + sin(a) * innerR + 2]);
  }
  brush.noStroke();
  brush.wash("#24282d", 195);
  drawShapePoly(topCrescent, 0.2, true);
  brush.noWash();

  // Lower interior cone catching diffused skylight
  let botCrescent = [];
  for (let a = -15; a <= 195; a += 25) {
    botCrescent.push([tx + cos(a) * outerR, ty + sin(a) * outerR]);
  }
  for (let a = 195; a >= -15; a -= 35) {
    botCrescent.push([tx + cos(a) * innerR, ty + sin(a) * innerR + 2]);
  }
  brush.noStroke();
  brush.wash("#9ca2a8", 150);
  drawShapePoly(botCrescent, 0.2, true);
  brush.noWash();

  // Directional radial hatching inside the cone
  for (let a = 0; a < 360; a += 12) {
    let isShadow = a > 175 && a < 355;
    brush.set("HB", isShadow ? "#181b1f" : "#6c7278", 0.55);
    brush.line(
      tx + cos(a) * (innerR + 1),
      ty + sin(a) * (innerR + 1) + 1.5,
      tx + cos(a) * outerR,
      ty + sin(a) * outerR
    );
  }

  // Deep recessed steel tie-rod core
  brush.noStroke();
  brush.wash("#101215", 235);
  brush.circle(tx, ty + 1.5, innerR, 0.15);
  brush.noWash();

  // Rusty-ash oxidized center pin inside the socket
  brush.set("cpencil", "#5c4d46", 0.8);
  brush.circle(tx, ty + 1.5, 3.2, 0.2);

  // Sharp chipped outer rim & bright lower lip
  brush.set("seam_etch", "#1c2024", 0.85);
  brush.arc(tx, ty, outerR, 175, 365);
  brush.set("lime_chalk", "#d0d5da", 0.9);
  brush.arc(tx, ty, outerR + 0.8, 15, 165);
}

