function drawRosePetalCluster(rx, ry, rad, sx, sy, ang) {
  let pts = [];
  let lobes = 9;
  for (let i = 0; i < lobes; i++) {
    let a = ang + (i / lobes) * 360;
    let r = rad * (i % 2 === 0 ? 1.05 : 0.76);
    pts.push([rx + cos(a) * r * sx, ry + sin(a) * r * sy]);
  }
  drawShapePoly(pts, 0.35, true);
}

