function drawSilverHairStrands() {
  // Swept-back silver, ash, and iron-grey hair strands from temple & forehead to the low bun
  let strandOrigins = [];
  for (let i = 0; i < 95; i++) {
    let t = i / 94;
    let sx = lerp(752, 912, t) + random(-6, 6);
    let sy = lerp(284, 386, t) - sin(t * 180) * 24 + random(-5, 5);
    strandOrigins.push([sx, sy, t]);
  }

  for (let so of strandOrigins) {
    let [sx, sy, t] = so;
    let midX = sx + random(45, 85);
    let midY = sy - random(8, 28) + t * 35;
    let endX = random(955, 998);
    let endY = random(375, 455);

    let pts = [
      [sx, sy, 0.5],
      [lerp(sx, midX, 0.5), lerp(sy, midY, 0.5) - 6, 0.9],
      [midX, midY, 1.0],
      [endX, endY, 0.6]
    ];

    let isLight = random() < 0.62;
    let col = isLight ? random(["#d2d6da", "#bcc1c6", "#e2e6ea"]) : random(["#383c40", "#52565b", "#6e7378"]);
    let bName = isLight ? (random() < 0.5 ? "cpencil" : "2H") : "HB";
    brush.set(bName, col, random(0.45, 0.9));
    brush.spline(pts, 0.42);
  }

  // Coiled silver strands in the low bun at the nape
  for (let i = 0; i < 45; i++) {
    let a1 = random(0, 360);
    let a2 = a1 + random(80, 170);
    let r = random(10, 36);
    let cx = 978 + random(-8, 8);
    let cy = 432 + random(-8, 8);
    let pts = [];
    for (let s = 0; s <= 4; s++) {
      let a = lerp(a1, a2, s / 4);
      pts.push([cx + cos(a) * r, cy + sin(a) * r * 1.15, 0.85]);
    }
    brush.set(i % 2 === 0 ? "cpencil" : "2H", i % 3 === 0 ? "#34383c" : "#cbd0d4", random(0.5, 0.85));
    brush.spline(pts, 0.45);
  }

  // Delicate loose flyaway silver filaments catching overcast light against the dark concrete
  for (let i = 0; i < 28; i++) {
    let fx = random(780, 995);
    let fy = random(248, 485);
    if (fx < 915 && fy > 305) continue;
    let pts = [
      [fx, fy, 0.6],
      [fx + random(12, 34), fy + random(-18, 14), 0.7],
      [fx + random(24, 58), fy + random(-22, 24), 0.3]
    ];
    brush.set("2H", "#dfe3e7", 0.45);
    brush.spline(pts, 0.45);
  }
}

