// ============================================================================
// GEOMETRY & SAFE DRAWING HELPERS
// ============================================================================

function safePoly(pts, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  let clean = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (
      clean.length === 0 ||
      Math.hypot(p[0] - clean[clean.length - 1][0], p[1] - clean[clean.length - 1][1]) > 1.5
    ) {
      clean.push(p);
    }
  }
  if (clean.length >= 3) {
    let f = clean[0];
    let l = clean[clean.length - 1];
    if (Math.hypot(f[0] - l[0], f[1] - l[1]) <= 1.5) clean.pop();
  }
  if (clean.length < 3) return;

  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(true);
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (
      clean.length === 0 ||
      Math.hypot(p[0] - clean[clean.length - 1][0], p[1] - clean[clean.length - 1][1]) > 1.5
    ) {
      clean.push(p);
    }
  }
  if (clean.length < 2) return;
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else {
    brush.spline(clean, curvature);
  }
}

function makeEllipsePts(cx, cy, rx, ry, n = 36, rotDeg = 0, wobble = 0) {
  let pts = [];
  let ca = cos(rotDeg);
  let sa = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let rMod = wobble > 0 ? 1 + wobble * (noise(cx * 0.01 + cos(a) * 1.5, cy * 0.01 + sin(a) * 1.5) - 0.5) : 1;
    let lx = cos(a) * rx * rMod;
    let ly = sin(a) * ry * rMod;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

function makePancakeBandPts(cx, cy, rx, ry, thickness, n = 32) {
  let pts = [];
  // Upper rim from left (180) to right (0) via front (90)
  for (let i = 0; i <= n; i++) {
    let a = 180 - (i / n) * 180;
    let nVal = noise(cx * 0.02 + cos(a) * 2, cy * 0.02 + sin(a) * 2);
    let dy = (nVal - 0.5) * 4;
    pts.push([cx + cos(a) * rx, cy + sin(a) * ry + dy]);
  }
  // Lower rim from right (0) to left (180) via front (90)
  for (let i = 0; i <= n; i++) {
    let a = (i / n) * 180;
    let nVal = noise(cx * 0.02 + cos(a) * 2 + 10, cy * 0.02 + sin(a) * 2 + 10);
    let bulge = sin(a) * 7;
    let localThick = thickness * (0.82 + 0.22 * sin(a)) + (nVal - 0.5) * 4;
    pts.push([cx + cos(a) * (rx + bulge * 0.4), cy + sin(a) * ry + localThick]);
  }
  return pts;
}

