function drawSinglePancake(p) {
  let { cx, cy, rx, ry, thick, seed, isTop } = p;

  // 1. Deep warm sepia cast shadow onto the surface below
  brush.noStroke();
  brush.fill("#4d311b", 105);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.35, 0.15);
  safePoly(makeEllipsePts(cx + 4, cy + thick + 9, rx * 0.99, ry * 0.96, 36, 0, 0.02), 0.25);

  brush.fill("#2e1a0c", 95);
  brush.fillBleed(0.1, "in");
  safePoly(makeEllipsePts(cx + 2, cy + thick + 3, rx * 0.95, ry * 0.9, 36, 0, 0.02), 0.25);
  brush.noFill();

  // 2. Fluffy pale crumb side-band (the characteristic aerated vertical rim of a pancake)
  let sideBandPts = makePancakeBandPts(cx, cy, rx, ry, thick, 34);
  brush.wash("#f3e3c6", 230);
  safePoly(sideBandPts, 0.2);
  brush.noWash();

  // Shaded lower & right side of the crumb band
  brush.fill("#cfa97e", 90);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.35, 0.12);
  safePoly(makePancakeBandPts(cx + 6, cy + thick * 0.28, rx * 0.98, ry * 0.96, thick * 0.72, 28), 0.2);

  // Toasted golden-brown bottom crust lip
  brush.fill("#8c5830", 85);
  brush.fillBleed(0.12, "in");
  safePoly(makePancakeBandPts(cx, cy + thick * 0.62, rx * 0.99, ry * 0.98, thick * 0.38, 28), 0.2);
  brush.noFill();

  // 3. Top browned griddle surface of the pancake
  // Pale cooked outer ring
  brush.wash("#f0dec0", 235);
  safePoly(makeEllipsePts(cx, cy, rx, ry, 40, 0, 0.025), 0.25);
  brush.noWash();

  // Rich golden-sepia Maillard browned top crust
  brush.fill("#b07c49", 105);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.42, 0.18);
  safePoly(makeEllipsePts(cx, cy, rx * 0.95, ry * 0.92, 38, 0, 0.03), 0.25);

  brush.fill("#875329", 110);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.45, 0.2);
  safePoly(makeEllipsePts(cx - 4, cy + 1, rx * 0.89, ry * 0.85, 36, 0, 0.035), 0.25);

  if (isTop) {
    // Extra mottled toasted depth on the top pancake surface
    brush.fill("#6b3c18", 85);
    brush.fillBleed(0.25, "in");
    brush.fillTexture(0.5, 0.22);
    safePoly(makeEllipsePts(cx - 8, cy + 2, rx * 0.78, ry * 0.74, 34, 0, 0.04), 0.25);
  }
  brush.noFill();

  // 4. FINE COLOURED PENCIL RENDERING OF THE PANCAKE CRUMB & CRUST
  // a) Vertical & cross-contour coloured pencil strokes along the spongy side band
  let numCrumbCols = 140;
  for (let i = 0; i <= numCrumbCols; i++) {
    let t = i / numCrumbCols;
    let a = 176 - t * 172; // Front visible arc from left (176°) to right (4°)
    let radX = cos(a) * rx;
    let radY = sin(a) * ry;
    let xBase = cx + radX;
    let yTop = cy + radY;
    let localThick = thick * (0.82 + 0.22 * sin(a));
    let yBot = yTop + localThick;

    // Illumination factor: brighter on upper-left & backlit outer edges, deeper in front-right core
    let shade = sin(a) * 0.65 + (cos(a) > 0 ? 0.35 : -0.1);

    // Upper browned lip overhang where top crust meets fluffy crumb
    brush.set("cpencil", shade > 0.5 ? "#5e3617" : "#784925", 0.55);
    let lipLen = localThick * random(0.14, 0.28);
    brush.line(xBase, yTop - 1, xBase + random(-1.5, 1.5), yTop + lipLen);

    // Spongy vertical crumb fibers in warm biscuit, ochre, and sepia coloured pencil
    let midCol = shade > 0.55 ? "#b88e5e" : shade > 0.25 ? "#cfa779" : "#dec09a";
    brush.set("cpencil", midCol, 0.42);
    let y1 = yTop + localThick * random(0.15, 0.45);
    let y2 = yTop + localThick * random(0.55, 0.88);
    brush.line(xBase + random(-1, 1), y1, xBase + random(-1.5, 1.5), y2);

    // Lower toasted edge hatching
    brush.set("cpencil", "#693e1d", 0.48);
    brush.line(xBase, yBot - localThick * random(0.15, 0.32), xBase + random(-1.5, 1.5), yBot);
  }

  // b) Longitudinal contour-hugging pencil strokes across the fluffy crumb band
  for (let row = 0; row < 7; row++) {
    let frac = 0.18 + (row / 6) * 0.68;
    let col = row === 0 || row === 6 ? "#704320" : row === 3 ? "#e8d2b0" : "#b58b5e";
    brush.set("2H", col, 0.42);
    let arcPts = [];
    for (let s = 0; s <= 24; s++) {
      let a = 172 - (s / 24) * 164;
      let localThick = thick * (0.82 + 0.22 * sin(a));
      let jitter = (noise(seed + s * 0.4, row) - 0.5) * 3.5;
      arcPts.push([cx + cos(a) * (rx + sin(a) * 2.5), cy + sin(a) * ry + localThick * frac + jitter]);
    }
    safeSpline(arcPts, 0.35);
  }

  // c) Tiny aerated steam-bubbles / pores & crumbly granules along the side rim
  let numPores = 95;
  for (let i = 0; i < numPores; i++) {
    let a = random(10, 170);
    let localThick = thick * (0.82 + 0.22 * sin(a));
    let py = cy + sin(a) * ry + localThick * random(0.22, 0.78);
    let px = cx + cos(a) * rx + random(-3, 3);
    let pr = random(1.4, 3.8);

    // Dark sepia upper interior of pore
    brush.set("cpencil", "#4f2d14", 0.5);
    brush.arc(px, py, pr, 190, 350);

    // Pale biscuit lower rim highlight of pore
    brush.set("2H", "#fff6e3", 0.45);
    brush.arc(px, py + 0.6, pr, 15, 165);
  }

  // d) Fine coloured pencil texture across the visible browned top surface
  let topStrokes = isTop ? 260 : 85;
  for (let i = 0; i < topStrokes; i++) {
    let ang = isTop ? random(0, 360) : random(5, 175);
    let rFrac = isTop ? sqrt(random(0.02, 0.94)) : random(0.76, 0.95);
    let sx = cx + cos(ang) * rx * rFrac;
    let sy = cy + sin(ang) * ry * rFrac;
    let segLen = random(10, 26);

    let cPick = random();
    let col = cPick < 0.35 ? "#6e3f1c" : cPick < 0.7 ? "#966136" : cPick < 0.9 ? "#c49464" : "#f2dfc1";
    brush.set("cpencil", col, random(0.32, 0.55));
    brush.line(sx - segLen * 0.5, sy + random(-1.5, 1.5), sx + segLen * 0.5, sy + random(-1.5, 1.5));
  }

  // Backlit cream highlight along the far left & right rims of each pancake
  brush.set("cpencil", "#fffaf0", 0.65);
  for (let side of [-1, 1]) {
    let rimPts = [];
    for (let s = 0; s <= 10; s++) {
      let a = side < 0 ? 140 + s * 4.5 : -25 + s * 4.5;
      rimPts.push([cx + cos(a) * (rx - 1), cy + sin(a) * (ry - 1)]);
    }
    safeSpline(rimPts, 0.4);
  }
}

// ============================================================================
// 3. WOODEN HONEY DIPPER HELD ALOFT (Turned Ridges in Coloured Pencil)
// ============================================================================

function drawWoodenHoneyDipper() {
  // Dipper center at (612, 192), axis tilted at -24 degrees (handle extends up-right)
  let dCx = 612;
  let dCy = 192;
  let tilt = -24;
  let ux = cos(tilt); // +0.9135 (along handle toward top-right)
  let uy = sin(tilt); // -0.4067
  let nx = -uy;       // +0.4067 (down-right perpendicular to axis)
  let ny = ux;        // +0.9135

  function dipperPt(s, r, thetaDeg) {
    // 3D point on a circular disk at axial station s, radius r, angle thetaDeg around axis
    // Camera views slightly from side/front so disk ellipses have aspect ratio 0.36
    let aspect = 0.36;
    let axialShift = r * cos(thetaDeg) * aspect;
    let perpShift = r * sin(thetaDeg);
    return [
      dCx + (s + axialShift) * ux + perpShift * nx,
      dCy + (s + axialShift) * uy + perpShift * ny
    ];
  }

  function makeDiskEllipse(s, r, n = 32) {
    let pts = [];
    for (let i = 0; i < n; i++) {
      let th = (i / n) * 360;
      pts.push(dipperPt(s, r, th));
    }
    return pts;
  }

  function makeCylinderSegment(s1, r1, s2, r2) {
    let pts = [];
    // Top edge from s1 to s2 (theta = -90)
    pts.push(dipperPt(s1, r1, -90));
    pts.push(dipperPt((s1 + s2) * 0.5, (r1 + r2) * 0.5, -90));
    pts.push(dipperPt(s2, r2, -90));
    // Front/right cap at s2
    for (let th = -60; th <= 60; th += 30) pts.push(dipperPt(s2, r2, th));
    // Bottom edge from s2 to s1 (theta = +90)
    pts.push(dipperPt(s2, r2, 90));
    pts.push(dipperPt((s1 + s2) * 0.5, (r1 + r2) * 0.5, 90));
    pts.push(dipperPt(s1, r1, 90));
    // Back/left cap at s1
    for (let th = 120; th <= 240; th += 30) pts.push(dipperPt(s1, r1, th));
    return pts;
  }

  // --- A. WOODEN HANDLE SHAFT & TURNED BALUSTER NECK (s = 95 to 660) ---
  let handleSegs = [
    { s1: 92, r1: 18, s2: 118, r2: 13 },
    { s1: 115, r1: 13, s2: 136, r2: 20 }, // Turned decorative collar ring
    { s1: 134, r1: 20, s2: 158, r2: 12 },
    { s1: 155, r1: 12, s2: 320, r2: 16 },
    { s1: 315, r1: 16, s2: 660, r2: 22 }
  ];

  // Handle watercolor base washes
  brush.noStroke();
  for (let seg of handleSegs) {
    brush.wash("#e3cca8", 225);
    safePoly(makeCylinderSegment(seg.s1, seg.r1, seg.s2, seg.r2), 0.2);
    brush.wash("#9e7348", 130);
    safePoly(makeCylinderSegment(seg.s1, seg.r1 * 0.5, seg.s2, seg.r2 * 0.85), 0.2);
  }
  brush.noWash();

  // Handle fine coloured pencil wood grain & lathe rings
  for (let i = 0; i < 65; i++) {
    let t = (i / 65) * 2 - 1; // -1 (top backlit edge) to +1 (bottom shaded edge)
    let th = t * 90;
    let col =
      t < -0.65
        ? "#fffdf7"
        : t < -0.25
        ? "#e6cfb0"
        : t < 0.25
        ? "#a87c51"
        : t < 0.7
        ? "#6b4423"
        : "#9c6836";
    brush.set("cpencil", col, t < -0.65 ? 0.65 : 0.45);
    let linePts = [];
    for (let s = 96; s <= 640; s += 28) {
      let r =
        s < 118
          ? map(s, 96, 118, 17, 13)
          : s < 136
          ? map(s, 118, 136, 13, 20)
          : s < 158
          ? map(s, 136, 158, 20, 12)
          : map(s, 158, 640, 12, 22);
      linePts.push(dipperPt(s, r, th));
    }
    safeSpline(linePts, 0.35);
  }

  // --- B. LATHE-TURNED HONEY DIPPER RIDGES (Drawn Back-to-Front: s = +88 down to s = -88) ---
  let ridges = [
    { s: 86, r: 37, thick: 13 },
    { s: 58, r: 55, thick: 14 },
    { s: 29, r: 69, thick: 15 },
    { s: 0, r: 75, thick: 15 },
    { s: -29, r: 69, thick: 15 },
    { s: -58, r: 55, thick: 14 },
    { s: -86, r: 35, thick: 13 }
  ];

  for (let idx = 0; idx < ridges.length; idx++) {
    let rg = ridges[idx];
    let sBack = rg.s + rg.thick * 0.5;
    let sFront = rg.s - rg.thick * 0.5;

    // 1. Deep recessed wooden spindle core behind this ridge (if not first)
    if (idx > 0) {
      let prevFront = ridges[idx - 1].s - ridges[idx - 1].thick * 0.5;
      brush.noStroke();
      brush.wash("#3b210e", 235);
      safePoly(makeCylinderSegment(sBack - 2, 24, prevFront + 2, 24), 0.15);

      // Glowing amber honey trapped inside the deep slot between ridges!
      brush.wash("#f59e0b", 190);
      safePoly(makeCylinderSegment(sBack - 3, ridges[idx].r * 0.86, prevFront + 3, ridges[idx - 1].r * 0.86), 0.25);
      brush.noWash();

      brush.fill("#c94700", 125);
      brush.fillBleed(0.12, "in");
      safePoly(
        [
          dipperPt(sBack, rg.r * 0.78, 15),
          dipperPt(prevFront, ridges[idx - 1].r * 0.78, 15),
          dipperPt(prevFront, ridges[idx - 1].r * 0.95, 88),
          dipperPt(sBack, rg.r * 0.95, 88)
        ],
        0.25
      );
      brush.noFill();

      // Internal golden glow inside the slot meniscus
      brush.set("satin", "#ffe66d", 0.9);
      let slotGlow = [];
      for (let th = 25; th <= 80; th += 15) {
        slotGlow.push(dipperPt((sBack + prevFront) * 0.5, (rg.r + ridges[idx - 1].r) * 0.43, th));
      }
      safeSpline(slotGlow, 0.4);
    }

    // 2. Ridge outer cylindrical rim & front planar face base washes
    brush.noStroke();
    // Outer rim band of the wooden disk
    brush.wash("#e6cfa8", 235);
    safePoly(makeCylinderSegment(sFront, rg.r, sBack, rg.r), 0.2);

    // Shaded lower half of outer rim
    brush.wash("#8c5d34", 165);
    safePoly(
      [
        dipperPt(sFront, rg.r, -10),
        dipperPt(sBack, rg.r, -10),
        dipperPt(sBack, rg.r, 110),
        dipperPt(sFront, rg.r, 110)
      ],
      0.2
    );

    // Front planar face of the wooden disk
    brush.wash("#c9a375", 230);
    safePoly(makeDiskEllipse(sFront, rg.r, 36), 0.25);

    // Recessed darker wood shadow on the lower planar face
    brush.wash("#6e4523", 155);
    let lowerFacePts = [];
    for (let th = -20; th <= 190; th += 15) lowerFacePts.push(dipperPt(sFront, rg.r * 0.94, th));
    safePoly(lowerFacePts, 0.25);
    brush.noWash();

    // 3. FINE COLOURED PENCIL RENDERING OF THE WOODEN RIDGE
    // a) Annular lathe turn-lines on the front face of the disk
    for (let ring = 0.35; ring <= 0.96; ring += 0.12) {
      for (let seg = 0; seg < 18; seg++) {
        let th1 = seg * 20;
        let th2 = th1 + 18;
        let p1 = dipperPt(sFront, rg.r * ring, th1);
        let p2 = dipperPt(sFront, rg.r * ring, th2);
        // Backlit top edge (-130 to -30) is luminous cream; lower part is warm umber/sepia
        let isTopRim = th1 >= 210 && th1 <= 330;
        let isBotRim = th1 >= 20 && th1 <= 150;
        let col = isTopRim ? "#f7ead2" : isBotRim ? "#4f2e15" : "#8a5e36";
        brush.set("cpencil", col, isTopRim ? 0.48 : 0.42);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // b) Cross-axial wood grain & bevel hatching across the thickness of each ridge rim
    for (let th = -110; th <= 110; th += 5) {
      let pFront = dipperPt(sFront, rg.r, th);
      let pBack = dipperPt(sBack, rg.r, th);
      let col;
      let w = 0.44;
      if (th < -55) {
        // Intense backlit window rim on the upper edge of the wooden ridge
        col = th < -75 ? "#fffdf7" : "#f2dfc0";
        w = 0.62;
      } else if (th < 5) {
        col = "#b3885c";
      } else if (th < 55) {
        col = "#694120";
      } else {
        // Underside of ridge coated in glowing amber honey reflection!
        col = th > 75 ? "#e07a00" : "#9c531b";
        w = 0.52;
      }
      brush.set("cpencil", col, w);
      brush.line(pFront[0], pFront[1], pBack[0], pBack[1]);
    }

    // c) Crisp 2H pencil contour definition on the front & back edges of the ridge
    brush.set("2H", "#4a2b13", 0.45);
    let frontRim = [];
    for (let th = -45; th <= 145; th += 12) frontRim.push(dipperPt(sFront, rg.r, th));
    safeSpline(frontRim, 0.4);

    // Bright backlit cream halo line along the upper crest of each wooden ridge
    brush.set("cpencil", "#ffffff", 0.72);
    let topCrest = [];
    for (let th = -125; th <= -45; th += 10) topCrest.push(dipperPt((sFront + sBack) * 0.5, rg.r + 0.6, th));
    safeSpline(topCrest, 0.4);
  }

  // Rounded front nose cap of the dipper at s = -94..-104
  brush.noStroke();
  brush.wash("#cfa87a", 220);
  safePoly(makeDiskEllipse(-95, 22, 24), 0.3);
  brush.noWash();
  brush.set("cpencil", "#593518", 0.48);
  safeSpline(makeDiskEllipse(-95, 22, 20).slice(0, 12), 0.4);
}

// ============================================================================
// 4. GLASSY HONEY RIBBON, FOLDS & POOL
// ============================================================================

// Mathematical profile of the stretching, twisting, nearly-snapping honey ribbon
function getRibbonSlice(y) {
  // Returns { cx, w, twist } for y from 235 (dipper underside) to 675 (top fold)
  let t = constrain((y - 235) / (675 - 235), 0, 1);

  // Centerline x with graceful fluid S-curve
  let cx =
    592 -
    22 * sin(t * 155) +
    8 * sin(t * 340 - 35) +
    (y > 550 ? map(y, 550, 675, 0, 16) : 0);

  let w;
  if (y < 325) {
    // Upper hyperbolic funnel pulling off the dipper ridges
    let u = (y - 235) / 90;
    w = 96 * pow(1 - u, 1.65) + 17;
  } else if (y < 430) {
    // First satin ribbon belly and mid-air twist
    let u = (y - 325) / 105;
    w = 17 + 13 * sin(u * 180);
    // Edge-on twist pinch around y = 420
    w *= 1 - 0.45 * exp(-pow((y - 420) / 22, 2));
  } else if (y < 498) {
    // High-tension capillary taper approaching the snap point
    let u = (y - 430) / 68;
    w = 16 * pow(1 - u, 1.5) + 2.4;
  } else if (y < 556) {
    // FROZEN AT THE INSTANT BEFORE THE RIBBON SNAPS:
    // Hair-thin spun-confection filament with a Plateau-Rayleigh satellite bead at y = 527
    let bead = 5.8 * exp(-pow((y - 527) / 8.5, 2));
    let neck = 2.1 + 0.9 * pow((y - 527) / 29, 2);
    w = neck + bead;
  } else {
    // Lower recoiling satin ribbon swelling into the top accordion fold
    let u = (y - 556) / (675 - 556);
    w = 2.8 + 35 * pow(u, 1.25);
  }

  return { cx, l: cx - w * 0.5, r: cx + w * 0.5, w };
}

function buildRibbonPoly(yStart, yEnd, step = 6, scaleW = 1.0, shiftX = 0) {
  let leftPts = [];
  let rightPts = [];
  for (let y = yStart; y <= yEnd; y += step) {
    let s = getRibbonSlice(y);
    let hw = (s.w * scaleW) * 0.5;
    leftPts.push([s.cx + shiftX - hw, y]);
    rightPts.push([s.cx + shiftX + hw, y]);
  }
  rightPts.reverse();
  return leftPts.concat(rightPts);
}

function drawHoneyMasterpiece() {
  // --- A. CAST SHADOWS & WARM AMBER CAUSTIC LENS GLOW ON PANCAKES ---
  brush.noStroke();
  // Warm golden-orange caustic light focused through the translucent honey pool onto the top pancake
  brush.fill("#ff9d00", 65);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.25, 0.08);
  safePoly(makeEllipsePts(584, 810, 155, 36, 36), 0.3);

  // Dark mahogany-amber contact shadow around the southern rim of the pool and folds
  brush.fill("#591c00", 85);
  brush.fillBleed(0.15, "out");
  safePoly(makeEllipsePts(582, 815, 142, 32, 36), 0.3);
  brush.noFill();

  // --- B. HONEY CLINGING TO THE WOODEN DIPPER & SECONDARY DRIPS ---
  drawDipperHoneyDrapes();

  // --- C. TOP PANCAKE HONEY POOL & CASCADING STREAMS OVER THE STACK ---
  drawPancakeHoneyPoolAndCascades();

  // --- D. THE STRETCHING, NEARLY-SNAPPING RIBBON (y = 235 to 675) ---
  drawStretchingHoneyRibbon();

  // --- E. THE FIVE GLASSY ACCORDION FOLDS (y = 655 to 806) ---
  drawHoneyAccordionFolds();

  // --- F. FINAL RAZOR-WHITE SPECULAR STREAKS & SPUN-CONFECTION TENSION HIGHLIGHTS ---
  drawRazorWhiteSpeculars();
}

function drawDipperHoneyDrapes() {
  // Viscous amber drapes coating the lower half of the wooden dipper ridges
  // and feeding into the main ribbon funnel through 4 arched capillary roots
  let drapeRoots = [
    // Root 1 (Front-left ridge k=6/5 at x=530..565)
    [
      [525, 232], [548, 224], [572, 255], [584, 305],
      [570, 305], [552, 265], [534, 248]
    ],
    // Root 2 (Central-left ridge k=4 at x=560..595)
    [
      [556, 218], [588, 206], [602, 255], [590, 315],
      [574, 315], [570, 262]
    ],
    // Root 3 (Central-right ridge k=3 at x=590..630)
    [
      [588, 204], [625, 188], [628, 242], [598, 315],
      [580, 315], [595, 252]
    ],
    // Root 4 (Rear-right ridge k=2 at x=625..665)
    [
      [622, 188], [662, 170], [654, 218], [612, 282],
      [592, 295], [622, 232]
    ]
  ];

  brush.noStroke();
  // Glaze 1: Pale sunlit gold base
  for (let rPts of drapeRoots) {
    brush.fill("#ffe366", 75);
    brush.fillBleed(0.08, "in");
    brush.fillTexture(0.2, 0.08);
    safePoly(rPts, 0.35);
  }
  // Glaze 2: Rich amber middle glaze
  for (let rPts of drapeRoots) {
    brush.fill("#f29400", 65);
    brush.fillBleed(0.06, "in");
    safePoly(rPts, 0.35);
  }
  brush.noFill();

  // Left secondary hanging teardrop drip at (528, 238..296)
  let leftDrip = [
    [522, 235], [536, 230], [533, 254], [537, 276],
    [533, 292], [527, 296], [521, 291], [519, 275], [525, 254]
  ];
  // Right secondary hanging bead at (658, 174..224)
  let rightDrip = [
    [650, 175], [668, 166], [665, 192], [669, 210],
    [663, 222], [655, 220], [652, 206], [655, 190]
  ];

  for (let dPts of [leftDrip, rightDrip]) {
    brush.wash("#ffea75", 190);
    safePoly(dPts, 0.35);
    brush.noWash();

    brush.fill("#e87a00", 85);
    brush.fillBleed(0.06, "in");
    brush.fillTexture(0.2, 0.12);
