    brush.set("cpencil", "#8a2200", 0.48);
    safeSpline(dPts.concat([dPts[0]]), 0.35);
  }
}

function drawPancakeHoneyPoolAndCascades() {
  // 1. TOP PANCAKE GLOSSY POOL (Centered around (582, 804))
  let poolOuter = [
