function drawStretchingHoneyRibbon() {
  // Build nested polygons for the stretching ribbon from y = 240 to y = 672
  let ribOuter = buildRibbonPoly(240, 672, 6, 1.0, 0);
  let ribMid = buildRibbonPoly(240, 672, 6, 0.72, 0);
  let ribCore = buildRibbonPoly(240, 672, 6, 0.42, 0);
  let ribLeftEdge = buildRibbonPoly(240, 672, 6, 0.24, -0.32);
  let ribRightEdge = buildRibbonPoly(240, 672, 6, 0.24, 0.32);

  brush.noStroke();

  // Glaze 1: Satin-smooth pale sunlit gold base across the entire taut ribbon
  brush.wash("#fff2a6", 220);
  safePoly(ribOuter, 0.25);
  brush.wash("#ffdd52", 160);
  safePoly(ribMid, 0.25);
  brush.noWash();

  // Glaze 2: Luminous amber watercolor glaze
  brush.fill("#f59e0b", 68);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.18, 0.08);
  safePoly(ribOuter, 0.25);

  // Glaze 3: Burnt-orange lateral Fresnel thickening along left & right ribbon edges
  brush.fill("#d45100", 78);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.2, 0.1);
  safePoly(ribLeftEdge, 0.25);
  safePoly(ribRightEdge, 0.25);

  // Glaze 4: Concentrated burnt-orange & deep amber at the upper funnel & mid-air twist (y = 330..450)
  let twistPoly = buildRibbonPoly(340, 455, 6, 0.85, 0);
  brush.fill("#b83700", 72);
  brush.fillBleed(0.05, "in");
  safePoly(twistPoly, 0.25);
  brush.noFill();

  // Glaze 5: Re-illuminate the thin stretched central membrane with sunlit pale gold
  brush.wash("#fff6bf", 150);
  safePoly(ribCore, 0.25);
  brush.noWash();

  // Satin-smooth longitudinal streamline gradients ("pulled, taut and translucent like spun confection")
  let streamFracs = [-0.46, -0.34, -0.2, 0.0, 0.2, 0.34, 0.46];
  for (let f of streamFracs) {
    let pts = [];
    for (let y = 242; y <= 670; y += 8) {
      let s = getRibbonSlice(y);
      // Add subtle twist phase so streamlines spiral across the ribbon at y = 390..440
      let twistShift = 0.18 * sin(((y - 240) / 430) * 360);
      let effF = constrain(f + twistShift, -0.48, 0.48);
      pts.push([s.cx + effF * s.w, y]);
    }
    let isEdge = abs(f) > 0.38;
    let isCenter = abs(f) < 0.12;
    if (isEdge) {
      brush.set("satin", "#b83300", 0.55);
      safeSpline(pts, 0.45);
      brush.set("cpencil", "#7a1800", 0.45);
      safeSpline(pts, 0.45);
    } else if (isCenter) {
      brush.set("satin", "#fff8cc", 0.75);
      safeSpline(pts, 0.45);
    } else {
      brush.set("satin", "#ffae00", 0.65);
      safeSpline(pts, 0.45);
    }
  }

  // Diagonal refractive fold crest across the mid-air ribbon twist (y = 365 to 445)
  let twistCrest = [];
  for (let i = 0; i <= 14; i++) {
    let u = i / 14;
    let y = 360 + u * 88;
    let s = getRibbonSlice(y);
    let f = map(u, 0, 1, -0.46, 0.46);
    twistCrest.push([s.cx + f * s.w, y]);
  }
  brush.set("satin", "#9e2600", 0.65);
  safeSpline(twistCrest, 0.45);
  brush.set("cpencil", "#661200", 0.5);
  safeSpline(twistCrest, 0.45);
}

function drawHoneyAccordionFolds() {
  // Five sumptuous, overlapping 3D figure-eight / accordion folds of honey
  // piling onto the top pancake pool (drawn bottom-to-top from Fold 1 to Fold 5)
  let folds = [
    // Fold 1: Wide cushion base fold merging into the pool (y = 766..806)
    {
      xL: 492, xR: 668, yTop: 766, yBot: 806, tilt: 3,
      loopSide: "both"
    },
    // Fold 2: Sweeping Left Loop (y = 740..780)
    {
      xL: 506, xR: 644, yTop: 740, yBot: 780, tilt: -4,
      loopSide: "left"
    },
    // Fold 3: Sweeping Right Loop (y = 714..754)
    {
      xL: 526, xR: 652, yTop: 714, yBot: 754, tilt: 5,
      loopSide: "right"
    },
    // Fold 4: Taut Upper-Left Loop (y = 688..726)
    {
      xL: 534, xR: 626, yTop: 688, yBot: 726, tilt: -5,
      loopSide: "left"
    },
    // Fold 5: Top Crest Fold receiving the falling ribbon (y = 662..698)
    {
      xL: 552, xR: 616, yTop: 662, yBot: 698, tilt: 4,
      loopSide: "right"
    }
  ];

  for (let idx = 0; idx < folds.length; idx++) {
    let f = folds[idx];
    let cx = (f.xL + f.xR) * 0.5;
    let cy = (f.yTop + f.yBot) * 0.5;
    let rx = (f.xR - f.xL) * 0.5;
    let ry = (f.yBot - f.yTop) * 0.5;

    // 1. Subsurface shadow & burnt-orange fold crease under the overhanging loop
    brush.noStroke();
    brush.fill("#731700", 85);
    brush.fillBleed(0.08, "out");
    brush.fillTexture(0.25, 0.12);
    safePoly(makeEllipsePts(cx, cy + ry * 0.45, rx * 0.96, ry * 0.65, 32, f.tilt), 0.35);
    brush.noFill();

    // 2. Pale gold translucent base of the fold
    let foldOuter = makeEllipsePts(cx, cy, rx, ry, 36, f.tilt);
    brush.wash("#ffea75", 205);
    safePoly(foldOuter, 0.35);
    brush.noWash();

    // 3. Rich amber watercolor glaze across the fold body
    brush.fill("#f08c00", 75);
    brush.fillBleed(0.06, "in");
    brush.fillTexture(0.2, 0.1);
    safePoly(foldOuter, 0.35);

    // 4. Deep burnt-orange glaze in the thickest doubled-over loop bends
    let leftBend = makeEllipsePts(f.xL + rx * 0.32, cy + 1, rx * 0.32, ry * 0.88, 28, f.tilt);
    let rightBend = makeEllipsePts(f.xR - rx * 0.32, cy + 1, rx * 0.32, ry * 0.88, 28, f.tilt);
    brush.fill("#bf3900", 88);
    brush.fillBleed(0.06, "in");
    safePoly(leftBend, 0.35);
    safePoly(rightBend, 0.35);

    brush.fill("#8c1d00", 72);
    brush.fillBleed(0.05, "in");
    safePoly(makeEllipsePts(f.xL + rx * 0.24, cy + 2, rx * 0.2, ry * 0.7, 24, f.tilt), 0.35);
    safePoly(makeEllipsePts(f.xR - rx * 0.24, cy + 2, rx * 0.2, ry * 0.7, 24, f.tilt), 0.35);
    brush.noFill();

    // 5. INTERNAL LIGHT GLOWING THROUGH THE THICKEST FOLDS
    // Intense luminous gold-amber core glowing right inside the burnt-orange loop turns!
    brush.wash("#ffe866", 175);
    safePoly(makeEllipsePts(cx, cy - ry * 0.1, rx * 0.65, ry * 0.52, 28, f.tilt), 0.35);
    brush.noWash();

    brush.set("glaze_soft", "#ffae00", 1.15);
    safeSpline(
      [
        [f.xL + 12, cy],
        [cx, cy - ry * 0.22],
        [f.xR - 12, cy]
      ],
      0.45
    );
    brush.set("satin", "#fff5b8", 0.95);
    safeSpline(
      [
        [f.xL + 18, cy - 1],
        [cx, cy - ry * 0.25],
        [f.xR - 18, cy - 1]
      ],
      0.45
    );

    // 6. Crisp burnt-orange refractive underside line of the fold
    brush.set("cpencil", "#661200", 0.55);
    let botArc = [];
    for (let a = 12; a <= 168; a += 12) {
      let ca = cos(f.tilt);
      let sa = sin(f.tilt);
      let lx = cos(a) * rx;
      let ly = sin(a) * ry;
      botArc.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
    }
    safeSpline(botArc, 0.4);
  }
}

