// ============================================================================
// ANATOMICAL SURFACE GEOMETRY & OVEREXPOSURE FIELD
// ============================================================================

function xFromU(u) {
  return X_LEFT + u * MOUTH_W;
}

function uFromX(x) {
  return (x - X_LEFT) / MOUTH_W;
}

// Commissure baseline (slight editorial tilt, left corner at y=606, right at y=584)
function yCommissure(u) {
  return 606 * (1 - u) + 584 * u;
}

// 1. Upper Vermilion Border (Cupid's bow & lateral slopes)
function yUpperVermilion(u) {
  let yc = yCommissure(u);
  let uc = constrain(u, 0, 1);
  // Sensual S-inflection near corners rising to Cupid's bow
  let arch = Math.pow(Math.sin(Math.PI * uc), 1.38) * 168;
  let peakL = 38 * Math.exp(-Math.pow((uc - 0.392) / 0.092, 2));
  let peakR = 35 * Math.exp(-Math.pow((uc - 0.608) / 0.092, 2));
  let notch = -35 * Math.exp(-Math.pow((uc - 0.500) / 0.046, 2));
  let cornerConcave = -7 * Math.exp(-Math.pow((uc - 0.12) / 0.07, 2));
  return yc - (arch + peakL + peakR + notch + cornerConcave);
}

// 2. Upper Lip Inner Border (Upper Stomion / Wet Line with central tubercle)
function yUpperStomion(u) {
  let yc = yCommissure(u);
  let uc = constrain(u, 0, 1);
  let openEnv = Math.pow(Math.sin(Math.PI * constrain((uc - 0.045) / 0.91, 0, 1)), 1.55);
  let tubercle = 16 * Math.exp(-Math.pow((uc - 0.500) / 0.082, 2));
  let latLiftL = 9 * Math.exp(-Math.pow((uc - 0.335) / 0.095, 2));
  let latLiftR = 8 * Math.exp(-Math.pow((uc - 0.665) / 0.095, 2));
  let cornerTuck = 5.5 * Math.exp(-Math.pow((uc - 0.055) / 0.042, 2));
  return yc - openEnv * 35 - (latLiftL + latLiftR) * openEnv + tubercle * openEnv + cornerTuck;
}

// 3. Lower Lip Inner Border (Lower Stomion / Wet Mucosal Line)
function yLowerStomion(u) {
  let yus = yUpperStomion(u);
  let uc = constrain(u, 0, 1);
  let partEnv = Math.pow(Math.sin(Math.PI * constrain((uc - 0.088) / 0.815, 0, 1)), 1.48);
  let centerDrop = 11 * Math.exp(-Math.pow((uc - 0.500) / 0.175, 2));
  return yus + partEnv * 53 + centerDrop * partEnv;
}

// 4. Lower Vermilion Border (Full bilobed lower lip contour)
function yLowerVermilion(u) {
  let yc = yCommissure(u);
  let uc = constrain(u, 0, 1);
  let belly = Math.pow(Math.sin(Math.PI * uc), 1.16) * 236;
  let lobeL = 23 * Math.exp(-Math.pow((uc - 0.375) / 0.145, 2));
  let lobeR = 21 * Math.exp(-Math.pow((uc - 0.625) / 0.145, 2));
  let medianCleft = -7.5 * Math.exp(-Math.pow((uc - 0.500) / 0.055, 2));
  let cornerCurve = -8 * Math.exp(-Math.pow((uc - 0.09) / 0.06, 2));
  return yc + belly + lobeL + lobeR + medianCleft + cornerCurve;
}

// Map (u, v) on Upper Lip: v=0 at Upper Vermilion, v=1 at Upper Stomion
function posUpperLip(u, v) {
  let x = xFromU(u);
  let y0 = yUpperVermilion(u);
  let y1 = yUpperStomion(u);
  return [x, y0 + (y1 - y0) * v];
}

// Map (u, v) on Lower Lip: v=0 at Lower Stomion, v=1 at Lower Vermilion
// Includes subtle 3D toroidal meridian bow across the plump lip belly
function posLowerLip(u, v) {
  let meridianShift = (u - 0.50) * (0.22 * Math.sin(Math.PI * v) + 0.09 * Math.pow(v, 1.4));
  let uEff = u + meridianShift * (1 - 0.65 * Math.pow(Math.abs(u - 0.5) * 2, 2));
  let x = xFromU(uEff);
  let y0 = yLowerStomion(uEff);
  let y1 = yLowerVermilion(uEff);
  return [x, y0 + (y1 - y0) * v];
}

// Blown-out beauty-dish overexposure visibility map:
// 1.0 = crispest tonal retention (left commissure, stomion, gloss pool)
// 0.0 = eaten completely into pure white paper (right side, outer cheek/chin)
function exposureVisibility(x, y) {
  // Primary beauty-dish hot-spot sits upper-right (around x=980, y=420)
  let dxHot = (x - 1015) / 480;
  let dyHot = (y - 440) / 460;
  let distHot = Math.sqrt(dxHot * dxHot + dyHot * dyHot);
  let hotEat = constrain(map(distHot, 0.28, 1.08, 0.0, 1.0), 0, 1);

  // Outer vignette eat-away (top philtrum, bottom chin, far left margin)
  let dxCenter = (x - 535) / 510;
  let dyCenter = (y - 625) / 365;
  let radial = Math.sqrt(dxCenter * dxCenter * 0.75 + dyCenter * dyCenter);
  let edgeEat = constrain(map(radial, 0.72, 1.22, 1.0, 0.0), 0, 1);

  // Extra preservation around the left commissure and lower gloss pool
  let dComm = Math.hypot((x - 185) / 170, (y - 606) / 145);
  let commBoost = 0.35 * Math.exp(-dComm * dComm);

  let dPool = Math.hypot((x - 595) / 230, (y - 715) / 120);
  let poolBoost = 0.28 * Math.exp(-dPool * dPool);

  return constrain(hotEat * edgeEat + commBoost + poolBoost, 0, 1);
}

// Groove wave modulation shared between sulci and highlight meniscus scallops
function sulcusScallop(u) {
  return (
    0.012 * Math.sin(u * 185) +
    0.008 * Math.cos(u * 310 + 0.7) +
    0.006 * Math.sin(u * 490 - 1.2)
  );
}

// ============================================================================
// WET LACQUER HIGHLIGHT POOL GEOMETRY & EXCLUSION TESTS
// ============================================================================

function buildHighlightPolygons() {
  highlightPolys = [];
  upperCatchPolys = [];

  // Helper to build a scalloped lower-lip specular island in (u, v) space
  function makeLowerIsland(uStart, uEnd, vCenterFn, vHalfFn, steps, scallopAmp) {
    let pts = [];
    // Top meniscus edge (left to right)
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let u = lerp(uStart, uEnd, t);
      let env = Math.pow(Math.sin(Math.PI * t), 0.58);
      let sc = scallopAmp * sulcusScallop(u) * env;
      // Sharp upward liquid peaks between sulcus grooves
      let v = vCenterFn(u, t) - vHalfFn(u, t) * env + sc;
      pts.push(posLowerLip(u, v));
    }
    // Bottom meniscus edge (right to left)
    for (let i = steps; i >= 0; i--) {
      let t = i / steps;
      let u = lerp(uStart, uEnd, t);
      let env = Math.pow(Math.sin(Math.PI * t), 0.62);
      let sc = scallopAmp * 1.25 * sulcusScallop(u + 0.003) * env;
      let lobe = 0.014 * Math.sin(t * Math.PI * 3) * env;
      let v = vCenterFn(u, t) + vHalfFn(u, t) * env + sc + lobe;
      pts.push(posLowerLip(u, v));
    }
    return pts;
  }

  // 1. Main Left-Center Lacquer Pool Island (A)
  highlightPolys.push(
    makeLowerIsland(
      0.328,
      0.493,
      (u, t) => 0.355 + 0.018 * Math.sin(t * Math.PI),
      (u, t) => 0.132 * (0.82 + 0.28 * Math.sin(t * Math.PI * 2 - 0.3)),
      44,
      1.15
    )
  );

  // 2. Main Right-Center Lacquer Pool Island (B) - separated by central sulcus bridge
  highlightPolys.push(
    makeLowerIsland(
      0.503,
      0.665,
      (u, t) => 0.348 + 0.012 * Math.sin(t * Math.PI),
      (u, t) => 0.136 * (0.85 + 0.24 * Math.cos(t * Math.PI * 2 - 0.5)),
      44,
      1.15
    )
  );

  // 3. Right Lateral Gloss Lobe (C)
  highlightPolys.push(
    makeLowerIsland(
      0.676,
      0.752,
      (u, t) => 0.332 - 0.015 * t,
      (u, t) => 0.088 * (1 - 0.25 * t),
      26,
      0.85
    )
  );

  // 4. Lower Equator Secondary Liquid Ribbon Left (D)
  highlightPolys.push(
    makeLowerIsland(
      0.372,
      0.474,
      (u, t) => 0.565 + 0.01 * Math.sin(t * Math.PI),
      (u, t) => 0.036,
      24,
      0.6
    )
  );

  // 5. Lower Equator Secondary Liquid Ribbon Right (E)
  highlightPolys.push(
    makeLowerIsland(
      0.522,
      0.622,
      (u, t) => 0.555 + 0.01 * Math.sin(t * Math.PI),
      (u, t) => 0.035,
      24,
      0.6
    )
  );

  // 6. Left Satellite Specular Beads (F, G, H)
  highlightPolys.push(
    makeLowerIsland(0.292, 0.319, () => 0.365, () => 0.052, 16, 0.4)
  );
  highlightPolys.push(
    makeLowerIsland(0.308, 0.332, () => 0.495, () => 0.032, 14, 0.3)
  );
  highlightPolys.push(
    makeLowerIsland(0.268, 0.284, () => 0.382, () => 0.028, 12, 0.2)
  );

  // 7. Wet Inner Mucosal Rim Micro-Catchlights on Lower Lip
  highlightPolys.push(
    makeLowerIsland(0.415, 0.482, () => 0.062, () => 0.022, 16, 0.3)
  );
  highlightPolys.push(
    makeLowerIsland(0.518, 0.588, () => 0.060, () => 0.022, 16, 0.3)
  );

  // 8. Upper Lip Wet Rim Catchlights (along tubercle & lateral roll)
  function makeUpperCatch(uStart, uEnd, vCenter, vHalf, steps) {
    let pts = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let u = lerp(uStart, uEnd, t);
      let env = Math.pow(Math.sin(Math.PI * t), 0.65);
      pts.push(posUpperLip(u, vCenter - vHalf * env));
    }
    for (let i = steps; i >= 0; i--) {
      let t = i / steps;
      let u = lerp(uStart, uEnd, t);
      let env = Math.pow(Math.sin(Math.PI * t), 0.65);
      pts.push(posUpperLip(u, vCenter + vHalf * env));
    }
    return pts;
  }

  upperCatchPolys.push(makeUpperCatch(0.455, 0.542, 0.86, 0.045, 18));
  upperCatchPolys.push(makeUpperCatch(0.355, 0.415, 0.83, 0.032, 14));
  upperCatchPolys.push(makeUpperCatch(0.575, 0.635, 0.83, 0.032, 14));
}

// Point-in-polygon ray casting test
function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect =
      yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

function isInsideAnyHighlight(x, y) {
  // Fast bounding-box pre-check
  if (x < 380 || x > 865 || y < 535 || y > 815) return false;
  for (let i = 0; i < highlightPolys.length; i++) {
    if (pointInPoly(x, y, highlightPolys[i])) return true;
  }
  for (let i = 0; i < upperCatchPolys.length; i++) {
    if (pointInPoly(x, y, upperCatchPolys[i])) return true;
  }
  return false;
}

// Draw a spline that cleanly lifts the pencil across any untouched-paper highlight island
function drawClippedSpline(pts, curvature = 0.5) {
  let currentRun = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (!isInsideAnyHighlight(p[0], p[1])) {
      currentRun.push(p);
    } else {
      if (currentRun.length >= 2) {
        brush.spline(currentRun, curvature);
      }
      currentRun = [];
    }
  }
  if (currentRun.length >= 2) {
    brush.spline(currentRun, curvature);
  }
}

// ============================================================================
// LAYER 1: FAINT ROSE MADDER WATERCOLOUR BLOOM IN LOWER LIP GLOSS POOL
// ============================================================================

function drawRoseMadderBloom() {
  brush.noField();
  brush.noStroke();

  // Helper to draw an organic elliptical/crescent watercolor lobe in lower-lip (u,v)
  function fillLowerLipLobe(uMin, uMax, vMin, vMax, steps, wobbleAmt, curvature = 0.55) {
    brush.beginShape(curvature);
    let uMid = (uMin + uMax) * 0.5;
    let vMid = (vMin + vMax) * 0.5;
    let uRad = (uMax - uMin) * 0.5;
    let vRad = (vMax - vMin) * 0.5;
    for (let i = 0; i < steps; i++) {
      let ang = (i / steps) * 360;
      let wob = 1 + wobbleAmt * (noise(i * 0.45, uMid * 10, vMid * 10) - 0.5);
      let u = uMid + Math.cos(radians(ang)) * uRad * wob;
      let v = vMid + Math.sin(radians(ang)) * vRad * wob;
      let [px, py] = posLowerLip(u, constrain(v, 0.02, 0.96));
      brush.vertex(px, py);
    }
    brush.endShape(true);
  }

  // Batch 1: Whisper-pale outer rose-water halo (confined strictly to lower lip gloss pool)
  brush.fill("#F4CEDC", 24);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.42, 0.25);
  fillLowerLipLobe(0.26, 0.77, 0.08, 0.84, 24, 0.14);
  fillLowerLipLobe(0.30, 0.73, 0.14, 0.78, 22, 0.16);

  // Batch 2: Luminous cool Rose Madder body around the lacquer pool
  brush.fill("#E593AE", 28);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.48, 0.32);
  fillLowerLipLobe(0.30, 0.52, 0.16, 0.68, 20, 0.15);
  fillLowerLipLobe(0.48, 0.71, 0.15, 0.66, 20, 0.15);
  fillLowerLipLobe(0.35, 0.65, 0.38, 0.76, 20, 0.14);

  // Batch 3: Deeper Alizarin / Rose Madder pigment pooling directly against the highlight meniscus
  brush.fill("#D15C80", 30);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.55, 0.42);
  // Upper meniscus shadow-bloom just above Islands A & B
  fillLowerLipLobe(0.32, 0.50, 0.14, 0.34, 18, 0.12);
  fillLowerLipLobe(0.50, 0.67, 0.14, 0.33, 18, 0.12);
  // Central sulcus bridge bloom between Islands A & B
  fillLowerLipLobe(0.475, 0.525, 0.20, 0.58, 16, 0.10);
  // Lower meniscus trough between primary islands (A,B) and secondary ribbon (D,E)
  fillLowerLipLobe(0.34, 0.50, 0.44, 0.60, 18, 0.12);
  fillLowerLipLobe(0.50, 0.66, 0.43, 0.59, 18, 0.12);

  // Batch 4: Cool violet-rose glaze accents for wet depth in the gloss pool
  brush.fill("#B85278", 22);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.52, 0.45);
  fillLowerLipLobe(0.36, 0.49, 0.18, 0.29, 16, 0.10);
  fillLowerLipLobe(0.51, 0.63, 0.18, 0.28, 16, 0.10);
  fillLowerLipLobe(0.482, 0.518, 0.26, 0.50, 14, 0.08);

  brush.noFill();

  // Restore 100% pure untouched paper inside all highlight islands so no watercolor bleed
  // ever softens their razor-sharp lacquer edges!
  brush.wash(PAPER_HEX, 255);
  for (let poly of highlightPolys) {
    brush.beginShape(0.15);
    for (let pt of poly) {
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);
  }
  for (let poly of upperCatchPolys) {
    brush.beginShape(0.15);
    for (let pt of poly) {
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);
  }
  brush.noWash();
}

// ============================================================================
// LAYER 2: WHISPER-THIN GRAPHITE FORM SHADING (UPPER LIP, STOMION, MENTOLABIAL)
// ============================================================================

function drawGraphiteFormShading() {
  brush.noFill();
  brush.noWash();

  // 1. Subtle cool-silver tonal shading on the lower third of the Upper Lip
  // (where the upper lip curves downward into the parted mouth away from the beauty dish)
  let upperShadeColors = ["#DCE1EA", "#CFD6E2", "#C0C9D8", "#B0BACB"];
  for (let pass = 0; pass < 4; pass++) {
    brush.set("graphite_shade", upperShadeColors[pass], 0.65 - pass * 0.08);
    let vStart = 0.35 + pass * 0.14;
    let numLines = 58 - pass * 8;
    for (let i = 0; i < numLines; i++) {
      let u = map(i, 0, numLines - 1, 0.04, 0.86) + random(-0.004, 0.004);
      let [xTest, yTest] = posUpperLip(u, 0.75);
      let vis = exposureVisibility(xTest, yTest);
      if (vis < 0.18 + pass * 0.12) continue;

      let pts = [];
      for (let s = 0; s <= 5; s++) {
        let v = lerp(vStart, 0.98, s / 5);
        let uCurve = u + (u - 0.5) * 0.04 * Math.sin(v * Math.PI);
        let [px, py] = posUpperLip(uCurve, v);
        pts.push([px, py, 0.3 + 0.7 * (s / 5) * vis]);
      }
      drawClippedSpline(pts, 0.45);
    }
  }

  // 2. Philtrum dimple & columns whisper-pale silver shading above Cupid's bow
  brush.set("graphite_6H", "#D4DAE4", 0.55);
  for (let i = 0; i < 48; i++) {
    let u = random(0.36, 0.63);
    let [bx, by] = posUpperLip(u, 0.0);
    // White roll offset (leave 7px of pure white paper right above the vermilion border!)
    let yStart = by - random(8, 16);
    let len = random(28, 85) * Math.exp(-Math.pow((u - 0.5) / 0.12, 2));
    let vis = exposureVisibility(bx, yStart - len * 0.5);
    if (vis < 0.22) continue;

    // Concentrate in the central philtrum trough (u ~ 0.46..0.54) and just outside the ridges
    let inTrough = Math.exp(-Math.pow((u - 0.50) / 0.038, 2));
    let onOuterSlope =
      Math.exp(-Math.pow((u - 0.38) / 0.035, 2)) +
      Math.exp(-Math.pow((u - 0.61) / 0.035, 2));
    if (random() > inTrough * 0.85 + onOuterSlope * 0.55) continue;

    let tilt = (u - 0.5) * 18;
    let pts = [
      [bx + tilt * 0.2, yStart, 0.7 * vis],
      [bx + tilt * 0.6, yStart - len * 0.5, 0.45 * vis],
      [bx + tilt, yStart - len, 0.1 * vis]
    ];
    brush.spline(pts, 0.4);
  }

  // 3. Lower Lip underside roll & Mentolabial shadow (beneath left/center lower lip)
  for (let pass = 0; pass < 3; pass++) {
    let col = pass === 0 ? "#D8DEE8" : pass === 1 ? "#C6CEDC" : "#B4BECE";
    brush.set("graphite_shade", col, 0.6 - pass * 0.1);
    for (let i = 0; i < 52; i++) {
      let u = map(i, 0, 51, 0.06, 0.76) + random(-0.005, 0.005);
      let [x0, y0] = posLowerLip(u, 0.80 + pass * 0.05);
      let vis = exposureVisibility(x0, y0);
      if (vis < 0.25 + pass * 0.12) continue;

      let pts = [];
      for (let s = 0; s <= 4; s++) {
        let v = lerp(0.78 + pass * 0.04, 1.06 + pass * 0.03, s / 4);
        let [px, py] = posLowerLip(u, v);
        pts.push([px, py, 0.5 * vis * Math.sin((s / 4) * Math.PI)]);
      }
      drawClippedSpline(pts, 0.5);
    }
  }
}

// ============================================================================
// LAYER 3: PARTED MOUTH INTERIOR (ORAL CAVITY SHADOW, TEETH, SALIVA MENISCI)
// ============================================================================

function drawMouthInteriorAndTeeth() {
  // We model the parted opening between u = 0.088 and u = 0.903
  // Tooth boundaries in u:
  // Left Lateral: [0.305, 0.388], Left Central: [0.388, 0.500],
  // Right Central: [0.500, 0.612], Right Lateral: [0.612, 0.695]
  function yIncisalEdge(u) {
    let yus = yUpperStomion(u);
    let yls = yLowerStomion(u);
    let gap = yls - yus;
    if (gap <= 2) return yus;

    // Central incisors hang down ~62% of the central parted gap
    if (u >= 0.388 && u <= 0.612) {
      let tTooth = u < 0.500 ? (u - 0.388) / 0.112 : (u - 0.500) / 0.112;
      // Rounded mesial and distal incisal corners (embrasures)
      let cornerRound = 4.5 * Math.pow(Math.cos((tTooth - 0.5) * Math.PI), 0.35);
      return yus + gap * 0.54 + cornerRound;
    }
    // Lateral incisors are slightly shorter/higher
    if ((u >= 0.305 && u < 0.388) || (u > 0.612 && u <= 0.695)) {
      let tLat = u < 0.5 ? (u - 0.305) / 0.083 : (u - 0.612) / 0.083;
      let arch = 4.0 * Math.sin(tLat * Math.PI);
      return yus + gap * 0.34 + arch;
    }
    return yus; // Outside visible anterior teeth
  }

  // 1. Dark velvety graphite shading in the recessed oral cavity BELOW the teeth
  // and in the lateral buccal corridors (u in [0.09, 0.31] and [0.69, 0.88])
  let cavityColors = ["#8F9BAE", "#6E7B8F", "#4E596C", "#333C4D", "#202634"];
  for (let layer = 0; layer < cavityColors.length; layer++) {
    brush.set(layer < 2 ? "graphite_2H_fine" : "crevice_2B", cavityColors[layer], 0.55 - layer * 0.05);
    let steps = 160 - layer * 18;
    for (let i = 0; i < steps; i++) {
      let u = map(i, 0, steps - 1, 0.085, 0.875) + random(-0.002, 0.002);
      let yTop = yIncisalEdge(u);
      let yBot = yLowerStomion(u);
      let cavityH = yBot - yTop;
      if (cavityH < 1.2) continue;

      let x = xFromU(u);
      let vis = exposureVisibility(x, (yTop + yBot) * 0.5);
      // Darker toward the left corner and directly under the incisal edge
      let cornerWeight = Math.exp(-Math.pow((u - 0.16) / 0.14, 2));
      if (layer >= 3 && vis * (0.55 + 0.65 * cornerWeight) < 0.42) continue;
      if (vis < 0.15) continue;

      let y1 = yTop + random(0.2, 2.0);
      let y2 = lerp(yTop, yBot, constrain(0.92 - layer * 0.12, 0.35, 0.95));
      if (y2 > y1 + 0.8) {
        // Leave tiny untouched saliva pinpoint highlights along the wet lower shelf
        let salivaGap =
          Math.abs(u - 0.245) < 0.008 ||
          Math.abs(u - 0.345) < 0.007 ||
          Math.abs(u - 0.642) < 0.007;
        if (salivaGap && y2 > yBot - 5.5) {
          y2 = yBot - 6.0;
        }
        if (y2 > y1 + 0.8) {
          brush.line(x + random(-0.6, 0.6), y1, x + random(-0.6, 0.6), y2);
        }
      }
    }
  }

  // Horizontal cross-hatching inside the deepest left buccal vestibule (u in [0.09, 0.34])
  brush.set("crevice_2B", "#262D3D", 0.42);
  for (let r = 0; r < 14; r++) {
    let t = r / 13;
    let pts = [];
    for (let u = 0.09; u <= 0.35; u += 0.02) {
      let yTop = yIncisalEdge(u);
      let yBot = yLowerStomion(u) - 2.5;
      if (yBot > yTop + 1) {
        pts.push([xFromU(u), lerp(yTop, yBot, t), 0.85 * (1 - (u - 0.09) / 0.28)]);
      }
    }
    if (pts.length >= 2) brush.spline(pts, 0.4);
  }

  // 2. Subtle cast shadow from the Upper Lip onto the enamel of the upper incisors
  for (let i = 0; i < 95; i++) {
    let u = map(i, 0, 94, 0.305, 0.695);
    let yus = yUpperStomion(u);
    let yInc = yIncisalEdge(u);
    let toothH = yInc - yus;
    if (toothH < 2.5) continue;

    let x = xFromU(u);
    let vis = exposureVisibility(x, yus + toothH * 0.5);

    // Upper half of visible tooth receives soft cool cast shadow; lower edge stays pure white enamel
    let shadowDepth = toothH * random(0.42, 0.62);
    brush.set("graphite_4H", "#A6B1C2", 0.38 * vis);
    brush.line(x, yus + 0.5, x, yus + shadowDepth);

    // Deeper contact shadow right under the wet upper lip rim
    brush.set("graphite_2H_fine", "#6C788B", 0.35 * vis);
    brush.line(x, yus, x, yus + toothH * random(0.18, 0.28));
  }

  // 3. Crisp interdental lines & dark embrasure triangles between the incisors
  let interdentalUs = [0.388, 0.500, 0.612];
  for (let iu of interdentalUs) {
    let x = xFromU(iu);
    let yus = yUpperStomion(iu);
    let yInc = yIncisalEdge(iu + 0.012);
    let vis = exposureVisibility(x, yus + 10);

    // Delicate vertical interdental seam
    brush.set("graphite_2H_fine", "#5B6678", 0.38 * vis);
    brush.line(x, yus + 1, x, yInc + 2);

    // Small dark interdental triangle at the bottom embrasure notch
    brush.set("crevice_2B", "#2D3546", 0.45 * vis);
    for (let dx = -3.5; dx <= 3.5; dx += 0.8) {
      let h = (1 - Math.abs(dx) / 3.8) * 5.5;
      brush.line(x + dx, yInc - h + 2.5, x + dx, yInc + 3.0);
    }
  }
}

// ============================================================================
// LAYER 4: THE SINGLE DEEP GRAPHITE CREASE AT THE LEFT CORNER OF THE MOUTH
// ============================================================================

function drawCornerCreaseMasterwork() {
  // Left oral commissure sits at u = 0 (x = 168, y = 606)
  // Extending outward-left to x ~ 132 and inward into the stomion to x ~ 285
  let xCorner = X_LEFT;
  let yCorner = yCommissure(0);

  // 1. Soft form-shadow halo of the modiolus (muscular node outside the corner)
  brush.set("graphite_shade", "#CFD6E2", 0.55);
  for (let i = 0; i < 36; i++) {
    let ang = map(i, 0, 35, 115, 255) + random(-4, 4);
    let r1 = random(6, 22);
    let r2 = r1 + random(24, 58);
    let x1 = xCorner + 6 + Math.cos(radians(ang)) * r1;
    let y1 = yCorner + 2 + Math.sin(radians(ang)) * r1 * 0.85;
    let x2 = xCorner + 6 + Math.cos(radians(ang)) * r2;
    let y2 = yCorner + 2 + Math.sin(radians(ang)) * r2 * 0.85;
    brush.line(x1, y1, x2, y2);
  }

  // 2. Upper commissural hood fold (where the upper lip skin wraps around the corner)
  for (let p = 0; p < 8; p++) {
    let off = (p - 3.5) * 1.1;
    let col = p < 3 ? "#8D99AC" : p < 6 ? "#AEB8C8" : "#CBD2DF";
    brush.set("graphite_4H", col, 0.36);
    let pts = [
      [xCorner + 38, yUpperVermilion(0.045) + off * 0.5, 0.2],
      [xCorner + 12, yCorner - 12 + off * 0.7, 0.65],
      [xCorner - 14, yCorner - 3 + off, 0.9],
      [xCorner - 26, yCorner + 11 + off * 1.2, 0.45],
      [xCorner - 30, yCorner + 25 + off * 1.4, 0.1]
    ];
    brush.spline(pts, 0.5);
  }

  // 3. THE SINGLE DEEP GRAPHITE CREASE (the dark tonal anchor of the entire drawing)
  // Built from progressive layers of 2H -> HB -> 2B -> deep carbon-graphite core
  let creaseLayers = [
    { brush: "graphite_2H_fine", col: "#7D899C", w: 0.65, spread: 4.2, count: 14 },
    { brush: "graphite_2H_fine", col: "#546073", w: 0.52, spread: 2.6, count: 14 },
    { brush: "crevice_2B", col: "#313A4B", w: 0.48, spread: 1.5, count: 12 },
    { brush: "crevice_2B", col: "#161B26", w: 0.42, spread: 0.65, count: 10 }
  ];

  for (let layer of creaseLayers) {
    brush.set(layer.brush, layer.col, layer.w);
    for (let i = 0; i < layer.count; i++) {
      let dy = map(i, 0, layer.count - 1, -layer.spread, layer.spread * 1.25);
      // Asymmetric vertical profile: razor-sharp on upper edge (dy < 0), softer downward gradient
      let pScale = dy < 0 ? 1.15 : map(dy, 0, layer.spread * 1.25, 1.0, 0.25);

      let pts = [
        [xCorner - 32 + random(-2, 2), yCorner - 7 + dy * 1.3, 0.08 * pScale],
        [xCorner - 16, yCorner - 2.5 + dy * 0.9, 0.55 * pScale],
        [xCorner - 3, yCorner + 0.5 + dy * 0.6, 1.0 * pScale],
        [xCorner + 14, yCorner + 3.5 + dy * 0.55, 1.1 * pScale],
        [xCorner + 38, yUpperStomion(0.042) + dy * 0.7, 0.95 * pScale],
        [xCorner + 68, yUpperStomion(0.078) + dy * 0.8, 0.65 * pScale],
        [xCorner + 102, yUpperStomion(0.118) + dy * 0.9, 0.2 * pScale]
      ];
      brush.spline(pts, 0.45);
    }
  }

  // Secondary downward tension crease branching from the commissure node
  for (let k = 0; k < 6; k++) {
    let off = (k - 2.5) * 0.7;
    brush.set("graphite_2H_fine", k < 2 ? "#465062" : "#7B879B", 0.35);
    let pts = [
      [xCorner + 6, yCorner + 2 + off * 0.3, 0.9],
      [xCorner - 6, yCorner + 9 + off * 0.7, 0.65],
      [xCorner - 19, yCorner + 19 + off, 0.35],
      [xCorner - 29, yCorner + 31 + off * 1.3, 0.05]
    ];
    brush.spline(pts, 0.45);
  }

  // Microscopic wet pinpoint catchlight right at the inner corner node (xCorner + 19, yCorner + 3)
  brush.noStroke();
  brush.wash(PAPER_HEX, 255);
  brush.circle(xCorner + 20, yCorner + 3.2, 2.4, 0.1);
  brush.noWash();

  // Crisp dark rim hugging that wet corner pinpoint catchlight
  brush.set("crevice_2B", "#141923", 0.32);
  brush.arc(xCorner + 20, yCorner + 3.2, 2.8, 160, 350);
}

// ============================================================================
// LAYER 5: HYPERREAL LIP LINES (SULCI) ON UPPER & LOWER LIPS
// ============================================================================

function drawLipSulci() {
  // --------------------------------------------------------------------------
  // A. LOWER LIP SULCI (Radial & Branching Diamond-Mesh Grooves)
  // --------------------------------------------------------------------------
  let numLowerSulci = 148;
  for (let i = 0; i < numLowerSulci; i++) {
    let u0 = map(i, 0, numLowerSulci - 1, 0.035, 0.915) + random(-0.0025, 0.0025);
    let [xMid, yMid] = posLowerLip(u0, 0.45);
    let vis = exposureVisibility(xMid, yMid);
    if (vis < 0.08) continue;

    // Determine if this sulcus sits inside the Rose Madder gloss pool
    let inRosePool =
      u0 > 0.28 &&
      u0 < 0.73 &&
      Math.exp(-Math.pow((u0 - 0.50) / 0.19, 2)) > 0.35;

    // Prominent anatomical sulci occur every ~5–7 lines (including the central cleft at u ~ 0.498)
    let isMajor = i % 6 === 0 || Math.abs(u0 - 0.498) < 0.008;

    // Select whisper-thin cool silver-grey or subtle rose-slate inside the watercolor bloom
    let strokeCol;
    if (inRosePool) {
      strokeCol = isMajor
        ? random(["#8E677B", "#9A7286", "#7F5C70"])
        : random(["#B28FA1", "#C0A0B0", "#A68496"]);
    } else {
      strokeCol = isMajor
        ? random(["#8A96A9", "#98A4B6", "#7C889B"])
        : random(["#B6C0CE", "#C5CEDB", "#D2D9E4", "#A8B2C2"]);
    }

    let brushName = isMajor ? "graphite_4H" : "graphite_6H";
    let baseWeight = (isMajor ? 0.44 : 0.28) * constrain(vis * 1.1, 0.2, 1.0);
    brush.set(brushName, strokeCol, baseWeight);

    // Trace sulcus from v=0.01 (wet inner line) to v=0.99 (lower vermilion border)
    let vSteps = 18;
    let pts = [];
    let phase = random(100);
    for (let s = 0; s <= vSteps; s++) {
      let v = s / vSteps;
      // Subtle organic lateral weave along the groove
      let weave = 0.0035 * Math.sin(v * Math.PI * 2.5 + phase) * Math.sin(v * Math.PI);
      let [px, py] = posLowerLip(u0 + weave, v);
      let localVis = exposureVisibility(px, py);

      // Tonal modulation along the 3D curve of the lower lip:
      // Stronger near the wet inner line (v < 0.22), across the gloss meniscus (v ~ 0.35..0.55),
      // and rolling under the lower vermilion shadow (v > 0.80)
      let pProfile =
        0.85 * Math.exp(-Math.pow((v - 0.08) / 0.12, 2)) +
        0.75 * Math.exp(-Math.pow((v - 0.42) / 0.22, 2)) +
        0.70 * Math.exp(-Math.pow((v - 0.88) / 0.14, 2));
      let pressure = constrain(pProfile * localVis * (isMajor ? 1.15 : 0.85), 0.08, 1.1);
      pts.push([px, py, pressure]);
    }
    drawClippedSpline(pts, 0.45);

    // Secondary Y-fork / diamond-mesh branches (characteristic of real lip epidermis)
    if (isMajor && u0 > 0.14 && u0 < 0.78 && vis > 0.28) {
      let vSplit = random(0.22, 0.44);
      let vMerge = vSplit + random(0.26, 0.42);
      let dir = random([-1, 1]);
      let branchPts = [];
      for (let b = 0; b <= 8; b++) {
        let tb = b / 8;
        let v = lerp(vSplit, min(0.98, vMerge), tb);
        let uBranch = u0 + dir * 0.0085 * Math.sin(tb * Math.PI);
        let [bx, by] = posLowerLip(uBranch, v);
        branchPts.push([bx, by, 0.55 * vis * Math.sin(tb * Math.PI)]);
      }
      brush.set("graphite_6H", strokeCol, baseWeight * 0.78);
      drawClippedSpline(branchPts, 0.45);
    }
  }

  // Accentuate the wet inner mucosal creases at the top of the lower lip (v in [0.0, 0.16])
  for (let i = 0; i < 64; i++) {
    let u = map(i, 0, 63, 0.10, 0.82) + random(-0.003, 0.003);
    let [x0, y0] = posLowerLip(u, 0.0);
    let vis = exposureVisibility(x0, y0);
    if (vis < 0.20) continue;

    let col = u > 0.32 && u < 0.68 ? "#77596C" : "#6D798C";
    brush.set("graphite_2H_fine", col, 0.34 * vis);
    let pts = [];
    for (let s = 0; s <= 5; s++) {
      let v = (s / 5) * random(0.11, 0.18);
      let [px, py] = posLowerLip(u, v);
      pts.push([px, py, (1 - s / 5) * 0.9 * vis]);
    }
    drawClippedSpline(pts, 0.4);
  }

  // --------------------------------------------------------------------------
  // B. UPPER LIP SULCI (Converging Radial Lines & Cupid's Bow Definition)
  // --------------------------------------------------------------------------
  let numUpperSulci = 124;
  for (let i = 0; i < numUpperSulci; i++) {
    let u0 = map(i, 0, numUpperSulci - 1, 0.025, 0.90) + random(-0.0025, 0.0025);
    let [xMid, yMid] = posUpperLip(u0, 0.6);
    let vis = exposureVisibility(xMid, yMid);
    if (vis < 0.10) continue;

    let isMajor = i % 5 === 0 || Math.abs(u0 - 0.500) < 0.01;
    let col = isMajor
      ? random(["#828E9F", "#919DAF", "#748093"])
      : random(["#B2BCCB", "#C2CAD8", "#D0D7E2", "#A3AEBF"]);

    brush.set(isMajor ? "graphite_4H" : "graphite_6H", col, (isMajor ? 0.40 : 0.26) * vis);

    // Upper lip sulci start slightly below the white roll (v ~ 0.06) and deepen toward v = 1.0
    let vStart = random(0.03, 0.14);
    let vSteps = 14;
    let pts = [];
    let phase = random(100);
    for (let s = 0; s <= vSteps; s++) {
      let v = lerp(vStart, 1.0, s / vSteps);
      // Slight inward radial convergence toward the stomion and around the central tubercle
      let radShift = (u0 - 0.50) * -0.055 * Math.pow(v, 1.3);
      let tubercleWrap =
        (u0 - 0.50) * 0.035 * Math.exp(-Math.pow((u0 - 0.50) / 0.09, 2)) * Math.sin(v * Math.PI);
      let weave = 0.0028 * Math.sin(v * Math.PI * 2 + phase);
      let [px, py] = posUpperLip(u0 + radShift + tubercleWrap + weave, v);
      let localVis = exposureVisibility(px, py);

      // Upper lip is brightest near top vermilion border (v -> 0) and darkest rolling into stomion (v -> 1)
      let pCurve = 0.20 + 0.85 * Math.pow(v, 1.25);
      pts.push([px, py, pCurve * localVis * (isMajor ? 1.1 : 0.85)]);
    }
    drawClippedSpline(pts, 0.45);
  }

  // Delicate Cupid's bow & Upper Vermilion border micro-contour
  // (Just above this line sits the pure white untouched mucocutaneous "white roll")
  for (let pass = 0; pass < 2; pass++) {
    brush.set("graphite_6H", pass === 0 ? "#C4CCD9" : "#9FAAB9", 0.32);
    let pts = [];
    for (let u = 0.02; u <= 0.82; u += 0.012) {
      let [px, py] = posUpperLip(u, 0.01 + pass * 0.015);
      let vis = exposureVisibility(px, py);
      // Emphasize the Cupid's bow notch (u ~ 0.50) and left slope (u < 0.42)
      let bowAccent = 0.45 + 0.55 * Math.exp(-Math.pow((u - 0.50) / 0.11, 2));
      if (vis * bowAccent > 0.16) {
        pts.push([px, py + random(-0.4, 0.4), vis * bowAccent * 0.85]);
      } else {
        if (pts.length >= 2) brush.spline(pts, 0.45);
        pts = [];
      }
    }
    if (pts.length >= 2) brush.spline(pts, 0.45);
  }
}

// ============================================================================
// LAYER 6: WET LACQUER HIGHLIGHT MENISCUS EDGING
// ============================================================================

function drawLacquerMeniscusEdges() {
  // "The pool's highlight is left as pure untouched paper, edged so cleanly it reads as wet lacquer."
  // We trace the exact liquid perimeter of each highlight island with surgical precision,
  // varying color from rose-graphite (where it sits inside the Rose Madder bloom)
  // to cool silver-graphite (where it approaches the outer lip).

  for (let idx = 0; idx < highlightPolys.length; idx++) {
    let poly = highlightPolys[idx];
    let n = poly.length;
    let isPrimary = idx <= 2;

    // Pass 1: Continuous razor-clean meniscus rim hugging the exact boundary
    for (let pass = 0; pass < (isPrimary ? 2 : 1); pass++) {
      let segPts = [];
      for (let i = 0; i <= n; i++) {
        let pt = poly[i % n];
        let nextPt = poly[(i + 1) % n];
        let vis = exposureVisibility(pt[0], pt[1]);

        // Surface normal tangent angle to weight the top & bottom liquid meniscus
        let dx = nextPt[0] - pt[0];
        let dy = nextPt[1] - pt[1];
        let horizFactor = Math.abs(dx) / (Math.hypot(dx, dy) + 1e-5);
        let pressure = (0.45 + 0.65 * horizFactor) * constrain(vis * 1.15, 0.25, 1.0);

        segPts.push([pt[0], pt[1], pressure]);
      }

      let col =
        idx <= 1
          ? pass === 0
            ? "#84586E"
            : "#5E4354"
          : idx === 2
          ? "#9E788B"
          : "#8D6D7F";
      brush.set("lacquer_edge", col, isPrimary ? 0.34 - pass * 0.08 : 0.24);
      brush.spline(segPts, 0.35);
    }

    // Pass 2: Micro-meniscus sulcus terminations (tiny dark/rose beads where each vertical
    // lip groove hits the top or bottom edge of the liquid lacquer pool and stops dead)
    if (isPrimary) {
      for (let i = 0; i < n; i += 2) {
        let pt = poly[i];
        let vis = exposureVisibility(pt[0], pt[1]);
        if (vis < 0.25) continue;

        // Determine whether this vertex is on the top or bottom meniscus
        let isTopEdge = i < n / 2;
        let dirY = isTopEdge ? -1 : 1;
        let len = random(3.5, 8.5);
        let col = random(["#784E64", "#8D6278", "#6B4A5E", "#997488"]);
        brush.set("lacquer_edge", col, 0.28 * vis);

        let beadPts = [
          [pt[0], pt[1] + dirY * 0.4, 1.05 * vis],
          [pt[0] + random(-0.6, 0.6), pt[1] + dirY * len * 0.5, 0.55 * vis],
          [pt[0] + random(-1.0, 1.0), pt[1] + dirY * len, 0.08 * vis]
        ];
        brush.spline(beadPts, 0.35);
      }
    }
  }

  // Subtle silver-graphite meniscus around the upper lip wet mucosal catchlights
  for (let poly of upperCatchPolys) {
    let segPts = [];
    for (let i = 0; i <= poly.length; i++) {
      let pt = poly[i % poly.length];
      segPts.push([pt[0], pt[1], 0.55]);
    }
    brush.set("graphite_6H", "#8D99AB", 0.24);
    brush.spline(segPts, 0.35);
  }

  // Ultra-faint optical refraction wisps across the narrowest waists of Islands A & B
  // (Leaving 98% of the highlight pure untouched paper while proving optical thickness)
  brush.set("graphite_6H", "#E2D4DC", 0.16);
  let [rx1, ry1] = posLowerLip(0.412, 0.29);
  let [rx2, ry2] = posLowerLip(0.414, 0.43);
  brush.line(rx1, ry1, rx2, ry2);

  let [rx3, ry3] = posLowerLip(0.584, 0.28);
  let [rx4, ry4] = posLowerLip(0.586, 0.42);
  brush.line(rx3, ry3, rx4, ry4);
}

// ============================================================================
// LAYER 7: FINE DOWN HAIR (VELLUS) & SKIN PORES FADING INTO OVEREXPOSURE
// ============================================================================

function drawSkinPoresAndVellusHair() {
  // Helper to check if a point (x, y) is outside the lip vermilion (with White Roll buffer)
  function isPerioralSkin(x, y) {
    let u = uFromX(x);
    if (u >= -0.02 && u <= 1.02) {
      let yTop = yUpperVermilion(constrain(u, 0, 1)) - 7.5; // Preserve the pure white roll!
      let yBot = yLowerVermilion(constrain(u, 0, 1)) + 4.0;
      if (y >= yTop && y <= yBot) return false;
    }
    return true;
  }

  // --------------------------------------------------------------------------
  // A. SKIN PORES & MICRO-EPIDERMAL TEXTURE (Fading into overexposed edges)
  // --------------------------------------------------------------------------
  // Pores are concentrated near the left commissure, upper lip skin above the white roll,
  // philtrum base, and left-center mentolabial crease
  let poreZones = [
    // Left commissure & cheek transition
    { xMin: 85, xMax: 340, yMin: 470, yMax: 770, count: 195 },
    // Left-to-center upper lip skin (above white roll) & philtrum
    { xMin: 180, xMax: 680, yMin: 270, yMax: 520, count: 165 },
    // Mentolabial shadow & lower lip chin transition
    { xMin: 160, xMax: 660, yMin: 825, yMax: 1025, count: 155 }
  ];

  for (let zone of poreZones) {
    for (let i = 0; i < zone.count; i++) {
      let px = random(zone.xMin, zone.xMax);
      let py = random(zone.yMin, zone.yMax);
      if (!isPerioralSkin(px, py)) continue;

      let vis = exposureVisibility(px, py);
      // Pores disappear where the overexposure eats the edges
      if (vis < 0.24 || random() > vis * 0.95) continue;

      let poreRadius = random(1.1, 2.4) * (0.65 + 0.45 * vis);
      let col = vis > 0.58 ? random(["#B2BCCB", "#C0C8D6"]) : random(["#CBD2DF", "#D7DDE8"]);

      // Draw only the upper-left shadow crescent of each pore (never a heavy flat dot!)
      // so the lower-right rim of the pore reads as a micro-highlight catching the beauty dish
      brush.set("graphite_6H", col, 0.24 * vis);
      let startAng = random(185, 225);
      let endAng = startAng + random(105, 145);
      brush.arc(px, py, poreRadius, startAng, endAng);

      // Subtle Langer's skin-tension micro-rhytid connecting occasional pores near left corner
      if (vis > 0.52 && random() < 0.28) {
        let meshAng = atan2(py - 606, px - 180) + 90 + random(-18, 18);
        let meshLen = random(4, 9);
        brush.set("graphite_6H", "#D8DFE9", 0.18 * vis);
        brush.line(
          px,
          py,
          px + Math.cos(radians(meshAng)) * meshLen,
          py + Math.sin(radians(meshAng)) * meshLen
        );
      }
    }
  }

  // --------------------------------------------------------------------------
  // B. FINE DOWN HAIR (VELLUS PEACH FUZZ)
  // --------------------------------------------------------------------------
  // Natural anatomical vellus stream directions around the human mouth:
  // Above upper lip: sweeping downward and outward toward the corner
  // Outside left corner: sweeping downward-left and curving gently around the modiolus
  // Below lower lip: sweeping downward and outward along the mentolabial slope
  let vellusCandidates = 420;
  for (let i = 0; i < vellusCandidates; i++) {
    // Bias distribution toward the left third and upper/lower left margins
    let rx = 75 + Math.pow(random(), 1.35) * 620;
    let ry = random(310, 1010);
    if (!isPerioralSkin(rx, ry)) continue;

    let vis = exposureVisibility(rx, ry);
    // Vellus hair fades out where overexposure eats the edges
    if (vis < 0.20 || random() > vis * 0.92) continue;

    // Compute natural facial hair flow angle at (rx, ry)
    let flowAngle;
    if (ry < 580) {
      // Upper lip skin: flows downward & outward from philtrum (x ~ 608)
      let tSide = constrain((608 - rx) / 440, -0.3, 1.2);
      flowAngle = 92 + tSide * 52 + random(-9, 9);
    } else if (ry < 740) {
      // Lateral cheek / commissure zone: curves downward-left and slightly inward
      flowAngle = 128 + ((ry - 580) / 160) * 18 + random(-10, 10);
    } else {
      // Mentolabial / chin zone: flows downward and slightly outward
      let tChin = constrain((580 - rx) / 420, -0.3, 1.2);
      flowAngle = 88 + tChin * 36 + random(-10, 10);
    }

    let hairLen = random(13, 34) * (0.6 + 0.5 * vis);
    let curveBend = random(-18, 18);

    let xMid = rx + Math.cos(radians(flowAngle + curveBend * 0.5)) * (hairLen * 0.5);
    let yMid = ry + Math.sin(radians(flowAngle + curveBend * 0.5)) * (hairLen * 0.5);
    let xEnd = rx + Math.cos(radians(flowAngle + curveBend)) * hairLen;
    let yEnd = ry + Math.sin(radians(flowAngle + curveBend)) * hairLen;

    // Avoid crossing into the vermilion lip interior
    if (!isPerioralSkin(xEnd, yEnd)) continue;

    // Where vellus hairs cross the shaded left commissure or mentolabial shadow,
    // some hairs catch the beauty-dish backlight as luminous white filaments paired with a whisper shadow!
    let inShadedZone =
      Math.hypot(rx - 165, ry - 608) < 95 ||
      (ry > 845 && ry < 925 && rx > 260 && rx < 560);

    if (inShadedZone && random() < 0.35) {
      // Subtle cast shadow of the vellus hair
      brush.set("vellus_hair", "#B8C2D1", 0.22 * vis);
      brush.spline(
        [
          [rx + 0.7, ry + 0.7, 0.2 * vis],
          [xMid + 0.7, yMid + 0.7, 0.75 * vis],
          [xEnd + 0.7, yEnd + 0.7, 0.05]
        ],
        0.5
      );
      // Backlit translucent white vellus filament
      brush.set("vellus_hair", PAPER_HEX, 0.32 * vis);
      brush.spline(
        [
          [rx, ry, 0.25 * vis],
          [xMid, yMid, 0.95 * vis],
          [xEnd, yEnd, 0.05]
        ],
        0.5
      );
    } else {
      // Whisper-pale silver-graphite vellus hair fading into the white paper
      let hairCol =
        vis > 0.62
          ? random(["#B6C0CE", "#C2CBD8", "#AEB8C8"])
          : random(["#CFD6E2", "#DAE0EA", "#E3E8F0"]);
      brush.set("vellus_hair", hairCol, (0.18 + 0.14 * vis) * random(0.8, 1.15));
      brush.spline(
        [
          [rx, ry, 0.22 * vis],
          [xMid, yMid, 0.85 * vis],
          [xEnd, yEnd, 0.02]
        ],
        0.5
      );
    }
  }
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background(PAPER_HEX);

  // 1. Construct the exact mathematical geometry for the lacquer highlight islands
  buildHighlightPolygons();

  // 2. Render the faint Rose Madder watercolour bloom in the lower lip's gloss pool
  //    (with pure untouched paper preserved inside every highlight island)
  drawRoseMadderBloom();

  // 3. Whisper-thin hard graphite form shading (upper lip roll, philtrum, mentolabial)
  drawGraphiteFormShading();

  // 4. Parted mouth interior (recessed oral shadow, translucent incisors, wet menisci)
  drawMouthInteriorAndTeeth();

  // 5. The single deep graphite crease at the left corner of the mouth (commissure node)
  drawCornerCreaseMasterwork();

  // 6. Pale silver-grey & rose-graphite anatomical lip sulci (stopping cleanly at highlights)
  drawLipSulci();

  // 7. Surgical wet-lacquer meniscus edging around the pure-paper highlight pool
  drawLacquerMeniscusEdges();

  // 8. Fine vellus down hair and micro skin pores fading out into the blown-out overexposure
  drawSkinPoresAndVellusHair();

  noLoop();
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(199908);
  noiseSeed(199908);

  // Scale built-in brushes first
  brush.scaleBrushes(3);

  // Custom airbrush, marker, and clinical hairline pen brushes
  brush.add("airbrush_wide", {
    type: "default",
    weight: 42,
    scatter: 0.75,
    sharpness: 0.04,
    grain: 5,
    opacity: 16,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.2],
    rotate: "natural",
    noise: 0.15
  });

  brush.add("airbrush_soft", {
