// ---------------------------------------------------------------------------
// GEOMETRY & DRAWING HELPERS
// ---------------------------------------------------------------------------

function rotPt(x, y, cx, cy, ang) {
  let c = cos(ang);
  let s = sin(ang);
  let dx = x - cx;
  let dy = y - cy;
  return [cx + dx * c - dy * s, cy + dx * s + dy * c];
}

function lerpPt(p1, p2, t) {
  return [lerp(p1[0], p2[0], t), lerp(p1[1], p2[1], t)];
}

function drawFilledPoly(pts, col, opacity, bleed = 0.04) {
  brush.noStroke();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed);
  brush.fillTexture(0.12, 0.04);
  brush.beginShape(0.15);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawWashedPoly(pts, col, opacity) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(0.12);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function safeSpline(pts, curv = 0.5) {
  if (pts.length >= 3) {
    brush.spline(pts, curv);
  } else if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  }
}

// Crisp star lens flare with airbrushed ice-blue glow & marker core
function drawLensFlare(x, y, radius, angleOffset = 0, intensity = 1.0) {
  brush.noFill();
  brush.noWash();

  // Outer cyan/lilac airbrush bloom
  brush.set("airbrush_soft", "#9ceeff", 1.1 * intensity);
  brush.circle(x, y, radius * 0.28, 0.05);
  brush.set("airbrush_fine", "#e5d4ff", 0.9 * intensity);
  brush.circle(x, y, radius * 0.16, 0.04);

  // Diagonal secondary rays
  brush.set("micro_marker", "#d8f6ff", 0.85 * intensity);
  for (let a = 45; a < 360; a += 90) {
    let ang = a + angleOffset;
    let r = radius * 0.42;
    let p1 = [x - cos(ang) * r, y - sin(ang) * r, 0.1];
    let p2 = [x, y, 1.2];
    let p3 = [x + cos(ang) * r, y + sin(ang) * r, 0.1];
    safeSpline([p1, p2, p3], 0.1);
  }

  // Primary 4-point marker spikes
  brush.set("gloss_marker", "#ffffff", 0.95 * intensity);
  for (let a = 0; a < 180; a += 90) {
    let ang = a + angleOffset;
    let r = a === 0 ? radius : radius * 0.82;
    let p1 = [x - cos(ang) * r, y - sin(ang) * r, 0.05];
    let p2 = [x - cos(ang) * r * 0.3, y - sin(ang) * r * 0.3, 0.9];
    let p3 = [x, y, 1.5];
    let p4 = [x + cos(ang) * r * 0.3, y + sin(ang) * r * 0.3, 0.9];
    let p5 = [x + cos(ang) * r, y + sin(ang) * r, 0.05];
    safeSpline([p1, p2, p3, p4, p5], 0.1);
  }

  // Hot white center ring
  brush.set("gloss_marker", "#ffffff", 1.2 * intensity);
  brush.circle(x, y, radius * 0.06, 0.02);
}

