// 1. FROSTED CYAN HAZE & FLOATING BUBBLE GLINTS
// ---------------------------------------------------------------------------

function drawFrostedBackground() {
  background("#d5f4fa");
  brush.noField();

  // Large pastel cyan & periwinkle atmospheric washes
  drawWashedPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], "#ccf2f9", 180);

  // Periwinkle corner depths (late-90s studio backdrop vignette)
  drawFilledPoly([[0, 0], [520, 0], [320, 420], [0, 620]], "#a8c0f0", 85, 0.25);
  drawFilledPoly([[750, 0], [1200, 0], [1200, 520], [920, 340]], "#98d8f4", 90, 0.25);
  drawFilledPoly([[0, 680], [380, 860], [520, 1200], [0, 1200]], "#9eb4ec", 95, 0.25);
  drawFilledPoly([[780, 780], [1200, 560], [1200, 1200], [680, 1200]], "#b5c4f2", 85, 0.25);

  // Luminous central ice-blue & white studio aura behind hand and phone
  for (let r = 560; r >= 140; r -= 70) {
    let col = r > 360 ? "#9be6f6" : (r > 220 ? "#c8f5fc" : "#eefdff");
    brush.noStroke();
    brush.wash(col, 42);
    brush.circle(570, 560, r, 0.08);
    brush.noWash();
  }

  // Sweeping diagonal airbrush bands in ice blue, periwinkle, and liquid silver
  let bgBands = [
    { y0: 140, y1: -40, col: "#9adcf2", w: 1.6 },
    { y0: 280, y1: 90, col: "#b5caf5", w: 1.5 },
    { y0: 440, y1: 230, col: "#e4fcff", w: 1.8 },
    { y0: 600, y1: 390, col: "#8cd8f0", w: 1.7 },
    { y0: 760, y1: 540, col: "#d8f8fe", w: 1.9 },
    { y0: 940, y1: 710, col: "#a4bcf0", w: 1.6 },
    { y0: 1120, y1: 890, col: "#8ed8f2", w: 1.5 },
    { y0: 1260, y1: 1040, col: "#c4d6f8", w: 1.5 }
  ];

  for (let b of bgBands) {
    brush.set("airbrush_wide", b.col, b.w);
    for (let offset = -45; offset <= 45; offset += 18) {
      let pts = [
        [-60, b.y0 + offset, 0.4],
        [380, lerp(b.y0, b.y1, 0.35) + offset + 25, 1.0],
        [820, lerp(b.y0, b.y1, 0.7) + offset - 20, 1.0],
        [1260, b.y1 + offset, 0.4]
      ];
      safeSpline(pts, 0.5);
    }
  }

  // Fine frosted spray texture across the cyan haze
  let sprayCols = ["#ffffff", "#85daf2", "#b8c8f5", "#d9fbff"];
  for (let c of sprayCols) {
    brush.set("mist_spray", c, 1.1);
    for (let i = 0; i < 14; i++) {
      let x1 = random(-40, 1050);
      let y1 = random(40, 1160);
      let len = random(180, 420);
      let ang = -18 + random(-10, 10);
      let pts = [
        [x1, y1, 0.3],
        [x1 + cos(ang) * len * 0.5, y1 + sin(ang) * len * 0.5 - 15, 1.0],
        [x1 + cos(ang) * len, y1 + sin(ang) * len, 0.3]
      ];
      safeSpline(pts, 0.4);
    }
  }
}

function drawBubbleGlints(bubbles) {
  for (let b of bubbles) {
    let { x, y, r, blur } = b;

    // Soft outer cyan-lilac glow
    brush.noStroke();
    brush.wash("#e6fcff", blur ? 35 : 55);
    brush.circle(x, y, r * 1.12, 0.03);
    brush.noWash();

    // Inner recessed periwinkle-cyan tint so bubble looks refractive
    brush.noStroke();
    brush.wash("#8fd4ee", blur ? 38 : 65);
    brush.circle(x + r * 0.06, y + r * 0.08, r * 0.86, 0.02);
    brush.noWash();

    // Iridescent lilac & ice-blue crescent arcs
    brush.set(blur ? "airbrush_soft" : "airbrush_fine", "#dfcff".replace("", "c"), blur ? 0.9 : 0.75);
    brush.arc(x, y, r * 0.92, 25, 145);

    brush.set(blur ? "airbrush_soft" : "airbrush_fine", "#8ce8ff", blur ? 0.9 : 0.8);
    brush.arc(x, y, r * 0.92, 195, 315);

    if (!blur) {
      // Crisp liquid-silver rim
      brush.set("clinical_pen", "#7aa6c9", 0.75);
      brush.circle(x, y, r, 0.015);

      // Warped mini studio horizon inside larger bubbles
      if (r > 26) {
        brush.set("airbrush_fine", "#6c64a6", 0.55);
        brush.arc(x, y + r * 0.12, r * 0.72, 15, 165);
      }

      // Hard white marker specular softbox arc (upper-left)
      brush.set("gloss_marker", "#ffffff", map(r, 10, 65, 0.45, 1.05, true));
      brush.arc(x, y, r * 0.82, 205, 265);

      // Opposite bottom-right bounce glint
      brush.set("micro_marker", "#ffffff", map(r, 10, 65, 0.35, 0.8, true));
      brush.arc(x, y, r * 0.84, 28, 72);

      // Tiny star glint on prominent bubbles
      if (r > 30) {
        let gx = x + cos(232) * r * 0.82;
        let gy = y + sin(232) * r * 0.82;
        drawLensFlare(gx, gy, r * 0.65, 12, 0.65);
      }
    } else {
      // Soft bokeh highlight
      brush.set("airbrush_fine", "#ffffff", 0.9);
      brush.arc(x, y, r * 0.75, 200, 275);
    }
  }
}

