function drawFlipPhone() {
  // Phone center & tilt axis
  const cx = 545;
  const cy = 545;
  const ang = -20; // Tilted left-up to right-down

  // Helper to convert local phone coordinates to canvas coordinates
  const P = (lx, ly) => rotPt(cx + lx, cy + ly, cx, cy, ang);

  // --- A. SOFT AMBIENT SHADOW BEHIND PHONE ---
  let shadowPts = [
    P(-215, -420), P(130, -420), P(205, 340), P(-155, 360), P(-230, 80)
  ];
  drawFilledPoly(shadowPts, "#7f8ec9", 75, 0.3);

  // --- B. STUBBY EXTENDABLE ANTENNA (Top-Left of Hinge) ---
  let antBaseL = -182, antBaseR = -132;
  let antTopL = -172, antTopR = -142;
  let antY0 = -175, antY1 = -415;

  let antPoly = [
    P(antBaseL, antY0), P(antBaseR, antY0),
    P(antTopR + 5, antY1 + 26), P(antTopR, antY1),
    P((antTopL + antTopR) / 2, antY1 - 16),
    P(antTopL, antY1), P(antTopL - 5, antY1 + 26)
  ];
  drawWashedPoly(antPoly, "#c2b2eb", 245);

  // Cylindrical longitudinal shading on antenna
  let antStripes = [
    { frac: 0.12, col: "#9adcf5", br: "airbrush_fine", w: 0.9 },
    { frac: 0.28, col: "#e6d8ff", br: "airbrush_fine", w: 1.0 },
    { frac: 0.50, col: "#5d508f", br: "airbrush_fine", w: 1.1 },
    { frac: 0.72, col: "#8576b8", br: "airbrush_fine", w: 0.9 },
    { frac: 0.88, col: "#b8e6ff", br: "airbrush_fine", w: 0.8 },
    { frac: 0.24, col: "#ffffff", br: "gloss_marker", w: 0.75 }
  ];
  for (let st of antStripes) {
    brush.set(st.br, st.col, st.w);
    let xBot = lerp(antBaseL, antBaseR, st.frac);
    let xTop = lerp(antTopL, antTopR, st.frac);
    let p1 = P(xBot, antY0);
    let p2 = P(lerp(xBot, xTop, 0.5), lerp(antY0, antY1, 0.5));
    let p3 = P(xTop, antY1);
    safeSpline([p1, p2, p3], 0.2);
  }

  // Chrome antenna tip cap with mini fisheye reflection
  let capCenter = P((antTopL + antTopR) / 2, antY1 + 8);
  brush.noStroke();
  brush.wash("#3e3568", 220);
  brush.circle(capCenter[0], capCenter[1], 19, 0.02);
  brush.noWash();
  brush.set("airbrush_fine", "#9ee6ff", 0.7);
  brush.arc(capCenter[0], capCenter[1], 14, 180, 350);
  brush.set("gloss_marker", "#ffffff", 0.65);
  brush.arc(capCenter[0], capCenter[1], 13, 200, 265);

  // Precision hairline seams on antenna rings
  brush.set("clinical_pen", "#3a2d5c", 0.8);
  for (let yy of [-388, -365, -210, -190]) {
    let pL = P(lerp(antBaseL, antTopL, (yy - antY0) / (antY1 - antY0)), yy);
    let pR = P(lerp(antBaseR, antTopR, (yy - antY0) / (antY1 - antY0)), yy);
    let pM = P(lerp((antBaseL + antBaseR) / 2, (antTopL + antTopR) / 2, (yy - antY0) / (antY1 - antY0)), yy - 5);
    safeSpline([pL, pM, pR], 0.5);
  }

  // --- C. UPPER CLAMSHELL LID (Angled Open Upward Above Hinge) ---
  // Left silver inner rim thickness + sculpted pearlescent lilac outer hood
  let upperRimPoly = [
    P(-175, -195), P(-140, -345), P(-65, -455), P(35, -460),
    P(55, -440), P(-45, -432), P(-118, -330), P(-148, -190)
  ];
  drawWashedPoly(upperRimPoly, "#9eb2d0", 245);

  let upperShellPoly = [
    P(-148, -190), P(-118, -330), P(-45, -432), P(45, -450),
    P(122, -415), P(162, -315), P(168, -190)
  ];
  drawWashedPoly(upperShellPoly, "#cfc0f2", 250);

  // Airbrush gradients across upper open clamshell lid
  for (let i = 0; i <= 14; i++) {
    let t = i / 14;
    let yCur = lerp(-200, -435, t);
    let halfW = lerp(152, 55, pow(t, 1.3));
    let xMid = lerp(10, 35, t);
    let col = t < 0.25 ? "#695ca3" : (t < 0.55 ? "#d8c8f8" : (t < 0.8 ? "#b2e6ff" : "#f4efff"));
    brush.set("airbrush_soft", col, 1.15);
    safeSpline([
      P(xMid - halfW, yCur + 12),
      P(xMid, yCur - 18),
      P(xMid + halfW, yCur + 14)
    ], 0.5);
  }

  // Specular marker streak along upper clamshell crown and left chrome edge
  brush.set("gloss_marker", "#ffffff", 0.95);
  safeSpline([P(-165, -210), P(-132, -335), P(-58, -440), P(35, -452), P(108, -422)], 0.5);
  brush.set("micro_marker", "#ffffff", 0.75);
  safeSpline([P(-95, -220), P(-68, -325), P(-10, -408), P(55, -418)], 0.5);

  // --- D. MAIN LOWER CLAMSHELL BODY (3D Left Bevel + Sculpted Pearlescent Back Shell) ---
  // 1. Left 3D side bevel (shows thickness of the flip phone & side volume buttons)
  let leftBevelPoly = [
    P(-186, -155), P(-148, -165), P(-142, 295),
    P(-95, 348), P(-135, 352), P(-182, 290)
