  drawWashedPoly(leftBevelPoly, "#8b7ec2", 250);

  // Metallic silver trim strip running down the side seam
  brush.set("chrome_band", "#d8e8f8", 0.85);
  safeSpline([P(-162, -155), P(-160, 70), P(-156, 290), P(-112, 345)], 0.3);
  brush.set("clinical_pen", "#3a2e63", 0.95);
  safeSpline([P(-150, -160), P(-148, 70), P(-144, 292), P(-98, 346)], 0.3);
  brush.set("micro_marker", "#ffffff", 0.75);
  safeSpline([P(-158, -145), P(-156, 70), P(-152, 285)], 0.3);

  // Two sculpted chrome pill volume buttons on the upper-left side bevel
  for (let by of [-65, 15]) {
