    safeSpline([P(-182, by - 26), P(-158, by - 26), P(-158, by + 26), P(-182, by + 26), P(-182, by - 26)], 0.1);
  }

  // 2. Main Pearlescent Lilac Front/Outer Clamshell Housing
  let bodyPoly = [
    P(-148, -165), P(172, -165),
    P(182, 80), P(168, 285),
    P(115, 348), P(12, 362), P(-95, 348),
    P(-142, 295), P(-152, 80)
  ];
  drawWashedPoly(bodyPoly, "#d4c3f5", 255);

  // Layered airbrush gradients across the pearlescent lilac shell
