    else if (t < 0.72) col = "#c9b5f2";  // Mid pearlescent lilac
    else if (t < 0.88) col = "#b2e4fc";  // Lower ice-blue pearlescent shift
    else col = "#7464ab";                // Bottom bevel shadow

    brush.set("airbrush_soft", col, 1.35);
    safeSpline([
      P(-wSpan, y + 10),
      P(0, y - 16),
      P(wSpan, y + 12)
    ], 0.45);
  }

  // Vertical cylindrical highlight & periwinkle core shadow along the shell length
  let shellLong = [
    { x: -115, col: "#9ce6ff", br: "airbrush_soft", w: 1.1 },
