  // Blurred face reflection spot in center hinge barrel
  let hFace = P(-8, -168);
  brush.set("airbrush_fine", "#eab8c9", 0.75);
  brush.circle(hFace[0], hFace[1], 11, 0.04);
  brush.set("clinical_pen", "#251c42", 0.8);
  brush.circle(hFace[0], hFace[1], 4, 0.02);

