  brush.set("gloss_marker", "#ffffff", 1.15);
  safeSpline([P(-174, -178), P(-125, -179), P(-76, -178)], 0.1);
  safeSpline([P(-58, -179), P(0, -181), P(58, -179)], 0.1);
  safeSpline([P(76, -178), P(122, -179), P(166, -178)], 0.1);

  // Hinge segment vertical seams in clinical pen
  brush.set("clinical_pen", "#231a42", 1.0);
  for (let hx of [-180, -68, 68, 172]) {
    safeSpline([P(hx, -198), P(hx - 4, -170), P(hx, -142)], 0.3);
  }

  // --- F. OVAL CHROME BEZEL & EXTERNAL SUB-DISPLAY (With Fisheye Reflection) ---
  let dispLocalX = 8;
  let dispLocalY = 22;
  let rxOuter = 90, ryOuter = 124;
  let rxInner = 64, ryInner = 96;

  // 1. Outer Chrome Torus Bezel Polygon
  let bezelOuterPts = [];
  let bezelInnerPts = [];
  for (let a = 0; a < 360; a += 15) {
    bezelOuterPts.push(P(dispLocalX + cos(a) * rxOuter, dispLocalY + sin(a) * ryOuter));
    bezelInnerPts.push(P(dispLocalX + cos(a) * rxInner, dispLocalY + sin(a) * ryInner));
  }
  drawWashedPoly(bezelOuterPts, "#d0dff2", 255);

  // Fisheye studio shading around the convex chrome oval bezel
  // Top half reflects ice-blue ceiling & softbox; bottom half reflects deep periwinkle floor & lilac shell
  for (let a = 0; a < 360; a += 10) {
    let aNext = a + 12;
    let rMid = (rxOuter + rxInner) * 0.5;
    let ryMid = (ryOuter + ryInner) * 0.5;
    let p1 = P(dispLocalX + cos(a) * rMid, dispLocalY + sin(a) * ryMid);
    let p2 = P(dispLocalX + cos((a + aNext) * 0.5) * rMid, dispLocalY + sin((a + aNext) * 0.5) * ryMid);
    let p3 = P(dispLocalX + cos(aNext) * rMid, dispLocalY + sin(aNext) * ryMid);

    let col;
    if (a >= 185 && a <= 335) col = "#96e4ff";       // Upper sky ice-blue
    else if (a > 335 || a < 25) col = "#382e66";     // Right horizon dark periwinkle
    else if (a >= 25 && a < 145) col = "#635699";    // Bottom floor reflection
    else col = "#312759";                            // Left horizon dark periwinkle

    brush.set("chrome_band", col, 1.15);
    safeSpline([p1, p2, p3], 0.3);
  }

  // Crisp white marker softbox arcs on the oval chrome bezel
  brush.set("gloss_marker", "#ffffff", 1.1);
  let sbArc1 = [];
  for (let a = 200; a <= 285; a += 12) {
    sbArc1.push(P(dispLocalX + cos(a) * (rxOuter - 9), dispLocalY + sin(a) * (ryOuter - 10)));
  }
  safeSpline(sbArc1, 0.4);

  brush.set("micro_marker", "#ffffff", 0.85);
  let sbArc2 = [];
  for (let a = 35; a <= 125; a += 12) {
    sbArc2.push(P(dispLocalX + cos(a) * (rxInner + 8), dispLocalY + sin(a) * (ryInner + 9)));
  }
  safeSpline(sbArc2, 0.4);

  // 2. Inner Backlit Ice-Blue / Periwinkle LCD Sub-Display
  drawWashedPoly(bezelInnerPts, "#485299", 255);

  // Glowing cyan/ice-blue LCD gradient + warped fisheye reflection inside the glass
  for (let ly = -ryInner + 10; ly <= ryInner - 10; ly += 12) {
    let frac = map(ly, -ryInner, ryInner, -1, 1);
    let span = sqrt(max(0, 1 - frac * frac)) * (rxInner - 6);
    let col = frac < -0.2 ? "#8ce8ff" : (frac < 0.15 ? "#2d356b" : (frac < 0.55 ? "#6a7de0" : "#b8f2ff"));
    brush.set("airbrush_fine", col, 1.25);
    safeSpline([
      P(dispLocalX - span, dispLocalY + ly + 5),
      P(dispLocalX, dispLocalY + ly - 8),
      P(dispLocalX + span, dispLocalY + ly + 5)
    ], 0.4);
  }

  // Warped blurred face & camera reflection inside the curved display glass
  let lcdFace = P(dispLocalX - 8, dispLocalY - 4);
  brush.set("airbrush_fine", "#e8b0c4", 0.95);
  brush.circle(lcdFace[0], lcdFace[1], 18, 0.05);
  brush.set("airbrush_fine", "#322654", 0.8);
  brush.circle(lcdFace[0] + 3, lcdFace[1] + 2, 8, 0.03);

  // Retro late-90s LCD digital clock & icons ("12:09" in glowing ice-cyan marker)
  brush.set("micro_marker", "#dffbff", 0.72);
  // "1"
  brush.line(...P(dispLocalX - 36, dispLocalY - 22), ...P(dispLocalX - 36, dispLocalY + 6));
  // "2"
  safeSpline([
    P(dispLocalX - 26, dispLocalY - 22), P(dispLocalX - 12, dispLocalY - 22),
    P(dispLocalX - 12, dispLocalY - 8), P(dispLocalX - 26, dispLocalY - 8),
    P(dispLocalX - 26, dispLocalY + 6), P(dispLocalX - 12, dispLocalY + 6)
  ], 0.05);
  // ":"
  brush.circle(...P(dispLocalX - 4, dispLocalY - 13), 1.5);
  brush.circle(...P(dispLocalX - 4, dispLocalY - 1), 1.5);
  // "0"
  safeSpline([
    P(dispLocalX + 4, dispLocalY - 22), P(dispLocalX + 18, dispLocalY - 22),
    P(dispLocalX + 18, dispLocalY + 6), P(dispLocalX + 4, dispLocalY + 6),
    P(dispLocalX + 4, dispLocalY - 22)
  ], 0.05);
  // "9"
  safeSpline([
    P(dispLocalX + 38, dispLocalY - 8), P(dispLocalX + 24, dispLocalY - 8),
    P(dispLocalX + 24, dispLocalY - 22), P(dispLocalX + 38, dispLocalY - 22),
    P(dispLocalX + 38, dispLocalY + 6), P(dispLocalX + 24, dispLocalY + 6)
  ], 0.05);

  // Diagonal curved white softbox streak across the glass screen
  brush.set("gloss_marker", "#ffffff", 0.95);
  safeSpline([
    P(dispLocalX - 46, dispLocalY - 58),
    P(dispLocalX - 15, dispLocalY - 68),
    P(dispLocalX + 22, dispLocalY - 52)
  ], 0.4);

  // Clinical hairline pen rims around outer and inner oval bezel
  brush.set("clinical_pen", "#271d4a", 0.95);
  safeSpline([...bezelOuterPts, bezelOuterPts[0]], 0.4);
  safeSpline([...bezelInnerPts, bezelInnerPts[0]], 0.4);

  // --- G. CONVEX SELFIE MIRROR DOME (Above Oval Screen, Full Fisheye Studio) ---
  let mirC = P(dispLocalX, -118);
  let mirR = 25;
  brush.noStroke();
  brush.wash("#352c61", 250);
  brush.circle(mirC[0], mirC[1], mirR, 0.02);
  brush.noWash();

  // Ice-blue upper sky inside convex mirror dome
  brush.set("airbrush_fine", "#94e8ff", 0.95);
  brush.arc(mirC[0], mirC[1], mirR * 0.72, 185, 355);

  // Blurred miniature face in convex mirror dome
  brush.set("airbrush_fine", "#f0b8ca", 0.75);
  brush.circle(mirC[0] - 2, mirC[1] + 2, 7, 0.04);
  brush.set("clinical_pen", "#1f1638", 0.8);
  brush.circle(mirC[0] - 1, mirC[1] + 2, 2.5, 0.02);

  // Crisp white marker softbox & rim on mirror dome
  brush.set("gloss_marker", "#ffffff", 0.85);
  brush.arc(mirC[0], mirC[1], mirR * 0.76, 205, 275);
  brush.set("micro_marker", "#ffffff", 0.65);
  brush.arc(mirC[0], mirC[1], mirR * 0.82, 25, 85);
  brush.set("clinical_pen", "#231942", 0.9);
  brush.circle(mirC[0], mirC[1], mirR, 0.015);

  // Star lens flare on the oval chrome bezel
  let bezelFlarePt = P(dispLocalX - 62, dispLocalY - 78);
  drawLensFlare(bezelFlarePt[0], bezelFlarePt[1], 44, 15, 0.85);
}

// ---------------------------------------------------------------------------
// 3. LONG ALMOND-SHAPED CHROME-POWDER NAIL GENERATOR
//    (Warped Fisheye Studio: Softbox, Blurred Face, Lens Flare, Clinical Chip)
// ---------------------------------------------------------------------------

function getAlmondNailContour(cx, cy, len, wid, ang, chipped = false, scaleM = 1.0) {
  let pts = [];
  let L = len * scaleM;
  let W = wid * scaleM;
  let steps = 36;

  // Upper edge: from cuticle base (-0.42*L) to almond point (+0.58*L)
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let x = lerp(-0.42 * L, 0.58 * L, u);
    let yProfile;
    if (u < 0.32) {
      yProfile = sin(map(u, 0, 0.32, 0, 90));
    } else {
      yProfile = pow(cos(map(u, 0.32, 1.0, 0, 90)), 1.28);
    }
    let y = -0.5 * W * yProfile;

    // Clinical tiny chip at the nail tip if enabled
    if (chipped && u > 0.89) {
      let chipDepth = map(u, 0.89, 1.0, 0, 0.16 * W);
      y += chipDepth + (i % 2 === 0 ? 1.8 : -1.2);
      if (u > 0.95) x -= 6 * scaleM;
    }
    pts.push(rotPt(cx + x, cy + y, cx, cy, ang));
  }

  // Lower edge: from almond point (+0.58*L) back to cuticle base (-0.42*L)
  for (let i = steps; i >= 0; i--) {
    let u = i / steps;
    let x = lerp(-0.42 * L, 0.58 * L, u);
    let yProfile;
    if (u < 0.32) {
      yProfile = sin(map(u, 0, 0.32, 0, 90));
    } else {
      yProfile = pow(cos(map(u, 0.32, 1.0, 0, 90)), 1.28);
    }
    let y = 0.5 * W * yProfile;
    if (chipped && u > 0.95) {
      x -= 5 * scaleM;
    }
    pts.push(rotPt(cx + x, cy + y, cx, cy, ang));
  }

  return pts;
}

function drawChromeAlmondNail(cfg) {
  let { cx, cy, len, wid, ang, chipped, flareScale } = cfg;
  const N = (lx, ly) => rotPt(cx + lx, cy + ly, cx, cy, ang);

  // 1. Cast shadow under the overhanging free almond nail tip onto phone/skin
  let shadowPts = getAlmondNailContour(cx - 6, cy + 12, len, wid, ang, chipped, 1.02);
  drawFilledPoly(shadowPts, "#38295c", 115, 0.18);

  // 2. If chipped, first draw the exposed thin natural nail plate & nail bed at the tip
  if (chipped) {
    let rawTipPts = getAlmondNailContour(cx, cy, len, wid, ang, false, 0.99);
    drawWashedPoly(rawTipPts, "#edd0dc", 235);
  }

  // 3. Base Liquid-Silver Chrome Nail Plate
  let nailPts = getAlmondNailContour(cx, cy, len, wid, ang, chipped, 1.0);
  drawWashedPoly(nailPts, "#d8e6f6", 255);

  // Helper to get half-width at normalized position u in [0, 1]
  const halfWAt = (u) => {
    let p = u < 0.32 ? sin(map(u, 0, 0.32, 0, 90)) : pow(cos(map(u, 0.32, 1.0, 0, 90)), 1.28);
    return 0.46 * wid * p;
  };
  const xAt = (u) => lerp(-0.40 * len, 0.54 * len, u);

  // 4. Longitudinal & Warped Fisheye Studio Gradients inside the Chrome Nail
  // v in [-1, 1] across the nail width:
  //   v = -0.8..-0.2 : Frosted Cyan & Ice-Blue studio sky
  //   v = -0.15..+0.22: Warped Fisheye Horizon (deep midnight periwinkle & violet)
  //   v = +0.25..+0.65: Liquid Silver & Periwinkle studio floor
  //   v = +0.68..+0.92: Pearlescent Lilac bounce light from the flip phone
  let bandSpecs = [
    { v: -0.78, col: "#7ad8f5", br: "chrome_band", w: 0.75 },
    { v: -0.52, col: "#bdf2ff", br: "chrome_band", w: 0.90 },
    { v: -0.28, col: "#ebfcff", br: "chrome_band", w: 0.85 },
    { v: -0.04, col: "#2b2252", br: "chrome_band", w: 0.95 }, // Warped fisheye horizon core
    { v:  0.16, col: "#544785", br: "chrome_band", w: 0.90 },
    { v:  0.38, col: "#8d99c9", br: "chrome_band", w: 0.85 },
    { v:  0.60, col: "#d9e6f7", br: "chrome_band", w: 0.80 },
    { v:  0.80, col: "#dfc8ff", br: "airbrush_fine", w: 0.75 } // Lilac phone bounce
  ];

  for (let b of bandSpecs) {
    brush.set(b.br, b.col, b.w);
    let curvePts = [];
    for (let u = 0.06; u <= 0.92; u += 0.14) {
      let lx = xAt(u);
      // Fisheye barrel warp bows the horizon outward near the center of the nail
      let fisheyeWarp = sin(u * 180) * 0.12 * wid * (1 - abs(b.v));
      let ly = b.v * halfWAt(u) + fisheyeWarp;
      curvePts.push(N(lx, ly));
    }
    safeSpline(curvePts, 0.45);
  }

  // 5. Lunula (subtle chrome-powder half-moon glow near cuticle base)
  brush.set("airbrush_fine", "#f2fbff", 0.85);
  let lunPts = [
    N(xAt(0.08), -halfWAt(0.10) * 0.65),
    N(xAt(0.20), 0),
    N(xAt(0.08), halfWAt(0.10) * 0.65)
  ];
  safeSpline(lunPts, 0.55);

  // 6. WARPED BLURRED FACE & CAMERA REFLECTION IN THE FISHEYE CENTER
  let facePos = N(xAt(0.44), 0.02 * wid);
  // Soft warm pastel skin blur of the reflected face
  brush.set("airbrush_fine", "#ebb2c5", 0.95);
  brush.circle(facePos[0], facePos[1], wid * 0.22, 0.05);
  brush.set("airbrush_fine", "#d18ea6", 0.75);
  brush.circle(facePos[0] + 2, facePos[1] + 2, wid * 0.15, 0.04);
  // Blurred dark hair/camera silhouette at the center of the face
  brush.set("airbrush_fine", "#2d234f", 0.85);
  brush.circle(facePos[0] - 2, facePos[1] - 1, wid * 0.09, 0.03);
  // Tiny cyan lens glint inside the camera reflection
  brush.set("micro_marker", "#aef2ff", 0.6);
  brush.circle(facePos[0] - 2, facePos[1] - 1, 1.8, 0.01);

  // 7. WARPED RECTANGULAR STUDIO SOFTBOX (Crisp White Marker Over Gradients)
  // Upper-dome banana-warped quadrilateral softbox reflection
  let sbPoly = [
    N(xAt(0.20), -halfWAt(0.20) * 0.68),
    N(xAt(0.62), -halfWAt(0.62) * 0.72),
    N(xAt(0.58), -halfWAt(0.58) * 0.25),
    N(xAt(0.18), -halfWAt(0.18) * 0.22)
  ];
  drawWashedPoly(sbPoly, "#ffffff", 240);

  // Hard white marker streaks defining the crisp softbox window & secondary rim streak
  brush.set("gloss_marker", "#ffffff", 1.05);
  safeSpline([
    N(xAt(0.16), -halfWAt(0.16) * 0.52),
    N(xAt(0.42), -halfWAt(0.42) * 0.58),
    N(xAt(0.72), -halfWAt(0.72) * 0.50),
    N(xAt(0.88), -halfWAt(0.88) * 0.35)
  ], 0.45);

  brush.set("gloss_marker", "#ffffff", 0.85);
  safeSpline([
    N(xAt(0.20), -halfWAt(0.20) * 0.32),
    N(xAt(0.40), -halfWAt(0.40) * 0.36),
    N(xAt(0.60), -halfWAt(0.60) * 0.30)
  ], 0.4);

  // Lower almond edge crisp white marker specular streak
  brush.set("micro_marker", "#ffffff", 0.9);
  safeSpline([
    N(xAt(0.28), halfWAt(0.28) * 0.72),
    N(xAt(0.56), halfWAt(0.56) * 0.74),
    N(xAt(0.84), halfWAt(0.84) * 0.66)
  ], 0.45);

  // 8. CLINICAL HAIRLINE PEN: Cuticle, Sidewalls, and Tiny Nail Tip Chip
  brush.set("clinical_pen", "#2c1d42", 0.95);
  safeSpline(nailPts, 0.35);

  // Double-lined clinical cuticle fold (eponychium) & radiating micro-creases
  let cutCurve1 = [];
  let cutCurve2 = [];
  for (let v = -0.85; v <= 0.85; v += 0.28) {
    let lx1 = -0.42 * len + (1 - v * v) * (-5);
    let ly1 = v * wid * 0.36;
    cutCurve1.push(N(lx1, ly1));

    let lx2 = -0.42 * len - 5 + (1 - v * v) * (-6);
    let ly2 = v * wid * 0.41;
    cutCurve2.push(N(lx2, ly2));
  }
  brush.set("clinical_pen", "#4a2e56", 0.9);
  safeSpline(cutCurve1, 0.5);
  brush.set("clinical_pen", "#694675", 0.75);
  safeSpline(cutCurve2, 0.5);

  // Glossy white marker highlight right along the raised cuticle rim
  brush.set("micro_marker", "#ffffff", 0.75);
  let cutGlint = [];
  for (let v = -0.65; v <= 0.55; v += 0.3) {
    cutGlint.push(N(-0.42 * len - 2.5 + (1 - v * v) * (-5), v * wid * 0.38));
  }
  safeSpline(cutGlint, 0.5);

  // Fine radial skin creases just behind the proximal nail fold
  brush.set("clinical_pen", "#5c3b69", 0.65);
  for (let v = -0.7; v <= 0.7; v += 0.2) {
    let pStart = N(-0.42 * len - 5 + (1 - v * v) * (-5), v * wid * 0.39);
    let pEnd = N(-0.42 * len - 14 + (1 - v * v) * (-6), v * wid * 0.46);
    brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);
  }

  // Surgical detail of the TINY CHIP at the nail tip
  if (chipped) {
    let c1 = N(0.49 * len, -0.14 * wid);
    let c2 = N(0.51 * len, -0.03 * wid);
    let c3 = N(0.55 * len, 0.02 * wid);
    let c4 = N(0.58 * len, -0.05 * wid);

    // Step-fracture edge of the chrome layer vs underlying keratin plate
    brush.set("clinical_pen", "#221436", 1.05);
    safeSpline([c1, c2, c3], 0.1);
    brush.set("clinical_pen", "#5e3d6b", 0.8);
    safeSpline([c1, c4, c3], 0.15);
    // Tiny stress micro-crack hairlines radiating from the chip corner
    let crk1 = N(0.44 * len, -0.06 * wid);
    let crk2 = N(0.46 * len, -0.11 * wid);
    brush.line(c2[0], c2[1], crk1[0], crk1[1]);
    brush.line(c1[0], c1[1], crk2[0], crk2[1]);

    // Razor-sharp white marker edge glint along the chipped chrome step
    brush.set("micro_marker", "#ffffff", 0.8);
    safeSpline([c1, c2, c3], 0.1);
  }

  // 9. Star Lens Flare on the Softbox Reflection
  if (flareScale > 0) {
    let flarePt = N(xAt(0.36), -halfWAt(0.36) * 0.48);
    drawLensFlare(flarePt[0], flarePt[1], wid * 0.85 * flareScale, ang + 18, flareScale);
  }
}

// ---------------------------------------------------------------------------
// 4. AIRBRUSHED HAND, FINGERS, KNUCKLE CREASES & SPECULAR SKIN
// ---------------------------------------------------------------------------

function drawSculptedFinger(f) {
  let { spine, radii, nailCfg, hasPalmBridge } = f;

  // Build top & bottom contour polygons along the 3-segment finger spine
  let upperPts = [];
  let lowerPts = [];
  let steps = 28;

  // Interpolate smoothly along the 3 spine points (knuckle -> middle joint -> fingertip)
  const sampleSpine = (t) => {
    if (t < 0.5) {
      let u = t * 2;
      return [
        lerp(spine[0][0], spine[1][0], u),
        lerp(spine[0][1], spine[1][1], u),
        lerp(radii[0], radii[1], u)
      ];
    } else {
      let u = (t - 0.5) * 2;
      return [
        lerp(spine[1][0], spine[2][0], u),
        lerp(spine[1][1], spine[2][1], u),
        lerp(radii[1], radii[2], u)
      ];
    }
  };

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let s = sampleSpine(t);
    let sNext = sampleSpine(min(1, t + 0.02));
    let sPrev = sampleSpine(max(0, t - 0.02));
    let ang = atan2(sNext[1] - sPrev[1], sNext[0] - sPrev[0]);
    let nx = -sin(ang);
    let ny = cos(ang);

    // Slight anatomical swell at knuckles (t=0.05 and t=0.5)
    let swell = 1.0 + 0.06 * exp(-pow((t - 0.5) / 0.12, 2));
    let r = s[2] * swell;
    upperPts.push([s[0] + nx * r, s[1] + ny * r]);
    lowerPts.push([s[0] - nx * r, s[1] - ny * r]);
  }

  // Round fingertip cap
  let tipCenter = spine[2];
  let tipDir = atan2(spine[2][1] - spine[1][1], spine[2][0] - spine[1][0]);
  let tipCap = [];
  for (let a = -75; a <= 75; a += 25) {
    let ca = tipDir + a;
    tipCap.push([
      tipCenter[0] + cos(ca) * radii[2] * 0.95,
      tipCenter[1] + sin(ca) * radii[2] * 0.95
    ]);
  }

  let fullPoly = [...upperPts, ...tipCap, ...lowerPts.slice().reverse()];

  // 1. Cast contact shadow from finger onto the pearlescent lilac flip phone
  let shadowPoly = fullPoly.map(p => [p[0] - 12, p[1] + 18]);
  drawFilledPoly(shadowPoly, "#4b3d7a", 95, 0.22);

  // 2. Base pastel porcelain-rose skin wash
  drawWashedPoly(fullPoly, "#f0ccd9", 252);

  // 3. Cylindrical Airbrush Gradients Along the Finger
  // Carrying ice-blue top rim light, warm pastel pink midtone, periwinkle core shadow, and lilac bounce
  let skinBands = [
    { offset:  0.78, col: "#b4ecff", br: "airbrush_fine", w: 1.05 }, // Frosted cyan rim light
    { offset:  0.48, col: "#fae2eb", br: "airbrush_soft", w: 1.15 }, // Lit porcelain highlight
    { offset:  0.12, col: "#ebb8cb", br: "airbrush_soft", w: 1.20 }, // Pastel rose midtone
    { offset: -0.28, col: "#b586ab", br: "airbrush_soft", w: 1.25 }, // Mauve-lilac turn
    { offset: -0.62, col: "#7d5b8c", br: "airbrush_soft", w: 1.15 }, // Periwinkle-plum core shadow
    { offset: -0.86, col: "#d5bef7", br: "airbrush_fine", w: 0.95 }  // Pearlescent lilac bounce light
  ];

  for (let sb of skinBands) {
    brush.set(sb.br, sb.col, sb.w);
    let bandPts = [];
    for (let t = 0.02; t <= 0.96; t += 0.15) {
      let idx = floor(t * steps);
      let pU = upperPts[idx];
      let pL = lowerPts[idx];
      let frac = map(sb.offset, 1, -1, 0, 1);
      bandPts.push(lerpPt(pU, pL, frac));
    }
    safeSpline(bandPts, 0.45);
  }

  // Fine mist spray for silky late-90s airbrush sheen
  brush.set("mist_spray", "#d9f6ff", 0.75);
  safeSpline([
    lerpPt(upperPts[3], lowerPts[3], 0.22),
    lerpPt(upperPts[14], lowerPts[14], 0.22),
    lerpPt(upperPts[24], lowerPts[24], 0.22)
  ], 0.4);

  // 4. Hard White Marker Specular Streaks Over the Glossy Skin
  brush.set("gloss_marker", "#ffffff", 0.9);
  safeSpline([
    lerpPt(upperPts[2], lowerPts[2], 0.20),
    lerpPt(upperPts[7], lowerPts[7], 0.18),
    lerpPt(upperPts[12], lowerPts[12], 0.21)
  ], 0.4);

  safeSpline([
    lerpPt(upperPts[15], lowerPts[15], 0.19),
    lerpPt(upperPts[19], lowerPts[19], 0.17),
    lerpPt(upperPts[24], lowerPts[24], 0.22)
  ], 0.4);

  // 5. CLINICAL HAIRLINE PEN: Knuckle Creases & Micro-Tension Lines
  // Draw lenticular knuckle folds at t = 0.10 (proximal/middle joint) and t = 0.52 (DIP joint)
  for (let jt of [0.10, 0.52]) {
    let s = sampleSpine(jt);
    let sNext = sampleSpine(min(1, jt + 0.04));
    let sPrev = sampleSpine(max(0, jt - 0.04));
    let fAng = atan2(sNext[1] - sPrev[1], sNext[0] - sPrev[0]);
    let creaseAng = fAng + 90; // Transverse across the knuckle

    let numCreases = jt < 0.3 ? 6 : 5;
    for (let c = -floor(numCreases / 2); c <= floor(numCreases / 2); c++) {
      let axialShift = c * 5.2;
      let jx = s[0] + cos(fAng) * axialShift;
      let jy = s[1] + sin(fAng) * axialShift;
      let span = s[2] * (0.68 - abs(c) * 0.09);
      let bow = (c === 0 ? 1.5 : c * 2.8);

      let p1 = [jx + cos(creaseAng) * span, jy + sin(creaseAng) * span];
      let pMid = [
        jx + cos(fAng) * bow + cos(creaseAng) * (c % 2 === 0 ? 3 : -3),
        jy + sin(fAng) * bow + sin(creaseAng) * (c % 2 === 0 ? 3 : -3)
      ];
      let p2 = [jx - cos(creaseAng) * span * 0.65, jy - sin(creaseAng) * span * 0.65];

      // Clinical dark hairline crease
      brush.set("clinical_pen", "#4a2c54", 0.82);
      safeSpline([p1, pMid, p2], 0.45);

      // Embossed white marker micro-glint right beside central knuckle creases
      if (abs(c) <= 1) {
        brush.set("micro_marker", "#ffffff", 0.55);
        safeSpline([
          [p1[0] + 1.5, p1[1] - 1.5],
          [pMid[0] + 1.5, pMid[1] - 1.5],
          [p2[0] + 1.5, p2[1] - 1.5]
        ], 0.45);
      }
    }

    // Fine diamond skin-tension cross-hatch lines between knuckle creases
    brush.set("clinical_pen", "#6d4878", 0.55);
    for (let d = -2; d <= 2; d++) {
      let dx = s[0] + cos(creaseAng) * (d * 7);
      let dy = s[1] + sin(creaseAng) * (d * 7);
      brush.line(dx - 5, dy - 4, dx + 5, dy + 4);
      brush.line(dx - 5, dy + 4, dx + 5, dy - 4);
    }
  }

  // Clinical hairline pen contour along finger silhouette
  brush.set("clinical_pen", "#442852", 0.85);
  safeSpline(upperPts, 0.35);
  safeSpline(lowerPts, 0.35);

  // 6. Render the Long Almond Chrome-Powder Nail at the Fingertip
  if (nailCfg) {
    drawChromeAlmondNail(nailCfg);
  }
}

