// =============================================================================
// CORE DRAWING HELPERS (SAFE BRUSH STATE MANAGEMENT)
// =============================================================================

function polyWash(pts, col, opacity = 255) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.polygon(pts);
  brush.noWash();
}

function rectWash(x, y, w, h, col, opacity = 255) {
  polyWash([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], col, opacity);
}

function circleWash(cx, cy, r, col, opacity = 255, segs = 24) {
  let pts = [];
  for (let i = 0; i < segs; i++) {
    let a = (i / segs) * 360;
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  polyWash(pts, col, opacity);
}

function ellipseWash(cx, cy, rx, ry, col, opacity = 255, segs = 24, rot = 0) {
  let pts = [];
  let cr = cos(rot), sr = sin(rot);
  for (let i = 0; i < segs; i++) {
    let a = (i / segs) * 360;
    let lx = cos(a) * rx;
    let ly = sin(a) * ry;
    pts.push([cx + lx * cr - ly * sr, cy + lx * sr + ly * cr]);
  }
  polyWash(pts, col, opacity);
}

function strokePoly(pts, brushName, col, weight = 0.5, closed = true) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  for (let i = 0; i < pts.length - 1; i++) {
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
  if (closed && pts.length > 2) {
    brush.line(pts[pts.length - 1][0], pts[pts.length - 1][1], pts[0][0], pts[0][1]);
  }
}

function markerPanel(x, y, w, h, fillCol, strokeCol = PAL.ink, weight = 0.45) {
  rectWash(x, y, w, h, fillCol, 245);
  // Saturated marker texture streaks inside panel
  brush.set("marker", fillCol, 1.1);
  for (let py = y + 4; py < y + h - 2; py += 7) {
    brush.line(x + 3, py, x + w - 3, py);
  }
  strokePoly([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], "rotring", strokeCol, weight, true);
}

function drawStitchLine(x1, y1, x2, y2, step = 9, col = PAL.stitch, shadowCol = PAL.ink) {
  let d = dist(x1, y1, x2, y2);
  let steps = max(2, floor(d / step));
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang), ny = cos(ang);

  // Subtle seam groove
  brush.set("rotring", shadowCol, 0.35);
  brush.line(x1, y1, x2, y2);

  for (let i = 0; i < steps; i++) {
    let t0 = (i + 0.15) / steps;
    let t1 = (i + 0.72) / steps;
    let sx0 = lerp(x1, x2, t0) + random(-0.4, 0.4);
    let sy0 = lerp(y1, y2, t0) + random(-0.4, 0.4);
    let sx1 = lerp(x1, x2, t1) + random(-0.4, 0.4);
    let sy1 = lerp(y1, y2, t1) + random(-0.4, 0.4);

    // Needle hole dots
    brush.set("rotring", shadowCol, 0.45);
    brush.line(sx0, sy0, sx0 + 0.6, sy0 + 0.6);

    // Thread segment slightly angled like saddle stitch
    brush.set("pen", col, 0.45);
    brush.line(sx0 + nx * 0.8, sy0 + ny * 0.8, sx1 - nx * 0.8, sy1 - ny * 0.8);
  }
}

function drawScuffedVinylPatch(pts, baseCol, midCol, scuffCol) {
  polyWash(pts, baseCol, 250);
  // Textured hatching for leather grain
  let p = new brush.Polygon(pts);
  brush.hatchStyle("charcoal", midCol, 0.5);
  p.hatch(5, 25, { rand: 0.15 });
  brush.hatchStyle("cpencil", scuffCol, 0.4);
  p.hatch(9, -35, { rand: 0.25 });
  brush.noHatch();
}

