function drawWindscreenBanner() {
  // Left & Right curved sun-strip banners across top of windshield (y: 145..242)
  const panes = [
    { x1: 62, x2: 582, text: "BYAHENG LANGIT" },
    { x1: 618, x2: 1138, text: "GOD KNOWS HUDAS NOT PAY" }
  ];

  for (let p of panes) {
    let w = p.x2 - p.x1;
    // Outer Kelly Green band
    polyWash([
      [p.x1, 145], [p.x2, 145],
      [p.x2, 232], [p.x1 + w * 0.5, 212], [p.x1, 232]
    ], PAL.kelly, 250);

    // Inner Candy Red arch band
    polyWash([
      [p.x1 + 8, 150], [p.x2 - 8, 150],
      [p.x2 - 8, 220], [p.x1 + w * 0.5, 200], [p.x1 + 8, 220]
    ], PAL.candyRed, 255);

    // Lemon Yellow center ribbon
    polyWash([
      [p.x1 + 26, 162], [p.x2 - 26, 162],
      [p.x2 - 34, 202], [p.x1 + w * 0.5, 188], [p.x1 + 34, 202]
    ], PAL.lemon, 255);

    // Electric Blue corner triangles
    polyWash([[p.x1 + 8, 150], [p.x1 + 68, 150], [p.x1 + 8, 218]], PAL.elecBlue, 250);
    polyWash([[p.x2 - 8, 150], [p.x2 - 68, 150], [p.x2 - 8, 218]], PAL.elecBlue, 250);

    // Scalloped bottom trim in Lemon & White
    let numScallops = 18;
    let sw = w / numScallops;
    for (let i = 0; i < numScallops; i++) {
      let sx = p.x1 + (i + 0.5) * sw;
      let t = (i + 0.5) / numScallops;
      let archY = lerp(232, 212, sin(t * 180));
      circleWash(sx, archY, 7, i % 2 === 0 ? PAL.lemon : PAL.elecBlue, 250, 12);
      brush.set("rotring", PAL.ink, 0.35);
