}

function drawSignPainterText(x1, y1, x2, y2, str, mainCol, shadowCol) {
  let n = str.length;
  let step = (x2 - x1) / n;
  let h = (y2 - y1) * 0.72;
  for (let i = 0; i < n; i++) {
    let ch = str[i];
    if (ch === " ") continue;
    let cx = x1 + i * step + step * 0.15;
    let w = step * 0.68;
    let midCurve = sin(((i + 0.5) / n) * 180) * -10;
    let cy = y1 + 4 + midCurve;

    // Drop shadow
    brush.set("marker", shadowCol, 0.7);
    brush.line(cx + 2, cy + 2, cx + 2, cy + h + 2);
    // Main letter stroke block
    rectWash(cx, cy, w, h, mainCol, 250);
    // Inner cutouts to suggest bold condensed Jeepney sign lettering
    let seed = ch.charCodeAt(0) % 4;
    if (seed === 0) {
      rectWash(cx + w * 0.28, cy + h * 0.2, w * 0.44, h * 0.25, PAL.lemon, 255);
      rectWash(cx + w * 0.28, cy + h * 0.55, w * 0.44, h * 0.25, PAL.lemon, 255);
    } else if (seed === 1) {
      rectWash(cx + w * 0.32, cy + h * 0.22, w * 0.68, h * 0.56, PAL.lemon, 255);
    } else if (seed === 2) {
      rectWash(cx, cy + h * 0.5, w * 0.35, h * 0.5, PAL.lemon, 255);
      rectWash(cx + w * 0.65, cy + h * 0.5, w * 0.35, h * 0.5, PAL.lemon, 255);
    } else {
      rectWash(cx + w * 0.28, cy + h * 0.2, w * 0.44, h * 0.6, PAL.lemon, 255);
    }
    strokePoly([[cx, cy], [cx + w, cy], [cx + w, cy + h], [cx, cy + h]], "rotring", shadowCol, 0.3, true);
  }
}

