function drawSaintStickerArch(x, y, w, h, type, robeCol, capeCol, haloCol) {
  let cx = x + w / 2;
  let r = w / 2;
  // Build arched polygon
  let pts = [[x, y + h], [x, y + r]];
  for (let a = 180; a <= 360; a += 15) {
    pts.push([cx + cos(a) * r, y + r + sin(a) * r]);
  }
  pts.push([x + w, y + h]);

  // White vinyl sticker peel border
  polyWash(pts, PAL.white, 255);
  strokePoly(pts, "rotring", PAL.ink, 0.45, true);

  // Inner gold foil ground
  let inPts = [];
  for (let p of pts) {
    inPts.push([lerp(cx, p[0], 0.86), lerp(y + h * 0.55, p[1], 0.88)]);
  }
  polyWash(inPts, haloCol, 250);

  // Radiating sunburst lines from halo
  let hx = cx, hy = y + h * 0.36;
  brush.set("rotring", PAL.hotOrange, 0.3);
  for (let a = 0; a < 360; a += 18) {
    brush.line(hx + cos(a) * 12, hy + sin(a) * 12, hx + cos(a) * 36, hy + sin(a) * 36);
  }

  // Halo ring
  circleWash(hx, hy, 22, PAL.brightLemon, 255, 18);
  brush.set("rotring", PAL.candyRed, 0.4);
  brush.circle(hx, hy, 22, 0.05);
  brush.circle(hx, hy, 18, 0.05);

  // Robes & mantle
  polyWash([
    [cx - 34, y + h - 10],
    [cx - 22, hy + 12],
    [cx + 22, hy + 12],
    [cx + 34, y + h - 10]
  ], robeCol, 255);

  polyWash([
    [cx - 24, y + h - 10],
    [cx - 12, hy + 18],
    [cx + 12, hy + 18],
    [cx + 24, y + h - 10]
  ], capeCol, 255);

  // Gold trim on robes
  brush.set("pen", PAL.lemon, 0.55);
  brush.line(cx - 22, hy + 12, cx - 32, y + h - 10);
  brush.line(cx + 22, hy + 12, cx + 32, y + h - 10);

  // Face & crown
  circleWash(hx, hy + 2, 11, "#F5C299", 255, 14);
  // Crown in gold & red jewels
  polyWash([[hx - 11, hy - 6], [hx - 14, hy - 18], [hx, hy - 14], [hx + 14, hy - 18], [hx + 11, hy - 6]], PAL.warmGold, 255);
  strokePoly([[hx - 11, hy - 6], [hx - 14, hy - 18], [hx, hy - 14], [hx + 14, hy - 18], [hx + 11, hy - 6]], "rotring", PAL.ink, 0.35, true);

  // Tiny facial features
  brush.set("rotring", PAL.ink, 0.35);
  brush.line(hx - 5, hy, hx - 2, hy);
  brush.line(hx + 2, hy, hx + 5, hy);
  brush.line(hx, hy + 1, hx, hy + 5);
  brush.set("rotring", PAL.candyRed, 0.35);
  brush.line(hx - 2, hy + 8, hx + 2, hy + 8);

  if (type === "HEART") {
    // Glowing Sacred Heart on chest
    circleWash(cx, hy + 34, 9, PAL.brightLemon, 255, 12);
    circleWash(cx, hy + 34, 5, PAL.candyRed, 255, 12);
  } else {
    // Infant child on left arm
    circleWash(cx - 12, hy + 28, 7, "#F5C299", 255, 10);
    polyWash([[cx - 20, hy + 34], [cx - 4, hy + 34], [cx - 2, hy + 56], [cx - 22, hy + 56]], PAL.kelly, 255);
  }

  // Festive scalloped sticker border dots
  for (let i = 0; i < pts.length; i++) {
    circleWash(pts[i][0], pts[i][1], 3.2, i % 2 === 0 ? PAL.kelly : PAL.candyRed, 255, 8);
  }

  // Bottom prayer ribbon banner
  rectWash(x + 8, y + h - 22, w - 16, 15, PAL.white, 250);
  strokePoly([[x + 8, y + h - 22], [x + w - 8, y + h - 22], [x + w - 8, y + h - 7], [x + 8, y + h - 7]], "rotring", PAL.ink, 0.35, true);
  brush.set("rotring", PAL.candyRed, 0.4);
  brush.line(x + 14, y + h - 14, x + w - 14, y + h - 14);
}

function drawSaintStickerOval(cx, cy, rx, ry, type, mainCol, accentCol, goldCol) {
  ellipseWash(cx, cy, rx + 5, ry + 5, PAL.white, 255, 28);
  ellipseWash(cx, cy, rx, ry, goldCol, 255, 28);
  ellipseWash(cx, cy, rx - 7, ry - 7, accentCol, 250, 24);

  // Radiating rays
  brush.set("rotring", PAL.brightLemon, 0.35);
  for (let a = 0; a < 360; a += 15) {
    brush.line(cx + cos(a) * 10, (cy - 12) + sin(a) * 10, cx + cos(a) * (rx - 9), (cy - 12) + sin(a) * (ry - 14));
  }

  // Iconic triangular Santo Niño cape
  polyWash([
    [cx, cy - 16],
    [cx - rx + 10, cy + ry - 14],
    [cx + rx - 10, cy + ry - 14]
  ], mainCol, 255);
  strokePoly([
    [cx, cy - 16],
    [cx - rx + 10, cy + ry - 14],
    [cx + rx - 10, cy + ry - 14]
  ], "pen", PAL.lemon, 0.55, true);

  // Gold embroidery chevrons on cape
  brush.set("rotring", PAL.lemon, 0.4);
  for (let k = 1; k <= 3; k++) {
    let yy = cy - 6 + k * 13;
    let ww = k * 9;
    brush.line(cx - ww, yy, cx, yy - 6);
    brush.line(cx, yy - 6, cx + ww, yy);
  }

  // Head & elaborate gold crown
  circleWash(cx, cy - 18, 10, "#F2BA90", 255, 14);
  polyWash([[cx - 12, cy - 26], [cx - 16, cy - 40], [cx, cy - 35], [cx + 16, cy - 40], [cx + 12, cy - 26]], PAL.lemon, 255);
  strokePoly([[cx - 12, cy - 26], [cx - 16, cy - 40], [cx, cy - 35], [cx + 16, cy - 40], [cx + 12, cy - 26]], "rotring", PAL.ink, 0.35, true);

  // Globus cruciger (orb) in left hand
  circleWash(cx - 16, cy + 8, 7, PAL.elecBlue, 255, 12);
  brush.set("rotring", PAL.lemon, 0.4);
  brush.line(cx - 16, cy + 1, cx - 16, cy - 5);
  brush.line(cx - 19, cy - 2, cx - 13, cy - 2);

  // Border bead dots
  for (let a = 0; a < 360; a += 18) {
    let bx = cx + cos(a) * (rx + 1);
    let by = cy + sin(a) * (ry + 1);
    circleWash(bx, by, 3, a % 36 === 0 ? PAL.candyRed : PAL.elecBlue, 255, 8);
  }
  brush.set("rotring", PAL.ink, 0.45);
  for (let a = 0; a < 360; a += 15) {
    let x0 = cx + cos(a) * (rx + 5);
    let y0 = cy + sin(a) * (ry + 5);
    let x1 = cx + cos(a + 15) * (rx + 5);
    let y1 = cy + sin(a + 15) * (ry + 5);
    brush.line(x0, y0, x1, y1);
  }
}

