function drawChromeBar(x, y, w, h, vertical = true) {
  rectWash(x, y, w, h, PAL.chromeMid, 255);
  // Sharp white-and-ink zigzag reflections along the chrome bar
  let steps = vertical ? floor(h / 28) : floor(w / 28);
  for (let i = 0; i < steps; i++) {
    if (vertical) {
      let yy = y + i * 28;
      polyWash([[x, yy], [x + w, yy + 10], [x + w, yy + 18], [x, yy + 8]], i % 2 === 0 ? PAL.ink : PAL.white, 250);
      polyWash([[x, yy + 14], [x + w, yy + 4], [x + w, yy + 10], [x, yy + 22]], i % 3 === 0 ? PAL.chromeWarm : PAL.white, 240);
    } else {
      let xx = x + i * 28;
      polyWash([[xx, y], [xx + 10, y + h], [xx + 18, y + h], [xx + 8, y]], i % 2 === 0 ? PAL.ink : PAL.white, 250);
      polyWash([[xx + 14, y], [xx + 4, y + h], [xx + 10, y + h], [xx + 22, y]], i % 3 === 0 ? PAL.chromeWarm : PAL.white, 240);
    }
  }
  strokePoly([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], "rotring", PAL.ink, 0.45, true);
}

