function drawRearviewMirror() {
  // Chrome center mounting bracket bolted to header
  drawChromeBar(582, 130, 36, 42, true);

  // Wide 5-panel panoramic Jeepney rearview mirror (x: 325..875, y: 162..246)
  let mx = 325, my = 162, mw = 550, mh = 84;
  // Outer Candy Red & Lemon frame
  markerPanel(mx, my, mw, mh, PAL.candyRed, PAL.ink, 0.65);

  // Checkerboard racing corners on mirror frame
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 4; c++) {
      let col = (r + c) % 2 === 0 ? PAL.lemon : PAL.ink;
      rectWash(mx + 4 + c * 9, my + 4 + r * 9, 9, 9, col, 255);
      rectWash(mx + mw - 40 + c * 9, my + 4 + r * 9, 9, 9, col, 255);
      rectWash(mx + 4 + c * 9, my + mh - 22 + r * 9, 9, 9, col, 255);
      rectWash(mx + mw - 40 + c * 9, my + mh - 22 + r * 9, 9, 9, col, 255);
    }
  }

  // 5 angled mirror glass panels reflecting the warm Jeepney interior behind
  let pw = (mw - 28) / 5;
  for (let i = 0; i < 5; i++) {
    let px = mx + 12 + i * (pw + 1);
    let py = my + 10;
    let ph = mh - 20;

    // Warm interior reflection (oxblood ceiling, golden passengers, bright window streaks)
    rectWash(px, py, pw - 2, ph, "#3D1214", 255);
    polyWash([[px, py], [px + pw - 2, py], [px + pw - 2, py + 24], [px, py + 16]], PAL.candyRed, 210);
    polyWash([[px, py + 24], [px + pw - 2, py + 18], [px + pw - 2, py + 44], [px, py + 48]], PAL.warmGold, 190);
    polyWash([[px + 8, py + 38], [px + pw - 10, py + 34], [px + pw - 4, py + ph], [px + 4, py + ph]], "#1C1417", 230);

    // Sharp diagonal glass reflection slashes
    polyWash([[px + 12, py], [px + 28, py], [px + 8, py + ph], [px, py + ph]], PAL.white, 215);
    polyWash([[px + 34, py], [px + 40, py], [px + 20, py + ph], [px + 14, py + ph]], PAL.brightLemon, 180);

    strokePoly([[px, py], [px + pw - 2, py], [px + pw - 2, py + ph], [px, py + ph]], "rotring", PAL.chromeLight, 0.45, true);
  }

  // Chrome wing-nut clamps on mirror sides
  drawChromeBar(mx - 14, my + 24, 16, 36, true);
  drawChromeBar(mx + mw - 2, my + 24, 16, 36, true);
}

function drawSwingingTasselsAndSampaguita() {
  // 1. SAMPAGUITA JASMINE GARLAND draped across mirror and swinging right
  let garlandPts = [];
  for (let i = 0; i <= 28; i++) {
    let t = i / 28;
    let gx = lerp(455, 755, t) + sin(t * 180) * 28;
    let gy = 242 + sin(t * 180) * 135;
    garlandPts.push([gx, gy]);
  }
  for (let i = 0; i < garlandPts.length; i++) {
    let [bx, by] = garlandPts[i];
    // Green calyx
    circleWash(bx, by, 5, PAL.kelly, 250, 8);
    // Twin creamy white jasmine buds
    ellipseWash(bx - 3, by + 3, 6.5, 4.5, PAL.cream, 255, 10, -25);
    ellipseWash(bx + 4, by + 2, 6.5, 4.5, PAL.white, 255, 10, 30);
    brush.set("rotring", PAL.warmInk, 0.3);
    brush.circle(bx - 3, by + 3, 5, 0.1);
    brush.circle(bx + 4, by + 2, 5, 0.1);
  }
  // Red ribbon & golden charm at bottom of Sampaguita loop
  let [rx, ry] = garlandPts[14];
  polyWash([[rx - 14, ry + 4], [rx, ry], [rx - 6, ry + 26], [rx - 18, ry + 22]], PAL.candyRed, 255);
  polyWash([[rx + 14, ry + 4], [rx, ry], [rx + 12, ry + 26], [rx + 2, ry + 22]], PAL.candyRed, 255);
  circleWash(rx + 2, ry + 32, 9, PAL.warmGold, 255, 12);
  brush.set("rotring", PAL.ink, 0.35);
  brush.circle(rx + 2, ry + 32, 9, 0.05);

  // 2. LARGE SWINGING FRINGED TASSELS (Left & Right of Mirror)
  drawOrnateSwingingTassel(415, 244, 18, [PAL.candyRed, PAL.lemon, PAL.kelly]);
  drawOrnateSwingingTassel(785, 244, 21, [PAL.elecBlue, PAL.candyRed, PAL.lemon]);
}

function drawOrnateSwingingTassel(anchorX, anchorY, swingDeg, tierColors) {
  push();
  translate(anchorX, anchorY);
  rotate(-swingDeg); // Swinging dynamically to the right!

  // Braided golden & red hanging cord with decorative wooden/gold beads
  brush.set("marker", PAL.warmGold, 0.9);
  brush.line(0, 0, 0, 58);
  brush.set("rotring", PAL.candyRed, 0.45);
  for (let y = 4; y < 54; y += 7) {
    brush.line(-3, y, 3, y + 4);
  }
  circleWash(0, 22, 8, PAL.candyRed, 255, 12);
  circleWash(0, 38, 10, PAL.warmGold, 255, 12);
  circleWash(-3, 36, 3, PAL.white, 255, 8);
  brush.set("rotring", PAL.ink, 0.4);
  brush.circle(0, 22, 8, 0.05);
  brush.circle(0, 38, 10, 0.05);

  // 3 Stacked Silk Fringe Tiers
  for (let t = 0; t < 3; t++) {
    let ty = 52 + t * 54;
    let col = tierColors[t];
    let topW = 14 + t * 3;
    let botW = 36 + t * 8;
    let th = 64;

    // Gold metallic crown cap
    polyWash([[-topW, ty], [topW, ty], [topW + 3, ty + 12], [-topW - 3, ty + 12]], PAL.warmGold, 255);
    strokePoly([[-topW, ty], [topW, ty], [topW + 3, ty + 12], [-topW - 3, ty + 12]], "rotring", PAL.ink, 0.4, true);

    // Base saturated marker body of fringe skirt
    polyWash([
      [-topW, ty + 12], [topW, ty + 12],
      [botW, ty + th], [-botW, ty + th]
    ], col, 250);

    // Hundreds of individual swinging silk fringe threads
    for (let f = -22; f <= 22; f++) {
      let u = f / 22;
      let sx = u * topW;
      let ex = u * botW + random(-2, 2);
      let ey = ty + th + random(-4, 6);

      if (f % 4 === 0) {
        brush.set("pen", PAL.brightLemon, 0.4);
      } else if (f % 3 === 0) {
        brush.set("rotring", PAL.ink, 0.35);
      } else {
        brush.set("pen", col, 0.5);
      }
      brush.spline([[sx, ty + 12], [(sx + ex) * 0.5 + 3, ty + th * 0.55], [ex, ey]], 0.4);
    }

    // Horizontal gold brocade band around top of fringe
    rectWash(-topW - 2, ty + 10, (topW + 2) * 2, 6, PAL.lemon, 255);
    brush.set("rotring", PAL.ink, 0.35);
    for (let gx = -topW; gx < topW; gx += 5) {
      brush.line(gx, ty + 10, gx + 3, ty + 16);
    }
  }
  pop();
}

function drawSwingingRosary() {
  // Swings from center mirror stem (600, 232) down in a graceful catenary curve to (662, 595)
  let leftLoop = [];
  let rightLoop = [];
  let steps = 22;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Left strand curving down to centerpiece at (636, 468)
    let lx = lerp(586, 636, t) - sin(t * 180) * 34 + t * t * 18;
    let ly = lerp(236, 468, t);
    leftLoop.push([lx, ly]);

    // Right strand curving down to centerpiece at (636, 468)
    let rx = lerp(614, 636, t) + sin(t * 180) * 38 + t * t * 18;
    let ry = lerp(236, 468, t);
    rightLoop.push([rx, ry]);
  }

  // Silver chain links connecting all beads
  strokePoly(leftLoop, "rotring", PAL.ink, 0.55, false);
  strokePoly(leftLoop, "rotring", PAL.white, 0.35, false);
  strokePoly(rightLoop, "rotring", PAL.ink, 0.55, false);
  strokePoly(rightLoop, "rotring", PAL.white, 0.35, false);

  // Draw translucent ruby-red & glowing amber rosary beads along both strands
  const allBeads = leftLoop.concat(rightLoop);
  for (let i = 0; i < allBeads.length; i++) {
    let [bx, by] = allBeads[i];
    let isPater = (i % 6 === 0);
    let r = isPater ? 6.8 : 4.8;
    let bCol = isPater ? PAL.brightLemon : PAL.candyRed;

    // Bead drop shadow
    circleWash(bx + 1.5, by + 1.5, r, PAL.ink, 160, 10);
    // Bead body
    circleWash(bx, by, r, bCol, 255, 12);
    // Specular pinpoint highlight
    circleWash(bx - r * 0.35, by - r * 0.35, r * 0.38, PAL.white, 255, 8);
    // Crisp ink rim
    brush.set("rotring", PAL.ink, 0.38);
    brush.circle(bx, by, r, 0.04);
  }

  // Ornate Silver Marian Centerpiece Medal at (636, 468)
  let mx = 636, my = 468;
  polyWash([[mx, my - 15], [mx + 14, my], [mx, my + 16], [mx - 14, my]], PAL.silver, 255);
  circleWash(mx, my, 8, PAL.elecBlue, 255, 12);
  circleWash(mx, my, 4, PAL.lemon, 255, 8);
  strokePoly([[mx, my - 15], [mx + 14, my], [mx, my + 16], [mx - 14, my]], "rotring", PAL.ink, 0.45, true);

  // Pendant tail from centerpiece (636, 484) to Crucifix at (660, 558)
  const tailBeads = [
    [640, 492, true],
    [644, 505, false],
    [647, 516, false],
    [650, 527, false],
    [654, 540, true]
  ];
  brush.set("rotring", PAL.ink, 0.55);
  brush.line(mx, my + 16, 660, 558);
  for (let tb of tailBeads) {
    let r = tb[2] ? 6.5 : 4.6;
    circleWash(tb[0], tb[1], r, tb[2] ? PAL.brightLemon : PAL.candyRed, 255, 10);
    circleWash(tb[0] - 2, tb[1] - 2, r * 0.35, PAL.white, 255, 6);
    brush.set("rotring", PAL.ink, 0.38);
    brush.circle(tb[0], tb[1], r, 0.04);
  }

  // Ornate Chrome & Gold Crucifix swinging at (662, 575), tilted -16 deg
  push();
  translate(662, 578);
  rotate(-16);
  // Shadow
  rectWash(-6, -24, 16, 68, PAL.ink, 140);
  rectWash(-26, -12, 56, 14, PAL.ink, 140);

  // Gold & Chrome Cross Beam
  rectWash(-7, -26, 14, 68, PAL.warmGold, 255);
  rectWash(-28, -14, 56, 14, PAL.warmGold, 255);

  // Sharp white-and-ink zigzag chrome reflections on crucifix
  polyWash([[-5, -24], [5, -18], [5, -12], [-5, -18]], PAL.white, 255);
  polyWash([[-5, -12], [5, -6], [5, 0], [-5, -6]], PAL.ink, 250);
  polyWash([[-26, -12], [-10, -2], [-18, -2], [-26, -8]], PAL.white, 255);
  polyWash([[8, -12], [26, -2], [18, -2], [8, -8]], PAL.white, 255);
  polyWash([[-5, 8], [5, 16], [5, 24], [-5, 16]], PAL.white, 255);
  polyWash([[-5, 24], [5, 32], [5, 38], [-5, 30]], PAL.ink, 250);

  // Trefoil tips on cross ends
  const tips = [[0, -28], [0, 42], [-29, -7], [29, -7]];
  for (let tp of tips) {
    circleWash(tp[0], tp[1], 7.5, PAL.lemon, 255, 10);
    circleWash(tp[0] - 2, tp[1] - 2, 3, PAL.white, 255, 6);
    brush.set("rotring", PAL.ink, 0.4);
    brush.circle(tp[0], tp[1], 7.5, 0.05);
  }

  // Silver Corpus figure on cross
  brush.set("pen", PAL.white, 0.85);
  brush.line(-18, -7, 18, -7);
  brush.line(0, -12, 0, 24);
  circleWash(0, -10, 4.5, PAL.silver, 255, 8);

  // Crisp ink outline
  strokePoly([
    [-7, -26], [7, -26], [7, -14], [28, -14], [28, 0],
    [7, 0], [7, 42], [-7, 42], [-7, 0], [-28, 0], [-28, -14], [-7, -14]
  ], "rotring", PAL.ink, 0.45, true);
  pop();
}

