function drawDashboardTopAndShrine() {
  // Padded red/amber dashboard top deck (y: 685..845)
  drawScuffedVinylPatch([
    [35, 685], [1165, 685], [1185, 845], [15, 845]
  ], PAL.vinylMid, PAL.vinylDark, PAL.vinylScuff);

  // Quilted dash-mat stitching across ledge
  for (let x = 60; x < 1140; x += 68) {
    drawStitchLine(x, 692, x - 25, 835, 9);
    drawStitchLine(x - 25, 692, x + 25, 835, 9);
  }

  // Horizontal chrome molding bar along base of windscreen (y: 682..704)
  drawChromeBar(48, 682, 1104, 20, false);

  // CENTER MINIATURE SANTO NIÑO DASHBOARD SHRINE (x: 525..675, y: 635..815)
  let sx = 528, sy = 640, sw = 144, sh = 165;
  // Arched shrine canopy in Kelly Green, Lemon & Candy Red
  polyWash([
    [sx, sy + sh], [sx, sy + 45],
    [sx + 25, sy + 10], [sx + sw * 0.5, sy], [sx + sw - 25, sy + 10],
    [sx + sw, sy + 45], [sx + sw, sy + sh]
  ], PAL.elecBlue, 255);

  polyWash([
    [sx + 10, sy + sh - 8], [sx + 10, sy + 48],
    [sx + 32, sy + 18], [sx + sw * 0.5, sy + 10], [sx + sw - 32, sy + 18],
    [sx + sw - 10, sy + 48], [sx + sw - 10, sy + sh - 8]
  ], PAL.lemon, 255);

  // Ring of glowing LED bulbs around the shrine arch
  const ledCols = [PAL.candyRed, PAL.brightLemon, PAL.brightGreen, PAL.brightBlue];
  for (let i = 0; i <= 14; i++) {
    let t = i / 14;
    let a = lerp(195, 345, t);
    let lx = (sx + sw * 0.5) + cos(a) * (sw * 0.46);
    let ly = (sy + 58) + sin(a) * 52;
    circleWash(lx, ly, 6.5, ledCols[i % 4], 255, 10);
    circleWash(lx - 1.5, ly - 1.5, 2.8, PAL.white, 255, 6);
    brush.set("rotring", PAL.ink, 0.35);
    brush.circle(lx, ly, 6.5, 0.05);
  }

  // Santo Niño Statue inside Shrine
  let ncx = sx + sw * 0.5, ncy = sy + 92;
  // Red velvet triangular cape
  polyWash([[ncx, ncy - 22], [ncx - 46, sy + sh - 16], [ncx + 46, sy + sh - 16]], PAL.candyRed, 255);
  // White & gold inner alb
  polyWash([[ncx, ncy - 18], [ncx - 16, sy + sh - 16], [ncx + 16, sy + sh - 16]], PAL.white, 255);
  // Gold trim & cross border
  strokePoly([[ncx, ncy - 22], [ncx - 46, sy + sh - 16], [ncx + 46, sy + sh - 16]], "pen", PAL.lemon, 0.65, true);
  // Head & golden crown
  circleWash(ncx, ncy - 26, 11, "#E5A97C", 255, 12);
  polyWash([[ncx - 13, ncy - 35], [ncx - 17, ncy - 50], [ncx, ncy - 44], [ncx + 17, ncy - 50], [ncx + 13, ncy - 35]], PAL.lemon, 255);
  strokePoly([[ncx - 13, ncy - 35], [ncx - 17, ncy - 50], [ncx, ncy - 44], [ncx + 17, ncy - 50], [ncx + 13, ncy - 35]], "rotring", PAL.ink, 0.35, true);

  // Stepped gold pedestal base of shrine
  markerPanel(sx - 8, sy + sh - 16, sw + 16, 22, PAL.candyRed, PAL.ink, 0.5);
  drawScrollPinstripeH(sx, sy + sh - 5, sx + sw, 6, PAL.lemon);
}

function drawPlasticFlowersCluster(baseX, baseY, flip) {
  // Colorful molded plastic roses, hibiscus & marigolds in a chrome/painted vase
  let vx = baseX + 55, vy = baseY + 135;

  // 1. Serrated Kelly Green Plastic Leaves fanning out
  const leafAngles = [-145, -120, -95, -70, -45, -20, 165, 15];
  for (let i = 0; i < leafAngles.length; i++) {
    let a = leafAngles[i];
    let len = 68 + (i % 3) * 18;
    let lx = vx + 50 + cos(a) * len;
    let ly = vy - 25 + sin(a) * len * 0.85;
    drawPlasticLeaf(vx + 50, vy - 20, lx, ly, i % 2 === 0 ? PAL.kelly : PAL.deepGreen);
  }

  // 2. Plastic Flower Blooms (Candy Red, Lemon, Hot Orange, Electric Blue, Magenta)
  const blooms = [
    { dx: 15, dy: 45, r: 30, c1: PAL.candyRed, c2: PAL.lemon },
    { dx: 72, dy: 30, r: 34, c1: PAL.lemon, c2: PAL.candyRed },
    { dx: 125, dy: 52, r: 28, c1: PAL.hotOrange, c2: PAL.brightLemon },
    { dx: 42, dy: 82, r: 29, c1: PAL.magenta, c2: PAL.lemon },
    { dx: 98, dy: 80, r: 31, c1: PAL.elecBlue, c2: PAL.white },
    { dx: 68, dy: 112, r: 26, c1: PAL.candyRed, c2: PAL.brightLemon },
    { dx: 18, dy: 108, r: 24, c1: PAL.lemon, c2: PAL.kelly },
    { dx: 122, dy: 105, r: 25, c1: PAL.candyRed, c2: PAL.white }
  ];

  for (let b of blooms) {
    let fx = baseX + b.dx;
    let fy = baseY + b.dy;
    // Green wire stem to vase
    brush.set("pen", PAL.deepGreen, 0.7);
    brush.line(vx + 50, vy, fx, fy);

    // Ruffled plastic petals
    let numPetals = 8;
    for (let p = 0; p < numPetals; p++) {
      let pa = (p / numPetals) * 360;
      let px = fx + cos(pa) * (b.r * 0.58);
      let py = fy + sin(pa) * (b.r * 0.58);
      circleWash(px, py, b.r * 0.48, b.c1, 250, 10);
      // Molded plastic specular sheen on petal edge
      brush.set("rotring", PAL.white, 0.4);
      brush.arc(px, py, b.r * 0.42, pa - 40, pa + 40);
      brush.set("rotring", PAL.ink, 0.35);
      brush.circle(px, py, b.r * 0.48, 0.05);
    }
    // Inner petal whorl
    circleWash(fx, fy, b.r * 0.52, b.c2, 255, 12);
    circleWash(fx, fy, b.r * 0.28, b.c1, 255, 10);
    // Plastic stamen dots
    for (let s = 0; s < 6; s++) {
      let sa = s * 60;
      circleWash(fx + cos(sa) * 5, fy + sin(sa) * 5, 2.2, PAL.white, 255, 6);
    }
    brush.set("rotring", PAL.ink, 0.4);
    brush.circle(fx, fy, b.r * 0.52, 0.06);
  }

  // 3. Dashboard Chrome & Folk-Painted Flower Vase bolted to dash
  polyWash([
    [vx + 18, vy - 10], [vx + 82, vy - 10],
    [vx + 70, vy + 58], [vx + 30, vy + 58]
  ], flip ? PAL.elecBlue : PAL.candyRed, 255);
  // Zigzag chrome band around vase middle
  drawChromeBar(vx + 22, vy + 12, 56, 18, false);
  // Vase base
  markerPanel(vx + 20, vy + 52, 60, 14, PAL.lemon, PAL.ink, 0.45);
  strokePoly([
    [vx + 18, vy - 10], [vx + 82, vy - 10],
    [vx + 70, vy + 58], [vx + 30, vy + 58]
  ], "rotring", PAL.ink, 0.5, true);
}

function drawPlasticLeaf(x1, y1, x2, y2, col) {
  let mx = (x1 + x2) * 0.5;
  let my = (y1 + y2) * 0.5;
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang) * 16;
  let ny = cos(ang) * 16;

  let pts = [
    [x1, y1],
    [lerp(x1, x2, 0.3) + nx * 0.8, lerp(y1, y2, 0.3) + ny * 0.8],
    [mx + nx * 1.15, my + ny * 1.15],
    [lerp(x1, x2, 0.75) + nx * 0.7, lerp(y1, y2, 0.75) + ny * 0.7],
    [x2, y2],
    [lerp(x1, x2, 0.75) - nx * 0.7, lerp(y1, y2, 0.75) - ny * 0.7],
    [mx - nx * 1.15, my - ny * 1.15],
    [lerp(x1, x2, 0.3) - nx * 0.8, lerp(y1, y2, 0.3) - ny * 0.8]
  ];
  polyWash(pts, col, 250);
  // Bright green & white plastic central vein and ribs
  brush.set("pen", PAL.brightGreen, 0.5);
  brush.line(x1, y1, x2, y2);
  brush.set("rotring", PAL.white, 0.35);
  for (let t = 0.25; t <= 0.75; t += 0.25) {
    let vx = lerp(x1, x2, t);
    let vy = lerp(y1, y2, t);
    brush.line(vx, vy, vx + nx * 0.65, vy + ny * 0.65);
    brush.line(vx, vy, vx - nx * 0.65, vy - ny * 0.65);
  }
  strokePoly(pts, "rotring", PAL.ink, 0.4, true);
}

function drawRowOfChromeHorses() {
  // 5 Iconic Sarao-style Chrome Stallion Figurines arrayed across the hood/dashboard ridge!
  const horses = [
    { x: 255, y: 745, sc: 0.88, flip: false },
    { x: 405, y: 748, sc: 0.96, flip: false },
    { x: 600, y: 765, sc: 1.12, flip: false }, // Center Lead Stallion
    { x: 795, y: 748, sc: 0.96, flip: true },
