function drawScrollPinstripeH(x1, y, x2, amp, col) {
  let span = x2 - x1;
  let numWaves = max(2, floor(span / 36));
  let w = span / numWaves;

  // Double hairline parallel rails
  brush.set("rotring", col, 0.35);
  brush.line(x1, y - amp - 2, x2, y - amp - 2);
  brush.line(x1, y + amp + 2, x2, y + amp + 2);

  // Scrolling vine wave with spiral curls and teardrops
  for (let i = 0; i < numWaves; i++) {
    let sx = x1 + i * w;
    let dir = i % 2 === 0 ? 1 : -1;
    brush.set("rotring", col, 0.42);
    brush.spline([
      [sx, y],
      [sx + w * 0.25, y + amp * dir],
      [sx + w * 0.5, y],
      [sx + w * 0.75, y - amp * dir],
      [sx + w, y]
    ], 0.6);

    // Tiny accent dots in the scroll hollows
    circleWash(sx + w * 0.25, y - amp * 0.4 * dir, 2.2, col === PAL.lemon ? PAL.white : PAL.lemon, 255, 6);
    circleWash(sx + w * 0.75, y + amp * 0.4 * dir, 2.2, PAL.candyRed, 255, 6);
  }
}

function drawFolkScrollMedallion(cx, cy, w, h) {
  // Center diamond
  polyWash([[cx, cy - h], [cx + 28, cy], [cx, cy + h], [cx - 28, cy]], PAL.lemon, 255);
  polyWash([[cx, cy - h * 0.55], [cx + 15, cy], [cx, cy + h * 0.55], [cx - 15, cy]], PAL.elecBlue, 255);
  strokePoly([[cx, cy - h], [cx + 28, cy], [cx, cy + h], [cx - 28, cy]], "rotring", PAL.ink, 0.4, true);

  // Symmetrical scrolling flourishes left and right
  for (let s of [-1, 1]) {
    brush.set("pen", PAL.white, 0.55);
    brush.spline([
      [cx + s * 28, cy],
      [cx + s * 55, cy - h * 0.8],
      [cx + s * 82, cy],
      [cx + s * 68, cy + h * 0.6],
      [cx + s * 52, cy]
    ], 0.65);
    brush.set("rotring", PAL.brightLemon, 0.4);
    brush.spline([
      [cx + s * 32, cy + 4],
      [cx + s * 62, cy + h * 0.85],
      [cx + s * 92, cy - 4]
    ], 0.6);
  }
}

