function drawChromeGauge(cx, cy, r, label, needleAng, accentCol) {
  // Outer chrome bezel with sharp white-and-ink zigzag reflections
  circleWash(cx, cy, r + 9, PAL.chromeMid, 255, 24);
  for (let a = 0; a < 360; a += 45) {
    let c = (a / 45) % 2 === 0 ? PAL.ink : PAL.white;
    let pts = [
      [cx + cos(a) * r, cy + sin(a) * r],
      [cx + cos(a + 22) * (r + 9), cy + sin(a + 22) * (r + 9)],
      [cx + cos(a + 40) * (r + 9), cy + sin(a + 40) * (r + 9)],
      [cx + cos(a + 18) * r, cy + sin(a + 18) * r]
    ];
    polyWash(pts, c, 250);
  }
  brush.set("rotring", PAL.ink, 0.5);
  brush.circle(cx, cy, r + 9, 0.04);

  // Gauge face (warm cream with colored arc band)
  circleWash(cx, cy, r, PAL.cream, 255, 24);
  brush.set("marker", accentCol, 0.8);
  brush.arc(cx, cy, r - 6, 150, 390);

  // Tick marks around dial
  brush.set("rotring", PAL.ink, 0.38);
  for (let a = 140; a <= 400; a += 20) {
    brush.line(
      cx + cos(a) * (r - 11), cy + sin(a) * (r - 11),
      cx + cos(a) * (r - 3), cy + sin(a) * (r - 3)
    );
  }

  // Odometer drum slots on large speedometer
  if (r > 45) {
    rectWash(cx - 20, cy + 12, 40, 11, PAL.ink, 255);
    brush.set("rotring", PAL.white, 0.35);
    for (let d = -14; d <= 14; d += 7) {
      brush.line(cx + d, cy + 14, cx + d, cy + 21);
    }
  }

  // Red pointer needle
  let na = -90 + needleAng;
  brush.set("pen", PAL.candyRed, 0.75);
  brush.line(cx - cos(na) * 8, cy - sin(na) * 8, cx + cos(na) * (r - 6), cy + sin(na) * (r - 6));
  circleWash(cx, cy, 5, PAL.chromeMid, 255, 8);
  brush.set("rotring", PAL.ink, 0.4);
  brush.circle(cx, cy, 5, 0.05);

  // Diagonal glass glare slash across gauge face
  polyWash([
    [cx - r * 0.65, cy - r * 0.45],
    [cx - r * 0.2, cy - r * 0.75],
    [cx + r * 0.65, cy + r * 0.45],
    [cx + r * 0.2, cy + r * 0.75]
  ], PAL.white, 135);

  brush.set("rotring", PAL.ink, 0.5);
  brush.circle(cx, cy, r, 0.04);
}

