function drawPesoCoin(cx, cy, rx, ry, type, rot) {
  // Coin edge thickness (3D cylinder side with milled ridges)
  ellipseWash(cx, cy + 3.5, rx, ry, PAL.ink, 230, 16, rot);

  // Outer coin face
  let outerCol = (type === 0) ? PAL.brass : (type === 1 ? PAL.silver : PAL.silver);
  let innerCol = (type === 0) ? PAL.silver : (type === 1 ? PAL.brass : PAL.white);

  ellipseWash(cx, cy, rx, ry, outerCol, 255, 16, rot);
  if (type < 2) {
    // Bimetallic core (₱10 and ₱20 coins)
    ellipseWash(cx, cy, rx * 0.62, ry * 0.62, innerCol, 255, 14, rot);
  }

  // Sharp metallic glint slash across coin face
  polyWash([
    [cx - rx * 0.5, cy - ry * 0.4],
    [cx - rx * 0.1, cy - ry * 0.6],
    [cx + rx * 0.5, cy + ry * 0.4],
    [cx + rx * 0.1, cy + ry * 0.6]
  ], PAL.white, 210);

  // Crisp ink coin rim & stamped relief mark
  brush.set("rotring", PAL.ink, 0.35);
  let cr = cos(rot), sr = sin(rot);
  for (let a = 0; a < 360; a += 30) {
    let x0 = cx + (cos(a) * rx * cr - sin(a) * ry * sr);
    let y0 = cy + (cos(a) * rx * sr + sin(a) * ry * cr);
    let x1 = cx + (cos(a + 30) * rx * cr - sin(a + 30) * ry * sr);
    let y1 = cy + (cos(a + 30) * rx * sr + sin(a + 30) * ry * cr);
    brush.line(x0, y0, x1, y1);
  }
}

