function drawSteeringWheelAndGearshift() {
  // 1. TALL CHROME GEARSHIFT LEVER & SWIRLED RESIN KNOB (x: 520..585, y: 840..1180)
  // Pleated black/oxblood vinyl gear boot at bottom
  drawScuffedVinylPatch([
