  ], PAL.ink, PAL.vinylDark, PAL.vinylScuff);
  drawStitchLine(522, 1090, 502, 1180, 8);
  drawStitchLine(564, 1090, 588, 1180, 8);

  // Bent chrome gearshift stalk
  polyWash([
    [538, 1090], [552, 1090],
    [574, 925], [558, 925]
  ], PAL.white, 255);
  polyWash([[540, 1050], [554, 1040], [562, 980], [548, 990]], PAL.ink, 250);
  strokePoly([[538, 1090], [552, 1090], [574, 925], [558, 925]], "rotring", PAL.ink, 0.5, true);

  // Striated Candy-Red, Lemon & Electric Blue Acrylic Shift Knob at (568, 895)
  let kx = 568, ky = 895;
  ellipseWash(kx, ky, 26, 36, PAL.candyRed, 255, 20, 12);
  ellipseWash(kx, ky - 6, 23, 14, PAL.lemon, 255, 16, 12);
  ellipseWash(kx, ky + 8, 22, 12, PAL.elecBlue, 255, 16, 12);
  // Glossy acrylic highlight
  ellipseWash(kx - 8, ky - 10, 7, 16, PAL.white, 235, 12, 12);
  brush.set("rotring", PAL.ink, 0.5);
  brush.circle(kx, ky, 31, 0.08);

  // 2. CUSTOM JEEPNEY STEERING WHEEL (Centered at x: 265, y: 1125, r: 215)
  let wcx = 265, wcy = 1125, wr = 210, thick = 28;

  // Three Perforated Chrome Spokes radiating from center hub (265, 1125)
  const spokeAngles = [205, 270, 335];
  for (let sa of spokeAngles) {
    let sx1 = wcx + cos(sa - 8) * 42;
    let sy1 = wcy + sin(sa - 8) * 42;
    let sx2 = wcx + cos(sa + 8) * 42;
    let sy2 = wcy + sin(sa + 8) * 42;
    let ex1 = wcx + cos(sa - 4) * (wr - 14);
    let ey1 = wcy + sin(sa - 4) * (wr - 14);
    let ex2 = wcx + cos(sa + 4) * (wr - 14);
    let ey2 = wcy + sin(sa + 4) * (wr - 14);

    polyWash([[sx1, sy1], [sx2, sy2], [ex2, ey2], [ex1, ey1]], PAL.chromeLight, 255);
    // Zigzag chrome reflections on spoke
    let mx1 = lerp(sx1, ex1, 0.45), my1 = lerp(sy1, ey1, 0.45);
    let mx2 = lerp(sx2, ex2, 0.55), my2 = lerp(sy2, ey2, 0.55);
    polyWash([[sx1, sy1], [sx2, sy2], [mx2, my2], [mx1, my1]], PAL.ink, 240);
    strokePoly([[sx1, sy1], [sx2, sy2], [ex2, ey2], [ex1, ey1]], "rotring", PAL.ink, 0.5, true);

    // 3 Racing holes along each chrome spoke
    for (let h = 1; h <= 3; h++) {
      let t = h * 0.23;
      let hx = wcx + cos(sa) * lerp(45, wr - 20, t);
      let hy = wcy + sin(sa) * lerp(45, wr - 20, t);
      let hr = 9 - h * 1.2;
      circleWash(hx, hy, hr, PAL.vinylDark, 255, 10);
      brush.set("rotring", PAL.white, 0.45);
      brush.arc(hx, hy, hr + 1.5, 0, 180);
      brush.set("rotring", PAL.ink, 0.45);
      brush.circle(hx, hy, hr, 0.05);
    }
  }

  // Spiral-Wrapped Multicolored Vinyl Rim of Steering Wheel (Candy Red, Lemon, Kelly Green, Electric Blue)
  const wrapCols = [PAL.candyRed, PAL.lemon, PAL.kelly, PAL.elecBlue];
  let segs = 36;
  for (let i = 0; i < segs; i++) {
    let a0 = 172 + (i / segs) * 196;
    let a1 = 172 + ((i + 1) / segs) * 196;
    let rIn = wr - thick * 0.5;
    let rOut = wr + thick * 0.5;

    let pts = [
      [wcx + cos(a0) * rIn, wcy + sin(a0) * rIn],
      [wcx + cos(a0 + 3) * rOut, wcy + sin(a0 + 3) * rOut],
      [wcx + cos(a1 + 3) * rOut, wcy + sin(a1 + 3) * rOut],
      [wcx + cos(a1) * rIn, wcy + sin(a1) * rIn]
    ];
    let col = wrapCols[i % 4];
    polyWash(pts, col, 255);

    // Specular vinyl ridge highlight along outer curve
    let hPts = [
      [wcx + cos(a0 + 1) * (wr + 2), wcy + sin(a0 + 1) * (wr + 2)],
      [wcx + cos(a1 + 1) * (wr + 2), wcy + sin(a1 + 1) * (wr + 2)],
      [wcx + cos(a1 + 1) * (wr + 8), wcy + sin(a1 + 1) * (wr + 8)],
      [wcx + cos(a0 + 1) * (wr + 8), wcy + sin(a0 + 1) * (wr + 8)]
    ];
    polyWash(hPts, PAL.white, 130);

    strokePoly(pts, "rotring", PAL.ink, 0.45, true);
  }

  // Center Chrome Horn Hub at (265, 1125)
  circleWash(wcx, wcy, 48, PAL.chromeMid, 255, 24);
  polyWash([[wcx - 46, wcy - 10], [wcx + 46, wcy - 22], [wcx + 42, wcy + 8], [wcx - 42, wcy + 18]], PAL.white, 255);
  polyWash([[wcx - 40, wcy + 12], [wcx + 40, wcy + 4], [wcx + 30, wcy + 32], [wcx - 30, wcy + 34]], PAL.ink, 250);
  circleWash(wcx, wcy, 28, PAL.candyRed, 255, 18);
  circleWash(wcx, wcy, 16, PAL.lemon, 255, 14);
  brush.set("rotring", PAL.ink, 0.55);
  brush.circle(wcx, wcy, 48, 0.04);
  brush.circle(wcx, wcy, 28, 0.04);

  // Suicide Knob (Acrylic Flower Spinner Knob) clamped to upper right rim at angle 312 deg
  let skx = wcx + cos(312) * wr;
  let sky = wcy + sin(312) * wr;
  // Chrome clamp bracket
  drawChromeBar(skx - 14, sky - 10, 28, 22, false);
  // Clear acrylic dome knob with encased tropical flower
  circleWash(skx + 14, sky - 18, 28, PAL.elecBlue, 245, 20);
  // Encased flower petals inside acrylic
  for (let p = 0; p < 6; p++) {
    let pa = p * 60;
    circleWash(skx + 14 + cos(pa) * 10, sky - 18 + sin(pa) * 10, 8, PAL.candyRed, 255, 10);
  }
  circleWash(skx + 14, sky - 18, 8, PAL.brightLemon, 255, 10);
  // High-gloss dome crescent highlight
  polyWash([
    [skx - 4, sky - 32], [skx + 18, sky - 40],
    [skx + 28, sky - 28], [skx + 2, sky - 22]
  ], PAL.white, 235);
  brush.set("rotring", PAL.ink, 0.55);
  brush.circle(skx + 14, sky - 18, 28, 0.04);
}

function drawLowerScuffedVinylBolster() {
  // Padded & Tufted Oxblood Vinyl Lower Dash Roll (y: 1102..1200)
  // Left & Right of steering column
  drawScuffedVinylPatch([[0, 1102], [205, 1102], [205, 1200], [0, 1200]], PAL.vinylDark, PAL.vinylMid, PAL.vinylScuff);
  drawScuffedVinylPatch([[325, 1102], [1200, 1102], [1200, 1200], [325, 1200]], PAL.vinylDark, PAL.vinylMid, PAL.vinylScuff);

  // Scuffed wear marks along the top padded lip where knees/hands brush the vinyl
  for (let sx = 30; sx < 1160; sx += 95) {
    if (sx > 190 && sx < 340) continue;
    polyWash([
      [sx, 1104], [sx + 52, 1104],
      [sx + 44, 1118], [sx + 8, 1116]
    ], PAL.vinylScuff, 195);
    brush.set("charcoal", "#D98B6C", 0.5);
    brush.line(sx + 4, 1109, sx + 46, 1109);
  }

  // Vertical pleated rolls & precise saddle stitching with frayed thread incidents
  for (let px = 45; px < 1180; px += 58) {
    if (px > 200 && px < 330) continue;
    drawStitchLine(px, 1104, px, 1198, 8, PAL.stitch, PAL.ink);
    drawStitchLine(px + 6, 1104, px + 6, 1198, 8, PAL.stitch, PAL.ink);

    // Occasional frayed stitch thread tail sticking out
    if (px % 116 === 45) {
      brush.set("rotring", PAL.stitch, 0.4);
      brush.spline([[px + 6, 1142], [px + 15, 1148], [px + 19, 1156]], 0.5);
    }

    // Brass upholstery tack at top of each pleat
    circleWash(px + 3, 1114, 4.2, PAL.brass, 255, 8);
    circleWash(px + 1.5, 1112.5, 1.8, PAL.white, 255, 6);
    brush.set("rotring", PAL.ink, 0.38);
    brush.circle(px + 3, 1114, 4.2, 0.05);
  }

  // Double horizontal saddle stitch seam running across the entire bolster
  drawStitchLine(0, 1106, 200, 1106, 8, PAL.stitch, PAL.ink);
  drawStitchLine(330, 1106, 1200, 1106, 8, PAL.stitch, PAL.ink);
  drawStitchLine(0, 1188, 200, 1188, 8, PAL.stitch, PAL.ink);
  drawStitchLine(330, 1188, 1200, 1188, 8, PAL.stitch, PAL.ink);
}

