function drawFinalGlareAndSparks() {
  // Starburst specular glints on the chrome horses, mirror, crucifix, gauges & coin tray
  const sparkPts = [
    [275, 582], [425, 580], [622, 578], [775, 580], [925, 582], // Horse brow glints
    [282, 650], [432, 652], [628, 655], [768, 652], [918, 650], // Horse chest glints
    [600, 205], [450, 195], [750, 195],                         // Mirror chrome glints
    [662, 568], [636, 468],                                     // Rosary crucifix & medal
    [238, 872], [118, 872], [358, 872],                         // Gauge bezel glints
    [770, 810], [920, 910], [1020, 895],                        // Coin tray & peso glints
    [572, 882], [398, 955]                                      // Shift knob & spinner knob
  ];

  for (let sp of sparkPts) {
    let [sx, sy] = sp;
    circleWash(sx, sy, 5, PAL.white, 255, 8);
    brush.set("rotring", PAL.white, 0.55);
    brush.line(sx - 18, sy, sx + 18, sy);
    brush.line(sx, sy - 18, sx, sy + 18);
    brush.set("rotring", PAL.brightLemon, 0.38);
    brush.line(sx - 10, sy - 10, sx + 10, sy + 10);
    brush.line(sx - 10, sy + 10, sx + 10, sy - 10);
  }
}
